# --- SOFTWARE ICONS: SINGLE-SOURCE GITHUB ARCHIVE (TOOL-PRO / MAIN) ---
# Icons.zip is downloaded only from the canonical raw URL below. There are no
# legacy mirrors, API-derived download URLs, bundled-archive sources, or old-repo fallbacks.
# A local icon cache is accepted only when its metadata identifies this exact source.
# Extract progressively and report a clear error if the configured source is unavailable.
$script:IconArchiveUrl = 'https://raw.githubusercontent.com/3mr10aa/Tool-Pro/main/Icons.zip'
# Keep the source ZIP and extracted images together in ProgramData\AMR-Utility\Icons.
$script:IconMinFileCount = 100
# Keep the approved image formats shared by the Software Catalog and Startup Apps.
# WIC decodes formats when a matching Windows Imaging Component codec is available.
$script:AMRIconImageExtensions = @('.png','.jpg','.jpeg','.jpe','.jfif','.bmp','.dib','.gif','.tif','.tiff','.ico','.webp','.wdp','.jxr','.hdp','.heic','.heif','.avif','.jp2','.j2k','.dds','.tga','.pcx','.ppm','.pgm','.pbm')
$script:IconDownloadTimeoutSec = 45 # retained for worker compatibility; individual requests now use explicit bounded timeouts

function Test-AMRIconCacheUsable {
    param([int]$Minimum = 100)
    try {
        if (-not (Test-Path -LiteralPath $script:IconDir -PathType Container)) { return $false }
        $count = @(Get-ChildItem -LiteralPath $script:IconDir -File -ErrorAction SilentlyContinue |
            Where-Object { ($script:AMRIconImageExtensions -contains $_.Extension.ToLowerInvariant()) -and $_.Length -gt 32 }).Count
        return ($count -ge $Minimum)
    } catch { return $false }
}

# Icon synchronization is implemented only inside Start-AMRBackgroundIconRefresh worker runspace.

# Convert icon files to frozen WPF ImageSource objects.
# WPF Image.Source expects an ImageSource, not a plain filesystem path string.
function Get-AMRIconImageSource {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,
        # Optional: when greater than zero and the image is wider than this value,
        # decode it at this pixel width (aspect ratio preserved). 0 keeps the original behavior.
        [int]$MaxPixelWidth = 0
    )

    if ([string]::IsNullOrWhiteSpace($Path) -or
        -not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return $null
    }

    try {
        $fullPath = [System.IO.Path]::GetFullPath($Path)
        # WIC selects a decoder from the file signature/content, not only its suffix.
        # Optional formats work when the corresponding Windows WIC codec is installed.
        $fileStream = [System.IO.File]::Open($fullPath,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite)
        try {
            $decoder = [System.Windows.Media.Imaging.BitmapDecoder]::Create(
                $fileStream,
                [System.Windows.Media.Imaging.BitmapCreateOptions]::IgnoreImageCache,
                [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
            )
            if ($null -eq $decoder -or $decoder.Frames.Count -lt 1) { return $null }
            $bitmap = $decoder.Frames[0]
            if ($MaxPixelWidth -gt 0 -and $bitmap.PixelWidth -gt $MaxPixelWidth) {
                try {
                    # Downscale oversized artwork at decode time. Any failure falls back to the full-size frame above.
                    $fileStream.Position = 0
                    $scaled = [System.Windows.Media.Imaging.BitmapImage]::new()
                    $scaled.BeginInit()
                    $scaled.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                    $scaled.CreateOptions = [System.Windows.Media.Imaging.BitmapCreateOptions]::IgnoreImageCache
                    $scaled.DecodePixelWidth = $MaxPixelWidth
                    $scaled.StreamSource = $fileStream
                    $scaled.EndInit()
                    if ($scaled.CanFreeze) { $scaled.Freeze() }
                    return $scaled
                } catch {}
            }
            if ($bitmap.CanFreeze) { $bitmap.Freeze() }
            return $bitmap
        } finally { $fileStream.Dispose() }
    }
    catch {
        Write-AMRLog "Could not load app icon '$Path': $($_.Exception.Message)" WARNING Software
        return $null
    }
}

$script:SoftwareCatalog = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:IconCacheUsableAtStartup = Test-AMRIconCacheUsable -Minimum $script:IconMinFileCount

# One directory listing replaces one Test-Path per (app id x extension) in the startup catalog loop.
# Keys are lower-case file names (Windows file names are case-insensitive).
$script:AMRStartupIconIndex = New-Object 'System.Collections.Generic.Dictionary[string,string]'
if ($script:IconCacheUsableAtStartup) {
    try {
        foreach ($indexedIconPath in [System.IO.Directory]::EnumerateFiles([string]$script:IconDir)) {
            $script:AMRStartupIconIndex[[System.IO.Path]::GetFileName($indexedIconPath).ToLowerInvariant()] = $indexedIconPath
        }
    } catch {}
}

$script:AMRCatalogItemCompiled = ($null -ne ('AMR.SoftwareCatalogItem' -as [type]))
# A1 (measurement only): how much of the catalog loop is icon decoding.
$script:AMRStartupIconDecodeTicks = [long]0
$script:AMRStartupIconDecodeCalls = 0
$amrCatalogLoopStart = [System.Diagnostics.Stopwatch]::GetTimestamp()
$RawApps | ForEach-Object {
    $initial  = if ($_.Name.Length -gt 0) { $_.Name.Substring(0,1).ToUpper() } else { 'A' }

    # A complete local cache is the runtime source of truth. Resolve each catalog
    # icon before the WPF view is created, so scrolling/recycling never waits for
    # a background worker to publish an image into the bound item.
    $iconSource = $null
    if ($script:IconCacheUsableAtStartup) {
        $localIconIds = @([string]$_.Id)
        if ($_.PSObject.Properties['IconAliases'] -and $_.IconAliases) {
            $localIconIds += @($_.IconAliases | ForEach-Object { [string]$_ })
        }
        foreach ($localIconId in $localIconIds) {
            foreach ($localIconExtension in $script:AMRIconImageExtensions) {
                $localIconPath = $null
                if ($script:AMRStartupIconIndex.TryGetValue(($localIconId + $localIconExtension).ToLowerInvariant(), [ref]$localIconPath)) {
                    # Catalog icons are shown at 30x30 DIPs; 96 px keeps them sharp on high-DPI displays.
                    $amrDecodeStart = [System.Diagnostics.Stopwatch]::GetTimestamp()
                    $iconSource = Get-AMRIconImageSource -Path $localIconPath -MaxPixelWidth 96
                    $script:AMRStartupIconDecodeTicks += ([System.Diagnostics.Stopwatch]::GetTimestamp() - $amrDecodeStart)
                    $script:AMRStartupIconDecodeCalls++
                    if ($null -ne $iconSource) { break }
                }
            }
            if ($null -ne $iconSource) { break }
        }
    }

    $catalogItemProps = [ordered]@{
        IsSelected    = $false
        IsInstalled   = $false
        Name          = $_.Name
        Category      = $_.Category
        Id            = $_.Id
        IconAliases   = if ($_.PSObject.Properties['IconAliases'] -and $_.IconAliases) { @($_.IconAliases) } else { @() }
        ChocoId       = $_.ChocoId
        DirectUrl     = $_.DirectUrl
        DirectArgs    = $_.DirectArgs
        Publisher     = $_.Publisher
        BrowserUrl    = if ($_.PSObject.Properties['BrowserUrl']) { [string]$_.PSObject.Properties['BrowserUrl'].Value } else { '' }
        CatalogUrl    = if ($_.PSObject.Properties['CatalogUrl']) { [string]$_.PSObject.Properties['CatalogUrl'].Value } else { '' }
        GoogleUrl     = if ($_.PSObject.Properties['GoogleUrl']) { [string]$_.PSObject.Properties['GoogleUrl'].Value } else { '' }
        # These fields are optional catalog metadata. Access them through
        # PSObject.Properties so StrictMode does not throw for legacy entries.
        Sha256        = if ($_.PSObject.Properties['Sha256']) { [string]$_.PSObject.Properties['Sha256'].Value } else { '' }
        InstallerType = if ($_.PSObject.Properties['InstallerType']) { [string]$_.PSObject.Properties['InstallerType'].Value } else { '' }
        InteractiveArgs = if ($_.PSObject.Properties['InteractiveArgs']) { [string]$_.PSObject.Properties['InteractiveArgs'].Value } else { '' }
        AllowedHosts  = if ($_.PSObject.Properties['AllowedHosts'] -and $null -ne $_.PSObject.Properties['AllowedHosts'].Value) { @($_.PSObject.Properties['AllowedHosts'].Value) } else { @() }
        InstallTimeoutSeconds = if ($_.PSObject.Properties['InstallTimeoutSeconds'] -and $_.PSObject.Properties['InstallTimeoutSeconds'].Value) { [int]$_.PSObject.Properties['InstallTimeoutSeconds'].Value } else { 1800 }
        Initials      = $initial
        Icon          = [System.Windows.Media.ImageSource]$iconSource
    }
    # Compiled model when available; the former PSCustomObject remains the fallback.
    $catalogItem = if ($script:AMRCatalogItemCompiled) { New-Object -TypeName 'AMR.SoftwareCatalogItem' -Property $catalogItemProps } else { [pscustomobject]$catalogItemProps }
    $script:SoftwareCatalog.Add($catalogItem)
}

$loadedIconCount = @($script:SoftwareCatalog | Where-Object { $null -ne $_.Icon }).Count
try {
    $amrTickMs = 1000.0 / [double][System.Diagnostics.Stopwatch]::Frequency
    $script:AMRStartupPhaseTimings['CatalogLoopMs'] = [int](([System.Diagnostics.Stopwatch]::GetTimestamp() - $amrCatalogLoopStart) * $amrTickMs)
    $script:AMRStartupPhaseTimings['CatalogIconDecodeMs'] = [int]($script:AMRStartupIconDecodeTicks * $amrTickMs)
    Write-AMRLog ('Startup catalog loop: {0} item(s); {1} icon decode call(s) took {2} ms of the {3} ms loop.' -f $script:SoftwareCatalog.Count,$script:AMRStartupIconDecodeCalls,$script:AMRStartupPhaseTimings['CatalogIconDecodeMs'],$script:AMRStartupPhaseTimings['CatalogLoopMs']) INFO Startup
} catch {}
$script:AMRStartupPhaseTimings['IconCatalogReadyMs'] = [int]$script:AMRStartupStopwatch.ElapsedMilliseconds
Write-AMRLog ("Startup catalog ready: {0} preloaded icons from local cache. Cache='{1}'." -f $loadedIconCount,$script:IconDir) INFO Software
Write-AMRLog ("Catalog item model: {0} ({1} items)." -f $(if ($script:AMRCatalogItemCompiled) { 'compiled AMR.SoftwareCatalogItem with INotifyPropertyChanged' } else { 'PSCustomObject fallback' }),$script:SoftwareCatalog.Count) INFO Software

# --- 4. FULL WPF XAML INTERFACE WITH PROGRESS BAR & 27 CUSTOMIZE TOOLS ---
[xml]$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" 
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" 
        xmlns:primitives="clr-namespace:System.Windows.Controls.Primitives;assembly=PresentationFramework" 
        Title="Amr | windows_utility" Height="700" Width="1100" 
        MinHeight="600" MinWidth="900" WindowStartupLocation="CenterScreen" WindowState="Normal" 
        Background="#18181B" Foreground="#E4E4E7" FontFamily="Segoe UI">
 <Window.Resources>
  <!-- Software cards: shared overlay brushes (one instance each, no animation, frozen at startup). Defined FIRST in Window.Resources: templates below resolve StaticResource at parse time and cannot see later keys. -->
  <RadialGradientBrush x:Key="AMRSoftCardGlowBrush" Center="0,0" GradientOrigin="0,0" RadiusX="0.7" RadiusY="1.0">
   <GradientStop Color="#24FFFFFF" Offset="0"/>
   <GradientStop Color="#0AFFFFFF" Offset="0.5"/>
   <GradientStop Color="#00FFFFFF" Offset="1"/>
  </RadialGradientBrush>
  <LinearGradientBrush x:Key="AMRSoftCardHairBrush" StartPoint="0,0" EndPoint="1,1">
   <GradientStop Color="#2EFFFFFF" Offset="0"/>
   <GradientStop Color="#0AFFFFFF" Offset="0.5"/>
   <GradientStop Color="#12FFFFFF" Offset="1"/>
  </LinearGradientBrush>
  <LinearGradientBrush x:Key="AMRSoftTileBrush" StartPoint="0,0" EndPoint="0,1">
   <GradientStop Color="#FF4A4A53" Offset="0"/>
   <GradientStop Color="#FF2F2F36" Offset="1"/>
  </LinearGradientBrush>
  <SolidColorBrush x:Key="AMRSoftTileEdgeBrush" Color="#1FFFFFFF"/>
  <!-- Details popup Copy button: same glass face and warm edge as the Activation copy button (values copied, Activation untouched). -->
  <LinearGradientBrush x:Key="AMRCopyBtnGlassBrush" StartPoint="0,0" EndPoint="1,1">
   <GradientStop Color="#B85D574B" Offset="0"/><GradientStop Color="#E33B3D41" Offset="0.22"/><GradientStop Color="#E52C2E33" Offset="0.68"/><GradientStop Color="#D9232529" Offset="1"/>
  </LinearGradientBrush>
  <LinearGradientBrush x:Key="AMRCopyBtnEdgeBrush" StartPoint="0,0" EndPoint="1,1">
   <GradientStop Color="#D9D4C29F" Offset="0"/><GradientStop Color="#986F624B" Offset="0.38"/><GradientStop Color="#665B554B" Offset="1"/>
  </LinearGradientBrush>
  <!-- Full card template (details popup/toggle) used only by the Installed surface; the catalog uses a lean inline template. -->
  <DataTemplate x:Key="AMRInstalledCardTemplate">
          <!-- Fixed item-slot geometry prevents category-header visibility and progressive
               page appends from changing UniformGrid's measured row height. -->
          <Grid Height="76" HorizontalAlignment="Stretch" VerticalAlignment="Stretch">
           <Grid.RowDefinitions><RowDefinition Height="12"/><RowDefinition Height="64"/></Grid.RowDefinitions>
           <Grid.Style>
            <Style TargetType="Grid">
             <Style.Triggers>
              <DataTrigger Binding="{Binding IsCategorySpacer}" Value="True"><Setter Property="Visibility" Value="Hidden"/></DataTrigger>
             </Style.Triggers>
            </Style>
           </Grid.Style>
           <StackPanel Grid.Row="0" Orientation="Horizontal" HorizontalAlignment="Left" Width="34" Height="12" FlowDirection="LeftToRight" Margin="3,0,0,0">
            <StackPanel.Style>
             <Style TargetType="StackPanel">
              <Setter Property="Visibility" Value="Collapsed"/>
              <Style.Triggers>
               <!-- Reserve the same header-row height across all columns so cards stay aligned. -->
               <DataTrigger Binding="{Binding IsCategoryHeaderRow}" Value="True"><Setter Property="Visibility" Value="Hidden"/></DataTrigger>
               <DataTrigger Binding="{Binding IsCategoryStart}" Value="True"><Setter Property="Visibility" Value="Visible"/></DataTrigger>
              </Style.Triggers>
             </Style>
            </StackPanel.Style>
            <Border Width="12" Height="2" CornerRadius="1" Background="#3B6FB8" VerticalAlignment="Center" Margin="0,0,5,0"/>
            <TextBlock Text="{Binding CategoryNumber}" Foreground="#7E9CBE" FontSize="9.5" FontWeight="SemiBold" VerticalAlignment="Center" Margin="0,0,0,0"/>
           </StackPanel>
          <!-- Static shadow layer (no Effect): cheap to render and to scroll. -->
          <Border Grid.Row="1" IsHitTestVisible="False" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" Height="63" Margin="2.5,0.5" CornerRadius="10.5" Background="#000000" Opacity="0.09"/>
          <!-- Static shadow layer (no Effect): cheap to render and to scroll. -->
          <Border Grid.Row="1" IsHitTestVisible="False" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" Height="66" Margin="1,-1" CornerRadius="12" Background="#000000" Opacity="0.06"/>
          <!-- Static shadow layer (no Effect): cheap to render and to scroll. -->
          <Border Grid.Row="1" IsHitTestVisible="False" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" Height="69" Margin="-0.5,-2.5" CornerRadius="13.5" Background="#000000" Opacity="0.035"/>
          <Border x:Name="SoftwareCardSurface" Grid.Row="1" Background="#FF222226" BorderBrush="#FF38383F" BorderThickness="1" CornerRadius="9" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" RenderTransformOrigin="0.5,0.5">
           <Border.Style>
            <Style TargetType="Border">
             <Setter Property="Height" Value="60"/>
             <Setter Property="Padding" Value="5,3"/>
             <Setter Property="Margin" Value="4,2"/>
             <Setter Property="RenderTransform">
              <Setter.Value><TransformGroup><ScaleTransform ScaleX="1" ScaleY="1"/><TranslateTransform X="0" Y="0"/></TransformGroup></Setter.Value>
             </Setter>
             <Style.Triggers>
              <MultiTrigger><MultiTrigger.Conditions><Condition Property="IsMouseOver" Value="True"/><Condition Property="IsVisible" Value="True"/></MultiTrigger.Conditions>
               <MultiTrigger.EnterActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF31353B" Duration="0:0:0.16">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FFFFE0AD" Duration="0:0:0.18">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="-3" Duration="0:0:0.16">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1.025" Duration="0:0:0.16">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1.025" Duration="0:0:0.16">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                 </Storyboard>
                </BeginStoryboard>
               </MultiTrigger.EnterActions>
               <MultiTrigger.ExitActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF222226" Duration="0:0:0.21">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FF38383F" Duration="0:0:0.21">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="0" Duration="0:0:0.21">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.21">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.21">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                 </Storyboard>
                </BeginStoryboard>
               </MultiTrigger.ExitActions>
              </MultiTrigger>
              <DataTrigger Binding="{Binding IsSelected}" Value="True">
               <Setter Property="Background" Value="#FF262E38"/>
               <Setter Property="BorderBrush" Value="#FFD7B77C"/>
               <Setter Property="BorderThickness" Value="1.4"/>
               </DataTrigger>
              <!-- A13g: the selection fade starts only once the card is in the visual tree (IsVisible). Starting a Storyboard on Border.Background while the template was still being built threw XamlParseException. -->
              <MultiDataTrigger><MultiDataTrigger.Conditions><Condition Binding="{Binding IsSelected}" Value="True"/><Condition Binding="{Binding RelativeSource={RelativeSource Self},Path=IsVisible}" Value="True"/></MultiDataTrigger.Conditions><MultiDataTrigger.EnterActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF2A3340" Duration="0:0:0.18"/>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FFFFDFA8" Duration="0:0:0.20"/>
                 </Storyboard>
                </BeginStoryboard>
               </MultiDataTrigger.EnterActions><MultiDataTrigger.ExitActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF222226" Duration="0:0:0.16"/>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FF38383F" Duration="0:0:0.16"/>
                 </Storyboard>
                </BeginStoryboard>
               </MultiDataTrigger.ExitActions></MultiDataTrigger>
             </Style.Triggers>
            </Style>
           </Border.Style>
           <Grid>
            <Grid.RowDefinitions><RowDefinition Height="*"/></Grid.RowDefinitions>
            <Border IsHitTestVisible="False" Grid.Row="0" Margin="-5,-3" CornerRadius="8" BorderThickness="1" Background="{StaticResource AMRSoftCardGlowBrush}" BorderBrush="{StaticResource AMRSoftCardHairBrush}"/>
            <Grid Grid.Row="0" VerticalAlignment="Center">
             <Grid.ColumnDefinitions>
              <ColumnDefinition Width="Auto"/>
              <ColumnDefinition Width="Auto"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="Auto"/>
             </Grid.ColumnDefinitions>
             <CheckBox IsChecked="{Binding IsSelected, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}"
                       VerticalAlignment="Center" HorizontalAlignment="Center" Margin="0,0,12,0"
                       ToolTip="Select this application" Cursor="Hand" FocusVisualStyle="{x:Null}"
                       Width="19" Height="19" VerticalContentAlignment="Center" HorizontalContentAlignment="Center">
              <CheckBox.Template>
               <ControlTemplate TargetType="CheckBox">
                <Border x:Name="SelectionSurface" Width="18" Height="18" CornerRadius="5"
                        Background="#FF1C222A" BorderBrush="#FF5B6573" BorderThickness="1.2"
                        SnapsToDevicePixels="True">
                 <Grid>
                  <Path x:Name="SelectionTick" RenderTransformOrigin="0.5,0.5" Data="M 3,9 L 7,13 L 15,4"
                        Stroke="#FFFFFFFF" StrokeThickness="2.0" StrokeStartLineCap="Round"
                        StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"
                        HorizontalAlignment="Center" VerticalAlignment="Center"/>
                 </Grid>
                </Border>
                <ControlTemplate.Triggers>
                 <Trigger Property="IsMouseOver" Value="True">
                  <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FFE0AD"/>
                  <Setter TargetName="SelectionSurface" Property="Background" Value="#FF2C3641"/>
                 </Trigger>
                 <Trigger Property="IsChecked" Value="True">
                  <Setter TargetName="SelectionSurface" Property="Background" Value="#FFB88D4D"/>
                  <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FFFFE0AD"/>
                  <Setter TargetName="SelectionTick" Property="Visibility" Value="Visible"/>
                 </Trigger>
                 <Trigger Property="IsEnabled" Value="False">
                  <Setter TargetName="SelectionSurface" Property="Opacity" Value="0.45"/>
                 </Trigger>
                </ControlTemplate.Triggers>
               </ControlTemplate>
              </CheckBox.Template>
             </CheckBox>
             <Grid Grid.Column="1" Width="36" Height="36" Margin="0,0,8,0">
              <Border Background="{StaticResource AMRSoftTileBrush}" BorderBrush="{StaticResource AMRSoftTileEdgeBrush}" BorderThickness="1" CornerRadius="9"/>
              <TextBlock x:Name="SoftwareIconInitials" Text="{Binding Initials}" Foreground="#A1A1AA" FontSize="16" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center">
               <TextBlock.Style>
                <Style TargetType="TextBlock">
                 <Setter Property="Visibility" Value="Collapsed"/>
                 <Style.Triggers>
                  <DataTrigger Binding="{Binding Icon}" Value="{x:Null}"><Setter Property="Visibility" Value="Visible"/></DataTrigger>
                 </Style.Triggers>
                </Style>
               </TextBlock.Style>
              </TextBlock>
              <Image x:Name="SoftwareIconImage" Source="{Binding Icon, Mode=OneWay, TargetNullValue={x:Null}, FallbackValue={x:Null}}" Width="30" Height="30" Stretch="Uniform" HorizontalAlignment="Center" VerticalAlignment="Center" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="LowQuality"/>
             </Grid>
             <StackPanel Grid.Column="2" VerticalAlignment="Center">
              <TextBlock x:Name="SoftwareNameText" Text="{Binding Name}" FontSize="14" FontWeight="SemiBold" Foreground="#FFFFFF" TextWrapping="Wrap">
               <TextBlock.Style>
                <Style TargetType="TextBlock">
                 <Style.Triggers>
                  <DataTrigger Binding="{Binding IsUniversalInventory}" Value="True">
                   <Setter Property="Text" Value="{Binding CardDisplayName}"/>
                   <Setter Property="TextWrapping" Value="NoWrap"/>
                   <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
                  </DataTrigger>
                  <DataTrigger Binding="{Binding DetailsExpanded}" Value="True">
                   <Setter Property="TextWrapping" Value="Wrap"/>
                   <Setter Property="TextTrimming" Value="None"/>
                  </DataTrigger>
                 </Style.Triggers>
                </Style>
               </TextBlock.Style>
              </TextBlock>
              <TextBlock Text="{Binding Id}" FontSize="10" Foreground="#71717A" TextWrapping="Wrap" Margin="0,3,0,0">
               <TextBlock.Style>
                <Style TargetType="TextBlock">
                 <Style.Triggers>
                  <DataTrigger Binding="{Binding IsUniversalInventory}" Value="True"><Setter Property="Visibility" Value="Collapsed"/></DataTrigger>
                 </Style.Triggers>
                </Style>
               </TextBlock.Style>
              </TextBlock>
             </StackPanel>
             <ToggleButton x:Name="InstalledDetailsToggle" Grid.Column="3" IsChecked="{Binding DetailsExpanded, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}" Width="25" Height="25" Margin="8,0,3,0" FontSize="15" FontWeight="Bold" Foreground="#FFFFFF" Background="#52525B" BorderBrush="#71717A" BorderThickness="1" Cursor="Hand" FocusVisualStyle="{x:Null}" VerticalAlignment="Center" HorizontalAlignment="Right" ToolTip="Show installation details">
              <ToggleButton.Template>
               <ControlTemplate TargetType="ToggleButton">
                <Border x:Name="ArrowSurface" Background="#52525B" BorderBrush="#71717A" BorderThickness="1" CornerRadius="5" SnapsToDevicePixels="True" RenderTransformOrigin="0.5,0.5">
                 <ContentPresenter x:Name="ArrowGlyph" RenderTransformOrigin="0.5,0.5" HorizontalAlignment="Center" VerticalAlignment="Center" RecognizesAccessKey="True"/>
                </Border>
                <ControlTemplate.Triggers>
                 <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="ArrowSurface" Property="Background" Value="#62626C"/><Setter TargetName="ArrowSurface" Property="BorderBrush" Value="#8E8E99"/></Trigger>
                 <Trigger Property="IsPressed" Value="True"><Setter TargetName="ArrowSurface" Property="Background" Value="#46464E"/><Setter TargetName="ArrowSurface" Property="BorderBrush" Value="#71717A"/><Setter TargetName="ArrowSurface" Property="RenderTransform"><Setter.Value><ScaleTransform ScaleX="0.9" ScaleY="0.9"/></Setter.Value></Setter></Trigger>
                 <Trigger Property="IsChecked" Value="True"><Setter Property="Content" Value="⌃"/></Trigger>
                </ControlTemplate.Triggers>
               </ControlTemplate>
              </ToggleButton.Template>
              <ToggleButton.Style>
               <Style TargetType="ToggleButton">
                <Setter Property="Visibility" Value="Collapsed"/>
                <Setter Property="Content" Value="⌄"/>
                <Style.Triggers>
                 <DataTrigger Binding="{Binding IsUniversalInventory}" Value="True"><Setter Property="Visibility" Value="Visible"/></DataTrigger>
                </Style.Triggers>
               </Style>
              </ToggleButton.Style>
             </ToggleButton>
            </Grid>
            <Border Width="8" Height="8" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,1,2,0"
                    Background="#3B82F6" CornerRadius="4" ToolTip="This app is installed"
                    SnapsToDevicePixels="True">
             <Border.Style>
              <Style TargetType="Border">
               <Setter Property="Visibility" Value="Collapsed"/>
               <Style.Triggers>
                <DataTrigger Binding="{Binding IsInstalled}" Value="True">
                 <Setter Property="Visibility" Value="Visible"/>
                </DataTrigger>
                <DataTrigger Binding="{Binding IsUniversalInventory}" Value="True">
                 <Setter Property="Visibility" Value="Collapsed"/>
                </DataTrigger>
               </Style.Triggers>
              </Style>
             </Border.Style>
            </Border>
            <Popup x:Name="InstalledDetailsPopup" PlacementTarget="{Binding ElementName=InstalledDetailsToggle}" Placement="Bottom" HorizontalOffset="-225" VerticalOffset="5" AllowsTransparency="True" StaysOpen="False" PopupAnimation="Fade" IsOpen="{Binding IsChecked, ElementName=InstalledDetailsToggle, Mode=OneWay}">
             <Control Focusable="False" IsTabStop="False">
<Control.Template>
<ControlTemplate TargetType="Control">
<Border x:Name="InstalledDetailsPanel" Width="250" Margin="0" Padding="8" Background="#1C232D" BorderBrush="#3F5F80" BorderThickness="1" CornerRadius="7" SnapsToDevicePixels="True">
             <StackPanel>
              <TextBlock Text="Installation details" Foreground="#7F9CBF" FontSize="10" FontWeight="Bold" Margin="0,0,0,5"/>
              <TextBlock Text="Full application name" Foreground="#94A3B8" FontSize="9"/>
              <TextBlock Text="{Binding DisplayName}" Foreground="#E2E8F0" FontSize="10" TextWrapping="Wrap" Margin="0,1,0,5"/>
              <TextBlock Text="Application ID" Foreground="#94A3B8" FontSize="9"/>
              <TextBlock Text="{Binding Id}" Foreground="#E2E8F0" FontSize="10" TextWrapping="Wrap" Margin="0,1,0,5"/>
              <TextBlock Text="Install path" Foreground="#94A3B8" FontSize="9"/>
              <DockPanel LastChildFill="True" Margin="0,1,0,5">
               <Button x:Name="InstalledCopyPathBtn" DockPanel.Dock="Right" Content="⧉" Tag="{Binding DisplayInstallPath}" Width="24" Height="22" Margin="6,0,0,0" Padding="0" FontSize="14" FontWeight="SemiBold" Foreground="#E8D8B5" Background="{StaticResource AMRCopyBtnGlassBrush}" BorderBrush="{StaticResource AMRCopyBtnEdgeBrush}" BorderThickness="1" Cursor="Hand" FocusVisualStyle="{x:Null}" ToolTip="Copy installation path">
                <Button.Style><Style TargetType="Button"><Setter Property="Visibility" Value="Collapsed"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/></Border></ControlTemplate></Setter.Value></Setter><Style.Triggers><DataTrigger Binding="{Binding HasCopyableInstallPath}" Value="True"><Setter Property="Visibility" Value="Visible"/></DataTrigger></Style.Triggers></Style></Button.Style>
               </Button>
               <TextBlock Text="{Binding DisplayInstallPath, TargetNullValue='Not recorded by Windows', FallbackValue='Not recorded by Windows'}" Foreground="#E2E8F0" FontSize="10" TextWrapping="Wrap" VerticalAlignment="Center"/>
              </DockPanel>
              <TextBlock Text="Version" Foreground="#94A3B8" FontSize="9"/>
              <TextBlock Text="{Binding DisplayVersion, TargetNullValue='Not recorded', FallbackValue='Not recorded'}" Foreground="#E2E8F0" FontSize="10" Margin="0,1,0,5"/>
              <TextBlock Text="Publisher / Source" Foreground="#94A3B8" FontSize="9"/>
              <TextBlock Text="{Binding Publisher}" Foreground="#E2E8F0" FontSize="10" TextWrapping="Wrap"/>
              <TextBlock Text="{Binding Source}" Foreground="#94A3B8" FontSize="9" TextWrapping="Wrap" Margin="0,4,0,0"/>
             </StackPanel>
            </Border>
</ControlTemplate>
</Control.Template>
</Control>
            </Popup>
           </Grid>
          </Border>
          </Grid>
         </DataTemplate>
  <!-- Activation Center: opaque glass-like graphite layers with warm reflective edges. -->
  <LinearGradientBrush x:Key="ActivationOuterGlassBrush" StartPoint="0,0" EndPoint="0.9,1">
   <GradientStop Color="#D65B554B" Offset="0"/><GradientStop Color="#E83A3B3F" Offset="0.20"/><GradientStop Color="#E52A2C31" Offset="0.62"/><GradientStop Color="#D91D1F23" Offset="1"/>
