  <!-- Windows Update Center controls: scoped premium glass template with hover/press motion. -->
  <Style x:Key="AMRUpdateGlassButtonStyle" TargetType="Button">
   <Setter Property="Background" Value="{DynamicResource ActivationInnerGlassBrush}"/>
   <Setter Property="Foreground" Value="#F4EAD5"/>
   <Setter Property="BorderBrush" Value="{DynamicResource ActivationGlassEdgeBrush}"/>
   <Setter Property="BorderThickness" Value="1"/>
   <Setter Property="FontWeight" Value="SemiBold"/>
   <Setter Property="FontSize" Value="11"/>
   <Setter Property="Padding" Value="13,7"/>
   <Setter Property="Cursor" Value="Hand"/>
   <Setter Property="RenderTransformOrigin" Value="0.5,0.5"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="Button">
      <Border x:Name="UpdateButtonSurface" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="9" RenderTransformOrigin="0.5,0.5">
       <Border.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Border.RenderTransform>
       <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="8" ShadowDepth="2" Opacity="0.20"/></Border.Effect>
       <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}" RecognizesAccessKey="True"/>
      </Border>
      <ControlTemplate.Triggers>
       <Trigger Property="IsMouseOver" Value="True">
        <Setter TargetName="UpdateButtonSurface" Property="BorderBrush" Value="#B49A70"/>
        <Setter TargetName="UpdateButtonSurface" Property="Effect">
         <Setter.Value><DropShadowEffect Color="#B49A70" BlurRadius="15" ShadowDepth="0" Opacity="0.30"/></Setter.Value>
        </Setter>
        <Trigger.EnterActions><BeginStoryboard><Storyboard>
         <DoubleAnimation Storyboard.TargetName="UpdateButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1.025" Duration="0:0:0.13"/>
         <DoubleAnimation Storyboard.TargetName="UpdateButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1.025" Duration="0:0:0.13"/>
        </Storyboard></BeginStoryboard></Trigger.EnterActions>
        <Trigger.ExitActions><BeginStoryboard><Storyboard>
         <DoubleAnimation Storyboard.TargetName="UpdateButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.16"/>
         <DoubleAnimation Storyboard.TargetName="UpdateButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.16"/>
        </Storyboard></BeginStoryboard></Trigger.ExitActions>
       </Trigger>
       <Trigger Property="IsPressed" Value="True">
        <Setter TargetName="UpdateButtonSurface" Property="Opacity" Value="0.88"/>
        <Trigger.EnterActions><BeginStoryboard><Storyboard>
         <DoubleAnimation Storyboard.TargetName="UpdateButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.985" Duration="0:0:0.06"/>
         <DoubleAnimation Storyboard.TargetName="UpdateButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.985" Duration="0:0:0.06"/>
        </Storyboard></BeginStoryboard></Trigger.EnterActions>
       </Trigger>
       <Trigger Property="IsEnabled" Value="False"><Setter TargetName="UpdateButtonSurface" Property="Opacity" Value="0.48"/></Trigger>
      </ControlTemplate.Triggers>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>
  <Style TargetType="Button">
   <Setter Property="Background" Value="#27272A"/>
   <Setter Property="Foreground" Value="#F4F4F5"/>
   <Setter Property="BorderThickness" Value="1"/>
   <Setter Property="BorderBrush" Value="#3F3F46"/>
   <Setter Property="FontWeight" Value="SemiBold"/>
   <Setter Property="Cursor" Value="Hand"/>
   <Setter Property="Padding" Value="15,8"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="Button">
      <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8">
       <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
      </Border>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>
  
  <!-- Main navigation tabs: clean software-style rounded rectangles with consistent spacing. -->
  <Style TargetType="TabControl">
   <Setter Property="Background" Value="#18181B"/>
   <Setter Property="BorderThickness" Value="0"/>
   <Setter Property="ClipToBounds" Value="False"/>
   <Setter Property="SnapsToDevicePixels" Value="True"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="TabControl">
      <Grid ClipToBounds="False" SnapsToDevicePixels="True">
       <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
       </Grid.RowDefinitions>
       <UniformGrid Grid.Row="0" Rows="1" Columns="12" IsItemsHost="True" Margin="0,0,0,12" ClipToBounds="False"/>
       <Border Grid.Row="1" Background="{TemplateBinding Background}" ClipToBounds="False">
        <ContentPresenter ContentSource="SelectedContent"/>
       </Border>
      </Grid>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>


  <!-- Main navigation + one shared contextual search field. -->
  <Style x:Key="MainNavigationTabControlStyle" TargetType="TabControl"
         BasedOn="{StaticResource {x:Type TabControl}}">
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="TabControl">
      <Grid ClipToBounds="False" SnapsToDevicePixels="True">
       <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
       </Grid.RowDefinitions>
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="330"/>
       </Grid.ColumnDefinitions>
       <UniformGrid x:Name="PART_MainTabStrip" Grid.Row="0" Grid.Column="0" Rows="1" Columns="6"
                    IsItemsHost="True" Margin="0,0,10,10" VerticalAlignment="Center"
                    ClipToBounds="False"/>
       <Border x:Name="PART_SmartSearchPanel" Grid.Row="0" Grid.Column="1" Margin="4,0,0,10"
               Background="#101D30" BorderBrush="#2874C7" BorderThickness="1.3"
               CornerRadius="11" Padding="9,6" VerticalAlignment="Center"
               RenderTransformOrigin="0.5,0.5">
        <Border.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Border.RenderTransform>
        <Border.Effect><DropShadowEffect Color="#38BDF8" BlurRadius="9" ShadowDepth="0" Opacity="0.10"/></Border.Effect>
        <StackPanel>
         <Grid Height="36">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <TextBox x:Name="PART_SmartSearchBox" Grid.Column="0" BorderThickness="0"
                   Background="Transparent" Foreground="#F1F5F9" CaretBrush="#38BDF8"
                   FontSize="14" VerticalContentAlignment="Center" Padding="3,0"
                   ToolTip="Search within the current section" Tag="Search in current section..."
                   Text=""/>
          <TextBlock Grid.Column="0" Text="{Binding Tag, ElementName=PART_SmartSearchBox}"
                     Foreground="#8194AA" FontSize="13" VerticalAlignment="Center"
                     Margin="4,0,0,0" IsHitTestVisible="False">
           <TextBlock.Style>
            <Style TargetType="TextBlock">
             <Setter Property="Visibility" Value="Collapsed"/>
             <Style.Triggers>
              <DataTrigger Binding="{Binding Text.Length, ElementName=PART_SmartSearchBox}" Value="0">
               <Setter Property="Visibility" Value="Visible"/>
              </DataTrigger>
             </Style.Triggers>
            </Style>
           </TextBlock.Style>
          </TextBlock>
          <TextBlock Grid.Column="1" Text="⌕" Foreground="#38BDF8" FontSize="25"
                     VerticalAlignment="Center" Margin="8,0,2,2" IsHitTestVisible="False"/>
         </Grid>
         <ComboBox x:Name="PART_SmartCategoryFilter" Height="30" Margin="0,5,0,0"
                   Padding="9,3" FontSize="12" FontWeight="SemiBold" VerticalContentAlignment="Center"
                   Background="#172536" Foreground="#E7EAF0" BorderBrush="#52647A"
                   BorderThickness="1" Visibility="Collapsed"
                   ToolTip="Filter the current section by category">
          <ComboBox.Resources>
           <!-- Refined champagne-on-navy selector: dark closed face, legible text, restrained hover and hairline separators. -->
           <SolidColorBrush x:Key="AMRCategoryFaceBrush" Color="#172536"/>
           <SolidColorBrush x:Key="AMRCategoryPopupBrush" Color="#101C2B"/>
           <SolidColorBrush x:Key="AMRCategoryTextBrush" Color="#E7EAF0"/>
           <SolidColorBrush x:Key="AMRCategoryAccentBrush" Color="#B89A62"/>
           <Style TargetType="{x:Type ComboBoxItem}">
            <Setter Property="Foreground" Value="#E7EAF0"/>
            <Setter Property="Background" Value="#101C2B"/>
            <Setter Property="Padding" Value="10,7"/>
            <Setter Property="Margin" Value="0,0,0,1"/>
            <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="BorderThickness" Value="0,0,0,1"/>
            <Setter Property="BorderBrush" Value="#26364A"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Style.Triggers>
             <Trigger Property="IsHighlighted" Value="True">
              <Setter Property="Background" Value="#26364A"/>
              <Setter Property="Foreground" Value="#E8D7B5"/>
              <Setter Property="BorderBrush" Value="#34465B"/>
             </Trigger>
             <Trigger Property="IsSelected" Value="True">
              <Setter Property="Background" Value="#29384A"/>
              <Setter Property="Foreground" Value="#D9BD8B"/>
              <Setter Property="BorderBrush" Value="#B89A62"/>
             </Trigger>
             <Trigger Property="IsEnabled" Value="False">
              <Setter Property="Foreground" Value="#778496"/>
             </Trigger>
            </Style.Triggers>
           </Style>
           <Style TargetType="{x:Type ComboBox}">
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="OverridesDefaultStyle" Value="True"/>
            <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
            <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Auto"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="{x:Type ComboBox}">
               <Grid>
                <ToggleButton x:Name="CategoryToggle" Focusable="False" ClickMode="Press" IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                 <ToggleButton.Template>
                  <ControlTemplate TargetType="{x:Type ToggleButton}">
                   <Border x:Name="Face" Background="#172536" BorderBrush="#52647A" BorderThickness="1" CornerRadius="6" Padding="9,4">
                    <Grid>
                     <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="16"/></Grid.ColumnDefinitions>
                     <ContentPresenter Grid.Column="0" Content="{Binding SelectionBoxItem, RelativeSource={RelativeSource AncestorType={x:Type ComboBox}}}" ContentTemplate="{Binding SelectionBoxItemTemplate, RelativeSource={RelativeSource AncestorType={x:Type ComboBox}}}" TextElement.Foreground="#E7EAF0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
                     <Path Grid.Column="1" Data="M 0 0 L 4 4 L 8 0" Stroke="#B89A62" StrokeThickness="1.5" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Grid>
                   </Border>
                   <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Face" Property="BorderBrush" Value="#B89A62"/></Trigger>
                    <Trigger Property="IsPressed" Value="True"><Setter TargetName="Face" Property="Background" Value="#202F42"/></Trigger>
                   </ControlTemplate.Triggers>
                  </ControlTemplate>
                 </ToggleButton.Template>
                </ToggleButton>
                <Popup x:Name="PART_Popup" IsOpen="{TemplateBinding IsDropDownOpen}" Placement="Bottom" AllowsTransparency="True" Focusable="False" PopupAnimation="Fade">
                 <Border Background="#101C2B" BorderBrush="#52647A" BorderThickness="1" CornerRadius="7" Padding="3" SnapsToDevicePixels="True">
                  <ScrollViewer MaxHeight="300" CanContentScroll="True"><ItemsPresenter KeyboardNavigation.DirectionalNavigation="Contained"/></ScrollViewer>
                 </Border>
                </Popup>
               </Grid>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
          </ComboBox.Resources>
         </ComboBox>
        </StackPanel>
        <Border.Triggers>
         <EventTrigger RoutedEvent="Mouse.MouseEnter">
          <BeginStoryboard>
           <Storyboard>
            <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1.035" Duration="0:0:0.135"/>
            <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1.035" Duration="0:0:0.135"/>
            <DoubleAnimation Storyboard.TargetProperty="(UIElement.Effect).(DropShadowEffect.Opacity)" To="0.62" Duration="0:0:0.15"/>
           </Storyboard>
          </BeginStoryboard>
         </EventTrigger>
         <EventTrigger RoutedEvent="Mouse.MouseLeave">
          <BeginStoryboard>
           <Storyboard>
            <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.145"/>
            <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.145"/>
            <DoubleAnimation Storyboard.TargetProperty="(UIElement.Effect).(DropShadowEffect.Opacity)" To="0.10" Duration="0:0:0.16"/>
           </Storyboard>
          </BeginStoryboard>
         </EventTrigger>
        </Border.Triggers>
       </Border>
       <Border Grid.Row="1" Grid.ColumnSpan="2" Background="{TemplateBinding Background}"
               ClipToBounds="False">
        <ContentPresenter ContentSource="SelectedContent" ClipToBounds="False"/>
       </Border>
      </Grid>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>

  <Style TargetType="TabItem">
   <Setter Property="Padding" Value="8,10"/>
   <Setter Property="Margin" Value="3,2"/>
   <Setter Property="MinHeight" Value="50"/>
   <Setter Property="Foreground" Value="#B8B8C2"/>
   <Setter Property="Background" Value="#242832"/>
   <Setter Property="BorderThickness" Value="1"/>
   <Setter Property="BorderBrush" Value="#3A414E"/>
   <Setter Property="FontSize" Value="13"/>
   <Setter Property="FontWeight" Value="SemiBold"/>
   <Setter Property="HorizontalContentAlignment" Value="Center"/>
   <Setter Property="VerticalContentAlignment" Value="Center"/>
   <Setter Property="SnapsToDevicePixels" Value="True"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="TabItem">
      <Border x:Name="TabSurface" Background="{TemplateBinding Background}"
              BorderBrush="{TemplateBinding BorderBrush}"
              BorderThickness="{TemplateBinding BorderThickness}"
              CornerRadius="9" Padding="{TemplateBinding Padding}"
              SnapsToDevicePixels="True" UseLayoutRounding="True">
       <ContentPresenter x:Name="ContentSite" VerticalAlignment="Center"
                         HorizontalAlignment="Center" ContentSource="Header"
                         RecognizesAccessKey="True"/>
      </Border>
      <ControlTemplate.Triggers>
       <Trigger Property="IsMouseOver" Value="True">
        <Setter TargetName="TabSurface" Property="Background" Value="#303B4D"/>
        <Setter TargetName="TabSurface" Property="BorderBrush" Value="#5878A5"/>
        <Setter Property="Foreground" Value="#EAF2FF"/>
       </Trigger>
       <Trigger Property="IsSelected" Value="True">
        <Setter TargetName="TabSurface" Property="Background" Value="#7024558A"/>
        <Setter TargetName="TabSurface" Property="BorderBrush" Value="#5B9BE0"/>
        <Setter Property="Foreground" Value="#FFFFFF"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
       </Trigger>
       <Trigger Property="IsEnabled" Value="False">
        <Setter TargetName="TabSurface" Property="Opacity" Value="0.55"/>
       </Trigger>
      </ControlTemplate.Triggers>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>

  <!-- Premium hover motion for the six primary navigation tabs only.
       The original tab colors, selected state, dimensions and content remain unchanged. -->
  <Style x:Key="MainNavigationTabItemStyle" TargetType="TabItem"
         BasedOn="{StaticResource {x:Type TabItem}}">
   <Setter Property="RenderTransformOrigin" Value="0.5,0.5"/>
   <Setter Property="RenderTransform">
    <Setter.Value><ScaleTransform ScaleX="1" ScaleY="1"/></Setter.Value>
   </Setter>
   <Setter Property="Effect">
    <Setter.Value><DropShadowEffect Color="#38BDF8" BlurRadius="8" ShadowDepth="0" Opacity="0.10"/></Setter.Value>
   </Setter>
   <Style.Triggers>
    <Trigger Property="IsMouseOver" Value="True">
     <Trigger.EnterActions>
      <BeginStoryboard>
       <Storyboard>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1.055" Duration="0:0:0.135"/>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1.055" Duration="0:0:0.135"/>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.Effect).(DropShadowEffect.Opacity)" To="0.58" Duration="0:0:0.15"/>
       </Storyboard>
      </BeginStoryboard>
     </Trigger.EnterActions>
     <Trigger.ExitActions>
      <BeginStoryboard>
       <Storyboard>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.145"/>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.145"/>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.Effect).(DropShadowEffect.Opacity)" To="0.10" Duration="0:0:0.16"/>
       </Storyboard>
      </BeginStoryboard>
     </Trigger.ExitActions>
    </Trigger>
   </Style.Triggers>
  </Style>

  <!-- Phase 6.10.24: Compact Overview tiles and reserve space for the Update tab. -->
  <Style x:Key="OverviewSubTabControlStyle" TargetType="TabControl">
   <Setter Property="Background" Value="#18181B"/>
   <Setter Property="BorderThickness" Value="0"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="TabControl">
      <Grid ClipToBounds="False">
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="190"/>
       </Grid.ColumnDefinitions>
       <Border Grid.Column="0" Background="{TemplateBinding Background}"
               Padding="0,0,10,0" ClipToBounds="False">
        <ContentPresenter ContentSource="SelectedContent" ClipToBounds="False"/>
       </Border>
       <Border Grid.Column="1" Background="#281A2634" BorderBrush="#36516A"
               BorderThickness="1" CornerRadius="9" Padding="9,9,9,9"
               Margin="5,7,6,10" VerticalAlignment="Top" MaxHeight="560"
               ClipToBounds="False">
        <DockPanel LastChildFill="True">
         <TextBlock DockPanel.Dock="Top" Text="{TemplateBinding Tag}" FontSize="11"
                    FontWeight="Bold" Foreground="#8FB8E8" Margin="5,3,5,10"/>
         <ScrollViewer VerticalScrollBarVisibility="Auto"
                       HorizontalScrollBarVisibility="Disabled"
                       CanContentScroll="False" Focusable="False"
                       ClipToBounds="False">
          <StackPanel IsItemsHost="True" Orientation="Vertical" HorizontalAlignment="Center" KeyboardNavigation.TabIndex="1"
                      ClipToBounds="False"/>
         </ScrollViewer>
        </DockPanel>
       </Border>
      </Grid>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>
