  <Style TargetType="TextBox">
   <Setter Property="Background" Value="#27272A"/>
   <Setter Property="Foreground" Value="#FFFFFF"/>
   <Setter Property="BorderBrush" Value="#3F3F46"/>
   <Setter Property="BorderThickness" Value="1"/>
   <Setter Property="Padding" Value="12,8"/>
   <Setter Property="VerticalContentAlignment" Value="Center"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="TextBox">
      <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8">
       <ScrollViewer x:Name="PART_ContentHost"/>
      </Border>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>

  <!-- Phase 6.10.29: global implicit ScrollBar style copied from approved Phase 6.10.24 outlined-circle design. -->
  <Style x:Key="{x:Type ScrollBar}" TargetType="ScrollBar">
         <Setter Property="Width" Value="14"/>
         <Setter Property="Background" Value="Transparent"/>
         <Setter Property="Foreground" Value="#8FB8E8"/>
         <Setter Property="Template">
          <Setter.Value>
           <ControlTemplate TargetType="ScrollBar">
            <Grid Background="Transparent" SnapsToDevicePixels="True">
             <Track Name="PART_Track" IsDirectionReversed="True">
              <Track.DecreaseRepeatButton>
               <RepeatButton Command="ScrollBar.LineUpCommand" Opacity="0" Focusable="False" IsHitTestVisible="False"/>
              </Track.DecreaseRepeatButton>
              <Track.Thumb>
               <Thumb Width="14" Height="14" MinWidth="14" MinHeight="14" Background="Transparent" HorizontalAlignment="Center" VerticalAlignment="Center">
                <Thumb.Template>
                 <ControlTemplate TargetType="Thumb">
                  <Border x:Name="ThumbHalo" Width="14" Height="14" CornerRadius="7"
                          Background="#26384D" BorderBrush="#668FB8E8" BorderThickness="1"
                          HorizontalAlignment="Center" VerticalAlignment="Center">
                   <Ellipse x:Name="ThumbCircle" Width="7" Height="7" Fill="#8FB8E8"
                            HorizontalAlignment="Center" VerticalAlignment="Center"/>
                  </Border>
                  <ControlTemplate.Triggers>
                   <Trigger Property="IsMouseOver" Value="True">
                    <Setter TargetName="ThumbHalo" Property="BorderBrush" Value="#99A9CCF2"/>
                    <Setter TargetName="ThumbHalo" Property="Background" Value="#334A65"/>
                    <Setter TargetName="ThumbCircle" Property="Fill" Value="#A9CCF2"/>
                   </Trigger>
                   <Trigger Property="IsDragging" Value="True">
                    <Setter TargetName="ThumbHalo" Property="BorderBrush" Value="#C3DDF8"/>
                    <Setter TargetName="ThumbHalo" Property="Background" Value="#405A78"/>
                    <Setter TargetName="ThumbCircle" Property="Fill" Value="#C3DDF8"/>
                   </Trigger>
                  </ControlTemplate.Triggers>
                 </ControlTemplate>
                </Thumb.Template>
               </Thumb>
              </Track.Thumb>
              <Track.IncreaseRepeatButton>
               <RepeatButton Command="ScrollBar.LineDownCommand" Opacity="0" Focusable="False" IsHitTestVisible="False"/>
              </Track.IncreaseRepeatButton>
             </Track>
            </Grid>
            <ControlTemplate.Triggers>
             <Trigger Property="Orientation" Value="Horizontal">
              <Setter Property="Height" Value="14"/>
              <Setter Property="Width" Value="Auto"/>
             </Trigger>
            </ControlTemplate.Triggers>
           </ControlTemplate>
          </Setter.Value>
         </Setter>
        </Style>
  <!-- System Center: signature refresh control with a living blue-glass hover response. -->
  <Style x:Key="AMRSystemRefreshButtonStyle" TargetType="Button">
   <Setter Property="Background" Value="#1E4264"/>
   <Setter Property="Foreground" Value="#F7FBFF"/>
   <Setter Property="BorderBrush" Value="#5B9BD0"/>
   <Setter Property="BorderThickness" Value="1"/>
   <Setter Property="FontWeight" Value="SemiBold"/>
   <Setter Property="Cursor" Value="Hand"/>
   <Setter Property="Padding" Value="16,8"/>
   <Setter Property="RenderTransformOrigin" Value="0.5,0.5"/>
   <Setter Property="SnapsToDevicePixels" Value="True"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="Button">
      <Border x:Name="SystemRefreshSurface" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="10" RenderTransformOrigin="0.5,0.5" SnapsToDevicePixels="True">
       <Border.RenderTransform><TransformGroup><ScaleTransform ScaleX="1" ScaleY="1"/><TranslateTransform Y="0"/></TransformGroup></Border.RenderTransform>
       <Border.Effect><DropShadowEffect Color="#071827" BlurRadius="9" ShadowDepth="2" Opacity="0.28"/></Border.Effect>
       <Grid ClipToBounds="False">
        <Border x:Name="RefreshSheen" CornerRadius="9" Opacity="0" HorizontalAlignment="Left" Width="34" Background="#5AADEB"/>
        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}" RecognizesAccessKey="True"/>
       </Grid>
      </Border>
      <ControlTemplate.Triggers>
       <Trigger Property="IsMouseOver" Value="True">
        <Setter TargetName="SystemRefreshSurface" Property="Background" Value="#285B83"/>
        <Setter TargetName="SystemRefreshSurface" Property="BorderBrush" Value="#9BD5FF"/>
        <Setter TargetName="SystemRefreshSurface" Property="Effect"><Setter.Value><DropShadowEffect Color="#55B9FF" BlurRadius="22" ShadowDepth="0" Opacity="0.62"/></Setter.Value></Setter>
        <Setter TargetName="RefreshSheen" Property="Opacity" Value="0.12"/>
        <Trigger.EnterActions><BeginStoryboard><Storyboard>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1.045" Duration="0:0:0.16"/>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1.045" Duration="0:0:0.16"/>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="-2" Duration="0:0:0.16"/>
         <DoubleAnimation Storyboard.TargetName="RefreshSheen" Storyboard.TargetProperty="Width" From="10" To="58" Duration="0:0:0.28"/>
        </Storyboard></BeginStoryboard></Trigger.EnterActions>
        <Trigger.ExitActions><BeginStoryboard><Storyboard>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.19"/>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.19"/>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="0" Duration="0:0:0.19"/>
         <DoubleAnimation Storyboard.TargetName="RefreshSheen" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.16"/>
        </Storyboard></BeginStoryboard></Trigger.ExitActions>
       </Trigger>
       <Trigger Property="IsPressed" Value="True">
        <Setter TargetName="SystemRefreshSurface" Property="Background" Value="#173653"/>
        <Setter TargetName="SystemRefreshSurface" Property="BorderBrush" Value="#C4E7FF"/>
        <Trigger.EnterActions><BeginStoryboard><Storyboard>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="0.975" Duration="0:0:0.06"/>
         <DoubleAnimation Storyboard.TargetName="SystemRefreshSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="0.975" Duration="0:0:0.06"/>
        </Storyboard></BeginStoryboard></Trigger.EnterActions>
       </Trigger>
       <Trigger Property="IsEnabled" Value="False"><Setter TargetName="SystemRefreshSurface" Property="Opacity" Value="0.48"/></Trigger>
      </ControlTemplate.Triggers>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>
  <Style x:Key="AMRCleanupCheckStyle" TargetType="CheckBox">
   <Setter Property="Cursor" Value="Hand"/>
   <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
   <Setter Property="VerticalContentAlignment" Value="Center"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="CheckBox">
      <StackPanel Orientation="Horizontal" Background="Transparent">
       <Border x:Name="SelectionSurface" Width="18" Height="18" CornerRadius="5"
               Background="#FF202C3B" BorderBrush="#FF65758B" BorderThickness="1.2"
               SnapsToDevicePixels="True" VerticalAlignment="Center">
        <Grid>
         <Path x:Name="SelectionTick" Data="M 3,9 L 7,13 L 15,4"
               Stroke="#FFFFFFFF" StrokeThickness="2.0" StrokeStartLineCap="Round"
               StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"
               HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Grid>
       </Border>
       <ContentPresenter Margin="4,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
      </StackPanel>
      <ControlTemplate.Triggers>
       <Trigger Property="IsMouseOver" Value="True">
        <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FFE0AD"/>
        <Setter TargetName="SelectionSurface" Property="Background" Value="#FF34465A"/>
       </Trigger>
       <Trigger Property="IsChecked" Value="True">
        <Setter TargetName="SelectionSurface" Property="Background" Value="#FFB88D4D"/>
        <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FFFFE0AD"/>
        <Setter TargetName="SelectionTick" Property="Visibility" Value="Visible"/>
       </Trigger>
       <Trigger Property="IsEnabled" Value="False">
        <Setter TargetName="SelectionSurface" Property="Opacity" Value="0.45"/>
       </Trigger>
      </ControlTemplate.Triggers>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>
  <Style x:Key="AMRTweakCheckStyle" TargetType="CheckBox">
   <Setter Property="Cursor" Value="Hand"/>
   <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
   <Setter Property="VerticalContentAlignment" Value="Center"/>
   <Setter Property="Template">
    <Setter.Value>
     <ControlTemplate TargetType="CheckBox">
      <StackPanel Orientation="Horizontal" Background="Transparent">
       <Border x:Name="SelectionSurface" Width="18" Height="18" CornerRadius="5"
               Background="#FF1E3550" BorderBrush="#FF5E8DB8" BorderThickness="1.2"
               SnapsToDevicePixels="True" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
        <Border.RenderTransform><ScaleTransform x:Name="BoxScale" ScaleX="1" ScaleY="1"/></Border.RenderTransform>
        <Grid>
         <Path x:Name="SelectionTick" Data="M 3,9 L 7,13 L 15,4"
               Stroke="#FFFFFFFF" StrokeThickness="2.0" StrokeStartLineCap="Round"
               StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"
               HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Grid>
       </Border>
       <ContentPresenter Margin="4,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
      </StackPanel>
      <ControlTemplate.Triggers>
       <Trigger Property="IsMouseOver" Value="True">
        <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FF8BC6F4"/>
        <Setter TargetName="SelectionSurface" Property="Background" Value="#FF2A4A6E"/>
        <Trigger.EnterActions><BeginStoryboard x:Name="TweakCheckHoverIn"><Storyboard><DoubleAnimation Storyboard.TargetName="BoxScale" Storyboard.TargetProperty="ScaleX" To="1.12" Duration="0:0:0.11"/><DoubleAnimation Storyboard.TargetName="BoxScale" Storyboard.TargetProperty="ScaleY" To="1.12" Duration="0:0:0.11"/></Storyboard></BeginStoryboard></Trigger.EnterActions>
        <Trigger.ExitActions><RemoveStoryboard BeginStoryboardName="TweakCheckHoverIn"/><BeginStoryboard><Storyboard FillBehavior="Stop"><DoubleAnimation Storyboard.TargetName="BoxScale" Storyboard.TargetProperty="ScaleX" From="1.12" To="1" Duration="0:0:0.12" FillBehavior="Stop"/><DoubleAnimation Storyboard.TargetName="BoxScale" Storyboard.TargetProperty="ScaleY" From="1.12" To="1" Duration="0:0:0.12" FillBehavior="Stop"/></Storyboard></BeginStoryboard></Trigger.ExitActions>
       </Trigger>
       <Trigger Property="IsChecked" Value="True">
        <Setter TargetName="SelectionSurface" Property="Background" Value="#FF3F8FD6"/>
        <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FF9DD2FA"/>
        <Setter TargetName="SelectionTick" Property="Visibility" Value="Visible"/>
       </Trigger>
       <Trigger Property="IsEnabled" Value="False">
        <Setter TargetName="SelectionSurface" Property="Opacity" Value="0.45"/>
       </Trigger>
      </ControlTemplate.Triggers>
     </ControlTemplate>
    </Setter.Value>
   </Setter>
  </Style>
 </Window.Resources>
 
 <Grid>
  <Grid.RowDefinitions><RowDefinition Height="*"/></Grid.RowDefinitions>
  <TextBlock Name="WingetHeader" Visibility="Collapsed"/>
  <TextBlock Name="StatusText" Visibility="Collapsed"/>
  
  <!-- Main navigation with persistent context-aware search at the right. -->
  <TabControl Name="MainNavigationTabs" Grid.Row="0" Margin="10,10,10,0" Style="{StaticResource MainNavigationTabControlStyle}" ItemContainerStyle="{StaticResource MainNavigationTabItemStyle}">
   
   <!-- 1. OVERVIEW -->
   <TabItem Header="System">
    <Grid Margin="0,0,0,0">
    <TabControl Name="OverviewSubTabs" Tag="SYSTEM CENTER" Style="{StaticResource OverviewSubTabControlStyle}" TabStripPlacement="Right" ItemContainerStyle="{StaticResource OverviewSubTabItemStyle}" Background="#18181B" BorderThickness="0" Margin="0,0,0,0">
     <TabItem Header="Overview" IsSelected="True">
      <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="12,8,12,18">
       <StackPanel>
        <Grid Margin="0,4,0,12">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0">
          <TextBlock Text="OVERVIEW" FontSize="25" FontWeight="Bold" Foreground="#F8FAFC"/>
          <TextBlock Text="Device identity and hardware  •  Live performance telemetry" Foreground="#94A3B8" FontSize="12" Margin="0,5,8,0"/>
         </StackPanel>
         <StackPanel Grid.Column="1" VerticalAlignment="Center" HorizontalAlignment="Right">
          <Button Name="RefreshOverviewBtn" Content="↻ Refresh" Style="{StaticResource AMRSystemRefreshButtonStyle}" Margin="0,0,7,0" Padding="18,9" FontSize="13"/>
          <TextBlock Name="ovLastRefresh" Text="" Visibility="Collapsed" Foreground="#94A3B8" FontSize="10" HorizontalAlignment="Right" Margin="0,5,2,0"/>
         </StackPanel>
        </Grid>
        <UniformGrid Columns="3" Margin="0,0,0,10">
         <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="11" Padding="12" Margin="4">
          <StackPanel><TextBlock Text="WINDOWS" Foreground="#7DB7F0" FontSize="10" FontWeight="Bold"/><TextBlock Name="ovOS" Text="OS: Reading…" Foreground="#F1F5F9" FontSize="14" FontWeight="SemiBold" Margin="0,6,0,2" TextWrapping="Wrap"/><TextBlock Name="ovBuild" Text="Build: Reading…" Foreground="#AFC4DA" FontSize="10" TextWrapping="Wrap"/></StackPanel>
         </Border>
         <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="11" Padding="12" Margin="4">
          <StackPanel><TextBlock Text="DEVICE" Foreground="#7DB7F0" FontSize="10" FontWeight="Bold"/><TextBlock Name="ovPCName" Text="Device: Reading…" Foreground="#F1F5F9" FontSize="14" FontWeight="SemiBold" Margin="0,6,0,2" TextWrapping="Wrap"/><TextBlock Name="ovDeviceModel" Text="Model: Reading…" Foreground="#AFC4DA" FontSize="10" TextWrapping="Wrap"/><TextBlock Name="ovArch" Text="Architecture: Reading…" Foreground="#AFC4DA" FontSize="10"/></StackPanel>
         </Border>
         <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="11" Padding="12" Margin="4">
          <StackPanel><TextBlock Text="DEVICE CLASS" Foreground="#7DB7F0" FontSize="10" FontWeight="Bold"/><TextBlock Name="ovDeviceType" Text="Device type: Reading…" Foreground="#F1F5F9" FontSize="14" FontWeight="SemiBold" Margin="0,6,0,2" TextWrapping="Wrap"/><TextBlock Name="ovLastBoot" Text="Last boot: Reading…" Foreground="#AFC4DA" FontSize="10" TextWrapping="Wrap"/></StackPanel>
         </Border>
        </UniformGrid>

        <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="11" Margin="4,0,4,10"><Border.Effect><DropShadowEffect Color="#07111F" BlurRadius="17" ShadowDepth="3" Opacity="0.30"/></Border.Effect>
         <StackPanel>
          <TextBlock Text="PERFORMANCE" Foreground="#9CCCF5" FontSize="11" FontWeight="Bold" Margin="2,0,2,8"/>
          <UniformGrid Columns="4">
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="CPU LOAD" Foreground="#9DB8D2" FontSize="9" FontWeight="Bold"/><TextBlock Name="ovCPUUsageValue" Text="--%" Foreground="#F4F8FC" FontSize="21" FontWeight="Bold" Margin="0,4,0,5"/><ProgressBar Name="ovCPUUsageBar" Height="6" Minimum="0" Maximum="100" Value="0" Background="#263B50" Foreground="#56A6E8" BorderThickness="0"/><TextBlock Name="ovCPUUsageDetail" Text="Waiting for sample" Foreground="#AFC4DA" FontSize="9" Margin="0,5,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="MEMORY" Foreground="#9DB8D2" FontSize="9" FontWeight="Bold"/><TextBlock Name="ovMemoryUsageValue" Text="--%" Foreground="#F4F8FC" FontSize="21" FontWeight="Bold" Margin="0,4,0,5"/><ProgressBar Name="ovMemoryUsageBar" Height="6" Minimum="0" Maximum="100" Value="0" Background="#263B50" Foreground="#55C4A1" BorderThickness="0"/><TextBlock Name="ovMemoryUsageDetail" Text="Waiting for sample" Foreground="#AFC4DA" FontSize="9" Margin="0,5,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="GPU LOAD" Foreground="#9DB8D2" FontSize="9" FontWeight="Bold"/><TextBlock Name="ovGPUUsageValue" Text="N/A" Foreground="#F4F8FC" FontSize="21" FontWeight="Bold" Margin="0,4,0,5"/><ProgressBar Name="ovGPUUsageBar" Height="6" Minimum="0" Maximum="100" Value="0" Background="#263B50" Foreground="#B69AE8" BorderThickness="0"/><TextBlock Name="ovGPUUsageDetail" Text="Waiting for GPU sample" Foreground="#AFC4DA" FontSize="9" Margin="0,5,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="NETWORK" Foreground="#9DB8D2" FontSize="9" FontWeight="Bold"/><TextBlock Name="ovNetworkStatusValue" Text="--" Foreground="#F4F8FC" FontSize="17" FontWeight="Bold" Margin="0,6,0,7" TextWrapping="Wrap"/><TextBlock Name="ovNetworkStatusDetail" Text="Waiting for sample" Foreground="#AFC4DA" FontSize="9" TextWrapping="Wrap"/></StackPanel></Border>
          </UniformGrid>
          <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3,7,3,0">
           <StackPanel>
            <Grid Margin="0,0,0,5"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="SYSTEM STORAGE · C:" Foreground="#9DB8D2" FontSize="9" FontWeight="Bold"/><TextBlock Name="ovSystemDriveStorageValue" Grid.Column="1" Text="N/A" Foreground="#D7E8F5" FontSize="10" FontWeight="Bold"/></Grid>
            <ProgressBar Name="ovSystemDriveStorageBar" Height="7" Minimum="0" Maximum="100" Value="0" Background="#263B50" Foreground="#6FA8C9" BorderThickness="0"/>
            <TextBlock Name="ovSystemDriveStorageDetail" Text="C: waiting for storage sample" Foreground="#AFC4DA" FontSize="9" Margin="0,5,0,0" TextWrapping="Wrap"/>
           </StackPanel>
          </Border>
          <TextBlock Name="ovPerformanceFootnote" Text="Measurements are read locally from Windows. Unsupported sensors are shown as unavailable." Foreground="#7892AA" FontSize="9" Margin="5,7,2,0" TextWrapping="Wrap"/>
         </StackPanel>
        </Border>

        <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="10" Margin="4,0,4,10"><Border.Effect><DropShadowEffect Color="#07111F" BlurRadius="17" ShadowDepth="3" Opacity="0.30"/></Border.Effect>
         <StackPanel>
          <TextBlock Text="HARDWARE DETAILS" Foreground="#9CCCF5" FontSize="11" FontWeight="Bold" Margin="3,0,0,7"/>
          <UniformGrid Columns="3">
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="PROCESSOR" Foreground="#78B9F0" FontSize="9" FontWeight="Bold" Margin="0,0,0,5"/><TextBlock Name="ovCPU" Text="Reading processor…" Foreground="#F1F5F9" FontSize="12" TextWrapping="Wrap"/><TextBlock Name="ovCPULoad" Text="CPU usage: --" Foreground="#B8C9D9" FontSize="10" Margin="0,4,0,0" TextWrapping="Wrap"/><TextBlock Name="ovThreads" Text="Cores / threads: --" Foreground="#B8C9D9" FontSize="10" Margin="0,3,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="GRAPHICS" Foreground="#78B9F0" FontSize="9" FontWeight="Bold" Margin="0,0,0,5"/><TextBlock Name="ovGPU" Text="Reading graphics adapter…" Foreground="#F1F5F9" FontSize="12" TextWrapping="Wrap"/><TextBlock Name="ovOverviewGPUDetails" Text="Graphics details: --" Foreground="#B8C9D9" FontSize="10" Margin="0,4,0,0" TextWrapping="Wrap"/><TextBlock Name="ovOverviewDisplay" Text="Display: --" Foreground="#B8C9D9" FontSize="10" Margin="0,3,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="MOTHERBOARD / BIOS" Foreground="#78B9F0" FontSize="9" FontWeight="Bold" Margin="0,0,0,5"/><TextBlock Name="ovMobo" Text="Reading board…" Foreground="#F1F5F9" FontSize="12" TextWrapping="Wrap"/><TextBlock Name="ovBIOS" Text="BIOS: --" Foreground="#B8C9D9" FontSize="10" Margin="0,4,0,0" TextWrapping="Wrap"/><TextBlock Name="ovBIOSDate" Text="BIOS date: --" Foreground="#B8C9D9" FontSize="10" Margin="0,3,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="MEMORY (RAM)" Foreground="#78B9F0" FontSize="9" FontWeight="Bold" Margin="0,0,0,5"/><TextBlock Name="ovRAMTotal" Text="Total RAM: --" Foreground="#F1F5F9" FontSize="12" TextWrapping="Wrap"/><TextBlock Name="ovRAMUsage" Text="" Visibility="Collapsed" Foreground="#B8C9D9" FontSize="10" Margin="0,4,0,0" TextWrapping="Wrap"/><TextBlock Name="ovOverviewRAMAvailable" Text="" Visibility="Collapsed" Foreground="#B8C9D9" FontSize="10" Margin="0,3,0,0" TextWrapping="Wrap"/></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="STORAGE" Foreground="#78B9F0" FontSize="9" FontWeight="Bold" Margin="0,0,0,5"/><TextBlock Text="FIXED PARTITIONS" Foreground="#9DB8D2" FontSize="9" FontWeight="Bold" Margin="0,2,0,5"/><TextBlock Name="ovDisksEmpty" Text="No fixed partitions detected" Foreground="#AFC4DA" FontSize="9" Margin="2,4,0,0" Visibility="Visible"/><ItemsControl Name="ovDisks"><ItemsControl.ItemTemplate><DataTemplate><Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="6" Padding="7" Margin="0,3,0,2"><StackPanel><Grid Margin="0,0,0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="{Binding Name}" Foreground="#DCE8F4" FontSize="10" FontWeight="SemiBold"/><TextBlock Text="{Binding UsedPercentText}" Grid.Column="1" Foreground="#9CCCF5" FontSize="10" FontWeight="Bold"/></Grid><ProgressBar Minimum="0" Maximum="100" Value="{Binding UsedPercent}" Height="6" Background="#263B50" Foreground="#6FA8C9" BorderThickness="0"/><TextBlock Text="{Binding DisplayText}" Foreground="#AFC4DA" FontSize="9" Margin="0,4,0,0" TextWrapping="Wrap"/></StackPanel></Border></DataTemplate></ItemsControl.ItemTemplate></ItemsControl></StackPanel></Border>
           <Border Background="{StaticResource AMROverviewGlassBrush}" BorderBrush="{StaticResource AMROverviewGlassEdgeBrush}" BorderThickness="1" CornerRadius="9" Padding="10" Margin="3"><Border.Effect><DropShadowEffect Color="#020817" BlurRadius="10" ShadowDepth="1" Opacity="0.25"/></Border.Effect><StackPanel><TextBlock Text="SYSTEM ACTIVITY" Foreground="#78B9F0" FontSize="9" FontWeight="Bold" Margin="0,0,0,5"/><TextBlock Name="ovOverviewUptime" Text="Uptime: --" Foreground="#F1F5F9" FontSize="11" TextWrapping="Wrap"/><TextBlock Name="ovOverviewProcesses" Text="Processes: --" Foreground="#B8C9D9" FontSize="10" Margin="0,4,0,0" TextWrapping="Wrap"/></StackPanel></Border>
          </UniformGrid>
         </StackPanel>
        </Border>


       </StackPanel>
      </ScrollViewer>
     </TabItem>
     <TabItem Header="Performance">
      <ScrollViewer VerticalScrollBarVisibility="Auto" Padding="12,8,12,18">
       <StackPanel>
        <Grid Margin="4,4,8,4" ClipToBounds="False"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="PERFORMANCE" FontSize="25" FontWeight="Bold" Foreground="#F8FAFC" VerticalAlignment="Center"/><Button Name="RefreshLivePerformanceBtn" Grid.Column="1" Content="↻ Refresh" Style="{StaticResource AMRSystemRefreshButtonStyle}" Margin="0,0,2,0" Padding="15,8" FontSize="11"/></Grid>
        <Grid Margin="4,0,0,14"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="Live Windows telemetry · real CPU, RAM, GPU and network samples · rolling 60-second history" Foreground="#94A3B8" FontSize="12"/><TextBlock Name="ovLiveRefreshStatus" Grid.Column="1" Text="" Visibility="Collapsed" Foreground="#8EA6BD" FontSize="9" HorizontalAlignment="Right"/></Grid>
        <UniformGrid Columns="3" Margin="0,0,0,8">
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="CPU LOAD" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><Grid Width="104" Height="104" Margin="0,8,0,5"><Ellipse Stroke="#344B63" StrokeThickness="8"/><Path Name="ovCpuGaugeArc" Stroke="#56A6E8" StrokeThickness="8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Data="M 52,4 A 48,48 0 0 1 52,100"/><TextBlock Name="ovLiveCPUValue" Text="N/A" Foreground="#F8FAFC" FontSize="20" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Grid><TextBlock Name="ovLiveCPUDetail" Text="Waiting for valid CPU sample" Foreground="#AFC4DA" FontSize="10" TextWrapping="Wrap"/></StackPanel></Border>
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="MEMORY USAGE" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><Grid Width="104" Height="104" Margin="0,8,0,5"><Ellipse Stroke="#344B63" StrokeThickness="8"/><Path Name="ovMemoryGaugeArc" Stroke="#55C4A1" StrokeThickness="8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Data="M 52,4 A 48,48 0 0 1 52,100"/><TextBlock Name="ovLiveMemoryValue" Text="N/A" Foreground="#F8FAFC" FontSize="20" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Grid><TextBlock Name="ovLiveMemoryDetail" Text="Waiting for physical memory sample" Foreground="#AFC4DA" FontSize="10" TextWrapping="Wrap"/><TextBlock Name="ovRAMAvailable" Text="Available RAM: unavailable" Foreground="#AFC4DA" FontSize="10" Margin="0,3,0,0" TextWrapping="Wrap"/></StackPanel></Border>
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="GPU LOAD" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><Grid Width="104" Height="104" Margin="0,8,0,5"><Ellipse Stroke="#344B63" StrokeThickness="8"/><Path Name="ovGpuGaugeArc" Stroke="#B69AE8" StrokeThickness="8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Data="M 52,4 A 48,48 0 0 1 52,100"/><TextBlock Name="ovLiveGPUValue" Text="N/A" Foreground="#F8FAFC" FontSize="20" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Grid><TextBlock Name="ovLiveGPUDetail" Text="Waiting for GPU engine sample" Foreground="#AFC4DA" FontSize="10" TextWrapping="Wrap"/></StackPanel></Border>
        </UniformGrid>
        <UniformGrid Columns="2" Margin="0,0,0,8">
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="CPU HISTORY · LAST 60 SECONDS" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><TextBlock Text="Real GetSystemTimes samples" Foreground="#94A3B8" FontSize="9" Margin="0,2,0,5"/><Canvas Name="ovCpuHistoryCanvas" Height="112" ClipToBounds="True"><Polyline Name="ovCpuHistoryLine" Stroke="#56A6E8" StrokeThickness="2" Points=""/></Canvas></StackPanel></Border>
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="NETWORK THROUGHPUT · LAST 60 SECONDS" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><TextBlock Name="ovNetworkRateDetail" Text="Download / Upload: waiting for byte counters" Foreground="#94A3B8" FontSize="9" Margin="0,2,0,5"/><Canvas Name="ovNetworkHistoryCanvas" Height="112" ClipToBounds="True"><Polyline Name="ovNetworkDownloadLine" Stroke="#55C4A1" StrokeThickness="2" Points=""/><Polyline Name="ovNetworkUploadLine" Stroke="#D8B56D" StrokeThickness="2" Points=""/></Canvas></StackPanel></Border>
        </UniformGrid>
        <UniformGrid Columns="2" Margin="0,0,0,8">
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="GPU HISTORY · LAST 60 SECONDS" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><TextBlock Text="Windows GPU engine utilization samples" Foreground="#94A3B8" FontSize="9" Margin="0,2,0,5"/><Canvas Name="ovGpuHistoryCanvas" Height="112" ClipToBounds="True"><Polyline Name="ovGpuHistoryLine" Stroke="#B69AE8" StrokeThickness="2" Points=""/></Canvas></StackPanel></Border>
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="SYSTEM ACTIVITY" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><TextBlock Name="ovUptime" Text="System uptime: Loading..." Foreground="#E4E4E7" FontSize="12" Margin="0,5"/><TextBlock Name="ovProcesses" Text="Processes: Loading..." Foreground="#E4E4E7" FontSize="12" Margin="0,4"/><TextBlock Name="ovLiveThreads" Text="Threads: Loading..." Foreground="#E4E4E7" FontSize="12" Margin="0,4"/><TextBlock Name="ovLiveActivityStatus" Text="Waiting for system activity sample" Foreground="#94A3B8" FontSize="10" Margin="0,4"/></StackPanel></Border>
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="NETWORK INTERFACE" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold"/><TextBlock Name="ovLiveNetworkStatus" Text="Sensor unavailable" Foreground="#F8FAFC" FontSize="15" FontWeight="Bold" Margin="0,5"/><TextBlock Name="ovLiveNetworkAdapter" Text="Adapter: --" Foreground="#E4E4E7" FontSize="11" Margin="0,3" TextWrapping="Wrap"/><TextBlock Name="ovLiveNetworkIP" Text="IPv4: --" Foreground="#E4E4E7" FontSize="11" Margin="0,3" TextWrapping="Wrap"/><TextBlock Name="ovLiveNetworkGateway" Text="Gateway: --" Foreground="#E4E4E7" FontSize="11" Margin="0,3" TextWrapping="Wrap"/><TextBlock Name="ovLiveNetworkRates" Text="Download: N/A  ·  Upload: N/A" Foreground="#94A3B8" FontSize="10" Margin="0,4" TextWrapping="Wrap"/></StackPanel></Border>
        </UniformGrid>
        <UniformGrid Columns="2" Margin="0,0,0,8">
         <Border Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="DISPLAY &amp; GRAPHICS" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold" Margin="0,0,0,8"/><TextBlock Name="ovDisplay" Text="Display: Loading..." Foreground="#E4E4E7" FontSize="12" Margin="0,4" TextWrapping="Wrap"/><TextBlock Name="ovGPUDetails" Text="Graphics details: Loading..." Foreground="#E4E4E7" FontSize="12" Margin="0,4" TextWrapping="Wrap"/></StackPanel></Border>
         <Border Name="ovBatteryCard" Background="{StaticResource AMRPerfGlassSoftBrush}" BorderBrush="{StaticResource AMRPerfGlassSoftEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="13" Margin="4"><StackPanel><TextBlock Text="BATTERY" Foreground="#7DD3FC" FontSize="11" FontWeight="Bold" Margin="0,0,0,8"/><TextBlock Name="ovBatteryStatus" Text="Battery: Checking..." Foreground="#E4E4E7" FontSize="12" Margin="0,4"/><TextBlock Name="ovBatteryHealth" Text="Battery health: Checking..." Foreground="#E4E4E7" FontSize="12" Margin="0,4"/><TextBlock Name="ovBatteryCapacity" Text="Design / Full Charge: Checking..." Foreground="#E4E4E7" FontSize="12" Margin="0,4"/></StackPanel></Border>
        </UniformGrid>
       </StackPanel>
      </ScrollViewer>
     </TabItem>
     <TabItem Name="DriverCenterTab">
      <TabItem.Header>
       <TextBlock Text="DRIVER CENTER" Foreground="#EAF2FF" FontWeight="Bold" FontSize="10" TextAlignment="Center" VerticalAlignment="Center" HorizontalAlignment="Center"/>
      </TabItem.Header>
      <ScrollViewer Name="DriverCenterScrollViewer"
                    FlowDirection="RightToLeft"
                    VerticalScrollBarVisibility="Auto"
                    HorizontalScrollBarVisibility="Disabled"
                    Padding="10,8,10,16">
       
       <!-- Keep the content's normal left-to-right layout while RTL places the scrollbar on the left. -->
       <StackPanel Name="DriverCenterMainPanel" FlowDirection="LeftToRight" Opacity="0" RenderTransformOrigin="0.5,0.5">
        <StackPanel.Resources>
         <!-- Driver Center scoped glass button style; preserves all existing button identities and handlers. -->
         <Style TargetType="{x:Type Button}">
          <Setter Property="BorderThickness" Value="1"/>
          <Setter Property="Padding" Value="12,8"/>
          <Setter Property="Cursor" Value="Hand"/>
          <Setter Property="Template">
           <Setter.Value>
            <ControlTemplate TargetType="{x:Type Button}">
             <Border x:Name="DriverGlassButtonSurface" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="10" Padding="{TemplateBinding Padding}" RenderTransformOrigin="0.5,0.5">
              <Border.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Border.RenderTransform>
              <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="8" ShadowDepth="2" Opacity="0.16"/></Border.Effect>
              <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="{TemplateBinding VerticalContentAlignment}" RecognizesAccessKey="True"/>
             </Border>
             <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
               <Setter TargetName="DriverGlassButtonSurface" Property="BorderBrush" Value="#D0B985"/>
               <Setter TargetName="DriverGlassButtonSurface" Property="Effect"><Setter.Value><DropShadowEffect Color="#B89A62" BlurRadius="16" ShadowDepth="0" Opacity="0.30"/></Setter.Value></Setter>
               <Trigger.EnterActions><BeginStoryboard><Storyboard>
                <DoubleAnimation Storyboard.TargetName="DriverGlassButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1.025" Duration="0:0:0.13"/>
                <DoubleAnimation Storyboard.TargetName="DriverGlassButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1.025" Duration="0:0:0.13"/>
               </Storyboard></BeginStoryboard></Trigger.EnterActions>
               <Trigger.ExitActions><BeginStoryboard><Storyboard>
                <DoubleAnimation Storyboard.TargetName="DriverGlassButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.16"/>
                <DoubleAnimation Storyboard.TargetName="DriverGlassButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.16"/>
               </Storyboard></BeginStoryboard></Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
               <Setter TargetName="DriverGlassButtonSurface" Property="Opacity" Value="0.88"/>
               <Trigger.EnterActions><BeginStoryboard><Storyboard>
                <DoubleAnimation Storyboard.TargetName="DriverGlassButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.985" Duration="0:0:0.06"/>
                <DoubleAnimation Storyboard.TargetName="DriverGlassButtonSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.985" Duration="0:0:0.06"/>
               </Storyboard></BeginStoryboard></Trigger.EnterActions>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False"><Setter TargetName="DriverGlassButtonSurface" Property="Opacity" Value="0.48"/></Trigger>
             </ControlTemplate.Triggers>
            </ControlTemplate>
           </Setter.Value>
          </Setter>
         </Style>
         <Style x:Key="AMRDriverDownloadsButtonStyle" TargetType="{x:Type Button}">
          <Setter Property="BorderThickness" Value="1"/>
          <Setter Property="Padding" Value="12,8"/>
          <Setter Property="Cursor" Value="Hand"/>
          <Setter Property="Template">
           <Setter.Value>
            <ControlTemplate TargetType="{x:Type Button}">
             <Border x:Name="DriverDownloadsSurface" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="10" Padding="{TemplateBinding Padding}" RenderTransformOrigin="0.5,0.5">
              <Border.RenderTransform><TransformGroup><ScaleTransform ScaleX="1" ScaleY="1"/><TranslateTransform X="0" Y="0"/><RotateTransform Angle="0"/></TransformGroup></Border.RenderTransform>
              <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="8" ShadowDepth="2" Opacity="0.16"/></Border.Effect>
              <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="{TemplateBinding VerticalContentAlignment}" RecognizesAccessKey="True"/>
             </Border>
             <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
               <Setter TargetName="DriverDownloadsSurface" Property="BorderBrush" Value="#D0B985"/>
               <Setter TargetName="DriverDownloadsSurface" Property="Effect"><Setter.Value><DropShadowEffect Color="#B89A62" BlurRadius="16" ShadowDepth="0" Opacity="0.30"/></Setter.Value></Setter>
               <Trigger.EnterActions><BeginStoryboard><Storyboard>
                <DoubleAnimation Storyboard.TargetName="DriverDownloadsSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1.02" Duration="0:0:0.22"/>
                <DoubleAnimation Storyboard.TargetName="DriverDownloadsSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1.02" Duration="0:0:0.22"/>
                <DoubleAnimation Storyboard.TargetName="DriverDownloadsSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="-1" Duration="0:0:0.22"/>
               </Storyboard></BeginStoryboard></Trigger.EnterActions>
               <Trigger.ExitActions><BeginStoryboard><Storyboard>
                <DoubleAnimation Storyboard.TargetName="DriverDownloadsSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.22"/>
                <DoubleAnimation Storyboard.TargetName="DriverDownloadsSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.22"/>
                <DoubleAnimation Storyboard.TargetName="DriverDownloadsSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="0" Duration="0:0:0.22"/>
                               </Storyboard></BeginStoryboard></Trigger.ExitActions>
              </Trigger>
              <Trigger Property="IsPressed" Value="True"><Setter TargetName="DriverDownloadsSurface" Property="Opacity" Value="0.88"/></Trigger>
              <Trigger Property="IsEnabled" Value="False"><Setter TargetName="DriverDownloadsSurface" Property="Opacity" Value="0.48"/></Trigger>
             </ControlTemplate.Triggers>
            </ControlTemplate>
           </Setter.Value>
          </Setter>
         </Style>
        </StackPanel.Resources>
        <StackPanel.RenderTransform><TranslateTransform Y="10"/></StackPanel.RenderTransform>
        <StackPanel.Triggers>
         <EventTrigger RoutedEvent="FrameworkElement.Loaded"><BeginStoryboard><Storyboard>
          <DoubleAnimation Storyboard.TargetProperty="Opacity" From="0" To="1" Duration="0:0:0.30"/>
          <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="10" To="0" Duration="0:0:0.34" DecelerationRatio="0.82"/>
         </Storyboard></BeginStoryboard></EventTrigger>
        </StackPanel.Triggers>
        <Border Name="DriverCenterHeader" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="15,12" Margin="0,2,0,14"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="17" ShadowDepth="4" Opacity="0.24"/></Border.Effect>
         <Grid>
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0" VerticalAlignment="Center" Margin="0,0,12,0">
          <TextBlock Text="DRIVER CENTER" FontSize="23" FontWeight="Bold" Foreground="#D8B56D"/>
          <TextBlock Text="Hardware intelligence • OEM-matched driver discovery" Foreground="#B8C5D6" FontSize="10" TextWrapping="Wrap" Margin="0,3,8,0"/>
         </StackPanel>
         <Border Grid.Column="1" Background="#0C1726" BorderBrush="#B89A62" BorderThickness="1" CornerRadius="10" Padding="4" Margin="0,0,12,0" VerticalAlignment="Center">
          <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
           <Button Name="DriverSmartModeBtn" Content="✦ Smart" Background="#344A43" Foreground="#F4D99B" BorderBrush="#D6B77E" BorderThickness="1" Padding="15,9" FontSize="11" FontWeight="Bold" Margin="0,0,5,0" Cursor="Hand"/>
           <Button Name="DriverAdvancedModeBtn" Content="Professional" Background="#1C293B" Foreground="#B9C9DC" BorderBrush="#456A91" BorderThickness="1" Padding="15,9" FontSize="11" Cursor="Hand"/>
          </StackPanel>
         </Border>
         <Button Name="ScanDriversBtn" Grid.Column="2" Content="⌕  Scan Device" Background="#244A70" Foreground="#F8FAFC" BorderBrush="#B89A62" BorderThickness="1" Padding="17,11" FontSize="12" FontWeight="SemiBold" VerticalAlignment="Center" Cursor="Hand"/>
         </Grid>
        </Border>
        <Border Name="DriverComputerSummaryCard" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="9,7" Margin="0,0,0,8"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="17" ShadowDepth="4" Opacity="0.24"/></Border.Effect>
         <Grid>
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
          <StackPanel Grid.Row="0" Grid.Column="0" Margin="3,1,6,1">
           <TextBlock Text="COMPUTER / OEM" Foreground="#D8B56D" FontSize="9" FontWeight="Bold"/>
           <TextBlock Name="DriverComputerModel" Text="Not scanned yet" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,3,5,0"/>
           <TextBlock Name="DriverComputerManufacturer" Text="Manufacturer: --" Foreground="#CBD5E1" FontSize="9" Margin="0,2,0,0" TextWrapping="Wrap"/>
          </StackPanel>
          <StackPanel Grid.Row="0" Grid.Column="1" Margin="6,1,4,1">
           <TextBlock Text="MOTHERBOARD" Foreground="#D8B56D" FontSize="9" FontWeight="Bold"/>
           <TextBlock Name="DriverBoardModel" Text="Not scanned yet" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,3,5,0"/>
           <TextBlock Name="DriverBoardManufacturer" Text="Manufacturer: --" Foreground="#CBD5E1" FontSize="9" Margin="0,2,0,0" TextWrapping="Wrap"/>
          </StackPanel>
          <Button Name="DriverIdentityToggleBtn" Grid.Row="0" Grid.Column="2" Content="◉" ToolTip="Show system identity and platform details" Width="31" Height="29" Padding="2" VerticalAlignment="Center" Background="#263F59" Foreground="#DCEBFA" BorderBrush="#6B91B5" BorderThickness="1" FontSize="13" Cursor="Hand" Margin="5,0,0,0"/>
          <TextBlock Name="DriverSystemIdentitySummary" Grid.Row="1" Grid.ColumnSpan="3" Text="Not scanned yet" Visibility="Collapsed" Foreground="#CBD5E1" FontSize="9" Margin="3,7,3,1" TextWrapping="Wrap"/>
         </Grid>
        </Border>
        <StackPanel Margin="0,0,0,10">
         <Border Name="DriverSmartActionsPanel" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="7,6" Margin="0,0,0,7"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="17" ShadowDepth="4" Opacity="0.24"/></Border.Effect>
          <Grid>
           <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
           <TextBlock Name="DriverModeEyebrow" Grid.Column="0" Text="SMART ASSISTANT" Foreground="#D8B56D" FontSize="12" FontWeight="Bold" VerticalAlignment="Center" Margin="2,0,8,0"/>
           <Button Name="DriverSmartSelectBtn" Grid.Column="1" Content="✦ Smart Select" IsEnabled="False" Background="#244A70" Foreground="#FFFFFF" BorderBrush="#5B91C5" BorderThickness="1" Padding="12,7" FontSize="10" FontWeight="Bold" Cursor="Hand" Margin="0,0,6,0"/>
           <Button Name="DriverStartSmartInstallBtn" Grid.Column="2" Content="Smart Install" IsEnabled="False" Background="#245B46" Foreground="#FFFFFF" BorderBrush="#55A987" BorderThickness="1" Padding="12,7" FontSize="10" FontWeight="Bold" Cursor="Hand"/>
          </Grid>
         </Border>
         <StackPanel Name="DriverProfessionalActionsPanel" Visibility="Collapsed">
          <Border Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="10" Margin="0,0,0,8">
           <StackPanel>
            <TextBlock Text="DRIVER PACKAGE" Foreground="#D8B56D" FontSize="10" FontWeight="Bold" Margin="2,0,0,7"/>
            <Grid>
             <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
             <Button Name="DriverDownloadSelectedBtn" Grid.Column="0" Content="Download &amp; Save Package" IsEnabled="False" Background="#244A70" Foreground="#EAF2FF" BorderBrush="#4B83B8" Padding="12,10" FontSize="10" FontWeight="SemiBold" Margin="0,0,5,0"/>
             <Button Name="DriverInstallSelectedBtn" Grid.Column="1" Content="Install Ready Update" IsEnabled="False" Background="#245B46" Foreground="#E8FFF3" BorderBrush="#3B8B69" Padding="12,10" FontSize="10" FontWeight="SemiBold" Margin="5,0,0,0"/>
            </Grid>
           </StackPanel>
          </Border>
          <Border Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="10" Margin="0,0,0,8">
           <StackPanel>
            <StackPanel Margin="2,0,2,10">
             <TextBlock Text="SELECTION &amp; INSTALL PLAN" Foreground="#D8B56D" FontSize="11" FontWeight="Bold" VerticalAlignment="Center" Margin="0,0,0,3"/>
             <TextBlock Text="Choose ready drivers, review the plan, then install only what you selected." Foreground="#AAB8C8" FontSize="10" TextWrapping="Wrap" VerticalAlignment="Center"/>
            </StackPanel>
            <WrapPanel Orientation="Horizontal">
             <Button Name="DriverSelectReadyBtn" Content="Select All Ready" IsEnabled="False" Background="#293B52" Foreground="#EAF1F8" BorderBrush="#526B86" Padding="13,8" FontSize="10" MinWidth="142" Margin="0,0,8,8"/>
             <Button Name="DriverClearSelectionBtn" Content="Clear Selection" IsEnabled="False" Background="#493B5874" Foreground="#F1F8FF" BorderBrush="#C7E5F8FF" BorderThickness="1.5" Padding="13,8" FontSize="10" FontWeight="SemiBold" MinWidth="142" Margin="0,0,8,8"/>
             <Button Name="DriverInstallBatchBtn" Content="Install Selected Ready (0)" IsEnabled="False" Background="#245B46" Foreground="#E8FFF3" BorderBrush="#55A987" Padding="13,8" FontSize="10" MinWidth="176" Margin="0,0,8,0"/>
             <Button Name="DriverInstallPlanBtn" Content="Preview Install Plan" IsEnabled="False" Background="#344B69" Foreground="#E7EEF7" BorderBrush="#6689B5" Padding="13,8" FontSize="10" MinWidth="160" Margin="0,0,0,0"/>
            </WrapPanel>
           </StackPanel>
          </Border>
          <Border Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="10" Margin="0,0,0,8">
           <StackPanel>
            <TextBlock Text="TOOLS &amp; OFFICIAL SOURCES" Foreground="#A7D8CE" FontSize="10" FontWeight="Bold" Margin="2,0,0,7"/>
            <WrapPanel Orientation="Horizontal">
             <Button Name="DriverCandidateManagerBtn" Content="Compare Candidates" IsEnabled="False" Background="#344B69" Foreground="#E2E8F0" BorderBrush="#6689B5" Padding="10,7" FontSize="10" Margin="0,0,6,6"/>
             <Button Name="DriverSourceManagerBtn" Content="Source Manager" IsEnabled="False" Background="#344B69" Foreground="#E2E8F0" BorderBrush="#6689B5" Padding="10,7" FontSize="10" Margin="0,0,6,6"/>
             <Button Name="DriverCatalogSearchBtn" Content="Microsoft Catalog ↗" IsEnabled="False" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="10,7" FontSize="10" Margin="0,0,6,6"/>
             <Button Name="DriverRollbackCheckBtn" Content="Check Rollback" IsEnabled="False" Background="#65412B" Foreground="#FFF1E6" BorderBrush="#A66B45" Padding="10,7" FontSize="10" Margin="0,0,6,6"/>
             <Button Name="OpenOfficialSupportBtn" Content="Official Support ↗" IsEnabled="False" Background="#263B3A" Foreground="#A7D8CE" BorderBrush="#456B65" Padding="10,7" FontSize="10" Margin="0,0,6,6"/>
             <Button Name="DriverOpenRecoveryBtn" Content="Recovery Backups" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="10,7" FontSize="10" Margin="0,0,0,6"/>
            </WrapPanel>
           </StackPanel>
          </Border>
         </StackPanel>
        </StackPanel>
        <Grid Name="DriverSummaryMetrics" Margin="0,0,0,12">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
         <Border Grid.Column="0" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="13" Margin="0,0,6,0">
          <StackPanel><TextBlock Text="WINDOWS" Foreground="#D8B56D" FontSize="11" FontWeight="Bold"/><TextBlock Name="DriverWindowsInfo" Text="Not scanned" Foreground="#F1F5F9" FontSize="12" Margin="0,6,0,0" TextWrapping="Wrap"/></StackPanel>
         </Border>
         <Border Grid.Column="1" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="13" Margin="3,0">
          <StackPanel><TextBlock Text="DETECTED DEVICES" Foreground="#D8B56D" FontSize="11" FontWeight="Bold"/><TextBlock Name="DriverDeviceCount" Text="--" Foreground="#F1F5F9" FontSize="20" FontWeight="Bold" Margin="0,4,0,0"/></StackPanel>
         </Border>
         <Border Grid.Column="2" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="13" Margin="6,0,0,0">
          <StackPanel><TextBlock Text="DEVICE ISSUES" Foreground="#FCA5A5" FontSize="11" FontWeight="Bold"/><TextBlock Name="DriverProblemCount" Text="--" Foreground="#F1F5F9" FontSize="20" FontWeight="Bold" Margin="0,4,0,0"/></StackPanel>
         </Border>
        </Grid>
        <Grid Margin="0,0,0,8">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0"><TextBlock Name="DriverModeSectionHeading" Text="" Visibility="Collapsed"/><TextBlock Name="DriverScanStatus" Text="Select Scan Device to inspect this computer. No driver will be downloaded or installed automatically." Foreground="#94A3B8" FontSize="11" TextWrapping="Wrap" Margin="0,0,8,0"><TextBlock.Style><Style TargetType="{x:Type TextBlock}"><Style.Triggers><DataTrigger Binding="{Binding Text, RelativeSource={RelativeSource Self}}" Value=""><Setter Property="Visibility" Value="Collapsed"/></DataTrigger></Style.Triggers></Style></TextBlock.Style></TextBlock><TextBlock Name="DriverModeDescription" Text="" Foreground="#94A3B8" FontSize="10" TextWrapping="Wrap" Margin="0,3,8,0"/></StackPanel>
        </Grid>
        <TextBlock Name="DriverRollbackStatus" Text="Select a device to check for retained driver alternatives. Windows determines whether Roll Back Driver is available." Foreground="#D6B58C" FontSize="10" TextWrapping="Wrap" Margin="3,0,3,8"/>
        <Grid Margin="3,0,3,8">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0" Margin="0,0,10,0">
          <TextBlock Name="DriverActionStatus" Text="Select a device row to view available actions. Downloads and installs require your confirmation." Foreground="#94A3B8" FontSize="10" TextWrapping="Wrap" Margin="0,0,0,3"/>
          <TextBlock Name="DriverSelectionSummary" Text="Selection: 0 selected • 0 ready to install • 0 unique updates available" Foreground="#7DD3FC" FontSize="10" TextWrapping="Wrap" Margin="0,0,0,5"/>
          <StackPanel Orientation="Horizontal" Margin="0,0,0,6">
           <Button Name="DriverRepairBtn" Content="Repair essential device" Visibility="Collapsed" IsEnabled="False" Background="#5A4A1F" Foreground="#FEF3C7" BorderBrush="#B08D3C" Padding="10,5" FontSize="10" Margin="0,0,6,0" ToolTip="Enables a disabled (Code 22) essential device, verifies it, rescans. Logged and reversible with Undo repair."/>
           <Button Name="DriverRepairUndoBtn" Content="Undo repair" Visibility="Collapsed" IsEnabled="False" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="10,5" FontSize="10" ToolTip="Disables the device that was just enabled by Repair (this session)."/>
          </StackPanel>
          <ProgressBar Name="DriverOperationProgress" Height="5" IsIndeterminate="True" Visibility="Collapsed" Background="#263548" Foreground="#60A5FA" BorderThickness="0"/>
          <Button Name="DriverCancelManagedOperationBtn" Content="Cancel background operation" Visibility="Collapsed" IsEnabled="False" HorizontalAlignment="Left" Background="#7F1D1D" Foreground="#FEE2E2" BorderBrush="#991B1B" Padding="8,3" FontSize="9" Margin="0,4,0,0"/>
         </StackPanel>
         <StackPanel Grid.Column="1" Orientation="Horizontal">
          <Button Name="DriverExportReportBtn" Content="Export Scan Report" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="10,5" FontSize="10" VerticalAlignment="Center" Margin="0,0,6,0"/>
          <Button Name="DriverExportHistoryBtn" Content="Export History" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="10,5" FontSize="10" VerticalAlignment="Center" Margin="0,0,6,0"/>
          <Button Name="DriverOpenDownloadsBtn" Style="{StaticResource AMRDriverDownloadsButtonStyle}" Content="Driver Downloads" Background="#263B52" Foreground="#DBEAFE" BorderBrush="#456B8A" Padding="10,5" FontSize="10" VerticalAlignment="Center" Margin="0,0,6,0"/>
          <Button Name="DriverDiagnosisBtn" Style="{StaticResource AMRDriverDownloadsButtonStyle}" Content="Diagnose Devices" IsEnabled="False" MinWidth="118" VerticalAlignment="Center" Background="#315047" Foreground="#E7FFF5" BorderBrush="#5C9A82" Padding="10,5" FontSize="10" Margin="0,0,0,0" ToolTip="Read-only diagnosis of all devices: what each problem code means, likely causes and suggested fixes. Changes nothing."/>
         </StackPanel>
        </Grid>
        <Border Name="DriverTabStrip" HorizontalAlignment="Left" Margin="2,2,0,10" Padding="4" CornerRadius="15" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1">
         <Grid>
          <Grid.Resources>
           <Style x:Key="AMRDriverTabStyle" TargetType="{x:Type Button}">
            <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Foreground" Value="#FFA9B4C4"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="{x:Type Button}">
               <Border Background="#00000000" CornerRadius="11" Padding="{TemplateBinding Padding}">
                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" RecognizesAccessKey="True"/>
               </Border>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
            <Style.Triggers>
             <Trigger Property="IsMouseOver" Value="True"><Setter Property="Foreground" Value="#FFEEF2F8"/></Trigger>
             <Trigger Property="Tag" Value="Active"><Setter Property="Foreground" Value="#FFF7ECD0"/></Trigger>
            </Style.Triggers>
           </Style>
          </Grid.Resources>
          <Border Name="DriverTabPill" Width="168" Height="38" HorizontalAlignment="Left" CornerRadius="11" BorderThickness="1" BorderBrush="#B0B89A62" IsHitTestVisible="False">
           <Border.Background>
            <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#A0788796" Offset="0"/><GradientStop Color="#70505D6A" Offset="1"/></LinearGradientBrush>
           </Border.Background>
           <Border.RenderTransform><TranslateTransform X="0"/></Border.RenderTransform>
          </Border>
          <StackPanel Orientation="Horizontal">
           <Button Name="DriverTabUpdateBtn" Style="{StaticResource AMRDriverTabStyle}" Tag="Active" Content="Driver Update" Width="168" Height="38" FontSize="13" FontWeight="SemiBold" Background="Transparent" BorderThickness="0"/>
           <Button Name="DriverTabProblemsBtn" Style="{StaticResource AMRDriverTabStyle}" Content="Problems" Width="168" Height="38" FontSize="13" FontWeight="SemiBold" Background="Transparent" BorderThickness="0"/>
          </StackPanel>
         </Grid>
        </Border>
        <Grid Name="DriverTabHost">
        <Border Name="DriverUpdatePane" Height="400" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="4">
         <ListView Name="DriverDeviceList" SelectionMode="Extended" Background="Transparent" Foreground="#E4E4E7" BorderThickness="0" MinHeight="260" MaxHeight="100000" ScrollViewer.HorizontalScrollBarVisibility="Auto" ScrollViewer.VerticalScrollBarVisibility="Auto" ScrollViewer.CanContentScroll="True" ScrollViewer.PanningMode="Both" VirtualizingPanel.IsVirtualizing="True" VirtualizingPanel.VirtualizationMode="Recycling">
          <ListView.Resources>
           <!-- Premium glass row and selection visuals; all original row bindings and selection behavior remain intact. -->
           <Style TargetType="GridViewColumnHeader">
            <Setter Property="Foreground" Value="#E9D8B5"/>
            <Setter Property="FontSize" Value="10"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Padding" Value="9,9"/>
            <Setter Property="Margin" Value="2,0,2,7"/>
            <Setter Property="HorizontalContentAlignment" Value="Center"/>
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="GridViewColumnHeader">
               <Border x:Name="DriverHeaderSurface" CornerRadius="8" Padding="{TemplateBinding Padding}"
                       Background="#B52A3039" BorderBrush="#9A9B8769" BorderThickness="1"
                       RenderTransformOrigin="0.5,0.5">
                <Border.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Border.RenderTransform>
                <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="7" ShadowDepth="2" Opacity="0.18"/></Border.Effect>
                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" RecognizesAccessKey="True"/>
               </Border>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="DriverHeaderSurface" Property="Background" Value="#D0444A53"/>
                 <Setter TargetName="DriverHeaderSurface" Property="BorderBrush" Value="#D8BD8B"/>
                 <Setter TargetName="DriverHeaderSurface" Property="Effect"><Setter.Value><DropShadowEffect Color="#B89A62" BlurRadius="13" ShadowDepth="0" Opacity="0.28"/></Setter.Value></Setter>
                 <Trigger.EnterActions><BeginStoryboard><Storyboard>
                  <DoubleAnimation Storyboard.TargetName="DriverHeaderSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1.018" Duration="0:0:0.12"/>
                  <DoubleAnimation Storyboard.TargetName="DriverHeaderSurface" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1.018" Duration="0:0:0.12"/>
                 </Storyboard></BeginStoryboard></Trigger.EnterActions>
                </Trigger>
                <Trigger Property="IsPressed" Value="True"><Setter TargetName="DriverHeaderSurface" Property="Opacity" Value="0.82"/></Trigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
           <Style TargetType="CheckBox">
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="HorizontalAlignment" Value="Center"/>
            <Setter Property="VerticalAlignment" Value="Center"/>
            <Setter Property="Width" Value="18"/>
            <Setter Property="Height" Value="18"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="CheckBox">
               <Grid Width="18" Height="18" RenderTransformOrigin="0.5,0.5">
                <Grid.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Grid.RenderTransform>
                <Border x:Name="SelectionTile" CornerRadius="5" Background="#92252B34" BorderBrush="#9B9FA8B4" BorderThickness="1.2" RenderTransformOrigin="0.5,0.5"><Border.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Border.RenderTransform>
                 <Grid>
                  <Path x:Name="SelectionTick" Data="M 3,8 L 6.5,11.5 L 14,4" Stroke="#171B20" StrokeThickness="2.1" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Opacity="0"/>
                 </Grid>
                </Border>
               </Grid>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="SelectionTile" Property="BorderBrush" Value="#E2C58E"/>
                 <Setter TargetName="SelectionTile" Property="Background" Value="#C23C4652"/>
                 <Trigger.EnterActions><BeginStoryboard><Storyboard>
                  <DoubleAnimation Storyboard.TargetName="SelectionTile" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1.10" Duration="0:0:0.10"/>
                  <DoubleAnimation Storyboard.TargetName="SelectionTile" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1.10" Duration="0:0:0.10"/>
                 </Storyboard></BeginStoryboard></Trigger.EnterActions>
                </Trigger>
                <Trigger Property="IsChecked" Value="True">
                 <Setter TargetName="SelectionTile" Property="Background" Value="#D9D0AE7C"/>
                 <Setter TargetName="SelectionTile" Property="BorderBrush" Value="#F0D8A4"/>
                 <Setter TargetName="SelectionTick" Property="Opacity" Value="1"/>
                </Trigger>
                <Trigger Property="IsEnabled" Value="False"><Setter TargetName="SelectionTile" Property="Opacity" Value="0.42"/></Trigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
           <Style TargetType="ListViewItem">
            <Setter Property="Foreground" Value="#E9E6DF"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Padding" Value="5,5"/>
            <Setter Property="Margin" Value="0,1,0,2"/>
            <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="ListViewItem">
               <Border x:Name="DriverRowBorder" Background="#4D252A32" BorderBrush="#4D8C8068"
                       BorderThickness="0,0,0,1" CornerRadius="9" Padding="{TemplateBinding Padding}"
                       RenderTransformOrigin="0.5,0.5">
                <Border.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Border.RenderTransform>
                <GridViewRowPresenter Content="{TemplateBinding Content}"
                 Columns="{Binding View.Columns, RelativeSource={RelativeSource AncestorType={x:Type ListView}}}"
                 VerticalAlignment="Center"/>
               </Border>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="DriverRowBorder" Property="Background" Value="#A13D4652"/>
                 <Setter TargetName="DriverRowBorder" Property="BorderBrush" Value="#B99D70"/>
                 <Setter Property="Foreground" Value="#FFF9ED"/>
                 <Setter TargetName="DriverRowBorder" Property="Effect"><Setter.Value><DropShadowEffect Color="#B89A62" BlurRadius="12" ShadowDepth="0" Opacity="0.20"/></Setter.Value></Setter>
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                 <Setter TargetName="DriverRowBorder" Property="Background" Value="#B347514E"/>
                 <Setter TargetName="DriverRowBorder" Property="BorderBrush" Value="#E0C28C"/>
                 <Setter TargetName="DriverRowBorder" Property="BorderThickness" Value="1"/>
                 <Setter Property="Foreground" Value="#FFF9EA"/>
                </Trigger>
                <MultiTrigger>
                 <MultiTrigger.Conditions><Condition Property="IsSelected" Value="True"/><Condition Property="IsMouseOver" Value="True"/></MultiTrigger.Conditions>
                 <Setter TargetName="DriverRowBorder" Property="Background" Value="#D0525C57"/>
                 <Setter TargetName="DriverRowBorder" Property="BorderBrush" Value="#F0D6A1"/>
                </MultiTrigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
          </ListView.Resources>
          <ListView.View>
           <GridView>
            <GridViewColumn Header="Select" Width="48">
             <GridViewColumn.CellTemplate>
              <DataTemplate>
               <CheckBox HorizontalAlignment="Center" VerticalAlignment="Center"
                         IsChecked="{Binding IsSelected, RelativeSource={RelativeSource AncestorType={x:Type ListViewItem}}, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}"
                         ToolTip="Select this driver row"/>
              </DataTemplate>
             </GridViewColumn.CellTemplate>
            </GridViewColumn>
            <GridViewColumn Header="Device" Width="245"><GridViewColumn.CellTemplate><DataTemplate><Border Background="#512D333C" BorderBrush="#565E6874" BorderThickness="1" CornerRadius="7" Padding="8,5" Margin="2,1"><TextBlock Text="{Binding DeviceName}" Foreground="#F3EEE4" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/></Border></DataTemplate></GridViewColumn.CellTemplate></GridViewColumn>
            <GridViewColumn Header="Class" Width="105"><GridViewColumn.CellTemplate><DataTemplate><Border Background="#452B3945" BorderBrush="#555E788A" BorderThickness="1" CornerRadius="7" Padding="6,5" Margin="2,1"><TextBlock Text="{Binding DeviceClass}" Foreground="#DCE8F2" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/></Border></DataTemplate></GridViewColumn.CellTemplate></GridViewColumn>
            <GridViewColumn Header="Manufacturer" Width="145"><GridViewColumn.CellTemplate><DataTemplate><Border Background="#512D333C" BorderBrush="#565E6874" BorderThickness="1" CornerRadius="7" Padding="7,5" Margin="2,1"><TextBlock Text="{Binding Manufacturer}" Foreground="#E7E2D8" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/></Border></DataTemplate></GridViewColumn.CellTemplate></GridViewColumn>
            <GridViewColumn Header="Status" Width="115"><GridViewColumn.CellTemplate><DataTemplate><Border Background="#583A463F" BorderBrush="#657B8B70" BorderThickness="1" CornerRadius="7" Padding="7,5" Margin="2,1"><TextBlock Text="{Binding StatusText}" Foreground="#DCEBDD" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/></Border></DataTemplate></GridViewColumn.CellTemplate></GridViewColumn>
            <GridViewColumn Header="Driver Provider" Width="150"><GridViewColumn.CellTemplate><DataTemplate><Border Background="#512D333C" BorderBrush="#565E6874" BorderThickness="1" CornerRadius="7" Padding="7,5" Margin="2,1"><TextBlock Text="{Binding DriverProvider}" Foreground="#E5E8ED" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/></Border></DataTemplate></GridViewColumn.CellTemplate></GridViewColumn>
            <GridViewColumn Header="Installed Version" Width="135" DisplayMemberBinding="{Binding DriverVersion}"/>
            <GridViewColumn Header="Driver Date" Width="95" DisplayMemberBinding="{Binding DriverDate}"/>
            <GridViewColumn Header="Update Check" Width="190" DisplayMemberBinding="{Binding UpdateStatus}"/>
            <GridViewColumn Header="Match Confidence" Width="190" DisplayMemberBinding="{Binding MatchConfidence}"/>
            <GridViewColumn Header="Alternatives" Width="75" DisplayMemberBinding="{Binding MatchCandidateCount}"/>
            <GridViewColumn Header="Available Update / Search Match" Width="250" DisplayMemberBinding="{Binding DriverSearchDisplay}"/>
            <GridViewColumn Header="Available Version" Width="130" DisplayMemberBinding="{Binding AvailableVersion}"/>
            <GridViewColumn Header="Code" Width="55" DisplayMemberBinding="{Binding ErrorCode}"/>
           </GridView>
          </ListView.View>
         </ListView>
        </Border>
         <Border Name="DriverProblemsPane" Visibility="Collapsed" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="18,16" Height="400">
          <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel>
           <Border Name="DriverProblemsEmpty" Background="#33000000" BorderBrush="#33FFFFFF" BorderThickness="1" CornerRadius="12" Padding="22,26">
            <StackPanel HorizontalAlignment="Center">
             <TextBlock Text="&#x2713;" FontSize="30" Foreground="#FFD8B56D" HorizontalAlignment="Center"/>
             <TextBlock Text="No diagnosis yet" FontSize="15" FontWeight="Bold" Foreground="#FFEAF0FF" HorizontalAlignment="Center" Margin="0,6,0,4"/>
             <TextBlock Text="Run Scan Device. AMR then checks every device in the background and lists problems here with the likely cause and a suggested fix." FontSize="12" Foreground="#FF9FB0CF" TextWrapping="Wrap" TextAlignment="Center" MaxWidth="460"/>
            </StackPanel>
           </Border>
                <Border Name="DriverDiagPanel" Visibility="Collapsed" Margin="0" Background="Transparent" BorderThickness="0" CornerRadius="12" Padding="0">
                 <StackPanel>
                  <Grid>
                   <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                   <TextBlock Name="DriverDiagBadge" Text="" FontSize="16" FontWeight="Bold" Foreground="#E9D8B5" VerticalAlignment="Center" TextWrapping="Wrap"/>
                   <Button Name="DriverDiagViewTextBtn" Grid.Column="1" Content="View as text" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="9,3" FontSize="10"/>
                  </Grid>
                  <TextBlock Name="DriverDiagSummary" Text="" Visibility="Collapsed" FontSize="10" Foreground="#94A3B8" TextWrapping="Wrap" Margin="0,3,0,6"/>
                  <StackPanel Name="DriverDiagCards" Margin="0,4,0,0"/>
                  <Button Name="DriverDiagShowMoreBtn" Content="Show 10 more" Visibility="Collapsed" HorizontalAlignment="Left" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" Padding="14,6" FontSize="11" Margin="0,2,0,0"/>
                 </StackPanel>
                </Border>
         </StackPanel>
          </ScrollViewer>
         </Border>
        </Grid>
       </StackPanel>
      </ScrollViewer>
     </TabItem>
     <TabItem Header="Startups">
      <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="14,10,14,18">
       <StackPanel>
        <Border Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="19" Padding="20" Margin="2,2,2,14">
         <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="22" ShadowDepth="6" Opacity="0.34"/></Border.Effect>
         <Grid>
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <StackPanel Grid.Column="0" VerticalAlignment="Center">
           <TextBlock Text="STARTUP MANAGER  ·  SYSTEM CONTROL" Foreground="#D9BD8B" FontSize="9" FontWeight="Bold" />
           <TextBlock Text="Startup apps" Foreground="#F8F2E7" FontSize="25" FontWeight="Bold" Margin="0,5,0,3"/>
           <TextBlock Text="Manage what launches with Windows" Foreground="#B8C3D0" FontSize="11" Margin="1,1,0,0"/>
          </StackPanel>
          <Button Name="AMRStartupRefreshBtn" Grid.Column="1" Content="↻  Refresh" Width="124" Height="40" VerticalAlignment="Center" Background="{DynamicResource ActivationInnerGlassBrush}" Foreground="#F4EAD5" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" FontSize="11" FontWeight="SemiBold" Cursor="Hand" Padding="14,0"/>
         </Grid>
        </Border>
        <Grid Margin="3,0,3,12">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
         <StackPanel>
          <TextBlock Name="AMRStartupSummary" Text="Discovering startup applications…" Foreground="#E5EDF6" FontSize="12" FontWeight="SemiBold"/>
          <TextBlock Name="AMRStartupHint" Text="" Foreground="#829BB3" FontSize="1" Visibility="Collapsed" Margin="0" TextWrapping="Wrap"/>
         </StackPanel>
         <Border Grid.Column="1" Background="#402D665A" BorderBrush="#806CC7A9" BorderThickness="1" CornerRadius="12" Padding="11,6" VerticalAlignment="Center">
          <Border.Effect><DropShadowEffect Color="#36B99A" BlurRadius="10" ShadowDepth="0" Opacity="0.18"/></Border.Effect>
          <TextBlock Text="●  LIVE INVENTORY" Foreground="#9BE2C9" FontSize="9" FontWeight="Bold"/>
         </Border>
        </Grid>
        <StackPanel Name="AMRStartupAppsHost"/>
        <Border Name="AMRStartupEmptyState" Background="#172536" BorderBrush="#30465C" BorderThickness="1" CornerRadius="13" Padding="20" Margin="3,4,3,8" Visibility="Collapsed">
         <StackPanel HorizontalAlignment="Center">
          <TextBlock Text="✦" Foreground="#D9BD8B" FontSize="28" HorizontalAlignment="Center"/>
          <TextBlock Name="AMRStartupEmptyTitle" Text="No startup applications detected" Foreground="#E5EDF6" FontSize="14" FontWeight="SemiBold" HorizontalAlignment="Center" Margin="0,7,0,3"/>
          <TextBlock Name="AMRStartupEmptyDetail" Text="Refresh to scan the current Windows startup locations again." Foreground="#91A6BA" FontSize="10" TextAlignment="Center" TextWrapping="Wrap"/>
         </StackPanel>
        </Border>
       </StackPanel>
      </ScrollViewer>
     </TabItem>
     <TabItem Header="Update">
      <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Background="#17191D">
       <Grid Margin="16,14,16,20" Opacity="0" RenderTransformOrigin="0.5,0.5">
        <Grid.RenderTransform><TranslateTransform Y="9"/></Grid.RenderTransform>
        <Grid.Triggers>
         <EventTrigger RoutedEvent="FrameworkElement.Loaded"><BeginStoryboard><Storyboard>
          <DoubleAnimation Storyboard.TargetProperty="Opacity" From="0" To="1" Duration="0:0:0.28"/>
          <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="9" To="0" Duration="0:0:0.30" DecelerationRatio="0.82"/>
         </Storyboard></BeginStoryboard></EventTrigger>
        </Grid.Triggers>
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <!-- Hero header -->
        <Border Grid.Row="0" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="16" Padding="20" Margin="0,0,0,13">
         <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="18" ShadowDepth="5" Opacity="0.30"/></Border.Effect>
         <Grid>
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <StackPanel VerticalAlignment="Center">
           <TextBlock Text="WINDOWS UPDATE CENTER" FontSize="10" FontWeight="Bold" Foreground="#D9BD8B"/>
           <TextBlock Text="Windows Update Center" FontSize="25" FontWeight="Bold" Foreground="#F1EEE7" Margin="0,5,0,3"/>
           <TextBlock Text="A clearer control room for update status, profiles, downloads, installation and recovery." Foreground="#B7B5AE" FontSize="11" TextWrapping="Wrap" MaxWidth="690"/>
           <ProgressBar Name="AMRUpdateProgress" Height="3" Margin="0,12,0,0" IsIndeterminate="True" Visibility="Collapsed" Background="#35383D" Foreground="#B89A62" BorderThickness="0"/>
          </StackPanel>
          <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="14,0,0,0">
           <Button Name="AMRUpdateRefreshBtn" Content="↻  Refresh Status" MinWidth="128" Height="38" Margin="0,0,8,0" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
           <Button Name="AMRUpdateSettingsBtn" Content="Windows Settings  ↗" MinWidth="146" Height="38" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
          </StackPanel>
         </Grid>
        </Border>

        <!-- Live system status tiles -->
        <Grid Grid.Row="1" Margin="-3,0,-3,10">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
         <Border Grid.Column="0" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="14" Margin="3">
          <StackPanel><TextBlock Text="UPDATE SERVICES" Foreground="#D9BD8B" FontSize="9" FontWeight="Bold"/><TextBlock Name="AMRUpdateServiceValue" Text="Checking…" Foreground="#F1EEE7" FontSize="17" FontWeight="Bold" Margin="0,6,0,2"/><TextBlock Name="AMRUpdateServiceDetail" Text="Windows Update / BITS" Foreground="#B7B5AE" FontSize="10"/></StackPanel>
         </Border>
         <Border Grid.Column="1" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="14" Margin="3">
          <StackPanel><TextBlock Text="LAST SUCCESSFUL UPDATE" Foreground="#D9BD8B" FontSize="9" FontWeight="Bold"/><TextBlock Name="AMRUpdateLastValue" Text="Not available" Foreground="#F1EEE7" FontSize="15" FontWeight="Bold" Margin="0,6,0,2"/><TextBlock Text="Local Windows update history" Foreground="#B7B5AE" FontSize="10"/></StackPanel>
         </Border>
         <Border Grid.Column="2" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="14" Margin="3">
          <StackPanel><TextBlock Text="RESTART STATUS" Foreground="#D9BD8B" FontSize="9" FontWeight="Bold"/><TextBlock Name="AMRUpdateRebootValue" Text="Checking…" Foreground="#F1EEE7" FontSize="17" FontWeight="Bold" Margin="0,6,0,2"/><TextBlock Text="Pending servicing / update reboot" Foreground="#B7B5AE" FontSize="10"/></StackPanel>
         </Border>
         <Border Grid.Column="3" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="14" Margin="3">
          <StackPanel><TextBlock Text="ACTIVE PROFILE" Foreground="#D9BD8B" FontSize="9" FontWeight="Bold"/><TextBlock Name="AMRUpdateProfileValue" Text="Windows default / unknown" Foreground="#F1EEE7" FontSize="14" FontWeight="Bold" Margin="0,6,0,2"/><TextBlock Name="AMRUpdateEditionValue" Text="Detecting Windows edition…" Foreground="#B7B5AE" FontSize="10" TextWrapping="Wrap"/></StackPanel>
         </Border>
        </Grid>

        <!-- Profile cards -->
        <Grid Grid.Row="2" Margin="-3,0,-3,12">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
         <Border Grid.Column="0" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="#65A997" BorderThickness="1.3" CornerRadius="15" Padding="17" Margin="3">
          <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="13" ShadowDepth="3" Opacity="0.22"/></Border.Effect>
          <StackPanel><TextBlock Text="✦  RECOMMENDED" Foreground="#91E0C9" FontSize="12" FontWeight="Bold"/><TextBlock Text="Balanced protection" Foreground="#F1EEE7" FontSize="17" FontWeight="Bold" Margin="0,7,0,3"/><TextBlock Text="Feature updates deferred for 365 days, quality updates for 4 days, notify before install and exclude drivers from quality updates." Foreground="#C9C5BA" FontSize="10" TextWrapping="Wrap" MinHeight="54" Margin="0,0,0,13"/><Button Name="AMRUpdateRecommendedBtn" Content="Apply Recommended" Height="37" Background="#3D665D" Foreground="#F4F1E8" BorderBrush="#8BC9B6" Style="{StaticResource AMRUpdateGlassButtonStyle}"/></StackPanel>
         </Border>
         <Border Grid.Column="1" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="15" Padding="17" Margin="3">
          <StackPanel><TextBlock Text="WINDOWS DEFAULT" Foreground="#D9BD8B" FontSize="12" FontWeight="Bold"/><TextBlock Text="Return control to Windows" Foreground="#F1EEE7" FontSize="17" FontWeight="Bold" Margin="0,7,0,3"/><TextBlock Text="Remove only policy values managed by AMR profiles. Existing settings are backed up first; Windows Update services are not forcibly changed." Foreground="#C9C5BA" FontSize="10" TextWrapping="Wrap" MinHeight="54" Margin="0,0,0,13"/><Button Name="AMRUpdateDefaultBtn" Content="Restore Windows Defaults" Height="37" Background="#45464A" Foreground="#F4F1E8" BorderBrush="#A39B89" Style="{StaticResource AMRUpdateGlassButtonStyle}"/></StackPanel>
         </Border>
         <Border Grid.Column="2" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="#A8795D" BorderThickness="1.2" CornerRadius="15" Padding="17" Margin="3">
          <StackPanel><TextBlock Text="ADVANCED PROFILE" Foreground="#E7B18E" FontSize="12" FontWeight="Bold"/><TextBlock Text="Restrict automatic updates" Foreground="#F1EEE7" FontSize="17" FontWeight="Bold" Margin="0,7,0,3"/><TextBlock Text="Restricts automatic update behavior without disabling servicing components. Manual checks remain possible. Security risk applies while restrictions are active." Foreground="#C9C5BA" FontSize="10" TextWrapping="Wrap" MinHeight="54" Margin="0,0,0,13"/><Button Name="AMRUpdateRestrictBtn" Content="Restrict Automatic Updates" Height="37" Background="#684A3B" Foreground="#FFF0E5" BorderBrush="#C08B6C" Style="{StaticResource AMRUpdateGlassButtonStyle}"/></StackPanel>
         </Border>
        </Grid>

        <!-- Update inventory and actions -->
        <Border Grid.Row="3" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="15" Padding="15" Margin="0,0,0,12">
         <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="16" ShadowDepth="4" Opacity="0.25"/></Border.Effect>
         <Grid>
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="190"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
          <Grid Grid.Row="0" Margin="1,0,1,10">
           <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
           <StackPanel><TextBlock Text="UPDATE LIBRARY" Foreground="#D9BD8B" FontSize="9" FontWeight="Bold"/><TextBlock Text="Available Windows updates" Foreground="#F1EEE7" FontSize="19" FontWeight="Bold" Margin="0,3,0,2"/><TextBlock Name="AMRUpdateListSummary" Text="Check Microsoft Update to discover available updates." Foreground="#B7B5AE" FontSize="10" TextWrapping="Wrap"/></StackPanel>
           <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
            <Button Name="AMRUpdateCheckBtn" Content="⌕  Check for Updates" MinWidth="148" Height="37" Background="#365D67" Foreground="#EAF7F7" BorderBrush="#83BFC7" Margin="0,0,8,0" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
            <Button Name="AMRUpdateHistoryBtn" Content="◷  History" MinWidth="96" Height="37" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
           </StackPanel>
          </Grid>
          <Border Grid.Row="1" Background="{DynamicResource ActivationInsetGlassBrush}" BorderBrush="#756C5D" BorderThickness="1" CornerRadius="9" Padding="8" Margin="0,0,0,8">
           <TextBlock Text="Select one or more updates below. Download and installation are always explicit actions; AMR will not silently install updates." Foreground="#C9C5BA" FontSize="10" TextWrapping="Wrap"/>
          </Border>
          <Border Grid.Row="2" Background="#B51B1D21" BorderBrush="#766D5D" BorderThickness="1" CornerRadius="12" Padding="3" ClipToBounds="True">
           <ListView Name="AMRUpdateResultsList" Background="Transparent" Foreground="#E5E0D6" BorderThickness="0" SelectionMode="Extended" MinHeight="150" ScrollViewer.VerticalScrollBarVisibility="Auto" ScrollViewer.HorizontalScrollBarVisibility="Disabled">
            <ListView.Resources>
             <Style TargetType="GridViewColumnHeader"><Setter Property="Background" Value="#403D37"/><Setter Property="Foreground" Value="#E8DCC3"/><Setter Property="BorderBrush" Value="#756C5D"/><Setter Property="BorderThickness" Value="0,0,0,1"/><Setter Property="Padding" Value="8,7"/><Setter Property="FontWeight" Value="Bold"/><Setter Property="FontSize" Value="10"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="GridViewColumnHeader"><Border x:Name="HeaderSurface" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="5" Padding="2"><ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center" Margin="6,1"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="HeaderSurface" Property="Background" Value="#484238"/><Setter TargetName="HeaderSurface" Property="BorderBrush" Value="#A58F68"/><Setter Property="Foreground" Value="#F3E8D2"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="HeaderSurface" Property="Background" Value="#51483B"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
             <Style TargetType="ListViewItem"><Setter Property="Foreground" Value="#E5E0D6"/><Setter Property="Background" Value="#25272B"/><Setter Property="BorderBrush" Value="#393B3F"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="6,5"/><Setter Property="Margin" Value="1,2"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ListViewItem"><Border x:Name="RowSurface" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="7" Padding="{TemplateBinding Padding}"><GridViewRowPresenter/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="RowSurface" Property="Background" Value="#393832"/><Setter TargetName="RowSurface" Property="BorderBrush" Value="#8F8064"/></Trigger><Trigger Property="IsSelected" Value="True"><Setter TargetName="RowSurface" Property="Background" Value="#51483B"/><Setter TargetName="RowSurface" Property="BorderBrush" Value="#B49A70"/><Setter Property="Foreground" Value="#F7F0E5"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
            </ListView.Resources>
           <ListView.View><GridView>
            <GridViewColumn Header="Update" Width="430" DisplayMemberBinding="{Binding Title}"/>
            <GridViewColumn Header="KB" Width="100" DisplayMemberBinding="{Binding KB}"/>
            <GridViewColumn Header="Size" Width="85" DisplayMemberBinding="{Binding SizeText}"/>
            <GridViewColumn Header="Downloaded" Width="95" DisplayMemberBinding="{Binding DownloadedText}"/>
           </GridView></ListView.View>
           </ListView>
          </Border>
          <Grid Grid.Row="3" Margin="0,11,0,0">
           <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
           <TextBlock Name="AMRUpdateActionStatus" Text="Ready. Background update operations are available; nothing installs without your selection." Foreground="#C9C5BA" FontSize="10" VerticalAlignment="Center" TextWrapping="Wrap" Margin="0,0,12,0"/>
           <StackPanel Grid.Column="1" Orientation="Horizontal">
            <Button Name="AMRUpdateDownloadBtn" Content="⇩  Download Selected" MinWidth="145" Height="37" Background="#365B68" Foreground="#EAF7F7" BorderBrush="#83BFC7" Margin="0,0,8,0" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
            <Button Name="AMRUpdateInstallBtn" Content="✓  Install Selected" MinWidth="135" Height="37" Background="#3D665D" Foreground="#F1F7F0" BorderBrush="#8BC9A8" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
           </StackPanel>
          </Grid>
         </Grid>
        </Border>

        <!-- Recovery footer -->
        <Border Grid.Row="4" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="13,11" Margin="0,0,0,2">
         <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <StackPanel VerticalAlignment="Center"><TextBlock Text="RECOVERY &amp; DIAGNOSTICS" Foreground="#D9BD8B" FontSize="10" FontWeight="Bold"/><TextBlock Text="Profile backups are saved locally before policy changes. Repair actions are explicit and logged." Foreground="#B7B5AE" FontSize="10" TextWrapping="Wrap" Margin="0,3,10,0"/></StackPanel>
          <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
           <Button Name="AMRUpdateRestoreBackupBtn" Content="↶  Undo Last Profile" MinWidth="142" Height="36" Margin="0,0,8,0" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
           <Button Name="AMRUpdateRepairBtn" Content="⚙  Repair Update Services" MinWidth="166" Height="36" Background="#604C3B" Foreground="#FFF2E4" BorderBrush="#B99A62" Style="{StaticResource AMRUpdateGlassButtonStyle}"/>
          </StackPanel>
         </Grid>
        </Border>
       </Grid>
      </ScrollViewer>
     </TabItem>
     <TabItem Header="Backups">
      <Border BorderThickness="0" Background="Transparent" Padding="0" Margin="0">
       <Grid>
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <TabControl Name="BackupSubTabs" Grid.Row="1" Background="Transparent" BorderThickness="0">
         <TabControl.Template>
          <ControlTemplate TargetType="{x:Type TabControl}">
           <Grid ClipToBounds="True" KeyboardNavigation.TabNavigation="Local">
            <Border Background="Transparent" BorderThickness="0">
             <ContentPresenter x:Name="PART_SelectedContentHost" ContentSource="SelectedContent" HorizontalAlignment="Stretch" VerticalAlignment="Stretch" SnapsToDevicePixels="{TemplateBinding SnapsToDevicePixels}"/>
            </Border>
           </Grid>
          </ControlTemplate>
         </TabControl.Template>
       <TabItem Header="Driver Backup" MinWidth="184" Height="34" Padding="14,4" FontSize="12" FontWeight="SemiBold" Background="#252B28" Foreground="#E9EEE9" BorderBrush="#789987">
        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" VerticalContentAlignment="Top" HorizontalContentAlignment="Stretch" Background="#17191D" Padding="18,16,18,22">
         <StackPanel Name="DriverBackupRoot" VerticalAlignment="Top" Margin="0" Opacity="0">
          <StackPanel.RenderTransform><TranslateTransform Y="8"/></StackPanel.RenderTransform>
          <StackPanel.Triggers>
           <EventTrigger RoutedEvent="FrameworkElement.Loaded">
            <BeginStoryboard>
             <Storyboard>
              <DoubleAnimation Storyboard.TargetProperty="Opacity" From="0" To="1" Duration="0:0:0.24"/>
              <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="8" To="0" Duration="0:0:0.24" DecelerationRatio="0.86"/>
             </Storyboard>
            </BeginStoryboard>
           </EventTrigger>
          </StackPanel.Triggers>
          <Border Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="16" Padding="22,17" Margin="0,0,0,12"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="16" ShadowDepth="4" Opacity="0.28"/></Border.Effect>
           <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <StackPanel Grid.Column="0" VerticalAlignment="Center">
             <TextBlock Text="DRIVER BACKUP" FontSize="26" FontWeight="Bold" Foreground="#E9D8B5" Margin="0,0,0,6"/>
             <Border Width="48" Height="2" CornerRadius="1" HorizontalAlignment="Left" Margin="0,0,0,9" Background="#D8B56D"/>
             <TextBlock Text="Create a Windows recovery checkpoint before driver changes, then return to that exact checkpoint when needed." Foreground="#CFCABF" FontSize="12" TextWrapping="Wrap" MaxWidth="760"/>
            </StackPanel>
            <Button Name="DriverRecoveryCenterBtn" Grid.Column="1" Cursor="Hand" VerticalAlignment="Center" Margin="18,0,0,0" FocusVisualStyle="{x:Null}" ToolTip="Show your AMR restore point and open Windows System Restore">
             <Button.Template>
              <ControlTemplate TargetType="{x:Type Button}">
               <Border x:Name="RcFace" Background="{DynamicResource ActivationInsetGlassBrush}" BorderBrush="#99B89A62" BorderThickness="1" CornerRadius="18" Padding="12,7" RenderTransformOrigin="0.5,0.5">
                <Border.RenderTransform><ScaleTransform x:Name="RcScale" ScaleX="1" ScaleY="1"/></Border.RenderTransform>
                <TextBlock x:Name="RcText" Text="RECOVERY CENTER" Foreground="#E2C68E" FontSize="10" FontWeight="Bold"/>
               </Border>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="RcFace" Property="BorderBrush" Value="#F0D9A0"/>
                 <Setter TargetName="RcText" Property="Foreground" Value="#FFF1D0"/>
                 <Setter TargetName="RcFace" Property="Effect"><Setter.Value><DropShadowEffect Color="#D8B56D" BlurRadius="14" ShadowDepth="0" Opacity="0.55"/></Setter.Value></Setter>
                 <Trigger.EnterActions><BeginStoryboard x:Name="RcIn"><Storyboard><DoubleAnimation Storyboard.TargetName="RcScale" Storyboard.TargetProperty="ScaleX" To="1.05" Duration="0:0:0.13"/><DoubleAnimation Storyboard.TargetName="RcScale" Storyboard.TargetProperty="ScaleY" To="1.05" Duration="0:0:0.13"/></Storyboard></BeginStoryboard></Trigger.EnterActions>
                 <Trigger.ExitActions><RemoveStoryboard BeginStoryboardName="RcIn"/><BeginStoryboard><Storyboard><DoubleAnimation Storyboard.TargetName="RcScale" Storyboard.TargetProperty="ScaleX" From="1.05" To="1" Duration="0:0:0.15"/><DoubleAnimation Storyboard.TargetName="RcScale" Storyboard.TargetProperty="ScaleY" From="1.05" To="1" Duration="0:0:0.15"/></Storyboard></BeginStoryboard></Trigger.ExitActions>
                </Trigger>
                <Trigger Property="IsPressed" Value="True">
                 <Trigger.EnterActions><BeginStoryboard x:Name="RcPress"><Storyboard><DoubleAnimation Storyboard.TargetName="RcScale" Storyboard.TargetProperty="ScaleX" To="0.96" Duration="0:0:0.07"/><DoubleAnimation Storyboard.TargetName="RcScale" Storyboard.TargetProperty="ScaleY" To="0.96" Duration="0:0:0.07"/></Storyboard></BeginStoryboard></Trigger.EnterActions>
                 <Trigger.ExitActions><RemoveStoryboard BeginStoryboardName="RcPress"/></Trigger.ExitActions>
                </Trigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Button.Template>
            </Button>
           </Grid>
          </Border>
          <Grid Margin="0,0,0,12">
           <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
           <Border Grid.Column="0" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="15" Padding="20" Margin="0,0,7,0"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="16" ShadowDepth="4" Opacity="0.28"/></Border.Effect>
            <StackPanel>
             <TextBlock Text="01  ·  CREATE A CHECKPOINT" FontSize="10" FontWeight="Bold" Foreground="#D8B56D" Margin="0,0,0,9"/>
             <TextBlock Text="Create Restore Point" FontSize="19" FontWeight="SemiBold" Foreground="#F0F3F6" Margin="0,0,0,6"/>
             <TextBlock Text="Save the current Windows system state before changing drivers. AMR enables System Protection on the Windows drive and verifies the exact checkpoint." Foreground="#CFCABF" FontSize="11" TextWrapping="Wrap" MinHeight="48" Margin="0,0,0,15"/>
             <Button Name="DriverCreateRestorePointBtn" Content="＋  Smart Create" Style="{StaticResource AMRUpdateGlassButtonStyle}" Height="42" MinWidth="185" HorizontalAlignment="Left" Background="#D93B382F" Foreground="#EDE2C9" BorderBrush="#9C865A" Padding="17,8" FontSize="12" FontWeight="Bold" Cursor="Hand" ToolTip="Enable System Protection, request a Windows restore point, and verify a new or explicitly reused checkpoint"/>
            </StackPanel>
           </Border>
           <Border Grid.Column="1" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="15" Padding="20" Margin="7,0,0,0"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="16" ShadowDepth="4" Opacity="0.28"/></Border.Effect>
            <StackPanel>
             <TextBlock Text="02  ·  RECOVER YOUR SYSTEM" FontSize="10" FontWeight="Bold" Foreground="#C9B27E" Margin="0,0,0,9"/>
             <TextBlock Text="Smart Restore" FontSize="19" FontWeight="SemiBold" Foreground="#F0F3F6" Margin="0,0,0,6"/>
             <TextBlock Text="Return Windows to the exact verified checkpoint saved here. If Windows blocks a new point due to its frequency limit, AMR may clearly label and reuse a recent existing checkpoint. It never silently substitutes another point." Foreground="#CFCABF" FontSize="11" TextWrapping="Wrap" MinHeight="48" Margin="0,0,0,15"/>
             <Button Name="DriverSmartRestoreBtn" IsEnabled="True" Content="↶  Smart Restore" Style="{StaticResource AMRUpdateGlassButtonStyle}" Height="42" MinWidth="185" HorizontalAlignment="Left" Padding="17,8" FontSize="12" FontWeight="Bold" Cursor="Hand" ToolTip="Restore Windows using the exact verified Windows checkpoint recorded by Driver Backup"/>
            </StackPanel>
           </Border>
          </Grid>
          <Border Name="DriverRestoreProgressPanel" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="16,13" Margin="0,0,0,12" Visibility="Collapsed">
           <StackPanel>
            <Grid Margin="0,0,0,8">
             <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
             <TextBlock Text="RESTORE POINT ACTIVITY" Foreground="#D8B56D" FontSize="10" FontWeight="Bold"/>
             <TextBlock Grid.Column="1" Text="LIVE STATUS" Foreground="#C9B27E" FontSize="9" FontWeight="Bold"/>
            </Grid>
            <Grid Margin="0,0,0,5">
             <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
             <TextBlock Text="LIVE OPERATION STAGE · WINDOWS DOES NOT REPORT A PERCENTAGE" Foreground="#C9B27E" FontSize="9" FontWeight="SemiBold"/>
             <TextBlock Name="DriverRestorePointPercent" Grid.Column="1" Text="Ready" Foreground="#E9D8B5" FontSize="10" FontWeight="Bold"/>
            </Grid>
            <ProgressBar Name="DriverRestorePointProgressBar" Height="6" IsIndeterminate="True" Minimum="0" Maximum="100" Value="0" Background="#2A2C31" Foreground="#D8B56D" BorderThickness="0"/>
            <Grid Margin="0,9,0,0">
             <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
             <TextBlock Name="DriverRestorePointProgressText" Text="Preparing Windows System Restore…" Foreground="#E1E7ED" FontSize="11" TextWrapping="Wrap"/>
             <TextBlock Name="DriverRestorePointElapsed" Grid.Column="1" Text="Elapsed 00:00" Foreground="#D9D2C2" FontSize="10" FontWeight="SemiBold" Margin="12,0,0,0" VerticalAlignment="Center"/>
             <TextBlock Name="DriverRestorePointEstimate" Grid.Column="2" Text="Waiting for Windows" Foreground="#C9B27E" FontSize="9" Margin="10,0,10,0" VerticalAlignment="Center"/>
             <Button Name="DriverRestorePointCancelBtn" Grid.Column="3" Content="Cancel" Visibility="Collapsed" IsEnabled="False" Height="28" MinWidth="72" Padding="12,3" FontSize="10" FontWeight="SemiBold" Background="#3B3032" Foreground="#F0DADB" BorderBrush="#805B60" BorderThickness="1" Cursor="Hand" ToolTip="Stop the AMR worker. Windows may still finish a native System Restore request already accepted."/>
            </Grid>
           </StackPanel>
          </Border>
          <Border Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="16,14" Margin="0,0,0,10">
           <StackPanel>
            <TextBlock Text="DRIVER SAFETY POINT" FontSize="12" FontWeight="Bold" Foreground="#D8B56D" Margin="0,0,0,6"/>
            <TextBlock Text="Restore points are not created automatically during driver installation. Create one whenever you choose. Smart Restore verifies and targets the exact checkpoint saved here; it will not silently choose another restore point. Before replacing a driver, this utility also attempts to export the current OEM driver package." Foreground="#CFCABF" FontSize="11" TextWrapping="Wrap"/>
           </StackPanel>
          </Border>
          <Border Background="{DynamicResource ActivationInsetGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="11" Padding="14,12">
           <StackPanel>
            <TextBlock Text="RESTORE POINT STATUS" Foreground="#D8B56D" FontSize="10" FontWeight="Bold" Margin="0,0,0,5"/>
            <TextBlock Name="DriverRestorePointStatus" Text="Checking Windows System Protection and saved recovery point…" Foreground="#DCE3EA" FontSize="11" TextWrapping="Wrap"/>
           </StackPanel>
          </Border>
          <TextBlock Text="Windows does not expose a reliable percentage or a safe cancel operation once it begins creating a restore point. AMR displays the actual worker stage, waits for Windows to return, then verifies the exact checkpoint before Smart Restore can use it." Foreground="#929EAC" FontSize="10" TextWrapping="Wrap" Margin="2,9,2,0"/>
         </StackPanel>
        </ScrollViewer>
       </TabItem>
        </TabControl>
       </Grid>
      </Border>
     </TabItem>
      <TabItem Name="ActivationTab" Header="Activation">
       <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Background="#17191D">
        <Grid Margin="18,16,18,22">
         <Grid.RowDefinitions>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
         </Grid.RowDefinitions>
         <Border Grid.Row="0" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="15" Padding="20" Margin="0,0,0,14">
          <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="18" ShadowDepth="5" Opacity="0.34"/></Border.Effect>
          <Grid>
           <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
           <StackPanel>
            <TextBlock Text="Activation &amp; License Center" Foreground="#F1EEE7" FontSize="25" FontWeight="Bold" Margin="0,5,0,3"/>
            <TextBlock Text="Inspect Windows and Microsoft Office licensing, understand the current state, and use official Microsoft activation tools." Foreground="#B7B5AE" FontSize="11" TextWrapping="Wrap" MaxWidth="720"/>
            <ProgressBar Name="ActivationScanProgress" Height="3" Margin="0,13,0,0" IsIndeterminate="True" Visibility="Collapsed" Background="#35383D" Foreground="#B89A62" BorderThickness="0"/>
           </StackPanel>
           <Button Name="ActivationRefreshBtn" Grid.Column="1" Content="↻  Refresh Status" Height="38" MinWidth="142" Padding="14,0" VerticalAlignment="Center" Margin="16,0,0,0" Background="{DynamicResource ActivationInnerGlassBrush}" Foreground="#F4EAD5" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" FontWeight="SemiBold" Cursor="Hand"/>
          </Grid>
         </Border>

         <Grid Grid.Row="1" Margin="0,0,0,14">
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
          <Border Grid.Column="0" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="17" Margin="0,0,7,0">
           <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="15" ShadowDepth="4" Opacity="0.30"/></Border.Effect>
           <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border Grid.RowSpan="2" Background="#182638" BorderBrush="#9ABFE0" BorderThickness="1" CornerRadius="12" Width="50" Height="50" VerticalAlignment="Top" Margin="0,0,13,0">
             <Border.Effect><DropShadowEffect Color="#83C9FF" BlurRadius="15" ShadowDepth="0" Opacity="0.28"/></Border.Effect>
             <Grid Width="29" Height="29">
              <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
              <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <Border Grid.Row="0" Grid.Column="0" Margin="0,0,2,2" Background="#EAF2FA"/>
              <Border Grid.Row="0" Grid.Column="1" Margin="2,0,0,2" Background="#EAF2FA"/>
              <Border Grid.Row="1" Grid.Column="0" Margin="0,2,2,0" Background="#EAF2FA"/>
              <Border Grid.Row="1" Grid.Column="1" Margin="2,2,0,0" Background="#EAF2FA"/>
             </Grid>
            </Border>
            <StackPanel Grid.Column="1">
             <TextBlock Text="WINDOWS LICENSE" Foreground="#B9A77E" FontSize="10" FontWeight="Bold"/>
             <TextBlock Name="ActivationWindowsStatus" Text="Not checked" Foreground="#F1EEE7" FontSize="21" FontWeight="Bold" Margin="0,5,0,2"/>
             <TextBlock Name="ActivationWindowsEdition" Text="Edition: —" Foreground="#D0CEC8" FontSize="11" TextWrapping="Wrap"/>
             <TextBlock Name="ActivationWindowsDetails" Text="License details will appear after inspection." Foreground="#A9A79F" FontSize="10" Margin="0,7,0,0" TextWrapping="Wrap"/>
            </StackPanel>
            <Border Grid.Row="2" Grid.ColumnSpan="2" Background="#34363A" Height="1" Margin="0,14,0,0" VerticalAlignment="Bottom"/>
           </Grid>
          </Border>
          <Border Grid.Column="1" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="17" Margin="7,0,0,0">
           <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="15" ShadowDepth="4" Opacity="0.30"/></Border.Effect>
           <Grid>
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border Grid.RowSpan="2" Background="#282638" BorderBrush="#C9C4E8" BorderThickness="1" CornerRadius="12" Width="50" Height="50" VerticalAlignment="Top" Margin="0,0,13,0">
             <Border.Effect><DropShadowEffect Color="#B9B2F2" BlurRadius="15" ShadowDepth="0" Opacity="0.24"/></Border.Effect>
             <Grid Width="29" Height="29">
              <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
              <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <Border Grid.Row="0" Grid.Column="0" Margin="0,0,2,2" Background="#EAF2FA"/>
              <Border Grid.Row="0" Grid.Column="1" Margin="2,0,0,2" Background="#EAF2FA"/>
              <Border Grid.Row="1" Grid.Column="0" Margin="0,2,2,0" Background="#EAF2FA"/>
              <Border Grid.Row="1" Grid.Column="1" Margin="2,2,0,0" Background="#EAF2FA"/>
             </Grid>
            </Border>
            <StackPanel Grid.Column="1">
             <TextBlock Text="MICROSOFT OFFICE" Foreground="#B9A77E" FontSize="10" FontWeight="Bold"/>
             <TextBlock Name="ActivationOfficeStatus" Text="Not checked" Foreground="#F1EEE7" FontSize="21" FontWeight="Bold" Margin="0,5,0,2"/>
             <TextBlock Name="ActivationOfficeEdition" Text="Product: —" Foreground="#D0CEC8" FontSize="11" TextWrapping="Wrap"/>
             <TextBlock Name="ActivationOfficeDetails" Text="Office licensing information will appear after inspection." Foreground="#A9A79F" FontSize="10" Margin="0,7,0,0" TextWrapping="Wrap"/>
            </StackPanel>
            <Border Grid.Row="2" Grid.ColumnSpan="2" Background="#34363A" Height="1" Margin="0,14,0,0" VerticalAlignment="Bottom"/>
           </Grid>
          </Border>
         </Grid>

         <Border Grid.Row="2" Background="{DynamicResource ActivationOuterGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="16" Margin="0,0,0,14">
          <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="14" ShadowDepth="4" Opacity="0.27"/></Border.Effect>
          <StackPanel>
           <Grid Margin="0,0,0,10">
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <StackPanel>
             <TextBlock Text="LICENSE DIAGNOSTICS" Foreground="#D0B77F" FontSize="11" FontWeight="Bold"/>
             <TextBlock Text="Read-only inspection report" Foreground="#A9A79F" FontSize="10" Margin="0,3,0,0"/>
            </StackPanel>
            <TextBlock Name="ActivationLastScan" Grid.Column="1" Text="Last inspection: not yet run" Foreground="#AAA69B" FontSize="10" VerticalAlignment="Center" TextWrapping="Wrap" Margin="0,0,9,0"/>
            <Button Name="ActivationCopyDiagnosticsIconBtn" Grid.Column="2" Content="⧉" Width="30" Height="28" Padding="0" Background="{DynamicResource ActivationInnerGlassBrush}" Foreground="#E8D8B5" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" FontSize="16" FontWeight="SemiBold" Cursor="Hand" ToolTip="Copy the license diagnostic report"/>
           </Grid>
           <Border Background="{DynamicResource ActivationInsetGlassBrush}" BorderBrush="#686052" BorderThickness="1" CornerRadius="9" Padding="11">
            <TextBox Name="ActivationDiagnostics" Text="Select Refresh Status to inspect the installed licensing records." IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" MinHeight="125" MaxHeight="245" Background="Transparent" Foreground="#D8D5CD" BorderThickness="0" FontFamily="Consolas" FontSize="10" Padding="2"/>
           </Border>
          </StackPanel>
         </Border>

         <Border Grid.Row="3" Background="{DynamicResource ActivationInnerGlassBrush}" BorderBrush="{DynamicResource ActivationGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="16" Margin="0,0,0,14">
          <Border.Effect><DropShadowEffect Color="#000000" BlurRadius="14" ShadowDepth="4" Opacity="0.27"/></Border.Effect>
          <StackPanel>
           <TextBlock Text="OFFICIAL MICROSOFT ACTIONS" Foreground="#D0B77F" FontSize="11" FontWeight="Bold" Margin="0,0,0,11"/>
           <WrapPanel>
            <Button Name="ActivationWindowsActivateBtn" Content="Activate Windows" Height="36" Padding="15,0" Margin="0,0,8,8" Background="#3B382F" Foreground="#EDE2C9" BorderBrush="#9C865A" FontWeight="SemiBold" Cursor="Hand" ToolTip="Runs Microsoft's built-in online activation request for an installed genuine license."/>
            <Button Name="ActivationOfficeActivateBtn" Content="Activate Office" Height="36" Padding="15,0" Margin="0,0,8,8" Background="#3B382F" Foreground="#EDE2C9" BorderBrush="#9C865A" FontWeight="SemiBold" Cursor="Hand" ToolTip="Runs the installed Office licensing script's official activation command."/>
            <Button Name="ActivationOpenSettingsBtn" Content="Windows Activation Settings" Height="34" Padding="13,0" Margin="0,0,8,8" Background="#34373B" Foreground="#D8D5CD" BorderBrush="#595B5E" Cursor="Hand"/>
            <Button Name="ActivationOpenSluiBtn" Content="Windows License UI" Height="34" Padding="13,0" Margin="0,0,8,8" Background="#34373B" Foreground="#D8D5CD" BorderBrush="#595B5E" Cursor="Hand"/>
            <Button Name="ActivationOpenOfficeBtn" Content="Open Office Apps" Height="34" Padding="13,0" Margin="0,0,8,8" Background="#34373B" Foreground="#D8D5CD" BorderBrush="#595B5E" Cursor="Hand"/>
            <Button Name="ActivationCopyReportBtn" Content="Copy Report" Height="34" Padding="13,0" Margin="0,0,8,8" Background="#34373B" Foreground="#D8D5CD" BorderBrush="#595B5E" Cursor="Hand"/>
            <Button Name="ActivationExportReportBtn" Content="Export Report" Height="34" Padding="13,0" Margin="0,0,8,8" Background="#34373B" Foreground="#D8D5CD" BorderBrush="#595B5E" Cursor="Hand"/>
           </WrapPanel>
           <TextBlock Name="ActivationTaskStatus" Text="Ready. Activation actions use Microsoft's installed licensing components and require a valid license." Foreground="#AAA69B" FontSize="10" TextWrapping="Wrap" Margin="0,4,0,0"/>
           <TextBlock Text="KMS configuration is inspected for diagnostics only. No third-party activation, emulation, unauthorized KMS activation, or license-store modification is performed." Foreground="#89877F" FontSize="10" TextWrapping="Wrap" Margin="0,5,0,0"/>
          </StackPanel>
         </Border>
         <TextBlock Grid.Row="4" Text="AMR LICENSE CENTER  •  READ-ONLY DIAGNOSTICS  •  MICROSOFT OFFICIAL ACTIVATION" Foreground="#77756F" FontSize="9" Margin="3,0,0,0"/>
        </Grid>
       </ScrollViewer>
      </TabItem>
</TabControl>
    </Grid>
   </TabItem>
<TabItem Header="Software" IsSelected="True">
    <Border Padding="10,0,10,4">
     <Grid>
      <Grid.RowDefinitions>
       <RowDefinition Height="Auto"/>
       <RowDefinition Height="*"/>
      </Grid.RowDefinitions>
      
      <Grid Grid.Row="0" Margin="0,2,0,4">
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="175"/>
       </Grid.ColumnDefinitions>
       <StackPanel Grid.Column="0" VerticalAlignment="Center">
        <TextBlock Text="Software Catalog" FontSize="22" FontWeight="Bold" Foreground="#FFFFFF"/>
       </StackPanel>

       <Grid Grid.Column="1" VerticalAlignment="Center">
        <Grid.ColumnDefinitions>
         <ColumnDefinition Width="0"/>
         <ColumnDefinition Width="175"/>
        </Grid.ColumnDefinitions>
        <TextBox Name="SearchBox" Grid.Column="0" Height="42" Margin="0,0,8,0" VerticalAlignment="Center" FontSize="15" ToolTip="Search by name or ID..." Visibility="Collapsed"/>
        <TextBlock Visibility="Collapsed" Grid.Column="0" Text="🔍 Search name or ID..." IsHitTestVisible="False" VerticalAlignment="Center" Margin="15,0,0,0" Foreground="#71717A" FontSize="14">
         <TextBlock.Style>
          <Style TargetType="TextBlock">
           <Setter Property="Visibility" Value="Hidden"/>
           <Style.Triggers>
            <DataTrigger Binding="{Binding Text.Length, ElementName=SearchBox}" Value="0">
             <Setter Property="Visibility" Value="Visible"/>
            </DataTrigger>
           </Style.Triggers>
          </Style>
         </TextBlock.Style>
        </TextBlock>
        <Button Name="ShowInstalledBtn" Grid.Column="1" HorizontalAlignment="Right" Height="36" VerticalAlignment="Center" Padding="12,0" FontSize="12" FontWeight="SemiBold" Cursor="Hand" Content="Show Installed" ToolTip="Show only applications detected as installed on this PC." Background="#263B3A" Foreground="#A7D8CE" BorderBrush="#456B65" BorderThickness="1"/>
       </Grid>
      </Grid>
      
      <Grid Grid.Row="1" Margin="0,0,0,4">
       <!-- Catalog spans behind the bottom glass console; Categories stop at its top edge. -->
       <Grid.RowDefinitions>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
       </Grid.RowDefinitions>
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="205"/>
       </Grid.ColumnDefinitions>
       <Border Grid.Row="0" Grid.Column="1" VerticalAlignment="Stretch" Margin="12,5,0,5" Background="#281A2634"
               BorderBrush="#36516A" BorderThickness="1" CornerRadius="10" Padding="10">
        <DockPanel LastChildFill="True">
         <TextBlock DockPanel.Dock="Top" Text="CATEGORIES" FontSize="11"
                    FontWeight="Bold" Foreground="#8FB8E8" Margin="5,3,5,10"/>
         <ListBox Name="SoftwareCategoryList"
                  Background="Transparent" BorderThickness="0" Foreground="#DCE8F7"
                  ScrollViewer.HorizontalScrollBarVisibility="Disabled"
                  ScrollViewer.VerticalScrollBarVisibility="Hidden"
                  SelectionMode="Single">
          <ListBox.ItemsPanel>
           <ItemsPanelTemplate><StackPanel Orientation="Vertical"/></ItemsPanelTemplate>
          </ListBox.ItemsPanel>
          <ListBox.Resources>
           <Style TargetType="ListBoxItem">
            <Setter Property="Foreground" Value="#C9D8EA"/>
            <Setter Property="Background" Value="#3826364B"/>
            <Setter Property="Padding" Value="7,6"/>
            <Setter Property="Height" Value="38"/>
            <Setter Property="Margin" Value="0,0,0,8"/>
            <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="Template">
             <Setter.Value>
              <ControlTemplate TargetType="ListBoxItem">
               <Border Name="CategoryTileBorder" Background="{TemplateBinding Background}"
                       BorderBrush="#3B526F" BorderThickness="1" CornerRadius="7"
                       Padding="{TemplateBinding Padding}">
                <ContentPresenter HorizontalAlignment="Stretch" VerticalAlignment="Center"/>
               </Border>
               <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                 <Setter TargetName="CategoryTileBorder" Property="Background" Value="#58304A6B"/>
                 <Setter TargetName="CategoryTileBorder" Property="BorderBrush" Value="#527AA8"/>
                 <Setter Property="Foreground" Value="#EAF2FF"/>
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                 <Setter TargetName="CategoryTileBorder" Property="Background" Value="#24558A"/>
                 <Setter TargetName="CategoryTileBorder" Property="BorderBrush" Value="#5B9BE0"/>
                 <Setter Property="Foreground" Value="#FFFFFF"/>
                 <Setter Property="FontWeight" Value="SemiBold"/>
                </Trigger>
               </ControlTemplate.Triggers>
              </ControlTemplate>
             </Setter.Value>
            </Setter>
           </Style>
          </ListBox.Resources>
         </ListBox>
        </DockPanel>
       </Border>

       <!-- Reserve the vertical scrollbar gutter permanently: Auto can change the viewport width
             when a filtered/short page crosses the scroll threshold, which changes card widths. -->
        <ScrollViewer x:Name="SoftwareScrollViewer" Grid.Row="0" Grid.Column="0" FlowDirection="RightToLeft" VerticalScrollBarVisibility="Visible" HorizontalScrollBarVisibility="Disabled" CanContentScroll="False" Background="Transparent" Padding="0" Margin="-5,0,0,0">
        <ItemsControl Name="SoftwareGrid" FlowDirection="LeftToRight" Margin="0,2,0,0" Background="Transparent">
         <ItemsControl.ItemsPanel>
          <ItemsPanelTemplate><UniformGrid Columns="4"/></ItemsPanelTemplate>
         </ItemsControl.ItemsPanel>
        <ItemsControl.ItemTemplate>
         <DataTemplate>
          <!-- Fixed item-slot geometry prevents category-header visibility and progressive
               page appends from changing UniformGrid's measured row height. -->
          <Grid Height="76" HorizontalAlignment="Stretch" VerticalAlignment="Stretch">
           <Grid.RowDefinitions><RowDefinition Height="12"/><RowDefinition Height="64"/></Grid.RowDefinitions>
           <Grid.Style>
            <Style TargetType="Grid">
             <Style.Triggers>
              <DataTrigger Binding="{Binding IsCategorySpacer}" Value="True"><Setter Property="Visibility" Value="Hidden"/></DataTrigger>
             </Style.Triggers>
            </Style>
           </Grid.Style>
           <StackPanel Grid.Row="0" Orientation="Horizontal" HorizontalAlignment="Left" Width="34" Height="12" FlowDirection="LeftToRight" Margin="3,0,0,0">
            <StackPanel.Style>
             <Style TargetType="StackPanel">
              <Setter Property="Visibility" Value="Collapsed"/>
              <Style.Triggers>
               <!-- Reserve the same header-row height across all columns so cards stay aligned. -->
               <DataTrigger Binding="{Binding IsCategoryHeaderRow}" Value="True"><Setter Property="Visibility" Value="Hidden"/></DataTrigger>
               <DataTrigger Binding="{Binding IsCategoryStart}" Value="True"><Setter Property="Visibility" Value="Visible"/></DataTrigger>
              </Style.Triggers>
             </Style>
            </StackPanel.Style>
            <Border Width="12" Height="2" CornerRadius="1" Background="#3B6FB8" VerticalAlignment="Center" Margin="0,0,5,0"/>
            <TextBlock Text="{Binding CategoryNumber}" Foreground="#7E9CBE" FontSize="9.5" FontWeight="SemiBold" VerticalAlignment="Center" Margin="0,0,0,0"/>
           </StackPanel>
          <!-- Static shadow layer (no Effect): cheap to render and to scroll. -->
          <Border Grid.Row="1" IsHitTestVisible="False" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" Height="63" Margin="2.5,0.5" CornerRadius="10.5" Background="#000000" Opacity="0.09"/>
          <!-- Static shadow layer (no Effect): cheap to render and to scroll. -->
          <Border Grid.Row="1" IsHitTestVisible="False" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" Height="66" Margin="1,-1" CornerRadius="12" Background="#000000" Opacity="0.06"/>
          <!-- Static shadow layer (no Effect): cheap to render and to scroll. -->
          <Border Grid.Row="1" IsHitTestVisible="False" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" Height="69" Margin="-0.5,-2.5" CornerRadius="13.5" Background="#000000" Opacity="0.035"/>
          <Border x:Name="SoftwareCardSurface" Grid.Row="1" Background="#FF222226" BorderBrush="#FF38383F" BorderThickness="1" CornerRadius="9" HorizontalAlignment="Stretch" VerticalAlignment="Bottom" RenderTransformOrigin="0.5,0.5">
           <Border.Style>
            <Style TargetType="Border">
             <Setter Property="Height" Value="60"/>
             <Setter Property="Padding" Value="5,3"/>
             <Setter Property="Margin" Value="4,2"/>
             <Setter Property="RenderTransform">
              <Setter.Value><TransformGroup><ScaleTransform ScaleX="1" ScaleY="1"/><TranslateTransform X="0" Y="0"/></TransformGroup></Setter.Value>
             </Setter>
             <Style.Triggers>
              <MultiTrigger><MultiTrigger.Conditions><Condition Property="IsMouseOver" Value="True"/><Condition Property="IsVisible" Value="True"/></MultiTrigger.Conditions>
               <MultiTrigger.EnterActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF31353B" Duration="0:0:0.16">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FFFFE0AD" Duration="0:0:0.18">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="-3" Duration="0:0:0.16">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1.025" Duration="0:0:0.16">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1.025" Duration="0:0:0.16">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                 </Storyboard>
                </BeginStoryboard>
               </MultiTrigger.EnterActions>
               <MultiTrigger.ExitActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF222226" Duration="0:0:0.21">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FF38383F" Duration="0:0:0.21">
                   <ColorAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></ColorAnimation.EasingFunction>
                  </ColorAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="0" Duration="0:0:0.21">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.21">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                  <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.21">
                   <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                  </DoubleAnimation>
                 </Storyboard>
                </BeginStoryboard>
               </MultiTrigger.ExitActions>
              </MultiTrigger>
              <DataTrigger Binding="{Binding IsSelected}" Value="True">
               <Setter Property="Background" Value="#FF262E38"/>
               <Setter Property="BorderBrush" Value="#FFD7B77C"/>
               <Setter Property="BorderThickness" Value="1.4"/>
               </DataTrigger>
              <!-- A13g: the selection fade starts only once the card is in the visual tree (IsVisible). Starting a Storyboard on Border.Background while the template was still being built threw XamlParseException. -->
              <MultiDataTrigger><MultiDataTrigger.Conditions><Condition Binding="{Binding IsSelected}" Value="True"/><Condition Binding="{Binding RelativeSource={RelativeSource Self},Path=IsVisible}" Value="True"/></MultiDataTrigger.Conditions><MultiDataTrigger.EnterActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF2A3340" Duration="0:0:0.18"/>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FFFFDFA8" Duration="0:0:0.20"/>
                 </Storyboard>
                </BeginStoryboard>
               </MultiDataTrigger.EnterActions><MultiDataTrigger.ExitActions>
                <BeginStoryboard>
                 <Storyboard>
                  <ColorAnimation Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)" To="#FF222226" Duration="0:0:0.16"/>
                  <ColorAnimation Storyboard.TargetProperty="(Border.BorderBrush).(SolidColorBrush.Color)" To="#FF38383F" Duration="0:0:0.16"/>
                 </Storyboard>
                </BeginStoryboard>
               </MultiDataTrigger.ExitActions></MultiDataTrigger>
             </Style.Triggers>
            </Style>
           </Border.Style>
           <Grid>
            <Grid.RowDefinitions><RowDefinition Height="*"/></Grid.RowDefinitions>
            <Border IsHitTestVisible="False" Grid.Row="0" Margin="-5,-3" CornerRadius="8" BorderThickness="1" Background="{StaticResource AMRSoftCardGlowBrush}" BorderBrush="{StaticResource AMRSoftCardHairBrush}"/>
            <Grid Grid.Row="0" VerticalAlignment="Center">
             <Grid.ColumnDefinitions>
              <ColumnDefinition Width="Auto"/>
              <ColumnDefinition Width="Auto"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="Auto"/>
             </Grid.ColumnDefinitions>
             <CheckBox IsChecked="{Binding IsSelected, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}"
                       VerticalAlignment="Center" HorizontalAlignment="Center" Margin="0,0,12,0"
                       ToolTip="Select this application" Cursor="Hand" FocusVisualStyle="{x:Null}"
                       Width="19" Height="19" VerticalContentAlignment="Center" HorizontalContentAlignment="Center">
              <CheckBox.Template>
               <ControlTemplate TargetType="CheckBox">
                <Border x:Name="SelectionSurface" Width="18" Height="18" CornerRadius="5"
                        Background="#FF1C222A" BorderBrush="#FF5B6573" BorderThickness="1.2"
                        SnapsToDevicePixels="True">
                 <Grid>
                  <Path x:Name="SelectionTick" RenderTransformOrigin="0.5,0.5" Data="M 3,9 L 7,13 L 15,4"
                        Stroke="#FFFFFFFF" StrokeThickness="2.0" StrokeStartLineCap="Round"
                        StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"
                        HorizontalAlignment="Center" VerticalAlignment="Center"/>
                 </Grid>
                </Border>
                <ControlTemplate.Triggers>
                 <Trigger Property="IsMouseOver" Value="True">
                  <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FFE0AD"/>
                  <Setter TargetName="SelectionSurface" Property="Background" Value="#FF2C3641"/>
                 </Trigger>
                 <Trigger Property="IsChecked" Value="True">
                  <Setter TargetName="SelectionSurface" Property="Background" Value="#FFB88D4D"/>
                  <Setter TargetName="SelectionSurface" Property="BorderBrush" Value="#FFFFE0AD"/>
                  <Setter TargetName="SelectionTick" Property="Visibility" Value="Visible"/>
                 </Trigger>
                 <Trigger Property="IsEnabled" Value="False">
                  <Setter TargetName="SelectionSurface" Property="Opacity" Value="0.45"/>
                 </Trigger>
                </ControlTemplate.Triggers>
               </ControlTemplate>
              </CheckBox.Template>
             </CheckBox>
             <Grid Grid.Column="1" Width="36" Height="36" Margin="0,0,8,0">
              <Border Background="{StaticResource AMRSoftTileBrush}" BorderBrush="{StaticResource AMRSoftTileEdgeBrush}" BorderThickness="1" CornerRadius="9"/>
              <TextBlock x:Name="SoftwareIconInitials" Text="{Binding Initials}" Foreground="#A1A1AA" FontSize="16" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center">
               <TextBlock.Style>
                <Style TargetType="TextBlock">
                 <Setter Property="Visibility" Value="Collapsed"/>
                 <Style.Triggers>
                  <DataTrigger Binding="{Binding Icon}" Value="{x:Null}"><Setter Property="Visibility" Value="Visible"/></DataTrigger>
                 </Style.Triggers>
                </Style>
               </TextBlock.Style>
              </TextBlock>
              <Image x:Name="SoftwareIconImage" Source="{Binding Icon, Mode=OneWay, TargetNullValue={x:Null}, FallbackValue={x:Null}}" Width="30" Height="30" Stretch="Uniform" HorizontalAlignment="Center" VerticalAlignment="Center" SnapsToDevicePixels="True" RenderOptions.BitmapScalingMode="LowQuality"/>
             </Grid>
             <StackPanel Grid.Column="2" VerticalAlignment="Center">
              <TextBlock x:Name="SoftwareNameText" Text="{Binding Name}" FontSize="14" FontWeight="SemiBold" Foreground="#FFFFFF" TextWrapping="Wrap">
              </TextBlock>
              <TextBlock Text="{Binding Id}" FontSize="10" Foreground="#71717A" TextWrapping="Wrap" Margin="0,3,0,0">
              </TextBlock>
             </StackPanel>
            </Grid>
            <Border Width="8" Height="8" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,1,2,0"
                    Background="#3B82F6" CornerRadius="4" ToolTip="This app is installed"
                    SnapsToDevicePixels="True">
             <Border.Style>
              <Style TargetType="Border">
               <Setter Property="Visibility" Value="Collapsed"/>
               <Style.Triggers>
                <DataTrigger Binding="{Binding IsInstalled}" Value="True">
                 <Setter Property="Visibility" Value="Visible"/>
                </DataTrigger>
               </Style.Triggers>
              </Style>
             </Border.Style>
            </Border>
           </Grid>
          </Border>
          </Grid>
         </DataTemplate>
        </ItemsControl.ItemTemplate>
        </ItemsControl>
       </ScrollViewer>
      <!-- App Console Bottom Bar | translucent glass overlay above the catalog -->
       <Border Name="AppManagementConsole" Grid.Row="1" Grid.ColumnSpan="2" VerticalAlignment="Stretch" BorderThickness="1" CornerRadius="16" Padding="14,10,14,10" Margin="0,0,0,5" SnapsToDevicePixels="True">
       <Border.Background>
        <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
         <GradientStop Color="#7D2D4058" Offset="0"/>
         <GradientStop Color="#70202F45" Offset="0.48"/>
         <GradientStop Color="#802A4562" Offset="1"/>
        </LinearGradientBrush>
       </Border.Background>
       <Border.BorderBrush>
        <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
         <GradientStop Color="#C9EAF6FF" Offset="0"/>
         <GradientStop Color="#668DB8D8" Offset="0.48"/>
         <GradientStop Color="#A6C5E4F5" Offset="1"/>
        </LinearGradientBrush>
       </Border.BorderBrush>
       <Border.Effect>
        <DropShadowEffect Color="#FF75B8E8" BlurRadius="28" ShadowDepth="2" Direction="270" Opacity="0.34"/>
       </Border.Effect>
       <Grid>
        <Grid.RowDefinitions>
         <RowDefinition Height="Auto"/>
         <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        
        <Grid Grid.Row="0">
         <Grid.ColumnDefinitions>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="Auto"/>
         </Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0" VerticalAlignment="Center">
          <TextBlock Text="App Management Console" Foreground="#FFFFFF" FontSize="16" FontWeight="Bold"/>
          <TextBlock Name="ProgressText" Text="Ready to process selected apps." Foreground="#10B981" FontSize="13" Margin="0,4,0,0" FontWeight="SemiBold"/>
         </StackPanel>
         <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right">
          <Button Name="DeselectAllBtn" Content="Cancel Selection" Background="#302D4964" Foreground="#EAF6FF" BorderBrush="#B8D9F2FF" BorderThickness="1" Padding="9,5" FontSize="12" FontWeight="SemiBold" Margin="0,0,10,0"/>
          <Button Name="RepairSelectedBtn" Content="🔧 Repair" Background="#EAB308" Foreground="#18181B" BorderThickness="0" Padding="10,6" FontSize="12" FontWeight="Bold" Margin="0,0,8,0"/>
          <Button Name="UninstallSelectedBtn" Content="🗑 Uninstall" Visibility="Collapsed" Background="#DC2626" Foreground="#FFFFFF" BorderBrush="#F87171" BorderThickness="1" Padding="10,6" FontSize="12" FontWeight="Bold" Margin="0,0,10,0" ToolTip="Safely uninstall selected installed applications."/>
          <Button Name="UpdateSelectedBtn" Content="⬆ Update" Background="#3B82F6" Foreground="#FFFFFF" BorderThickness="0" Padding="10,6" FontSize="12" FontWeight="Bold" Margin="0,0,8,0"/>
          <Button Name="InstallInteractiveBtn" Content="🖥 Interactive Install" Background="#8B5CF6" Foreground="#FFFFFF" BorderThickness="0" Padding="11,7" FontSize="12" FontWeight="Bold" Margin="0,0,8,0"/>
          <Button Name="InstallSelectedBtn" Content="⬇ Smart Install" Background="#10B981" Foreground="#FFFFFF" BorderThickness="0" Padding="13,7" FontSize="12" FontWeight="Bold"/>
         </StackPanel>
        </Grid>
        
        <!-- Live Progress Bar -->
        <ProgressBar Name="InstallProgressBar" Grid.Row="1" Height="8" Minimum="0" Maximum="100" Value="0" Background="#263447" Foreground="#54D6A0" Margin="0,7,0,0" BorderBrush="#8FB8D6" BorderThickness="0.7"/>
       </Grid>
      </Border>
     </Grid>
     </Grid>
    </Border>
   </TabItem>
<TabItem Header="Tool Kit">
    <Grid Margin="0,0,0,0">
<TabControl Name="ToolKitSubTabs" Tag="TOOLKIT" SelectedIndex="0" Style="{StaticResource ToolkitSubTabControlStyle}" TabStripPlacement="Right" ItemContainerStyle="{StaticResource ToolkitSubTabItemStyle}" Background="#18181B" BorderThickness="0" Margin="0,0,0,0">
      
<TabItem Header="Tweaks" IsSelected="True">
<ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="8,0,4,8">
      <StackPanel Name="BasicTweaksPanel"><StackPanel.Resources><Style TargetType="CheckBox" BasedOn="{StaticResource AMRTweakCheckStyle}"/></StackPanel.Resources>
       <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="13" Padding="13,11" Margin="0,8,0,12">
        <StackPanel>
         <TextBlock Text="Windows Tweaks" FontSize="17" FontWeight="SemiBold" Foreground="#E5F1FF"/>
         <TextBlock Text="Choose a preset to pre-select options. Nothing runs until you press Apply." Foreground="#B8CDE4" FontSize="11" TextWrapping="Wrap" Margin="0,3,0,8"/>
         <UniformGrid Columns="4" Margin="0,0,0,10">
          <Button Name="BasicPresetEssentialBtn" Content="Essential" Background="#2F6DAF" Foreground="#F2F8FF" BorderBrush="#7DB9EC" BorderThickness="1.0" Padding="7,7" Margin="3" FontWeight="Bold" ToolTip="Select everyday privacy and convenience options"/>
          <Button Name="BasicPresetMinimalBtn" Content="Minimal" Background="#46566B" Foreground="#F1F5F9" BorderBrush="#8999AC" BorderThickness="1.2" Padding="7,7" Margin="3" FontWeight="Bold" ToolTip="Select a small, conservative set of options"/>
          <Button Name="BasicPresetMediumBtn" Content="Medium" Background="#10B981" Foreground="#FFFFFF" BorderBrush="#55D6A8" BorderThickness="1.2" Padding="7,7" Margin="3" FontWeight="Bold" ToolTip="Select a balanced set of options"/>
