 <TabItem Header="Cleanup">
     <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
      <DockPanel Grid.Row="0" Margin="0,0,0,8" LastChildFill="False">
       <TextBox Name="CleanupSearchBox" Visibility="Collapsed" Width="300" Height="34" Padding="10,4" VerticalContentAlignment="Center"
                Background="#101F35" Foreground="#EAF4FF" BorderBrush="#2874C7"
                ToolTip="Search cleanup options on this page"/>
      </DockPanel>
      <TabControl Grid.Row="1" Name="CleanupSubTabs" Tag="CLEAN UP CENTER" Style="{StaticResource CleanupSubTabControlStyle}" TabStripPlacement="Right" ItemContainerStyle="{StaticResource CleanupSubTabItemStyle}" Background="#18181B" BorderThickness="0" Margin="0,0,0,0">
      <TabItem Header="Smart" IsSelected="True">
       <Grid Margin="18,6,18,18">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0" Margin="2,0,2,5">
         <TextBlock Text="SMART CLEAN UP CENTER" FontSize="21" FontWeight="Bold" Foreground="#F4F4F5"/>
         <TextBlock Text="Review temporary files and safe-to-remove cache items to free up storage space." FontSize="11" Foreground="#A1A1AA" Margin="0,3,0,0"/>
        </StackPanel>
        <Button Name="CleanupScanBtn" Grid.Row="1" Content="⌕  Scan Now" Width="112" Height="34" Margin="0,0,2,7" HorizontalAlignment="Right"
                Background="#263B36" Foreground="#A7F3D0" BorderBrush="#36594D" FontWeight="SemiBold"/>
        <Border Grid.Row="2" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="14">
         <Grid>
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
          <Grid Grid.Row="0" Margin="0,0,0,10">
           <StackPanel>
            <TextBlock Text="SAFE CLEANUP" FontSize="14" FontWeight="SemiBold" Foreground="#E4E4E7"/>
            <TextBlock Name="CleanupScanSummary" Visibility="Collapsed" Text=""/>
           </StackPanel>
          </Grid>
          <Grid Grid.Row="1" Margin="0,0,0,8">
           <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
           <TextBlock Grid.Column="0" Text="Choose items to clean" FontSize="12" Foreground="#CBD5E1" VerticalAlignment="Center"/>
           <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right">
            <Button Name="CleanupSelectAllBtn" Content="Select All" Height="28" MinWidth="88" Margin="0,0,6,0" Padding="10,3" Background="#244B3B" Foreground="#D1FAE5" BorderBrush="#3F8B68" FontSize="10" FontWeight="SemiBold"/>
            <Button Name="CleanupCancelSelectionBtn" Content="Cancel Selection" Height="28" MinWidth="112" Padding="10,3" Background="#49313A" Foreground="#FFE4E6" BorderBrush="#8B5363" FontSize="10" FontWeight="SemiBold"/>
           </StackPanel>
          </Grid>
          <ScrollViewer Name="CleanupSmartItemsScrollViewer" Grid.Row="2" VerticalScrollBarVisibility="Auto">
           <StackPanel>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupUserTempCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="User temporary files" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Temporary files in your Windows user profile." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupUserTempInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupWindowsTempCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="Windows temporary files" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Temporary files under the Windows Temp folder." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupWindowsTempInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupUpdateCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="Windows &amp; NVIDIA update leftovers" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Windows Update downloads and old NVIDIA app update artifacts (30+ days)." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupUpdateInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupWerCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="Windows error reports" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Archived and queued Windows Error Reporting files." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupWerInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupShaderCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="GPU shader cache" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Rebuildable DirectX, NVIDIA, AMD and Intel shader caches (7+ days)." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupShaderInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupAppCacheCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="Application caches" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Recognized rebuildable caches for common browsers, chat, media, gaming and developer apps (7+ days)." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupAppCacheInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,7"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><CheckBox Name="CleanupDeliveryCheck" Style="{StaticResource AMRCleanupCheckStyle}" Content="Delivery Optimization cache" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Cached update delivery files that Windows can download again." Foreground="#CBD5E1" FontSize="11" Margin="22,3,0,0"/></StackPanel><TextBlock Name="CleanupDeliveryInfo" Grid.Column="1" Text="Not scanned" Foreground="#D1D5DB" VerticalAlignment="Center" Margin="8,0,0,0" FontSize="10"/></Grid></Border>

            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,2,0,8">
             <StackPanel>
              <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
               <StackPanel><TextBlock Text="Recycle Bin (system drive only)" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Name="CleanupRecycleBinInfo" Text="Not scanned" Foreground="#CBD5E1" FontSize="11" Margin="0,3,0,0"/></StackPanel>
               <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                <Button Name="CleanupRecycleBinRefreshBtn" Content="Refresh" Height="28" Padding="9,3" Margin="0,0,6,0" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D" FontSize="10"/>
                <Button Name="CleanupRecycleBinEmptyBtn" Content="Empty Bin" Height="28" Padding="9,3" Background="#49313A" Foreground="#FFE4E6" BorderBrush="#8B5363" FontSize="10"/>
               </StackPanel>
              </Grid>
              <TextBlock Text="Only the Windows system drive is included. Emptying requires a separate confirmation." Foreground="#A1A1AA" FontSize="10" Margin="0,5,0,0"/>
             </StackPanel>
            </Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,8">
             <StackPanel>
              <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
               <StackPanel><TextBlock Text="Crash Dumps &amp; Windows Upgrade Leftovers" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/><TextBlock Text="Read-only discovery: crash dumps, Windows.old, upgrade staging and update remnants." Foreground="#CBD5E1" FontSize="11" Margin="0,3,0,0"/></StackPanel>
               <Button Name="CleanupDiscoveryScanBtn" Grid.Column="1" Content="Inspect" Height="28" Padding="12,3" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D" FontSize="10" VerticalAlignment="Center"/>
              </Grid>
              <TextBlock Name="CleanupDiscoverySummary" Text="Not inspected" Foreground="#D1D5DB" FontSize="10" Margin="0,6,0,4"/>
              <TextBox Name="CleanupDiscoveryReport" Text="Inspection results will appear here. These findings are never included in Clean Selected." IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" MaxHeight="150" Background="#0B1220" Foreground="#DCE7F3" BorderBrush="#40566D" FontFamily="Consolas" FontSize="10" Padding="7"/>
             </StackPanel>
            </Border>
            <Border Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="8" Padding="10" Margin="0,0,0,4">
             <StackPanel>
              <TextBlock Text="Large Files Review (read-only)" Foreground="#F1F5F9" FontSize="12" FontWeight="SemiBold"/>
              <TextBlock Text="Finds files of 512 MB or larger in common folders on the system drive. Review manually; no delete action is provided." Foreground="#CBD5E1" FontSize="11" Margin="0,3,0,5"/>
              <Button Name="CleanupLargeFilesScanBtn" Content="Find Large Files" Height="28" HorizontalAlignment="Left" Padding="12,3" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D" FontSize="10"/>
              <TextBlock Name="CleanupLargeFilesSummary" Text="Not inspected" Foreground="#D1D5DB" FontSize="10" Margin="0,6,0,4"/>
              <TextBox Name="CleanupLargeFilesReport" Text="Large-file findings will appear here. No files are selected for cleanup." IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" MaxHeight="150" Background="#0B1220" Foreground="#DCE7F3" BorderBrush="#40566D" FontFamily="Consolas" FontSize="10" Padding="7"/>
             </StackPanel>
            </Border>

           </StackPanel>
          </ScrollViewer>
          <StackPanel Grid.Row="3" Margin="0,10,0,8">
           <ProgressBar Name="CleanupProgress" Height="7" Minimum="0" Maximum="100" Value="0" Background="#292933" Foreground="#6FC6A5"/>
           <Grid Margin="0,5,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Name="CleanupProgressText" Text="Ready" Foreground="#CBD5E1" FontSize="11" TextTrimming="CharacterEllipsis"/><TextBlock Name="CleanupProgressPercent" Grid.Column="1" Text="" Visibility="Collapsed" Foreground="#8BDCC5" FontSize="12" FontWeight="Bold" Margin="10,0,0,0"/><TextBlock Name="CleanupSelectedSummary" Visibility="Collapsed" Text="Selected: 0 files • 0 MB"/></Grid>
          </StackPanel>
          <Button Name="CleanupRunBtn" Grid.Row="4" Content="Clean Selected" Height="36" HorizontalAlignment="Stretch" Background="#28483E" Foreground="#C7F9E8" BorderBrush="#416B5D" IsEnabled="False"/>
         </Grid>
        </Border>
       </Grid>
      </TabItem>
      <TabItem Header="Disk Tools">
       <Grid Margin="18">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0" Margin="2,0,2,16">
         <TextBlock Text="DISK TOOLS &amp; DIAGNOSTICS" FontSize="21" FontWeight="Bold" Foreground="#F4F4F5"/>
         <TextBlock Text="Analyze fixed drives and Windows components. Analysis is read-only unless a clearly marked repair action is selected." FontSize="12" Foreground="#A1A1AA" TextWrapping="Wrap" Margin="0,4,0,0"/>
        </StackPanel>
        <Border Grid.Row="1" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="14">
         <Grid>
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
          <StackPanel Grid.Row="0" Margin="0,0,0,12">
           <TextBlock Text="DIAGNOSTIC TOOLS" FontSize="14" FontWeight="SemiBold" Foreground="#E4E4E7" Margin="0,0,0,10"/>
           <Button Name="CleanupDriveAnalyzeBtn" Content="Analyze Drives" Height="36" Margin="0,0,0,8" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D" HorizontalContentAlignment="Left" Padding="12,0"/>
           <Button Name="CleanupComponentAnalyzeBtn" Content="Analyze Windows Components" Height="36" Margin="0,0,0,8" Background="#343044" Foreground="#DDD2F5" BorderBrush="#51466A" HorizontalContentAlignment="Left" Padding="12,0"/>
           <Button Name="CleanupComponentRunBtn" Content="Clean Component Store (DISM)" Height="36" Margin="0,0,0,12" Background="#493B2B" Foreground="#F4DFC0" BorderBrush="#70583A" Padding="12,0" IsEnabled="False"/>
          </StackPanel>
          <Grid Grid.Row="1">
           <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
           <TextBlock Grid.Row="0" Text="ANALYSIS REPORT" FontSize="11" FontWeight="SemiBold" Foreground="#A1A1AA" Margin="0,0,0,7"/>
           <TextBox Name="CleanupAdvancedReport" Grid.Row="1" Text="Advanced analysis has not been run." IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" Background="#0B1220" Foreground="#F1F5F9" BorderBrush="#526176" FontFamily="Consolas" FontSize="12" Padding="10"/>
          </Grid>
         </Grid>
        </Border>
       </Grid>
      </TabItem>
      <TabItem Header="Organizers">
       <Grid Margin="18">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0" Margin="2,0,2,14">
         <TextBlock Text="ORGANIZERS" FontSize="21" FontWeight="Bold" Foreground="#F4F4F5"/>
         <TextBlock Text="Manage drives and storage tools." FontSize="12" Foreground="#A1A1AA" TextWrapping="Wrap" Margin="0,4,0,0"/>
        </StackPanel>
        <StackPanel Grid.Row="1" Orientation="Horizontal" Margin="0,0,0,10">
         <Button Name="CleanupDiskOrganizerRefreshBtn" Content="Refresh Drives" Height="32" MinWidth="112" Margin="0,0,8,0" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D"/>
         <Button Name="CleanupDiskOrganizerOpenBtn" Content="Open Selected Drive" Height="32" MinWidth="142" Margin="0,0,8,0" Background="#263B36" Foreground="#A7F3D0" BorderBrush="#36594D"/>
         <Button Name="CleanupDiskOrganizerStorageBtn" Content="Storage Settings" Height="32" MinWidth="122" Margin="0,0,8,0" Background="#343044" Foreground="#DDD2F5" BorderBrush="#51466A"/>
         <Button Name="CleanupDiskOrganizerOptimizeBtn" Content="Optimize Drives" Height="32" MinWidth="118" Background="#493B2B" Foreground="#F4DFC0" BorderBrush="#70583A"/>
        </StackPanel>
        <Border Grid.Row="2" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="12">
         <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
          <TextBlock Grid.Row="0" Text="AVAILABLE VOLUMES" FontSize="12" FontWeight="SemiBold" Foreground="#DCE7F5" Margin="2,0,0,8"/>
          <ListBox Name="CleanupDiskOrganizerList" Grid.Row="1" Background="#0B1220" Foreground="#E5EDF7" BorderBrush="#34465B" FontFamily="Consolas" FontSize="12" Padding="8"/>
         </Grid>
        </Border>
        <TextBlock Name="CleanupDiskOrganizerStatus" Grid.Row="3" Text="Drive inventory has not been refreshed yet." Foreground="#AEB8C8" FontSize="11" Margin="2,9,0,0" TextWrapping="Wrap"/>
       </Grid>
      </TabItem>
      <TabItem Header="Web &amp; Browsers">
       <Grid Margin="18">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <Grid Grid.Row="0" Margin="2,0,2,14">
         <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
         <StackPanel Grid.Column="0" VerticalAlignment="Center">
          <TextBlock Text="WEB &amp; BROWSERS" FontSize="21" FontWeight="Bold" Foreground="#F4F4F5"/>
          <TextBlock Text="Open browser privacy and cache settings." FontSize="12" Foreground="#A1A1AA" TextWrapping="Wrap" Margin="0,4,0,0"/>
         </StackPanel>
         <Button Name="CleanupBrowserGoToScanBtn" Grid.Column="1" Content="Open Cleanup Scan" Height="34" MinWidth="150" Margin="12,0,0,0" Padding="12,0" VerticalAlignment="Center" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D" ToolTip="Open the main Clean Up scan"/>
        </Grid>
        <Border Grid.Row="1" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="14" Margin="0,0,0,10">
         <StackPanel>
          <TextBlock Text="BROWSER CLEANUP" FontSize="13" FontWeight="SemiBold" Foreground="#E4E4E7" Margin="0,0,0,9"/>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
           <ComboBox Name="CleanupBrowserChoice" Grid.Column="0" Height="34" SelectedIndex="0"
                     Background="#172536" Foreground="#E7EAF0" BorderBrush="#52647A"
                     BorderThickness="1" Padding="9,3" FontSize="12" FontWeight="SemiBold"
                     VerticalContentAlignment="Center" ToolTip="Choose a browser to open its cleanup settings">
            <ComboBox.Resources>
             <!-- Match the Smart Search All Categories selector: dark face, dark popup, champagne accent. -->
             <Style TargetType="{x:Type ComboBoxItem}">
              <Setter Property="Foreground" Value="#E7EAF0"/>
              <Setter Property="Background" Value="#101C2B"/>
              <Setter Property="Padding" Value="10,7"/>
              <Setter Property="Margin" Value="0,0,0,1"/>
              <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
              <Setter Property="VerticalContentAlignment" Value="Center"/>
              <Setter Property="BorderThickness" Value="0,0,0,1"/>
              <Setter Property="BorderBrush" Value="#26364A"/>
              <Setter Property="SnapsToDevicePixels" Value="True"/>
              <Style.Triggers>
               <Trigger Property="IsHighlighted" Value="True">
                <Setter Property="Background" Value="#26364A"/>
                <Setter Property="Foreground" Value="#E8D7B5"/>
                <Setter Property="BorderBrush" Value="#34465B"/>
               </Trigger>
               <Trigger Property="IsSelected" Value="True">
                <Setter Property="Background" Value="#29384A"/>
                <Setter Property="Foreground" Value="#D9BD8B"/>
                <Setter Property="BorderBrush" Value="#B89A62"/>
               </Trigger>
               <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Foreground" Value="#778496"/>
               </Trigger>
              </Style.Triggers>
             </Style>
             <Style TargetType="{x:Type ComboBox}">
              <Setter Property="SnapsToDevicePixels" Value="True"/>
              <Setter Property="OverridesDefaultStyle" Value="True"/>
              <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
              <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Auto"/>
              <Setter Property="Template">
               <Setter.Value>
                <ControlTemplate TargetType="{x:Type ComboBox}">
                 <Grid>
                  <ToggleButton x:Name="BrowserChoiceToggle" Focusable="False" ClickMode="Press"
                                IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                   <ToggleButton.Template>
                    <ControlTemplate TargetType="{x:Type ToggleButton}">
                     <Border x:Name="BrowserChoiceFace" Background="#172536" BorderBrush="#52647A"
                             BorderThickness="1" CornerRadius="6" Padding="9,4">
                      <Grid>
                       <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="16"/></Grid.ColumnDefinitions>
                       <ContentPresenter Grid.Column="0"
                         Content="{Binding SelectionBoxItem, RelativeSource={RelativeSource AncestorType={x:Type ComboBox}}}"
                         ContentTemplate="{Binding SelectionBoxItemTemplate, RelativeSource={RelativeSource AncestorType={x:Type ComboBox}}}"
                         TextElement.Foreground="#E7EAF0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
                       <Path Grid.Column="1" Data="M 0 0 L 4 4 L 8 0" Stroke="#B89A62"
                             StrokeThickness="1.5" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                      </Grid>
                     </Border>
                     <ControlTemplate.Triggers>
                      <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="BrowserChoiceFace" Property="BorderBrush" Value="#B89A62"/></Trigger>
                      <Trigger Property="IsPressed" Value="True"><Setter TargetName="BrowserChoiceFace" Property="Background" Value="#202F42"/></Trigger>
                     </ControlTemplate.Triggers>
                    </ControlTemplate>
                   </ToggleButton.Template>
                  </ToggleButton>
                  <Popup x:Name="PART_Popup" IsOpen="{TemplateBinding IsDropDownOpen}" Placement="Bottom"
                         AllowsTransparency="True" Focusable="False" PopupAnimation="Fade">
                   <Border Background="#101C2B" BorderBrush="#52647A" BorderThickness="1"
                           CornerRadius="7" Padding="3" SnapsToDevicePixels="True">
                    <ScrollViewer MaxHeight="300" CanContentScroll="True">
                     <ItemsPresenter KeyboardNavigation.DirectionalNavigation="Contained"/>
                    </ScrollViewer>
                   </Border>
                  </Popup>
                 </Grid>
                </ControlTemplate>
               </Setter.Value>
              </Setter>
             </Style>
            </ComboBox.Resources>
            <ComboBoxItem Content="Google Chrome" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Mozilla Firefox" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Microsoft Edge" Tag="edge://settings/clearBrowserData"/>
            <ComboBoxItem Content="Brave Browser" Tag="brave://settings/clearBrowserData"/>
            <ComboBoxItem Content="Opera" Tag="opera://settings/clearBrowserData"/>
            <ComboBoxItem Content="Opera GX" Tag="opera://settings/clearBrowserData"/>
            <ComboBoxItem Content="Vivaldi" Tag="vivaldi://settings/clearBrowserData"/>
            <ComboBoxItem Content="Tor Browser" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="LibreWolf" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Waterfox" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Pale Moon" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Chromium" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Maxthon Browser" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Falkon" Tag="falkon://settings/privacy"/>
            <ComboBoxItem Content="Avast Secure Browser" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Sidekick Browser" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Zen Browser" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Floorp Browser" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Google Chrome Beta" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Google Chrome Dev" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Mozilla Firefox Developer Edition" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="Microsoft Edge Beta" Tag="edge://settings/clearBrowserData"/>
            <ComboBoxItem Content="Microsoft Edge Dev" Tag="edge://settings/clearBrowserData"/>
            <ComboBoxItem Content="Microsoft Edge Canary" Tag="edge://settings/clearBrowserData"/>
            <ComboBoxItem Content="Chromium (Ungoogled)" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Midori Browser" Tag="midori://settings/clearBrowserData"/>
            <ComboBoxItem Content="Brave Beta" Tag="brave://settings/clearBrowserData"/>
            <ComboBoxItem Content="Vivaldi Snapshot" Tag="vivaldi://settings/clearBrowserData"/>
            <ComboBoxItem Content="Brave Nightly" Tag="brave://settings/clearBrowserData"/>
            <ComboBoxItem Content="Mullvad Browser" Tag="about:preferences#privacy"/>
            <ComboBoxItem Content="DuckDuckGo Browser" Tag="duck://settings/clearBrowserData"/>
            <ComboBoxItem Content="Thorium Browser" Tag="chrome://settings/clearBrowserData"/>
            <ComboBoxItem Content="Arc Browser" Tag="chrome://settings/clearBrowserData"/>
           </ComboBox>
           <Button Name="CleanupBrowserOpenBtn" Grid.Column="1" Content="Open Cleanup Settings" Height="34" MinWidth="164" Margin="10,0,0,0" Background="#263B36" Foreground="#A7F3D0" BorderBrush="#36594D"/>
          </Grid>
         </StackPanel>
        </Border>
        <Border Name="CleanupBrowserInfoPanel" Grid.Row="2" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="14">
         <StackPanel>
          <TextBlock Text="WHAT AMR CLEANS" FontSize="13" FontWeight="SemiBold" Foreground="#E4E4E7" Margin="0,0,0,8"/>
          <TextBlock Text="• Rebuildable browser cache folders (where detected)
• Code and GPU caches
• Recognized browser profiles only — profile databases, passwords, cookies, history, bookmarks and downloads are not targeted by the Clean Up cache scan." Foreground="#CBD5E1" FontSize="12" TextWrapping="Wrap"/>
          <TextBlock Text="For cookies, history, saved passwords or site data, use the browser’s built-in controls above so you can review exactly what the browser will remove." Foreground="#D9BD8B" FontSize="11" TextWrapping="Wrap" Margin="0,12,0,0"/>
         </StackPanel>
        </Border>
       </Grid>
      </TabItem>
      <TabItem Header="Orphan Cleanup">
       <Grid Margin="18">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0" Margin="2,0,2,8">
         <TextBlock Text="ORPHAN CLEANUP" FontSize="21" FontWeight="Bold" Foreground="#F4F4F5"/>
         <TextBlock Text="Analyze leftovers. Review before quarantine; restore anytime." FontSize="11" Foreground="#A1A1AA" Margin="0,3,0,0"/>
        </StackPanel>
        <Border Grid.Row="1" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="10" Margin="0,0,0,8">
         <WrapPanel VerticalAlignment="Center">
          <Button Name="CleanupOrphanScanBtn" Content="Analyze" Height="32" MinWidth="88" Margin="0,0,7,0" Background="#263B36" Foreground="#A7F3D0" BorderBrush="#36594D"/>
          <Button Name="CleanupOrphanQuarantineBtn" Content="Quarantine Selected" Height="32" MinWidth="132" Margin="0,0,7,0" Background="#493A27" Foreground="#E8D7B5" BorderBrush="#806744"/>
          <Button Name="CleanupOrphanRefreshBtn" Content="Refresh Quarantine" Height="32" MinWidth="128" Margin="0,0,7,0" Background="#293746" Foreground="#C7DDF5" BorderBrush="#40566D"/>
          <Button Name="CleanupOrphanRestoreBtn" Content="Restore Selected" Height="32" MinWidth="118" Background="#263B36" Foreground="#A7F3D0" BorderBrush="#36594D"/>
          <TextBlock Name="CleanupOrphanStatus" Text="Ready" Width="235" Foreground="#CBD5E1" FontSize="11" VerticalAlignment="Center" Margin="12,0,0,0" TextWrapping="Wrap"/>
         </WrapPanel>
        </Border>
        <Grid Name="CleanupOrphanListsPanel" Grid.Row="2">
         <Grid.ColumnDefinitions><ColumnDefinition Width="1.25*"/><ColumnDefinition Width="12"/><ColumnDefinition Width="0.85*"/></Grid.ColumnDefinitions>
         <Border Grid.Column="0" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="9">
          <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
           <TextBlock Text="ANALYSIS RESULTS · SELECT TO QUARANTINE" Foreground="#D9BD8B" FontSize="10" FontWeight="SemiBold" Margin="2,0,0,7"/>
           <ListBox Name="CleanupOrphanResults" Grid.Row="1" SelectionMode="Extended" Background="#0B1220" Foreground="#E5EDF7" BorderBrush="#34465B" FontSize="10" Padding="6">
            <ListBox.ItemTemplate><DataTemplate><CheckBox Content="{Binding Display}" IsChecked="{Binding IsChecked, Mode=TwoWay}" Foreground="#E5EDF7" Background="#0B1220" Padding="2,4" FocusVisualStyle="{x:Null}">
             <CheckBox.Style>
              <Style TargetType="{x:Type CheckBox}">
               <Setter Property="Template">
                <Setter.Value>
                 <ControlTemplate TargetType="{x:Type CheckBox}">
                  <Grid SnapsToDevicePixels="True">
                   <Grid.ColumnDefinitions><ColumnDefinition Width="18"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                   <Border x:Name="CheckBoxFrame" Grid.Column="0" Width="13" Height="13" CornerRadius="3" BorderThickness="1.2" BorderBrush="#B89A62" Background="#172536" VerticalAlignment="Center" HorizontalAlignment="Center"/>
                   <Path x:Name="CheckGlyph" Grid.Column="0" Data="M 2,6.5 L 5.2,9.5 L 11.5,2.5" Stroke="#FFFFFF" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed" Width="11" Height="10" Stretch="Fill" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                   <ContentPresenter Grid.Column="1" Margin="5,0,0,0" VerticalAlignment="Center" HorizontalAlignment="Left" RecognizesAccessKey="True"/>
                  </Grid>
                  <ControlTemplate.Triggers>
                   <Trigger Property="IsChecked" Value="True">
                    <Setter TargetName="CheckGlyph" Property="Visibility" Value="Visible"/>
                    <Setter TargetName="CheckBoxFrame" Property="Background" Value="#B89A62"/>
                   </Trigger>
                   <Trigger Property="IsMouseOver" Value="True">
                    <Setter TargetName="CheckBoxFrame" Property="BorderBrush" Value="#D9BD8B"/>
                    <Setter TargetName="CheckGlyph" Property="Stroke" Value="#111827"/>
                   </Trigger>
                   <Trigger Property="IsEnabled" Value="False">
                    <Setter TargetName="CheckBoxFrame" Property="Opacity" Value="0.45"/>
                    <Setter Property="Opacity" Value="0.6"/>
                   </Trigger>
                  </ControlTemplate.Triggers>
                 </ControlTemplate>
                </Setter.Value>
               </Setter>
              </Style>
             </CheckBox.Style>
            </CheckBox></DataTemplate></ListBox.ItemTemplate>
           </ListBox>
          </Grid>
         </Border>
         <Border Grid.Column="2" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="10" Padding="9">
          <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
           <TextBlock Text="QUARANTINE · RESTORE" Foreground="#D9BD8B" FontSize="10" FontWeight="SemiBold" Margin="2,0,0,7"/>
           <ListBox Name="CleanupOrphanQuarantineList" Grid.Row="1" SelectionMode="Extended" Background="#0B1220" Foreground="#E5EDF7" BorderBrush="#34465B" FontSize="10" Padding="6">
            <ListBox.ItemTemplate><DataTemplate><CheckBox Content="{Binding Display}" IsChecked="{Binding IsChecked, Mode=TwoWay}" Foreground="#E5EDF7" Background="#0B1220" Padding="2,4" FocusVisualStyle="{x:Null}">
             <CheckBox.Style>
              <Style TargetType="{x:Type CheckBox}">
               <Setter Property="Template">
                <Setter.Value>
                 <ControlTemplate TargetType="{x:Type CheckBox}">
                  <Grid SnapsToDevicePixels="True">
                   <Grid.ColumnDefinitions><ColumnDefinition Width="18"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                   <Border x:Name="CheckBoxFrame" Grid.Column="0" Width="13" Height="13" CornerRadius="3" BorderThickness="1.2" BorderBrush="#B89A62" Background="#172536" VerticalAlignment="Center" HorizontalAlignment="Center"/>
                   <Path x:Name="CheckGlyph" Grid.Column="0" Data="M 2,6.5 L 5.2,9.5 L 11.5,2.5" Stroke="#FFFFFF" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed" Width="11" Height="10" Stretch="Fill" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                   <ContentPresenter Grid.Column="1" Margin="5,0,0,0" VerticalAlignment="Center" HorizontalAlignment="Left" RecognizesAccessKey="True"/>
                  </Grid>
                  <ControlTemplate.Triggers>
                   <Trigger Property="IsChecked" Value="True">
                    <Setter TargetName="CheckGlyph" Property="Visibility" Value="Visible"/>
                    <Setter TargetName="CheckBoxFrame" Property="Background" Value="#B89A62"/>
                   </Trigger>
                   <Trigger Property="IsMouseOver" Value="True">
                    <Setter TargetName="CheckBoxFrame" Property="BorderBrush" Value="#D9BD8B"/>
                    <Setter TargetName="CheckGlyph" Property="Stroke" Value="#111827"/>
                   </Trigger>
                   <Trigger Property="IsEnabled" Value="False">
                    <Setter TargetName="CheckBoxFrame" Property="Opacity" Value="0.45"/>
                    <Setter Property="Opacity" Value="0.6"/>
                   </Trigger>
                  </ControlTemplate.Triggers>
                 </ControlTemplate>
                </Setter.Value>
               </Setter>
              </Style>
             </CheckBox.Style>
            </CheckBox></DataTemplate></ListBox.ItemTemplate>
           </ListBox>
          </Grid>
         </Border>
        </Grid>
        <TextBlock Grid.Row="3" Text="Protected: user profiles, AppData, browser data, shared folders and Windows components. Quarantine is reversible; restore stops on conflicts." Foreground="#D9BD8B" FontSize="10" TextWrapping="Wrap" Margin="2,7,2,0"/>
       </Grid>
      </TabItem>
      <TabItem Header="Windows Component Cleanup">
       <Grid Margin="18">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <StackPanel Grid.Row="0" Margin="2,0,2,14">
         <TextBlock Text="WINDOWS COMPONENT CLEANUP" FontSize="21" FontWeight="Bold" Foreground="#F4F4F5"/>
         <TextBlock Text="Analyze and clean the Windows component store." FontSize="12" Foreground="#A1A1AA" TextWrapping="Wrap" Margin="0,4,0,0"/>
        </StackPanel>
        <Border Grid.Row="1" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="14" Margin="0,0,0,10">
         <StackPanel>
          <TextBlock Text="COMPONENT STORE" FontSize="13" FontWeight="SemiBold" Foreground="#E4E4E7" Margin="0,0,0,9"/>
          <StackPanel Orientation="Horizontal">
           <Button Name="CleanupComponentAnalyzeNewBtn" Content="Analyze Component Store" Height="34" MinWidth="170" Margin="0,0,8,0" Background="#343044" Foreground="#DDD2F5" BorderBrush="#51466A"/>
           <Button Name="CleanupComponentRunNewBtn" Content="Clean Component Store" Height="34" MinWidth="160" Background="#493B2B" Foreground="#F4DFC0" BorderBrush="#70583A" IsEnabled="False"/>
          </StackPanel>
          <TextBlock Text="No /ResetBase. Updates remain uninstallable. Do not interrupt DISM." Foreground="#D9BD8B" FontSize="11" TextWrapping="Wrap" Margin="0,10,0,0"/>
          <TextBlock Name="CleanupComponentStatusNew" Text="Ready. Analyze before cleanup." Foreground="#AEB8C8" FontSize="11" TextWrapping="Wrap" Margin="0,8,0,0"/>
         </StackPanel>
        </Border>
        <Border Grid.Row="2" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="12" Padding="12">
         <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
          <TextBlock Grid.Row="0" Text="REPORT" FontSize="11" FontWeight="SemiBold" Foreground="#A1A1AA" Margin="0,0,0,7"/>
          <TextBox Name="CleanupComponentReportNew" Grid.Row="1" Text="Component store analysis has not been run." IsReadOnly="True" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" Background="#0B1220" Foreground="#F1F5F9" BorderBrush="#526176" FontFamily="Consolas" FontSize="12" Padding="10"/>
         </Grid>
        </Border>
       </Grid>
      </TabItem>
     </TabControl>
    </Grid>
    </TabItem>

<TabItem Header="Logs">
    <Border Padding="15">
     <Grid>
      <Grid.RowDefinitions>
       <RowDefinition Height="Auto"/>
       <RowDefinition Height="*"/>
      </Grid.RowDefinitions>
      
      <Grid Grid.Row="0" Margin="0,0,0,10" Opacity="0">
       <Grid.RenderTransform><TranslateTransform Y="10"/></Grid.RenderTransform>
       <Grid.Triggers><EventTrigger RoutedEvent="FrameworkElement.Loaded"><BeginStoryboard><Storyboard>
        <DoubleAnimation Storyboard.TargetProperty="Opacity" From="0" To="1" Duration="0:0:0.62" DecelerationRatio="0.82"/>
        <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="10" To="0" Duration="0:0:0.62" DecelerationRatio="0.82"/>
       </Storyboard></BeginStoryboard></EventTrigger></Grid.Triggers>
       <Grid.ColumnDefinitions>
        <ColumnDefinition Width="*"/>
        <ColumnDefinition Width="Auto"/>
       </Grid.ColumnDefinitions>
       <StackPanel Grid.Column="0">
        <TextBlock Text="Detailed System &amp; Component Log Suite" FontSize="22" FontWeight="Bold" Foreground="#FFFFFF"/>
        <TextBlock Text="Real-time categorized execution trace and diagnostic console." Foreground="#A1A1AA" FontSize="13" Margin="0,2,0,0"/>
       </StackPanel>
       <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
        <Button Name="ExportLogsBtn" Content="💾 Export Log File" Background="#2563EB" Foreground="#FFFFFF" BorderThickness="0" Margin="0,0,10,0"/>
        <Button Name="LogShowAllBtn" Content="👁 Show All" Background="#0F766E" Foreground="#FFFFFF" BorderThickness="0" Margin="0,0,10,0"/>
        <Button Name="ClearAllLogsBtn" Content="🗑 Clear All Consoles" Background="#3F3F46" Foreground="#FFFFFF" BorderThickness="0"/>
       </StackPanel>
      </Grid>
      
      <Border Grid.Row="1" Background="{StaticResource AMRSoftGlassBrush}" BorderBrush="{StaticResource AMRSoftGlassEdgeBrush}" BorderThickness="1" CornerRadius="14" Padding="8" Opacity="0">
      <Border.RenderTransform><TranslateTransform Y="16"/></Border.RenderTransform>
      <Border.Triggers><EventTrigger RoutedEvent="FrameworkElement.Loaded"><BeginStoryboard><Storyboard>
       <DoubleAnimation Storyboard.TargetProperty="Opacity" From="0" To="1" Duration="0:0:0.936" BeginTime="0:0:0.10" DecelerationRatio="0.86"/>
       <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="16" To="0" Duration="0:0:0.936" BeginTime="0:0:0.10" DecelerationRatio="0.86"/>
      </Storyboard></BeginStoryboard></EventTrigger></Border.Triggers>
      <TabControl Background="Transparent" BorderThickness="0">
       <TabControl.Resources>
        <Style TargetType="{x:Type TabItem}">
         <Setter Property="RenderTransformOrigin" Value="0.5,0.5"/>
         <Setter Property="RenderTransform"><Setter.Value><TranslateTransform Y="0"/></Setter.Value></Setter>
         <Setter Property="Margin" Value="5,3,5,7"/>
         <Setter Property="Padding" Value="10,6"/>
         <Setter Property="Foreground" Value="#DCEBFA"/>
         <Setter Property="Background" Value="{StaticResource AMRSoftGlassBrush}"/>
         <Setter Property="BorderBrush" Value="{StaticResource AMRSoftGlassEdgeBrush}"/>
         <Setter Property="BorderThickness" Value="1"/>
         <Setter Property="FontSize" Value="11"/>
         <Setter Property="FontWeight" Value="SemiBold"/>
         <Setter Property="Template">
          <Setter.Value>
           <ControlTemplate TargetType="{x:Type TabItem}">
            <Border x:Name="LogTabSurface" Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}"
                    CornerRadius="9" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
             <ContentPresenter ContentSource="Header" HorizontalAlignment="Center" VerticalAlignment="Center"
                               RecognizesAccessKey="True"/>
            </Border>
            <ControlTemplate.Triggers>
             <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="LogTabSurface" Property="Background" Value="#354F6B"/>
              <Setter TargetName="LogTabSurface" Property="BorderBrush" Value="#6F9BC6"/>
              <Setter Property="Foreground" Value="#FFFFFF"/>
             </Trigger>
             <Trigger Property="IsSelected" Value="True">
              <Setter TargetName="LogTabSurface" Property="Background" Value="#315D86"/>
