</ResourceDictionary>
'@)

        $footer = New-Object System.Windows.Controls.DockPanel
        $footer.Margin = New-Object System.Windows.Thickness(16,0,16,12)
        $footer.LastChildFill = $true
        $countText = New-Object System.Windows.Controls.TextBlock
        $countText.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#91A9C2')
        $countText.VerticalAlignment = 'Center'
        [void]$footer.Children.Add($countText)
        $hint = New-Object System.Windows.Controls.TextBlock
        $hint.Text = 'Double-click a folder to browse • Double-click a file to open'
        $hint.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#7891AA')
        $hint.FontSize = 10
        $hint.HorizontalAlignment = 'Right'
        $hint.VerticalAlignment = 'Center'
        [System.Windows.Controls.DockPanel]::SetDock($hint, [System.Windows.Controls.Dock]::Right)
        [void]$footer.Children.Add($hint)

        [System.Windows.Controls.Grid]::SetRow($header,0)
        [System.Windows.Controls.Grid]::SetRow($toolbar,1)
        [System.Windows.Controls.Grid]::SetRow($list,2)
        [System.Windows.Controls.Grid]::SetRow($footer,3)
        [void]$layout.Children.Add($header)
        [void]$layout.Children.Add($toolbar)
        [void]$layout.Children.Add($list)
        [void]$layout.Children.Add($footer)
        $root.Child = $layout
        $win.Content = $root
        $root.Opacity = 0
        $root.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
        $popupScale = New-Object System.Windows.Media.ScaleTransform(0.975,0.975)
        $root.RenderTransform = $popupScale
        $win.Add_ContentRendered({
            $fadeIn = [System.Windows.Media.Animation.DoubleAnimation]::new(0.0,1.0,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(190)))
            $scaleIn = [System.Windows.Media.Animation.DoubleAnimation]::new(0.975,1.0,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(210)))
            $fadeIn.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::HoldEnd
            $scaleIn.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::HoldEnd
            $root.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fadeIn)
            $popupScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$scaleIn)
            $popupScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$scaleIn)
        }.GetNewClosure())

        $state = @{ Current=$rootPath; Root=$rootPath }
        $loadFolder = {
            param([string]$folder)
            try {
                $resolved = [System.IO.Path]::GetFullPath($folder)
                if (-not (Test-Path -LiteralPath $resolved -PathType Container)) { return }
                $state.Current = $resolved
                $pathBox.Text = $resolved
                $list.Items.Clear()
                $entries = @(Get-ChildItem -LiteralPath $resolved -Force -ErrorAction Stop | Sort-Object @{Expression={ if ($_.PSIsContainer) { 0 } else { 1 } }}, Name)
                foreach ($entry in $entries) {
                    $type = if ($entry.PSIsContainer) { 'Folder' } else { [System.IO.Path]::GetExtension($entry.Name).TrimStart('.').ToUpperInvariant() }
                    if ([string]::IsNullOrWhiteSpace($type)) { $type = 'File' }
                    $size = if ($entry.PSIsContainer) { '—' } else { '{0:N1} KB' -f ($entry.Length / 1KB) }
                    [void]$list.Items.Add([pscustomobject]@{
                        Name = $(if ($entry.PSIsContainer) { '▰  ' + $entry.Name } else { '▤  ' + $entry.Name })
                        Type = $type
                        Size = $size
                        Modified = $entry.LastWriteTime.ToString('yyyy-MM-dd HH:mm')
                        FullName = $entry.FullName
                        IsDirectory = [bool]$entry.PSIsContainer
                    })
                }
                $countText.Text = ('{0} items' -f $entries.Count)
                $up.IsEnabled = ($resolved.TrimEnd('\') -ine $state.Root.TrimEnd('\'))
            } catch {
                $countText.Text = 'Unable to read this folder'
                try { Write-AMRLog ('AMR file browser read error: ' + $_.Exception.Message) WARNING System } catch {}
            }
        }
        $up.Add_Click({
            try {
                if ($state.Current.TrimEnd('\') -ine $state.Root.TrimEnd('\')) {
                    $parent = [System.IO.Directory]::GetParent($state.Current)
                    if ($parent) { & $loadFolder $parent.FullName }
                }
            } catch {}
        })
        $refresh.Add_Click({ & $loadFolder $state.Current })
        $openRoot.Add_Click({ & $loadFolder $state.Root })
        $list.Add_MouseDoubleClick({
            $selected = $list.SelectedItem
            if (-not $selected) { return }
            try {
                if ($selected.IsDirectory) { & $loadFolder $selected.FullName }
                else { Start-Process -FilePath $selected.FullName -ErrorAction Stop }
            } catch {
                try { Write-AMRLog ('AMR file browser open error: ' + $_.Exception.Message) WARNING System } catch {}
            }
        })
        $win.Add_Closed({ $script:AMRFilesPopup = $null })
        $script:AMRFilesPopup = $win
        & $loadFolder $rootPath
        [void]$win.ShowDialog()
    } catch {
        try { Write-AMRLog ('Could not open AMR program files popup: ' + $_.Exception.Message) ERROR System } catch {}
        try { Show-AMRMessageGlass ('Could not open the AMR program files window: ' + $_.Exception.Message) 'AMR Program Files' OK Error | Out-Null } catch {}
    }
}

function Get-AMRToolKitControlTabSelected {
    # True while one of the Control Center pages (children under the Control Center entry) is the selected Tool Kit page.
    $kit = C 'ToolKitSubTabs'
    if (-not $kit -or -not $kit.SelectedItem) { return $false }
    return ([string]$kit.SelectedItem.Tag -eq 'CCChild')
}
function Get-AMRToolKitEffectiveSub {
    $kit = C 'ToolKitSubTabs'
    if (-not $kit -or -not $kit.SelectedItem) { return 'Tweaks' }
    return [string]$kit.SelectedItem.Header
}
# Logs page search. The shared top search box filters the in-app log consoles (All Logs, System, Tools, Overview, Software, Customize, Tweaks, Cleanup).
# The Drivers sub-tab keeps its own search box and severity filter. The disk log is never filtered.
function Get-AMRLogSubTabs {
    if ($script:LogSubTabsCtl) { return $script:LogSubTabsCtl }
    try {
        $node = C 'LogConsoleAll'
        for ($hop = 0; $hop -lt 12 -and $node; $hop++) {
            $node = [System.Windows.LogicalTreeHelper]::GetParent($node)
            if ($node -is [System.Windows.Controls.TabControl]) {
                $hasDrivers = $false
                foreach ($tabItem in $node.Items) { if ([string]$tabItem.Header -match 'Drivers') { $hasDrivers = $true } }
                if ($hasDrivers) { $script:LogSubTabsCtl = $node; return $node }
                return $null
            }
        }
    } catch {}
    return $null
}
function Test-AMRLogDriversSubTab {
    $subTabs = Get-AMRLogSubTabs
    if (-not $subTabs -or -not $subTabs.SelectedItem) { return $true }
    return ([string]$subTabs.SelectedItem.Header -match 'Drivers')
}
function Set-AMRLogSearchFilter {
    param([string]$Query)
    $text = if ($null -eq $Query) { '' } else { $Query.Trim() }
    if ($text -ceq [string]$script:LogUISearch) { return }
    $script:LogUISearch = $text
    foreach ($dirtyKey in @('All','System','Overview','Software','Customize','Tweaks','Cleanup','Tools')) { $script:LogUIDirty[$dirtyKey] = $true }
    try { Invoke-AMRLogUIPumpTick } catch {}
}
function Get-AMRSmartSearchTarget {
    $main = C 'MainNavigationTabs'
    if (-not $main -or -not $main.SelectedItem) { return $null }
    $page = [string]$main.SelectedItem.Header
    if ($page -eq 'System') {
        $overview = C 'OverviewSubTabs'
        if ($overview -and $overview.SelectedItem -eq (C 'DriverCenterTab')) { return '__DriverSearch' }
        if ($overview -and $overview.SelectedItem -and [string]$overview.SelectedItem.Header -eq 'Backups') { return '__ContentFilter' }
    }
    if ($page -eq 'Software') { return 'SearchBox' }
    if ($page -eq 'Logs') { if (Test-AMRLogDriversSubTab) { return 'DriverLogSearchBox' } else { return '__LogFilter' } }
    if ($page -eq 'System' -or $page -eq 'Overview' -or $page -eq 'About' -or $page -eq 'Activation') { return '__ContentFilter' }
    if ($page -eq 'Backups' -or ($page -eq 'System' -and (C 'OverviewSubTabs') -and (C 'OverviewSubTabs').SelectedItem -and [string](C 'OverviewSubTabs').SelectedItem.Header -eq 'Backups')) {
        $backup = C 'BackupSubTabs'
        $sub = if ($backup -and $backup.SelectedItem) { [string]$backup.SelectedItem.Header } else { 'Backup Center' }
        if ($sub -eq 'Backup Center') { return 'BackupSearchBox' }
        return '__ContentFilter'
    }
    if ($page -eq 'Cleanup') { return 'CleanupSearchBox' }
    if ($page -eq 'Tool Kit') {
        $sub = Get-AMRToolKitEffectiveSub
        $map = @{ Optimize='OptSearchBox'; Security='SecSearchBox'; System='SysSearchBox'; Networks='NetSearchBox'; Utilities='UtilSearchBox'; Backup='BackupSearchBox'; Tweaks='__ContentFilter'; Customization='__ContentFilter' }
        if ($map.ContainsKey($sub)) { return $map[$sub] }
    }
    return $null
}
function Get-AMRSmartCategoryTarget {
    $main = C 'MainNavigationTabs'
    if (-not $main -or -not $main.SelectedItem) { return $null }
    $page = [string]$main.SelectedItem.Header
    if ($page -eq 'Tool Kit') {
        $sub = Get-AMRToolKitEffectiveSub
        $map = @{ Optimize='OptCategoryFilter'; Security='SecCategoryFilter'; System='SysCategoryFilter'; Networks='NetCategoryFilter'; Utilities='UtilCategoryFilter'; Backup='BackupCategoryFilter' }
        if ($map.ContainsKey($sub)) { return $map[$sub] }
    }
    if ($page -eq 'Backups' -or ($page -eq 'System' -and (C 'OverviewSubTabs') -and (C 'OverviewSubTabs').SelectedItem -and [string](C 'OverviewSubTabs').SelectedItem.Header -eq 'Backups')) {
        $backup = C 'BackupSubTabs'
        $sub = if ($backup -and $backup.SelectedItem) { [string]$backup.SelectedItem.Header } else { 'Backup Center' }
        if ($sub -eq 'Backup Center') { return 'BackupCategoryFilter' }
    }
    return $null
}

function Set-AMRSmartContentFilter {
    param([string]$Query)
    try {
        $main = C 'MainNavigationTabs'
        if (-not $main -or -not $main.SelectedItem) { return }
        $active = $main.SelectedItem
        $page = [string]$active.Header
        if ($page -eq 'Tool Kit') {
            $kit = C 'ToolKitSubTabs'
            if ($kit -and $kit.SelectedItem) { $active = $kit.SelectedItem }
        } elseif ($page -eq 'System' -or $page -eq 'Overview') {
            $overview = C 'OverviewSubTabs'
            if ($overview -and $overview.SelectedItem) { $active = $overview.SelectedItem }
        } elseif ($page -eq 'Backups') {
            $backup = C 'BackupSubTabs'
            if ($backup -and $backup.SelectedItem) { $active = $backup.SelectedItem }
        }
        $root = $active.Content
        if (-not $root) { return }
        $stack = New-Object 'System.Collections.Generic.Stack[object]'
        $stack.Push($root)
        while ($stack.Count -gt 0) {
            $node = $stack.Pop()
            if ($node -is [System.Windows.Controls.CheckBox]) {
                $label = [string]$node.Content
                $match = [string]::IsNullOrWhiteSpace($Query) -or
                    $label.IndexOf($Query,[System.StringComparison]::OrdinalIgnoreCase) -ge 0
                $node.Visibility = if ($match) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            }
            try {
                foreach ($child in [System.Windows.LogicalTreeHelper]::GetChildren($node)) {
                    if ($null -ne $child -and -not ($child -is [string])) { $stack.Push($child) }
                }
            } catch {}
        }
    } catch {
        Write-AMRLog "Smart Search page filter warning: $($_.Exception.Message)" WARNING System
    }
}

$script:SmartSearchContextUpdating = $false
function Update-AMRSmartSearchContext {
    # Category synchronization can raise additional routed selection events.
    # Prevent re-entrant context refreshes while the shared controls are being updated.
    if ($script:SmartSearchContextUpdating) { return }
    if (-not $script:SmartSearchBox) { return }
    $script:SmartSearchContextUpdating = $true
    try {
        Update-AMRSmartSearchContextCore
    } finally {
        $script:SmartSearchContextUpdating = $false
    }
}
function Update-AMRSmartSearchContextCore {
    if (-not $script:SmartSearchBox) { return }
    $main = C 'MainNavigationTabs'
    $page = if ($main -and $main.SelectedItem) { [string]$main.SelectedItem.Header } else { 'current page' }
    if ($page -eq 'Tool Kit') {
        $page += ' / ' + (Get-AMRToolKitEffectiveSub)
    } elseif ($page -eq 'System' -or $page -eq 'Overview') {
        $overview = C 'OverviewSubTabs'
        if ($overview -and $overview.SelectedItem) {
            if ($overview.SelectedItem -eq (C 'DriverCenterTab')) { $page += ' / Driver Center' }
            else {
                $page += ' / ' + [string]$overview.SelectedItem.Header
                if ([string]$overview.SelectedItem.Header -eq 'Backups') {
                    $backupTabs = C 'BackupSubTabs'
                    if ($backupTabs -and $backupTabs.SelectedItem) { $page += ' / ' + [string]$backupTabs.SelectedItem.Header }
                }
            }
        }
    } elseif ($page -eq 'Backups') {
        $backupTabs = C 'BackupSubTabs'
        if ($backupTabs -and $backupTabs.SelectedItem) { $page += ' / ' + [string]$backupTabs.SelectedItem.Header }
    }
    $targetName = Get-AMRSmartSearchTarget
    $placeholder = 'Search in ' + $page + '...'
    switch -Regex ($page) {
        '^Software$' { $placeholder = 'Search software, package name or ID...'; break }
        '^Tool Kit / Optimize$' { $placeholder = 'Search in Optimize...'; break }
        '^Tool Kit / Security$' { $placeholder = 'Search in Security...'; break }
        '^Tool Kit / System$' { $placeholder = 'Search in System...'; break }
        '^Tool Kit / Networks$' { $placeholder = 'Search in Networks...'; break }
        '^Tool Kit / Utilities$' { $placeholder = 'Search in Utilities...'; break }
        '^Tool Kit / Backup$' { $placeholder = 'Search backup tools by name or category...'; break }
        '^Tool Kit / Activation$' { $placeholder = 'Search Windows, Office, licensing services or KMS configuration...'; break }
        '^(Backups|System / Backups) / Backup Center$' { $placeholder = 'Search backup tools by name or category...'; break }
        '^System / Driver Center$' { $placeholder = 'Search driver names, devices, hardware IDs or versions...'; break }
        '^System.*$' { $placeholder = 'Search in ' + $page + '...'; break }
        '^Cleanup$' { $placeholder = 'Search cleanup options...'; break }
        '^Logs$' { $placeholder = 'Search logs, events or device IDs...'; break }
        '^Overview' { $placeholder = 'Search within this overview...'; break }
        '^About$' { $placeholder = 'Search about this application...'; break }
    }
    if ($targetName -eq '__LogFilter') { $placeholder = 'Filter log lines by text, area or level...' }
    $script:SmartSearchBox.Tag = $placeholder
    $script:SmartSearchBox.ToolTip = 'Smart Search — ' + $page + ' | ' + $placeholder

    $categoryTargetName = Get-AMRSmartCategoryTarget
    $categoryTarget = if ($categoryTargetName) { C $categoryTargetName } else { $null }
    $sharedCategory = $script:SmartCategoryFilter
    if ($sharedCategory) {
        $script:SmartCategoryRouting = $true
        try {
            $sharedCategory.Items.Clear()
            if ($categoryTarget -and $categoryTarget.Items.Count -gt 0) {
                foreach ($item in $categoryTarget.Items) {
                    $copy = New-Object System.Windows.Controls.ComboBoxItem
                    if ($item -is [System.Windows.Controls.ComboBoxItem]) { $copy.Content = [string]$item.Content }
                    else { $copy.Content = [string]$item }
                    [void]$sharedCategory.Items.Add($copy)
                }
                $sharedCategory.SelectedIndex = [Math]::Max(0,$categoryTarget.SelectedIndex)
                $wasCategoryHidden = ($sharedCategory.Visibility -ne [System.Windows.Visibility]::Visible)
                if ($wasCategoryHidden) {
                    $sharedCategory.Opacity = 0
                    $sharedCategory.RenderTransform = [System.Windows.Media.TranslateTransform]::new(0,-5)
                }
                $sharedCategory.Visibility = [System.Windows.Visibility]::Visible
                if ($wasCategoryHidden) {
                    try {
                        $fadeIn = [System.Windows.Media.Animation.DoubleAnimation]::new(0.0,1.0,[TimeSpan]::FromMilliseconds(190))
                        $fadeIn.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
                        $fadeIn.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
                        $sharedCategory.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fadeIn)
                        $slideIn = [System.Windows.Media.Animation.DoubleAnimation]::new(-5.0,0.0,[TimeSpan]::FromMilliseconds(190))
                        $slideIn.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
                        $slideIn.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
                        $sharedCategory.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$slideIn)
                    } catch { $sharedCategory.Opacity = 1 }
                }
                # Hide the old in-page category/search cluster; the shared selector is now the single visible control.
                try { $categoryTarget.Parent.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
            } else {
                $sharedCategory.Visibility = [System.Windows.Visibility]::Collapsed
            }
        } finally { $script:SmartCategoryRouting = $false }
    }
    if ($targetName -eq '__LogFilter') {
        Set-AMRLogSearchFilter -Query ([string]$script:SmartSearchBox.Text)
        $script:SmartSearchBox.IsEnabled = $true
        return
    }
    if ([string]$script:LogUISearch -ne '') { Set-AMRLogSearchFilter -Query '' }
    if ($targetName -eq '__DriverSearch') {
        Update-AMRDriverSearchView -Query ([string]$script:SmartSearchBox.Text)
        $script:SmartSearchBox.IsEnabled = $true
        return
    }
    if ($targetName -eq '__ContentFilter') {
        $perfCf = Get-AMRPerfNow
        Set-AMRSmartContentFilter -Query ([string]$script:SmartSearchBox.Text)
        Add-AMRPerfSince 'smart.contentFilterWalk' $perfCf
        $script:SmartSearchBox.IsEnabled = $true
        return
    }
    $target = if ($targetName) { C $targetName } else { $null }
    if ($target -and $target -is [System.Windows.Controls.TextBox]) {
        $script:SmartSearchRouting = $true
        try { $target.Text = [string]$script:SmartSearchBox.Text }
        finally { $script:SmartSearchRouting = $false }
        $script:SmartSearchBox.IsEnabled = $true
    } else {
        $script:SmartSearchBox.IsEnabled = $false
    }
}


try {
    foreach ($categoryName in @('OptCategoryFilter','SecCategoryFilter','SysCategoryFilter','NetCategoryFilter','UtilCategoryFilter','BackupCategoryFilter')) {
        $localCategory = C $categoryName
        if ($localCategory) { $localCategory.Visibility = [System.Windows.Visibility]::Collapsed }
    }
    $mainTabs = C 'MainNavigationTabs'
    if ($mainTabs) {
        $mainTabs.ApplyTemplate()
        $script:SmartSearchBox = $mainTabs.Template.FindName('PART_SmartSearchBox', $mainTabs)
        if ($script:SmartSearchBox) {
            $script:SmartCategoryFilter = $mainTabs.Template.FindName('PART_SmartCategoryFilter', $mainTabs)
            if ($script:SmartCategoryFilter) {
                $script:SmartCategoryFilter.Add_SelectionChanged({
                    if ($script:SmartCategoryRouting) { return }
                    $categoryName = Get-AMRSmartCategoryTarget
                    if ($categoryName) {
                        $targetCategory = C $categoryName
                        if ($targetCategory -and $script:SmartCategoryFilter.SelectedIndex -ge 0) {
                            $script:SmartCategoryRouting = $true
                            try { $targetCategory.SelectedIndex = $script:SmartCategoryFilter.SelectedIndex }
                            finally { $script:SmartCategoryRouting = $false }
                        }
                    }
                })
            }
            $script:SmartSearchBox.Add_TextChanged({
                if ($script:SmartSearchRouting) { return }
                $activeMain = C 'MainNavigationTabs'
                $activePage = if ($activeMain -and $activeMain.SelectedItem) { [string]$activeMain.SelectedItem.Header } else { '' }
                $searchText = [string]$script:SmartSearchBox.Text
                if ($activePage -eq 'About' -and $searchText.Trim() -match '^(?i:TELE)$') {
                    Invoke-AMRHiddenTelegramExperience
                    return
                }
                # About shortcut: FIL / FILE / FILES opens the AMR-managed
                # program files browser (Downloads, Drivers, Icons, Logs, Backups, etc.).
                if ($activePage -eq 'About' -and $searchText.Trim() -match '^(?i:fil(?:e?s)?)$') {
                    Open-AMRProgramFilesFolder
                    return
                }
                # Backups-only shortcut: exactly "file" or "files" while System > Backups is the open page.
                if ($activePage -eq 'System' -and $searchText.Trim() -match '^(?i:files?)$') {
                    $shortcutTabs = C 'OverviewSubTabs'
                    if ($shortcutTabs -and $shortcutTabs.SelectedItem -and [string]$shortcutTabs.SelectedItem.Header -eq 'Backups') {
                        Open-AMRRestoreReceiptFolder
                        return
                    }
                }
                $targetName = Get-AMRSmartSearchTarget
                if ($targetName -eq '__LogFilter') {
                    Set-AMRLogSearchFilter -Query $searchText
                    return
                }
                if ($targetName -eq '__DriverSearch') {
                    Update-AMRDriverSearchView -Query ([string]$script:SmartSearchBox.Text)
                    return
                }
                if ($targetName -eq '__ContentFilter') {
                    Set-AMRSmartContentFilter -Query ([string]$script:SmartSearchBox.Text)
                    return
                }
                if ($targetName) {
                    $target = C $targetName
                    if ($target -and $target -is [System.Windows.Controls.TextBox]) {
                        $script:SmartSearchRouting = $true
                        try { $target.Text = [string]$script:SmartSearchBox.Text }
                        finally { $script:SmartSearchRouting = $false }
                    }
                }
            })
        }
        $mainTabs.Add_SelectionChanged({
            # WPF SelectionChanged is a routed event. Ignore child TabControl events
            # bubbling through MainNavigationTabs to prevent duplicate expensive refreshes.
            if ($_.OriginalSource -ne $this) { return }
            Update-AMRSmartSearchContext
        })
        # Logs sub-tabs: re-route the shared search box when the sub-tab changes (Drivers keeps its own box; the others use the log filter).
        try {
            $logSubTabsCtl = Get-AMRLogSubTabs
            if ($logSubTabsCtl) {
                $logSubTabsCtl.Add_SelectionChanged({
                    if ($_.OriginalSource -ne $this) { return }
                    Update-AMRSmartSearchContext
                })
            }
        } catch { try { Write-AMRLog ('Could not attach the Logs sub-tab search routing: ' + $_.Exception.Message) WARNING System } catch {} }
    }
    function Invoke-AMRNavigationTilePressAnimation {
        param([object]$Element)

        try {
            if (-not ($Element -is [System.Windows.UIElement])) { return }

            $transform = $Element.RenderTransform
            if (-not ($transform -is [System.Windows.Media.TranslateTransform])) {
                $transform = New-Object System.Windows.Media.TranslateTransform
                $Element.RenderTransform = $transform
            }

            $ease = New-Object System.Windows.Media.Animation.QuadraticEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $move = New-Object System.Windows.Media.Animation.DoubleAnimation
            $move.From = 4.0
            $move.To = 0.0
            $move.Duration = [TimeSpan]::FromMilliseconds(220)
            $move.EasingFunction = $ease
            $transform.BeginAnimation(
                [System.Windows.Media.TranslateTransform]::XProperty,
                $move,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )

            $fade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $fade.From = 0.90
            $fade.To = 1.0
            $fade.Duration = [TimeSpan]::FromMilliseconds(220)
            $fade.EasingFunction = $ease
            $Element.BeginAnimation(
                [System.Windows.UIElement]::OpacityProperty,
                $fade,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )
        } catch {}
    }

    # A5: gentle grow/shrink of the page box when the main page changes (System / Software / Tool Kit / Cleanup / Logs / About).
    # Only a fresh ScaleTransform on the selected page root; no layout, size or content change. Skipped if the root already has its own transform.
    function Invoke-AMRMainPageSizeTransition {
        param([object]$TabItem)
        try {
            if (-not $TabItem) { return }
            $root = $TabItem.Content
            if (-not ($root -is [System.Windows.FrameworkElement])) { return }
            $existing = $root.RenderTransform
            $isFree = ($null -eq $existing) -or ($existing -eq [System.Windows.Media.Transform]::Identity) -or
                      (($existing -is [System.Windows.Media.ScaleTransform]) -and $existing.ScaleX -eq 1.0 -and $existing.ScaleY -eq 1.0)
            if (-not $isFree) { return }
            $scale = New-Object System.Windows.Media.ScaleTransform(1.0,1.0)
            $root.RenderTransformOrigin = New-Object System.Windows.Point(0.5,0.5)
            $root.RenderTransform = $scale
            $ease = New-Object System.Windows.Media.Animation.QuadraticEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            foreach ($prop in @([System.Windows.Media.ScaleTransform]::ScaleXProperty,[System.Windows.Media.ScaleTransform]::ScaleYProperty)) {
                $a = New-Object System.Windows.Media.Animation.DoubleAnimation
                $a.From = 0.972
                $a.To = 1.0
                $a.Duration = [TimeSpan]::FromMilliseconds(280)
                $a.EasingFunction = $ease
                $a.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
                $scale.BeginAnimation($prop,$a,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
            }
        } catch {}
    }

    # Lightweight staggered entrance used by System pages and backup cards.
    # RenderTransform is layout-neutral; no timers or background workers are created.
    # Premium, low-cost page transition for System navigation.
    # Animate only the selected page root (not its child controls) so the
    # transition stays smooth without triggering a cascade of layout/render work.
    function Invoke-AMRSystemPageTransition {
        param([object]$TabItem)
        try {
            if (-not $TabItem) { return }
            $pageRoot = $TabItem.Content
            if (-not ($pageRoot -is [System.Windows.UIElement])) { return }

            $pageTransform = $pageRoot.RenderTransform
            if (-not ($pageTransform -is [System.Windows.Media.TranslateTransform])) {
                $pageTransform = New-Object System.Windows.Media.TranslateTransform
                $pageRoot.RenderTransform = $pageTransform
            }

            $ease = New-Object System.Windows.Media.Animation.CubicEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            # Almost imperceptible fade + 3px rise: elegant feedback, no heavy stagger.
            $fade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $fade.From = 0.985
            $fade.To = 1.0
            $fade.Duration = [TimeSpan]::FromMilliseconds(210)
            $fade.EasingFunction = $ease

            $rise = New-Object System.Windows.Media.Animation.DoubleAnimation
            $rise.From = 3.0
            $rise.To = 0.0
            $rise.Duration = [TimeSpan]::FromMilliseconds(230)
            $rise.EasingFunction = $ease

            $pageRoot.BeginAnimation(
                [System.Windows.UIElement]::OpacityProperty,
                $fade,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )
            $pageTransform.BeginAnimation(
                [System.Windows.Media.TranslateTransform]::YProperty,
                $rise,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )
        } catch {
            try { Write-AMRLog ('System page transition skipped: ' + $_.Exception.Message) WARNING System } catch {}
        }
    }

    function Invoke-AMRSingleElementEntranceAnimation {
        param(
            [object]$Element,
            [int]$DelayMs = 0,
            [int]$DurationMs = 420,
            [double]$OffsetY = 14.0
        )
        try {
            if (-not ($Element -is [System.Windows.UIElement])) { return }
            $transform = $Element.RenderTransform
            if (-not ($transform -is [System.Windows.Media.TranslateTransform])) {
                $transform = New-Object System.Windows.Media.TranslateTransform
                $Element.RenderTransform = $transform
            }
            $Element.Opacity = 0.0
            $ease = New-Object System.Windows.Media.Animation.CubicEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $fade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $fade.From = 0.0; $fade.To = 1.0
            $fade.Duration = [TimeSpan]::FromMilliseconds($DurationMs)
            $fade.BeginTime = [TimeSpan]::FromMilliseconds([Math]::Max(0,$DelayMs))
            $fade.EasingFunction = $ease

            $rise = New-Object System.Windows.Media.Animation.DoubleAnimation
            $rise.From = $OffsetY; $rise.To = 0.0
            $rise.Duration = [TimeSpan]::FromMilliseconds($DurationMs)
            $rise.BeginTime = [TimeSpan]::FromMilliseconds([Math]::Max(0,$DelayMs))
            $rise.EasingFunction = $ease

            $Element.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
            $transform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$rise,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
        } catch {}
    }

    function Invoke-AMRContainerEntranceAnimation {
        param([object]$Root,[int]$StepDelayMs = 48,[int]$DurationMs = 440)
        try {
            if (-not $Root) { return }
            # Unwrap common WPF content containers without traversing every visual in the tree.
            $container = $Root
            for ($depth=0; $depth -lt 4; $depth++) {
                if ($container -is [System.Windows.Controls.ScrollViewer]) { $container = $container.Content; continue }
                if ($container -is [System.Windows.Controls.Border]) { $container = $container.Child; continue }
                if ($container -is [System.Windows.Controls.ContentControl] -and
                    -not ($container -is [System.Windows.Controls.TabItem])) { $container = $container.Content; continue }
                break
            }
            if ($container -is [System.Windows.Controls.Panel]) {
                $items = @($container.Children)
            } elseif ($container -is [System.Windows.Controls.Decorator] -and $container.Child) {
                $items = @($container.Child)
            } else {
                $items = @($container)
            }
            $index = 0
            foreach ($item in $items) {
                if ($item -is [System.Windows.UIElement]) {
                    Invoke-AMRSingleElementEntranceAnimation -Element $item -DelayMs ($index * $StepDelayMs) -DurationMs $DurationMs -OffsetY 13
                    $index++
                }
            }
        } catch {}
    }

    function Invoke-AMRToolKitEntranceAnimation {
    param([object]$TabItem)

    try {
        if (-not $TabItem) { return }

        $tabName = [string]$TabItem.Header
        if ($tabName -notin @('Optimize','Security','System','Networks','Utilities')) { return }

        if (-not $script:AMRToolKitEntrancePlayed) {
            $script:AMRToolKitEntrancePlayed = @{}
        }
        if ($script:AMRToolKitEntrancePlayed.ContainsKey($tabName)) { return }

        # Animate only the selected page's existing ScrollViewer root.
        # No card creation, layout changes, timers, or Dispatcher work is involved.
        $root = $TabItem.Content
        if (-not ($root -is [System.Windows.UIElement])) { return }

        $translate = New-Object System.Windows.Media.TranslateTransform
        $root.RenderTransform = $translate

        $ease = New-Object System.Windows.Media.Animation.QuadraticEase
        $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

        $fade = New-Object System.Windows.Media.Animation.DoubleAnimation
        $fade.From = 0.96
        $fade.To = 1.0
        $fade.Duration = [TimeSpan]::FromMilliseconds(360)
        $fade.EasingFunction = $ease

        $rise = New-Object System.Windows.Media.Animation.DoubleAnimation
        $rise.From = 8.0
        $rise.To = 0.0
        $rise.Duration = [TimeSpan]::FromMilliseconds(360)
        $rise.EasingFunction = $ease

        $root.BeginAnimation(
            [System.Windows.UIElement]::OpacityProperty,
            $fade,
            [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
        )
        $translate.BeginAnimation(
            [System.Windows.Media.TranslateTransform]::YProperty,
            $rise,
            [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
        )

        # Remember only after both animations have been successfully started.
        # Returning to this sub-tab will not replay the entrance.
        $script:AMRToolKitEntrancePlayed[$tabName] = $true
    } catch {
        try { Write-AMRLog ("Tool Kit entrance animation skipped for {0}: {1}" -f $tabName,$_.Exception.Message) WARNING System } catch {}
    }
}

    # Control Center group: the six pages are sidebar items under the Control Center entry.
    # They drop down (height + fade, short stagger) when the group opens and fold back when another Tool Kit page is chosen.
    $script:AMRControlCenterState = @{ Open = $false; Token = 0; Last = 'Optimize' }
    function Get-AMRControlCenterChildren {
        $kit = C 'ToolKitSubTabs'
        if (-not $kit) { return @() }
        return @($kit.Items | Where-Object { $_ -is [System.Windows.Controls.TabItem] -and [string]$_.Tag -eq 'CCChild' })
    }
    function Set-AMRControlCenterGroup {
        param([bool]$Open)
        try {
            $state = $script:AMRControlCenterState
            if ([bool]$state.Open -eq $Open) { return }
            $state.Open = $Open
            $state.Token = [int]$state.Token + 1
            $token = [int]$state.Token
            $isOpen = $Open
            $items = @(Get-AMRControlCenterChildren)
            $parent = C 'ToolKitControlTab'
            if ($parent) {
                $glyph = if ($Open) { [char]0x25BE } else { [char]0x25B8 }
                $parent.Header = ([string]$script:AMRControlTabName + '  ' + [string]$glyph)
                if ($Open) {
                    $parent.Background = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#4B30567E')
                    $parent.Foreground = (New-Object System.Windows.Media.BrushConverter).ConvertFromString('#EAF2FF')
                } else {
                    $parent.ClearValue([System.Windows.Controls.Control]::BackgroundProperty)
                    $parent.ClearValue([System.Windows.Controls.Control]::ForegroundProperty)
                }
            }
            $count = $items.Count
            if ($count -eq 0) { return }
            $ease = New-Object System.Windows.Media.Animation.QuadraticEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $ms = if ($Open) { 230 } else { 170 }
            $lastAnim = $null
            for ($n = 0; $n -lt $count; $n++) {
                $it = $items[$n]
                if ($Open -and $it.Visibility -ne [System.Windows.Visibility]::Visible) {
                    $it.LayoutTransform = New-Object System.Windows.Media.ScaleTransform(1.0, 0.0)
                    $it.Opacity = 0.0
                    $it.Margin = New-Object System.Windows.Thickness(0, 0, 0, 0)
                    $it.Visibility = [System.Windows.Visibility]::Visible
                }
                $scale = $it.LayoutTransform -as [System.Windows.Media.ScaleTransform]
                if (-not $scale) {
                    $scale = New-Object System.Windows.Media.ScaleTransform(1.0, 1.0)
                    $it.LayoutTransform = $scale
                }
                $order = if ($Open) { $n } else { $count - 1 - $n }
                $begin = [TimeSpan]::FromMilliseconds(26 * $order)
                $toScale = if ($Open) { 1.0 } else { 0.0 }
                $toMargin = if ($Open) { 8.0 } else { 0.0 }

                $aScale = New-Object System.Windows.Media.Animation.DoubleAnimation
                $aScale.To = $toScale
                $aScale.Duration = [TimeSpan]::FromMilliseconds($ms)
                $aScale.BeginTime = $begin
                $aScale.EasingFunction = $ease
                $aFade = New-Object System.Windows.Media.Animation.DoubleAnimation
                $aFade.To = $toScale
                $aFade.Duration = [TimeSpan]::FromMilliseconds($ms)
                $aFade.BeginTime = $begin
                $aFade.EasingFunction = $ease
                $aMargin = New-Object System.Windows.Media.Animation.ThicknessAnimation
                $aMargin.To = New-Object System.Windows.Thickness(0, 0, 0, $toMargin)
                $aMargin.Duration = [TimeSpan]::FromMilliseconds($ms)
                $aMargin.BeginTime = $begin
                $aMargin.EasingFunction = $ease

                $scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $aScale, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
                $it.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $aFade, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
                $it.BeginAnimation([System.Windows.FrameworkElement]::MarginProperty, $aMargin, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
                if ($order -eq ($count - 1)) { $lastAnim = $aMargin }
            }
            if ($lastAnim) {
                # Runs when the last (latest-starting) item finishes: drop the animation clocks and set the resting values.
                # Only locals are used inside the closure (script-scope variables do not resolve there).
                $lastAnim.Add_Completed({
                    param($sender, $evt)
                    if ([int]$state.Token -ne $token) { return }
                    foreach ($x in $items) {
                        $x.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
                        $x.BeginAnimation([System.Windows.FrameworkElement]::MarginProperty, $null)
                        $sc = $x.LayoutTransform -as [System.Windows.Media.ScaleTransform]
                        if ($sc) { $sc.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null) }
                        $x.LayoutTransform = [System.Windows.Media.Transform]::Identity
                        $x.Opacity = 1.0
                        $x.Margin = New-Object System.Windows.Thickness(0, 0, 0, 8)
                        if (-not $isOpen) { $x.Visibility = [System.Windows.Visibility]::Collapsed }
                    }
                }.GetNewClosure())
            }
        } catch {
            try { Write-AMRLog ("Control Center group animation fallback: " + $_.Exception.Message) WARNING System } catch {}
            try {
                foreach ($x in @(Get-AMRControlCenterChildren)) {
                    $x.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
                    $x.BeginAnimation([System.Windows.FrameworkElement]::MarginProperty, $null)
                    $x.LayoutTransform = [System.Windows.Media.Transform]::Identity
                    $x.Opacity = 1.0
                    $x.Margin = New-Object System.Windows.Thickness(0, 0, 0, 8)
                    $x.Visibility = if ($Open) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
                }
            } catch {}
        }
    }
    function Invoke-AMRControlCenterEntered {
        try {
            $kit = C 'ToolKitSubTabs'
            if (-not $kit -or -not $kit.SelectedItem) { return }
            if ([string]$kit.SelectedItem.Header -eq 'Backup' -and [string]$kit.SelectedItem.Tag -eq 'CCChild') { Request-AMRBackupViewRefresh }
        } catch {}
    }

$kitTabs = C 'ToolKitSubTabs'
    if ($kitTabs) {
        $script:AMRToolKitEntrancePlayed = @{}
        $kitTabs.Add_SelectionChanged({
            # Only process a selection made by ToolKitSubTabs itself.
            if ($_.OriginalSource -ne $this) { return }
            $selItem = $this.SelectedItem
            if ($selItem) {
                if ([object]::ReferenceEquals($selItem,(C 'ToolKitControlTab'))) {
                    # Control Center entry: open its group and land on the last used page (Optimize the first time).
                    Set-AMRControlCenterGroup -Open $true
                    $wanted = $null
                    $kids = @(Get-AMRControlCenterChildren)
                    foreach ($k in $kids) { if ([string]$k.Header -eq [string]$script:AMRControlCenterState.Last) { $wanted = $k } }
                    if (-not $wanted -and $kids.Count -gt 0) { $wanted = $kids[0] }
                    if ($wanted) { $this.SelectedItem = $wanted; return }
                } elseif ([string]$selItem.Tag -eq 'CCChild') {
                    $script:AMRControlCenterState.Last = [string]$selItem.Header
                    Set-AMRControlCenterGroup -Open $true
                } else {
                    Set-AMRControlCenterGroup -Open $false
                }
            }
            $perfKit = Get-AMRPerfNow
            Invoke-AMRNavigationTilePressAnimation -Element $this.SelectedItem
            Add-AMRPerfSince 'kit.sel.pressAnim' $perfKit
            $perfKit = Get-AMRPerfNow
            Update-AMRSmartSearchContext
            Add-AMRPerfSince 'kit.sel.smartContext' $perfKit
            $perfKit = Get-AMRPerfNow
            Invoke-AMRToolKitEntranceAnimation -TabItem $this.SelectedItem
            Add-AMRPerfSince 'kit.sel.entranceAnim' $perfKit
            $perfKit = Get-AMRPerfNow
            Invoke-AMRControlCenterEntered
            Add-AMRPerfSince 'kit.sel.entered' $perfKit
        })
    }
    function Invoke-AMRCleanupSubTabAnimation {
        param([object]$TabItem)

        try {
            if (-not $TabItem) { return }

            $tabName = [string]$TabItem.Header
            $targetName = switch ($tabName) {
                'Smart'                     { 'CleanupSmartItemsScrollViewer'; break }
                'Disk Tools'                { 'CleanupAdvancedReport'; break }
                'Organizers'                { 'CleanupDiskOrganizerList'; break }
                'Web & Browsers'            { 'CleanupBrowserInfoPanel'; break }
                'Orphan Cleanup'            { 'CleanupOrphanListsPanel'; break }
                'Windows Component Cleanup' { 'CleanupComponentReportNew'; break }
                default                     { $null }
            }
            if (-not $targetName) { return }

            # Selection feedback is limited to the selected tile; RenderTransform does not affect layout.
            $tileTransform = $TabItem.RenderTransform
            if (-not ($tileTransform -is [System.Windows.Media.TranslateTransform])) {
                $tileTransform = New-Object System.Windows.Media.TranslateTransform
                $TabItem.RenderTransform = $tileTransform
            }

            $tileEase = New-Object System.Windows.Media.Animation.QuadraticEase
            $tileEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $tileMove = New-Object System.Windows.Media.Animation.DoubleAnimation
            $tileMove.From = 4.0
            $tileMove.To = 0.0
            $tileMove.Duration = [TimeSpan]::FromMilliseconds(220)
            $tileMove.EasingFunction = $tileEase
            $tileTransform.BeginAnimation(
                [System.Windows.Media.TranslateTransform]::XProperty,
                $tileMove,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )

            $tileFade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $tileFade.From = 0.90
            $tileFade.To = 1.0
            $tileFade.Duration = [TimeSpan]::FromMilliseconds(220)
            $tileFade.EasingFunction = $tileEase
            $TabItem.BeginAnimation(
                [System.Windows.UIElement]::OpacityProperty,
                $tileFade,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )

            if ($null -eq $script:AMRCleanupEntrancePlayed) {
                $script:AMRCleanupEntrancePlayed = @{}
            }
            # A3: the Smart page entrance replays on every entry; the other sub-tabs keep the once-per-session behavior.
            if ($tabName -ne 'Smart' -and $script:AMRCleanupEntrancePlayed.ContainsKey($tabName)) { return }

            $target = C $targetName
            if (-not ($target -is [System.Windows.UIElement])) { return }

            $contentTransform = New-Object System.Windows.Media.TranslateTransform
            $target.RenderTransform = $contentTransform

            $contentEase = New-Object System.Windows.Media.Animation.QuadraticEase
            $contentEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $contentFade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $contentFade.From = 0.94
            $contentFade.To = 1.0
            $contentFade.Duration = [TimeSpan]::FromMilliseconds(320)
            $contentFade.EasingFunction = $contentEase

            $contentRise = New-Object System.Windows.Media.Animation.DoubleAnimation
            $contentRise.From = 7.0
            $contentRise.To = 0.0
            $contentRise.Duration = [TimeSpan]::FromMilliseconds(320)
            $contentRise.EasingFunction = $contentEase

            $target.BeginAnimation(
                [System.Windows.UIElement]::OpacityProperty,
                $contentFade,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )
            $contentTransform.BeginAnimation(
                [System.Windows.Media.TranslateTransform]::YProperty,
                $contentRise,
                [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace
            )

            # Content enters once per sub-tab; returning does not replay or rebuild it.
            $script:AMRCleanupEntrancePlayed[$tabName] = $true
        } catch {
            try { Write-AMRLog ("Cleanup entrance animation skipped for {0}: {1}" -f $tabName,$_.Exception.Message) WARNING Cleanup } catch {}
        }
    }

    # Match the Tweaks checkmark feedback on the seven selectable Smart Cleanup rows.
    $cleanupSmartCheckNames = @(
        'CleanupUserTempCheck',
        'CleanupWindowsTempCheck',
        'CleanupUpdateCheck',
        'CleanupWerCheck',
        'CleanupShaderCheck',
        'CleanupAppCacheCheck',
        'CleanupDeliveryCheck'
    )
    foreach ($checkName in $cleanupSmartCheckNames) {
        $cleanupCheck = C $checkName
        if (-not ($cleanupCheck -is [System.Windows.Controls.CheckBox])) { continue }

        $rowElement = [System.Windows.LogicalTreeHelper]::GetParent($cleanupCheck)
        while ($rowElement -and -not ($rowElement -is [System.Windows.Controls.Border])) {
            $rowElement = [System.Windows.LogicalTreeHelper]::GetParent($rowElement)
        }
        if (-not ($rowElement -is [System.Windows.Controls.Border])) { continue }
        if (-not ($rowElement.Background -is [System.Windows.Media.SolidColorBrush])) { continue }

        $baseRowColor = $rowElement.Background.Color
        $selectedRowColor = [System.Windows.Media.Color]::FromArgb(72,49,130,190)

        $cleanupCheck.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
        $cleanupCheckScale = New-Object System.Windows.Media.ScaleTransform(1,1)
        $cleanupCheck.RenderTransform = $cleanupCheckScale

        $cleanupCheck.Add_Checked({
            $pop = New-Object System.Windows.Media.Animation.DoubleAnimation(
                0.91,1.0,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(160))
            )
            $ease = New-Object System.Windows.Media.Animation.BackEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $ease.Amplitude = 1.25
            $pop.EasingFunction = $ease
            $cleanupCheckScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$pop)
            $cleanupCheckScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$pop)

            $colorAnim = New-Object System.Windows.Media.Animation.ColorAnimation(
                $selectedRowColor,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(180))
            )
            $rowElement.Background.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$colorAnim)
        }.GetNewClosure())

        $cleanupCheck.Add_Unchecked({
            $pop = New-Object System.Windows.Media.Animation.DoubleAnimation(
                1.03,1.0,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(130))
            )
            $pop.EasingFunction = New-Object System.Windows.Media.Animation.QuadraticEase
            $cleanupCheckScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$pop)
            $cleanupCheckScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$pop)

            $colorAnim = New-Object System.Windows.Media.Animation.ColorAnimation(
                $baseRowColor,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(160))
            )
            $rowElement.Background.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$colorAnim)
        }.GetNewClosure())
    }

    $cleanupTabs = C 'CleanupSubTabs'
    if ($cleanupTabs) {
        $script:AMRCleanupEntrancePlayed = @{}
        $cleanupTabs.Add_SelectionChanged({
            if ($_.OriginalSource -ne $this) { return }
            Invoke-AMRCleanupSubTabAnimation -TabItem $this.SelectedItem
        })
    }

    if ($mainTabs) {
        $mainTabs.Add_SelectionChanged({
            if ($_.OriginalSource -ne $this) { return }
            $activeSection = if ($this.SelectedItem) { [string]$this.SelectedItem.Header } else { '' }
            Invoke-AMRMainPageSizeTransition -TabItem $this.SelectedItem
            if($activeSection -ne 'Backups'){$script:AMRBackupEntranceLastKey=$null}
            if ($activeSection -eq 'Cleanup') {
                $activeCleanupTabs = C 'CleanupSubTabs'
                if ($activeCleanupTabs -and $activeCleanupTabs.SelectedItem) {
                    Invoke-AMRCleanupSubTabAnimation -TabItem $activeCleanupTabs.SelectedItem
                }
            } elseif ($activeSection -eq 'System') {
                $activeSystemTabs = C 'OverviewSubTabs'
                if ($activeSystemTabs -and $activeSystemTabs.SelectedItem) {
                    # Keep navigation immediate while giving the selected page a subtle root-only transition.
                    $perfMainSel = Get-AMRPerfNow
                    Invoke-AMRNavigationTilePressAnimation -Element $activeSystemTabs.SelectedItem
                    Invoke-AMRSystemPageTransition -TabItem $activeSystemTabs.SelectedItem
                    Add-AMRPerfSince 'ov.main.tileAndTransition' $perfMainSel
                    if ([string]$activeSystemTabs.SelectedItem.Header -eq 'Overview') {
                        try {
                            $perfOv = Get-AMRPerfNow
                            Set-AMRPerfMark 'overview.entryTelemetry(main)'
                            Start-AMROverviewTelemetry -Force
                            Add-AMRPerfSince 'ov.main.telemetryForce' $perfOv
                            $overviewState = $script:OverviewTelemetryState
                            if ($overviewState -and -not $overviewState.InventoryCurrent -and
                                ((Get-Date) - $overviewState.LastInventoryRefresh).TotalSeconds -ge $overviewState.InventoryIntervalSeconds) {
                                $overviewState.LastInventoryRefresh = Get-Date
                                $perfOv = Get-AMRPerfNow
                                Start-AMROverviewInventoryRefresh
                                Add-AMRPerfSince 'ov.main.inventoryRefreshStart' $perfOv
                            }
                            $overviewStatus = C 'ovLiveRefreshStatus'
                            if ($overviewStatus) { $overviewStatus.Text = 'Refreshing live system readings…' }
                        } catch {
                            try { Write-AMRLog ('Overview entry refresh could not start: ' + $_.Exception.Message) WARNING Overview } catch {}
                        }
                    }
                }
            } elseif ($activeSection -eq 'Tool Kit') {
                # A4: same small tile slide-in System uses when its main tab is entered (same helper, same values).
                $activeKitTabs = C 'ToolKitSubTabs'
                if ($activeKitTabs -and $activeKitTabs.SelectedItem) {
                    Invoke-AMRNavigationTilePressAnimation -Element $activeKitTabs.SelectedItem
                }
            } elseif ($activeSection -eq 'Backups') {
                $activeBackupTabs = C 'BackupSubTabs'
                if ($activeBackupTabs -and $activeBackupTabs.SelectedItem) {
                    $activeBackupName=[string]$activeBackupTabs.SelectedItem.Header
                    if($script:AMRBackupEntranceLastKey -ne $activeBackupName){
                        $script:AMRBackupEntranceLastKey=$activeBackupName
                    }
                }
            }
        })
    }

    # Initialize Startup navigation state before attaching routed WPF events.
    # Set-StrictMode is enabled, so every script-scoped flag must exist before
    # SelectionChanged can inspect it.
    $script:StartupManagerLoaded = $false
    $script:StartupEntryWorkQueued = $false
    $script:StartupAutoFirstRefreshDone = $false
    $script:StartupRenderState = $null

    # StrictMode-safe state for the approved deferred Startup discovery pipeline.
    $script:StartupAppxState = $null
    $script:StartupTaskState = $null
    $script:StartupCimState = $null
    $script:StartupAppxTimer = $null
    $script:StartupTaskTimer = $null
    $script:StartupCimTimer = $null
    $script:StartupRenderTimer = $null
    $script:StartupIconTimer = $null
    $script:StartupIconQueue = $null
    $script:StartupPackageIconIndex = @{}
    $script:StartupInstalledMatchIndex = $null
    $script:StartupCacheComplete = $false
    $script:StartupInstalledMatchIndexSource = $null
    $script:StartupBrushProto = @{}
    $script:StartupIconFileMaps = @{}
    $script:StartupBrowserShortcutIconIndex = @{}

    $overviewTabs = C 'OverviewSubTabs'
    if ($overviewTabs) {
        $script:AMRSystemEntrancePlayed = @{}
        $overviewTabs.Add_SelectionChanged({
            # Queue Startup's first refresh before filtering routed child events.
            # WPF can report a TabItem/content element as OriginalSource even when
            # OverviewSubTabs itself has changed selection.
            $selectedSystemPage = $this.SelectedItem
            Set-AMRPerfMark ('sel:' + (Get-AMRPerfTabHeader $selectedSystemPage))
            if ($selectedSystemPage -and [string]$selectedSystemPage.Header -eq 'Startups') {
                if (-not $script:StartupAutoFirstRefreshDone -and
                    -not $script:StartupEntryWorkQueued -and
                    -not $script:StartupManagerLoaded -and
                    -not $script:StartupRenderState) {
                    $script:StartupEntryWorkQueued = $true
                    $startupDispatcher = $this.Dispatcher
                    [void]$startupDispatcher.BeginInvoke([System.Action]{
                        try {
                            $activeStartupTabs = C 'OverviewSubTabs'
                            if (-not $activeStartupTabs -or -not $activeStartupTabs.SelectedItem -or
                                [string]$activeStartupTabs.SelectedItem.Header -ne 'Startups') { return }
                            if ($script:StartupManagerLoaded -or $script:StartupRenderState) {
                                $script:StartupAutoFirstRefreshDone = $true
                                return
                            }
                            $startupHostPanel = C 'AMRStartupAppsHost'
                            if (-not $startupHostPanel) { throw 'Startup applications panel is unavailable.' }
                            # Match the real Refresh button action, including its visual
                            # feedback and installed-inventory refresh.
                            $perfFirst = Get-AMRPerfNow
                            Set-AMRPerfMark 'startups.firstRefresh'
                            try { Start-AMRRefreshButtonAnimation -Button (C 'AMRStartupRefreshBtn') } catch {}
                            Add-AMRPerfSince 'startups.refreshButtonAnim' $perfFirst
                            $cachedStartupEntries=$null
                            try { $cachedStartupEntries=Get-AMRStartupCachedEntries } catch {}
                            if ($cachedStartupEntries) {
                                $script:StartupCacheComplete = $true
                                Refresh-AMRStartupManager -Entries $cachedStartupEntries -SkipDeferredCim
                            } else {
                                Refresh-AMRStartupManager -RefreshInventory
                            }
                            Add-AMRPerfSince 'startups.firstRefreshTotalSync' $perfFirst
                            $script:StartupAutoFirstRefreshDone = $true
                        } catch {
                            $script:StartupAutoFirstRefreshDone = $false
                            try { Write-AMRLog ('Startup manager automatic first refresh warning: ' + $_.Exception.Message) WARNING System } catch {}
                        } finally {
                            $script:StartupEntryWorkQueued = $false
                        }
                    }, [System.Windows.Threading.DispatcherPriority]::Background)
                }
            }
            if ($_.OriginalSource -ne $this) { return }
            $perfSel = Get-AMRPerfNow
            Update-AMRSmartSearchContext
            Add-AMRPerfSince 'ov.sel.smartSearchContext' $perfSel
            $selectedSystemPage = $this.SelectedItem
            if ($selectedSystemPage) {
                # Animate only the page surface: subtle, smooth, and layout-neutral.
                $perfSel = Get-AMRPerfNow
                Invoke-AMRNavigationTilePressAnimation -Element $selectedSystemPage
                Add-AMRPerfSince 'ov.sel.tilePressAnim' $perfSel
                $perfSel = Get-AMRPerfNow
                Invoke-AMRSystemPageTransition -TabItem $selectedSystemPage
                Add-AMRPerfSince 'ov.sel.pageTransition' $perfSel

                # Overview must perform a fresh live sample when the user opens it,
                # rather than relying only on the startup snapshot or placeholder text.
                if ([string]$selectedSystemPage.Header -eq 'Overview') {
                    try {
                        $perfOv = Get-AMRPerfNow
                        Set-AMRPerfMark 'overview.entryTelemetry'
                        Start-AMROverviewTelemetry -Force
                        Add-AMRPerfSince 'ov.sel.telemetryForce' $perfOv
                        $overviewState = $script:OverviewTelemetryState
                        if ($overviewState -and -not $overviewState.InventoryCurrent -and
                            ((Get-Date) - $overviewState.LastInventoryRefresh).TotalSeconds -ge $overviewState.InventoryIntervalSeconds) {
                            $overviewState.LastInventoryRefresh = Get-Date
                            $perfOv = Get-AMRPerfNow
                            Start-AMROverviewInventoryRefresh
                            Add-AMRPerfSince 'ov.sel.inventoryRefreshStart' $perfOv
                        }
                        $overviewStatus = C 'ovLiveRefreshStatus'
                        if ($overviewStatus) { $overviewStatus.Text = 'Refreshing live system readings…' }
                    } catch {
                        try { Write-AMRLog ('Overview entry refresh could not start: ' + $_.Exception.Message) WARNING Overview } catch {}
                    }
                }
            }
        })
    }
    $backupTabs = C 'BackupSubTabs'
    if ($backupTabs) {
        $script:AMRBackupEntranceLastKey=$null
        $backupTabs.Add_SelectionChanged({
            if ($_.OriginalSource -ne $this) { return }
            Update-AMRSmartSearchContext
            if ($this.SelectedItem) {
                $activeBackupName=[string]$this.SelectedItem.Header
                if($script:AMRBackupEntranceLastKey -ne $activeBackupName){
                    $script:AMRBackupEntranceLastKey=$activeBackupName
                }
            }
        })
    }
    Update-AMRSmartSearchContext
} catch {
    Write-AMRLog "Smart Search initialization warning: $($_.Exception.Message)" WARNING System
}

$script:Status        = C 'StatusText'
Register-AMRExceptionHandlers
$script:ProgressBar   = C 'InstallProgressBar'
$script:ProgressText  = C 'ProgressText'

try {
    $cleanupSearch = C 'CleanupSearchBox'
    if ($cleanupSearch) {
        $cleanupSearch.Add_TextChanged({
            $query = ([string](C 'CleanupSearchBox').Text).Trim()
            $candidateNames = @('CleanupUserTempCheck','CleanupWindowsTempCheck','CleanupUpdateCheck','CleanupWerCheck','CleanupShaderCheck','CleanupDeliveryCheck')
            foreach ($controlName in $candidateNames) {
                $control = C $controlName
                if (-not $control) { continue }
                $label = [string]$control.Content
                $match = [string]::IsNullOrWhiteSpace($query) -or $label.IndexOf($query,[System.StringComparison]::OrdinalIgnoreCase) -ge 0
                $control.Visibility = if ($match) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            }
        })
    }
} catch {
    Write-AMRLog "Cleanup Smart Search filter warning: $($_.Exception.Message)" WARNING Cleanup
}

$script:LogControls['All']       = C 'LogConsoleAll'
$script:LogControls['System']    = C 'LogConsoleSystem'
$script:LogControls['Overview']  = C 'LogConsoleOverview'
$script:LogControls['Software']  = C 'LogConsoleSoftware'
$script:LogControls['Customize'] = C 'LogConsoleCustomize'
$script:LogControls['Tweaks']    = C 'LogConsoleTweaks'
$script:LogControls['Cleanup']   = C 'LogConsoleCleanup'
$script:LogControls['Tools']     = C 'LogConsoleTools'
$script:DriverLogConsole = C 'DriverLogConsole'

# Logs suite micro-interactions. Reuse the restrained Activation copy-button motion
# (same scale, timing and soft glow), while preserving each Logs button's own colors.
try {
    $logInteractiveButtonNames = @(
        'LogCopyAllBtn','LogCopySystemBtn','LogCopyToolsBtn','LogCopyOverviewBtn',
        'LogCopySoftwareBtn','LogCopyCustomizeBtn','LogCopyTweaksBtn','LogCopyCleanupBtn',
        'ExportLogsBtn','LogShowAllBtn','ClearAllLogsBtn','DriverLogRefreshBtn','DriverLogCopyBtn','DriverLogExportBtn'
    )
    foreach ($logButtonName in $logInteractiveButtonNames) {
        $logButton = C $logButtonName
        if ($logButton -and $logButton -is [System.Windows.Controls.Button]) {
            Set-AMRActivationCopyButtonMotion -Button $logButton
            # PreviewMouseDown gives immediate tactile feedback for every action,
            # including refresh/export/clear, without changing their click handlers.
            $logButton.Add_PreviewMouseDown({
                param($sender,$eventArgs)
                Invoke-AMRActivationCopyButtonFeedback -Button $sender
            }.GetNewClosure())
        }
    }

    # The Driver severity selector (whose first item is All) already has its own
    # face-color hover triggers. Add only a tiny lift/settle to make the selector
    # feel responsive without changing the selected value or popup behavior.
    $driverSeveritySelector = C 'DriverLogSeverityFilter'
    if ($driverSeveritySelector) {
        $driverSeveritySelector.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
        $driverSeverityScale = New-Object System.Windows.Media.ScaleTransform(1.0,1.0)
        $driverSeveritySelector.RenderTransform = $driverSeverityScale
        $driverSeveritySelector.Add_MouseEnter({
            $a = [System.Windows.Media.Animation.DoubleAnimation]::new(1.0,1.025,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(135)))
            $a.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
            $a.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $driverSeverityScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a)
            $driverSeverityScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a)
        }.GetNewClosure())
        $driverSeveritySelector.Add_MouseLeave({
            $a = [System.Windows.Media.Animation.DoubleAnimation]::new(1.025,1.0,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(155)))
            $a.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
            $a.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $driverSeverityScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a)
            $driverSeverityScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a)
        }.GetNewClosure())
    }
} catch {
    Write-AMRLog ('Logs interaction setup warning: ' + $_.Exception.Message) WARNING System
}

# Copy buttons for the standard log consoles (Driver Center keeps its existing Copy Visible button).
$logCopyTargets = @{
    'LogCopyAllBtn'='All'; 'LogCopySystemBtn'='System'; 'LogCopyOverviewBtn'='Overview';
    'LogCopySoftwareBtn'='Software'; 'LogCopyCustomizeBtn'='Customize';
    'LogCopyTweaksBtn'='Tweaks'; 'LogCopyCleanupBtn'='Cleanup'; 'LogCopyToolsBtn'='Tools'
}
foreach ($buttonName in $logCopyTargets.Keys) {
    $copyButton = C $buttonName
    $targetKey = [string]$logCopyTargets[$buttonName]
    if ($copyButton) {
        $copyButton.Add_Click({
            $target = $script:LogControls[$targetKey]
            try {
                if ($target -and -not [string]::IsNullOrEmpty([string]$target.Text)) {
                    [System.Windows.Clipboard]::SetText([string]$target.Text)
                    Write-AMRLog ("Copied the visible {0} log console." -f $targetKey) SUCCESS System
                } else {
                    Show-AMRMessageGlass 'There is no log text to copy yet.' 'Copy Logs' OK Information | Out-Null
                }
            } catch {
                Show-AMRMessageGlass ('Could not copy log text: ' + $_.Exception.Message) 'Copy Logs' OK Warning | Out-Null
            }
        }.GetNewClosure())
    }
}

# Each session starts with empty in-app consoles and shows only its own lines. The daily log
# file is not read back into the UI (it stays fully written by the background disk writer).

Start-AMRLogUIPump
$script:Window.Add_Closed({
    # Stop the active Cleanup worker before releasing the window. A closed window
    # must never leave a previous scan alive or let a later launch inherit stale work.
    try {
        $cleanupJob = $script:AMRCleanupScanState.Current
        if ($cleanupJob) {
            try { Write-AMRLog ('Cleanup scan session ' + [string]$cleanupJob.ScanId + ' cancelled because its window was closed; a future launch must start a new scan.') WARNING Cleanup } catch {}
            try { Write-AMRCleanupTrace ('Scan cancelled on window close. Session=' + [string]$cleanupJob.ScanId) 'WARNING' } catch {}
            if ($cleanupJob.Timer) { try { $cleanupJob.Timer.Stop() } catch {} }
            if ($cleanupJob.PowerShell) { try { $cleanupJob.PowerShell.Stop() } catch {}; try { $cleanupJob.PowerShell.Dispose() } catch {} }
            if ($cleanupJob.Runspace) { try { $cleanupJob.Runspace.Close() } catch {}; try { $cleanupJob.Runspace.Dispose() } catch {} }
            $script:AMRCleanupScanState.Current = $null
        }
    } catch {}
    # Stop window-scoped DispatcherTimers before releasing the UI and its worker.
    if ($script:LogUIFlushTimer) {
        try { $script:LogUIFlushTimer.Stop() } catch {}
        $script:LogUIFlushTimer = $null
    }
    if ($script:DriverLogRefreshTimer) {
        try { $script:DriverLogRefreshTimer.Stop() } catch {}
        $script:DriverLogRefreshTimer = $null
    }
    # Stop Startup-only background discovery and deferred icon work with the window.
    try { if ($script:StartupIconTimer) { $script:StartupIconTimer.Stop(); $script:StartupIconTimer = $null } } catch {}
    try { if ($script:StartupRenderTimer) { $script:StartupRenderTimer.Stop(); $script:StartupRenderTimer = $null }; $script:StartupRenderState = $null } catch {}
    try {
        $startupState = $script:StartupManagerAsyncState
        if ($startupState) {
            if ($startupState.Timer) { try { $startupState.Timer.Stop() } catch {}; $startupState.Timer = $null }
            $startupJob = $startupState.Current
            if ($startupJob) {
                if ($startupJob.PowerShell) { try { $startupJob.PowerShell.Stop() } catch {}; try { $startupJob.PowerShell.Dispose() } catch {} }
                if ($startupJob.Runspace) { try { $startupJob.Runspace.Close() } catch {}; try { $startupJob.Runspace.Dispose() } catch {} }
                $startupState.Current = $null
            }
        }
    } catch {}
    if ($script:OverviewTelemetryState) {
        if ($script:OverviewTelemetryState.Timer) { try { $script:OverviewTelemetryState.Timer.Stop() } catch {}; $script:OverviewTelemetryState.Timer = $null }
        $overviewJob = $script:OverviewTelemetryState.Current
        if ($overviewJob) { if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($overviewJob.PowerShell,$overviewJob.Runspace)}else{try{$overviewJob.PowerShell.Stop()}catch{};try{$overviewJob.PowerShell.Dispose()}catch{};try{$overviewJob.Runspace.Close()}catch{};try{$overviewJob.Runspace.Dispose()}catch{}}; $script:OverviewTelemetryState.Current = $null; $script:OverviewTelemetryState.FastRunspace=$null; $script:OverviewTelemetryState.FastRunspaceInitialized=$false }
        $fastRunspace=$script:OverviewTelemetryState.FastRunspace
        if($fastRunspace){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($null,$fastRunspace)}else{try{$fastRunspace.Close()}catch{};try{$fastRunspace.Dispose()}catch{}};$script:OverviewTelemetryState.FastRunspace=$null;$script:OverviewTelemetryState.FastRunspaceInitialized=$false}
        $diskJob=$script:OverviewTelemetryState.DiskCurrent
        if($diskJob){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($diskJob.PowerShell,$diskJob.Runspace)}else{try{$diskJob.PowerShell.Stop()}catch{};try{$diskJob.PowerShell.Dispose()}catch{};try{$diskJob.Runspace.Close()}catch{};try{$diskJob.Runspace.Dispose()}catch{}};$script:OverviewTelemetryState.DiskCurrent=$null}
        $activityJob=$script:OverviewTelemetryState.ActivityCurrent
        if($activityJob){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($activityJob.PowerShell,$activityJob.Runspace)}else{try{$activityJob.PowerShell.Stop()}catch{};try{$activityJob.PowerShell.Dispose()}catch{};try{$activityJob.Runspace.Close()}catch{};try{$activityJob.Runspace.Dispose()}catch{}};$script:OverviewTelemetryState.ActivityCurrent=$null}
        $inventoryJob=$script:OverviewTelemetryState.InventoryCurrent
        if($inventoryJob){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($inventoryJob.PowerShell,$inventoryJob.Runspace)}else{try{$inventoryJob.PowerShell.Stop()}catch{};try{$inventoryJob.PowerShell.Dispose()}catch{};try{$inventoryJob.Runspace.Close()}catch{};try{$inventoryJob.Runspace.Dispose()}catch{}};$script:OverviewTelemetryState.InventoryCurrent=$null}
        $gpuJob=$script:OverviewTelemetryState.GpuCurrent
        if($gpuJob){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($gpuJob.PowerShell,$gpuJob.Runspace)}else{try{$gpuJob.PowerShell.Stop()}catch{};try{$gpuJob.PowerShell.Dispose()}catch{};try{$gpuJob.Runspace.Close()}catch{};try{$gpuJob.Runspace.Dispose()}catch{}};$script:OverviewTelemetryState.GpuCurrent=$null}
        $networkJob=$script:OverviewTelemetryState.NetworkCurrent
        if($networkJob){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($networkJob.PowerShell,$networkJob.Runspace)}else{try{$networkJob.PowerShell.Stop()}catch{};try{$networkJob.PowerShell.Dispose()}catch{};try{$networkJob.Runspace.Close()}catch{};try{$networkJob.Runspace.Dispose()}catch{}};$script:OverviewTelemetryState.NetworkCurrent=$null}
        # Idle persistent sensor runspaces (a runspace that still belongs to a running job was queued above).
        try { foreach($statKey in @($script:OverviewSensorRunspaceStats.Keys)){ $statItem=$script:OverviewSensorRunspaceStats[$statKey]; Write-AMRLog ('LIVE_SENSOR [Runspace] shutdown key={0} created={1} reused={2} stillRegistered={3}' -f $statKey,$statItem.Created,$statItem.Reused,$script:OverviewSensorRunspaces.ContainsKey($statKey)) INFO Overview } } catch {}
        foreach($sensorKey in @($script:OverviewSensorRunspaces.Keys)){
            $sensorRunspace=$script:OverviewSensorRunspaces[$sensorKey]
            $alreadyQueued=$false
            foreach($closingJob in @($diskJob,$activityJob,$gpuJob,$networkJob)){if($closingJob -and [object]::ReferenceEquals($closingJob.Runspace,$sensorRunspace)){$alreadyQueued=$true}}
            if($sensorRunspace -and -not $alreadyQueued){if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($null,$sensorRunspace)}else{try{$sensorRunspace.Close()}catch{};try{$sensorRunspace.Dispose()}catch{}}}
        }
        $script:OverviewSensorRunspaces.Clear()
    }
    if ($script:IconRefreshTimer) {
        try { $script:IconRefreshTimer.Stop() } catch {}
        $script:IconRefreshTimer = $null
    }

    # The icon worker is window-owned. Cancel an in-flight invocation and release
    # its PowerShell/runspace handles so closing the window cannot leave it running.
    if ($script:IconRefreshPowerShell) {
        try { $script:IconRefreshPowerShell.Stop() } catch {}
        try { $script:IconRefreshPowerShell.Dispose() } catch {}
        $script:IconRefreshPowerShell = $null
    }
    if ($script:IconRefreshRunspace) {
        try { $script:IconRefreshRunspace.Close() } catch {}
        try { $script:IconRefreshRunspace.Dispose() } catch {}
        $script:IconRefreshRunspace = $null
    }
    $script:IconRefreshAsync = $null
    $script:IconRefreshReadyQueue = $null
    $script:IconRefreshStarted = $false

    # Stop the installed-inventory background runspace when the owning window closes.
    try {
        $installedJob = $script:InstalledScanState.Current
        if ($installedJob) {
            if ($installedJob.Timer) { try { $installedJob.Timer.Stop() } catch {} }
            if ($installedJob.PowerShell) {
                try { $installedJob.PowerShell.Stop() } catch {}
                try { $installedJob.PowerShell.Dispose() } catch {}
            }
            if ($installedJob.Runspace) {
                try { $installedJob.Runspace.Close() } catch {}
                try { $installedJob.Runspace.Dispose() } catch {}
            }
            $script:InstalledScanState.Current = $null
        }
    } catch {}
    # Session end line (with open duration) goes to the same daily log file, then the disk queue is flushed.
    try {
        $sessionOpen = (Get-Date) - $script:AMRSessionStartedAt
        [AMRLogDiskWriter]::Enqueue(('[{0}] [INFO] [System] ===== SESSION END | Id={1} | OpenDuration={2:00}:{3:00}:{4:00} =====' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'),$script:AMRSessionId,[int][math]::Floor($sessionOpen.TotalHours),$sessionOpen.Minutes,$sessionOpen.Seconds))
    } catch {}
    # Flush the independent disk queue only after all window-owned workers are stopped.
    try { [AMRLogDiskWriter]::Shutdown() } catch {}
})

