# Native P/Invoke is compiled inside the persistent fast-sampler runspace below.
# PowerShell session state is isolated per runspace; do not assume Add-Type in the UI
# runspace makes a type available to a background runspace.
# Queue potentially blocking Runspace.Stop/Close work away from the WPF Dispatcher.
try {
    if (-not ('AMRRunspaceCleanupV1' -as [type])) {
        Add-Type -TypeDefinition @"
using System;
using System.Management.Automation;
using System.Management.Automation.Runspaces;
using System.Threading;
public static class AMRRunspaceCleanupV1 {
    public static void Queue(PowerShell powerShell, Runspace runspace) {
        ThreadPool.QueueUserWorkItem(delegate(object state) {
            object[] items = (object[])state;
            PowerShell ps = (PowerShell)items[0];
            Runspace rs = (Runspace)items[1];
            try { if (ps != null) ps.Stop(); } catch { }
            try { if (ps != null) ps.Dispose(); } catch { }
            try { if (rs != null) rs.Close(); } catch { }
            try { if (rs != null) rs.Dispose(); } catch { }
        }, new object[] { powerShell, runspace });
    }
}
"@ -ErrorAction Stop | Out-Null
    }
} catch {
    Write-AMRLog ('LIVE_SENSOR [Cleanup] asynchronous runspace cleanup helper unavailable: ' + $_.Exception.Message) WARNING Overview
}

# --- 6. OVERVIEW TELEMETRY ENGINE ---
# All provider-backed queries run in a dedicated MTA runspace. The WPF dispatcher
# only receives a completed snapshot, so slow OEM/WMI providers cannot freeze the UI.
$script:OverviewTelemetryState = [pscustomobject]@{
    Current = $null
    # The fast sampler owns a persistent runspace so its native bridge is compiled
    # once in the same PowerShell session that executes the sampling script.
    FastRunspace = $null
    FastRunspaceInitialized = $false
    FastWorkerFailures = 0
    LastFastWorkerError = ''
    InventoryCurrent = $null
    Timer = $null
    NextRefresh = [DateTime]::MinValue
    RefreshRequested = $false
    StartedAt = [DateTime]::MinValue
    IntervalSeconds = 0.75
    PreviousCpuSample = $null
    LastInternetProbe = [DateTime]::MinValue
    LastInternetReachable = $null
    NetworkCurrent = $null
    NetworkLastSample = [DateTime]::MinValue
    NetworkIntervalSeconds = 0.75
    NetworkTimeoutSeconds = 8
    DiskCurrent = $null
    DiskLastSample = [DateTime]::MinValue
    DiskIntervalSeconds = 3
    DiskTimeoutSeconds = 10
    DiskRows = @()
    DiskSensorError = 'Disk sampler is starting'
    ActivityCurrent = $null
    ActivityLastSample = [DateTime]::MinValue
    ActivityIntervalSeconds = 2
    ActivityTimeoutSeconds = 10
    Processes = $null
    ProcessThreads = $null
    ProcessSensorError = 'Activity sampler is starting'
    NetworkConnected = $false
    NetworkStatus = 'Sampling'
    InternetReachable = $null
    NetworkSensorError = 'Network sampler is starting'
    NetRxBytes = $null
    NetTxBytes = $null
    NetworkAdapter = 'Waiting for network sample'
    IPv4 = 'Unavailable'
    Gateway = 'Not assigned'
    DNS = 'Not assigned'
    LinkMbps = $null
    GpuCurrent = $null
    GpuLastSample = [DateTime]::MinValue
    GpuIntervalSeconds = 2.5
    GpuTimeoutSeconds = 12
    GPUPercent = $null
    GPUSensorError = 'GPU sensor is sampling independently'
    GPUSensorSource = 'independent GPU worker'
    LastSuccessfulSample = [DateTime]::MinValue
    LastInventoryRefresh = [DateTime]::MinValue
    InventoryIntervalSeconds = 900
    HasInitialSnapshot = $false
    History = (New-Object System.Collections.ArrayList)
    PreviousNetworkSample = $null
    LastSensorLog = [DateTime]::MinValue
    DiskSignature = ''
}

$script:OverviewNativeBridgeBootstrap = @'
if (-not ('AMRLiveSensorNativeV3' -as [type])) {
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class AMRLiveSensorNativeV3 {
    [StructLayout(LayoutKind.Sequential)] public struct FILETIME { public uint Low; public uint High; public ulong Value { get { return ((ulong)High << 32) | Low; } } }
    [StructLayout(LayoutKind.Sequential)] public struct MEMORYSTATUSEX { public uint dwLength; public uint dwMemoryLoad; public ulong ullTotalPhys; public ulong ullAvailPhys; public ulong ullTotalPageFile; public ulong ullAvailPageFile; public ulong ullTotalVirtual; public ulong ullAvailVirtual; public ulong ullAvailExtendedVirtual; }
    [DllImport("kernel32.dll", SetLastError=true)] private static extern bool GetSystemTimes(out FILETIME idle, out FILETIME kernel, out FILETIME user);
    [DllImport("kernel32.dll", SetLastError=true)] private static extern bool GlobalMemoryStatusEx(ref MEMORYSTATUSEX state);
    [DllImport("kernel32.dll")] public static extern ulong GetTickCount64();
    public static ulong[] ReadCpuTimes() { FILETIME i,k,u; if (!GetSystemTimes(out i,out k,out u)) return null; return new ulong[] { i.Value,k.Value,u.Value }; }
    public static ulong[] ReadMemory() { MEMORYSTATUSEX m = new MEMORYSTATUSEX(); m.dwLength=(uint)Marshal.SizeOf(typeof(MEMORYSTATUSEX)); if(!GlobalMemoryStatusEx(ref m)) return null; return new ulong[] { m.ullTotalPhys,m.ullAvailPhys,(ulong)m.dwMemoryLoad }; }
}
"@ -ErrorAction Stop | Out-Null
}
$cpuProbe=[AMRLiveSensorNativeV3]::ReadCpuTimes()
$memoryProbe=[AMRLiveSensorNativeV3]::ReadMemory()
if($null -eq $cpuProbe -or $cpuProbe.Length -lt 3){throw 'Native engine self-test failed: GetSystemTimes is unavailable'}
if($null -eq $memoryProbe -or $memoryProbe.Length -lt 2 -or [double]$memoryProbe[0] -le 0){throw 'Native engine self-test failed: GlobalMemoryStatusEx is unavailable'}
[pscustomobject]@{NativeBridgeReady=$true;CpuCounterCount=$cpuProbe.Length;TotalPhysicalBytes=[double]$memoryProbe[0]}
'@

$script:OverviewFastTelemetryWorker = @'
param([bool]$DoInternetProbe = $false)
$ErrorActionPreference='Stop'
$cpuRaw=$null;$cpuError='';$cpuPercent=$null
try{
 $cpuFirst=[AMRLiveSensorNativeV3]::ReadCpuTimes()
 if($null -eq $cpuFirst -or $cpuFirst.Length -lt 3){throw 'GetSystemTimes returned no counters'}
 Start-Sleep -Milliseconds 250
 $cpuSecond=[AMRLiveSensorNativeV3]::ReadCpuTimes()
 if($null -eq $cpuSecond -or $cpuSecond.Length -lt 3){throw 'GetSystemTimes second sample returned no counters'}
 $idleDelta=[double]$cpuSecond[0]-[double]$cpuFirst[0]
 $kernelDelta=[double]$cpuSecond[1]-[double]$cpuFirst[1]
 $userDelta=[double]$cpuSecond[2]-[double]$cpuFirst[2]
 $totalDelta=$kernelDelta+$userDelta
 if($totalDelta -gt 0 -and $idleDelta -ge 0 -and $idleDelta -le $totalDelta){$cpuPercent=[Math]::Round([Math]::Max(0,[Math]::Min(100,(1-($idleDelta/$totalDelta))*100)),1)}
 $cpuRaw=$cpuSecond
 if($null -eq $cpuPercent){throw 'GetSystemTimes produced an invalid time delta'}
}catch{$cpuError=$_.Exception.Message;$cpuRaw=$null}
# No CIM/performance-counter fallback is executed in this fast lane. The native
# bridge is self-tested before the worker starts; a failed sensor is reported cleanly.

$totalMB=0.0;$freeMB=0.0;$usedMB=0.0;$memoryPercent=$null;$memoryError=''
try{$m=[AMRLiveSensorNativeV3]::ReadMemory();if($null -eq $m -or $m.Length -lt 2){throw 'GlobalMemoryStatusEx returned no memory data'};$totalMB=[double]$m[0]/1MB;$freeMB=[double]$m[1]/1MB;$usedMB=[Math]::Max(0.0,$totalMB-$freeMB);if($totalMB -gt 0){$memoryPercent=[Math]::Round(($usedMB/$totalMB)*100,1)}else{throw 'GlobalMemoryStatusEx returned zero physical memory'}}catch{$memoryError=$_.Exception.Message}
# RAM remains a direct GlobalMemoryStatusEx reading in this fast lane.
$gpuPercent=$null;$gpuError='GPU sampled by independent worker';$gpuSource='independent GPU worker'
$diskRows=@();$diskError='Disk sampling is isolated';
$networkStatus='Sampling';$networkError='Network sampler is running independently';$internetReachable=$null;$rx=$null;$tx=$null;$adapterDisplay='Waiting for network sample';$ipv4=@();$gateways=@();$dns=@();$linkMbps=$null
$processCount=$null;$threadCount=$null;$processError='Activity sampling is isolated';
$uptime='Unavailable';$lastBoot='Unavailable'
try{$span=[TimeSpan]::FromMilliseconds([double][AMRLiveSensorNativeV3]::GetTickCount64());$uptime='{0}d {1}h {2}m' -f [int]$span.TotalDays,$span.Hours,$span.Minutes;$lastBoot=(Get-Date).Subtract($span).ToString('yyyy-MM-dd HH:mm')}catch{}
[pscustomobject]@{CPUPercent=$cpuPercent;CPURaw=$cpuRaw;CPUSensorError=$cpuError;GPUPercent=$gpuPercent;GPUSensorError=$gpuError;GPUSensorSource=$gpuSource;Threads=[Environment]::ProcessorCount;TotalMB=$totalMB;FreeMB=$freeMB;UsedMB=$usedMB;MemoryPercent=$memoryPercent;MemorySensorError=$memoryError;DiskRows=@($diskRows);DiskSensorError=$diskError;NetworkConnected=($networkStatus -eq 'Connected');NetworkStatus=$networkStatus;InternetReachable=$internetReachable;NetworkSensorError=$networkError;NetRxBytes=$rx;NetTxBytes=$tx;NetworkAdapter=$adapterDisplay;IPv4=$(if($ipv4.Count){$ipv4 -join ', '}else{'Unavailable'});Gateway=$(if($gateways.Count){$gateways -join ', '}else{'Not assigned'});DNS=$(if($dns.Count){$dns -join ', '}else{'Not assigned'});LinkMbps=$linkMbps;Processes=$processCount;ProcessThreads=$threadCount;ProcessSensorError=$processError;Uptime=$uptime;LastBoot=$lastBoot}
'@

# GPU is isolated: a slow/broken GPU provider cannot block CPU/RAM/network samples.
$script:OverviewGpuTelemetryWorker = @'
$ErrorActionPreference='Stop'
$gpuPercent=$null;$gpuError='';$gpuSource='unavailable'
# A1: native PDH sampling (pdh.dll, same counter '\GPU Engine(*)\Utilization Percentage', two collections 1 s apart, same engine types, maximum of the
# newest sample, clamped 0-100). It replaces the Get-Counter cmdlet pipeline (about 0.8 s CPU per sample in the A22 log). Any failure falls back
# to the previous Get-Counter code, then to WMI, exactly as before. Three consecutive native failures disable the native path for the session.
$gpuNativeDone=$false
try{
 if([string][AppDomain]::CurrentDomain.GetData('AMRGpuPdhDisabled') -ne '1'){
  if(-not ('AMRGpuPdhNative' -as [type])){
   Add-Type -Language CSharp -ErrorAction Stop -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Threading;
public static class AMRGpuPdhNative {
    [DllImport("pdh.dll", CharSet = CharSet.Unicode)] private static extern uint PdhOpenQueryW(string dataSource, IntPtr userData, out IntPtr query);
    [DllImport("pdh.dll", CharSet = CharSet.Unicode)] private static extern uint PdhAddEnglishCounterW(IntPtr query, string fullCounterPath, IntPtr userData, out IntPtr counter);
    [DllImport("pdh.dll")] private static extern uint PdhCollectQueryData(IntPtr query);
    [DllImport("pdh.dll", CharSet = CharSet.Unicode)] private static extern uint PdhGetFormattedCounterArrayW(IntPtr counter, uint format, ref uint bufferSize, out uint itemCount, IntPtr buffer);
    [DllImport("pdh.dll")] private static extern uint PdhCloseQuery(IntPtr query);
    [StructLayout(LayoutKind.Sequential)] private struct FmtValue { public uint Status; public double Value; }
    [StructLayout(LayoutKind.Sequential)] private struct Item { public IntPtr Name; public FmtValue Fmt; }
    private const uint PDH_FMT_DOUBLE = 0x00000200;
    private const uint PDH_MORE_DATA = 0x800007D2;
    private static bool IsEngine(string name) {
        return name.IndexOf("engtype_3D", StringComparison.OrdinalIgnoreCase) >= 0
            || name.IndexOf("engtype_Compute", StringComparison.OrdinalIgnoreCase) >= 0
            || name.IndexOf("engtype_Copy", StringComparison.OrdinalIgnoreCase) >= 0
            || name.IndexOf("engtype_VideoDecode", StringComparison.OrdinalIgnoreCase) >= 0
            || name.IndexOf("engtype_VideoEncode", StringComparison.OrdinalIgnoreCase) >= 0;
    }
    public static int ItemSize() { return Marshal.SizeOf(typeof(Item)); }
    // Walks a PDH_FMT_COUNTERVALUE_ITEM_W array already in memory; returns the maximum valid engine value or -1 when none.
    public static double MaxEngineValue(IntPtr buffer, uint count) {
        int stride = Marshal.SizeOf(typeof(Item));
        double max = -1.0;
        for (int i = 0; i < (int)count; i++) {
            Item it = (Item)Marshal.PtrToStructure(new IntPtr(buffer.ToInt64() + (long)i * stride), typeof(Item));
            if (it.Name == IntPtr.Zero) continue;
            string name = Marshal.PtrToStringUni(it.Name);
            if (name == null || !IsEngine(name)) continue;
            if (it.Fmt.Status != 0 && it.Fmt.Status != 1) continue;
            if (it.Fmt.Value > max) max = it.Fmt.Value;
        }
        return max;
    }
    public static double SampleMaxEngineUtilization(int intervalMs) {
        IntPtr query;
        uint r = PdhOpenQueryW(null, IntPtr.Zero, out query);
        if (r != 0) throw new InvalidOperationException("PdhOpenQuery 0x" + r.ToString("X"));
        try {
            IntPtr counter;
            r = PdhAddEnglishCounterW(query, "\\GPU Engine(*)\\Utilization Percentage", IntPtr.Zero, out counter);
            if (r != 0) throw new InvalidOperationException("PdhAddEnglishCounter 0x" + r.ToString("X"));
            r = PdhCollectQueryData(query);
            if (r != 0) throw new InvalidOperationException("PdhCollectQueryData(1) 0x" + r.ToString("X"));
            Thread.Sleep(intervalMs);
            r = PdhCollectQueryData(query);
            if (r != 0) throw new InvalidOperationException("PdhCollectQueryData(2) 0x" + r.ToString("X"));
            uint size = 0, count = 0;
            r = PdhGetFormattedCounterArrayW(counter, PDH_FMT_DOUBLE, ref size, out count, IntPtr.Zero);
            if (r != PDH_MORE_DATA) {
                if (r == 0 || r == 0x800007D5) return -1.0;
                throw new InvalidOperationException("PdhGetFormattedCounterArray(size) 0x" + r.ToString("X"));
            }
            IntPtr buffer = Marshal.AllocHGlobal((int)size);
            try {
                r = PdhGetFormattedCounterArrayW(counter, PDH_FMT_DOUBLE, ref size, out count, buffer);
                if (r != 0) throw new InvalidOperationException("PdhGetFormattedCounterArray 0x" + r.ToString("X"));
                return MaxEngineValue(buffer, count);
            } finally { Marshal.FreeHGlobal(buffer); }
        } finally { PdhCloseQuery(query); }
    }
}
"@
  }
  $nativeMax=[AMRGpuPdhNative]::SampleMaxEngineUtilization(1000)
  if($nativeMax -ge 0){
   $gpuPercent=[Math]::Round([Math]::Max(0,[Math]::Min(100,[double]$nativeMax)),1);$gpuSource='GPU Engine PDH · 1-second sample';$gpuNativeDone=$true
   [AppDomain]::CurrentDomain.SetData('AMRGpuPdhFailures','0')
  }
 }
}catch{
 try{ $nativeFailures=0;[void][int]::TryParse([string][AppDomain]::CurrentDomain.GetData('AMRGpuPdhFailures'),[ref]$nativeFailures);$nativeFailures++;[AppDomain]::CurrentDomain.SetData('AMRGpuPdhFailures',[string]$nativeFailures);if($nativeFailures -ge 3){[AppDomain]::CurrentDomain.SetData('AMRGpuPdhDisabled','1')} }catch{}
}
if(-not $gpuNativeDone){
try{
 # PDH samples over a one-second window are more representative than a single
 # formatted-counter read, which can briefly report stale or spiky engine values.
 $gpuCounter=Get-Counter -Counter '\GPU Engine(*)\Utilization Percentage' -SampleInterval 1 -MaxSamples 2 -ErrorAction Stop
 # A24: same selection and result as before (valid engine types, newest timestamp, maximum value, clamped
 # 0-100) but computed with two plain loops instead of four pipelines over every engine instance
 # (A22 log: this worker costs about 0.8 s CPU and about 290 gen0 GCs per sample).
 $engRx=New-Object System.Text.RegularExpressions.Regex('engtype_(3D|Compute|Copy|VideoDecode|VideoEncode)',[System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
 $allSamples=$gpuCounter.CounterSamples
 $latestStamp=[DateTime]::MinValue;$validCount=0
 foreach($sm in $allSamples){ if($null -ne $sm.CookedValue -and $engRx.IsMatch([string]$sm.InstanceName)){ $validCount++; if($sm.Timestamp -gt $latestStamp){$latestStamp=$sm.Timestamp} } }
 if($validCount -gt 0){
  $maxVal=$null
  foreach($sm in $allSamples){ if($null -ne $sm.CookedValue -and $sm.Timestamp -eq $latestStamp -and $engRx.IsMatch([string]$sm.InstanceName)){ $cv=[double]$sm.CookedValue; if($null -eq $maxVal -or $cv -gt $maxVal){$maxVal=$cv} } }
  if($null -ne $maxVal){$gpuPercent=[Math]::Round([Math]::Max(0,[Math]::Min(100,$maxVal)),1);$gpuSource='GPU Engine PDH · 1-second sample'}
 }
 if($null -eq $gpuPercent){throw 'GPU PDH sampling returned no valid engine instances'}
}catch{
 $gpuError=$_.Exception.Message
 try{
  $gpuRows=@(Get-WmiObject -Namespace 'root\cimv2' -Class 'Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine' -ErrorAction Stop)
  $gpuValues=@($gpuRows | Where-Object {$_.Name -match 'engtype_(3D|Compute|Copy|VideoDecode|VideoEncode)' -and $null -ne $_.UtilizationPercentage} | ForEach-Object {[double]$_.UtilizationPercentage})
  if($gpuValues.Count -gt 0){$gpuPercent=[Math]::Round([Math]::Max(0,[Math]::Min(100,(($gpuValues | Measure-Object -Maximum).Maximum))),1);$gpuSource='GPU Engine WMI fallback';$gpuError=''}else{throw 'GPU WMI fallback returned no utilization instances'}
 }catch{$gpuError+='; WMI fallback: '+$_.Exception.Message}
}
}
[pscustomobject]@{GPUPercent=$gpuPercent;GPUSensorError=$gpuError;GPUSensorSource=$gpuSource;Timestamp=(Get-Date)}
'@

# Network interface discovery and byte counters are independent from CPU/RAM/GPU.
$script:OverviewNetworkTelemetryWorker = @'
param([bool]$DoInternetProbe = $false,[object]$PreviousInternetReachable = $null)
$ErrorActionPreference='Stop'
$networkStatus='Offline';$networkError='';$internetReachable=$PreviousInternetReachable;$rx=$null;$tx=$null
$primary=$null;$ipv4=@();$gateways=@();$dns=@();$linkMbps=$null
try{
 $ranked=@()
 foreach($n in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()){
  try{
   if($n.OperationalStatus -ne [System.Net.NetworkInformation.OperationalStatus]::Up -or $n.NetworkInterfaceType -in @([System.Net.NetworkInformation.NetworkInterfaceType]::Loopback,[System.Net.NetworkInformation.NetworkInterfaceType]::Tunnel)){continue}
   $ip=$n.GetIPProperties();$v4=@($ip.UnicastAddresses|Where-Object{$_.Address.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetwork -and -not [System.Net.IPAddress]::IsLoopback($_.Address)}|ForEach-Object{$_.Address.IPAddressToString})
   $gw=@($ip.GatewayAddresses|Where-Object{$_.Address -and $_.Address.ToString() -notin @('0.0.0.0','::')}|ForEach-Object{$_.Address.IPAddressToString})
   $score=0;if($gw.Count -gt 0){$score+=200};if($v4.Count -gt 0){$score+=60};if($n.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Wireless80211){$score+=55}elseif($n.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Ethernet){$score+=50}
   if(([string]$n.Name+' '+[string]$n.Description) -match '(?i)vmware|virtualbox|loopback|bluetooth|vpn|tap-|teredo'){$score-=45}
   $ranked += [pscustomobject]@{Nic=$n;IP=$ip;IPv4=$v4;Gateway=$gw;Score=$score}
  }catch{}
 }
 $primary=$ranked|Sort-Object Score -Descending|Select-Object -First 1
 if($primary){
  $ipv4=@($primary.IPv4);$gateways=@($primary.Gateway);$dns=@($primary.IP.DnsAddresses|ForEach-Object{$_.IPAddressToString});if($primary.Nic.Speed -gt 0){$linkMbps=[Math]::Round($primary.Nic.Speed/1000000,0)}
  try{$st=$primary.Nic.GetIPStatistics();$rx=[long]$st.BytesReceived;$tx=[long]$st.BytesSent}catch{
   $networkError=$_.Exception.Message
   foreach($candidate in $ranked){try{$candidateStats=$candidate.Nic.GetIPStatistics();$candidateRx=[long]$candidateStats.BytesReceived;$candidateTx=[long]$candidateStats.BytesSent;if($null -ne $candidateRx -and $null -ne $candidateTx){$primary=$candidate;$ipv4=@($candidate.IPv4);$gateways=@($candidate.Gateway);$rx=$candidateRx;$tx=$candidateTx;$networkError='';break}}catch{}}
  }
  if($ipv4.Count -eq 0){$networkStatus='Active interface, no IPv4'}
  elseif($gateways.Count -eq 0){$networkStatus='No gateway'}
  else{
   if($DoInternetProbe){$internetReachable=$false;foreach($hostIp in @('1.1.1.1','8.8.8.8')){$c=$null;$a=$null;try{$c=New-Object System.Net.Sockets.TcpClient;$a=$c.BeginConnect($hostIp,443,$null,$null);if($a.AsyncWaitHandle.WaitOne(650,$false)){$c.EndConnect($a);if($c.Connected){$internetReachable=$true}}}catch{}finally{if($a){try{$a.AsyncWaitHandle.Close()}catch{}};if($c){try{$c.Close()}catch{}}};if($internetReachable){break}}}
   if($internetReachable -eq $true){$networkStatus='Connected'}elseif($internetReachable -eq $false){$networkStatus='Active interface, internet unverified'}else{$networkStatus='Active interface, internet check pending'}
  }
 }else{$networkStatus='Offline'}
}catch{
 $primaryProviderError=$_.Exception.Message
 $networkError=$primaryProviderError
 $networkStatus='Sensor unavailable'
 # Fallback provider: Windows NetTCPIP cmdlets can still expose the active
 # adapter and its addressing when .NET NetworkInterface enumeration fails.
 try{
  $fallbackConfigs=@(Get-NetIPConfiguration -ErrorAction Stop | Where-Object {$_.NetAdapter -and [string]$_.NetAdapter.Status -eq 'Up'})
  $fallbackConfig=$fallbackConfigs | Sort-Object @{Expression={if(@($_.IPv4DefaultGateway).Count -gt 0){0}elseif(@($_.IPv4Address).Count -gt 0){1}else{2}}} | Select-Object -First 1
  if(-not $fallbackConfig){$networkStatus='Offline';$networkError=''}
  else{
  $fallbackAdapter=$null
  try{$fallbackAdapter=Get-NetAdapter -InterfaceIndex ([int]$fallbackConfig.InterfaceIndex) -ErrorAction Stop}catch{}
  $ipv4=@($fallbackConfig.IPv4Address | ForEach-Object {[string]$_.IPAddress} | Where-Object {$_})
  $gateways=@($fallbackConfig.IPv4DefaultGateway | ForEach-Object {[string]$_.NextHop} | Where-Object {$_})
  $dns=@($fallbackConfig.DNSServer.ServerAddresses | ForEach-Object {[string]$_} | Where-Object {$_})
  $fallbackName=if($fallbackAdapter){[string]$fallbackAdapter.Name}else{[string]$fallbackConfig.InterfaceAlias}
  $fallbackDescription=if($fallbackAdapter){[string]$fallbackAdapter.InterfaceDescription}else{[string]$fallbackConfig.InterfaceAlias}
  $fallbackType='Ethernet'
  if(($fallbackName+' '+$fallbackDescription) -match '(?i)wi-?fi|wireless'){$fallbackType='Wireless80211'}
  $fallbackSpeed=0L;if($fallbackAdapter){try{$fallbackSpeed=[long]$fallbackAdapter.LinkSpeed}catch{}}
  $primary=[pscustomobject]@{Nic=[pscustomobject]@{Name=$fallbackName;Description=$fallbackDescription;NetworkInterfaceType=$fallbackType;Speed=$fallbackSpeed};IPv4=$ipv4;Gateway=$gateways;IP=[pscustomobject]@{DnsAddresses=$dns}}
  $linkMbps=$null;if($fallbackSpeed -gt 0){$linkMbps=[Math]::Round($fallbackSpeed/1000000,0)}
  try{$fallbackStats=Get-NetAdapterStatistics -Name $fallbackName -ErrorAction Stop;$rx=[long]$fallbackStats.ReceivedBytes;$tx=[long]$fallbackStats.SentBytes}catch{$rx=$null;$tx=$null}
  if($ipv4.Count -eq 0){$networkStatus='Active interface, no IPv4'}
  elseif($gateways.Count -eq 0){$networkStatus='No gateway'}
  else{
   if($DoInternetProbe){$internetReachable=$false;foreach($hostIp in @('1.1.1.1','8.8.8.8')){$c=$null;$a=$null;try{$c=New-Object System.Net.Sockets.TcpClient;$a=$c.BeginConnect($hostIp,443,$null,$null);if($a.AsyncWaitHandle.WaitOne(650,$false)){$c.EndConnect($a);if($c.Connected){$internetReachable=$true}}}catch{}finally{if($a){try{$a.AsyncWaitHandle.Close()}catch{}};if($c){try{$c.Close()}catch{}}};if($internetReachable){break}}}
   if($internetReachable -eq $true){$networkStatus='Connected'}elseif($internetReachable -eq $false){$networkStatus='Active interface, internet unverified'}else{$networkStatus='Active interface, internet check pending'}
  }
  $networkError=''
  }
 }catch{
  $networkError=$primaryProviderError+'; NetTCPIP fallback: '+$_.Exception.Message
  $networkStatus='Sensor unavailable'
 }
}
$adapterDisplay='No active network adapter'
if($primary){
 $adapterIdentity=([string]$primary.Nic.Name+' '+[string]$primary.Nic.Description)
 if($adapterIdentity -match '(?i)wi-?fi\s*direct|mobile\s*hotspot|hosted\s*network|local area connection\s*\*'){$adapterKind='Mobile Hotspot / Wi-Fi Direct'}
 elseif($primary.Nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Wireless80211){$adapterKind='Wi-Fi'}
 elseif($primary.Nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Ethernet){$adapterKind='Ethernet'}
 else{$adapterKind=[string]$primary.Nic.NetworkInterfaceType}
 $adapterDisplay='{0} ({1})' -f $primary.Nic.Name,$adapterKind
}

[pscustomobject]@{NetworkConnected=($networkStatus -eq 'Connected');NetworkStatus=$networkStatus;InternetReachable=$internetReachable;NetworkSensorError=$networkError;NetRxBytes=$rx;NetTxBytes=$tx;NetworkAdapter=$adapterDisplay;IPv4=$(if($ipv4.Count){$ipv4 -join ', '}else{'Unavailable'});Gateway=$(if($gateways.Count){$gateways -join ', '}else{'Not assigned'});DNS=$(if($dns.Count){$dns -join ', '}else{'Not assigned'});LinkMbps=$linkMbps;Timestamp=(Get-Date)}
'@

$script:OverviewDiskTelemetryWorker = @'
$ErrorActionPreference='Stop'
$diskRows=@();$diskError=''
try {
    foreach($drive in [System.IO.DriveInfo]::GetDrives()) {
        try {
            if($drive.DriveType -eq [System.IO.DriveType]::Fixed -and $drive.IsReady -and $drive.TotalSize -gt 0) {
                $total=[double]$drive.TotalSize; $free=[double]$drive.AvailableFreeSpace
                $percent=[Math]::Round((($total-$free)/$total)*100,1)
                $diskRows += [pscustomobject]@{Name=$drive.Name;TotalGB=[Math]::Round($total/1GB,1);FreeGB=[Math]::Round($free/1GB,1);UsedPercent=$percent;UsedPercentText=('{0:N0}%' -f $percent);DisplayText=('{0}  {1:N0}% used  •  {2:N1} GB free of {3:N1} GB' -f $drive.Name,$percent,($free/1GB),($total/1GB))}
            }
        } catch { $diskError=$_.Exception.Message }
    }
} catch { $diskError=$_.Exception.Message }
[pscustomobject]@{DiskRows=@($diskRows);DiskSensorError=$diskError;Timestamp=(Get-Date)}
'@

$script:OverviewActivityTelemetryWorker = @'
$ErrorActionPreference='Stop'
$processCount=$null;$threadCount=$null;$processError=''
try {
    $processes=[System.Diagnostics.Process]::GetProcesses()
    $processCount=$processes.Count; $threadCount=0
    foreach($process in $processes) {
        try { $threadCount += $process.Threads.Count } catch { }
        finally { try { $process.Dispose() } catch { } }
    }
} catch { $processError=$_.Exception.Message }
[pscustomobject]@{Processes=$processCount;ProcessThreads=$threadCount;ProcessSensorError=$processError;Timestamp=(Get-Date)}
'@

$script:OverviewTelemetryWorker = @' 
param([bool]$DoInternetProbe = $false,[bool]$DoInventoryRefresh = $false)
$ErrorActionPreference = 'SilentlyContinue'
$ProgressPreference = 'SilentlyContinue'
# This is the slower inventory worker; live sampling runs independently in OverviewFastTelemetryWorker.
$osKey = $null; $bios = $null; $cpuKey = $null
try { $osKey = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop } catch {}
try { $bios = Get-ItemProperty -LiteralPath 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -ErrorAction Stop } catch {}
try { $cpuKey = Get-ItemProperty -LiteralPath 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -ErrorAction Stop } catch {}
$osProduct = if ($osKey -and $osKey.ProductName) { [string]$osKey.ProductName } else { [Environment]::OSVersion.VersionString }
$osBuildNumber = 0; try { $osBuildNumber = [int]$osKey.CurrentBuildNumber } catch { try { $osBuildNumber = [Environment]::OSVersion.Version.Build } catch {} }
$editionId = if ($osKey -and $osKey.EditionID) { [string]$osKey.EditionID } else { '' }
$editionName = switch -Regex ($editionId) { '^Professional$' {'Pro'} '^Core$' {'Home'} '^Enterprise$' {'Enterprise'} '^Education$' {'Education'} '^ProfessionalWorkstation$' {'Pro for Workstations'} '^ProfessionalEducation$' {'Pro Education'} default { $editionId } }
$osName = $osProduct
# Do not mislabel every pre-Windows-11 build as Windows 10. Keep Server names intact
# and identify legacy client releases by their actual NT build families.
if ($osProduct -notmatch '(?i)Windows\s+Server') {
    $detectedWindowsFamily = switch ($osBuildNumber) {
        { $_ -ge 22000 } { 'Windows 11'; break }
        { $_ -ge 10240 } { 'Windows 10'; break }
        { $_ -ge 9600 } { 'Windows 8.1'; break }
        { $_ -ge 9200 } { 'Windows 8'; break }
        { $_ -ge 7600 } { 'Windows 7'; break }
        { $_ -ge 6000 } { 'Windows Vista'; break }
        default { $osProduct }
    }
    if ($detectedWindowsFamily) {
        $osName = $detectedWindowsFamily
        if ($editionName) { $osName += ' ' + $editionName }
    }
}
$displayVersion = if ($osKey -and $osKey.DisplayVersion) { [string]$osKey.DisplayVersion } elseif ($osKey -and $osKey.ReleaseId) { [string]$osKey.ReleaseId } else { 'Version unavailable' }
$buildText = if ($osKey -and $osKey.CurrentBuildNumber) { '{0}  •  Version {1}' -f $osKey.CurrentBuildNumber,$displayVersion } else { 'Build ' + [Environment]::OSVersion.Version.Build }
$manufacturer = if ($bios -and $bios.SystemManufacturer) { [string]$bios.SystemManufacturer } else { 'Manufacturer unavailable' }
$model = if ($bios -and $bios.SystemProductName) { [string]$bios.SystemProductName } elseif ($bios -and $bios.SystemFamily) { [string]$bios.SystemFamily } else { 'Model unavailable' }
$classHint = (($manufacturer + ' ' + $model + ' ' + [string]$bios.SystemFamily) -as [string])
$isTablet = $classHint -match '(?i)tablet|surface pro|detachable|2-in-1|convertible'
$isLaptop = $classHint -match '(?i)laptop|notebook|portable|thinkpad|latitude|pavilion|vivobook|zenbook|elitebook|probook|inspiron|aspire|swift|toughbook|xps|vostro|ideapad|yoga|zbook|envy|spectre|travelmate|surface laptop|precision\s+(?:3[0-9]{3}|5[0-9]{3}|7[0-9]{3})|mobile workstation'
$isMobileWorkstation = $classHint -match '(?i)precision|zbook|thinkpad\s*p[0-9]|mobile workstation|fury'
$chassisTypes = @()
try {
    $enclosure = Get-CimInstance -ClassName Win32_SystemEnclosure -ErrorAction Stop | Select-Object -First 1
    if ($enclosure -and $enclosure.ChassisTypes) { $chassisTypes = @($enclosure.ChassisTypes | ForEach-Object { [int]$_ }) }
} catch {
    try { $enclosure = Get-WmiObject -Class Win32_SystemEnclosure -ErrorAction Stop | Select-Object -First 1; if ($enclosure -and $enclosure.ChassisTypes) { $chassisTypes = @($enclosure.ChassisTypes | ForEach-Object { [int]$_ }) } } catch {}
}
if ($chassisTypes -contains 30) { $deviceType = 'Tablet' }
elseif (($chassisTypes | Where-Object { $_ -in @(8,9,10,14,31,32) }).Count -gt 0 -or $isTablet) {
    if ($chassisTypes -contains 31) { $deviceType = 'Convertible Laptop' }
    elseif ($chassisTypes -contains 32) { $deviceType = 'Detachable Laptop' }
    elseif ($isMobileWorkstation) { $deviceType = 'Laptop Workstation' }
    else { $deviceType = 'Laptop' }
}
elseif ($isLaptop -and $isMobileWorkstation) { $deviceType = 'Laptop Workstation' }
elseif ($isLaptop) { $deviceType = 'Laptop' }
elseif ($classHint -match '(?i)precision|thinkstation|z[0-9]+\s*tower|workstation') { $deviceType = 'Desktop Workstation' }
else { $deviceType = 'Desktop PC' }
if ($env:SESSIONNAME -match 'RDP') { $deviceType = 'Remote session' }
$deviceDisplay = ('{0} {1}' -f ($manufacturer -replace '(?i)\s+Inc\.?$',''),$model).Trim()
$cpuName = if ($cpuKey -and $cpuKey.ProcessorNameString) { ([string]$cpuKey.ProcessorNameString).Trim() } else { 'Processor information unavailable' }
$coreCount = 'N/A'

# Inventory is deliberately low-frequency. It uses its own CIM sample and does not
# depend on a native type compiled in the live-sampler runspace.
$cpuPercent=$null; $cpuSensorError='CPU live sampling is owned by the fast telemetry worker'; $cpuRaw=$null
$totalMB=0.0; $freeMB=0.0; $usedMB=0.0; $memoryPercent=$null; $memorySensorError=''
try {
    $inventoryOs=Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    $totalMB=[double]$inventoryOs.TotalVisibleMemorySize/1024
    $freeMB=[double]$inventoryOs.FreePhysicalMemory/1024
    $usedMB=[Math]::Max(0.0,$totalMB-$freeMB)
    if($totalMB -gt 0){$memoryPercent=[Math]::Round(($usedMB/$totalMB)*100,1)}else{$memorySensorError='Win32_OperatingSystem returned zero physical memory'}
} catch { $memorySensorError=$_.Exception.Message }

$diskRows=@(); $systemDisk=$null; $diskSensorError=''
try {
    foreach($drive in [System.IO.DriveInfo]::GetDrives()) { try { if($drive.DriveType -eq [System.IO.DriveType]::Fixed -and $drive.IsReady -and $drive.TotalSize -gt 0){$total=[double]$drive.TotalSize;$free=[double]$drive.AvailableFreeSpace;$pct=[Math]::Round((($total-$free)/$total)*100,1);$entry=[pscustomobject]@{DisplayText=('{0}  {1:N0}% used  •  {2:N1} GB free of {3:N1} GB' -f $drive.Name,$pct,($free/1GB),($total/1GB));Name=$drive.Name;TotalGB=[Math]::Round($total/1GB,1);FreeGB=[Math]::Round($free/1GB,1);UsedPercent=$pct;UsedPercentText=('{0:N0}%' -f $pct)};$diskRows+=$entry;if($drive.Name.TrimEnd('\') -eq $env:SystemDrive.TrimEnd('\')){$systemDisk=$entry}} }catch{$diskSensorError=$_.Exception.Message} }
}catch{$diskSensorError=$_.Exception.Message}

$activeNics=@();$primaryNic=$null;$ipv4=@();$ipv6=@();$gateways=@();$dnsServers=@();$linkMbps=$null
$networkConnected=$false;$networkStatus='Offline';$networkSensorError='';$netRxBytes=$null;$netTxBytes=$null
try {
    $rankedNics=@()
    foreach($nic in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
        try {
            if($nic.OperationalStatus -ne [System.Net.NetworkInformation.OperationalStatus]::Up -or
               $nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Loopback -or
               $nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Tunnel) { continue }
            $props=$nic.GetIPProperties()
            $addresses=@($props.UnicastAddresses | Where-Object {-not [System.Net.IPAddress]::IsLoopback($_.Address) -and -not $_.Address.IsIPv6LinkLocal})
            $nicGateways=@($props.GatewayAddresses | Where-Object {$_.Address -and $_.Address.ToString() -ne '0.0.0.0' -and $_.Address.ToString() -ne '::'} | ForEach-Object {$_.Address.IPAddressToString})
            $isWifi=($nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Wireless80211)
            $isEthernet=($nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Ethernet)
            $score=0
            if($isWifi){$score+=55}elseif($isEthernet){$score+=50}
            if($nicGateways.Count -gt 0){$score+=180}
            if(@($addresses | Where-Object {$_.Address.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetwork}).Count -gt 0){$score+=45}
            if(([string]$nic.Name+' '+[string]$nic.Description) -match '(?i)virtual|vmware|virtualbox|hyper-v|vethernet|tap-|vpn|tunnel|bluetooth'){$score-=130}
            $rankedNics += [pscustomobject]@{Nic=$nic;Props=$props;Addresses=$addresses;Gateways=$nicGateways;Score=$score}
        } catch { }
    }
    $chosen=$rankedNics | Sort-Object Score -Descending | Select-Object -First 1
    if($chosen) {
        $primaryNic=$chosen.Nic
        $ipv4=@($chosen.Addresses | Where-Object {$_.Address.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetwork} | ForEach-Object {$_.Address.IPAddressToString})
        $ipv6=@($chosen.Addresses | Where-Object {$_.Address.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetworkV6} | ForEach-Object {$_.Address.IPAddressToString})
        $gateways=@($chosen.Gateways);$dnsServers=@($chosen.Props.DnsAddresses | ForEach-Object {$_.IPAddressToString})
        if($chosen.Nic.Speed -gt 0){$linkMbps=[Math]::Round(($chosen.Nic.Speed/1000000),0)}
        try { $stats=$chosen.Nic.GetIPStatistics(); $netRxBytes=[long]$stats.BytesReceived; $netTxBytes=[long]$stats.BytesSent } catch { $networkSensorError=$_.Exception.Message }
        if($ipv4.Count -eq 0) { $networkStatus='Active interface, no IPv4' }
        elseif($gateways.Count -eq 0) { $networkStatus='No gateway' }
        else {
            $internetReachable=$null
            if($DoInternetProbe) {
                $internetReachable=$false
                foreach($probeAddress in @('1.1.1.1','8.8.8.8')) {
                    $probeClient=$null;$probeAsync=$null
                    try {
                        $probeClient=New-Object System.Net.Sockets.TcpClient
                        $probeAsync=$probeClient.BeginConnect($probeAddress,443,$null,$null)
                        if($probeAsync.AsyncWaitHandle.WaitOne(650,$false)) {
                            $probeClient.EndConnect($probeAsync)
                            if($probeClient.Connected){$internetReachable=$true}
                        }
                    } catch { }
                    finally { if($probeAsync){try{$probeAsync.AsyncWaitHandle.Close()}catch{}}; if($probeClient){try{$probeClient.Close()}catch{}} }
                    if($internetReachable){break}
                }
            }
            if($internetReachable -eq $true){$networkStatus='Connected';$networkConnected=$true}
            elseif($internetReachable -eq $false){$networkStatus='Active interface, internet unverified'}
            else{$networkStatus='Active interface, internet check pending'}
        }
    }
} catch { $networkSensorError=$_.Exception.Message; $networkStatus='Sensor unavailable' }
if(-not $primaryNic -and -not $networkSensorError) { $networkStatus='Offline' }
$gpuName='Graphics adapter details are being detected';$gpuMemory='Not reported yet';$displayText='Display details are being detected'
if($DoInventoryRefresh){
$gpuNames=@();$gpuDetails=@();$gpuMemory='Not reported by display driver';$displayText='Display details unavailable'
try {
    $displayClass='HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
    foreach($adapterKey in (Get-ChildItem -LiteralPath $displayClass -ErrorAction SilentlyContinue | Where-Object {$_.PSChildName -match '^\d{4}$'})) {
        try {
            $v=Get-ItemProperty -LiteralPath $adapterKey.PSPath -ErrorAction Stop
            $desc=[string]$v.DriverDesc
            if(-not $desc){$desc=[string]$v.'HardwareInformation.AdapterString'}
            if($desc -and $gpuNames -notcontains $desc){$gpuNames+=$desc}
            if($desc){
                $version=[string]$v.DriverVersion
                $provider=[string]$v.ProviderName
                $memBytes=0L
                foreach($memProp in @('HardwareInformation.qwMemorySize','HardwareInformation.MemorySize','HardwareInformation.MemorySizeInBytes')) { try { $raw=$v.$memProp; if($raw -is [byte[]]){$raw=[BitConverter]::ToUInt64($raw,0)}; if([double]$raw -gt 0){$memBytes=[long]$raw;break} } catch {} }
                if($memBytes -gt 0){$gpuMemory=('{0:N1} GB dedicated/reported graphics memory' -f ($memBytes/1GB))}
                $gpuDetails += (($provider+' '+$desc+' '+$(if($version){'Driver '+$version}else{''})).Trim())
            }
        } catch {}
    }
} catch {}
if($gpuNames.Count -eq 0) {
    try {
        $pnpCmd=Get-Command Get-PnpDevice -ErrorAction SilentlyContinue
        if($pnpCmd){$gpuNames=@(Get-PnpDevice -Class Display -ErrorAction SilentlyContinue | Where-Object {$_.FriendlyName} | ForEach-Object {[string]$_.FriendlyName} | Select-Object -Unique)}
    } catch {}
}
$gpuName=if($gpuNames.Count -gt 0){$gpuNames -join '  | '}else{'Graphics adapter not reported by Windows'}
if($gpuDetails.Count -gt 0){$gpuMemory=($gpuDetails -join '  | ')+$(if($gpuMemory -ne 'Not reported by display driver'){'  •  '+$gpuMemory}else{''})}
try {
    $pnpCmd=Get-Command Get-PnpDevice -ErrorAction SilentlyContinue
    if($pnpCmd){$monitors=@(Get-PnpDevice -Class Monitor -ErrorAction SilentlyContinue | Where-Object {$_.Status -eq 'OK' -and $_.FriendlyName} | ForEach-Object {[string]$_.FriendlyName} | Select-Object -Unique);if($monitors.Count -gt 0){$displayText=$monitors -join '  | '}}
} catch {}
}
$boardName='Motherboard information unavailable';if($bios -and ($bios.BaseBoardManufacturer -or $bios.BaseBoardProduct)){$boardName=('{0} {1}' -f $bios.BaseBoardManufacturer,$bios.BaseBoardProduct).Trim()}
$biosName=if($bios -and $bios.BIOSVersion){@($bios.BIOSVersion) -join ' '}else{'Unavailable'}
$biosDate=if($bios -and $bios.BIOSReleaseDate){@($bios.BIOSReleaseDate) -join ' '}else{'Unavailable'}
$uptimeText='Unavailable';$lastBootText='Unavailable'
try{if($inventoryOs -and $inventoryOs.LastBootUpTime){$bootTime=[datetime]$inventoryOs.LastBootUpTime;$uptime=(Get-Date)-$bootTime;$uptimeText='{0}d {1}h {2}m' -f [int]$uptime.TotalDays,$uptime.Hours,$uptime.Minutes;$lastBootText=$bootTime.ToString('yyyy-MM-dd HH:mm')}}catch{}
$processCount=$null;$processThreadCount=$null;$processSensorError='';try{$procList=[System.Diagnostics.Process]::GetProcesses();$processCount=$procList.Count;$processThreadCount=0;foreach($procItem in $procList){try{$processThreadCount += $procItem.Threads.Count}catch{}}}catch{$processSensorError=$_.Exception.Message}
$defenderText='Security status refresh pending';$firewallText='Security status refresh pending';$tpmText='Security status refresh pending';$secureBootText='Security status refresh pending';$activationText='Activation status refresh pending';$latestUpdateText='Windows Update history refresh pending'
if($DoInventoryRefresh){
$defenderText='Unavailable';$firewallText='Unavailable';$tpmText='Unavailable';$secureBootText='Unavailable';$activationText='Unavailable'
$mpCommand=Get-Command Get-MpComputerStatus -ErrorAction SilentlyContinue
if(-not $mpCommand){$defenderText='Not supported'}else{
    try{$mp=Get-MpComputerStatus -ErrorAction Stop;if(-not $mp.AntivirusEnabled){$defenderText='Disabled'}elseif($mp.RealTimeProtectionEnabled){$defenderText='Enabled'}else{$defenderText='Disabled'}}
    catch{if($_.Exception -is [System.UnauthorizedAccessException] -or $_.Exception.Message -match '(?i)access is denied|access denied'){$defenderText='Access denied'}else{$defenderText='Unavailable: '+$_.Exception.Message}}
}
$fwCommand=Get-Command Get-NetFirewallProfile -ErrorAction SilentlyContinue
if(-not $fwCommand){$firewallText='Not supported'}else{
    try{$fw=@(Get-NetFirewallProfile -ErrorAction Stop);if($fw.Count -gt 0){$on=@($fw | Where-Object {$_.Enabled -eq $true}).Count;if($on -eq $fw.Count){$firewallText='Enabled'}elseif($on -eq 0){$firewallText='Disabled'}else{$firewallText=('Partially enabled ({0}/{1})' -f $on,$fw.Count)}}else{$firewallText='Unavailable'}}
    catch{if($_.Exception -is [System.UnauthorizedAccessException] -or $_.Exception.Message -match '(?i)access is denied|access denied'){$firewallText='Access denied'}else{$firewallText='Unavailable: '+$_.Exception.Message}}
}
$tpmCommand=Get-Command Get-Tpm -ErrorAction SilentlyContinue
if(-not $tpmCommand){$tpmText='Not supported'}else{
    try{$t=Get-Tpm -ErrorAction Stop;if(-not $t.TpmPresent){$tpmText='Not supported (TPM not detected)'}elseif($t.TpmReady){$tpmText='Enabled (present and ready)'}else{$tpmText='Disabled (present but not ready)'}}
    catch{if($_.Exception -is [System.UnauthorizedAccessException] -or $_.Exception.Message -match '(?i)access is denied|access denied'){$tpmText='Access denied'}else{$tpmText='Unavailable: '+$_.Exception.Message}}
}
$secureBootCommand=Get-Command Confirm-SecureBootUEFI -ErrorAction SilentlyContinue
if(-not $secureBootCommand){$secureBootText='Not supported'}else{
    try{$sb=Confirm-SecureBootUEFI -ErrorAction Stop;$secureBootText=if($sb){'Enabled'}else{'Disabled'}}
    catch{if($_.Exception -is [System.UnauthorizedAccessException] -or $_.Exception.Message -match '(?i)access is denied|access denied'){$secureBootText='Access denied'}elseif($_.Exception -is [System.PlatformNotSupportedException] -or $_.Exception.Message -match '(?i)not supported|unsupported|UEFI'){$secureBootText='Not supported'}else{$secureBootText='Unavailable: '+$_.Exception.Message}}
}
try{$lic=Get-CimInstance -ClassName SoftwareLicensingProduct -Filter "Name like 'Windows%' AND PartialProductKey is not null" -ErrorAction Stop | Where-Object {$_.LicenseStatus -eq 1} | Select-Object -First 1;if($lic){$activationText='Activated'}else{$activationText='Not activated'}}catch{if($_.Exception -is [System.UnauthorizedAccessException] -or $_.Exception.Message -match '(?i)access is denied|access denied'){$activationText='Access denied'}else{$activationText='Unavailable: '+$_.Exception.Message}}
$latestUpdateText='Windows Update history date unavailable'
try{$wuKey=Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install' -ErrorAction Stop;if($wuKey.LastSuccessTime){$wuDate=[datetime]::Parse([string]$wuKey.LastSuccessTime);$latestUpdateText='Last successful Windows Update: '+$wuDate.ToString('yyyy-MM-dd HH:mm')}}catch{}
}
$ramSlotsText='Module-level RAM details not queried';

[pscustomobject]@{
 OSName=$osName;Build=$buildText;PCName=$deviceDisplay;Architecture=$(if([Environment]::Is64BitOperatingSystem){'64-bit Windows'}else{'32-bit Windows'})
 DeviceType=$deviceType;Manufacturer=$manufacturer;Model=$model;CPUName=$cpuName;CPUPercent=$cpuPercent;CPURaw=$cpuRaw;CPUSensorError=$cpuSensorError;Cores=$coreCount;Threads=[Environment]::ProcessorCount
 GPUName=$gpuName;GPUMemory=$gpuMemory;Display=$displayText;Board=$boardName;BIOS=$biosName;BIOSDate=$biosDate
 TotalMB=$totalMB;FreeMB=$freeMB;UsedMB=$usedMB;MemoryPercent=$memoryPercent;MemorySensorError=$memorySensorError;DiskSensorError=$diskSensorError;RAMModules=$ramSlotsText;DiskRows=@($diskRows);SystemDisk=$systemDisk
 NetworkConnected=$networkConnected;NetworkStatus=$networkStatus;InternetReachable=$internetReachable;NetworkSensorError=$networkSensorError;NetRxBytes=$netRxBytes;NetTxBytes=$netTxBytes;NetworkAdapter=$(if($primaryNic){('{0} ({1})' -f [string]$primaryNic.Name,[string]$primaryNic.NetworkInterfaceType)}else{'No active network adapter'})
 IPv4=$(if($ipv4.Count -gt 0){$ipv4 -join ', '}else{'Unavailable'})
 Gateway=$(if($gateways.Count -gt 0){$gateways -join ', '}else{'Not assigned'});DNS=$(if($dnsServers.Count -gt 0){$dnsServers -join ', '}else{'Not assigned'});LinkMbps=$linkMbps
 Uptime=$uptimeText;LastBoot=$lastBootText;Processes=$processCount;ProcessThreads=$processThreadCount;ProcessSensorError=$processSensorError
 Defender=$defenderText;Firewall=$firewallText;TPM=$tpmText;SecureBoot=$secureBootText;Activation=$activationText;LatestUpdate=$latestUpdateText
 HasBattery=$false;Battery='Battery sensor not queried';BatteryHealth='Not reported by battery firmware';BatteryCapacity='Capacity data unavailable';InventoryUpdated=$DoInventoryRefresh
}
'@

# A21: Overview control cache. The named controls never change after the window is built, so one FindName per name is enough (null is never cached).
$script:OvControlCache = @{}
function OvC {
    param([string]$Name)
    $hit = $script:OvControlCache[$Name]
    if ($null -ne $hit) { return $hit }
    $found = $script:Window.FindName($Name)
    if ($null -ne $found) { $script:OvControlCache[$Name] = $found }
    return $found
}
# A21: shared frozen brushes for the Overview bars and gauges (same colours as before, created once).
$script:OvBrushCache = @{}
$script:OvGaugeGeometryText = @{}
function Get-AMROvBrush {
    param([int]$Red,[int]$Green,[int]$Blue)
    $cacheKey = '{0},{1},{2}' -f $Red,$Green,$Blue
    $cachedBrush = $script:OvBrushCache[$cacheKey]
    if ($null -eq $cachedBrush) {
        $cachedBrush = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb([byte]$Red,[byte]$Green,[byte]$Blue))
        $cachedBrush.Freeze()
        $script:OvBrushCache[$cacheKey] = $cachedBrush
    }
    return $cachedBrush
}

function Set-AMROverviewProgress {
    param([string]$Name,[object]$Value)
    $bar = OvC $Name
    if (-not $bar -or $null -eq $Value) { return }
    try {
        $target = [Math]::Max(0,[Math]::Min(100,[double]$Value))
        if([Math]::Abs($target-[double]$bar.Value) -lt 0.05){return}
        $animation = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $animation.From = [double]$bar.Value
        $animation.To = $target
        $animation.Duration = [TimeSpan]::FromMilliseconds(420)
        $animation.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
        if($Name -match 'CPU' -or $Name -match 'Memory'){
            if($target -ge 85){$bar.Foreground=(Get-AMROvBrush 218 104 104)}
            elseif($target -ge 65){$bar.Foreground=(Get-AMROvBrush 211 169 103)}
            elseif($Name -match 'Memory'){$bar.Foreground=(Get-AMROvBrush 85 196 161)}
            else{$bar.Foreground=(Get-AMROvBrush 86 166 232)}
        } elseif($Name -match 'Drive|Storage'){
            if($target -ge 90){$bar.Foreground=(Get-AMROvBrush 218 104 104)}
            elseif($target -ge 80){$bar.Foreground=(Get-AMROvBrush 211 169 103)}
            else{$bar.Foreground=(Get-AMROvBrush 111 168 201)}
        }
        $bar.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty,$animation)
    } catch { try { $bar.Value = [double]$Value } catch {} }
}

function Set-AMROverviewUnavailable {
    param([string]$Reason = 'Sensor data unavailable')
    foreach ($name in @('ovCPUUsageValue','ovMemoryUsageValue','ovGPUUsageValue','ovNetworkStatusValue')) {
        $control = OvC $name
        if ($control) { $control.Text = 'N/A' }
    }
    foreach ($name in @('ovCPUUsageDetail','ovMemoryUsageDetail','ovGPUUsageDetail','ovNetworkStatusDetail')) {
        $control = OvC $name
        if ($control) { $control.Text = $Reason }
    }
    # Preserve the local identity snapshot; only live sensor values are marked unavailable.
    foreach ($name in @('ovCPUUsageBar','ovMemoryUsageBar')) {
        $control = OvC $name
        if ($control) { try { $control.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty,$null); $control.Value = 0 } catch {} }
    }
    Set-AMRCircularGauge 'ovCpuGaugeArc' 'ovLiveCPUValue' $null
    Set-AMRCircularGauge 'ovMemoryGaugeArc' 'ovLiveMemoryValue' $null
    Set-AMRCircularGauge 'ovGpuGaugeArc' 'ovLiveGPUValue' $null
    foreach($name in @('ovLiveCPUDetail','ovLiveMemoryDetail','ovLiveGPUDetail','ovNetworkRateDetail','ovLiveNetworkRates')){
        $control=OvC $name;if($control){$control.Text=$Reason}
    }
    $networkControl=OvC 'ovLiveNetworkStatus';if($networkControl){$networkControl.Text='Sensor unavailable'}
    $storageDetail=OvC 'ovSystemDriveStorageDetail';if($storageDetail){$storageDetail.Text='System drive sensor unavailable'}
    $storageValue=OvC 'ovSystemDriveStorageValue';if($storageValue){$storageValue.Text='N/A'}
    $storageBar=OvC 'ovSystemDriveStorageBar';if($storageBar){$storageBar.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty,$null);$storageBar.Value=0}
}

function Set-AMRCircularGauge {
    param([string]$PathName,[string]$ValueName,[object]$Value)
    $path=OvC $PathName; $label=OvC $ValueName
    if($null -eq $Value -or -not $path -or -not $label) {
        if($label){$label.Text='N/A'}
        if($path){$path.Data=[System.Windows.Media.Geometry]::Parse('M 52,4 L 52,4'); $script:OvGaugeGeometryText.Remove($PathName)}
        return
    }
    $pct=[Math]::Max(0,[Math]::Min(100,[double]$Value))
    $label.Text=('{0:N0}%' -f $pct)
    if($pct -lt 0.5) { $path.Data=[System.Windows.Media.Geometry]::Parse('M 52,4 L 52,4'); $script:OvGaugeGeometryText.Remove($PathName); return }
    $drawPct=[Math]::Min(99.9,$pct)
    $angle=$drawPct*3.6*[Math]::PI/180.0
    $x=52.0+48.0*[Math]::Sin($angle)
    $y=52.0-48.0*[Math]::Cos($angle)
    $large=if($drawPct -gt 50){1}else{0}
    if($PathName -match 'CPU'){
        if($pct -ge 85){$path.Stroke=[System.Windows.Media.Brushes]::IndianRed}
        elseif($pct -ge 65){$path.Stroke=[System.Windows.Media.Brushes]::Goldenrod}
        else{$path.Stroke=[System.Windows.Media.Brushes]::LightSkyBlue}
    } elseif($PathName -match 'Memory'){
        if($pct -ge 85){$path.Stroke=[System.Windows.Media.Brushes]::IndianRed}
        elseif($pct -ge 70){$path.Stroke=[System.Windows.Media.Brushes]::Goldenrod}
        else{$path.Stroke=[System.Windows.Media.Brushes]::MediumAquamarine}
    } else {
        if($pct -ge 90){$path.Stroke=[System.Windows.Media.Brushes]::IndianRed}
        elseif($pct -ge 80){$path.Stroke=[System.Windows.Media.Brushes]::Goldenrod}
        else{$path.Stroke=[System.Windows.Media.Brushes]::LightSteelBlue}
    }
    try { $geometryText=[string]::Format([Globalization.CultureInfo]::InvariantCulture,'M 52,4 A 48,48 0 {0} 1 {1:0.###},{2:0.###}',$large,$x,$y); if($script:OvGaugeGeometryText[$PathName] -ne $geometryText){ $path.Data=[System.Windows.Media.Geometry]::Parse($geometryText); $script:OvGaugeGeometryText[$PathName]=$geometryText } } catch {}
}

function Set-AMRHistoryPolyline {
    param([string]$CanvasName,[string]$LineName,[object[]]$Values,[double]$Maximum=100)
    $canvas=OvC $CanvasName; $line=OvC $LineName
    if(-not $canvas -or -not $line){return}
    $points=[System.Windows.Media.PointCollection]::new()
    $items=$Values
    if($items.Count -lt 2){$line.Points=$points;return}
    $width=[double]$canvas.ActualWidth; $height=[double]$canvas.ActualHeight
    if($width -lt 10){$width=360}; if($height -lt 10){$height=100}
    if($Maximum -le 0){$Maximum=1}
    for($i=0;$i -lt $items.Count;$i++){
        if($null -eq $items[$i]){continue}
        $x=($i/([Math]::Max(1,$items.Count-1)))*$width
        $y=$height-(([Math]::Max(0,[double]$items[$i])/$Maximum)*($height-5))-2
        $y=[Math]::Max(2,[Math]::Min($height-2,$y))
        [void]$points.Add([System.Windows.Point]::new($x,$y))
    }
    $line.Points=$points
}

function Update-AMROverviewHistory {
    param([object]$Snapshot)
    $state=$script:OverviewTelemetryState
    if(-not $state){return}
    $now=Get-Date
    $rxRate=$null;$txRate=$null
    $hasRx=($Snapshot.PSObject.Properties['NetRxBytes'] -and $null -ne $Snapshot.NetRxBytes)
    $hasTx=($Snapshot.PSObject.Properties['NetTxBytes'] -and $null -ne $Snapshot.NetTxBytes)
    if($hasRx -and $hasTx){
        $adapter=[string]$Snapshot.NetworkAdapter
        if($state.PreviousNetworkSample -and $state.PreviousNetworkSample.Adapter -eq $adapter){
            $elapsed=($now-$state.PreviousNetworkSample.Timestamp).TotalSeconds
            if($elapsed -gt 0 -and [long]$Snapshot.NetRxBytes -ge [long]$state.PreviousNetworkSample.Rx -and [long]$Snapshot.NetTxBytes -ge [long]$state.PreviousNetworkSample.Tx){
                $rxRate=([long]$Snapshot.NetRxBytes-[long]$state.PreviousNetworkSample.Rx)/$elapsed/1MB
                $txRate=([long]$Snapshot.NetTxBytes-[long]$state.PreviousNetworkSample.Tx)/$elapsed/1MB
            }
        }
        $state.PreviousNetworkSample=[pscustomobject]@{Adapter=$adapter;Rx=[long]$Snapshot.NetRxBytes;Tx=[long]$Snapshot.NetTxBytes;Timestamp=$now}
    }
    $cpu=$Snapshot.CPUPercent
    $memory=$Snapshot.MemoryPercent
    $driveC=@($Snapshot.DiskRows | Where-Object {$_.Name -match '^C:'} | Select-Object -First 1)
    $driveValue=if($driveC.Count -gt 0){[double]$driveC[0].UsedPercent}else{$null}
    $gpuValue=$Snapshot.GPUPercent
    $entry=[pscustomobject]@{Timestamp=$now;CPU=$cpu;Memory=$memory;GPU=$gpuValue;Download=$rxRate;Upload=$txRate;DriveC=$driveValue}
    [void]$state.History.Add($entry)
    while($state.History.Count -gt 0 -and $state.History[0].Timestamp -lt $now.AddSeconds(-60)){$state.History.RemoveAt(0)}; while($state.History.Count -gt 60){$state.History.RemoveAt(0)}
    $histCount=$state.History.Count
    $cpuValues=New-Object 'object[]' $histCount; $gpuValues=New-Object 'object[]' $histCount
    $downloadValues=New-Object 'object[]' $histCount; $uploadValues=New-Object 'object[]' $histCount
    $networkMax=1.0; $anyRate=$false; $maxRate=0.0
    for($hi=0;$hi -lt $histCount;$hi++){
        $he=$state.History[$hi]
        $cpuValues[$hi]=$he.CPU; $gpuValues[$hi]=$he.GPU; $downloadValues[$hi]=$he.Download; $uploadValues[$hi]=$he.Upload
        if($null -ne $he.Download){$anyRate=$true;if([double]$he.Download -gt $maxRate){$maxRate=[double]$he.Download}}
        if($null -ne $he.Upload){$anyRate=$true;if([double]$he.Upload -gt $maxRate){$maxRate=[double]$he.Upload}}
    }
    if($anyRate){$networkMax=[Math]::Max(0.1,$maxRate*1.15)}
    Set-AMRHistoryPolyline 'ovCpuHistoryCanvas' 'ovCpuHistoryLine' $cpuValues 100
    Set-AMRHistoryPolyline 'ovGpuHistoryCanvas' 'ovGpuHistoryLine' $gpuValues 100
    Set-AMRHistoryPolyline 'ovNetworkHistoryCanvas' 'ovNetworkDownloadLine' $downloadValues $networkMax
    Set-AMRHistoryPolyline 'ovNetworkHistoryCanvas' 'ovNetworkUploadLine' $uploadValues $networkMax
    Set-AMRCircularGauge 'ovCpuGaugeArc' 'ovLiveCPUValue' $cpu
    Set-AMRCircularGauge 'ovMemoryGaugeArc' 'ovLiveMemoryValue' $memory
    $gpuValue=$Snapshot.GPUPercent
    Set-AMRCircularGauge 'ovGpuGaugeArc' 'ovLiveGPUValue' $gpuValue
    if($null -ne $gpuValue){(OvC 'ovLiveGPUDetail').Text=('GPU engine utilization · {0}' -f [string]$Snapshot.GPUSensorSource)}else{(OvC 'ovLiveGPUDetail').Text='GPU utilization unavailable: '+[string]$Snapshot.GPUSensorError}
    if($null -ne $cpu){(OvC 'ovLiveCPUDetail').Text=('GetSystemTimes · {0:N0} logical processors' -f $Snapshot.Threads)}else{(OvC 'ovLiveCPUDetail').Text='Unavailable: '+[string]$Snapshot.CPUSensorError}
    if($null -ne $memory){(OvC 'ovLiveMemoryDetail').Text=('{0:N1} GB used of {1:N1} GB total' -f ($Snapshot.UsedMB/1024),($Snapshot.TotalMB/1024));(OvC 'ovRAMAvailable').Text=('Available RAM: {0:N1} GB' -f ($Snapshot.FreeMB/1024))}else{(OvC 'ovLiveMemoryDetail').Text='Unavailable: '+[string]$Snapshot.MemorySensorError;(OvC 'ovRAMAvailable').Text='Available RAM: unavailable'}
    if($null -ne $rxRate -and $null -ne $txRate){
        (OvC 'ovNetworkRateDetail').Text=('Download {0:N2} MB/s · Upload {1:N2} MB/s' -f $rxRate,$txRate)
        (OvC 'ovLiveNetworkRates').Text=('Download: {0:N2} MB/s  ·  Upload: {1:N2} MB/s' -f $rxRate,$txRate)
    }else{
        if($null -eq $Snapshot.NetRxBytes -or $null -eq $Snapshot.NetTxBytes){
            $rateError=if($Snapshot.NetworkSensorError){[string]$Snapshot.NetworkSensorError}else{'Network byte counters unavailable'}
            (OvC 'ovNetworkRateDetail').Text='Throughput sensor unavailable: '+$rateError
            (OvC 'ovLiveNetworkRates').Text='Download: unavailable  ·  Upload: unavailable'
        }else{
            (OvC 'ovNetworkRateDetail').Text='Waiting for two valid network counter samples'
            (OvC 'ovLiveNetworkRates').Text='Download: N/A  ·  Upload: N/A (sampling)'
        }
    }
    $status=if($Snapshot.PSObject.Properties['NetworkStatus']){[string]$Snapshot.NetworkStatus}else{'Sensor unavailable'}
    (OvC 'ovLiveNetworkStatus').Text=$status
    (OvC 'ovLiveNetworkAdapter').Text='Adapter: '+[string]$Snapshot.NetworkAdapter
    (OvC 'ovLiveNetworkIP').Text='IPv4: '+[string]$Snapshot.IPv4
    (OvC 'ovLiveNetworkGateway').Text='Gateway: '+[string]$Snapshot.Gateway
    (OvC 'ovLiveActivityStatus').Text=('Last sample: {0}' -f $now.ToString('HH:mm:ss'))
    if($null -ne $Snapshot.Processes){(OvC 'ovProcesses').Text=('Running processes: {0:N0}' -f $Snapshot.Processes)}else{(OvC 'ovProcesses').Text='Running processes: unavailable'}
    if($null -ne $Snapshot.ProcessThreads){(OvC 'ovLiveThreads').Text=('Threads: {0:N0}' -f $Snapshot.ProcessThreads)}else{(OvC 'ovLiveThreads').Text='Threads: unavailable'}
}

function Apply-AMROverviewSnapshot {
    param([Parameter(Mandatory=$true)][object]$Snapshot,[switch]$FastOnly)
    $cpuPercent = $null
    if($Snapshot.PSObject.Properties['CPUPercent'] -and $null -ne $Snapshot.CPUPercent){$cpuPercent=[double]$Snapshot.CPUPercent}
    $cpuRaw = $Snapshot.CPURaw
    if($null -eq $cpuPercent -and $null -ne $cpuRaw -and @($cpuRaw).Count -ge 3){
        $currentCpu=[pscustomobject]@{Idle=[ulong]$cpuRaw[0];Kernel=[ulong]$cpuRaw[1];User=[ulong]$cpuRaw[2];Timestamp=(Get-Date)}
        $previousCpu=$script:OverviewTelemetryState.PreviousCpuSample
        if($previousCpu){
            $idleDelta=$currentCpu.Idle-$previousCpu.Idle
            $kernelDelta=$currentCpu.Kernel-$previousCpu.Kernel
            $userDelta=$currentCpu.User-$previousCpu.User
            $totalDelta=$kernelDelta+$userDelta
            if($totalDelta -gt 0 -and $idleDelta -le $totalDelta){$cpuPercent=[Math]::Round(([Math]::Max(0.0,[Math]::Min(100.0,(1.0-([double]$idleDelta/[double]$totalDelta))*100.0))),1)}
        }
        $script:OverviewTelemetryState.PreviousCpuSample=$currentCpu
    }
    if($null -eq $cpuPercent -and $Snapshot.CPUSensorError){$Snapshot.CPUPercent=$null}
    else{$Snapshot.CPUPercent=$cpuPercent}
    $memoryPercent = $Snapshot.MemoryPercent
    if ($null -ne $cpuPercent) {
        (OvC 'ovCPUUsageValue').Text = ('{0:N1}%' -f [double]$cpuPercent)
        (OvC 'ovCPUUsageDetail').Text = ('Live CPU load  •  {0} logical processors' -f $Snapshot.Threads)
        (OvC 'ovCPULoad').Text = ('Current load: {0:N1}%' -f [double]$cpuPercent)
        Set-AMROverviewProgress 'ovCPUUsageBar' $cpuPercent
    } else {
        if($Snapshot.CPUSensorError){(OvC 'ovCPUUsageValue').Text='N/A';(OvC 'ovCPUUsageDetail').Text='CPU sensor unavailable: '+[string]$Snapshot.CPUSensorError;(OvC 'ovCPULoad').Text='CPU usage: unavailable'}
        else{(OvC 'ovCPUUsageValue').Text='Sampling…';(OvC 'ovCPUUsageDetail').Text='Collecting the second real GetSystemTimes sample';(OvC 'ovCPULoad').Text='CPU usage: sampling'}
        $cpuBar=OvC 'ovCPUUsageBar';if($cpuBar){$cpuBar.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty,$null);$cpuBar.Value=0}
    }
    if ($null -ne $memoryPercent) {
        (OvC 'ovMemoryUsageValue').Text = ('{0:N1}%' -f [double]$memoryPercent)
        (OvC 'ovMemoryUsageDetail').Text = ('{0:N1} GB used of {1:N1} GB' -f ($Snapshot.UsedMB/1024),($Snapshot.TotalMB/1024))
        Set-AMROverviewProgress 'ovMemoryUsageBar' $memoryPercent
        (OvC 'ovRAMTotal').Text = ('Installed RAM: {0:N1} GB' -f ($Snapshot.TotalMB/1024))
        (OvC 'ovRAMUsage').Text = ''
        (OvC 'ovOverviewRAMAvailable').Text = ''
        (OvC 'ovRAMAvailable').Text = ('Available RAM: {0:N1} GB' -f ($Snapshot.FreeMB/1024))
    } else {
        (OvC 'ovMemoryUsageValue').Text = 'N/A'; (OvC 'ovMemoryUsageDetail').Text = 'Memory data unavailable'; (OvC 'ovRAMTotal').Text = 'Total RAM: unavailable'; (OvC 'ovRAMUsage').Text = ''; (OvC 'ovOverviewRAMAvailable').Text = ''; (OvC 'ovRAMAvailable').Text = 'Available RAM: unavailable'
        $memoryBar=OvC 'ovMemoryUsageBar';if($memoryBar){$memoryBar.BeginAnimation([System.Windows.Controls.Primitives.RangeBase]::ValueProperty,$null);$memoryBar.Value=0}
    }
    $driveC = @($Snapshot.DiskRows | Where-Object { $_.Name -match '^C:' } | Select-Object -First 1)
    if($driveC.Count -gt 0){
        $systemDrive=$driveC[0]
        (OvC 'ovSystemDriveStorageDetail').Text=('C: {0:N1} GB free of {1:N1} GB' -f $systemDrive.FreeGB,$systemDrive.TotalGB)
        (OvC 'ovSystemDriveStorageValue').Text=('{0:N0}% used' -f $systemDrive.UsedPercent)
        Set-AMROverviewProgress 'ovSystemDriveStorageBar' $systemDrive.UsedPercent
    } else {
        (OvC 'ovSystemDriveStorageDetail').Text='C: unavailable'
        (OvC 'ovSystemDriveStorageValue').Text='N/A'
        $storageBar=OvC 'ovSystemDriveStorageBar';if($storageBar){$storageBar.Value=0}
    }
    $networkState=if($Snapshot.PSObject.Properties['NetworkStatus']){[string]$Snapshot.NetworkStatus}elseif($Snapshot.NetworkConnected){'Active interface'}else{'Sensor unavailable'}
    (OvC 'ovNetworkStatusValue').Text=$networkState
    (OvC 'ovNetworkStatusDetail').Text=if($null -ne $Snapshot.LinkMbps){('{0:N0} Mbps · {1}' -f $Snapshot.LinkMbps,[string]$Snapshot.NetworkAdapter)}elseif($Snapshot.PSObject.Properties['NetworkSensorError']){[string]$Snapshot.NetworkSensorError}else{'Network sensor initializing'}
    # GPU value is merged from its isolated worker; unavailable providers stay explicit.
    $gpuPercent=$null
    if($Snapshot.PSObject.Properties['GPUPercent'] -and $null -ne $Snapshot.GPUPercent){$gpuPercent=[double]$Snapshot.GPUPercent}
    if($null -ne $gpuPercent){
        (OvC 'ovGPUUsageValue').Text=('{0:N1}%' -f $gpuPercent)
        (OvC 'ovGPUUsageDetail').Text=if($Snapshot.GPUSensorSource){[string]$Snapshot.GPUSensorSource}else{'Windows GPU engine utilization'}
        Set-AMROverviewProgress 'ovGPUUsageBar' $gpuPercent
    }else{
        (OvC 'ovGPUUsageValue').Text='N/A'
        (OvC 'ovGPUUsageDetail').Text=if($Snapshot.GPUSensorError){'Unavailable: '+[string]$Snapshot.GPUSensorError}else{'Waiting for GPU engine sample'}
    }

    if(-not $FastOnly){
    (OvC 'ovOS').Text = [string]$Snapshot.OSName
    (OvC 'ovBuild').Text = 'Build: ' + [string]$Snapshot.Build
    (OvC 'ovPCName').Text = [string]$Snapshot.PCName
    (OvC 'ovArch').Text = [string]$Snapshot.Architecture
    (OvC 'ovDeviceType').Text = [string]$Snapshot.DeviceType
    (OvC 'ovLastBoot').Text = 'Last boot: ' + [string]$Snapshot.LastBoot
    (OvC 'ovCPU').Text = [string]$Snapshot.CPUName
    (OvC 'ovThreads').Text = ('Logical processors: {0}' -f $Snapshot.Threads)
    if($Snapshot.InventoryUpdated){
        (OvC 'ovGPU').Text = [string]$Snapshot.GPUName
        (OvC 'ovOverviewGPUDetails').Text = 'Graphics details: ' + [string]$Snapshot.GPUMemory
        (OvC 'ovGPUDetails').Text = 'Graphics details: ' + [string]$Snapshot.GPUMemory
        (OvC 'ovOverviewDisplay').Text = 'Active display: ' + [string]$Snapshot.Display
        (OvC 'ovDisplay').Text = 'Display: ' + [string]$Snapshot.Display
    }
    (OvC 'ovMobo').Text = [string]$Snapshot.Board
    (OvC 'ovBIOS').Text = 'BIOS: ' + [string]$Snapshot.BIOS
    (OvC 'ovBIOSDate').Text = 'BIOS date: ' + [string]$Snapshot.BIOSDate
    (OvC 'ovProcesses').Text = if($null -ne $Snapshot.Processes -and $null -ne $Snapshot.ProcessThreads){'Running processes: {0:N0}  •  Threads: {1:N0}' -f $Snapshot.Processes,$Snapshot.ProcessThreads}elseif($null -ne $Snapshot.Processes){'Running processes: {0:N0}' -f $Snapshot.Processes}else{'Running processes: unavailable'}
    $batteryCard = OvC 'ovBatteryCard'
    if ($batteryCard) {
        $batteryCard.Visibility = if ($Snapshot.HasBattery) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        if ($Snapshot.HasBattery) { (OvC 'ovBatteryStatus').Text = 'Battery: ' + [string]$Snapshot.Battery; (OvC 'ovBatteryHealth').Text = 'Battery health: ' + [string]$Snapshot.BatteryHealth; (OvC 'ovBatteryCapacity').Text = [string]$Snapshot.BatteryCapacity }
    }
    }
    try {
        $otherDriveRows=@($Snapshot.DiskRows | Where-Object { $_.Name -match '^[A-Z]:' } | Sort-Object Name)
        $diskSignature=(@($otherDriveRows | ForEach-Object {'{0}:{1}:{2}' -f $_.Name,$_.UsedPercent,$_.FreeGB}) -join '|')
        if($diskSignature -ne $script:OverviewTelemetryState.DiskSignature){
            (OvC 'ovDisks').ItemsSource=$otherDriveRows
            $emptyDriveHint=OvC 'ovDisksEmpty';if($emptyDriveHint){$emptyDriveHint.Visibility=if($otherDriveRows.Count -gt 0){[System.Windows.Visibility]::Collapsed}else{[System.Windows.Visibility]::Visible}}
            $script:OverviewTelemetryState.DiskSignature=$diskSignature
        }
    } catch { Write-AMRLog ('LIVE_SENSOR [DiskUI] update failed: '+$_.Exception.Message) WARNING Overview }
    (OvC 'ovOverviewUptime').Text = 'System uptime: ' + [string]$Snapshot.Uptime
    (OvC 'ovUptime').Text = 'System uptime: ' + [string]$Snapshot.Uptime
    (OvC 'ovOverviewProcesses').Text = if($null -ne $Snapshot.Processes -and $null -ne $Snapshot.ProcessThreads){'Processes: {0:N0}  •  Threads: {1:N0}' -f $Snapshot.Processes,$Snapshot.ProcessThreads}elseif($null -ne $Snapshot.Processes){'Processes: {0:N0}' -f $Snapshot.Processes}else{'Processes: unavailable'}
    $sampleStamp=(Get-Date).ToString('HH:mm:ss')
    (OvC 'ovLastRefresh').Text = ''
    $liveRefreshStatus=OvC 'ovLiveRefreshStatus';if($liveRefreshStatus){$liveRefreshStatus.Text='Last sample: '+$sampleStamp}
    $shouldLogSensors=$false
    if($Snapshot.PSObject.Properties['NetworkStatus']){
        $perfHist = Get-AMRPerfNow
        Update-AMROverviewHistory -Snapshot $Snapshot
        Add-AMRPerfSince 'ov.apply.history' $perfHist
        if($script:OverviewTelemetryState.History.Count -gt 0){
            $latestOverviewSample=$script:OverviewTelemetryState.History[$script:OverviewTelemetryState.History.Count-1]
            if($null -ne $latestOverviewSample.Download -and $null -ne $latestOverviewSample.Upload){
                (OvC 'ovNetworkStatusDetail').Text=('↓ {0:N2} MB/s  ↑ {1:N2} MB/s' -f $latestOverviewSample.Download,$latestOverviewSample.Upload)
            }
        }
        if($null -eq $Snapshot.CPUPercent){$cpuGaugeValue=OvC 'ovLiveCPUValue';if($cpuGaugeValue){$cpuGaugeValue.Text=if($Snapshot.CPUSensorError){'N/A'}else{'Sampling…'}}}
        $nowForLog=Get-Date
        $shouldLogSensors=(($nowForLog-$script:OverviewTelemetryState.LastSensorLog).TotalSeconds -ge 30)
        if($shouldLogSensors){
            $script:OverviewTelemetryState.LastSensorLog=$nowForLog
        $stamp=(Get-Date).ToString('o')
        foreach($sensor in @(
            [pscustomobject]@{Name='CPU';Source='GetSystemTimes-delta';Value=$(if($null -ne $Snapshot.CPUPercent){$Snapshot.CPUPercent}elseif($Snapshot.CPURaw){'WarmingUp'}else{'Unavailable'});Status=$(if($null -ne $Snapshot.CPUPercent){'success'}elseif($Snapshot.CPURaw){'sampling'}else{'unavailable'});Error=[string]$Snapshot.CPUSensorError},
            [pscustomobject]@{Name='RAM';Source='GlobalMemoryStatusEx';Value=$(if($null -ne $Snapshot.MemoryPercent){('percent={0};usedMB={1:N0};availableMB={2:N0};totalMB={3:N0}' -f $Snapshot.MemoryPercent,$Snapshot.UsedMB,$Snapshot.FreeMB,$Snapshot.TotalMB)}else{'Unavailable'});Status=$(if($null -ne $Snapshot.MemoryPercent){'success'}else{'unavailable'});Error=[string]$Snapshot.MemorySensorError},
            [pscustomobject]@{Name='GPU';Source=[string]$Snapshot.GPUSensorSource;Value=$(if($null -ne $Snapshot.GPUPercent){$Snapshot.GPUPercent}else{'Unavailable'});Status=$(if($null -ne $Snapshot.GPUPercent){'success'}else{'unavailable'});Error=[string]$Snapshot.GPUSensorError},
            [pscustomobject]@{Name='Network';Source='NetworkInterface.GetIPStatistics-byte-counters';Value=('status={0};rxBytes={1};txBytes={2}' -f $Snapshot.NetworkStatus,$Snapshot.NetRxBytes,$Snapshot.NetTxBytes);Status=$(if($null -ne $Snapshot.NetRxBytes -and $null -ne $Snapshot.NetTxBytes){'success'}else{'unavailable'});Error=[string]$Snapshot.NetworkSensorError},
            [pscustomobject]@{Name='Disk';Source='DriveInfo';Value=$(if($driveC.Count -gt 0){('percent={0};freeGB={1:N1};totalGB={2:N1}' -f $driveC[0].UsedPercent,$driveC[0].FreeGB,$driveC[0].TotalGB)}else{'Unavailable'});Status=$(if($driveC.Count -gt 0){'success'}else{'unavailable'});Error=[string]$Snapshot.DiskSensorError},
            [pscustomobject]@{Name='DiskVolumes';Source='DriveInfo';Value=$(if(@($Snapshot.DiskRows).Count -gt 0){(@($Snapshot.DiskRows | ForEach-Object {'{0}={1:N0}%' -f $_.Name,$_.UsedPercent}) -join ', ')}else{'Unavailable'});Status=$(if(@($Snapshot.DiskRows).Count -gt 0){'success'}else{'unavailable'});Error=[string]$Snapshot.DiskSensorError},
            [pscustomobject]@{Name='Processes';Source='Process.GetProcesses';Value=$(if($null -ne $Snapshot.Processes){$Snapshot.Processes}else{'Unavailable'});Status=$(if($null -ne $Snapshot.Processes){'success'}else{'unavailable'});Error=[string]$Snapshot.ProcessSensorError},
            [pscustomobject]@{Name='Threads';Source='Process.Threads';Value=$(if($null -ne $Snapshot.ProcessThreads){$Snapshot.ProcessThreads}else{'Unavailable'});Status=$(if($null -ne $Snapshot.ProcessThreads){'success'}else{'unavailable'});Error=[string]$Snapshot.ProcessSensorError}
        )){
            $logLine='LIVE_SENSOR [{0}] source={1} value={2} timestamp={3} status={4}' -f $sensor.Name,$sensor.Source,$sensor.Value,$stamp,$sensor.Status
            if($sensor.Error){$logLine+=' error='+$sensor.Error}
            Write-AMRLog $logLine $(if($sensor.Status -eq 'success'){'INFO'}else{'WARNING'}) Overview
        }
        if($script:OverviewTelemetryState.History.Count -gt 0){
            $latestNetworkSample=$script:OverviewTelemetryState.History[$script:OverviewTelemetryState.History.Count-1]
            $networkRateStatus=if($null -ne $latestNetworkSample.Download -and $null -ne $latestNetworkSample.Upload){'success'}else{'sampling'}
            $networkRateLog='LIVE_SENSOR [NetworkRate] source=byte-counter-delta value=downloadMBps={0};uploadMBps={1} timestamp={2} status={3}' -f $latestNetworkSample.Download,$latestNetworkSample.Upload,$stamp,$networkRateStatus
            Write-AMRLog $networkRateLog $(if($networkRateStatus -eq 'success'){'INFO'}else{'DEBUG'}) Overview
        }
            Write-AMRLog 'Overview telemetry snapshot updated from local Windows hardware and performance providers.' SUCCESS Overview
        }
    }
}

function Get-AMROverviewFastSnapshot {
    # Read the identity and the most important capacity figures directly from the
    # local OS, registry, .NET and Win32 APIs. No WMI/CIM provider is required here.
    $osKey = $null; $bios = $null; $cpuKey = $null
    try { $osKey = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop } catch {}
    try { $bios = Get-ItemProperty -LiteralPath 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -ErrorAction Stop } catch {}
    try { $cpuKey = Get-ItemProperty -LiteralPath 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -ErrorAction Stop } catch {}

    $osProduct = if ($osKey -and $osKey.ProductName) { [string]$osKey.ProductName } else { [Environment]::OSVersion.VersionString }
    $osBuildNumber = 0; try { $osBuildNumber = [int]$osKey.CurrentBuildNumber } catch { try { $osBuildNumber = [Environment]::OSVersion.Version.Build } catch {} }
    $editionId = if ($osKey -and $osKey.EditionID) { [string]$osKey.EditionID } else { '' }
    $editionName = switch -Regex ($editionId) { '^Professional$' {'Pro'} '^Core$' {'Home'} '^Enterprise$' {'Enterprise'} '^Education$' {'Education'} '^ProfessionalWorkstation$' {'Pro for Workstations'} '^ProfessionalEducation$' {'Pro Education'} default { $editionId } }
    $osName = $osProduct
    if ($osProduct -notmatch '(?i)Windows\s+Server') {
        $detectedWindowsFamily = switch ($osBuildNumber) {
            { $_ -ge 22000 } { 'Windows 11'; break }
            { $_ -ge 10240 } { 'Windows 10'; break }
            { $_ -ge 9600 } { 'Windows 8.1'; break }
            { $_ -ge 9200 } { 'Windows 8'; break }
            { $_ -ge 7600 } { 'Windows 7'; break }
            { $_ -ge 6000 } { 'Windows Vista'; break }
            default { $osProduct }
        }
        if ($detectedWindowsFamily) { $osName=$detectedWindowsFamily; if($editionName){$osName+=' '+$editionName} }
    }
    $displayVersion = if ($osKey -and $osKey.DisplayVersion) { [string]$osKey.DisplayVersion } elseif ($osKey -and $osKey.ReleaseId) { [string]$osKey.ReleaseId } else { 'Version unavailable' }
    $build = if ($osKey -and $osKey.CurrentBuildNumber) { '{0}  •  Version {1}' -f $osKey.CurrentBuildNumber,$displayVersion } else { 'Build ' + [Environment]::OSVersion.Version.Build }
    $manufacturer = if ($bios -and $bios.SystemManufacturer) { [string]$bios.SystemManufacturer } else { 'Manufacturer unavailable' }
    $model = if ($bios -and $bios.SystemProductName) { [string]$bios.SystemProductName } elseif ($bios -and $bios.SystemFamily) { [string]$bios.SystemFamily } else { 'Model unavailable' }
    $classHint = (($manufacturer + ' ' + $model + ' ' + [string]$bios.SystemFamily) -as [string])
    $isTablet = $classHint -match '(?i)tablet|surface pro|detachable|2-in-1|convertible'
    $isLaptop = $classHint -match '(?i)laptop|notebook|portable|thinkpad|latitude|pavilion|vivobook|zenbook|elitebook|probook|inspiron|aspire|swift|toughbook|xps|vostro|ideapad|yoga|zbook|envy|spectre|travelmate|surface laptop|precision\s+(?:3[0-9]{3}|5[0-9]{3}|7[0-9]{3})|mobile workstation'
    $isMobileWorkstation = $classHint -match '(?i)precision|zbook|thinkpad\s*p[0-9]|mobile workstation|fury'
    if ($isTablet) { $deviceType='Tablet' } elseif ($isLaptop -and $isMobileWorkstation) { $deviceType='Laptop Workstation' } elseif ($isLaptop) { $deviceType='Laptop' } elseif ($classHint -match '(?i)precision|thinkstation|workstation') { $deviceType='Desktop Workstation' } else { $deviceType='Desktop PC' }
    if ($env:SESSIONNAME -match 'RDP') { $deviceType='Remote session' }
    $deviceDisplay = ('{0} {1}' -f ($manufacturer -replace '(?i)\s+Inc\.?$',''),$model).Trim()

    $cpuName = if ($cpuKey -and $cpuKey.ProcessorNameString) { ([string]$cpuKey.ProcessorNameString).Trim() } else { 'Processor name unavailable' }
    $coreCount = 'N/A'

    $totalMB = 0.0; $freeMB = 0.0; $usedMB = 0.0; $memoryPercent = $null
    try {
        if (-not ('AMROverviewNativeMemory' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
[StructLayout(LayoutKind.Sequential, CharSet=CharSet.Auto)]
public class AMRMemoryStatusEx {
 public uint dwLength; public uint dwMemoryLoad; public ulong ullTotalPhys; public ulong ullAvailPhys;
 public ulong ullTotalPageFile; public ulong ullAvailPageFile; public ulong ullTotalVirtual; public ulong ullAvailVirtual; public ulong ullAvailExtendedVirtual;
 public AMRMemoryStatusEx(){ dwLength=(uint)Marshal.SizeOf(typeof(AMRMemoryStatusEx)); }
}
public static class AMROverviewNativeMemory {
 [DllImport("kernel32.dll", SetLastError=true)] public static extern bool GlobalMemoryStatusEx([In,Out] AMRMemoryStatusEx lpBuffer);
 [DllImport("kernel32.dll")] public static extern ulong GetTickCount64();
}
'@ -ErrorAction Stop | Out-Null
        }
        $mem = New-Object AMRMemoryStatusEx
        if ([AMROverviewNativeMemory]::GlobalMemoryStatusEx($mem)) {
            $totalMB = [double]$mem.ullTotalPhys / 1MB
            $freeMB = [double]$mem.ullAvailPhys / 1MB
            $usedMB = [Math]::Max(0,$totalMB-$freeMB)
            if ($totalMB -gt 0) { $memoryPercent = [Math]::Round(($usedMB/$totalMB)*100,1) }
        }
    } catch {}

    $diskRows = @(); $systemDisk = $null
    try {
        foreach ($drive in [System.IO.DriveInfo]::GetDrives()) {
            try {
                if ($drive.IsReady -and $drive.DriveType -eq [System.IO.DriveType]::Fixed -and $drive.TotalSize -gt 0) {
                    $total = [double]$drive.TotalSize; $free = [double]$drive.AvailableFreeSpace
                    $pct = [Math]::Round((($total-$free)/$total)*100,1)
                    $entry = [pscustomobject]@{DisplayText=('{0}  {1:N0}% used  •  {2:N1} GB free of {3:N1} GB' -f $drive.Name,$pct,($free/1GB),($total/1GB));Name=$drive.Name;TotalGB=[Math]::Round($total/1GB,1);FreeGB=[Math]::Round($free/1GB,1);UsedPercent=$pct;UsedPercentText=('{0:N0}%' -f $pct)}
                    $diskRows += $entry
                    if ($drive.Name.TrimEnd('\') -eq $env:SystemDrive.TrimEnd('\')) { $systemDisk = $entry }
                }
            } catch {}
        }
    } catch {}

    $boardName = 'Motherboard information unavailable'
    if ($bios -and ($bios.BaseBoardManufacturer -or $bios.BaseBoardProduct)) { $boardName = ('{0} {1}' -f $bios.BaseBoardManufacturer,$bios.BaseBoardProduct).Trim() }
    $biosName = if ($bios -and $bios.BIOSVersion) { @($bios.BIOSVersion) -join ' ' } else { 'Unavailable' }
    $biosDate = if ($bios -and $bios.BIOSReleaseDate) { @($bios.BIOSReleaseDate) -join ' ' } else { 'Unavailable' }
    $uptimeText = 'Unavailable'; $lastBootText = 'Unavailable'
    try {
        $uptime = [TimeSpan]::FromMilliseconds([double][AMROverviewNativeMemory]::GetTickCount64())
        $uptimeText = '{0}d {1}h {2}m' -f [int]$uptime.TotalDays,$uptime.Hours,$uptime.Minutes
        $lastBootText = (Get-Date).Subtract($uptime).ToString('yyyy-MM-dd HH:mm')
    } catch {}
    $processCount = 0; try { $processCount = [System.Diagnostics.Process]::GetProcesses().Count } catch {}

    [pscustomobject]@{
        OSName=$osName; Build=$build; PCName=$deviceDisplay
        Architecture=$(if ([Environment]::Is64BitOperatingSystem) {'64-bit Windows'} else {'32-bit Windows'})
        DeviceType=$deviceType; Manufacturer=$manufacturer; Model=$model
        CPUName=$cpuName; CPUPercent=$null; CPURaw=$null; CPUSensorError=''; Cores=$coreCount; Threads=[Environment]::ProcessorCount
        GPUPercent=$null; GPUSensorError='GPU sampling is starting'; GPUSensorSource='independent GPU worker'
        NetworkSensorError='Network sampling is starting'; DiskSensorError='Disk sampling is starting'; ProcessSensorError='Activity sampling is starting'
        GPUName='Graphics adapter details are being detected'; GPUMemory='Not reported yet'; Display='Display details are being detected'
        Board=$boardName; BIOS=$biosName; BIOSDate=$biosDate
        TotalMB=$totalMB; FreeMB=$freeMB; UsedMB=$usedMB; MemoryPercent=$memoryPercent; MemorySensorError=''; RAMModules='Module details updating'
        DiskRows=@($diskRows); SystemDisk=$systemDisk
        NetworkConnected=$false; NetworkStatus='Sampling'; NetRxBytes=$null; NetTxBytes=$null
        NetworkAdapter='Network details updating'; IPv4='Network details updating'; Gateway='Not queried yet'; DNS='Not queried yet'; LinkMbps=$null
        Uptime=$uptimeText; LastBoot=$lastBootText; Processes=$processCount; ProcessThreads=0
        Defender='Security status updating'; Firewall='Security status updating'; TPM='Security status updating'; SecureBoot='Security status updating'; Activation='Activation status is available in Windows Settings'; LatestUpdate='Update inventory deferred to keep live readings responsive'
        HasBattery=$false; Battery='Not detected'; BatteryHealth='Not reported'; BatteryCapacity='Unavailable'
        InventoryUpdated=$false
    }
}

function Apply-AMROverviewInventorySnapshot {
    param([Parameter(Mandatory=$true)][object]$Snapshot)
    try {
        (OvC 'ovOS').Text=[string]$Snapshot.OSName
        (OvC 'ovBuild').Text='Build: '+[string]$Snapshot.Build
        (OvC 'ovPCName').Text=[string]$Snapshot.PCName
        $deviceModelText=('{0} {1}' -f [string]$Snapshot.Manufacturer,[string]$Snapshot.Model).Trim()
        if([string]::IsNullOrWhiteSpace($deviceModelText)){$deviceModelText='Model not reported by firmware'}
        (OvC 'ovDeviceModel').Text='Model: '+$deviceModelText
        (OvC 'ovArch').Text=[string]$Snapshot.Architecture
        (OvC 'ovDeviceType').Text=[string]$Snapshot.DeviceType
        (OvC 'ovLastBoot').Text='Last boot: '+[string]$Snapshot.LastBoot
        (OvC 'ovCPU').Text=[string]$Snapshot.CPUName
        (OvC 'ovThreads').Text='Logical processors: '+[string]$Snapshot.Threads
        (OvC 'ovMobo').Text=[string]$Snapshot.Board
        (OvC 'ovBIOS').Text='BIOS: '+[string]$Snapshot.BIOS
        (OvC 'ovBIOSDate').Text='BIOS date: '+[string]$Snapshot.BIOSDate
        (OvC 'ovGPU').Text=[string]$Snapshot.GPUName
        (OvC 'ovOverviewGPUDetails').Text='Graphics details: '+[string]$Snapshot.GPUMemory
        (OvC 'ovGPUDetails').Text='Graphics details: '+[string]$Snapshot.GPUMemory
        (OvC 'ovOverviewDisplay').Text='Active display: '+[string]$Snapshot.Display
        (OvC 'ovDisplay').Text='Display: '+[string]$Snapshot.Display
        Write-AMRLog 'LIVE_SENSOR [Inventory] source=Windows registry/PnP/Security providers status=success' INFO Overview
    } catch { Write-AMRLog ('LIVE_SENSOR [Inventory] status=partial error='+$_.Exception.Message) WARNING Overview }
}

function Start-AMROverviewInventoryRefresh {
    $state=$script:OverviewTelemetryState
    if(-not $state -or $state.InventoryCurrent){return}
    $rs=$null;$ps=$null
    try {
        $perfInv = Get-AMRPerfNow
        $rs=[System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $rs.ApartmentState=[System.Threading.ApartmentState]::MTA
        $rs.ThreadOptions=[System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $rs.Open()
        Add-AMRPerfSince 'overview.inventoryRunspaceOpen' $perfInv
        $ps=[PowerShell]::Create();$ps.Runspace=$rs
        [void]$ps.AddScript($script:OverviewTelemetryWorker).AddArgument($false).AddArgument($true)
        $async=$ps.BeginInvoke()
        $state.InventoryCurrent=[pscustomobject]@{PowerShell=$ps;Runspace=$rs;Async=$async;StartedAt=(Get-Date)}
        Write-AMRLog 'LIVE_SENSOR [Inventory] background inventory refresh started.' INFO Overview
    } catch {
        if($ps){try{$ps.Dispose()}catch{}};if($rs){try{$rs.Dispose()}catch{}}
        $state.LastInventoryRefresh=Get-Date; Write-AMRLog ('LIVE_SENSOR [Inventory] could not start: '+$_.Exception.Message) WARNING Overview
    }
}

# One persistent runspace per independent sensor. The previous code created and opened a new
# runspace for every sample on the UI thread. The sample scripts, their intervals, the timeout
# handling and the one-job-per-sensor rule are unchanged; scripts run in a local scope so no
# variables leak from one sample to the next (same isolation as a fresh runspace).
$script:OverviewSensorRunspaces = @{}
# Diagnostics only: per-sensor counters for the create / reuse / replace log lines.
$script:OverviewSensorRunspaceStats = @{}
function Get-AMROverviewSensorRunspace {
    param([Parameter(Mandatory=$true)][string]$Key)
    $existing = $script:OverviewSensorRunspaces[$Key]
    $sensorStat = $null
    try {
        $sensorStat = $script:OverviewSensorRunspaceStats[$Key]
        if (-not $sensorStat) { $sensorStat = [pscustomobject]@{ Created = 0; Reused = 0 }; $script:OverviewSensorRunspaceStats[$Key] = $sensorStat }
    } catch {}
    if ($existing) {
        $usable = $false
        try {
            $usable = ($existing.RunspaceStateInfo.State -eq [System.Management.Automation.Runspaces.RunspaceState]::Opened -and
                       $existing.RunspaceAvailability -eq [System.Management.Automation.Runspaces.RunspaceAvailability]::Available)
        } catch { $usable = $false }
        if ($usable) {
            # Log the first reuse and then every 200th, so the log shows reuse without one line per sample.
            try {
                $sensorStat.Reused = [int]$sensorStat.Reused + 1
                if ($sensorStat.Reused -eq 1 -or ($sensorStat.Reused % 200) -eq 0) {
                    Write-AMRLog ('LIVE_SENSOR [Runspace] reused key={0} id={1} reuseCount={2} createdCount={3}' -f $Key,$existing.InstanceId,$sensorStat.Reused,$sensorStat.Created) INFO Overview
                }
            } catch {}
            return $existing
        }
        try { Write-AMRLog ('LIVE_SENSOR [Runspace] key={0} id={1} not reusable (state={2}, availability={3}); disposing and creating a new one.' -f $Key,$existing.InstanceId,$existing.RunspaceStateInfo.State,$existing.RunspaceAvailability) WARNING Overview } catch {}
        [void]$script:OverviewSensorRunspaces.Remove($Key)
        try { $existing.Dispose() } catch {}
    }
    $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
    $runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
    $runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
    $runspace.Open()
    $script:OverviewSensorRunspaces[$Key] = $runspace
    try {
        $sensorStat.Created = [int]$sensorStat.Created + 1
        Write-AMRLog ('LIVE_SENSOR [Runspace] created key={0} id={1} createdCount={2} activeRunspaces={3}' -f $Key,$runspace.InstanceId,$sensorStat.Created,$script:OverviewSensorRunspaces.Count) INFO Overview
    } catch {}
    return $runspace
}

function Start-AMROverviewNetworkTelemetry {
    $state=$script:OverviewTelemetryState
    if(-not $state -or $state.NetworkCurrent){return}
    $rs=$null;$ps=$null
    try{
        $rs=Get-AMROverviewSensorRunspace -Key 'Network'
        $ps=[PowerShell]::Create();$ps.Runspace=$rs
        $now=Get-Date;$doInternetProbe=(($now-$state.LastInternetProbe).TotalSeconds -ge 5)
        if($doInternetProbe){$state.LastInternetProbe=$now}
        [void]$ps.AddScript($script:OverviewNetworkTelemetryWorker,$true).AddArgument([bool]$doInternetProbe).AddArgument($state.LastInternetReachable)
        $async=$ps.BeginInvoke()
        $state.NetworkCurrent=[pscustomobject]@{PowerShell=$ps;Runspace=$rs;Async=$async;StartedAt=(Get-Date)}
    }catch{
        if($ps){try{$ps.Dispose()}catch{}};if($rs){try{$rs.Close()}catch{};try{$rs.Dispose()}catch{}}
        $state.NetworkLastSample=Get-Date;$state.NetworkStatus='Sensor unavailable';$state.NetworkSensorError=$_.Exception.Message
        Write-AMRLog ('LIVE_SENSOR [Network] could not start independent worker: '+$_.Exception.Message) WARNING Overview
    }
}

