function Start-AMROverviewActivityTelemetry {
    $state=$script:OverviewTelemetryState
    if(-not $state -or $state.ActivityCurrent){return}
    $rs=$null;$ps=$null
    try{
        $rs=Get-AMROverviewSensorRunspace -Key 'Activity'
        $ps=[PowerShell]::Create();$ps.Runspace=$rs
        [void]$ps.AddScript($script:OverviewActivityTelemetryWorker,$true)
        $async=$ps.BeginInvoke()
        $state.ActivityCurrent=[pscustomobject]@{PowerShell=$ps;Runspace=$rs;Async=$async;StartedAt=(Get-Date)}
    }catch{
        if($ps){try{$ps.Dispose()}catch{}};if($rs){try{$rs.Close()}catch{};try{$rs.Dispose()}catch{}}
        $state.ActivityLastSample=Get-Date;$state.ProcessSensorError=$_.Exception.Message
        Write-AMRLog ('LIVE_SENSOR [Activity] could not start worker: '+$_.Exception.Message) WARNING Overview
    }
}

function Start-AMROverviewTelemetry {
    param([switch]$Force)
    $state = $script:OverviewTelemetryState
    if ($Force) { $state.LastInventoryRefresh = [DateTime]::MinValue }
    if (-not $state.HasInitialSnapshot) {
        try {
            $perfFs = Get-AMRPerfNow
            $fastSnapshot = Get-AMROverviewFastSnapshot
            Add-AMRPerfSince 'overview.getFastSnapshotSync' $perfFs
            if ($fastSnapshot) {
                $state.DiskRows=@($fastSnapshot.DiskRows)
                $state.Processes=$fastSnapshot.Processes
                $state.ProcessThreads=$fastSnapshot.ProcessThreads
                $perfFs = Get-AMRPerfNow
                Apply-AMROverviewSnapshot -Snapshot $fastSnapshot
                Add-AMRPerfSince 'overview.applyInitialSnapshot' $perfFs
                $state.HasInitialSnapshot = $true
            }
        } catch {
            Write-AMRLog ('Overview local snapshot warning: ' + $_.Exception.Message) WARNING Overview
        }
    }
    if ($state.Current) {
        if ($Force) {
            $state.RefreshRequested = $true; $state.Current.Manual = $true
            if (-not $state.InventoryCurrent) { $state.LastInventoryRefresh=Get-Date; Start-AMROverviewInventoryRefresh }
            (C 'ovLastRefresh').Text = 'Refresh queued — current sample will finish first…'
            $liveStatus=C 'ovLiveRefreshStatus';if($liveStatus){$liveStatus.Text='Refresh queued — current sample will finish first…'}
            (C 'RefreshOverviewBtn').IsEnabled = $true
        }
        return
    }
    $button = C 'RefreshOverviewBtn'
    if ($button) { $button.IsEnabled = $true }; if($Force){(C 'ovLastRefresh').Text='Refreshing system readings…';$liveStatus=C 'ovLiveRefreshStatus';if($liveStatus){$liveStatus.Text='Collecting a fresh Windows sample…'}}
    $runspace = $state.FastRunspace; $powerShell = $null
    try {
        if(-not $runspace) {
            $perfRsOpen = Get-AMRPerfNow
            $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
            $runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
            $runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
            $runspace.Open()
            $state.FastRunspace = $runspace
            $state.FastRunspaceInitialized = $false
            Add-AMRPerfSince 'overview.fastRunspaceOpen' $perfRsOpen
        }
        if(-not $state.FastRunspaceInitialized) {
            $perfBoot = Get-AMRPerfNow
            $bootstrapPowerShell = [PowerShell]::Create(); $bootstrapPowerShell.Runspace = $runspace
            try {
                [void]$bootstrapPowerShell.AddScript($script:OverviewNativeBridgeBootstrap)
                $bootstrapResult=@($bootstrapPowerShell.Invoke())
                if($bootstrapPowerShell.Streams.Error.Count -gt 0) { throw ($bootstrapPowerShell.Streams.Error[0].ToString()) }
                if($bootstrapResult.Count -eq 0 -or -not $bootstrapResult[$bootstrapResult.Count-1].NativeBridgeReady) { throw 'Native sensor bridge self-test returned no valid result' }
                $state.FastRunspaceInitialized = $true
                Write-AMRLog ('LIVE_SENSOR [Engine] native bridge ready; GetSystemTimes counters={0}; physical RAM={1:N0} bytes.' -f $bootstrapResult[$bootstrapResult.Count-1].CpuCounterCount,$bootstrapResult[$bootstrapResult.Count-1].TotalPhysicalBytes) INFO Overview
            } finally { try { $bootstrapPowerShell.Dispose() } catch {}; Add-AMRPerfSince 'overview.nativeBridgeBootstrap' $perfBoot }
        }
        $powerShell = [PowerShell]::Create(); $powerShell.Runspace = $runspace
        $nowForProbe=Get-Date
        [void]$powerShell.AddScript($script:OverviewFastTelemetryWorker).AddArgument($false)
        $async = $powerShell.BeginInvoke()
        if(-not $state.InventoryCurrent -and (($nowForProbe - $state.LastInventoryRefresh).TotalSeconds -ge $state.InventoryIntervalSeconds)){ $state.LastInventoryRefresh=$nowForProbe; Start-AMROverviewInventoryRefresh }
        $state.Current = [pscustomobject]@{PowerShell=$powerShell;Runspace=$runspace;Async=$async;StartedAt=(Get-Date);Manual=[bool]$Force}
        if (-not $state.Timer) {
            # Capture the actual telemetry state before creating a closure. A script-scoped
            # lookup from inside GetNewClosure() can resolve against the closure module's
            # script scope (null), causing every DispatcherTimer tick to return immediately.
            $telemetryState = $state
            $state.Timer = New-Object System.Windows.Threading.DispatcherTimer
            $state.Timer.Interval = [TimeSpan]::FromMilliseconds(750)
            $state.Timer.Add_Tick(({
                $perfOvTick = Get-AMRPerfNow
                try {
                $activeState = $telemetryState
                if ($null -eq $activeState) { return }
                # Network polling is independent; adapter/provider delays never hold CPU/RAM values.
                if($activeState.NetworkCurrent){
                    $networkJob=$activeState.NetworkCurrent
                    if($networkJob.Async.IsCompleted){
                        try{
                            $networkResult=@($networkJob.PowerShell.EndInvoke($networkJob.Async))
                            if($networkResult.Count -gt 0 -and $null -ne $networkResult[$networkResult.Count-1]){
                                $networkSnapshot=$networkResult[$networkResult.Count-1]
                                foreach($propertyName in @('NetworkConnected','NetworkStatus','NetworkSensorError','NetRxBytes','NetTxBytes','NetworkAdapter','IPv4','Gateway','DNS','LinkMbps','InternetReachable')){$activeState.$propertyName=$networkSnapshot.$propertyName};$activeState.LastInternetReachable=$networkSnapshot.InternetReachable
                            }
                        }catch{$activeState.NetworkStatus='Sensor unavailable';$activeState.NetworkSensorError=$_.Exception.Message;$activeState.NetRxBytes=$null;$activeState.NetTxBytes=$null;$activeState.PreviousNetworkSample=$null;Write-AMRLog ('LIVE_SENSOR [Network] worker failed: '+$_.Exception.Message) WARNING Overview}
                        finally{try{$networkJob.PowerShell.Dispose()}catch{};$activeState.NetworkCurrent=$null;$activeState.NetworkLastSample=Get-Date}
                    }elseif(((Get-Date)-$networkJob.StartedAt).TotalSeconds -gt $activeState.NetworkTimeoutSeconds){
                        if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($networkJob.PowerShell,$networkJob.Runspace)}else{try{$networkJob.PowerShell.Stop()}catch{};try{$networkJob.PowerShell.Dispose()}catch{};try{$networkJob.Runspace.Close()}catch{};try{$networkJob.Runspace.Dispose()}catch{}}
                        [void]$script:OverviewSensorRunspaces.Remove('Network');$activeState.NetworkCurrent=$null;$activeState.NetworkLastSample=Get-Date;$activeState.NetworkStatus='Sensor unavailable';$activeState.NetworkSensorError='Network provider timed out; CPU/RAM/GPU continue independently';$activeState.NetRxBytes=$null;$activeState.NetTxBytes=$null;$activeState.PreviousNetworkSample=$null
                        Write-AMRLog 'LIVE_SENSOR [Network] provider timed out; only network sampling was cancelled.' WARNING Overview
                    }
                }
                if(-not $activeState.NetworkCurrent -and ((Get-Date)-$activeState.NetworkLastSample).TotalSeconds -ge $activeState.NetworkIntervalSeconds){$perfSt=Get-AMRPerfNow;Start-AMROverviewNetworkTelemetry;Add-AMRPerfSince 'overview.startNetwork' $perfSt}
                # Disk capacity is isolated from CPU/RAM; a slow removable or unhealthy drive cannot stall live CPU samples.
                if($activeState.DiskCurrent){
                    $diskJob=$activeState.DiskCurrent
                    if($diskJob.Async.IsCompleted){
                        try{$diskResult=@($diskJob.PowerShell.EndInvoke($diskJob.Async));if($diskResult.Count -gt 0 -and $diskResult[$diskResult.Count-1]){$diskSnapshot=$diskResult[$diskResult.Count-1];$activeState.DiskRows=@($diskSnapshot.DiskRows);$activeState.DiskSensorError=[string]$diskSnapshot.DiskSensorError}}
                        catch{$activeState.DiskSensorError=$_.Exception.Message;Write-AMRLog ('LIVE_SENSOR [Disk] worker failed: '+$_.Exception.Message) WARNING Overview}
                        finally{try{$diskJob.PowerShell.Dispose()}catch{};$activeState.DiskCurrent=$null;$activeState.DiskLastSample=Get-Date}
                    }elseif(((Get-Date)-$diskJob.StartedAt).TotalSeconds -gt $activeState.DiskTimeoutSeconds){
                        if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($diskJob.PowerShell,$diskJob.Runspace)}else{try{$diskJob.PowerShell.Stop()}catch{};try{$diskJob.PowerShell.Dispose()}catch{};try{$diskJob.Runspace.Close()}catch{};try{$diskJob.Runspace.Dispose()}catch{}}
                        [void]$script:OverviewSensorRunspaces.Remove('Disk');$activeState.DiskCurrent=$null;$activeState.DiskLastSample=Get-Date;$activeState.DiskSensorError='Disk provider timed out; CPU/RAM/network/GPU continue independently'
                        Write-AMRLog 'LIVE_SENSOR [Disk] provider timed out; only disk sampling was cancelled.' WARNING Overview
                    }
                }
                if(-not $activeState.DiskCurrent -and ((Get-Date)-$activeState.DiskLastSample).TotalSeconds -ge $activeState.DiskIntervalSeconds){$perfSt=Get-AMRPerfNow;Start-AMROverviewDiskTelemetry;Add-AMRPerfSince 'overview.startDisk' $perfSt}
                # Process/thread enumeration is isolated so access-denied processes cannot stop CPU/RAM polling.
                if($activeState.ActivityCurrent){
                    $activityJob=$activeState.ActivityCurrent
                    if($activityJob.Async.IsCompleted){
                        try{$activityResult=@($activityJob.PowerShell.EndInvoke($activityJob.Async));if($activityResult.Count -gt 0 -and $activityResult[$activityResult.Count-1]){$activitySnapshot=$activityResult[$activityResult.Count-1];$activeState.Processes=$activitySnapshot.Processes;$activeState.ProcessThreads=$activitySnapshot.ProcessThreads;$activeState.ProcessSensorError=[string]$activitySnapshot.ProcessSensorError}}
                        catch{$activeState.ProcessSensorError=$_.Exception.Message;Write-AMRLog ('LIVE_SENSOR [Activity] worker failed: '+$_.Exception.Message) WARNING Overview}
                        finally{try{$activityJob.PowerShell.Dispose()}catch{};$activeState.ActivityCurrent=$null;$activeState.ActivityLastSample=Get-Date}
                    }elseif(((Get-Date)-$activityJob.StartedAt).TotalSeconds -gt $activeState.ActivityTimeoutSeconds){
                        if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($activityJob.PowerShell,$activityJob.Runspace)}else{try{$activityJob.PowerShell.Stop()}catch{};try{$activityJob.PowerShell.Dispose()}catch{};try{$activityJob.Runspace.Close()}catch{};try{$activityJob.Runspace.Dispose()}catch{}}
                        [void]$script:OverviewSensorRunspaces.Remove('Activity');$activeState.ActivityCurrent=$null;$activeState.ActivityLastSample=Get-Date;$activeState.ProcessSensorError='Process/thread provider timed out; other sensors continue independently'
                        Write-AMRLog 'LIVE_SENSOR [Activity] provider timed out; only activity sampling was cancelled.' WARNING Overview
                    }
                }
                if(-not $activeState.ActivityCurrent -and ((Get-Date)-$activeState.ActivityLastSample).TotalSeconds -ge $activeState.ActivityIntervalSeconds){$perfSt=Get-AMRPerfNow;Start-AMROverviewActivityTelemetry;Add-AMRPerfSince 'overview.startActivity' $perfSt}
                # Poll GPU independently; a timeout affects only the GPU sensor.
                if($activeState.GpuCurrent){
                    $gpuJob=$activeState.GpuCurrent
                    if($gpuJob.Async.IsCompleted){
                        try{
                            $gpuResult=@($gpuJob.PowerShell.EndInvoke($gpuJob.Async))
                            if($gpuResult.Count -gt 0 -and $null -ne $gpuResult[$gpuResult.Count-1]){
                                $gpuSnapshot=$gpuResult[$gpuResult.Count-1]
                                $activeState.GPUPercent=$gpuSnapshot.GPUPercent
                                $activeState.GPUSensorError=[string]$gpuSnapshot.GPUSensorError
                                $activeState.GPUSensorSource=[string]$gpuSnapshot.GPUSensorSource
                                Set-AMRCircularGauge 'ovGpuGaugeArc' 'ovLiveGPUValue' $activeState.GPUPercent
                                $gpuDetail=C 'ovLiveGPUDetail'
                                if($gpuDetail){$gpuDetail.Text=if($null -ne $activeState.GPUPercent){('GPU engine utilization · {0}' -f $activeState.GPUSensorSource)}else{'GPU unavailable: '+$activeState.GPUSensorError}}
                                Write-AMRLog ('LIVE_SENSOR [GPU] source='+$activeState.GPUSensorSource+' value='+$(if($null -ne $activeState.GPUPercent){$activeState.GPUPercent}else{'Unavailable'})+' status='+$(if($null -ne $activeState.GPUPercent){'success'}else{'unavailable'})+' error='+$activeState.GPUSensorError) $(if($null -ne $activeState.GPUPercent){'INFO'}else{'WARNING'}) Overview
                            }
                        }catch{$activeState.GPUPercent=$null;$activeState.GPUSensorError=$_.Exception.Message;Write-AMRLog ('LIVE_SENSOR [GPU] worker failed: '+$_.Exception.Message) WARNING Overview}
                        finally{try{$gpuJob.PowerShell.Dispose()}catch{};$activeState.GpuCurrent=$null;$activeState.GpuLastSample=Get-Date}
                    }elseif(((Get-Date)-$gpuJob.StartedAt).TotalSeconds -gt $activeState.GpuTimeoutSeconds){
                        if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($gpuJob.PowerShell,$gpuJob.Runspace)}else{try{$gpuJob.PowerShell.Stop()}catch{};try{$gpuJob.PowerShell.Dispose()}catch{};try{$gpuJob.Runspace.Close()}catch{};try{$gpuJob.Runspace.Dispose()}catch{}}
                        [void]$script:OverviewSensorRunspaces.Remove('Gpu');$activeState.GpuCurrent=$null;$activeState.GpuLastSample=Get-Date;$activeState.GPUPercent=$null;$activeState.GPUSensorError='GPU provider timed out; other sensors continue normally'
                        $gpuDetail=C 'ovLiveGPUDetail';if($gpuDetail){$gpuDetail.Text='GPU provider timed out · CPU/RAM/network remain independent'}
                        Write-AMRLog 'LIVE_SENSOR [GPU] provider exceeded its 12-second timeout; only GPU sampling was cancelled.' WARNING Overview
                    }
                }
                if(-not $activeState.GpuCurrent -and ((Get-Date)-$activeState.GpuLastSample).TotalSeconds -ge $activeState.GpuIntervalSeconds){$perfSt=Get-AMRPerfNow;Start-AMROverviewGpuTelemetry;Add-AMRPerfSince 'overview.startGpu' $perfSt}
                $pulseControl=C 'ovLiveRefreshStatus'
                if($pulseControl){
                    $pulseTime=(Get-Date).ToString('HH:mm:ss')
                    $sampleAge='waiting for sample'
                    if($activeState.LastSuccessfulSample -ne [DateTime]::MinValue){$sampleAge=('data {0:HH:mm:ss}' -f $activeState.LastSuccessfulSample)}
                    $pulseControl.Text=('Live monitoring · {0}' -f $sampleAge)
                }
                if($activeState.InventoryCurrent){
                    $inventoryJob=$activeState.InventoryCurrent
                    if($inventoryJob.Async.IsCompleted){
                        try{$inventoryResult=@($inventoryJob.PowerShell.EndInvoke($inventoryJob.Async));if($inventoryResult.Count -gt 0 -and $inventoryResult[$inventoryResult.Count-1]){Apply-AMROverviewInventorySnapshot -Snapshot $inventoryResult[$inventoryResult.Count-1]}else{Write-AMRLog 'LIVE_SENSOR [Inventory] worker returned no snapshot.' WARNING Overview}}
                        catch{Write-AMRLog ('LIVE_SENSOR [Inventory] failed: '+$_.Exception.Message) WARNING Overview}
                        finally{try{$inventoryJob.PowerShell.Dispose()}catch{};try{$inventoryJob.Runspace.Close()}catch{};try{$inventoryJob.Runspace.Dispose()}catch{};$activeState.InventoryCurrent=$null}
                    }elseif(((Get-Date)-$inventoryJob.StartedAt).TotalSeconds -gt 45){
                        if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($inventoryJob.PowerShell,$inventoryJob.Runspace)}else{try{$inventoryJob.PowerShell.Stop()}catch{};try{$inventoryJob.PowerShell.Dispose()}catch{};try{$inventoryJob.Runspace.Close()}catch{};try{$inventoryJob.Runspace.Dispose()}catch{}};$activeState.InventoryCurrent=$null
                        Write-AMRLog 'LIVE_SENSOR [Inventory] timed out; live telemetry remains independent.' WARNING Overview
                    }
                }
                if (-not $activeState.InventoryCurrent -and ((Get-Date)-$activeState.LastInventoryRefresh).TotalSeconds -ge $activeState.InventoryIntervalSeconds){$activeState.LastInventoryRefresh=Get-Date;Start-AMROverviewInventoryRefresh}
                if ($activeState.Current -and -not $activeState.Current.Async.IsCompleted -and ((Get-Date) - $activeState.Current.StartedAt).TotalSeconds -gt 32) {
                    $stalledJob = $activeState.Current
                    $activeState.Current = $null
                    if('AMRRunspaceCleanupV1' -as [type]){[AMRRunspaceCleanupV1]::Queue($stalledJob.PowerShell,$stalledJob.Runspace)}else{try{$stalledJob.PowerShell.Stop()}catch{};try{$stalledJob.PowerShell.Dispose()}catch{};try{$stalledJob.Runspace.Close()}catch{};try{$stalledJob.Runspace.Dispose()}catch{}}
                    $activeState.FastRunspace=$null; $activeState.FastRunspaceInitialized=$false
                    $activeState.FastWorkerFailures++
                    $activeState.LastFastWorkerError='Fast telemetry worker timed out'
                    Set-AMROverviewUnavailable 'Windows sensor query timed out'; $status = C 'ovLastRefresh'; if ($status) { $status.Text = 'Sensor query timed out. Press Refresh to retry.' }
                    $button = C 'RefreshOverviewBtn'; if ($button) { $button.IsEnabled = $true }
                    Write-AMRLog 'Overview telemetry exceeded its 32-second safety timeout; the worker was cancelled.' WARNING Overview
                    $activeState.NextRefresh = if($activeState.RefreshRequested){[DateTime]::MinValue}else{(Get-Date).AddSeconds(4)}
                    if($activeState.RefreshRequested){$activeState.RefreshRequested=$false}
                    return
                }
                if ($activeState.Current -and $activeState.Current.Async.IsCompleted) {
                    $job = $activeState.Current
                    try {
                        $result = @($job.PowerShell.EndInvoke($job.Async))
                        if ($job.PowerShell.Streams.Error.Count -gt 0) { foreach ($workerError in $job.PowerShell.Streams.Error) { Write-AMRLog ('Overview telemetry provider warning: ' + $workerError.ToString()) WARNING Overview } }
                        if ($result.Count -gt 0 -and $null -ne $result[$result.Count-1]) {
                            $liveSnapshot=$result[$result.Count-1]
                            $liveSnapshot.GPUPercent=$activeState.GPUPercent
                            $liveSnapshot.GPUSensorError=$activeState.GPUSensorError
                            $liveSnapshot.GPUSensorSource=$activeState.GPUSensorSource
                            $liveSnapshot.NetworkConnected=$activeState.NetworkConnected
                            $liveSnapshot.NetworkStatus=$activeState.NetworkStatus
                            $liveSnapshot.NetworkSensorError=$activeState.NetworkSensorError
                            $liveSnapshot.NetRxBytes=$activeState.NetRxBytes
                            $liveSnapshot.NetTxBytes=$activeState.NetTxBytes
                            $liveSnapshot.NetworkAdapter=$activeState.NetworkAdapter
                            $liveSnapshot.IPv4=$activeState.IPv4
                            $liveSnapshot.Gateway=$activeState.Gateway
                            $liveSnapshot.DNS=$activeState.DNS
                            $liveSnapshot.LinkMbps=$activeState.LinkMbps
                            $liveSnapshot.DiskRows=@($activeState.DiskRows)
                            $liveSnapshot.DiskSensorError=[string]$activeState.DiskSensorError
                            $liveSnapshot.Processes=$activeState.Processes
                            $liveSnapshot.ProcessThreads=$activeState.ProcessThreads
                            $liveSnapshot.ProcessSensorError=[string]$activeState.ProcessSensorError
                            $perfApply = Get-AMRPerfNow
                            Apply-AMROverviewSnapshot -Snapshot $liveSnapshot -FastOnly
                            Add-AMRPerfSince 'overview.applyLiveSnapshot' $perfApply
                            $activeState.LastSuccessfulSample=Get-Date
                        }
                        else {
                            $activeState.FastWorkerFailures++
                            $activeState.LastFastWorkerError='Fast worker returned no telemetry snapshot'
                            Set-AMROverviewUnavailable 'No telemetry data returned'
                            (C 'ovLastRefresh').Text = 'Update failed: no telemetry data returned'
                            Write-AMRLog 'LIVE_SENSOR [Engine] fast worker returned no telemetry snapshot.' WARNING Overview
                        }
                    } catch {
                        $activeState.FastWorkerFailures++
                        $activeState.LastFastWorkerError=$_.Exception.Message
                        Set-AMROverviewUnavailable ('Telemetry error: ' + $_.Exception.Message)
                        (C 'ovLastRefresh').Text = 'Update failed: ' + $_.Exception.Message
                        Write-AMRLog ('LIVE_SENSOR [Engine] fast telemetry refresh failed: ' + $_.Exception.ToString()) ERROR Overview
                    } finally {
                        # Dispose only the completed pipeline. Keep its runspace alive so
                        # AMRLiveSensorNativeV3 remains loaded for the next 500 ms sample.
                        try { $job.PowerShell.Dispose() } catch {}
                        $activeState.Current = $null
                        $activeState.NextRefresh = $job.StartedAt.AddSeconds($activeState.IntervalSeconds)
                        if ($activeState.RefreshRequested) { $activeState.RefreshRequested = $false; $activeState.NextRefresh = [DateTime]::MinValue; $status = C 'ovLastRefresh'; if($status){$status.Text='Running queued refresh…'} }
                        $button = C 'RefreshOverviewBtn'; if ($button) { $button.IsEnabled = $true }
                    }
                    return
                }
                if (-not $activeState.Current -and (Get-Date) -ge $activeState.NextRefresh) { Start-AMROverviewTelemetry }
                } finally { Add-AMRPerfSince 'overview.telemetryTick' $perfOvTick }
            }).GetNewClosure())
            $state.Timer.Start()
        }
    } catch {
        if ($powerShell) { try { $powerShell.Dispose() } catch {} }
        if ($runspace) { try { $runspace.Close() } catch {}; try { $runspace.Dispose() } catch {} }
        $state.FastRunspace=$null; $state.FastRunspaceInitialized=$false
        $state.FastWorkerFailures++
        $state.LastFastWorkerError=$_.Exception.ToString()
        $state.Current = $null
        if ($button) { $button.IsEnabled = $true }
        (C 'ovLastRefresh').Text = 'Unable to start telemetry: ' + $_.Exception.Message
        Write-AMRLog ('Could not start Overview telemetry worker: ' + $_.Exception.ToString()) ERROR Overview
    }
}

function Update-AMROverviewData { Start-AMROverviewTelemetry -Force }

function Refresh-AMROverview {
    param([switch]$DeferRestorePoint)
    $wg = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($wg) { (C 'WingetHeader').Text = 'WINGET ENGINE READY' } else { (C 'WingetHeader').Text = 'WINGET NOT FOUND' }
    Start-AMROverviewTelemetry -Force
    if ($DeferRestorePoint) {
        Add-AMRDeferredStartupAction -Name 'DriverRestorePointStatus' -Action { Update-AMRDriverRestorePointStatus }
    } else {
        Update-AMRDriverRestorePointStatus
    }
}

# Refresh-button visuals and click animation: intentionally limited to the three requested buttons.
function Set-AMRRefreshButtonVisual {
    param([Parameter(Mandatory=$true)]$Button, [Parameter(Mandatory=$true)][string]$Label)
    $contentPanel = [System.Windows.Controls.StackPanel]::new()
    $contentPanel.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $contentPanel.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
    $contentPanel.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

    $refreshGlyph = [System.Windows.Controls.TextBlock]::new()
    $refreshGlyph.Text = '↻'
    $refreshGlyph.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $refreshGlyph.Margin = [System.Windows.Thickness]::new(0,0,5,0)
    $refreshGlyph.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
    $refreshGlyph.RenderTransform = [System.Windows.Media.RotateTransform]::new(0)

    $labelBlock = [System.Windows.Controls.TextBlock]::new()
    $labelBlock.Text = $Label
    $labelBlock.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

    [void]$contentPanel.Children.Add($refreshGlyph)
    [void]$contentPanel.Children.Add($labelBlock)
    $Button.Content = $contentPanel
    $Button.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)

    # Give the whole button its own transform so its body visibly moves,
    # without changing its layout slot, dimensions, or surrounding controls.
    $buttonTransforms = [System.Windows.Media.TransformGroup]::new()
    [void]$buttonTransforms.Children.Add([System.Windows.Media.TranslateTransform]::new(0,0))
    [void]$buttonTransforms.Children.Add([System.Windows.Media.RotateTransform]::new(0))
    [void]$buttonTransforms.Children.Add([System.Windows.Media.ScaleTransform]::new(1,1))
    $Button.RenderTransform = $buttonTransforms
}

function Start-AMRRefreshButtonAnimation {
    param([Parameter(Mandatory=$true)]$Button)
    if (-not $Button) { return }
    $glyph = $null
    if ($Button.Content -is [System.Windows.Controls.StackPanel] -and $Button.Content.Children.Count -gt 0) {
        $glyph = $Button.Content.Children[0]
    } elseif ($Button.Content -is [System.Windows.Controls.ContentPresenter]) {
        $glyph = $Button.Content
    }
    if (-not $glyph -or -not ($glyph.RenderTransform -is [System.Windows.Media.RotateTransform])) { return }

    # Startup-only premium refresh: a smooth double-turn, breathing glass edge and a restrained lift.
    # Other refresh buttons retain their existing animation unchanged.
    if ([string]$Button.Name -eq 'AMRStartupRefreshBtn') {
        $spin = [System.Windows.Media.Animation.DoubleAnimation]::new(0,720,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(880)))
        $spin.EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
        $spin.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
        $glyph.RenderTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$spin)

        $edge = $Button.BorderBrush
        if ($edge -is [System.Windows.Media.SolidColorBrush]) {
            $pulse = [System.Windows.Media.Animation.ColorAnimationUsingKeyFrames]::new()
            [void]$pulse.KeyFrames.Add([System.Windows.Media.Animation.LinearColorKeyFrame]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#E6C98F'),[System.Windows.Media.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(0))))
            [void]$pulse.KeyFrames.Add([System.Windows.Media.Animation.EasingColorKeyFrame]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#FFF0C8'),[System.Windows.Media.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(260))))
            [void]$pulse.KeyFrames.Add([System.Windows.Media.Animation.EasingColorKeyFrame]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#A98A5C'),[System.Windows.Media.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(880))))
            $pulse.KeyFrames[1].EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
            $pulse.KeyFrames[2].EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
            $edge.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$pulse)
        }

        if ($Button.RenderTransform -is [System.Windows.Media.TransformGroup] -and $Button.RenderTransform.Children.Count -ge 3) {
            $lift = $Button.RenderTransform.Children[0]
            $scale = $Button.RenderTransform.Children[2]
            $liftY = [System.Windows.Media.Animation.DoubleAnimation]::new(0,-2.2,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(250)))
            $liftY.AutoReverse = $true
            $liftY.EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
            $liftY.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $lift.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$liftY)
            $scalePulse = [System.Windows.Media.Animation.DoubleAnimation]::new(1,1.035,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(260)))
            $scalePulse.AutoReverse = $true
            $scalePulse.EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
            $scalePulse.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$scalePulse)
            $scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$scalePulse)
        }
        return
    }

    # Keep the existing refresh-glyph spin for the other refresh buttons.
    $spin = [System.Windows.Media.Animation.DoubleAnimation]::new(0,360,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(620)))
    $spin.EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
    $spin.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
    $glyph.RenderTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$spin)

    # Animate the complete button body with a more visible, restrained wobble.
    if (-not ($Button.RenderTransform -is [System.Windows.Media.TransformGroup]) -or $Button.RenderTransform.Children.Count -lt 2) {
        $buttonTransforms = [System.Windows.Media.TransformGroup]::new()
        [void]$buttonTransforms.Children.Add([System.Windows.Media.TranslateTransform]::new(0,0))
        [void]$buttonTransforms.Children.Add([System.Windows.Media.RotateTransform]::new(0))
        [void]$buttonTransforms.Children.Add([System.Windows.Media.ScaleTransform]::new(1,1))
        $Button.RenderTransform = $buttonTransforms
    }
    if ($Button.RenderTransform.Children.Count -lt 3) {
        [void]$Button.RenderTransform.Children.Add([System.Windows.Media.ScaleTransform]::new(1,1))
    }
    $move = $Button.RenderTransform.Children[0]
    $tilt = $Button.RenderTransform.Children[1]

    $xShake = [System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames]::new()
    [void]$xShake.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(0,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(0))))
    [void]$xShake.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(-3,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(65))))
    [void]$xShake.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(3,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(130))))
    [void]$xShake.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(-2,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(195))))
    [void]$xShake.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(0,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(270))))

    $yBounce = [System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames]::new()
    [void]$yBounce.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(0,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(0))))
    [void]$yBounce.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(-1.5,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(65))))
    [void]$yBounce.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(1.5,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(130))))
    [void]$yBounce.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(-0.75,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(195))))
    [void]$yBounce.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(0,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(270))))

    $tiltWobble = [System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames]::new()
    [void]$tiltWobble.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(0,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(0))))
    [void]$tiltWobble.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(-1.4,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(65))))
    [void]$tiltWobble.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(1.4,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(130))))
    [void]$tiltWobble.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(-0.6,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(195))))
    [void]$tiltWobble.KeyFrames.Add([System.Windows.Media.Animation.LinearDoubleKeyFrame]::new(0,[System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds(270))))

    $move.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$xShake)
    $move.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$yBounce)
    $tilt.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$tiltWobble)
}

# Immediate tactile press/release feedback for the same three Refresh buttons only.
function Set-AMRRefreshButtonPressedState {
    param([Parameter(Mandatory=$true)]$Button, [Parameter(Mandatory=$true)][bool]$Pressed)
    if (-not $Button -or -not ($Button.RenderTransform -is [System.Windows.Media.TransformGroup])) { return }
    if ($Button.RenderTransform.Children.Count -lt 3) { return }
    $scale = $Button.RenderTransform.Children[2]
    if (-not ($scale -is [System.Windows.Media.ScaleTransform])) { return }

    $target = if ($Pressed) { 0.945 } else { 1.0 }
    $duration = if ($Pressed) { 75 } else { 115 }
    $currentX = [double]$scale.ScaleX
    $currentY = [double]$scale.ScaleY
    $pressEase = [System.Windows.Media.Animation.CubicEase]::new()
    $pressEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

    $scaleXAnimation = [System.Windows.Media.Animation.DoubleAnimation]::new($currentX,$target,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($duration)))
    $scaleYAnimation = [System.Windows.Media.Animation.DoubleAnimation]::new($currentY,$target,[System.Windows.Duration]::new([TimeSpan]::FromMilliseconds($duration)))
    $scaleXAnimation.EasingFunction = $pressEase
    $scaleYAnimation.EasingFunction = $pressEase
    $scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$scaleXAnimation,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
    $scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$scaleYAnimation,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
}

function Enable-AMRRefreshButtonPressFeedback {
    param([Parameter(Mandatory=$true)]$Button)
    $Button.Add_PreviewMouseLeftButtonDown({ Set-AMRRefreshButtonPressedState -Button $Button -Pressed $true }.GetNewClosure())
    $Button.Add_PreviewMouseLeftButtonUp({ Set-AMRRefreshButtonPressedState -Button $Button -Pressed $false }.GetNewClosure())
    $Button.Add_LostMouseCapture({ Set-AMRRefreshButtonPressedState -Button $Button -Pressed $false }.GetNewClosure())
}

