# --- AMR DRIVER RESTORE POINT MANAGEMENT ---
function Get-AMRComputerRestorePoints {
    param([ValidateRange(1,60)][int]$TimeoutSec = 5)
    $command = Get-Command -Name Get-CimInstance -ErrorAction SilentlyContinue
    if (-not $command) { throw 'Get-CimInstance is unavailable in this worker session.' }
    try {
        # SystemRestore is exposed by Windows in root/default. Use CIM directly so
        # the query timeout is bounded and the worker can report the real provider error.
        $points = @(Get-CimInstance -ClassName 'SystemRestore' -Namespace 'root/default' -OperationTimeoutSec $TimeoutSec -ErrorAction Stop)
    } catch {
        throw ('Windows System Restore inventory query failed (timeout {0}s): {1}' -f $TimeoutSec,$_.Exception.Message)
    }
    return @($points | Select-Object SequenceNumber,Description,CreationTime,RestorePointType,EventType)
}

function ConvertFrom-AMRRestorePointTime {
    param([object]$Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [datetime]) { return [datetime]$Value }
    $raw = [string]$Value
    if ($raw -match '^(\d{14})\.(\d{6})([+-])(\d{3})$') {
        # DMTF datetime. Parse by hand so the worker needs no extra assembly: the text is local
        # time plus its UTC offset in minutes.
        try {
            $local = [datetime]::ParseExact($Matches[1],'yyyyMMddHHmmss',[System.Globalization.CultureInfo]::InvariantCulture)
            $offsetMinutes = [int]$Matches[4]; if ($Matches[3] -eq '-') { $offsetMinutes = -$offsetMinutes }
            $utc = [datetime]::SpecifyKind($local.AddMinutes(-$offsetMinutes),[System.DateTimeKind]::Utc)
            return $utc.ToLocalTime()
        } catch {}
        try { return [System.Management.ManagementDateTimeConverter]::ToDateTime($raw) } catch { return $null }
    }
    try { return [datetime]$Value } catch { return $null }
}

function New-AMRDriverSafetyRestorePoint {
    [CmdletBinding()]
    param([string]$Reason = 'Before driver changes')

    # Confirm elevation inside the retained background worker.
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw ('The Restore Point worker is not elevated. Worker identity: {0}. Relaunch AMR with Run as administrator.' -f $identity.Name)
    }
    if ([string]::IsNullOrWhiteSpace([string]$env:SystemDrive) -or $env:SystemDrive -notmatch '^[A-Za-z]:$') { throw 'Windows did not report a valid system drive.' }
    if ([string]::IsNullOrWhiteSpace([string]$script:DriverRestorePointStateFile)) { throw 'The isolated AMR Driver Backup receipt path is not configured.' }
    foreach ($name in @('Enable-ComputerRestore','Get-CimInstance','Get-WmiObject')) {
        if (-not (Get-Command -Name $name -ErrorAction SilentlyContinue)) { throw ('Required Windows command is unavailable in the worker: ' + $name) }
    }

    $metadataRoot = Split-Path -Parent $script:DriverRestorePointStateFile
    try {
        if (-not (Test-Path -LiteralPath $metadataRoot -PathType Container)) { New-Item -ItemType Directory -Path $metadataRoot -Force -ErrorAction Stop | Out-Null }
        $metadataRoot = [IO.Path]::GetFullPath($metadataRoot)
        $probe = Join-Path $metadataRoot ('.write-test-' + [guid]::NewGuid().ToString('N'))
        [IO.File]::WriteAllText($probe,'AMR')
        Remove-Item -LiteralPath $probe -Force -ErrorAction Stop
    } catch { throw ('AMR Driver Backup isolated storage is not writable: {0}' -f $_.Exception.Message) }

    $systemDriveRoot = [string]($env:SystemDrive + '\')
    if (Get-Command -Name Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue) {
        Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage ('Confirming elevated token and System Protection on {0}' -f $systemDriveRoot)
    }
    # Native snapshots remain owned by Windows in System Volume Information.
    # AMR stores only the exact Windows identity receipt in its private folder.
    try { Enable-ComputerRestore -Drive $systemDriveRoot -ErrorAction Stop }
    catch { throw ('Windows could not enable System Protection on {0}: {1}' -f $systemDriveRoot,$_.Exception.Message) }

    $baseline = @(Get-AMRComputerRestorePoints -TimeoutSec 12)
    $baselineSequences = @{}
    foreach ($oldPoint in $baseline) {
        $oldSeq = 0L
        if ([long]::TryParse([string]$oldPoint.SequenceNumber,[ref]$oldSeq) -and $oldSeq -gt 0) { $baselineSequences[[string]$oldSeq] = $true }
    }

    $requestStarted = Get-Date
    $stamp = Get-Date
    $sessionTag = ([string]$script:AMRSessionId -replace '[^A-Fa-f0-9]','')
    if ($sessionTag.Length -gt 8) { $sessionTag = $sessionTag.Substring(0,8) }
    if ([string]::IsNullOrWhiteSpace($sessionTag)) { $sessionTag = [guid]::NewGuid().ToString('N').Substring(0,8) }
    $description = 'Driver Safety - AMR-' + $sessionTag + ' - ' + $stamp.ToString('yyyyMMdd-HHmmss')

    if (Get-Command -Name Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue) {
        Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Requesting a Windows restore point through the native SystemRestore provider'
    }

    # Use the documented SystemRestore.CreateRestorePoint WMI method rather than
    # Checkpoint-Computer. Windows may return S_OK while applying its default
    # 24-hour frequency rule and skipping the new snapshot. Therefore success is
    # determined ONLY by a new sequence in the Windows inventory, never by S_OK.
    $nativeReturnCode = $null
    try {
        $systemRestoreClass = [wmiclass]'\\.\root\default:SystemRestore'
        $nativeResult = $systemRestoreClass.CreateRestorePoint($description,10,100)
        if ($null -eq $nativeResult -or $null -eq $nativeResult.ReturnValue) {
            throw 'SystemRestore.CreateRestorePoint returned no status code.'
        }
        $nativeReturnCode = [uint32]$nativeResult.ReturnValue
        if ($nativeReturnCode -ne 0) {
            throw ('SystemRestore.CreateRestorePoint returned Windows status 0x{0:X8}.' -f $nativeReturnCode)
        }
    } catch {
        throw ('Windows System Restore rejected the native CreateRestorePoint request: {0}' -f $_.Exception.Message)
    }

    if (Get-Command -Name Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue) {
        Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Verifying whether Windows created a new checkpoint or applied its frequency limit'
    }

    $verifyDeadline = (Get-Date).AddSeconds(30)
    $selected = $null
    $isReusedExisting = $false
    $lastInventoryError = $null
    $lastCandidateSummary = @()
    $latestInventory = @()
    do {
        $remaining = [int][math]::Ceiling(($verifyDeadline - (Get-Date)).TotalSeconds)
        if ($remaining -le 0) { break }
        $queryTimeout = [int][math]::Max(1,[math]::Min(8,$remaining))
        try {
            $latestInventory = @(Get-AMRComputerRestorePoints -TimeoutSec $queryTimeout)
            $lastInventoryError = $null
            $candidates = @()
            foreach ($candidate in $latestInventory) {
                $seq = 0L
                if (-not [long]::TryParse([string]$candidate.SequenceNumber,[ref]$seq) -or $seq -le 0) { continue }
                if ($baselineSequences.ContainsKey([string]$seq)) { continue }
                $createdAt = ConvertFrom-AMRRestorePointTime -Value $candidate.CreationTime
                if ($null -eq $createdAt) { continue }
                if ($createdAt -lt $requestStarted.AddMinutes(-2) -or $createdAt -gt (Get-Date).AddMinutes(2)) { continue }
                if ([int]$candidate.RestorePointType -ne 10) { continue }
                $candidates += [pscustomobject]@{
                    Point=$candidate; Sequence=$seq; CreatedAt=$createdAt
                    ExactDescription=([string]$candidate.Description -ceq $description)
                }
            }
            $lastCandidateSummary = @($candidates | ForEach-Object {
                [pscustomobject]@{Sequence=$_.Sequence;Description=[string]$_.Point.Description;CreationTime=$_.CreatedAt.ToString('o');Type=[int]$_.Point.RestorePointType;ExactDescription=$_.ExactDescription}
            })
            $exact = @($candidates | Where-Object { $_.ExactDescription })
            if ($exact.Count -eq 1) { $selected = $exact[0]; break }
            if ($exact.Count -eq 0 -and $candidates.Count -eq 1) { $selected = $candidates[0]; break }
            if ($candidates.Count -gt 1) {
                throw ('More than one new Windows driver checkpoint matched this request; refusing to guess. Candidates: ' + ($lastCandidateSummary | ConvertTo-Json -Compress -Depth 4))
            }
        } catch {
            if ($_.Exception.Message -like 'More than one new Windows driver checkpoint*') { throw }
            $lastInventoryError = [string]$_.Exception.Message
        }
        $remaining = [int][math]::Ceiling(($verifyDeadline - (Get-Date)).TotalSeconds)
        if ($remaining -gt 0) { Start-Sleep -Seconds ([int][math]::Min(2,$remaining)) }
    } while ((Get-Date) -lt $verifyDeadline)

    if ($null -eq $selected) {
        if ($lastInventoryError) {
            throw ('Windows accepted the native request, but its restore-point inventory could not be verified: {0}. No restore target was recorded.' -f $lastInventoryError)
        }
        # Windows documents that CreateRestorePoint may return S_OK while skipping
        # creation when a point already exists within the default 24-hour window.
        # In that case AMR may safely pin the latest existing checkpoint as a
        # clearly labelled REUSED target; it must never call it newly created.
        $reuseCandidates = @()
        foreach ($existing in $latestInventory) {
            $seq = 0L
            if (-not [long]::TryParse([string]$existing.SequenceNumber,[ref]$seq) -or $seq -le 0) { continue }
            if (-not $baselineSequences.ContainsKey([string]$seq)) { continue }
            $existingTime = ConvertFrom-AMRRestorePointTime -Value $existing.CreationTime
            if ($null -eq $existingTime) { continue }
            if ($existingTime -gt $requestStarted -or $existingTime -lt $requestStarted.AddHours(-24)) { continue }
            $reuseCandidates += [pscustomobject]@{Point=$existing;Sequence=$seq;CreatedAt=$existingTime;ExactDescription=$false}
        }
        $reuseCandidates = @($reuseCandidates | Sort-Object -Property CreatedAt,Sequence -Descending)
        if ($reuseCandidates.Count -gt 0) {
            $selected = $reuseCandidates[0]
            $isReusedExisting = $true
        } else {
            $details = if ($lastCandidateSummary.Count) { ' Candidate details: ' + ($lastCandidateSummary | ConvertTo-Json -Compress -Depth 4) } else { ' Windows did not publish a new driver-install checkpoint, and no existing checkpoint from the last 24 hours is available to reuse.' }
            throw ('Windows did not create a new restore point (the native API can report success when its 24-hour frequency rule skips creation).{0} No restore target was recorded.' -f $details)
        }
    }

    $point = $selected.Point
    $sequence = [long]$selected.Sequence
    $createdAt = [datetime]$selected.CreatedAt
    $actualDescription = [string]$point.Description
    $state = [pscustomobject]@{
        SchemaVersion = 4
        Product = 'AMR Windows Utility - Driver Backup'
        SessionId = [string]$script:AMRSessionId
        SequenceNumber = $sequence
        Description = $actualDescription
        RequestedDescription = $description
        RequestedDescriptionMatched = [bool]$selected.ExactDescription
        IsReusedExisting = [bool]$isReusedExisting
        PointOrigin = $(if ($isReusedExisting) { 'ExistingWindowsCheckpoint-Reused' } else { 'CreatedByAMR-NativeSystemRestore' })
        NativeCreateReturnCode = $nativeReturnCode
        CreationTime = $createdAt.ToString('o')
        RestorePointType = [int]$point.RestorePointType
        EventType = [int]$point.EventType
        WindowsDrive = $systemDriveRoot
        StorageOwner = 'Windows System Restore (System Volume Information)'
        AMRMetadataRoot = $metadataRoot
        Reason = [string]$Reason
        VerificationMethod = $(if ($isReusedExisting) { 'Exact existing Windows sequence + exact description + creation within preceding 24 hours; reused because Windows frequency rule skipped new creation' } else { 'New sequence absent from pre-request inventory + request-time window + DEVICE_DRIVER_INSTALL type; exact description preferred' })
        VerifiedAt = (Get-Date).ToString('o')
        RecordedAt = (Get-Date).ToString('o')
    }

    $statePath = [IO.Path]::GetFullPath([string]$script:DriverRestorePointStateFile)
    $temporaryStatePath = $statePath + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
    try {
        $state | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $temporaryStatePath -Encoding UTF8 -ErrorAction Stop
        $staged = Get-Content -LiteralPath $temporaryStatePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ([long]$staged.SequenceNumber -ne $sequence -or [string]$staged.Description -cne $actualDescription -or [string]$staged.CreationTime -cne $createdAt.ToString('o') -or [bool]$staged.IsReusedExisting -ne [bool]$isReusedExisting) {
            throw 'Staged AMR receipt failed its checkpoint identity check.'
        }
        Move-Item -LiteralPath $temporaryStatePath -Destination $statePath -Force -ErrorAction Stop
    } catch {
        try { Remove-Item -LiteralPath $temporaryStatePath -Force -ErrorAction SilentlyContinue } catch {}
        throw ('Windows checkpoint #{0} was verified, but its isolated AMR receipt could not be committed: {1}' -f $sequence,$_.Exception.Message)
    }
    return $state
}

function Get-AMRRecordedDriverRestorePoint {
    [CmdletBinding()]
    param([ValidateRange(1,60)][int]$InventoryTimeoutSec = 5)

    $statePath = [string]$script:DriverRestorePointStateFile
    if ([string]::IsNullOrWhiteSpace($statePath) -or -not (Test-Path -LiteralPath $statePath -PathType Leaf)) {
        throw 'No AMR Driver Backup receipt exists. Create and verify a Driver Safety Point first.'
    }

    try {
        $state = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
    } catch {
        throw ('The AMR Driver Backup receipt is unreadable or damaged. Create a new verified restore point. Details: {0}' -f $_.Exception.Message)
    }

    $sequence = 0L
    if (-not [long]::TryParse([string]$state.SequenceNumber,[ref]$sequence) -or $sequence -le 0) {
        throw 'The saved AMR restore-point sequence is invalid. Create a new Driver Safety Point.'
    }
    $description = [string]$state.Description
    $isReusedReceipt = ([bool]$state.IsReusedExisting -and [int]$state.SchemaVersion -ge 4 -and [string]$state.PointOrigin -ceq 'ExistingWindowsCheckpoint-Reused')
    if ([string]::IsNullOrWhiteSpace($description)) {
        throw 'The saved receipt has no Windows restore-point description. Smart Restore is blocked.'
    }
    if (-not $isReusedReceipt -and $description -notmatch '^(Driver Safety - AMR-[A-Fa-f0-9]{8} - \d{8}-\d{6}|(AMR )?Driver Safety - )') {
        throw 'The saved receipt does not identify an AMR-created or explicitly reused Windows checkpoint. Smart Restore is blocked.'
    }
    if ($sequence -gt [int]::MaxValue) {
        throw 'The saved restore-point sequence is outside the range supported by Windows Restore-Computer. Smart Restore is blocked.'
    }

    try {
        $matches = @(Get-AMRComputerRestorePoints -TimeoutSec $InventoryTimeoutSec | Where-Object {
            [long]$_.SequenceNumber -eq $sequence -and [string]$_.Description -ceq $description
        })
    } catch {
        throw ('Windows System Restore inventory could not be verified within the configured timeout. Smart Restore is blocked; no alternate point will be selected. Details: {0}' -f $_.Exception.Message)
    }

    if ($matches.Count -ne 1) {
        throw 'The exact saved Driver Safety Point is missing or ambiguous in Windows System Restore. Windows may have removed it during storage cleanup. Smart Restore will not substitute another point.'
    }
    return [pscustomobject]@{ State=$state; Point=$matches[0] }
}

function Update-AMRDriverRestorePointStatusCore {
    try {
        $record = Get-AMRRecordedDriverRestorePoint
        $when = try { ([datetime]$record.State.CreationTime).ToString('dd MMM yyyy  ·  hh:mm tt') } catch { [string]$record.State.CreationTime }
        $statusPrefix = if ([bool]$record.State.IsReusedExisting) { 'Verified existing Windows checkpoint (reused)' } else { 'Verified AMR-created checkpoint' }; (C 'DriverRestorePointStatus').Text = ('{0}  #{1}  ·  {2}  ·  {3}' -f $statusPrefix,$record.State.SequenceNumber,$record.State.Description,$when)
        (C 'DriverSmartRestoreBtn').IsEnabled = $true
    } catch {
        $savedState = $null
        try {
            if (Test-Path -LiteralPath $script:DriverRestorePointStateFile -PathType Leaf) {
                $savedState = Get-Content -LiteralPath $script:DriverRestorePointStateFile -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            }
        } catch {}
        if ($savedState -and -not [string]::IsNullOrWhiteSpace([string]$savedState.SequenceNumber)) {
            $reason = [string]$_.Exception.Message
            (C 'DriverRestorePointStatus').Text = ('Saved checkpoint #{0} · inventory check unavailable: {1}' -f $savedState.SequenceNumber,$reason)
        } else {
            (C 'DriverRestorePointStatus').Text = 'No verified driver restore point is recorded. Use Smart Create whenever you want to save a recovery point.'
        }
        (C 'DriverSmartRestoreBtn').IsEnabled = $true
    }
}

# A13c: measured wrapper. The status query reads the Windows restore-point inventory on the UI thread
# (up to 5 s timeout), so its real duration is logged to find out whether it causes UI stalls.
function Update-AMRDriverRestorePointStatus {
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    try { Update-AMRDriverRestorePointStatusCore }
    finally {
        $watch.Stop()
        try {
            $ms = [long]$watch.ElapsedMilliseconds
            Write-AMRDriverDiagnostic -Severity $(if ($ms -ge 250) { 'WARNING' } else { 'TRACE' }) -Operation 'RestorePoint' -Stage 'StatusQueryTiming' -Message ('Restore-point status query ran on the UI thread for {0} ms.' -f $ms) -Source 'Update-AMRDriverRestorePointStatus' -DurationMs $ms
        } catch {}
    }
}

function Invoke-AMRDriverSmartRestore {
    if($script:DriverManagedJob -or $script:DriverActionJob -or $script:DriverScanJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive -or $script:DriverOperationState.State -eq 'Running'){Show-AMRMessageGlass 'System Restore cannot be started while another driver operation is active. Wait for it to finish first.' 'Driver Operation Busy' OK Warning | Out-Null;return}
    try {
        $record = Get-AMRRecordedDriverRestorePoint -InventoryTimeoutSec 12
        $sequence = [long]$record.Point.SequenceNumber
        if ($sequence -le 0 -or $sequence -gt [int]::MaxValue) {
            throw 'Windows returned a restore-point sequence that cannot be passed safely to Restore-Computer. No restore was started.'
        }
        $description = [string]$record.Point.Description
        if ([string]$record.Point.Description -cne [string]$record.State.Description) {
            throw 'The Windows inventory identity no longer matches the saved AMR receipt. No restore was started.'
        }
        $created = try { ([datetime]$record.State.CreationTime).ToString('dd MMM yyyy  ·  hh:mm tt') } catch { [string]$record.State.CreationTime }
        $restoreOriginNote = if ([bool]$record.State.IsReusedExisting) { "Windows did not create a new point because a recent checkpoint already exists. AMR is reusing this existing Windows checkpoint; it was NOT created by AMR.`n`n" } else { "This is the new Windows checkpoint created and verified by AMR.`n`n" }; $message = "${restoreOriginNote}The exact Windows restore point was found and verified:`n`n$description`nSequence: $sequence`nCreated: $created`n`nWindows will start System Restore using this exact sequence number. This can close applications and restart Windows. Save your work before continuing. Other restore points will not be deleted.`n`nStart restoring now?"
        if ((Show-AMRMessageGlass $message 'Confirm Smart Restore' YesNo Warning) -ne 'Yes') { return }
        $restoreCommand = Get-Command -Name Restore-Computer -ErrorAction SilentlyContinue
        if (-not $restoreCommand -or -not $restoreCommand.Parameters.ContainsKey('RestorePoint')) {
            Show-AMRMessageGlass 'This Windows PowerShell installation does not expose Restore-Computer with its exact RestorePoint parameter. The target point was verified, but AMR cannot safely invoke an exact-point restore. No restore point was changed.' 'Smart Restore Unavailable' OK Warning | Out-Null
            return
        }
        Show-AMRMessageGlass 'The exact restore-point sequence is being handed to Windows. Windows System Restore will restart the computer; the restore completes during startup. Do not power off the computer during the process.' 'Starting Smart Restore' OK Warning | Out-Null
        Write-AMRLog (("Smart Restore requested for {0} Windows restore point #{1} ({2})." -f $(if ([bool]$record.State.IsReusedExisting) { 'reused existing' } else { 'AMR-created' }),$sequence,$description)) WARNING Overview
        Restore-Computer -RestorePoint ([int]$sequence) -Confirm:$false -ErrorAction Stop
    } catch {
        $detail = [string]$_.Exception.Message
        if ($detail -like 'No verified driver restore point*') {
            Show-AMRMessageGlass 'There is no verified Driver Safety Point yet. Create a restore point first; Smart Restore will then target that exact checkpoint.' 'Smart Restore Not Ready' OK Information | Out-Null
        } else {
            Show-AMRMessageGlass ('Smart Restore could not continue: ' + $detail + "`n`nNo alternative restore point will be selected automatically.") 'Smart Restore Error' OK Error | Out-Null
        }
        Write-AMRLog ('Smart Restore validation/invocation failed: ' + $detail) ERROR Overview
    }
}

function Complete-AMRDriverRestorePointWorker {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][System.Management.Automation.Job]$Job)

    # Restore Point owns a private job reference captured by its button handler.
    # Never depend on the shared DriverManagedJob slot: unrelated dispatcher
    # callbacks may clear that slot while this specific job is still alive.
    $job = $Job
    if ($job.State -notin @('Completed','Failed','Stopped')) { return $null }

    $result = $null
    $failure = $null
    $errorRecord = $null
    try {
        if ($job.State -eq 'Completed') {
            $received = @(Receive-Job -Job $job -ErrorAction Stop)
            if ($received.Count -gt 0) { $result = $received[-1] }
            if ($null -eq $result) { $failure = 'The Restore Point worker completed without returning a result object.' }
        } else {
            foreach ($child in @($job.ChildJobs)) {
                if ($child.Error -and $child.Error.Count -gt 0) { $errorRecord = $child.Error[-1] }
                if ($child.JobStateInfo -and $child.JobStateInfo.Reason) { $failure = [string]$child.JobStateInfo.Reason.Message }
            }
            if (-not $failure -and $errorRecord) { $failure = [string]$errorRecord.Exception.Message }
            if (-not $failure) { $failure = ('Restore Point worker ended in state: ' + [string]$job.State) }
        }
    } catch {
        $errorRecord = $_
        $failure = [string]$_.Exception.Message
    }

    $operationId = if ($job.PSObject.Properties['AMROperationId']) { [string]$job.AMROperationId } else { '' }
    $durationMs = $null
    if ($script:DriverOperationState -and $script:DriverOperationState.StartedAt) {
        try { $durationMs = [long]((Get-Date) - [datetime]$script:DriverOperationState.StartedAt).TotalMilliseconds } catch {}
    }

    # Clean only resources still owned by this exact job. Do not reset another
    # operation that may have started after this job's shared slot was cleared.
    $isCurrentJob = $false
    try { $isCurrentJob = [object]::ReferenceEquals($script:DriverManagedJob,$job) } catch {}
    if (-not $isCurrentJob -and $script:DriverManagedJob -and $operationId) {
        # A13e: same operation by id counts as the shared job, so the shared slot can never stay stuck after a restore point.
        try { if ($script:DriverManagedJob.PSObject.Properties['AMROperationId'] -and [string]$script:DriverManagedJob.AMROperationId -eq $operationId) { $isCurrentJob = $true } } catch {}
    }
    $ownsRestoreOperation = ($script:DriverOperationState -and [string]$script:DriverOperationState.Name -eq 'RestorePoint' -and $job.PSObject.Properties['AMRGeneration'] -and [int]$job.AMRGeneration -eq [int]$script:DriverOperationState.Generation)
    $isActiveRestoreJob = $false
    try { $isActiveRestoreJob = [object]::ReferenceEquals($script:DriverRestorePointActiveJob,$job) } catch {}
    try { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {}
    if ($isCurrentJob -or $ownsRestoreOperation -or $isActiveRestoreJob) {
        if ($isCurrentJob) { $script:DriverManagedJob = $null }
        if ($isCurrentJob -and $script:DriverManagedProgressTimer) { try { $script:DriverManagedProgressTimer.Stop() } catch {}; $script:DriverManagedProgressTimer = $null }
        if ($isCurrentJob -and $script:DriverManagedProgressFile) {
            try { Remove-Item -LiteralPath $script:DriverManagedProgressFile -Force -ErrorAction SilentlyContinue; Remove-Item -LiteralPath ($script:DriverManagedProgressFile + '.tmp') -Force -ErrorAction SilentlyContinue } catch {}
        }
        if ($isCurrentJob) { $script:DriverManagedProgressFile = $null; $script:DriverManagedWorkerId = $null; $script:DriverManagedWatchdog = $null }
        $script:DriverRestorePointActiveJob = $null
        if ($script:DriverOperationState -and [string]$script:DriverOperationState.Name -eq 'RestorePoint') {
            $script:DriverOperationState = [pscustomobject]@{ Name='Idle'; State='Idle'; StartedAt=$null; Generation=[int]$script:DriverOperationState.Generation; CanCancel=$false; Status='Ready'; PartialShown=$false }
        }
        try { Release-AMRDriverOperationLock } catch {}
        try { (C 'DriverOperationProgress').IsIndeterminate=$false; (C 'DriverOperationProgress').Visibility='Collapsed' } catch {}
        try { Update-AMRDriverActionButtons } catch {}
    }

    if ($failure) {
        Write-AMRDriverDiagnostic -Severity ERROR -Operation 'RestorePoint' -Stage 'WorkerResultCollectionFailed' -Message 'The dedicated Restore Point worker did not provide a usable result.' -OperationId $operationId -Source 'Complete-AMRDriverRestorePointWorker' -DurationMs $durationMs -Result 'Failed' -ErrorRecord $(if ($errorRecord) { $errorRecord } else { $failure })
        throw $failure
    }
    Write-AMRDriverDiagnostic -Severity SUCCESS -Operation 'RestorePoint' -Stage 'WorkerResultCollected' -Message 'The dedicated Restore Point worker result was collected from its retained job reference.' -OperationId $operationId -Source 'Complete-AMRDriverRestorePointWorker' -DurationMs $durationMs -Result 'Completed'
    return $result
}

(C 'DriverCreateRestorePointBtn').Add_Click({
    $button = C 'DriverCreateRestorePointBtn'
    if ($script:DriverManagedJob -or $script:DriverActionJob -or $script:DriverScanJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive -or $script:DriverOperationState.State -eq 'Running') { Show-AMRMessageGlass 'Wait for the current driver operation to finish before creating a restore point.' 'Driver Operation Busy' OK Information | Out-Null; return }
    if (-not (Test-AMRAdmin)) { Show-AMRMessageGlass 'Creating and verifying a Windows restore point requires Administrator privileges. Close the utility and launch it again as Administrator.' 'Administrator Required' OK Warning | Out-Null; return }
    if ((-not $script:DriverRestorePromptApproved) -and ((Show-AMRMessageGlass 'Create a Windows System Restore point now? AMR will enable System Protection on the Windows drive if needed, request a checkpoint, and verify the exact Windows result. If Windows skips a new point due to its frequency rule, AMR may record a clearly labelled recent existing checkpoint instead. This does not install or change any driver. Windows does not expose a native percentage for this operation, so AMR displays activity rather than a fabricated percentage. You can stop AMR waiting, but Windows may still finish a request it has already accepted.' 'Create Driver Safety Point' YesNo Warning) -ne 'Yes')) { return }
    $progressPanel=C 'DriverRestoreProgressPanel';$progressBar=C 'DriverRestorePointProgressBar';$progressText=C 'DriverRestorePointProgressText';$elapsedText=C 'DriverRestorePointElapsed';$percentText=C 'DriverRestorePointPercent';$estimateText=C 'DriverRestorePointEstimate';$cancelButton=C 'DriverRestorePointCancelBtn'
    $script:DriverRestorePointStartedAt=Get-Date;$script:DriverRestorePointLastFailure=$null;$script:DriverRestorePointCancelled=$false
    if($progressPanel){$progressPanel.Visibility='Visible'}
    if($progressBar){$progressBar.IsIndeterminate=$true;$progressBar.Value=0}
    if($percentText){$percentText.Text='Running'}
    if($progressText){$progressText.Text='Starting Windows System Restore…'}
    if($elapsedText){$elapsedText.Text='Elapsed 00:00'}
    if($estimateText){$estimateText.Text='Waiting for Windows'}
    if($cancelButton){$cancelButton.Visibility='Visible';$cancelButton.IsEnabled=$true}
    $button.IsEnabled=$false;$button.Content='Creating checkpoint…'
    try {
        $restoreJob=Start-AMRDriverManagedWorker -Operation RestorePoint -Device ([pscustomobject]@{DeviceName='Driver Backup';DeviceId='DriverBackup'}) -Candidate 'Manually created from Driver Backup'
        $script:DriverRestorePointActiveJob = $restoreJob
        $restoreProgressPath = [string]$script:DriverManagedProgressFile
        if (-not $restoreJob -or -not ($restoreJob -is [System.Management.Automation.Job])) {
            throw 'Start-AMRDriverManagedWorker did not return a valid PowerShell Job object for Restore Point.'
        }
        $poll=New-Object System.Windows.Threading.DispatcherTimer
        $poll.Interval=[TimeSpan]::FromMilliseconds(500)
        $script:DriverRestorePointPollTimer=$poll
        $poll.Add_Tick(({
            if ($script:DriverRestorePointCancelled) { try { $poll.Stop() } catch {}; return }
            # This closure-held job is the sole authority for this Restore Point UI.
            # A null shared slot is not a failure while the captured job still exists.
            $jobState = [string]$restoreJob.State
            if ($script:DriverRestorePointStartedAt) {
                $elapsed=[timespan]((Get-Date)-[datetime]$script:DriverRestorePointStartedAt)
                if($elapsedText){$elapsedText.Text=('Elapsed '+$elapsed.ToString('mm\:ss'))}
            }
            if ($restoreProgressPath -and (Test-Path -LiteralPath $restoreProgressPath -PathType Leaf)) {
                try {
                    $liveProgress=Get-Content -LiteralPath $restoreProgressPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                    if($liveProgress.Stage -and $progressText){$progressText.Text=[string]$liveProgress.Stage}
                } catch {}
            }
            if ($jobState -notin @('Completed','Failed','Stopped')) {
                if($progressBar){$progressBar.IsIndeterminate=$true}
                if($percentText){$percentText.Text='Running'}
                if($estimateText){$estimateText.Text='Waiting for Windows'}
                return
            }

            $poll.Stop()
            try {
                $created=Complete-AMRDriverRestorePointWorker -Job $restoreJob
                if(-not $created -or -not $created.Success){throw $(if($created -and $created.Failure){[string]$created.Failure}else{'Restore point creation did not return a verified result.'})}
                $state=$created.RestoreState
                Update-AMRDriverRestorePointStatus
                (C 'DriverSmartRestoreBtn').IsEnabled=$true
                if($progressBar){$progressBar.IsIndeterminate=$false;$progressBar.Value=100}
                if($percentText){$percentText.Text='Verified'}
                if($progressText){$progressText.Text='Success — Windows created the restore point and the exact sequence number was verified.'}
                if($estimateText){$estimateText.Text='Completed and verified'}
                Write-AMRLog ("Created AMR driver restore point #{0}." -f $state.SequenceNumber) SUCCESS Overview
                try {
                    $whenText = try { ([datetime]$state.CreationTime).ToString('dd MMM yyyy  ·  hh:mm tt') } catch { [string]$state.CreationTime }
                    $headline = if ([bool]$state.IsReusedExisting) { "Windows already had a recent restore point (it allows only one new point per 24 hours), so AMR is using that existing one as your recovery target." } else { "Windows created a new restore point and AMR verified it." }
                    Show-AMRMessageGlass ("$headline`n`nNumber: #$($state.SequenceNumber)`nName: $($state.Description)`nTime: $whenText`n`nIf a driver causes a problem, use Smart Restore in Backups > Driver Backup to return to this exact point.") 'Restore Point Ready' OK Information | Out-Null
                } catch {}
            } catch {
                if($progressBar){$progressBar.IsIndeterminate=$false;$progressBar.Value=0}
                if($percentText){$percentText.Text='Not verified'}
                if($progressText){$progressText.Text=('Failed — '+[string]$_.Exception.Message)}
                if($estimateText){$estimateText.Text='Operation ended · not verified'}
                Update-AMRDriverRestorePointStatus
                Show-AMRMessageGlass ('Could not create and verify a Windows restore point: '+[string]$_.Exception.Message) 'Restore Point Failed' OK Error | Out-Null
                Write-AMRLog ('AMR driver restore point creation failed: '+[string]$_.Exception.Message) ERROR Overview
            } finally {
                $script:DriverRestorePointStartedAt=$null
                $button.Content='＋  Smart Create';$button.IsEnabled=$true
                if($cancelButton){$cancelButton.Visibility='Collapsed';$cancelButton.IsEnabled=$false}
            }
        }).GetNewClosure())
        $script:DriverManagedTimer=$poll;$poll.Start()
    } catch {
        $button.Content='＋  Smart Create';$button.IsEnabled=$true
        if($progressBar){$progressBar.IsIndeterminate=$false;$progressBar.Value=0}
        if($percentText){$percentText.Text='—'}
        if($progressText){$progressText.Text=('Could not start — '+[string]$_.Exception.Message)}
        if($estimateText){$estimateText.Text='Not started'}
        if($cancelButton){$cancelButton.Visibility='Collapsed';$cancelButton.IsEnabled=$false}
        $script:DriverRestorePointStartedAt=$null
        Show-AMRMessageGlass ('Could not start restore point creation: '+[string]$_.Exception.Message) 'Restore Point Failed' OK Error | Out-Null
    }
})

(C 'DriverRestorePointCancelBtn').Add_Click({
    $restoreCancelJob=$script:DriverRestorePointActiveJob
    if(-not $restoreCancelJob -or [string]$script:DriverOperationState.Name -ne 'RestorePoint'){return}
    if((Show-AMRMessageGlass 'Stop the AMR background worker now? This ends AMR waiting and verification. If Windows has already accepted the native restore-point request, Windows may still complete it in the background; AMR will not mark it as verified unless it can confirm the exact checkpoint.' 'Cancel Restore Point Operation' YesNo Warning) -ne 'Yes'){return}
    $script:DriverRestorePointCancelled=$true
    # A13c: stop this operation's own poll timer first, so a stopped job can never be reported as a failure after Cancel.
    if ($script:DriverRestorePointPollTimer) { try { $script:DriverRestorePointPollTimer.Stop() } catch {}; $script:DriverRestorePointPollTimer=$null }
    try { if ([object]::ReferenceEquals($script:DriverManagedJob,$restoreCancelJob)) { Stop-AMRDriverManagedWorker -Force } else { Stop-Job -Job $restoreCancelJob -ErrorAction SilentlyContinue } } catch {}
    try { Remove-Job -Job $restoreCancelJob -Force -ErrorAction SilentlyContinue } catch {}
    $script:DriverRestorePointActiveJob=$null
    if ($script:DriverOperationState -and [string]$script:DriverOperationState.Name -eq 'RestorePoint') {
        $script:DriverOperationState = [pscustomobject]@{ Name='Idle'; State='Idle'; StartedAt=$null; Generation=[int]$script:DriverOperationState.Generation; CanCancel=$false; Status='Ready'; PartialShown=$false }
        try { Release-AMRDriverOperationLock } catch {}
        try { Update-AMRDriverActionButtons } catch {}
    }
    $button=C 'DriverCreateRestorePointBtn';if($button){$button.Content='＋  Smart Create';$button.IsEnabled=$true}
    $progressBar=C 'DriverRestorePointProgressBar';if($progressBar){$progressBar.IsIndeterminate=$false;$progressBar.Value=0}
    $percentText=C 'DriverRestorePointPercent';if($percentText){$percentText.Text='Cancelled'}
    $progressText=C 'DriverRestorePointProgressText';if($progressText){$progressText.Text='AMR worker cancelled. Windows may still finish a request already accepted; check System Protection before retrying.'}
    $elapsedText=C 'DriverRestorePointElapsed';if($elapsedText){$elapsedText.Text='Stopped by user'}
    $estimateText=C 'DriverRestorePointEstimate';if($estimateText){$estimateText.Text='Not verified'}
    $cancelButton=C 'DriverRestorePointCancelBtn';if($cancelButton){$cancelButton.Visibility='Collapsed';$cancelButton.IsEnabled=$false}
    $script:DriverRestorePointStartedAt=$null
    Update-AMRDriverRestorePointStatus
})
# --- Recovery Center: floating restore-point window (view only; never starts a restore) ---
$script:AMRRecoveryPointWindow = $null
$script:AMRRestoreAssist = $null

function Get-AMRRecoveryPointInfo {
    $info = [ordered]@{ Found=$false; Name=''; Sequence=''; When=''; Origin=''; Problem='' }
    try {
        $record = Get-AMRRecordedDriverRestorePoint -InventoryTimeoutSec 8
        $info.Found = $true
        $info.Name = [string]$record.Point.Description
        $info.Sequence = [string]$record.Point.SequenceNumber
        $created = $null
        try { $created = [datetime]$record.State.CreationTime } catch {}
        if ($created -is [datetime]) { $info.When = ($created.ToString('d',[System.Globalization.CultureInfo]::CurrentCulture) + '  ' + $created.ToString('t',[System.Globalization.CultureInfo]::CurrentCulture)) }
        $info.Origin = $(if ([bool]$record.State.IsReusedExisting) { 'EXISTING WINDOWS POINT (REUSED BY AMR)' } else { 'AMR DRIVER SAFETY POINT' })
        return [pscustomobject]$info
    } catch { $info.Problem = [string]$_.Exception.Message }
    # Receipt missing or not verifiable: show the newest AMR-named Windows point, for display only.
    try {
        $named = @(Get-AMRComputerRestorePoints -TimeoutSec 8 | Where-Object { [string]$_.Description -match '^Driver Safety - AMR-[A-Fa-f0-9]{8} - \d{8}-\d{6}$' })
        if ($named.Count -gt 0) {
            $newest = @($named | Sort-Object { [long]$_.SequenceNumber } -Descending)[0]
            $info.Found = $true
            $info.Name = [string]$newest.Description
            $info.Sequence = [string]$newest.SequenceNumber
            $when = ConvertFrom-AMRRestorePointTime $newest.CreationTime
            if ($when -is [datetime]) { $info.When = ($when.ToString('d',[System.Globalization.CultureInfo]::CurrentCulture) + '  ' + $when.ToString('t',[System.Globalization.CultureInfo]::CurrentCulture)) }
            $info.Origin = 'NEWEST AMR POINT FOUND IN WINDOWS'
        }
    } catch { if ([string]::IsNullOrWhiteSpace($info.Problem)) { $info.Problem = [string]$_.Exception.Message } }
    return [pscustomobject]$info
}

# Background helper for the Windows System Restore window. Navigation only: it can select the
# second restore option, tick "show more points" and select ONE matching list row. It never
# invokes any button (no Next, no Finish) and never starts a restore. Any failure ends it quietly.
$script:AMRRestoreAssistScript = @'
param([string]$Description,[int]$TimeoutSec,$State)
try {
    Add-Type -AssemblyName UIAutomationClient
    Add-Type -AssemblyName UIAutomationTypes
} catch { $State.Stage = 'unavailable'; return }
$AE = [System.Windows.Automation.AutomationElement]
$CT = [System.Windows.Automation.ControlType]
$TS = [System.Windows.Automation.TreeScope]
$deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSec)
$seenWindow = $false; $radioDone = $false; $nextDone = $false; $radioAt = [DateTime]::UtcNow; $nextAt = [DateTime]::UtcNow; $moreDone = $false; $zeroScans = 0; $introDone = $false; $introAttempts = 0; $introPolls = 0; $introAt = [DateTime]::UtcNow
while ([DateTime]::UtcNow -lt $deadline -and -not $State.Cancel) {
    try {
        # Several top-level windows can belong to rstrui.exe (a hidden or empty one may come first): use the one that has the most controls.
        $win = $null
        $winBest = -1
        foreach ($proc in @(Get-Process -Name rstrui -ErrorAction SilentlyContinue)) {
            $cond = New-Object System.Windows.Automation.PropertyCondition($AE::ProcessIdProperty,[int]$proc.Id)
            foreach ($cand in $AE::RootElement.FindAll($TS::Children,$cond)) {
                $candCount = 0
                try { $candCount = $cand.FindAll($TS::Descendants,[System.Windows.Automation.Condition]::TrueCondition).Count } catch {}
                if ($candCount -gt $winBest) { $win = $cand; $winBest = $candCount }
            }
        }
        if (-not $win) { if ($seenWindow) { break } else { Start-Sleep -Milliseconds 400; continue } }
        $seenWindow = $true
        $listCond = New-Object System.Windows.Automation.PropertyCondition($AE::ControlTypeProperty,$CT::ListItem)
        $items = $win.FindAll($TS::Descendants,$listCond)
        if ($items.Count -gt 0) {
            # No AMR point name (none was created): Windows is now on its list page; nothing is marked and nothing more is pressed.
            if ([string]::IsNullOrWhiteSpace($Description)) { $State.Stage = 'list-no-point'; break }
            $rowMatches = New-Object System.Collections.ArrayList
            foreach ($item in $items) {
                $texts = New-Object System.Collections.ArrayList
                [void]$texts.Add([string]$item.Current.Name)
                foreach ($part in $item.FindAll($TS::Descendants,[System.Windows.Automation.Condition]::TrueCondition)) { [void]$texts.Add([string]$part.Current.Name) }
                foreach ($text in $texts) {
                    if (-not [string]::IsNullOrWhiteSpace($text) -and $text.IndexOf($Description,[System.StringComparison]::OrdinalIgnoreCase) -ge 0) { [void]$rowMatches.Add($item); break }
                }
            }
            if ($rowMatches.Count -eq 1) {
                $pattern = $null
                if ($rowMatches[0].TryGetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern,[ref]$pattern)) {
                    $pattern.Select()
                    Start-Sleep -Milliseconds 150
                    if ($pattern.Current.IsSelected) { $State.Stage = 'row-selected'; break }
                }
                $State.Stage = 'row-not-found'; break
            }
            if ($rowMatches.Count -gt 1) { $State.Stage = 'row-not-found'; break }
            # No match yet: older points are hidden until the single "show more" check box is ticked.
            if (-not $moreDone) {
                $moreDone = $true
                $boxCond = New-Object System.Windows.Automation.PropertyCondition($AE::ControlTypeProperty,$CT::CheckBox)
                $boxes = $win.FindAll($TS::Descendants,$boxCond)
                if ($boxes.Count -eq 1) {
                    $toggle = $null
                    if ($boxes[0].TryGetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern,[ref]$toggle)) {
                        if ($toggle.Current.ToggleState -eq [System.Windows.Automation.ToggleState]::Off) { $toggle.Toggle() }
                    }
                }
                Start-Sleep -Milliseconds 600; continue
            }
            $zeroScans++
            if ($zeroScans -ge 3) { $State.Stage = 'row-not-found'; break }
        } elseif (-not $radioDone) {
            $radioCond = New-Object System.Windows.Automation.PropertyCondition($AE::ControlTypeProperty,$CT::RadioButton)
            $radios = $win.FindAll($TS::Descendants,$radioCond)
            if ($radios.Count -eq 2) {
                $radioDone = $true
                $pattern = $null
                if ($radios[1].TryGetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern,[ref]$pattern)) {
                    if (-not $pattern.Current.IsSelected) { $pattern.Select() }
                    $State.Stage = 'radio-selected'
                    $radioAt = [DateTime]::UtcNow
                } else { $State.Detail = 'second radio option has no selection pattern' }
            } elseif ($radios.Count -eq 0) {
                # Intro page of the wizard (no radio options, Next and Cancel only; shown when Windows has no recommended point). Press Next once.
                # Only a button that is really named Next (or has the wizard Next id) is pressed, and never while a Finish button is enabled
                # (that is the confirmation page). No default-button guess and no Enter key here.
                $introPolls++
                # Try on polls 3, 5, 7 ... up to 6 times (about 6 s), so a slow-loading page is still found. Every try logs what the window contains.
                if (-not $introDone -and $introPolls -ge 3 -and (($introPolls - 3) % 2) -eq 0) {
                    $introAttempts++
                    $pickI = New-Object System.Collections.ArrayList
                    $dumpI = New-Object System.Collections.ArrayList
                    $finishSeen = $false
                    $elCount = 0
                    foreach ($elI in $win.FindAll($TS::Descendants,[System.Windows.Automation.Condition]::TrueCondition)) {
                        try {
                            $curI = $elI.Current
                            $elCount++
                            $typeI = ([string]$curI.ControlType.ProgrammaticName) -replace '^ControlType\.',''
                            $nameI = [string]$curI.Name
                            $idI = [string]$curI.AutomationId
                            $enI = [bool]$curI.IsEnabled
                            if ($dumpI.Count -lt 60) { [void]$dumpI.Add(('{0}|{1}|id={2}|cls={3}|en={4}' -f $typeI,$nameI.Substring(0,[Math]::Min(40,$nameI.Length)),$idI,[string]$curI.ClassName,$enI)) }
                            if ($enI) {
                                if ($nameI -match '(?i)^\s*&?finish') { $finishSeen = $true }
                                if ($nameI -match '(?i)^\s*&?next\b' -or ($typeI -eq 'Button' -and $idI -eq '12324')) { [void]$pickI.Add($elI) }
                            }
                        } catch {}
                    }
                    $winI = ''
                    try { $winI = ('window name="{0}" class={1} pid={2} rect={3}' -f [string]$win.Current.Name,[string]$win.Current.ClassName,[int]$win.Current.ProcessId,[string]$win.Current.BoundingRectangle) } catch {}
                    $State.Detail = ('intro page try {0}; {1}; controls={2}; Next candidates={3}; Finish enabled={4}; all: {5}' -f $introAttempts,$winI,$elCount,$pickI.Count,$finishSeen,($dumpI -join ' ; '))
                    $pressedI = $false
                    if (-not $finishSeen -and $pickI.Count -eq 1) {
                        $invokeI = $null
                        if ($pickI[0].TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern,[ref]$invokeI)) {
                            try { $invokeI.Invoke(); $pressedI = $true } catch {}
                        }
                    }
                    if ($pressedI) { $introDone = $true; $State.Method = 'intro-next'; $State.Stage = 'next-pressed'; $nextAt = [DateTime]::UtcNow }
                    elseif ($introAttempts -ge 6) { $introDone = $true; $State.Stage = 'next-manual' }
                } elseif ($introDone -and $State.Stage -eq 'next-pressed' -and ([DateTime]::UtcNow - $nextAt).TotalSeconds -ge 8) {
                    $State.Stage = 'next-manual'
                }
            } elseif ($radios.Count -gt 0) { $State.Detail = 'page 1 shows ' + $radios.Count + ' radio option(s), expected 2' }
        } elseif (-not $nextDone -and ([DateTime]::UtcNow - $radioAt).TotalMilliseconds -ge 700) {
            # Page 1 only (two radio options, no list yet, second option selected): press the wizard's default button, which is Next here.
            # Finish is never pressed: this branch needs the two-radio page, and the confirm page has no radios.
            $nextDone = $true
            $radioCond2 = New-Object System.Windows.Automation.PropertyCondition($AE::ControlTypeProperty,$CT::RadioButton)
            $radios2 = $win.FindAll($TS::Descendants,$radioCond2)
            $secondSelected = $false
            if ($radios2.Count -eq 2) {
                $selPattern = $null
                if ($radios2[1].TryGetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern,[ref]$selPattern)) { $secondSelected = [bool]$selPattern.Current.IsSelected }
            }
            if ($secondSelected) {
                $btnCond = New-Object System.Windows.Automation.PropertyCondition($AE::ControlTypeProperty,$CT::Button)
                $enabledBtns = New-Object System.Collections.ArrayList
                $btnDesc = New-Object System.Collections.ArrayList
                foreach ($btn in $win.FindAll($TS::Descendants,$btnCond)) {
                    if (-not $btn.Current.IsEnabled) { continue }
                    $isDefault = $false
                    $legacy = $null
                    if ($btn.TryGetCurrentPattern([System.Windows.Automation.LegacyIAccessiblePattern]::Pattern,[ref]$legacy)) {
                        if (([int]$legacy.Current.State -band 0x00400000) -ne 0) { $isDefault = $true }
                    }
                    [void]$enabledBtns.Add([pscustomobject]@{ El = $btn; Id = [string]$btn.Current.AutomationId; Name = [string]$btn.Current.Name; Default = $isDefault })
                    [void]$btnDesc.Add(('{0}|id={1}|default={2}' -f $btn.Current.Name,$btn.Current.AutomationId,$isDefault))
                }
                $State.Detail = 'enabled buttons on page 1: ' + ($btnDesc -join '; ')
                # Fallbacks in order, page 1 only. Finish is never chosen: this page has Next and Cancel only.
                $pick = $null; $method = ''
                $found = @($enabledBtns | Where-Object { $_.Default })
                if ($found.Count -eq 1) { $pick = $found[0]; $method = 'default-flag' }
                if (-not $pick) { $found = @($enabledBtns | Where-Object { $_.Id -eq '12324' }); if ($found.Count -eq 1) { $pick = $found[0]; $method = 'wizard-id-12324' } }
                if (-not $pick) { $found = @($enabledBtns | Where-Object { $_.Name -match '^\s*&?Next' }); if ($found.Count -eq 1) { $pick = $found[0]; $method = 'name-next' } }
                if (-not $pick) { $found = @($enabledBtns | Where-Object { $_.Id -ne '2' -and $_.Name -notmatch '(?i)cancel|help|back|close|finish' }); if ($found.Count -eq 1) { $pick = $found[0]; $method = 'not-cancel' } }
                $pressed = $false
                if ($pick) {
                    $invoke = $null
                    if ($pick.El.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern,[ref]$invoke)) {
                        try { $invoke.Invoke(); $pressed = $true } catch {}
                    }
                }
                if (-not $pressed) {
                    # Last resort: Enter presses the wizard's default button. Only sent when the Windows System Restore window really has the focus.
                    try {
                        Add-Type -AssemblyName System.Windows.Forms
                        $win.SetFocus()
                        Start-Sleep -Milliseconds 250
                        $focused = $AE::FocusedElement
                        if ($focused -and [int]$focused.Current.ProcessId -eq [int]$win.Current.ProcessId) {
                            [System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
                            $pressed = $true; $method = 'enter-key'
                        }
                    } catch {}
                }
                if ($pressed) { $State.Method = $method; $State.Stage = 'next-pressed'; $nextAt = [DateTime]::UtcNow }
                else { $State.Stage = 'next-manual' }
            }
        } elseif ($nextDone -and $State.Stage -eq 'next-pressed' -and ([DateTime]::UtcNow - $nextAt).TotalSeconds -ge 8) {
            $State.Stage = 'next-manual'
        }
    } catch {}
    Start-Sleep -Milliseconds 500
}
if ($State.Stage -eq 'row-selected') {
    # The AMR floating window closes itself now; hand the focus back to the Windows System Restore window so nothing covers it.
    try {
        $closeDeadline = [DateTime]::UtcNow.AddSeconds(4)
        while ([DateTime]::UtcNow -lt $closeDeadline -and -not $State.Closed) { Start-Sleep -Milliseconds 100 }
        Start-Sleep -Milliseconds 150
        foreach ($proc in @(Get-Process -Name rstrui -ErrorAction SilentlyContinue)) {
            $cond = New-Object System.Windows.Automation.PropertyCondition($AE::ProcessIdProperty,[int]$proc.Id)
            $win = $AE::RootElement.FindFirst($TS::Children,$cond)
            if ($win) { $win.SetFocus(); break }
        }
    } catch {}
}
if ($State.Stage -eq 'radio-selected' -or $State.Stage -eq 'next-pressed' -or $State.Stage -eq 'next-manual' -or $State.Stage -eq '') { $State.Stage = 'ended-' + $State.Stage }
'@

function Start-AMRRestoreWindowAssist {
    param([string]$Description)
    if ($null -eq $Description) { $Description = '' }
    if ($script:AMRRestoreAssist -and $script:AMRRestoreAssist.State) { try { $script:AMRRestoreAssist.State.Cancel = $true } catch {} }
    $assistState = [hashtable]::Synchronized(@{ Stage = ''; Cancel = $false; Closed = $false; Detail = ''; Method = '' })
    $assistShell = [powershell]::Create()
    [void]$assistShell.AddScript($script:AMRRestoreAssistScript).AddArgument($Description).AddArgument(180).AddArgument($assistState)
    $assistHandle = $assistShell.BeginInvoke()
    # Closures made inside a function read $script: variables as empty, so keep the window and the log state in locals.
    $assistWindow = $script:AMRRecoveryPointWindow
    $assistLog = @{ Last = ''; Detail = '' }
    $assistHasPoint = (-not [string]::IsNullOrWhiteSpace($Description))
    try {
        $assistAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        Write-AMRLog ('Recovery helper started (AMR elevated={0}).' -f $assistAdmin) INFO Backup
    } catch {}
    $assistTimer = New-Object System.Windows.Threading.DispatcherTimer
    $assistTimer.Interval = [TimeSpan]::FromMilliseconds(700)
    $script:AMRRestoreAssist = [pscustomobject]@{ State = $assistState; Shell = $assistShell; Handle = $assistHandle; Timer = $assistTimer }
    $assistTimer.Add_Tick({
        try {
            $stage = [string]$assistState.Stage
            $note = $null
            try { if ($assistWindow) { $note = $assistWindow.FindName('RpNote') } } catch {}
            try {
                $stageDetail = [string]$assistState.Detail
                if ($stage -ne $assistLog.Last -or $stageDetail -ne $assistLog.Detail) {
                    $assistLog.Last = $stage; $assistLog.Detail = $stageDetail
                    if ($stage -ne '' -or $stageDetail -ne '') { Write-AMRLog ('Recovery helper stage: {0}; method={1}; {2}' -f $stage,[string]$assistState.Method,$stageDetail) INFO Backup }
                }
            } catch {}
            if ($note) {
                switch -Wildcard ($stage) {
                    'radio-selected' { $note.Text = 'Windows is open. The second option is selected for you.'; $note.Visibility = 'Visible' }
                    'next-pressed'   { if ($assistHasPoint) { $note.Text = 'Windows is moving to the list. Your restore point will be selected for you.' } else { $note.Text = 'Windows is moving to the list. No AMR restore point exists yet, so choose one yourself.' }; $note.Visibility = 'Visible' }
                    'list-no-point'  { $note.Text = 'No AMR restore point exists yet, so nothing is marked. Choose a point in the Windows list.'; $note.Visibility = 'Visible' }
                    'next-manual'    { $note.Text = 'The second option is selected for you. Click Next and your point will be selected in the list.'; $note.Visibility = 'Visible' }
                    'row-selected'   { $note.Text = 'Your restore point is selected in the Windows list. Check that the name and time match, then continue in Windows.'; $note.Visibility = 'Visible' }
                    'row-not-found'  { $note.Text = 'Could not mark the point automatically. Choose the one that matches the name and time shown above.'; $note.Visibility = 'Visible' }
                    'ended-*'        { $note.Text = 'The point was not marked automatically. Choose the one that matches the name and time shown above.'; $note.Visibility = 'Visible' }
                }
            }
            # Job done (point selected in the Windows list): the floating window removes itself. Every other outcome keeps it open as the fallback.
            if ($stage -eq 'row-selected' -and $assistWindow) {
                $doneWindow = $assistWindow
                try { $doneWindow.Topmost = $false } catch {}
                try { $assistState.Closed = $true } catch {}
                try { $doneWindow.Close() } catch {}
            }
            if ($assistHandle.IsCompleted) {
                $assistTimer.Stop()
                try { $assistShell.EndInvoke($assistHandle) | Out-Null } catch {}
                try { $assistShell.Dispose() } catch {}
            }
        } catch {}
    }.GetNewClosure())
    $assistTimer.Start()
}

function Update-AMRRecoveryPointWindowInfo {
    $window = $script:AMRRecoveryPointWindow
    if (-not $window) { return }
    $info = Get-AMRRecoveryPointInfo
    $window = $script:AMRRecoveryPointWindow
    if (-not $window) { return }
    $nameBlock = $window.FindName('RpName'); $whenBlock = $window.FindName('RpWhen'); $badge = $window.FindName('RpBadge'); $note = $window.FindName('RpNote'); $copyButton = $window.FindName('RpCopy')
    if ($info.Found) {
        $nameBlock.Text = [string]$info.Name
        $whenBlock.Text = ('#' + [string]$info.Sequence + $(if ($info.When) { '   |   ' + [string]$info.When } else { '' }))
        $badge.Text = [string]$info.Origin
        $copyButton.IsEnabled = $true
        $window.Tag = [string]$info.Name
    } else {
        $nameBlock.Text = 'No AMR restore point found yet'
        $whenBlock.Text = 'Use Smart Create first. Windows System Restore can still be opened.'
        $badge.Text = 'NOTHING TO MARK'
        $copyButton.IsEnabled = $false
        $window.Tag = ''
    }
}

function Show-AMRRecoveryPointWindow {
    if ($script:AMRRecoveryPointWindow) {
        try { [void]$script:AMRRecoveryPointWindow.Activate(); return } catch { $script:AMRRecoveryPointWindow = $null }
    }
    $windowXamlTemplate = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" ResizeMode="NoResize" ShowInTaskbar="False" Topmost="True" SizeToContent="Height" Width="356"
        AllowsTransparency="@@TRANSPARENT@@" Background="@@WINBG@@" FontFamily="Segoe UI" WindowStartupLocation="Manual">
 <Window.Resources>
  <Style x:Key="RpButton" TargetType="Button">
   <Setter Property="Cursor" Value="Hand"/><Setter Property="FocusVisualStyle" Value="{x:Null}"/>
   <Setter Property="Height" Value="32"/><Setter Property="Padding" Value="12,0"/><Setter Property="Margin" Value="0,0,8,0"/>
   <Setter Property="FontSize" Value="11"/><Setter Property="FontWeight" Value="SemiBold"/>
   <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button">
    <Border x:Name="Face" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="9" Padding="{TemplateBinding Padding}" RenderTransformOrigin="0.5,0.5">
     <Border.RenderTransform><ScaleTransform x:Name="FaceScale" ScaleX="1" ScaleY="1"/></Border.RenderTransform>
     <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/>
    </Border>
    <ControlTemplate.Triggers>
     <Trigger Property="IsMouseOver" Value="True">
      <Setter TargetName="Face" Property="BorderBrush" Value="#F0D9A0"/>
      <Setter TargetName="Face" Property="Effect"><Setter.Value><DropShadowEffect Color="#D8B56D" BlurRadius="12" ShadowDepth="0" Opacity="0.45"/></Setter.Value></Setter>
      <Trigger.EnterActions><BeginStoryboard x:Name="In"><Storyboard><DoubleAnimation Storyboard.TargetName="FaceScale" Storyboard.TargetProperty="ScaleX" To="1.04" Duration="0:0:0.12"/><DoubleAnimation Storyboard.TargetName="FaceScale" Storyboard.TargetProperty="ScaleY" To="1.04" Duration="0:0:0.12"/></Storyboard></BeginStoryboard></Trigger.EnterActions>
      <Trigger.ExitActions><RemoveStoryboard BeginStoryboardName="In"/></Trigger.ExitActions>
     </Trigger>
     <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Face" Property="Opacity" Value="0.45"/></Trigger>
    </ControlTemplate.Triggers>
   </ControlTemplate></Setter.Value></Setter>
  </Style>
 </Window.Resources>
 <Border x:Name="RpRoot" CornerRadius="14" BorderThickness="1" BorderBrush="#88E9D8B5" Margin="@@MARGIN@@" Opacity="0" RenderTransformOrigin="0.5,0.5">
  <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="@@BG1@@" Offset="0"/><GradientStop Color="@@BG2@@" Offset="1"/></LinearGradientBrush></Border.Background>
  <Border.RenderTransform><TranslateTransform Y="8"/></Border.RenderTransform>
  <Border.Triggers><EventTrigger RoutedEvent="FrameworkElement.Loaded"><BeginStoryboard><Storyboard><DoubleAnimation Storyboard.TargetProperty="Opacity" From="0" To="1" Duration="0:0:0.18"/><DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="8" To="0" Duration="0:0:0.18" DecelerationRatio="0.8"/></Storyboard></BeginStoryboard></EventTrigger></Border.Triggers>
  <Grid>
   <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
   <Grid x:Name="RpTitleBar" Grid.Row="0" Margin="18,12,10,4" Background="Transparent">
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <TextBlock Text="RECOVERY POINT" FontSize="13" FontWeight="Bold" Foreground="#E9D8B5" VerticalAlignment="Center"/>
    <Button x:Name="RpClose" Grid.Column="1" Content="&#x2715;" Width="28" Height="28" Cursor="Hand" FocusVisualStyle="{x:Null}" Foreground="#CBD5E1" Background="Transparent" BorderThickness="0">
     <Button.Template><ControlTemplate TargetType="Button">
      <Border x:Name="CloseFace" CornerRadius="14" Background="#00000000" BorderBrush="#00000000" BorderThickness="1"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/></Border>
      <ControlTemplate.Triggers>
       <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="CloseFace" Property="Background" Value="#55E5646B"/><Setter TargetName="CloseFace" Property="BorderBrush" Value="#99E5646B"/></Trigger>
       <Trigger Property="IsPressed" Value="True"><Setter TargetName="CloseFace" Property="Background" Value="#88B52A38"/></Trigger>
      </ControlTemplate.Triggers>
     </ControlTemplate></Button.Template>
    </Button>
   </Grid>
   <StackPanel Grid.Row="1" Margin="18,2,18,6">
    <TextBlock x:Name="RpBadge" Text="LOOKING FOR YOUR RESTORE POINT" FontSize="10" FontWeight="Bold" Foreground="#D8B56D"/>
    <TextBlock x:Name="RpName" Text="Finding your restore point..." FontSize="14" FontWeight="Bold" Foreground="#F4EBD3" TextWrapping="Wrap" Margin="0,4,0,0"/>
    <TextBlock x:Name="RpWhen" Text="" FontSize="12" Foreground="#CFCABF" Margin="0,3,0,0" TextWrapping="Wrap"/>
    <Border Height="1" Background="#33D8B56D" Margin="0,10,0,10"/>
    <TextBlock x:Name="RpHint" Text="In the Windows window, choose the restore point with this exact name and time." FontSize="11" Foreground="#B8C2CE" TextWrapping="Wrap"/>
    <TextBlock x:Name="RpNote" Text="" FontSize="11" Foreground="#E2C68E" TextWrapping="Wrap" Margin="0,8,0,0" Visibility="Collapsed"/>
   </StackPanel>
   <StackPanel Grid.Row="2" Orientation="Horizontal" Margin="18,6,18,16">
    <Button x:Name="RpOpen" Content="Open Windows System Restore" Style="{StaticResource RpButton}" Background="#D93B382F" Foreground="#EDE2C9" BorderBrush="#9C865A"/>
    <Button x:Name="RpCopy" Content="Copy name" Style="{StaticResource RpButton}" Background="#303846" Foreground="#E2E8F0" BorderBrush="#526176" IsEnabled="False"/>
   </StackPanel>
  </Grid>
 </Border>
</Window>
'@
    $tiers = @('A','B')
    try { if (([int]([System.Windows.Media.RenderCapability]::Tier -shr 16)) -lt 2) { $tiers = @('B') } } catch {}
    $window = $null
    foreach ($tier in $tiers) {
        try {
            $xaml = $windowXamlTemplate
            if ($tier -eq 'A') { $xaml = $xaml.Replace('@@TRANSPARENT@@','True').Replace('@@WINBG@@','Transparent').Replace('@@MARGIN@@','6').Replace('@@BG1@@','#F0202B3A').Replace('@@BG2@@','#F0111823') }
            else { $xaml = $xaml.Replace('@@TRANSPARENT@@','False').Replace('@@WINBG@@','#FF141B27').Replace('@@MARGIN@@','0').Replace('@@BG1@@','#FF202B3A').Replace('@@BG2@@','#FF111823') }
            $window = [System.Windows.Markup.XamlReader]::Parse($xaml)
            break
        } catch {
            $window = $null
            try { Write-AMRDriverDiagnostic -Severity WARNING -Operation RecoveryCenter -Stage WindowTierFallback -Message ('Recovery point window style {0} failed: {1}' -f $tier,$_.Exception.Message) -Source 'AMRRecoveryPoint' } catch {}
        }
    }
    if (-not $window) {
        Show-AMRMessageGlass 'The Recovery Center window could not be created. Windows System Restore can still be opened from the Start menu.' 'Recovery Center' OK Warning | Out-Null
        return
    }
    try { if ($script:Window -and $script:Window.IsVisible) { $window.Owner = $script:Window } } catch {}
    # Centre it over the AMR window (screen centre when AMR is maximized or minimized). Re-centred once the real height is known.
    $script:AMRCenterRecoveryWindow = {
        param($target)
        try {
            $width = [double]$target.ActualWidth; if ($width -le 0) { $width = 356 }
            $height = [double]$target.ActualHeight; if ($height -le 0) { $height = 300 }
            $vsLeft = [System.Windows.SystemParameters]::VirtualScreenLeft; $vsTop = [System.Windows.SystemParameters]::VirtualScreenTop
            $vsWidth = [System.Windows.SystemParameters]::VirtualScreenWidth; $vsHeight = [System.Windows.SystemParameters]::VirtualScreenHeight
            $main = $script:Window
            if ($main -and $main.IsVisible -and $main.WindowState -eq [System.Windows.WindowState]::Normal -and $main.ActualWidth -gt 0) {
                $left = $main.Left + (($main.ActualWidth - $width) / 2)
                $top = $main.Top + (($main.ActualHeight - $height) / 2)
            } else {
                $work = [System.Windows.SystemParameters]::WorkArea
                $left = $work.Left + (($work.Width - $width) / 2)
                $top = $work.Top + (($work.Height - $height) / 2)
            }
            $target.Left = [Math]::Min([Math]::Max($vsLeft,$left),($vsLeft + $vsWidth - $width))
            $target.Top = [Math]::Min([Math]::Max($vsTop,$top),($vsTop + $vsHeight - $height))
        } catch {}
    }
    & $script:AMRCenterRecoveryWindow $window
    $window.Add_ContentRendered({ param($s,$e) & $script:AMRCenterRecoveryWindow $s })
    $window.Add_PreviewKeyDown({ param($s,$e) if ($e.Key -eq [System.Windows.Input.Key]::Escape) { $e.Handled = $true; $s.Close() } })
    $window.FindName('RpTitleBar').Add_MouseLeftButtonDown({ param($s,$e) try { [System.Windows.Window]::GetWindow($s).DragMove() } catch {} })
    $window.FindName('RpClose').Add_Click({ param($s,$e) try { [System.Windows.Window]::GetWindow($s).Close() } catch {} })
    $window.FindName('RpCopy').Add_Click({
        param($s,$e)
        try {
            $win = [System.Windows.Window]::GetWindow($s)
            if (-not [string]::IsNullOrWhiteSpace([string]$win.Tag)) { [System.Windows.Clipboard]::SetText([string]$win.Tag); $s.Content = 'Copied' }
        } catch {}
    })
    $window.FindName('RpOpen').Add_Click({
        param($s,$e)
        $win = [System.Windows.Window]::GetWindow($s)
        $note = $win.FindName('RpNote')
        try {
            $restoreExe = Join-Path ([Environment]::GetFolderPath('System')) 'rstrui.exe'
            if (-not (Test-Path -LiteralPath $restoreExe -PathType Leaf)) { $restoreExe = Join-Path $env:windir 'sysnative\rstrui.exe' }
            if (-not (Test-Path -LiteralPath $restoreExe -PathType Leaf)) { throw 'rstrui.exe was not found on this PC.' }
            [void](Start-Process -FilePath $restoreExe -PassThru -ErrorAction Stop)
            # Never sit on top of the Windows window: drop Topmost once it is launched.
            try { $win.Topmost = $false } catch {}
            Write-AMRLog 'Opened Windows System Restore from the Recovery Center.' INFO Overview
            # The helper always starts: with an AMR point it marks that point; without one it only presses Next on the first page.
            Start-AMRRestoreWindowAssist -Description ([string]$win.Tag)
        } catch {
            $note.Text = 'Windows System Restore could not be opened: ' + $_.Exception.Message
            $note.Visibility = 'Visible'
            Write-AMRLog ('Recovery Center could not open System Restore: ' + $_.Exception.Message) WARNING Overview
        }
    })
    $window.Add_Closed({
        try { if ($script:AMRRestoreAssist -and $script:AMRRestoreAssist.State) { $script:AMRRestoreAssist.State.Cancel = $true; $script:AMRRestoreAssist.State.Closed = $true } } catch {}
        $script:AMRRecoveryPointWindow = $null
    })
    $script:AMRRecoveryPointWindow = $window
    $window.Show()
    # Fill in the point after the window has painted; the lookup is bounded (8 s) like Smart Restore's.
    [void]$window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background,[Action]{ try { Update-AMRRecoveryPointWindowInfo } catch { try { Write-AMRLog ('Recovery point lookup failed: ' + $_.Exception.Message) WARNING Overview } catch {} } })
}

# Hidden shortcut on System > Backups only: typing "file" or "files" in Smart Search opens the receipt folder.
function Open-AMRRestoreReceiptFolder {
    try {
        $receipt = [string]$script:DriverRestorePointStateFile
        if ([string]::IsNullOrWhiteSpace($receipt)) { return }
        $folder = Split-Path -Parent $receipt
        if (-not (Test-Path -LiteralPath $folder -PathType Container)) { New-Item -ItemType Directory -Path $folder -Force -ErrorAction Stop | Out-Null }
        if (Test-Path -LiteralPath $receipt -PathType Leaf) { [void](Start-Process -FilePath 'explorer.exe' -ArgumentList ('/select,"{0}"' -f $receipt)) }
        else { [void](Start-Process -FilePath 'explorer.exe' -ArgumentList ('"{0}"' -f $folder)) }
    } catch {
        try { Write-AMRLog ('Could not open the restore point files folder: ' + $_.Exception.Message) WARNING Overview } catch {}
    }
}

(C 'DriverSmartRestoreBtn').Add_Click({ Invoke-AMRDriverSmartRestore })
(C 'DriverRecoveryCenterBtn').Add_Click({ Show-AMRRecoveryPointWindow })

# Driver Backup buttons: matched neutral-glass hover and press feedback for both actions.
foreach($driverActionButtonName in @('DriverCreateRestorePointBtn','DriverSmartRestoreBtn')){
    $driverActionButton=C $driverActionButtonName
    if(-not $driverActionButton){continue}
    $driverActionButton.RenderTransformOrigin=[System.Windows.Point]::new(0.5,0.5)
    $driverActionButton.RenderTransform=[System.Windows.Media.ScaleTransform]::new(1.0,1.0)
    $driverActionButton.Add_MouseEnter({
        try{if($this.Style){return};
            if(-not $this.IsEnabled){return}
            $hoverColor='#A0788796'
            $brush=[System.Windows.Media.SolidColorBrush]::new($this.Background.Color);$this.Background=$brush
            $ca=New-Object System.Windows.Media.Animation.ColorAnimation;$ca.To=[System.Windows.Media.ColorConverter]::ConvertFromString($hoverColor);$ca.Duration=[TimeSpan]::FromMilliseconds(165);$ca.EasingFunction=New-Object System.Windows.Media.Animation.QuadraticEase;$brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$ca)
            $edge=[System.Windows.Media.SolidColorBrush]::new($this.BorderBrush.Color);$this.BorderBrush=$edge
            $ea=New-Object System.Windows.Media.Animation.ColorAnimation;$ea.To=[System.Windows.Media.ColorConverter]::ConvertFromString('#F0F4F8');$ea.Duration=[TimeSpan]::FromMilliseconds(165);$edge.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$ea)
            $scale=New-Object System.Windows.Media.Animation.DoubleAnimation;$scale.To=1.018;$scale.Duration=[TimeSpan]::FromMilliseconds(165);$scale.EasingFunction=New-Object System.Windows.Media.Animation.QuadraticEase;$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$scale);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$scale)
        }catch{}
    }.GetNewClosure())
    $driverActionButton.Add_MouseLeave({
        try{if($this.Style){return};
            $baseColor='#805E6B78'
            $edgeColor='#D0DAE4'
            $brush=[System.Windows.Media.SolidColorBrush]::new($this.Background.Color);$this.Background=$brush
            $ca=New-Object System.Windows.Media.Animation.ColorAnimation;$ca.To=[System.Windows.Media.ColorConverter]::ConvertFromString($baseColor);$ca.Duration=[TimeSpan]::FromMilliseconds(185);$brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$ca)
            $edge=[System.Windows.Media.SolidColorBrush]::new($this.BorderBrush.Color);$this.BorderBrush=$edge
            $ea=New-Object System.Windows.Media.Animation.ColorAnimation;$ea.To=[System.Windows.Media.ColorConverter]::ConvertFromString($edgeColor);$ea.Duration=[TimeSpan]::FromMilliseconds(185);$edge.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$ea)
            $scale=New-Object System.Windows.Media.Animation.DoubleAnimation;$scale.To=1.0;$scale.Duration=[TimeSpan]::FromMilliseconds(185);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$scale);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$scale)
        }catch{}
    }.GetNewClosure())
    $driverActionButton.Add_PreviewMouseDown({
        try{if($this.Style){return};if(-not $this.IsEnabled){return};$a=New-Object System.Windows.Media.Animation.DoubleAnimation;$a.To=0.986;$a.Duration=[TimeSpan]::FromMilliseconds(65);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a)}catch{}
    }.GetNewClosure())
    $driverActionButton.Add_PreviewMouseUp({
        try{if($this.Style){return};if(-not $this.IsEnabled -or -not $this.IsMouseOver){return};$a=New-Object System.Windows.Media.Animation.DoubleAnimation;$a.To=1.018;$a.Duration=[TimeSpan]::FromMilliseconds(90);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a);$this.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a)}catch{}
    }.GetNewClosure())
}

# --- Phase 6.10.3 | ASUS routing + ASRock Latest Driver Catalog metadata (building on MSI + GIGABYTE) (based on Phase 6.10.1) ---
# Phase 6.10.1 universal 72-vendor support routing is preserved below.
# --- Phase 6.10.1 | Universal Vendor Coverage Completion (based on Phase 6.10) ---
# --- Phase 6.5: Universal Hardware Coverage & OEM Model Matching ---
# Phase 6.6A: bounded multi-ID discovery and transparent candidate comparison.
# Phase 6.7: expanded offline hardware-ID coverage, evidence confidence and source-manager diagnostics.
# The registry is intentionally local/offline. It identifies vendors and routes users to
# official support portals; a portal reference is never represented as a verified package.
function Get-AMRDriverVendorRegistry {
    return @(
        [pscustomobject]@{Vendor='Dell';Role='OEM';Aliases=@('Dell Inc','Dell Computer','Alienware','OptiPlex','Latitude','Precision','Vostro','Inspiron','XPS');Url='https://www.dell.com/support/home/en-us?app=drivers';Mode='Official OEM support portal';Note='Prefer exact Service Tag or product model. Dell Driver Pack Catalog is a separate system-pack source.'},
        [pscustomobject]@{Vendor='HP';Role='OEM';Aliases=@('HP','Hewlett-Packard','HP Inc','Hewlett Packard','EliteBook','ProBook','ZBook','ZBook Fury','ZBook Power','ZBook Studio','ZBook Firefly','ZBook Create','Pavilion','OMEN','Victus','EliteDesk','ProDesk','Z2','Z4','Z6','Z8');Url='https://support.hp.com/drivers';Mode='Official OEM support portal';Note='ZBook: exact SystemID/model matching through HP Client Driver Pack Catalog and HP HPIA platform SoftPaq references. Victus and other consumer HP systems: use the exact HP product number/model on HP Support Drivers when no public business catalog entry exists; never substitute another model.'},
        [pscustomobject]@{Vendor='Lenovo';Role='OEM';Aliases=@('Lenovo','ThinkPad','ThinkCentre','IdeaPad','Legion','Yoga');Url='https://pcsupport.lenovo.com/';Mode='Official OEM support portal';Note='Use exact machine type/model (MTM) or serial number; regional variants may share a family name but differ by MTM.'},
