        [pscustomobject]@{ ProviderId='Dynabook.DriverPortal'; DisplayName='Dynabook Drivers and Software'; AdapterType='SpecializedPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true; Capabilities=@('Discover','Search','GetDetails'); Acquisition='Model/serial-selected official portal; manual package selection'; Verification='Exact Dynabook/Toshiba model and OS required; older Toshiba model support may differ by region'; Notes='Official support portal provides model-filtered drivers, software patches and updates.' },
        [pscustomobject]@{ ProviderId='Huawei.DriverPortal'; DisplayName='HUAWEI PC Driver List'; AdapterType='SpecializedPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true; Capabilities=@('Discover','Search','GetDetails'); Acquisition='PC Manager recommended; serial-selected driver list where available'; Verification='Exact serial/model and region required; no result is not evidence that no driver exists'; Notes='Huawei recommends PC Manager and exposes a serial-number-based driver list; avoid guessing direct package URLs.' },
        [pscustomobject]@{ ProviderId='MicrosoftSurface.DriverPortal'; DisplayName='Microsoft Surface Drivers and Firmware'; AdapterType='SpecializedPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true; Capabilities=@('Discover','Search','GetDetails'); Acquisition='Model/OS-specific Microsoft Download Center MSI; manual acquisition pending AMR package verification'; Verification='Exact Surface model and Windows build/architecture required; MSI bundles can contain multiple drivers and firmware; inspect contents before installability'; Notes='Microsoft publishes model-specific Surface MSI bundles and recommends Windows Update for routine updates; bundle is not treated as an individual INF driver.' },
        [pscustomobject]@{ ProviderId='Intel.DriverPortal'; DisplayName='Intel Official Driver Portal'; AdapterType='OfficialPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true; Capabilities=@('Discover','Search','GetDetails'); Acquisition='None - user-assisted official portal'; Verification='No package resolved; exact model and OS must be confirmed on Intel'; Notes='Intel does not expose a documented public driver-catalog API for this adapter; links to Intel Download Center and DSA.' },
        [pscustomobject]@{ ProviderId='NVIDIA.DriverPortal'; DisplayName='NVIDIA Official Driver Portal'; AdapterType='OfficialPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true; Capabilities=@('Discover','Search','GetDetails'); Acquisition='None - user-assisted official portal'; Verification='No package resolved; exact GPU, OS, driver branch and notebook/desktop variant must be confirmed on NVIDIA'; Notes='NVIDIA driver search is provided as an official portal route; no unsupported private API is called.' },
        [pscustomobject]@{ ProviderId='AMD.DriverPortal'; DisplayName='AMD Official Driver Portal'; AdapterType='OfficialPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true; Capabilities=@('Discover','Search','GetDetails'); Acquisition='None - user-assisted official portal'; Verification='No package resolved; exact product and OS must be confirmed on AMD'; Notes='AMD Product Selector and Auto-Detect documentation; portal route only.' },
        [pscustomobject]@{ ProviderId='Generic.JSON'; DisplayName='Generic JSON Catalog Template'; AdapterType='Generic'; SourceAdapter='AMRGenericJSONCatalog'; Enabled=$false; Capabilities=@(); Acquisition='Not configured'; Verification='Metadata only until a provider is registered'; Notes='Template only; register a validated provider definition before use.' },
        [pscustomobject]@{ ProviderId='Generic.XML'; DisplayName='Generic XML Catalog Template'; AdapterType='Generic'; SourceAdapter='AMRGenericXMLCatalog'; Enabled=$false; Capabilities=@(); Acquisition='Not configured'; Verification='Metadata only until a provider is registered'; Notes='Template only; register a validated provider definition before use.' }
    )
    # Register every known OEM/component/peripheral/ODM/system-integrator portal as a
    # first-class source in the same Local Vendor API. Portal sources are discovery leads,
    # never package candidates and never installable. Dedicated catalog providers above
    # retain their stronger capabilities and are not duplicated here.
    $dedicatedIds=@('Microsoft.WindowsUpdate','Microsoft.UpdateCatalog','Dell.DriverPackCatalog','HP.ClientDriverPackCatalog','Lenovo.CDRT','MSI.DriverCatalog','GIGABYTE.DriverCatalog','ASRock.DriverCatalog','Realtek.DriverPortal','Broadcom.DriverPortal','Qualcomm.DriverPortal','MediaTek.DriverPortal','Marvell.DriverPortal','SiliconLabs.DriverPortal','FTDI.DriverPortal','WCH.DriverPortal','ASIX.DriverPortal','Prolific.DriverPortal','CMedia.DriverPortal','Infineon.DriverPortal','Synaptics.DriverPortal','Goodix.DriverPortal','ELAN.DriverPortal','GenesysLogic.DriverPortal','ASMedia.DriverPortal','Logitech.DriverPortal','SteelSeries.DriverPortal','Corsair.DriverPortal','Elgato.DriverPortal','AVerMedia.DriverPortal','Razer.DriverPortal','Acer.DriverPortal','Fujitsu.DriverPortal','Panasonic.DriverPortal','Dynabook.DriverPortal','Huawei.DriverPortal','MicrosoftSurface.DriverPortal','Intel.DriverPortal','NVIDIA.DriverPortal','AMD.DriverPortal','Generic.JSON','Generic.XML')
    foreach($vendorEntry in @(Get-AMRDriverVendorRegistry)) {
        $portalId=Get-AMRVendorPortalProviderId -Vendor ([string]$vendorEntry.Vendor)
        if($portalId -in $dedicatedIds) { continue }
        if(@($providers | Where-Object {$_.ProviderId -eq $portalId}).Count -gt 0) { continue }
        $providers += [pscustomobject]@{
            ProviderId=$portalId; DisplayName=([string]$vendorEntry.Vendor+' Official Support Portal')
            AdapterType='OfficialPortal'; SourceAdapter='OfficialVendorPortal'; Enabled=$true
            Capabilities=@('Discover','Search','GetDetails')
            Acquisition='None - user-assisted official support portal'
            Verification='Portal lead only; no package/version/INF/CAT/signature has been resolved'
            Notes=([string]$vendorEntry.Role+' | '+[string]$vendorEntry.Note)
        }
    }
    # Append validated user-defined providers from the local manifest; never execute provider code.
    try {
        $manifest=Get-AMRLocalVendorProviderManifest
        foreach($provider in @($manifest.providers)) {
            $validation=Test-AMRLocalVendorProviderDefinition -Provider $provider
            if(-not $validation.IsValid){continue}
            $providers += [pscustomobject]@{
                ProviderId=[string]$provider.id;DisplayName=[string]$provider.name;AdapterType=('Generic'+[string]$provider.type)
                SourceAdapter=$(if([string]$provider.type -eq 'JSON'){'AMRGenericJSONCatalog'}else{'AMRGenericXMLCatalog'})
                Enabled=[bool]$provider.enabled;Capabilities=@('Discover','Search','GetDetails')
                Acquisition='Shared AMR acquisition only after explicit package resolver and verification';Verification='Metadata only until package is independently acquired and verified'
                Notes='Validated local manifest provider; no arbitrary code execution.'
            }
        }
    } catch { }
    return @($providers)
}

function Get-AMRLocalVendorAdapterCapabilities {
    [CmdletBinding()]
    param([string]$ProviderId='')
    $registry=@(Get-AMRLocalVendorAdapterRegistry)
    if(-not [string]::IsNullOrWhiteSpace($ProviderId)) { return @($registry | Where-Object { $_.ProviderId -eq $ProviderId }) }
    return $registry
}

function ConvertTo-AMRLocalVendorCandidate {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Candidate,[string]$ProviderId='')
    $item=$Candidate | Select-Object *
    $defaults=@{
        ProviderId=$ProviderId; SourceAdapter=''; Source=''; Manufacturer=''; Model=''; Title=''; Version='Not supplied'; DriverDate='Not supplied'
        MatchConfidence='Not assessed'; MatchReason='No device-match evidence supplied.'; SearchTerms=''; PackageUrl=''; Url=''; ExpectedHash=''; HashAlgorithm=''
        IsDownloaded=$false; IsInstallable=$false; IsDownloadable=$false; VerificationState='Not verified'; Capabilities=@(); ProviderMetadata=$null
    }
    foreach($key in $defaults.Keys) { if(-not $item.PSObject.Properties[$key]) { $item | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force } }
    if($ProviderId -and -not $item.ProviderId) { $item.ProviderId=$ProviderId }
    # Metadata-only candidates cannot silently become installable through normalization.
    if([string]$item.SourceAdapter -in @('OfficialVendorPortal','AMRGenericJSONCatalog','AMRGenericXMLCatalog')) { $item.IsInstallable=$false }
    return $item
}

function Get-AMRLocalManifestValue {
    param([object]$InputObject,[string]$Path)
    $value=$InputObject
    foreach($segment in @($Path -split '\.' | Where-Object { $_ })) {
        if($null -eq $value) { return $null }
        if($value -is [System.Collections.IDictionary]) { $value=$value[$segment] }
        else { $property=$value.PSObject.Properties[$segment]; if($property) { $value=$property.Value } else { return $null } }
    }
    return $value
}


# Phase 6.9 completion: provider manifest lifecycle and strict generic adapter contract.
function Get-AMRLocalVendorManifestPath {
    $driverRoot=Join-Path $script:DownloadDir 'Drivers'
    $adapterRoot=Join-Path $driverRoot '_VendorAdapters'
    if(-not (Test-Path -LiteralPath $adapterRoot -PathType Container)){New-Item -ItemType Directory -Path $adapterRoot -Force -ErrorAction Stop | Out-Null}
    return (Join-Path $adapterRoot 'providers.json')
}

function Test-AMRLocalVendorProviderDefinition {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Provider)
    $errors=New-Object 'System.Collections.Generic.List[string]'
    $id=[string]$Provider.id; $name=[string]$Provider.name; $type=[string]$Provider.type; $endpoint=[string]$Provider.searchUrl
    if($id -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]{2,79}$'){$errors.Add('Provider id must be 3-80 safe characters (letters, numbers, dot, underscore or hyphen).')}
    if($id -in @('Microsoft.WindowsUpdate','Microsoft.UpdateCatalog','Dell.DriverPackCatalog','HP.ClientDriverPackCatalog','Lenovo.CDRT','MSI.DriverCatalog','GIGABYTE.DriverCatalog','ASRock.DriverCatalog','Realtek.DriverPortal','Broadcom.DriverPortal','Qualcomm.DriverPortal','MediaTek.DriverPortal','Marvell.DriverPortal','SiliconLabs.DriverPortal','FTDI.DriverPortal','WCH.DriverPortal','ASIX.DriverPortal','Prolific.DriverPortal','CMedia.DriverPortal','Infineon.DriverPortal','Synaptics.DriverPortal','Goodix.DriverPortal','ELAN.DriverPortal','GenesysLogic.DriverPortal','ASMedia.DriverPortal','Logitech.DriverPortal','SteelSeries.DriverPortal','Corsair.DriverPortal','Elgato.DriverPortal','AVerMedia.DriverPortal','Razer.DriverPortal','Acer.DriverPortal','Fujitsu.DriverPortal','Panasonic.DriverPortal','Dynabook.DriverPortal','Huawei.DriverPortal','MicrosoftSurface.DriverPortal','Intel.DriverPortal','NVIDIA.DriverPortal','AMD.DriverPortal','Generic.JSON','Generic.XML') -or $id -match '^Vendor\..+\.OfficialPortal$'){$errors.Add('Provider id is reserved by a built-in AMR adapter or generated official-vendor portal.')}
    if([string]::IsNullOrWhiteSpace($name) -or $name.Length -gt 120){$errors.Add('Provider name is required and must be at most 120 characters.')}
    if($type -notin @('JSON','XML')){$errors.Add('Only JSON and XML catalog adapters are supported by the generic engine.')}
    $uri=$null
    if(-not [uri]::TryCreate($endpoint,[UriKind]::Absolute,[ref]$uri) -or $null -eq $uri -or $uri.Scheme -ne 'https'){$errors.Add('Search URL must be an absolute HTTPS URL.')}
    $hosts=@($Provider.allowedHosts | ForEach-Object {([string]$_).Trim().ToLowerInvariant()} | Where-Object {$_})
    if($hosts.Count -eq 0){$errors.Add('At least one exact allowed host is required.')}
    foreach($host in $hosts){if($host -notmatch '^(?=.{1,253}$)[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?$' -or $host.Contains('..') -or $host.StartsWith('.') -or $host.EndsWith('.')){$errors.Add(('Invalid allowed host: '+$host))}}
    if($uri -and $uri.Host.ToLowerInvariant() -notin $hosts){$errors.Add('Search URL host must be included in allowedHosts.')}
    if([string]$Provider.itemsPath -notmatch '^[A-Za-z0-9_.$\[\]-]{1,200}$'){$errors.Add('itemsPath is missing or contains unsupported path syntax.')}
    foreach($field in @('title','version','downloadUrl','model','date','hash')){
        $path=[string]$Provider.fields.$field
        if($field -eq 'title' -and [string]::IsNullOrWhiteSpace($path)){$errors.Add('fields.title is required.')}
        if($path -and $path -notmatch '^[A-Za-z0-9_.$\[\]-]{1,200}$'){$errors.Add(('Invalid field path: '+$field))}
    }
    if([string]$Provider.hashAlgorithm -and [string]$Provider.hashAlgorithm -notin @('SHA256','SHA384','SHA512','MD5')){$errors.Add('hashAlgorithm must be SHA256, SHA384, SHA512 or MD5.')}
    return [pscustomobject]@{IsValid=($errors.Count -eq 0);Errors=@($errors.ToArray());ProviderId=$id;ProviderType=$type;AllowedHosts=@($hosts | Select-Object -Unique)}
}

function Get-AMRLocalVendorProviderManifest {
    [CmdletBinding()]
    param()
    $path=Get-AMRLocalVendorManifestPath
    if(-not (Test-Path -LiteralPath $path -PathType Leaf)){return [pscustomobject]@{schemaVersion=1;providers=@()}}
    try{$data=Get-Content -LiteralPath $path -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop}catch{throw ('Vendor provider manifest is invalid JSON: '+$_.Exception.Message)}
    if([int]$data.schemaVersion -ne 1){throw 'Unsupported vendor provider manifest schemaVersion.'}
    if($null -eq $data.providers){$data.providers=@()}
    return $data
}

function Save-AMRLocalVendorProviderManifest {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Manifest)
    $path=Get-AMRLocalVendorManifestPath
    $ids=@{}
    foreach($provider in @($Manifest.providers)){
        $check=Test-AMRLocalVendorProviderDefinition -Provider $provider
        if(-not $check.IsValid){throw ('Provider '+[string]$provider.id+' rejected: '+($check.Errors -join ' '))}
        $key=$check.ProviderId.ToLowerInvariant();if($ids.ContainsKey($key)){throw ('Duplicate provider id: '+$check.ProviderId)};$ids[$key]=$true
    }
    $temp=$path+'.tmp'
    try{$Manifest | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $temp -Encoding UTF8 -ErrorAction Stop;Move-Item -LiteralPath $temp -Destination $path -Force -ErrorAction Stop}catch{Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue;throw}
    return $path
}

function Register-AMRLocalVendorProvider {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Provider)
    $check=Test-AMRLocalVendorProviderDefinition -Provider $Provider
    if(-not $check.IsValid){throw ('Provider definition validation failed: '+($check.Errors -join ' '))}
    $manifest=Get-AMRLocalVendorProviderManifest
    $existing=@($manifest.providers | Where-Object {[string]$_.id -ne [string]$Provider.id})
    $manifest.providers=@($existing)+@($Provider)
    Save-AMRLocalVendorProviderManifest -Manifest $manifest | Out-Null
    return [pscustomobject]@{ProviderId=[string]$Provider.id;Registered=$true;Enabled=[bool]$Provider.enabled;Validation=$check}
}

function Set-AMRLocalVendorProviderEnabled {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$ProviderId,[Parameter(Mandatory=$true)][bool]$Enabled)
    $manifest=Get-AMRLocalVendorProviderManifest;$found=$false
    foreach($provider in @($manifest.providers)){if([string]$provider.id -eq $ProviderId){$provider.enabled=$Enabled;$found=$true}}
    if(-not $found){throw ('Provider not found: '+$ProviderId)}
    Save-AMRLocalVendorProviderManifest -Manifest $manifest | Out-Null
    return [pscustomobject]@{ProviderId=$ProviderId;Enabled=$Enabled}
}

function Get-AMRGenericVendorManifestCandidates {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[string]$ProviderId='')
    $results=New-Object 'System.Collections.Generic.List[object]'
    $errors=New-Object 'System.Collections.Generic.List[string]'
    try{$manifest=Get-AMRLocalVendorProviderManifest}catch{return [pscustomobject]@{Results=@();Errors=@($_.Exception.Message)}}
    foreach($provider in @($manifest.providers)) {
        try {
            if(-not [bool]$provider.enabled -or ($ProviderId -and [string]$provider.id -ne $ProviderId)){continue}
            $validation=Test-AMRLocalVendorProviderDefinition -Provider $provider
            if(-not $validation.IsValid){$errors.Add(([string]$provider.id+': '+($validation.Errors -join '; ')));continue}
            $allowed=@($validation.AllowedHosts)
            $endpoint=[string]$provider.searchUrl
            $hardware=@($Device.HardwareIds | Select-Object -First 5)
            $compatible=@($Device.CompatibleIds | Select-Object -First 2)
            $queryParts=@([string]$Device.DeviceName)+$hardware+$compatible
            $query=([uri]::EscapeDataString((@($queryParts | Where-Object {$_}) -join ' ')))
            $requestUrl=$endpoint.Replace('{query}',$query).Replace('{model}',[uri]::EscapeDataString([string]$Device.DeviceName))
            if($requestUrl -match '\{[^}]+\}'){$errors.Add(([string]$provider.id+': unsupported URL template token.'));continue}
            $requestUri=[uri]$requestUrl
            if($requestUri.Scheme -ne 'https' -or $requestUri.Host.ToLowerInvariant() -notin $allowed){$errors.Add(([string]$provider.id+': request URL failed host validation.'));continue}
            $response=Invoke-WebRequest -Uri $requestUri.AbsoluteUri -UseBasicParsing -TimeoutSec 25 -MaximumRedirection 5 -ErrorAction Stop
            $finalUri=$requestUri
            try{if($response.BaseResponse -and $response.BaseResponse.ResponseUri){$finalUri=[uri]$response.BaseResponse.ResponseUri}}catch{}
            if($finalUri.Scheme -ne 'https' -or $finalUri.Host.ToLowerInvariant() -notin $allowed){throw 'Redirect destination is not in the provider allowed-host list.'}
            if([string]$provider.type -eq 'JSON'){$payload=$response.Content | ConvertFrom-Json -ErrorAction Stop}else{[xml]$payload=$response.Content}
            $rows=Get-AMRLocalManifestValue -InputObject $payload -Path ([string]$provider.itemsPath)
            $rowCount=0
            foreach($row in @($rows)) {
                if($rowCount -ge 100){break};$rowCount++
                $title=[string](Get-AMRLocalManifestValue $row ([string]$provider.fields.title))
                if([string]::IsNullOrWhiteSpace($title)){continue}
                $version=[string](Get-AMRLocalManifestValue $row ([string]$provider.fields.version))
                $downloadValue=[string](Get-AMRLocalManifestValue $row ([string]$provider.fields.downloadUrl))
                $resolved=''
                if($downloadValue){try{$resolved=([uri]::new($finalUri,$downloadValue)).AbsoluteUri}catch{}}
                if($resolved){$downloadUri=[uri]$resolved;if($downloadUri.Scheme -ne 'https' -or $downloadUri.Host.ToLowerInvariant() -notin $allowed){$resolved=''}}
                $modelValue=[string](Get-AMRLocalManifestValue $row ([string]$provider.fields.model))
                $hashValue=[string](Get-AMRLocalManifestValue $row ([string]$provider.fields.hash))
                $results.Add([pscustomobject]@{
                    ProviderId=[string]$provider.id;Title=$title;Name=$title;Source=[string]$provider.name;Manufacturer=[string]$provider.name
                    Model=$modelValue;Version=$(if($version){$version}else{'Not supplied'})
                    DriverDate=[string](Get-AMRLocalManifestValue $row ([string]$provider.fields.date));PackageUrl=$resolved;Url=$resolved
                    SourceAdapter=$(if([string]$provider.type -eq 'JSON'){'AMRGenericJSONCatalog'}else{'AMRGenericXMLCatalog'})
                    MatchConfidence='Unverified catalog metadata';MatchReason='Generic provider metadata only; package contents, exact INF Hardware ID, OS compatibility and signature must be verified by the shared AMR acquisition pipeline.'
                    SearchTerms=([uri]::UnescapeDataString($query));IsDownloaded=$false;IsInstallable=$false;IsDownloadable=[bool]$resolved
                    VerificationState='Metadata only – not verified for installation';ExpectedHash=$hashValue;HashAlgorithm=[string]$provider.hashAlgorithm
                    Capabilities=@('Discover','Search','GetDetails');ProviderMetadata=[pscustomobject]@{ProviderId=[string]$provider.id;CatalogType=[string]$provider.type;AllowedHosts=$allowed;ExpectedHash=$hashValue}
                })
            }
        } catch {$errors.Add(([string]$provider.id+': '+[string]$_.Exception.Message))}
    }
    return [pscustomobject]@{Results=@($results.ToArray());Errors=@($errors.ToArray())}
}

# --- Phase 6.10.1 | Full OEM + component + peripheral + system-integrator portal coverage ---
function Get-AMRAllVendorSupportPortalCandidates {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[object]$OEMProfile,[string]$ProviderId='')
    $results=New-Object 'System.Collections.Generic.List[object]'
    $errors=New-Object 'System.Collections.Generic.List[string]'
    $targets=New-Object 'System.Collections.Generic.List[object]'
    $deviceName='';$manufacturer='';$hardwareSummary='';$evidence=''
    try { if($Device.PSObject.Properties['DeviceName']){$deviceName=[string]$Device.DeviceName} } catch {}
    try { if($Device.PSObject.Properties['Manufacturer']){$manufacturer=[string]$Device.Manufacturer} } catch {}
    try { if($Device.PSObject.Properties['HardwareIdSummary']){$hardwareSummary=[string]$Device.HardwareIdSummary} } catch {}

    # Explicit USB/PCI vendor-ID fallbacks for chip vendors whose friendly PnP
    # manufacturer strings are frequently missing, generic, or OEM-branded.
    # These IDs identify a silicon/bridge vendor only; they do not prove package compatibility.
    $rawIds=@(@($Device.HardwareIds)+@($Device.CompatibleIds) | ForEach-Object {[string]$_} | Where-Object {$_})
    $idVendorRules=@(
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_10EC|PCI\\VEN_10EC)';Vendor='Realtek'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_0BDA|PCI\\VEN_10EC)';Vendor='Realtek'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_0A5C|PCI\\VEN_14E4)';Vendor='Broadcom'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_0E8D|PCI\\VEN_14C3)';Vendor='MediaTek'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_05C6|PCI\\VEN_17CB|PCI\\VEN_168C)';Vendor='Qualcomm'},
        [pscustomobject]@{Pattern='(?i)(?:PCI\\VEN_11AB|PCI\\VEN_1B4B)';Vendor='Marvell'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_10C4';Vendor='Silicon Labs'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_0403';Vendor='FTDI'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_1A86';Vendor='WCH'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_0B95';Vendor='ASIX'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_067B';Vendor='Prolific'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_0D8C';Vendor='C-Media'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_04B4';Vendor='Infineon'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_06CB|PCI\\VEN_06CB)';Vendor='Synaptics'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_27C6';Vendor='Goodix'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_04F3|ACPI\\ELAN)';Vendor='ELAN'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_05E3';Vendor='Genesys Logic'},
        [pscustomobject]@{Pattern='(?i)PCI\\VEN_1B21';Vendor='ASMedia'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_046D';Vendor='Logitech'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_1038';Vendor='SteelSeries'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_1B1C';Vendor='Corsair'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_0FD9';Vendor='Elgato'},
        [pscustomobject]@{Pattern='(?i)(?:USB\\VID_07CA|PCI\\VEN_1461)';Vendor='AverMedia'},
        [pscustomobject]@{Pattern='(?i)USB\\VID_1532';Vendor='Razer'}
    )
    foreach($rule in $idVendorRules) {
        $matchedId=$rawIds | Where-Object {$_ -match $rule.Pattern} | Select-Object -First 1
        if($matchedId) {
            $idEntry=Resolve-AMRDriverVendorName -Text ([string]$rule.Vendor)
            if($idEntry) {
                $targets.Add([pscustomobject]@{
                    Entry=$idEntry;Evidence=('Explicit hardware vendor ID '+$matchedId+' maps to '+$rule.Vendor+'; vendor identity only, not package compatibility')
                    Model=$deviceName;Kind='Hardware ID vendor fallback'
                })
            }
        }
    }

    # Chip / controller vendor from PCI, USB, HDAUDIO, ACPI or PnP evidence.
    try {
        $coverage=Get-AMRDriverHardwareCoverage -Device $Device
        if($coverage -and $coverage.HardwareVendorName) {
            $coverageVendor=[string]$coverage.HardwareVendorName
            # A Microsoft USB peripheral is not evidence that the host is a Surface PC.
            if($coverageVendor -match '(?i)^Microsoft$' -and $deviceName -notmatch '(?i)Surface') { $coverageVendor='' }
            $entry=if($coverageVendor){Resolve-AMRDriverVendorName -Text $coverageVendor}else{$null}
            if($entry) {
                $evidence='Hardware ID: '+[string]$coverage.HardwareVendorEvidence+' ('+[string]$coverage.HardwareVendorEvidenceLevel+')'
                $targets.Add([pscustomobject]@{Entry=$entry;Evidence=$evidence;Model=$deviceName;Kind='Component'})
            }
            # A SUBSYS vendor may identify the board/ODM partner (e.g. GPU board maker)
            # independently from the silicon vendor in PCI VEN_. Keep it as secondary evidence.
            if($coverage.SubsystemVendorName -and [string]$coverage.SubsystemVendorName -ne $coverageVendor) {
                $partner=Resolve-AMRDriverVendorName -Text ([string]$coverage.SubsystemVendorName)
                if($partner) {
                    $partnerEvidence='PCI subsystem partner ID (secondary evidence; silicon vendor remains primary)'
                    $targets.Add([pscustomobject]@{Entry=$partner;Evidence=$partnerEvidence;Model=$deviceName;Kind='Subsystem partner'})
                }
            }
        }
    } catch { $errors.Add('Hardware-vendor routing: '+[string]$_.Exception.Message) }

    # Exact computer maker/model and board maker/model are independent sources.
    if($OEMProfile) {
        try {
            $oemText=[string]$OEMProfile.OEMVendor
            if(-not $oemText){$oemText=[string]$OEMProfile.ComputerManufacturer}
            if($oemText) {
                # The Surface portal is selected only when SMBIOS product identity supports it.
                if($oemText -match '(?i)Microsoft' -and ([string]$OEMProfile.ComputerModel+' '+[string]$OEMProfile.ProductName) -notmatch '(?i)Surface') { $oemText='' }
                $entry=if($oemText){Resolve-AMRDriverVendorName -Text $oemText -Role 'OEM'}else{$null}
                if(-not $entry){$entry=Resolve-AMRDriverVendorName -Text $oemText}
                if($entry) {
                    $model=[string]$OEMProfile.ComputerModel
                    if(-not $model){$model=[string]$OEMProfile.ProductName}
                    $targets.Add([pscustomobject]@{Entry=$entry;Evidence=('System manufacturer/model identity: '+$oemText+'; '+[string]$OEMProfile.Confidence);Model=$model;Kind='OEM'})
                }
            }
        } catch { $errors.Add('OEM portal routing: '+[string]$_.Exception.Message) }
        try {
            $boardText=[string]$OEMProfile.BoardVendor
            if(-not $boardText){$boardText=[string]$OEMProfile.BoardManufacturer}
            if($boardText) {
                $entry=Resolve-AMRDriverVendorName -Text $boardText -Role 'Motherboard'
                if(-not $entry){$entry=Resolve-AMRDriverVendorName -Text $boardText}
                if($entry) {
                    $boardModel=[string]$OEMProfile.BoardProduct
                    $targets.Add([pscustomobject]@{Entry=$entry;Evidence=('Motherboard manufacturer/model: '+$boardText);Model=$boardModel;Kind='Motherboard'})
                }
            }
        } catch { $errors.Add('Motherboard portal routing: '+[string]$_.Exception.Message) }
        # Preserve multiple board vendors from an inventory (multi-board/workstation cases).
        foreach($boardMatch in @($OEMProfile.BoardVendorMatches)) {
            try {
                $entry=Resolve-AMRDriverVendorName -Text ([string]$boardMatch.Vendor) -Role 'Motherboard'
                if(-not $entry){$entry=Resolve-AMRDriverVendorName -Text ([string]$boardMatch.Vendor)}
                if($entry){$targets.Add([pscustomobject]@{Entry=$entry;Evidence=('Board inventory: '+[string]$boardMatch.InventoryText);Model=[string]$boardMatch.InventoryText;Kind='Motherboard / inventory'})}
            } catch {}
        }
    }

    # PnP manufacturer is supporting evidence only; never let it replace stronger IDs.
    if($manufacturer) {
        try {
            $manufacturerText=$manufacturer
            if($manufacturerText -match '(?i)Microsoft' -and $deviceName -notmatch '(?i)Surface'){$manufacturerText=''}
            $entry=if($manufacturerText){Resolve-AMRDriverVendorName -Text $manufacturerText}else{$null}
            if($entry){$targets.Add([pscustomobject]@{Entry=$entry;Evidence='PnP manufacturer string (supporting evidence only)';Model=$deviceName;Kind='PnP'})}
        } catch {}
    }

    $seen=@{}
    foreach($target in $targets) {
        if(-not $target.Entry){continue}
        $entry=$target.Entry
        $vendor=[string]$entry.Vendor
        $id=Get-AMRVendorPortalProviderId -Vendor $vendor
        if($ProviderId -and $ProviderId -ne $id){continue}
        $dedupeKey=($id+'|'+[string]$target.Kind+'|'+[string]$target.Model)
        if($seen.ContainsKey($dedupeKey)){continue}
        $seen[$dedupeKey]=$true
        $url=[string]$entry.Url
        $uri=$null
        if(-not [uri]::TryCreate($url,[UriKind]::Absolute,[ref]$uri) -or $null -eq $uri -or $uri.Scheme -ne 'https') {
            $errors.Add(('Skipped '+$vendor+': registry URL is not a valid HTTPS support portal.'))
            continue
        }
        $searchTerms=(@($target.Model,$deviceName,$hardwareSummary) | Where-Object {$_}) -join ' '
        $results.Add([pscustomobject]@{
            CandidateId=('PORTAL-'+($vendor -replace '[^A-Za-z0-9]','')+'-'+([guid]::NewGuid().ToString('N').Substring(0,8)))
            ProviderId=$id;Title=($vendor+' Official Support Portal');Name=($vendor+' Official Support Portal')
            Source=($vendor+' official support website');Manufacturer=$vendor;Model=[string]$target.Model
            Version='Not resolved';DriverDate='Not resolved';SourceAdapter='OfficialVendorPortal';CandidateType='OfficialSupportPortal'
            Url=$url;SupportUrl=$url;SecondarySupportUrl='';PackageUrl='';ExpectedHash='';HashAlgorithm=''
            OS=[string]$script:DriverWindowsContext;Architecture=''
            MatchConfidence='Vendor/source identified; exact package compatibility not verified'
            MatchReason=([string]$target.Kind+' source identified. '+[string]$target.Evidence+'. '+[string]$entry.Note)
            SearchTerms=$searchTerms;ComparisonScore=0;ComparisonRank=0
            IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$false
            VerificationState='Official support portal lead only. No driver package, version, INF/CAT, hash or signature has been resolved.'
            Capabilities=@('Discover','Search','GetDetails')
            ProviderMetadata=[pscustomobject]@{
                Vendor=$vendor;Role=[string]$entry.Role;PrimaryUrl=$url;Evidence=[string]$target.Evidence
                ResolutionMode=[string]$entry.Mode;DirectPackageApiSupported=$false;PortalOnly=$true
                OEMFirst=($vendor -in @('Qualcomm','MediaTek','Realtek','Broadcom'))
                HardwareIds=@($rawIds | Select-Object -First 8)
                SearchGuidance=$(switch($vendor){
                    'Realtek' {'Search exact codec/controller family; prefer OEM-customized audio/WLAN package when available.'}
                    'Broadcom' {'Search exact chip/product part number and Drivers asset type; sign-in/entitlement may be required.'}
                    'Qualcomm' {'Check laptop/system OEM and Windows Update first; Qualcomm consumer driver catalog is limited.'}
                    'MediaTek' {'Check laptop/system OEM and Windows Update first; use exact WLAN/Bluetooth module model.'}
                    'Marvell' {'Search exact part number/platform in Public Driver Downloads; license acceptance may be required.'}
                    'Silicon Labs' {'CP210x route is relevant only when USB VID_10C4 identifies a Silicon Labs bridge.'}
                    'FTDI' {'VCP route is relevant only when USB VID_0403 identifies an FTDI interface.'}
                    'WCH' {'Confirm CH34x/CH91xx family before choosing a WCH package.'}
                    'ASIX' {'Confirm exact AX-series USB Ethernet chipset before choosing a package.'}
                    'Prolific' {'Confirm USB VID_067B and exact PL2303 chip family/PID; check whether the adapter uses a legacy revision before selecting a current driver.'}
                    'C-Media' {'Confirm exact C-Media USB audio codec/model and prefer the headset, motherboard or computer OEM package.'}
                    'Infineon' {'Confirm exact Infineon/Cypress controller family and product generation; VID_04B4 alone is not enough to select a driver.'}
                    'Synaptics' {'For touchpads and fingerprint devices, use the exact notebook OEM model and its customized driver package first.'}
                    'Goodix' {'Confirm the exact Goodix fingerprint/touch controller and retrieve the driver from the system OEM.'}
                    'ELAN' {'Confirm exact ELAN touchpad/controller hardware ID and use the notebook OEM package first.'}
                    'Genesys Logic' {'Confirm the exact USB hub/card-reader controller model and the system/peripheral OEM package.'}
                    'ASMedia' {'Confirm exact ASM controller model and motherboard revision; prefer the board OEM package.'}
                    'Logitech' {'Search by exact Logitech model or part number; separate Options+ / G HUB software and firmware from a real driver package.'}
                    'SteelSeries' {'Search by exact device model; SteelSeries GG is companion software and must not be treated as a generic driver.'}
                    'Corsair' {'Use the exact Corsair product selector; distinguish iCUE, firmware and product-specific driver packages.'}
                    'Elgato' {'Confirm exact capture-device model and Windows version; respect the official UVC plug-and-play designation where no proprietary driver is needed.'}
                    'AverMedia' {'Select exact capture/tuner model and hardware revision; filter the official catalog by Driver versus Firmware or Application.'}
                    'Razer' {'Use exact Razer peripheral or Blade model; Synapse and firmware are separate from a device driver.'}
                    default {'Use exact model and operating system; confirm package applicability independently.'}
                })
            }
        })
    }
    return [pscustomobject]@{Results=@($results.ToArray());Errors=@($errors.ToArray());SourcesQueried=@($results | ForEach-Object {$_.Manufacturer} | Select-Object -Unique);PortalOnly=$true}
}

# --- Phase 6.10 | Intel / NVIDIA / AMD official support portal adapters ---
function Get-AMROfficialGraphicsVendorPortalCandidates {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[string]$ProviderId='')
    $results=New-Object 'System.Collections.Generic.List[object]'
    $hardware=@()
    try { $hardware=@($Device.HardwareIds | ForEach-Object {[string]$_}) } catch {}
    $compatible=@()
    try { $compatible=@($Device.CompatibleIds | ForEach-Object {[string]$_}) } catch {}
    $deviceName=[string]$Device.DeviceName
    $classText=@([string]$Device.Class,[string]$Device.DeviceClass,[string]$Device.ClassName) -join ' '
    $isDisplay=($classText -match '(?i)display') -or ($deviceName -match '(?i)display|graphics|video|radeon|geforce|quadro|arc\s|iris|uhd graphics')
    if(-not $isDisplay){return [pscustomobject]@{Results=@();Errors=@();SourcesQueried=@();PortalOnly=$true}}
    $vendor='';$vendorId=''
    foreach($id in @($hardware+$compatible)) {
        if($id -match '(?i)^PCI\\VEN_([0-9A-F]{4})') {
            $vendorId=$Matches[1].ToUpperInvariant()
            switch($vendorId) {
                '8086' {$vendor='Intel'}
                '10DE' {$vendor='NVIDIA'}
                '1002' {$vendor='AMD'}
            }
            if($vendor){break}
        }
    }
    if(-not $vendor) {
        if($deviceName -match '(?i)Intel.*(Graphics|Arc|Iris|UHD)|\bArc\s*A?\d{3,4}\b'){$vendor='Intel';$vendorId='8086'}
        elseif($deviceName -match '(?i)NVIDIA|GeForce|Quadro|RTX\s*\d{3,4}'){$vendor='NVIDIA';$vendorId='10DE'}
        elseif($deviceName -match '(?i)AMD Radeon|Radeon RX|Radeon Pro'){$vendor='AMD';$vendorId='1002'}
    }
    if(-not $vendor){return [pscustomobject]@{Results=@();Errors=@();SourcesQueried=@();PortalOnly=$true}}
    $id=switch($vendor){'Intel'{'Intel.DriverPortal'} 'NVIDIA'{'NVIDIA.DriverPortal'} 'AMD'{'AMD.DriverPortal'}}
    if($ProviderId -and $ProviderId -ne $id){return [pscustomobject]@{Results=@();Errors=@();SourcesQueried=@();PortalOnly=$true}}
    $portalUrl=switch($vendor){
        'Intel' {'https://www.intel.com/content/www/us/en/download-center/home.html'}
        'NVIDIA' {'https://www.nvidia.com/Download/index.aspx'}
        'AMD' {'https://www.amd.com/en/support/download/drivers.html'}
    }
    $secondaryUrl=switch($vendor){
        'Intel' {'https://www.intel.com/content/www/us/en/support/detect.html'}
        'NVIDIA' {'https://www.nvidia.com/en-us/geforce/drivers/'}
        'AMD' {'https://www.amd.com/en/resources/support-articles/faqs/GPU-131.html'}
    }
    $searchTerms=(@($deviceName)+@($hardware | Select-Object -First 4)) -join ' '
    $matchReason=('{0} hardware vendor identified from {1}; this is an official support route, not a verified driver match.' -f $vendor,$vendorId)
    $results.Add([pscustomobject]@{
        CandidateId=('PORTAL-'+$vendorId+'-'+([guid]::NewGuid().ToString('N').Substring(0,8)))
        ProviderId=$id;Title=($vendor+' Official Driver Support');Name=($vendor+' Official Driver Support')
        Source=($vendor+' official support website');Manufacturer=$vendor;Model=$deviceName;Version='Not resolved';DriverDate='Not resolved'
        SourceAdapter='OfficialVendorPortal';CandidateType='OfficialSupportPortal';Url=$portalUrl;SupportUrl=$portalUrl;SecondarySupportUrl=$secondaryUrl
        PackageUrl='';ExpectedHash='';HashAlgorithm='';OS=[string]$script:DriverWindowsContext;Architecture=''
        MatchConfidence='Vendor identified only - exact driver compatibility not verified';MatchReason=$matchReason
        SearchTerms=$searchTerms;ComparisonScore=0;ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$false
        VerificationState='Portal route only. AMR has not resolved a driver package, version, hardware compatibility, or signature.'
        Capabilities=@('Discover','Search','GetDetails');ProviderMetadata=[pscustomobject]@{VendorId=$vendorId;PrimaryUrl=$portalUrl;SecondaryUrl=$secondaryUrl;ResolutionMode='User-assisted official portal';DirectPackageApiSupported=$false}
    })
    return [pscustomobject]@{Results=@($results.ToArray());Errors=@();SourcesQueried=@($vendor+' official portal');PortalOnly=$true}
}

function Invoke-AMRLocalVendorApi {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][ValidateSet('GetCapabilities','GetProvider','ValidateProvider','RegisterProvider','SetProviderEnabled','Discover','Search','GetDetails','ResolveDownload','Acquire','Normalize')][string]$Action,
        [object]$Device,[object]$OEMProfile,[string]$ProviderId='',[object[]]$Candidates=@(),[object]$ProviderDefinition,[bool]$Enabled=$true,[string]$CandidateId='',[object]$Candidate
    )
    switch($Action) {
        'GetCapabilities' {return Get-AMRLocalVendorAdapterCapabilities -ProviderId $ProviderId}
        'GetProvider' {
            if($ProviderId){$builtin=@(Get-AMRLocalVendorAdapterRegistry | Where-Object {$_.ProviderId -eq $ProviderId});if($builtin.Count){return $builtin[0]}}
            $manifest=Get-AMRLocalVendorProviderManifest;return @($manifest.providers | Where-Object {[string]$_.id -eq $ProviderId})
        }
        'ValidateProvider' {if(-not $ProviderDefinition){throw 'ValidateProvider requires ProviderDefinition.'};return Test-AMRLocalVendorProviderDefinition -Provider $ProviderDefinition}
        'RegisterProvider' {if(-not $ProviderDefinition){throw 'RegisterProvider requires ProviderDefinition.'};return Register-AMRLocalVendorProvider -Provider $ProviderDefinition}
        'SetProviderEnabled' {if(-not $ProviderId){throw 'SetProviderEnabled requires ProviderId.'};return Set-AMRLocalVendorProviderEnabled -ProviderId $ProviderId -Enabled $Enabled}
        'ResolveDownload' {
            if(-not $Candidate){throw 'ResolveDownload requires Candidate.'}
            $adapter=[string]$Candidate.SourceAdapter
            if($adapter -in @('OfficialVendorPortal','MSIDriverCatalogMetadata','GigabyteDriverCatalogMetadata','ASRockDriverCatalogMetadata')){throw 'This candidate is catalog metadata only. Open the official vendor package URL manually; AMR will not download or install it until archive hash/signature and INF/CAT verification are implemented.'}
            $allowedHosts=switch($adapter){'DellDriverPackCatalog' {@('downloads.dell.com','ftp.dell.com')} 'HPDriverPackCatalog' {@('ftp.hp.com','hpia.hpcloud.hp.com')} 'LenovoCDRTDriverPackCatalog' {@('download.lenovo.com')} default {@()}}
            $uri=$null;$url=[string]$Candidate.PackageUrl
            if(-not [uri]::TryCreate($url,[UriKind]::Absolute,[ref]$uri) -or $null -eq $uri -or $uri.Scheme -ne 'https' -or $uri.Host.ToLowerInvariant() -notin $allowedHosts){throw 'Candidate does not expose a download URL approved by its registered dedicated adapter.'}
            return [pscustomobject]@{ProviderId=$ProviderId;Uri=$uri.AbsoluteUri;Host=$uri.Host;RequiresAcquisitionVerification=$true;Installable=$false}
        }
        'Acquire' {
            if(-not $Device -or -not $Candidate){throw 'Acquire requires Device and Candidate.'}
            $resolved=Invoke-AMRLocalVendorApi -Action ResolveDownload -ProviderId $ProviderId -Candidate $Candidate
            return Invoke-AMRVendorPackageAcquisition -Device $Device -Candidate $Candidate
        }
        'Normalize' {
            $normalized=New-Object 'System.Collections.Generic.List[object]'
            foreach($candidate in @($Candidates)){if($candidate){$normalized.Add((ConvertTo-AMRLocalVendorCandidate -Candidate $candidate -ProviderId $ProviderId))}}
            return @($normalized.ToArray())
        }
        {$_ -in @('Discover','Search')} {
            if(-not $Device){throw ($Action+' requires a device record.')}
            $all=New-Object 'System.Collections.Generic.List[object]';$errors=New-Object 'System.Collections.Generic.List[string]'
            if(-not $ProviderId -or $ProviderId -in @('Dell.DriverPackCatalog','HP.ClientDriverPackCatalog','Lenovo.CDRT')){
                $dedicatedDiscovery=Get-AMRDirectVendorPackageCandidates -Device $Device -OEMProfile $OEMProfile
                foreach($candidate in @($dedicatedDiscovery.Results)){
                    if($candidate){$candidateProvider=[string]$candidate.ProviderId;if(-not $candidateProvider){$candidateProvider=[string]$candidate.SourceAdapter};if(-not $ProviderId -or $ProviderId -eq $candidateProvider -or ($ProviderId -eq 'Dell.DriverPackCatalog' -and $candidateProvider -match 'Dell') -or ($ProviderId -eq 'HP.ClientDriverPackCatalog' -and $candidateProvider -match 'HP') -or ($ProviderId -eq 'Lenovo.CDRT' -and $candidateProvider -match 'Lenovo')){$all.Add((ConvertTo-AMRLocalVendorCandidate -Candidate $candidate -ProviderId $candidateProvider))}}
                }
                foreach($message in @($dedicatedDiscovery.Errors)){$errors.Add([string]$message)}
            }
            # MSI and GIGABYTE expose model-specific public motherboard catalog endpoints.
            # These are metadata-only adapters: direct URLs are surfaced, but no download or
            # install is enabled until package/archive verification is implemented.
            if(-not $ProviderId -or $ProviderId -in @('MSI.DriverCatalog','GIGABYTE.DriverCatalog')){
                $boardCatalog=Get-AMRBoardVendorCatalogMetadataCandidates -Device $Device -OEMProfile $OEMProfile -ProviderId $ProviderId
                foreach($candidate in @($boardCatalog.Results)){if($candidate){$all.Add((ConvertTo-AMRLocalVendorCandidate -Candidate $candidate -ProviderId ([string]$candidate.ProviderId)))}}
                foreach($message in @($boardCatalog.Errors)){$errors.Add([string]$message)}
            }
            if(-not $ProviderId -or $ProviderId -eq 'ASRock.DriverCatalog'){
                $asrockCatalog=Get-AMRAsrockDriverCatalogMetadataCandidates -Device $Device -OEMProfile $OEMProfile
                foreach($candidate in @($asrockCatalog.Results)){if($candidate){$all.Add((ConvertTo-AMRLocalVendorCandidate -Candidate $candidate -ProviderId 'ASRock.DriverCatalog'))}}
                foreach($message in @($asrockCatalog.Errors)){$errors.Add([string]$message)}
            }
            # Remaining vendors continue through the universal official portal layer.
            $portalDiscovery=Get-AMRAllVendorSupportPortalCandidates -Device $Device -OEMProfile $OEMProfile -ProviderId $ProviderId
            foreach($candidate in @($portalDiscovery.Results)){
                if($candidate){$all.Add((ConvertTo-AMRLocalVendorCandidate -Candidate $candidate -ProviderId ([string]$candidate.ProviderId)))}
            }
            foreach($message in @($portalDiscovery.Errors)){$errors.Add([string]$message)}
            $isGenericProvider=(-not $ProviderId -or $ProviderId -like 'Generic.*' -or @((Get-AMRLocalVendorProviderManifest).providers | Where-Object {[string]$_.id -eq $ProviderId}).Count -gt 0)
            if($isGenericProvider){
                $generic=Get-AMRGenericVendorManifestCandidates -Device $Device -ProviderId $(if($ProviderId){$ProviderId}else{''})
                foreach($candidate in @($generic.Results)){if($candidate){$all.Add((ConvertTo-AMRLocalVendorCandidate -Candidate $candidate -ProviderId ([string]$candidate.ProviderId)))}}
                foreach($message in @($generic.Errors)){$errors.Add([string]$message)}
            }
            return [pscustomobject]@{Action=$Action;ProviderId=$ProviderId;Results=@($all.ToArray());Errors=@($errors.ToArray());CompletedAt=(Get-Date)}
        }
        'GetDetails' {
            foreach($candidate in @($Candidates)){if($CandidateId -and [string]$candidate.CandidateId -eq $CandidateId){return $candidate}}
            return $null
        }
    }
}

# --- Phase 6.10.2 | Direct motherboard catalog metadata adapters (MSI + GIGABYTE) ---
# Changes: adds exact-model MSI and GIGABYTE driver metadata discovery; six-hour local cache;
# official-host validation; direct package links remain non-downloadable/non-installable by AMR
# until package archive hash/signature and INF/CAT verification are implemented.
# These adapters use the vendors' public support endpoints, but deliberately emit
# metadata-only candidates. They do not download, execute, or install vendor packages.
function Get-AMRVendorObjectValue {
    [CmdletBinding()]
    param([object]$InputObject,[string[]]$Names)
    if($null -eq $InputObject){return $null}
    foreach($name in $Names){
        $property=$InputObject.PSObject.Properties | Where-Object {$_.Name -ieq $name} | Select-Object -First 1
        if($property -and $null -ne $property.Value -and [string]$property.Value -ne ''){return $property.Value}
    }
    return $null
}

function Get-AMRVendorObjectTree {
    [CmdletBinding()]
    param([object]$InputObject,[int]$Depth=0)
    $items=New-Object 'System.Collections.Generic.List[object]'
    if($null -eq $InputObject -or $Depth -gt 18){return @()}
    if($InputObject -is [string] -or $InputObject -is [ValueType]){return @()}
    if($InputObject -is [System.Collections.IDictionary]){
        $items.Add($InputObject)
        foreach($value in $InputObject.Values){foreach($child in @(Get-AMRVendorObjectTree -InputObject $value -Depth ($Depth+1))){$items.Add($child)}}
    } elseif($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [pscustomobject]){
        foreach($value in $InputObject){foreach($child in @(Get-AMRVendorObjectTree -InputObject $value -Depth ($Depth+1))){$items.Add($child)}}
    } else {
        $items.Add($InputObject)
        foreach($property in $InputObject.PSObject.Properties){if($property.MemberType -in @('NoteProperty','Property','AliasProperty')){foreach($child in @(Get-AMRVendorObjectTree -InputObject $property.Value -Depth ($Depth+1))){$items.Add($child)}}}
    }
    return @($items.ToArray())
}

function ConvertTo-AMRVendorModelKey {
    param([string]$Value)
    if([string]::IsNullOrWhiteSpace($Value)){return ''}
    return ([regex]::Replace($Value.ToUpperInvariant(),'[^A-Z0-9]',''))
}

function Get-AMRBoardVendorCatalogMetadataCandidates {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[object]$OEMProfile,[string]$ProviderId='')
    $results=New-Object 'System.Collections.Generic.List[object]'
    $errors=New-Object 'System.Collections.Generic.List[string]'
    $boardModel=[string]$OEMProfile.BoardProduct
    if($boardModel -match '(?i)to be filled|default string|unknown|system product name'){$boardModel=''}
    if(-not $boardModel -or $boardModel -match '(?i)to be filled|default string|unknown'){
        return [pscustomobject]@{Results=@();Errors=@('MSI/GIGABYTE direct catalogs require an exact motherboard product model; no reliable board model was detected.');SourcesQueried=@();MetadataOnly=$true}
    }
    $boardKey=ConvertTo-AMRVendorModelKey $boardModel
    $cacheRoot=Join-Path (Join-Path $script:DownloadDir 'Drivers') '_VendorCatalogCache'
    if(-not(Test-Path -LiteralPath $cacheRoot -PathType Container)){New-Item -ItemType Directory -Path $cacheRoot -Force -ErrorAction Stop | Out-Null}
    $osLabel='Win11 64'
    if([string]$script:DriverWindowsContext -match '(?i)Windows\s*10'){$osLabel='Win10 64'}
    elseif([string]$script:DriverWindowsContext -match '(?i)Windows\s*11'){$osLabel='Win11 64'}
    else{$errors.Add('Vendor motherboard catalogs currently query Windows 10/11 x64 only; this OS context was not recognized.')}

    # MSI support panel: product slug is the exact board model; this endpoint returns driver metadata.
    if(-not $ProviderId -or $ProviderId -eq 'MSI.DriverCatalog'){
        try{
            if($OEMProfile.BoardVendor -match '(?i)MSI|Micro-Star' -or $boardModel -match '(?i)^MS-[A-Z0-9]{3,}$'){
                $slugSource=([string]$boardModel).Trim() -replace '(?i)\s*\(MS-[A-Z0-9]+\)\s*$',''
                if($slugSource -match '(?i)^MS-[A-Z0-9]+$'){throw 'MSI SMBIOS board code was detected without the commercial product slug; exact product catalog lookup is not safe.'}
                $slug=([regex]::Replace($slugSource,'[^A-Za-z0-9]+','-')).Trim('-')
                $cachePath=Join-Path $cacheRoot ('MSI_'+$boardKey+'_'+($osLabel -replace '\s+','')+'.json')
                $cached=$false
                if(Test-Path -LiteralPath $cachePath -PathType Leaf){$cacheAge=(Get-Date)-(Get-Item -LiteralPath $cachePath).LastWriteTime;if($cacheAge.TotalHours -lt 6){try{$cachedRows=@(Get-Content -LiteralPath $cachePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop);foreach($cachedRow in $cachedRows){$results.Add($cachedRow)};$cached=$true}catch{Remove-Item -LiteralPath $cachePath -Force -ErrorAction SilentlyContinue}}}
                if(-not $cached){
                $beforeCount=$results.Count
                $uri='https://www.msi.com/api/v1/product/support/panel?product='+[uri]::EscapeDataString($slug)+'&type=driver&os='+[uri]::EscapeDataString($osLabel)
                $response=Invoke-WebRequest -Uri $uri -UseBasicParsing -TimeoutSec 25 -MaximumRedirection 3 -ErrorAction Stop
                if($response.BaseResponse -and $response.BaseResponse.ResponseUri -and ([uri]$response.BaseResponse.ResponseUri).Host -notin @('www.msi.com','msi.com')){throw 'MSI catalog redirected outside the official MSI host.'}
                $payload=$response.Content | ConvertFrom-Json -ErrorAction Stop
                foreach($row in @(Get-AMRVendorObjectTree -InputObject $payload)){
                    $title=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('download_name','download_title','name','title','fileName'))
                    $rawUrl=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('download_url','download_link','url','link','fileUrl'))
                    if(-not $title -or -not $rawUrl -or $title -match '(?i)BIOS|Firmware|Utility|MSI Center|Manual') {continue}
                    $packageUri=$null
                    if(-not [uri]::TryCreate($rawUrl,[UriKind]::Absolute,[ref]$packageUri)){try{$packageUri=[uri]::new([uri]'https://www.msi.com/',$rawUrl)}catch{continue}}
                    if($packageUri.Scheme -ne 'https' -or $packageUri.Host.ToLowerInvariant() -notin @('download.msi.com','download.msi.com.tw')){continue}
                    $version=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('download_version','version','Version'))
                    $date=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('download_date','release_date','date','Date'))
                    $hashRaw=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('download_sha256','sha256','SHA256'))
                    $hash=([regex]::Match($hashRaw,'(?i)[A-F0-9]{64}')).Value
                    $sizeValue=Get-AMRVendorObjectValue -InputObject $row -Names @('download_size','file_size','size')
                    $size=0L;[void][long]::TryParse([string]$sizeValue,[ref]$size)
                    $results.Add([pscustomobject]@{
                        CandidateId=('MSI-'+([guid]::NewGuid().ToString('N').Substring(0,10)));ProviderId='MSI.DriverCatalog'
                        Title=$title;Name=$title;Source='MSI Official Driver Catalog';Manufacturer='MSI';Model=$boardModel
                        Version=$(if($version){$version}else{'Not supplied'});DriverDate=$(if($date){$date}else{'Not supplied'})
                        SourceAdapter='MSIDriverCatalogMetadata';CandidateType='OfficialCatalogMetadata';Url=$packageUri.AbsoluteUri;SupportUrl='https://www.msi.com/support'
                        PackageUrl=$packageUri.AbsoluteUri;ExpectedHash=$hash;HashAlgorithm=$(if($hash){'SHA256'}else{''});ExpectedSize=$size;OS=$osLabel;Architecture='x64'
                        MatchConfidence='Exact MSI motherboard model endpoint; package contents not inspected'
                        MatchReason=('MSI support panel returned this driver entry for exact board model '+$boardModel+'. Published SHA-256 '+$(if($hash){'is available'}else{'was not supplied'})+'.')
                        SearchTerms=$boardModel;ComparisonScore=45;ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$false
                        VerificationState='Official catalog metadata only. Manual vendor download is possible from the official URL; AMR has not acquired or inspected the archive.'
                        Capabilities=@('Discover','Search','GetDetails');ProviderMetadata=[pscustomobject]@{Catalog='MSI';ProductSlug=$slug;PublishedSHA256=$hash;MetadataOnly=$true}
                    })
                }
                $freshRows=@($results | Select-Object -Skip $beforeCount)
                if($freshRows.Count -gt 0){$freshRows | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $cachePath -Encoding UTF8 -ErrorAction SilentlyContinue}
                }
            }
        } catch {$errors.Add('MSI direct catalog: '+[string]$_.Exception.Message)}
    }

    # GIGABYTE: resolve an exact product ID from its official motherboard list, then read its support tab.
    if(-not $ProviderId -or $ProviderId -eq 'GIGABYTE.DriverCatalog'){
        try{
            if($OEMProfile.BoardVendor -match '(?i)GIGABYTE|Gigabyte' -or $OEMProfile.BoardProduct -match '(?i)AORUS|GIGABYTE'){
                $cachePath=Join-Path $cacheRoot ('GIGABYTE_'+$boardKey+'_'+($osLabel -replace '\s+','')+'.json')
                $cached=$false
                if(Test-Path -LiteralPath $cachePath -PathType Leaf){$cacheAge=(Get-Date)-(Get-Item -LiteralPath $cachePath).LastWriteTime;if($cacheAge.TotalHours -lt 6){try{$cachedRows=@(Get-Content -LiteralPath $cachePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop);foreach($cachedRow in $cachedRows){$results.Add($cachedRow)};$cached=$true}catch{Remove-Item -LiteralPath $cachePath -Force -ErrorAction SilentlyContinue}}}
                if(-not $cached){
                $beforeCount=$results.Count
                $listUrl='https://www.gigabyte.com/iisApplicationNuxt/api/proxy/api/v1.0/Support/global/DownloadCenter/2/GetProducts'
                $listResponse=Invoke-WebRequest -Uri $listUrl -UseBasicParsing -TimeoutSec 30 -MaximumRedirection 3 -ErrorAction Stop
                if($listResponse.BaseResponse -and $listResponse.BaseResponse.ResponseUri -and ([uri]$listResponse.BaseResponse.ResponseUri).Host -notin @('www.gigabyte.com','gigabyte.com')){throw 'GIGABYTE product catalog redirected outside the official host.'}
                $listPayload=$listResponse.Content | ConvertFrom-Json -ErrorAction Stop
                $matchedProduct=$null
                foreach($row in @(Get-AMRVendorObjectTree -InputObject $listPayload)){
                    $name=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('productName','ProductName','name','Name','model','Model'))
                    $idValue=Get-AMRVendorObjectValue -InputObject $row -Names @('productId','ProductId','productID','id','Id')
                    if($name -and $idValue -and (ConvertTo-AMRVendorModelKey $name) -eq $boardKey){$matchedProduct=$row;break}
                }
                if(-not $matchedProduct){throw ('No exact GIGABYTE motherboard catalog match was returned for '+$boardModel+'.')}
                $productId=[string](Get-AMRVendorObjectValue -InputObject $matchedProduct -Names @('productId','ProductId','productID','id','Id'))
                $tabUrl='https://www.gigabyte.com/iisApplicationNuxt/api/proxy/api/v1.0/Consumer/global/GetProductTabDataAsync/Support/'+[uri]::EscapeDataString($productId)
                $tabResponse=Invoke-WebRequest -Uri $tabUrl -UseBasicParsing -TimeoutSec 30 -MaximumRedirection 3 -ErrorAction Stop
                if($tabResponse.BaseResponse -and $tabResponse.BaseResponse.ResponseUri -and ([uri]$tabResponse.BaseResponse.ResponseUri).Host -notin @('www.gigabyte.com','gigabyte.com')){throw 'GIGABYTE support tab redirected outside the official host.'}
                $tabPayload=$tabResponse.Content | ConvertFrom-Json -ErrorAction Stop
                foreach($row in @(Get-AMRVendorObjectTree -InputObject $tabPayload)){
                    $title=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('fileName','FileName','title','Title','name','Name'))
                    $rawUrl=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('fileUrl','FileUrl','downloadUrl','DownloadUrl','url','Url','path','Path'))
                    if(-not $title -or -not $rawUrl -or $title -notmatch '(?i)driver|audio|chipset|LAN|WLAN|Bluetooth|USB|SATA|RAID|Serial|VGA') {continue}
                    if($title -match '(?i)BIOS|Firmware|Utility|APP Center|EasyTune|RGB Fusion') {continue}
                    $packageUri=$null
                    if(-not [uri]::TryCreate($rawUrl,[UriKind]::Absolute,[ref]$packageUri)){try{$packageUri=[uri]::new([uri]'https://www.gigabyte.com/',$rawUrl)}catch{continue}}
                    if($packageUri.Scheme -ne 'https' -or $packageUri.Host.ToLowerInvariant() -notin @('download.gigabyte.com','www.gigabyte.com')){continue}
                    $version=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('version','Version','fileVersion','FileVersion'))
                    $date=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('releaseDate','ReleaseDate','date','Date'))
                    $osText=[string](Get-AMRVendorObjectValue -InputObject $row -Names @('os','OS','operatingSystem','OperatingSystem'))
                    if($osText -and $osText -notmatch '(?i)Windows\s*(10|11)|Win\s*(10|11)') {continue}
                    $results.Add([pscustomobject]@{
                        CandidateId=('GIGA-'+([guid]::NewGuid().ToString('N').Substring(0,10)));ProviderId='GIGABYTE.DriverCatalog'
                        Title=$title;Name=$title;Source='GIGABYTE Official Driver Catalog';Manufacturer='GIGABYTE';Model=$boardModel
                        Version=$(if($version){$version}else{'Not supplied'});DriverDate=$(if($date){$date}else{'Not supplied'})
                        SourceAdapter='GigabyteDriverCatalogMetadata';CandidateType='OfficialCatalogMetadata';Url=$packageUri.AbsoluteUri;SupportUrl='https://www.gigabyte.com/Support'
                        PackageUrl=$packageUri.AbsoluteUri;ExpectedHash='';HashAlgorithm='';OS=$(if($osText){$osText}else{$osLabel});Architecture='x64'
                        MatchConfidence='Exact GIGABYTE product ID; OS metadata may require manual confirmation'
                        MatchReason=('GIGABYTE official product catalog exact model match ('+$productId+'). Package checksum is not published in the parsed metadata and has not been inferred from the URL.')
                        SearchTerms=$boardModel;ComparisonScore=44;ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$false
                        VerificationState='Official catalog metadata only. The URL points to a vendor-hosted package; AMR has not downloaded, hashed, signature-checked or INF-validated it.'
                        Capabilities=@('Discover','Search','GetDetails');ProviderMetadata=[pscustomobject]@{Catalog='GIGABYTE';ProductId=$productId;MetadataOnly=$true;QueryHashTrusted=$false}
                    })
                }
                $freshRows=@($results | Select-Object -Skip $beforeCount)
                if($freshRows.Count -gt 0){$freshRows | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $cachePath -Encoding UTF8 -ErrorAction SilentlyContinue}
                }
            }
        } catch {$errors.Add('GIGABYTE direct catalog: '+[string]$_.Exception.Message)}
    }
    return [pscustomobject]@{Results=@($results.ToArray());Errors=@($errors.ToArray());SourcesQueried=@($results | ForEach-Object {$_.Source} | Select-Object -Unique);MetadataOnly=$true}
}

# --- Phase 6.10.3 | ASRock public latest-driver listing adapter ---
# The public ASRock Latest Drivers Update page exposes model/description/OS/date/size/download
# rows. This adapter performs exact model matching only and surfaces vendor-hosted metadata.
# It never downloads, executes or installs a package; package archive/signature/INF/CAT checks
# remain mandatory before a future acquisition adapter can be enabled.
function Get-AMRAsrockDriverCatalogMetadataCandidates {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[object]$OEMProfile)
    $results=New-Object 'System.Collections.Generic.List[object]'
    $errors=New-Object 'System.Collections.Generic.List[string]'
    $boardVendor=[string]$OEMProfile.BoardVendor
    if(-not $boardVendor){$boardVendor=[string]$OEMProfile.BoardManufacturer}
    if($boardVendor -notmatch '(?i)ASRock') {
        return [pscustomobject]@{Results=@();Errors=@();SourcesQueried=@();MetadataOnly=$true}
    }
    $boardModel=[string]$OEMProfile.BoardProduct
    if(-not $boardModel -or $boardModel -match '(?i)to be filled|default string|unknown|system product name|base board product') {
        $errors.Add('ASRock catalog requires an exact motherboard product model; no reliable BoardProduct value was detected.')
        return [pscustomobject]@{Results=@();Errors=@($errors.ToArray());SourcesQueried=@();MetadataOnly=$true}
    }
    $boardKey=ConvertTo-AMRVendorModelKey $boardModel
    if(-not $boardKey -or $boardKey.Length -lt 5) {
        $errors.Add('ASRock motherboard model was too short for safe exact matching; no catalog search was attempted.')
        return [pscustomobject]@{Results=@();Errors=@($errors.ToArray());SourcesQueried=@();MetadataOnly=$true}
    }
    $windows=[string]$script:DriverWindowsContext
    if($windows -notmatch '(?i)Windows\s*(10|11)') {
        $errors.Add('ASRock public latest-driver adapter currently filters Windows 10/11 listings only.')
        return [pscustomobject]@{Results=@();Errors=@($errors.ToArray());SourcesQueried=@();MetadataOnly=$true}
    }
    $cacheRoot=Join-Path (Join-Path $script:DownloadDir 'Drivers') '_VendorCatalogCache'
    if(-not(Test-Path -LiteralPath $cacheRoot -PathType Container)){New-Item -ItemType Directory -Path $cacheRoot -Force -ErrorAction Stop | Out-Null}
    $cachePath=Join-Path $cacheRoot ('ASRock_'+$boardKey+'_'+($(if($windows -match '(?i)Windows\s*11'){'Win11'}else{'Win10'}))+'.json')
    try {
        $cached=$false
        if(Test-Path -LiteralPath $cachePath -PathType Leaf) {
            $age=(Get-Date)-(Get-Item -LiteralPath $cachePath).LastWriteTime
            if($age.TotalHours -lt 6) {
                try {
                    $cachedRows=@(Get-Content -LiteralPath $cachePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop)
                    foreach($row in $cachedRows){if($row){$results.Add($row)}}
                    $cached=$true
                } catch {Remove-Item -LiteralPath $cachePath -Force -ErrorAction SilentlyContinue}
            }
        }
        if(-not $cached) {
            $pageUrl='https://www.asrock.com/support/index.asp?cat=Drivers'
            $response=Invoke-WebRequest -Uri $pageUrl -UseBasicParsing -TimeoutSec 45 -MaximumRedirection 3 -ErrorAction Stop
            if($response.BaseResponse -and $response.BaseResponse.ResponseUri) {
                $finalUri=[uri]$response.BaseResponse.ResponseUri
                if($finalUri.Scheme -ne 'https' -or $finalUri.Host.ToLowerInvariant() -notin @('asrock.com','www.asrock.com','pg.asrock.com')) {
                    throw 'ASRock latest-driver page redirected outside the approved official ASRock hosts.'
                }
            }
            $html=[string]$response.Content
            if($html.Length -lt 1000 -or $html -notmatch '(?i)Latest Drivers Update') {throw 'ASRock response did not contain the expected Latest Drivers Update page.'}
            $htmlRows=[regex]::Matches($html,'(?is)<tr\b[^>]*>(.*?)</tr>')
            $found=0
            foreach($rowMatch in $htmlRows) {
                $rowHtml=[string]$rowMatch.Groups[1].Value
                $cells=[regex]::Matches($rowHtml,'(?is)<td\b[^>]*>(.*?)</td>')
                if($cells.Count -lt 5){continue}
                $cellText=New-Object 'System.Collections.Generic.List[string]'
                foreach($cell in $cells) {
                    $raw=[regex]::Replace([string]$cell.Groups[1].Value,'(?is)<script\b.*?</script>|<style\b.*?</style>',' ')
                    $raw=[regex]::Replace($raw,'(?is)<[^>]+>',' ')
                    $raw=[System.Net.WebUtility]::HtmlDecode($raw)
                    $raw=[regex]::Replace($raw,'\s+',' ').Trim()
                    $cellText.Add($raw)
                }
                $modelCell=[string]$cellText[0]
                $modelAnchors=[regex]::Matches([string]$cells[0].Groups[1].Value,'(?is)<a\b[^>]*>(.*?)</a>')
                $matchedModel=''
                foreach($anchor in $modelAnchors) {
                    $anchorText=[regex]::Replace([string]$anchor.Groups[1].Value,'(?is)<[^>]+>',' ')
                    $anchorText=[System.Net.WebUtility]::HtmlDecode(([regex]::Replace($anchorText,'\s+',' ')).Trim())
                    if((ConvertTo-AMRVendorModelKey $anchorText) -eq $boardKey){$matchedModel=$anchorText;break}
                }
                if(-not $matchedModel -and (ConvertTo-AMRVendorModelKey $modelCell) -eq $boardKey){$matchedModel=$modelCell}
                if(-not $matchedModel){continue}
                $description=[string]$cellText[1]
                $osText=[string]$cellText[2]
                $dateText=[string]$cellText[3]
                $sizeText=[string]$cellText[4]
                if($description -notmatch '(?i)driver|chipset|audio|LAN|WLAN|Bluetooth|USB|SATA|RAID|VGA|Ethernet|Wireless') {continue}
                if($description -match '(?i)BIOS|Firmware|Utility|APP Shop|Polychrome|A-Tuning') {continue}
                if($osText -and $osText -notmatch '(?i)Windows\s*(10|11)|Win\s*(10|11)') {continue}
                if($windows -match '(?i)Windows\s*11' -and $osText -match '(?i)Windows\s*10' -and $osText -notmatch '(?i)Windows\s*11') {continue}
                if($windows -match '(?i)Windows\s*10' -and $osText -match '(?i)Windows\s*11' -and $osText -notmatch '(?i)Windows\s*10') {continue}
                $downloadAnchors=[regex]::Matches([string]$cells[$cells.Count-1].Groups[1].Value,'(?is)<a\b[^>]*href\s*=\s*["'']([^"'']+)["''][^>]*>(.*?)</a>')
                if($downloadAnchors.Count -eq 0) {
                    # Some ASRock rows place the download link in any cell after the model.
                    $downloadAnchors=[regex]::Matches($rowHtml,'(?is)<a\b[^>]*href\s*=\s*["'']([^"'']+)["''][^>]*>(.*?)</a>')
                }
                $packageUri=$null
                foreach($anchor in $downloadAnchors) {
                    $href=[System.Net.WebUtility]::HtmlDecode([string]$anchor.Groups[1].Value).Trim()
                    try {$candidateUri=[uri]::new([uri]'https://www.asrock.com/',$href)} catch {continue}
                    if($candidateUri.Scheme -eq 'https' -and $candidateUri.Host.ToLowerInvariant() -in @('asrock.com','www.asrock.com','pg.asrock.com','download.asrock.com')) {$packageUri=$candidateUri;break}
                }
                if($null -eq $packageUri){continue}
                $title=$description
                if($title.Length -gt 180){$title=$title.Substring(0,180)}
                $results.Add([pscustomobject]@{
                    CandidateId=('ASROCK-'+([guid]::NewGuid().ToString('N').Substring(0,10)));ProviderId='ASRock.DriverCatalog'
                    Title=('ASRock '+$matchedModel+' – '+$title);Name=('ASRock '+$matchedModel+' – '+$title)
                    Source='ASRock Official Latest Drivers Update';Manufacturer='ASRock';Model=$matchedModel
                    Version='Not supplied';DriverDate=$dateText;SourceAdapter='ASRockDriverCatalogMetadata';CandidateType='OfficialCatalogMetadata'
                    Url=$packageUri.AbsoluteUri;SupportUrl=$pageUrl;PackageUrl=$packageUri.AbsoluteUri
                    ExpectedHash='';HashAlgorithm='';ExpectedSize='';OS=$osText;Architecture='x64'
                    MatchConfidence='Exact ASRock motherboard model row; OS listing checked; package contents not inspected'
                    MatchReason=('Exact model match on ASRock public Latest Drivers Update page: '+$matchedModel+'. '+$description+'. Package size shown by vendor: '+$sizeText+'.')
                    SearchTerms=$matchedModel;ComparisonScore=43;ComparisonRank=0
                    IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$false
                    VerificationState='Official catalog metadata only. AMR has not downloaded, hashed, signature-checked or INF/CAT-validated this package.'
                    Capabilities=@('Discover','Search','GetDetails')
                    ProviderMetadata=[pscustomobject]@{Catalog='ASRock';ListingUrl=$pageUrl;VendorSize=$sizeText;MetadataOnly=$true;ExactModelMatch=$true}
                })
                $found++
                if($found -ge 100){break}
            }
            if($results.Count -gt 0) {
                @($results.ToArray()) | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $cachePath -Encoding UTF8 -ErrorAction SilentlyContinue
            }
        }
    } catch {$errors.Add('ASRock latest-driver catalog: '+[string]$_.Exception.Message)}
    return [pscustomobject]@{Results=@($results.ToArray());Errors=@($errors.ToArray());SourcesQueried=@('ASRock public Latest Drivers Update');MetadataOnly=$true}
}

function Get-AMRDirectVendorPackageCandidates {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[object]$OEMProfile)
    $results=New-Object 'System.Collections.Generic.List[object]'
    $errors=New-Object 'System.Collections.Generic.List[string]'
    $root=Join-Path (Join-Path $script:DownloadDir 'Drivers') '_VendorCatalogCache'
    if(-not(Test-Path -LiteralPath $root -PathType Container)){New-Item -ItemType Directory -Path $root -Force -ErrorAction Stop | Out-Null}
    $windows=[string]$script:DriverWindowsContext
    $osMajor=10; $osMinor=0
    $targetOs=''
    if($windows -match '(?i)Windows\s*11'){$targetOs='Windows 11';$osMajor=10;$osMinor=0}
    elseif($windows -match '(?i)Windows\s*10'){$targetOs='Windows 10';$osMajor=10;$osMinor=0}
    elseif($windows -match '(?i)Windows\s*Server\s*2022'){$targetOs='Windows Server 2022';$osMajor=10;$osMinor=0}
    $arch='amd64';if($windows -match '(?i)arm64'){$arch='arm64'}elseif($windows -match '(?i)x86|32-bit'){$arch='x86'}
    $modelNames=@([string]$Device.DeviceName,[string]$OEMProfile.ComputerModel,[string]$OEMProfile.ProductName,[string]$OEMProfile.SystemSKU,[string]$OEMProfile.ProductVersion) | ForEach-Object {([string]$_).Trim()} | Where-Object {$_ -and $_ -notmatch '(?i)to be filled|default string|unknown|system manufacturer'} | Select-Object -Unique
    $modelText=$modelNames -join ' '
    $systemIdCandidates=@()
    foreach($value in @([string]$OEMProfile.SystemSKU,[string]$OEMProfile.ProductVersion,[string]$OEMProfile.ProductName,[string]$OEMProfile.ComputerModel,[string]$OEMProfile.BoardProduct)){
        if($value -match '(?i)(?:^|\s)([0-9A-Z]{4})(?:\s|$)'){$systemIdCandidates+= $Matches[1].ToUpperInvariant()}
        foreach($idMatch in [regex]::Matches($value,'(?i)(?:^|_)([0-9A-Z]{4})(?=_|$)')){$systemIdCandidates+=$idMatch.Groups[1].Value.ToUpperInvariant()}
    }
    $systemIdCandidates=@($systemIdCandidates | Select-Object -Unique)
    $deviceVendor=Resolve-AMRDriverVendorName -Text ([string]$OEMProfile.OEMVendor)

    # Dell Driver Pack Catalog: digitally signed CAB with model/SystemID + OS metadata.
    if($deviceVendor -and $deviceVendor.Vendor -eq 'Dell' -and $targetOs -in @('Windows 10','Windows 11')){
        try{
            if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Downloading Dell official Driver Pack Catalog'}
            $cab=Join-Path $root 'Dell_DriverPackCatalog.cab';$xmlPath=Join-Path $root 'Dell_DriverPackCatalog.xml'
            $catalogUrl='https://downloads.dell.com/catalog/DriverPackCatalog.cab'
            $refresh=(-not(Test-Path -LiteralPath $cab -PathType Leaf))
            if(-not $refresh){$age=(Get-Date)-(Get-Item -LiteralPath $cab).LastWriteTime;$refresh=($age.TotalHours -ge 12)}
            if($refresh){$partial=$cab+'.download';if(Test-Path -LiteralPath $partial){Remove-Item -LiteralPath $partial -Force -ErrorAction SilentlyContinue};Invoke-WebRequest -Uri $catalogUrl -OutFile $partial -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop;if(-not(Test-Path -LiteralPath $partial -PathType Leaf) -or (Get-Item -LiteralPath $partial).Length -le 0 -or (Get-Item -LiteralPath $partial).Length -gt 250MB){throw 'Dell catalog download is empty or exceeds the 250 MB safety limit.'};Move-Item -LiteralPath $partial -Destination $cab -Force -ErrorAction Stop}
            $catalogSig=Get-AuthenticodeSignature -FilePath $cab -ErrorAction Stop
            if([string]$catalogSig.Status -ne 'Valid' -or -not $catalogSig.SignerCertificate){Remove-Item -LiteralPath $cab -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath $xmlPath -Force -ErrorAction SilentlyContinue;throw 'Dell Driver Pack Catalog CAB signature is not valid; catalog results were rejected.'}
            if(-not(Test-Path -LiteralPath $xmlPath -PathType Leaf) -or (Get-Item -LiteralPath $xmlPath).LastWriteTime -lt (Get-Item -LiteralPath $cab).LastWriteTime){
                $expanded=Join-Path $root 'Dell_Expanded';if(Test-Path -LiteralPath $expanded){Remove-Item -LiteralPath $expanded -Recurse -Force -ErrorAction SilentlyContinue};New-Item -ItemType Directory -Path $expanded -Force | Out-Null
                $expand=Join-Path $env:WINDIR 'System32\expand.exe';if(-not(Test-Path $expand)){throw 'Windows expand.exe is unavailable for the Dell catalog CAB.'}
                $expandOutput=& $expand $cab '-F:DriverPackCatalog.xml' $expanded 2>&1 | Out-String
                if([int]$LASTEXITCODE -ne 0){throw ('Dell catalog CAB extraction failed: '+$expandOutput.Trim())}
                $foundXml=Get-ChildItem -LiteralPath $expanded -Filter 'DriverPackCatalog.xml' -File -Recurse | Select-Object -First 1
                if(-not $foundXml){throw 'Dell DriverPackCatalog.xml was not present in the signed catalog CAB.'}
                Copy-Item -LiteralPath $foundXml.FullName -Destination $xmlPath -Force
            }
            [xml]$doc=Get-Content -LiteralPath $xmlPath -Raw -ErrorAction Stop
            $packages=@($doc.DriverPackManifest.DriverPackage)
            foreach($pkg in $packages){
                if([string]$pkg.type -match '(?i)WinPE'){continue}
                $models=@($pkg.SupportedSystems.Brand.Model)
                $modelMatches=@($models | Where-Object {
                    $sid=[string]$_.systemID;$name=[string]$_.name
                    (($systemIdCandidates.Count -gt 0) -and ($systemIdCandidates -contains $sid.ToUpperInvariant())) -or
                    (($name -and $modelNames -contains $name))
                })
                if($modelMatches.Count -eq 0){continue}
                $osMatches=@($pkg.SupportedOperatingSystems.OperatingSystem | Where-Object {
                    $major=0;$minor=0;[void][int]::TryParse([string]$_.majorVersion,[ref]$major);[void][int]::TryParse([string]$_.minorVersion,[ref]$minor)
                    $osLabel=@([string]$_.name,[string]$_.osName,[string]$_.description) -join ' '
                    (($major -eq $osMajor -and $minor -eq $osMinor) -or ($major -eq 0 -and $minor -eq 0)) -and ([string]$_.osArch -match ('(?i)'+[regex]::Escape($arch)+'|x64|64')) -and ((-not $osLabel.Trim()) -or ($targetOs -and $osLabel -match ('(?i)'+[regex]::Escape($targetOs))))
                })
                if($osMatches.Count -eq 0){continue}
                $base=[string]$doc.DriverPackManifest.baseLocation
                $relative=[string]$pkg.path
                if([string]::IsNullOrWhiteSpace($base) -or [string]::IsNullOrWhiteSpace($relative)){continue}
                $packageUrl=([uri]::new([uri]$base,$relative)).AbsoluteUri
                if(([uri]$packageUrl).Scheme -ne 'https' -or ([uri]$packageUrl).Host -notin @('downloads.dell.com','ftp.dell.com')){continue}
                $matchedModel=@($modelMatches | ForEach-Object {[string]$_.name} | Select-Object -Unique) -join '; '
                $results.Add([pscustomobject]@{Title=('Dell Driver Pack – '+$matchedModel);Name=('Dell Driver Pack – '+$matchedModel);Source='Dell';Manufacturer='Dell';Model=$matchedModel;Version=[string]$pkg.dellVersion;DriverDate=[string]$pkg.dateTime;PackageUrl=$packageUrl;Url=$packageUrl;SourceAdapter='DellDriverPackCatalog';PackageType='OEMDriverPack';PackageFormat=[string]$pkg.format;ExpectedHash=[string]$pkg.hashMD5;HashAlgorithm='MD5';ExpectedSize=[int64]$pkg.size;ReleaseId=[string]$pkg.releaseID;SystemIds=@($modelMatches | ForEach-Object {[string]$_.systemID} | Select-Object -Unique);OS=$targetOs;Architecture=$arch;MatchConfidence='Exact Dell SystemID / model + OS catalog match';MatchReason=('Dell signed Driver Pack Catalog exact model match: '+$matchedModel);ComparisonScore=80;ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$true;VerificationState='Official Dell package listed in signed catalog; payload download/signature/hash verification pending';SearchTerms=($modelText+' '+($systemIdCandidates -join ' '));CatalogSigner=[string]$catalogSig.SignerCertificate.Subject;CatalogSignatureStatus=[string]$catalogSig.Status})
            }
        }catch{if($cab -and (Test-Path -LiteralPath ($cab+'.download'))){Remove-Item -LiteralPath ($cab+'.download') -Force -ErrorAction SilentlyContinue};$errors.Add(('Dell adapter: '+[string]$_.Exception.Message))}
    }

    # HP Client Driver Pack Catalog: SoftPaq packages mapped to product OS driver packs.
    if($deviceVendor -and $deviceVendor.Vendor -eq 'HP' -and $targetOs -in @('Windows 10','Windows 11')){
        try{
            if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Downloading HP official Client Driver Pack Catalog'}
            $cab=Join-Path $root 'HP_ClientDriverPackCatalog.cab';$xmlPath=Join-Path $root 'HP_ClientDriverPackCatalog.xml';$catalogUrl='https://hpia.hpcloud.hp.com/downloads/driverpackcatalog/HPClientDriverPackCatalog.cab'
            $refresh=(-not(Test-Path -LiteralPath $cab -PathType Leaf));if(-not $refresh){$age=(Get-Date)-(Get-Item -LiteralPath $cab).LastWriteTime;$refresh=($age.TotalHours -ge 12)}
            if($refresh){$partial=$cab+'.download';if(Test-Path -LiteralPath $partial){Remove-Item -LiteralPath $partial -Force -ErrorAction SilentlyContinue};Invoke-WebRequest -Uri $catalogUrl -OutFile $partial -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop;if(-not(Test-Path -LiteralPath $partial -PathType Leaf) -or (Get-Item -LiteralPath $partial).Length -le 0 -or (Get-Item -LiteralPath $partial).Length -gt 250MB){throw 'HP catalog download is empty or exceeds the 250 MB safety limit.'};Move-Item -LiteralPath $partial -Destination $cab -Force -ErrorAction Stop}
            $expand=Join-Path $env:WINDIR 'System32\expand.exe';if(-not(Test-Path $expand)){throw 'Windows expand.exe is unavailable for the HP catalog CAB.'}
            if(-not(Test-Path -LiteralPath $xmlPath -PathType Leaf) -or (Get-Item -LiteralPath $xmlPath).LastWriteTime -lt (Get-Item -LiteralPath $cab).LastWriteTime){
                $expanded=Join-Path $root 'HP_Expanded';if(Test-Path -LiteralPath $expanded){Remove-Item -LiteralPath $expanded -Recurse -Force -ErrorAction SilentlyContinue};New-Item -ItemType Directory -Path $expanded -Force | Out-Null
                $expandOutput=& $expand $cab $expanded 2>&1 | Out-String;if([int]$LASTEXITCODE -ne 0){throw ('HP catalog CAB extraction failed: '+$expandOutput.Trim())}
                $foundXml=Get-ChildItem -LiteralPath $expanded -Filter '*.xml' -File -Recurse | Select-Object -First 1;if(-not $foundXml){throw 'HP Client Driver Pack catalog XML was not found in the CAB.'};Copy-Item -LiteralPath $foundXml.FullName -Destination $xmlPath -Force
            }
            if((Get-Item -LiteralPath $xmlPath).Length -gt 150MB){throw 'HP Client Driver Pack catalog exceeded the 150 MB safety limit.'}
            [xml]$doc=Get-Content -LiteralPath $xmlPath -Raw -ErrorAction Stop
            $catalogRoot=$doc.NewDataSet.HPClientDriverPackCatalog;if(-not $catalogRoot){throw 'HP Client Driver Pack catalog XML has an unexpected schema.'}
            $softPaqs=@($catalogRoot.SoftPaqList.SoftPaq);$driverPacks=@($catalogRoot.ProductOSDriverPackList.ProductOSDriverPack)
            foreach($pack in $driverPacks){
                $systemIds=@(([string]$pack.SystemId) -split ',') | ForEach-Object {$_.Trim().ToUpperInvariant()} | Where-Object {$_}
                $modelName=[string]$pack.SystemName
                $modelMatch=($systemIds | Where-Object {$systemIdCandidates -contains $_} | Select-Object -First 1)
                if(-not $modelMatch -and $modelName){foreach($known in $modelNames){if($known -and $modelName.Equals($known,[StringComparison]::OrdinalIgnoreCase)){$modelMatch='Exact model name';break}}}
                if(-not $modelMatch){continue}
                $hpPackFamily=if($modelName -match '(?i)\bZBook\b'){'ZBook'}elseif($modelName -match '(?i)\bVictus\b'){'Victus'}else{[string]$OEMProfile.HPProductFamily}
                $osName=[string]$pack.OSName
                if($targetOs -notin @('Windows 10','Windows 11') -or $osName -notmatch ('(?i)'+[regex]::Escape($targetOs))){continue}
                if($arch -ne 'amd64'){continue}
                $softPaq=@($softPaqs | Where-Object {[string]$_.Id -eq [string]$pack.SoftPaqId} | Select-Object -First 1)
                if($softPaq.Count -eq 0){continue};$soft=$softPaq[0]
                $packageUrl=[string]$soft.Url;$uri=$null;if(-not [uri]::TryCreate($packageUrl,[UriKind]::Absolute,[ref]$uri)){continue}
                if($uri.Scheme -ne 'https' -or $uri.Host -notin @('ftp.hp.com','hpia.hpcloud.hp.com')){continue}
                $results.Add([pscustomobject]@{Title=('HP Driver Pack – '+$modelName+' – '+[string]$pack.SoftPaqId);Name=('HP Driver Pack – '+$modelName);Source='HP';Manufacturer='HP';Model=$modelName;Version=[string]$pack.OSName;DriverDate=[string]$soft.DateReleased;PackageUrl=$packageUrl;Url=$packageUrl;SourceAdapter='HPDriverPackCatalog';PackageType='OEMDriverPack';PackageFormat='EXE';ExpectedHash=[string]$soft.MD5;HashAlgorithm='MD5';ExpectedSize=0L;ReleaseId=[string]$pack.SoftPaqId;SystemIds=@($systemIds);OS=$osName;Architecture=$arch;MatchConfidence='Exact HP SystemId / model + OS catalog match';MatchReason=('HP Client Driver Pack Catalog exact product mapping: '+$modelName+' / SoftPaq '+[string]$pack.SoftPaqId+'; family '+$hpPackFamily);ComparisonScore=$(if($hpPackFamily -eq 'ZBook'){95}else{80});ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$true;VerificationState='Official HP SoftPaq mapped by HP product/OS catalog; payload download/hash/signature verification pending';SearchTerms=($modelText+' '+($systemIds -join ' '));CatalogSigner='HP official HTTPS catalog; CAB signature not independently asserted';HPProductFamily=$hpPackFamily;ProviderMetadata=[pscustomobject]@{Catalog='HP Client Driver Pack Catalog';ProductFamily=$hpPackFamily;SystemIds=@($systemIds);OS=$osName;SoftPaqId=[string]$pack.SoftPaqId;ExactSystemIdMatch=([bool]$modelMatch -and $modelMatch -ne 'Exact model name')}})
            }
        }catch{if($cab -and (Test-Path -LiteralPath ($cab+'.download'))){Remove-Item -LiteralPath ($cab+'.download') -Force -ErrorAction SilentlyContinue};$errors.Add(('HP adapter: '+[string]$_.Exception.Message))}
    }

    # HP HPIA platform reference catalog: individual model/OS-specific SoftPaq drivers.
    # This extends (and does not replace) the existing HP Client Driver Pack catalog.
    if($deviceVendor -and $deviceVendor.Vendor -eq 'HP' -and $targetOs -in @('Windows 10','Windows 11')){
        try{
            if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Resolving HP HPIA platform and individual driver SoftPaqs'}
            $hpiaRoot=Join-Path $root 'HP_HPIA'
            if(-not(Test-Path -LiteralPath $hpiaRoot -PathType Container)){New-Item -ItemType Directory -Path $hpiaRoot -Force -ErrorAction Stop | Out-Null}
            $expand=Join-Path $env:WINDIR 'System32\expand.exe'
            if(-not(Test-Path -LiteralPath $expand -PathType Leaf)){throw 'Windows expand.exe is unavailable for HP HPIA reference catalogs.'}

            # HPIA platform IDs are four hexadecimal characters. Keep every plausible
            # SMBIOS candidate until the official platform list confirms the exact ID.
            $platformId=''
            $platformIdCandidates=New-Object 'System.Collections.Generic.List[string]'
            if($OEMProfile -and ([string]$OEMProfile.BoardProduct -match '(?i)^\s*([0-9A-F]{4})\s*$')){$platformIdCandidates.Add($Matches[1].ToUpperInvariant())}
            foreach($candidateId in @($systemIdCandidates)){
                $candidatePlatformId=([string]$candidateId).Trim().ToUpperInvariant()
                if($candidatePlatformId -match '^[0-9A-F]{4}$' -and -not $platformIdCandidates.Contains($candidatePlatformId)){$platformIdCandidates.Add($candidatePlatformId)}
            }
            if($platformIdCandidates.Count -eq 0){throw 'HP HPIA discovery requires a four-character hexadecimal platform ID from SMBIOS BaseBoard Product / System ID.'}

            # Cache the official platform list; it defines which OS releases HP supports for this platform.
            $platformCab=Join-Path $hpiaRoot 'platformList.cab'
            $platformXml=Join-Path $hpiaRoot 'platformList.xml'
            $refreshPlatform=(-not(Test-Path -LiteralPath $platformCab -PathType Leaf))
            if(-not $refreshPlatform){$platformAge=(Get-Date)-(Get-Item -LiteralPath $platformCab).LastWriteTime;$refreshPlatform=($platformAge.TotalHours -ge 24)}
            if($refreshPlatform){
                $partialPlatform=$platformCab+'.download'
                if(Test-Path -LiteralPath $partialPlatform){Remove-Item -LiteralPath $partialPlatform -Force -ErrorAction SilentlyContinue}
                try{Invoke-WebRequest -Uri 'https://hpia.hpcloud.hp.com/ref/platformList.cab' -OutFile $partialPlatform -UseBasicParsing -TimeoutSec 90 -ErrorAction Stop}
                catch{
                    if(Test-Path -LiteralPath $partialPlatform){Remove-Item -LiteralPath $partialPlatform -Force -ErrorAction SilentlyContinue}
                    Invoke-WebRequest -Uri 'https://ftp.hp.com/pub/caps-softpaq/cmit/imagepal/ref/platformList.cab' -OutFile $partialPlatform -UseBasicParsing -TimeoutSec 90 -ErrorAction Stop
                }
                if(-not(Test-Path -LiteralPath $partialPlatform -PathType Leaf) -or (Get-Item -LiteralPath $partialPlatform).Length -le 0 -or (Get-Item -LiteralPath $partialPlatform).Length -gt 100MB){throw 'HP HPIA platform-list download is empty or exceeds the 100 MB safety limit.'}
                Move-Item -LiteralPath $partialPlatform -Destination $platformCab -Force -ErrorAction Stop
            }
            if(-not(Test-Path -LiteralPath $platformXml -PathType Leaf) -or (Get-Item -LiteralPath $platformXml).LastWriteTime -lt (Get-Item -LiteralPath $platformCab).LastWriteTime){
                if(Test-Path -LiteralPath $platformXml -PathType Leaf){Remove-Item -LiteralPath $platformXml -Force -ErrorAction SilentlyContinue}
                # expand.exe's documented single-file form avoids relying on folder extraction semantics.
                $platformExpandOutput=& $expand $platformCab $platformXml 2>&1 | Out-String
                if([int]$LASTEXITCODE -ne 0 -or -not(Test-Path -LiteralPath $platformXml -PathType Leaf)){throw ('HP HPIA platform-list CAB extraction failed: '+$platformExpandOutput.Trim())}
            }
            if((Get-Item -LiteralPath $platformXml).Length -gt 100MB){throw 'HP HPIA platform-list XML exceeded the 100 MB safety limit.'}
            [xml]$platformDoc=Get-Content -LiteralPath $platformXml -Raw -ErrorAction Stop
            if(-not $platformDoc.ImagePal.Platform){throw 'HP HPIA platform-list XML has an unexpected schema.'}
            $platformNode=$null
            foreach($candidatePlatformId in $platformIdCandidates){
                $platformMatches=@($platformDoc.ImagePal.Platform | Where-Object {[string]$_.SystemID -ieq $candidatePlatformId} | Select-Object -First 1)
                if($platformMatches.Count -gt 0){$platformId=[string]$platformMatches[0].SystemID;$platformNode=$platformMatches[0];break}
            }
            if(-not $platformNode){throw ('HP HPIA does not list any detected SMBIOS platform ID ('+($platformIdCandidates -join ', ')+'); the existing HP Client Driver Pack lookup remains available.')}

            $currentRelease=''
            try{$currentRelease=[string](Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop).DisplayVersion}catch{}
            if(-not $currentRelease){
                $currentBuild=0
                try{$osRecord=Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop;[void][int]::TryParse([string]$osRecord.BuildNumber,[ref]$currentBuild)}catch{}
                if($targetOs -eq 'Windows 11'){
                    if($currentBuild -ge 28000){$currentRelease='26H2'}elseif($currentBuild -ge 26200){$currentRelease='25H2'}elseif($currentBuild -ge 26100){$currentRelease='24H2'}elseif($currentBuild -ge 22631){$currentRelease='23H2'}elseif($currentBuild -ge 22000){$currentRelease='21H2'}
                }else{
                    if($currentBuild -ge 19045){$currentRelease='22H2'}elseif($currentBuild -ge 19044){$currentRelease='21H2'}elseif($currentBuild -ge 19043){$currentRelease='21H1'}elseif($currentBuild -ge 19042){$currentRelease='20H2'}elseif($currentBuild -ge 19041){$currentRelease='2004'}
                }
            }
            if([string]::IsNullOrWhiteSpace($currentRelease)){throw 'The installed Windows release (DisplayVersion) could not be resolved safely; HP HPIA results were not guessed from another release.'}
            $osNum=if($targetOs -eq 'Windows 11'){'11.0'}else{'10.0'}
            $platformOs=@($platformNode.OS | Where-Object {[string]$_.OSDescription -match ('(?i)'+[regex]::Escape($targetOs))})
            $matchingOs=@($platformOs | Where-Object {[string]$_.OSReleaseIdDisplay -ieq $currentRelease} | Select-Object -First 1)
            if($matchingOs.Count -eq 0){throw ('HP HPIA platform '+$platformId+' does not publish an exact '+$targetOs+' '+$currentRelease+' reference catalog. No cross-release driver substitution was made.')}
            $matchingOs=$matchingOs[0]
            $releaseId=[string]$matchingOs.OSReleaseIdDisplay
            $hpiaArch=switch($arch){'amd64'{'64'} 'x86'{'32'} default{''}}
            if(-not $hpiaArch){throw ('HP HPIA architecture '+$arch+' is not supported by this dedicated reference-catalog route.')}
            $platformLower=$platformId.ToLowerInvariant()
            $releaseLower=$releaseId.ToLowerInvariant()
            $hpiaCab=Join-Path $hpiaRoot ('{0}_{1}_{2}_{3}.cab' -f $platformLower,$hpiaArch,$osNum,$releaseLower)
            $hpiaXml=Join-Path $hpiaRoot ('{0}_{1}_{2}_{3}.xml' -f $platformLower,$hpiaArch,$osNum,$releaseLower)
            $hpiaUrl=('https://hpia.hpcloud.hp.com/ref/{0}/{0}_{1}_{2}.{3}.cab' -f $platformLower,$hpiaArch,$osNum,$releaseLower)
            $refreshHpia=(-not(Test-Path -LiteralPath $hpiaCab -PathType Leaf))
            if(-not $refreshHpia){$hpiaAge=(Get-Date)-(Get-Item -LiteralPath $hpiaCab).LastWriteTime;$refreshHpia=($hpiaAge.TotalHours -ge 12)}
            if($refreshHpia){
                $partialHpia=$hpiaCab+'.download'
                if(Test-Path -LiteralPath $partialHpia){Remove-Item -LiteralPath $partialHpia -Force -ErrorAction SilentlyContinue}
                try{Invoke-WebRequest -Uri $hpiaUrl -OutFile $partialHpia -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop}
                catch{
                    if(Test-Path -LiteralPath $partialHpia){Remove-Item -LiteralPath $partialHpia -Force -ErrorAction SilentlyContinue}
                    $fallbackHpiaUrl=('https://ftp.hp.com/pub/caps-softpaq/cmit/imagepal/ref/{0}/{0}_{1}_{2}.{3}.cab' -f $platformLower,$hpiaArch,$osNum,$releaseLower)
                    Invoke-WebRequest -Uri $fallbackHpiaUrl -OutFile $partialHpia -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop
                }
                if(-not(Test-Path -LiteralPath $partialHpia -PathType Leaf) -or (Get-Item -LiteralPath $partialHpia).Length -le 0 -or (Get-Item -LiteralPath $partialHpia).Length -gt 200MB){throw 'HP HPIA platform reference CAB is empty or exceeds the 200 MB safety limit.'}
                Move-Item -LiteralPath $partialHpia -Destination $hpiaCab -Force -ErrorAction Stop
            }
            if(-not(Test-Path -LiteralPath $hpiaXml -PathType Leaf) -or (Get-Item -LiteralPath $hpiaXml).LastWriteTime -lt (Get-Item -LiteralPath $hpiaCab).LastWriteTime){
                if(Test-Path -LiteralPath $hpiaXml -PathType Leaf){Remove-Item -LiteralPath $hpiaXml -Force -ErrorAction SilentlyContinue}
                # HP's reference CAB contains one XML file; expand directly to its cache path.
                $hpiaExpandOutput=& $expand $hpiaCab $hpiaXml 2>&1 | Out-String
                if([int]$LASTEXITCODE -ne 0 -or -not(Test-Path -LiteralPath $hpiaXml -PathType Leaf)){throw ('HP HPIA platform reference CAB extraction failed: '+$hpiaExpandOutput.Trim())}
            }
            if((Get-Item -LiteralPath $hpiaXml).Length -gt 150MB){throw 'HP HPIA platform reference XML exceeded the 150 MB safety limit.'}
            [xml]$hpiaDoc=Get-Content -LiteralPath $hpiaXml -Raw -ErrorAction Stop
            if(-not $hpiaDoc.ImagePal.Solutions){throw 'HP HPIA platform reference XML has an unexpected schema.'}
            $hpiaUpdates=@($hpiaDoc.ImagePal.Solutions.UpdateInfo)
            if($hpiaUpdates.Count -eq 0){throw 'HP HPIA platform reference XML contains no SoftPaq update records.'}

            $hpModelName=[string]$OEMProfile.ComputerModel
            if(-not $hpModelName){$hpModelName=[string]$OEMProfile.ProductName}
            if(-not $hpModelName){$hpModelName=[string]$OEMProfile.SystemSKU}
            if(-not $hpModelName){$hpModelName=('HP platform '+$platformId)}
            $hpPlatformName=$hpModelName
            try{$platformNameNode=$platformNode.SelectSingleNode('SystemName');if($platformNameNode){$hpPlatformName=[string]$platformNameNode.InnerText}}catch{}
            $hpPlatformEvidenceText=(@($hpModelName,$hpPlatformName,[string]$OEMProfile.ProductName,[string]$OEMProfile.ProductVersion,[string]$OEMProfile.SystemSKU,[string]$OEMProfile.ComputerModel) | Where-Object {$_}) -join ' '
            $isZBookPlatform=($hpPlatformEvidenceText -match '(?i)\bZBook\b')
            $isVictusPlatform=($hpPlatformEvidenceText -match '(?i)\bVictus\b')
            $hpProductFamily=if($isZBookPlatform){'ZBook'}elseif($isVictusPlatform){'Victus'}else{[string]$OEMProfile.HPProductFamily}
            $deviceEvidenceParts=@([string]$Device.DeviceName,[string]$Device.DeviceClass,[string]$Device.Manufacturer)+@($Device.HardwareIds)+@($Device.CompatibleIds)
            $deviceEvidenceText=$deviceEvidenceParts -join ' '
            $isFingerprintTarget=([string]$Device.DeviceClass -match '(?i)Biometric') -or ($deviceEvidenceText -match '(?i)fingerprint|biometric|validity|synaptics|goodix|elan|USB\\VID_(06CB|27C6|04F3|138A)')
            $seenHpSoftPaqIds=@{}
            foreach($existingHpCandidate in @($results.ToArray())){
                $existingId=[string]$existingHpCandidate.ReleaseId
                if($existingId){$seenHpSoftPaqIds[$existingId.ToLowerInvariant()]=$true}
            }
            $hpAdded=0
            # Read optional XML elements without relying on adapted-property presence under StrictMode.
            $readHpiaNodeText={param($node,[string]$nodeName)$child=$node.SelectSingleNode($nodeName);if($child){[string]$child.InnerText}else{''}}
            foreach($update in $hpiaUpdates){
                $softpaqId=([string](& $readHpiaNodeText $update 'Id')).Trim()
                if($softpaqId -notmatch '(?i)^sp[0-9]{4,7}$'){continue}
                if($seenHpSoftPaqIds.ContainsKey($softpaqId.ToLowerInvariant())){continue}
                $softpaqName=[string](& $readHpiaNodeText $update 'Name')
                $category=[string](& $readHpiaNodeText $update 'Category')
                $description=[string](& $readHpiaNodeText $update 'Description')
                $packageText=($softpaqName+' '+$category+' '+$description)
                if($category -notmatch '(?i)driver' -and $softpaqName -notmatch '(?i)driver|fingerprint|biometric'){continue}
                if($category -match '(?i)BIOS|Firmware|Utility|Application|Software'){continue}
                $packageUrl=[string](& $readHpiaNodeText $update 'Url')
                if($packageUrl -match '(?i)^http://'){$packageUrl='https://'+$packageUrl.Substring(7)}elseif($packageUrl -match '(?i)^ftp://'){$packageUrl='https://'+$packageUrl.Substring(6)}elseif($packageUrl -and $packageUrl -notmatch '(?i)^https://'){$packageUrl='https://'+$packageUrl.TrimStart('/')}
                $packageUri=$null
                if(-not [uri]::TryCreate($packageUrl,[UriKind]::Absolute,[ref]$packageUri)){continue}
                if($packageUri.Scheme -ne 'https' -or $packageUri.Host.ToLowerInvariant() -ne 'ftp.hp.com'){continue}

                $cvaUrl=[string](& $readHpiaNodeText $update 'CvaUrl')
                if(-not $cvaUrl){$cvaUrl=[string](& $readHpiaNodeText $update 'Metadata')}
                if($cvaUrl -match '(?i)^http://'){$cvaUrl='https://'+$cvaUrl.Substring(7)}elseif($cvaUrl -match '(?i)^ftp://'){$cvaUrl='https://'+$cvaUrl.Substring(6)}elseif($cvaUrl -and $cvaUrl -notmatch '(?i)^https://'){$cvaUrl='https://'+$cvaUrl.TrimStart('/')}
                $cvaUri=$null
                if(-not [string]::IsNullOrWhiteSpace($cvaUrl) -and [uri]::TryCreate($cvaUrl,[UriKind]::Absolute,[ref]$cvaUri) -and $cvaUri.Scheme -eq 'https' -and $cvaUri.Host.ToLowerInvariant() -eq 'ftp.hp.com'){$cvaUrl=$cvaUri.AbsoluteUri}else{$cvaUrl=''}

                $expectedHash='';$hashAlgorithm=''
                $shaValue=([string](& $readHpiaNodeText $update 'SHA256')).Trim()
                $md5Value=([string](& $readHpiaNodeText $update 'MD5')).Trim()
                if($shaValue -match '^[A-Fa-f0-9]{64}$'){$expectedHash=$shaValue.ToUpperInvariant();$hashAlgorithm='SHA256'}
                elseif($md5Value -match '^[A-Fa-f0-9]{32}$'){$expectedHash=$md5Value.ToUpperInvariant();$hashAlgorithm='MD5'}
                $expectedSize=[int64]0
                [void][int64]::TryParse([string](& $readHpiaNodeText $update 'Size'),[ref]$expectedSize)
                $releaseDate=[string](& $readHpiaNodeText $update 'DateReleased')
                $version=[string](& $readHpiaNodeText $update 'Version')
                if(-not $version){$version='Not supplied by HP catalog'}
                $hpReleaseType=[string](& $readHpiaNodeText $update 'ReleaseType')

                # For biometric packages only, retrieve the small official CVA metadata file.
                # This supplies an additional checksum and platform support evidence when HP publishes it.
                if($cvaUrl -and $packageText -match '(?i)fingerprint|biometric|WBF' -and ($expectedHash -eq '' -or $isFingerprintTarget)){
                    $cvaFile=''
                    try{
                        $cvaCache=Join-Path $hpiaRoot 'CVA'
                        if(-not(Test-Path -LiteralPath $cvaCache -PathType Container)){New-Item -ItemType Directory -Path $cvaCache -Force | Out-Null}
                        $cvaFile=Join-Path $cvaCache ($softpaqId.ToLowerInvariant()+'.cva')
                        $refreshCva=(-not(Test-Path -LiteralPath $cvaFile -PathType Leaf))
                        if(-not $refreshCva){$cvaAge=(Get-Date)-(Get-Item -LiteralPath $cvaFile).LastWriteTime;$refreshCva=($cvaAge.TotalDays -ge 7)}
                        if($refreshCva){
                            $cvaPartial=$cvaFile+'.download'
                            if(Test-Path -LiteralPath $cvaPartial){Remove-Item -LiteralPath $cvaPartial -Force -ErrorAction SilentlyContinue}
                            Invoke-WebRequest -Uri $cvaUrl -OutFile $cvaPartial -UseBasicParsing -TimeoutSec 25 -ErrorAction Stop
                            if((Test-Path -LiteralPath $cvaPartial -PathType Leaf) -and (Get-Item -LiteralPath $cvaPartial).Length -gt 0 -and (Get-Item -LiteralPath $cvaPartial).Length -le 2MB){Move-Item -LiteralPath $cvaPartial -Destination $cvaFile -Force -ErrorAction Stop}else{Remove-Item -LiteralPath $cvaPartial -Force -ErrorAction SilentlyContinue}
                        }
                        if(Test-Path -LiteralPath $cvaFile -PathType Leaf){
                            $cvaText=Get-Content -LiteralPath $cvaFile -Raw -ErrorAction Stop
                            if(-not $expectedHash){
                                $cvaSha=[regex]::Match($cvaText,'(?im)^\s*SoftPaqSHA256\s*=\s*([A-Fa-f0-9]{64})\s*$')
                                $cvaMd5=[regex]::Match($cvaText,'(?im)^\s*SoftPaqMD5\s*=\s*([A-Fa-f0-9]{32})\s*$')
                                if($cvaSha.Success){$expectedHash=$cvaSha.Groups[1].Value.ToUpperInvariant();$hashAlgorithm='SHA256'}elseif($cvaMd5.Success){$expectedHash=$cvaMd5.Groups[1].Value.ToUpperInvariant();$hashAlgorithm='MD5'}
                            }
                            $cvaSystemIds=@([regex]::Matches($cvaText,'(?im)^\s*SysId\d+\s*=\s*(?:0x)?([A-Fa-f0-9]{4})\s*$') | ForEach-Object {$_.Groups[1].Value.ToUpperInvariant()} | Select-Object -Unique)
                            if($cvaSystemIds.Count -gt 0 -and $cvaSystemIds -notcontains $platformId){continue}
                        }
                    }catch{if($cvaFile -and (Test-Path -LiteralPath ($cvaFile+'.download'))){Remove-Item -LiteralPath ($cvaFile+'.download') -Force -ErrorAction SilentlyContinue}}
                }

                $relevanceScore=15
                $relevanceReason='Exact HP platform and Windows release catalog match; device-specific INF Hardware ID applicability remains to be verified.'
                if($isZBookPlatform){$relevanceScore=30;$relevanceReason='Exact HP ZBook platform and Windows release match from the official HPIA reference catalog; device-specific INF Hardware ID applicability remains to be verified.'}
                if($isFingerprintTarget -and $packageText -match '(?i)fingerprint|biometric|WBF'){$relevanceScore=210;$relevanceReason='High-priority biometric candidate: selected device name/class/Hardware IDs indicate a fingerprint sensor. The downloaded INF must still match the exact Hardware ID.'}
                elseif($isZBookPlatform -and $packageText -match '(?i)fingerprint|biometric|WBF'){$relevanceScore=135;$relevanceReason='ZBook platform-specific biometric SoftPaq candidate; confirm the fingerprint reader is present and the downloaded INF matches its exact Hardware ID.'}
                elseif([string]$Device.DeviceClass -match '(?i)^Net$' -and $packageText -match '(?i)network|ethernet|wireless|WLAN|Bluetooth'){$relevanceScore=85;$relevanceReason='HP platform driver category is relevant to the selected network-class device; exact INF match remains pending.'}
                elseif([string]$Device.DeviceClass -match '(?i)Display' -and $packageText -match '(?i)graphics|display|video|GPU'){$relevanceScore=85;$relevanceReason='HP platform driver category is relevant to the selected display-class device; exact INF match remains pending.'}
                elseif([string]$Device.DeviceClass -match '(?i)MEDIA' -and $packageText -match '(?i)audio|sound|codec'){$relevanceScore=85;$relevanceReason='HP platform driver category is relevant to the selected audio-class device; exact INF match remains pending.'}
                elseif([string]$Device.DeviceClass -match '(?i)USB|HIDClass|Keyboard|Mouse' -and $packageText -match '(?i)USB|input|keyboard|mouse|touchpad|fingerprint|biometric'){$relevanceScore=75;$relevanceReason='HP platform driver category is relevant to the selected input/USB-class device; exact INF match remains pending.'}
                if($hpReleaseType -match '(?i)Critical'){$relevanceScore+=15}elseif($hpReleaseType -match '(?i)Recommended'){$relevanceScore+=8}

                $matchReason=('HP HPIA official platform reference match: platform '+$platformId+' ('+$hpPlatformName+'), '+$targetOs+' '+$releaseId+', SoftPaq '+$softpaqId+', category '+$category+'. '+$relevanceReason)
                $searchTerms=(@($hpModelName,$hpPlatformName,$platformId,[string]$Device.DeviceName,[string]$Device.DeviceClass,$softpaqId,$softpaqName,$category,$description,@($Device.HardwareIds),@($Device.CompatibleIds)) | ForEach-Object {if($_ -is [array]){$_ -join ' '}else{[string]$_}} | Where-Object {$_}) -join ' '
                $results.Add([pscustomobject]@{
                    CandidateId=('HP-HPIA-'+$softpaqId.ToUpperInvariant());ProviderId='HP.ClientDriverPackCatalog'
                    Title=('HP '+$category+' – '+$softpaqName+' ('+$softpaqId.ToUpperInvariant()+')');Name=$softpaqName
                    Source='HP HPIA Platform Reference Catalog';Manufacturer='HP';Model=$hpModelName
                    Version=$version;DriverDate=$releaseDate;PackageUrl=$packageUri.AbsoluteUri;Url=$packageUri.AbsoluteUri
                    SourceAdapter='HPDriverPackCatalog';CandidateType='HPIASoftPaq';PackageType='HP Individual SoftPaq';PackageFormat='EXE'
                    ExpectedHash=$expectedHash;HashAlgorithm=$hashAlgorithm;ExpectedSize=$expectedSize;ReleaseId=$softpaqId.ToLowerInvariant()
                    SystemIds=@($platformId);OS=($targetOs+' '+$releaseId);Architecture=$arch
                    MatchConfidence='HP platform/OS catalog match; device-specific INF match pending'
                    MatchReason=$matchReason;ComparisonScore=80;ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$true
                    VerificationState='Official HP HPIA platform-scoped SoftPaq. Package SHA-256/MD5 and HP Authenticode signature verification are pending; INF/CAT and exact device Hardware ID validation are not yet performed.'
                    SearchTerms=$searchTerms;CatalogSigner='HP official HTTPS HPIA metadata; SoftPaq publisher verification pending'
                    HPCatalogType='HPIASoftPaq';HPCategory=$category;HPDescription=$description;HPPlatformId=$platformId;HPPlatformName=$hpPlatformName;HPProductFamily=$hpProductFamily
                    HPIAOSRelease=$releaseId;HPIACvaUrl=$cvaUrl;HPReleaseNotesUrl=[string](& $readHpiaNodeText $update 'ReleaseNotesUrl');HPReleaseType=$hpReleaseType;HPZBookPlatform=$isZBookPlatform;HPVictusPlatform=$isVictusPlatform
                    HPRelevanceScore=$relevanceScore;HPRelevanceReason=$relevanceReason
                    ProviderMetadata=[pscustomobject]@{Catalog='HP HPIA Platform Reference Catalog';PlatformId=$platformId;PlatformName=$hpPlatformName;ProductFamily=$hpProductFamily;OS=$targetOs;OSRelease=$releaseId;SoftPaqId=$softpaqId;Category=$category;ReleaseType=$hpReleaseType;CvaUrl=$cvaUrl;MetadataOnly=$false;DeviceSpecificInfMatchPending=$true}
                    Capabilities=@('Discover','Search','Match','GetDetails','ResolveDownload','Acquire','Verify')
                })
                $seenHpSoftPaqIds[$softpaqId.ToLowerInvariant()]=$true
                $hpAdded++
                if($hpAdded -ge 1000){break}
            }
            if($hpAdded -gt 0 -and (Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue)){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage ('HP HPIA found {0} individual driver SoftPaq candidate(s) for platform {1} / {2} {3}' -f $hpAdded,$platformId,$targetOs,$releaseId)}
            if($hpAdded -eq 0){$errors.Add(('HP HPIA platform '+$platformId+' / '+$targetOs+' '+$releaseId+' returned no additional individual driver SoftPaqs; existing HP Client Driver Pack results were retained.'))}
        }catch{$errors.Add(('HP HPIA SoftPaq adapter: '+[string]$_.Exception.Message))}
    }

    # Lenovo CDRT public catalog: model/SystemType-specific SCCM driver packs.
    if($deviceVendor -and $deviceVendor.Vendor -eq 'Lenovo' -and $targetOs -in @('Windows 10','Windows 11')){
        try{
            if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Downloading Lenovo official CDRT driver-pack catalog'}
            $xmlPath=Join-Path $root 'Lenovo_CDRT_catalogv2.xml';$catalogUrl='https://download.lenovo.com/cdrt/td/catalogv2.xml'
            $refresh=(-not(Test-Path -LiteralPath $xmlPath -PathType Leaf));if(-not $refresh){$age=(Get-Date)-(Get-Item -LiteralPath $xmlPath).LastWriteTime;$refresh=($age.TotalHours -ge 12)}
            if($refresh){$partial=$xmlPath+'.download';if(Test-Path -LiteralPath $partial){Remove-Item -LiteralPath $partial -Force -ErrorAction SilentlyContinue};Invoke-WebRequest -Uri $catalogUrl -OutFile $partial -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop;if(-not(Test-Path -LiteralPath $partial -PathType Leaf) -or (Get-Item -LiteralPath $partial).Length -le 0 -or (Get-Item -LiteralPath $partial).Length -gt 100MB){throw 'Lenovo CDRT catalog is empty or exceeds the 100 MB safety limit.'};[xml]$validation=Get-Content -LiteralPath $partial -Raw -ErrorAction Stop;if(-not $validation.ModelList.Model){throw 'Lenovo CDRT catalog XML has an unexpected schema.'};Move-Item -LiteralPath $partial -Destination $xmlPath -Force -ErrorAction Stop}
            if((Get-Item -LiteralPath $xmlPath).Length -gt 100MB){throw 'Lenovo CDRT catalog exceeded the 100 MB safety limit.'}
            [xml]$doc=Get-Content -LiteralPath $xmlPath -Raw -ErrorAction Stop
            foreach($model in @($doc.ModelList.Model)){
                $modelName=[string]$model.name
                $types=@($model.Types.Type | ForEach-Object {[string]$_ -split ','} | ForEach-Object {$_.Trim().ToUpperInvariant()} | Where-Object {$_})
                $modelMatch=$false
                foreach($id in $systemIdCandidates){if($types -contains $id){$modelMatch=$true}}
                if(-not $modelMatch -and $modelName){foreach($known in $modelNames){if($known -and $modelName.Equals($known,[StringComparison]::OrdinalIgnoreCase)){$modelMatch=$true;break}}}
                if(-not $modelMatch){continue}
                foreach($item in @($model.SCCM)){
                    $osName=[string]$item.os;if($osName -notin @('win10','win11')){continue}
                    if(($targetOs -eq 'Windows 11' -and $osName -ne 'win11') -or ($targetOs -eq 'Windows 10' -and $osName -ne 'win10') -or [string]::IsNullOrWhiteSpace($targetOs)){continue}
                    $url=[string]$item.'#text';if([string]::IsNullOrWhiteSpace($url)){continue}
                    $uri=$null;if(-not [uri]::TryCreate($url,[UriKind]::Absolute,[ref]$uri)){continue}
                    if($uri.Scheme -ne 'https' -or $uri.Host -notin @('download.lenovo.com')){continue}
                    $displayOs=if($osName -eq 'win11'){'Windows 11'}else{'Windows 10'}
                    $results.Add([pscustomobject]@{Title=('Lenovo Driver Pack – '+$modelName);Name=('Lenovo Driver Pack – '+$modelName);Source='Lenovo';Manufacturer='Lenovo';Model=$modelName;Version=[string]$item.version;DriverDate=[string]$item.date;PackageUrl=$url;Url=$url;SourceAdapter='LenovoCDRTDriverPackCatalog';PackageType='OEMDriverPack';PackageFormat='EXE';ExpectedHash=[string]$item.crc;HashAlgorithm='MD5';ExpectedSize=0L;ReleaseId=[IO.Path]::GetFileName($uri.AbsolutePath);SystemIds=@($types);OS=$displayOs;Architecture='amd64';MatchConfidence='Exact Lenovo Machine Type / model catalog match';MatchReason=('Lenovo CDRT SCCM driver pack for exact model '+$modelName+' ('+($types -join ', ')+')');ComparisonScore=80;ComparisonRank=0;IsDownloaded=$false;IsInstallable=$false;IsDownloadable=$true;VerificationState='Official Lenovo CDRT package listed in public catalog; payload download/signature/hash verification pending';SearchTerms=($modelText+' '+($types -join ' '))})
                }
            }
        }catch{if($xmlPath -and (Test-Path -LiteralPath ($xmlPath+'.download'))){Remove-Item -LiteralPath ($xmlPath+'.download') -Force -ErrorAction SilentlyContinue};$errors.Add(('Lenovo adapter: '+[string]$_.Exception.Message))}
    }
    $dedup=@{};$unique=New-Object 'System.Collections.Generic.List[object]'
    foreach($candidate in $results){$key=([string]$candidate.SourceAdapter+'|'+[string]$candidate.PackageUrl).ToLowerInvariant();if(-not $dedup.ContainsKey($key)){$dedup[$key]=$true;$unique.Add($candidate)}}
    $ordered=@($unique | Sort-Object @{Expression={if($_.PSObject.Properties['HPCatalogType'] -and [string]$_.HPCatalogType -eq 'HPIASoftPaq'){[int]$_.HPRelevanceScore}elseif($_.MatchConfidence -like 'Exact*'){100}else{0}};Descending=$true},@{Expression='Source'},@{Expression='DriverDate';Descending=$true})
    $rank=0;foreach($candidate in $ordered){$rank++;$candidate.ComparisonRank=$rank}
    return [pscustomobject]@{Results=@($ordered);Errors=@($errors.ToArray());SourcesQueried=@('Dell Driver Pack Catalog','HP Client Driver Pack Catalog','HP HPIA Platform Reference Catalog','Lenovo CDRT Driver Pack Catalog');PackageCandidateCount=$ordered.Count;CatalogOnly=$true}
}

function Invoke-AMRVendorPackageAcquisition {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][object]$Candidate)
    $adapter=[string]$Candidate.SourceAdapter
    $allowedHosts=switch($adapter){'DellDriverPackCatalog' {@('downloads.dell.com','ftp.dell.com')} 'HPDriverPackCatalog' {@('ftp.hp.com','hpia.hpcloud.hp.com')} 'LenovoCDRTDriverPackCatalog' {@('download.lenovo.com')} default {throw 'Unsupported vendor package adapter.'}}
    $url=[string]$Candidate.PackageUrl;$uri=$null
    if(-not [uri]::TryCreate($url,[UriKind]::Absolute,[ref]$uri) -or $uri.Scheme -ne 'https' -or $uri.Host -notin $allowedHosts){throw 'Vendor package URL failed HTTPS host allowlist validation.'}
    $root=Join-Path (Join-Path $script:DownloadDir 'Drivers') 'VendorPackages';if(-not(Test-Path -LiteralPath $root -PathType Container)){New-Item -ItemType Directory -Path $root -Force | Out-Null}
    $safeDevice=([string]$Device.DeviceId -replace '[^A-Za-z0-9._-]','_');if($safeDevice.Length -gt 55){$safeDevice=$safeDevice.Substring(0,55)}
    $safeRelease=([string]$Candidate.ReleaseId -replace '[^A-Za-z0-9._-]','_');if(-not $safeRelease){$safeRelease=([string]$Candidate.Version -replace '[^A-Za-z0-9._-]','_')};if(-not $safeRelease){$safeRelease=[guid]::NewGuid().ToString('N')}
    $folder=Join-Path $root (($adapter+'_'+$safeDevice+'_'+$safeRelease).Trim('_'))
    if(Test-Path -LiteralPath $folder -PathType Container){$folder=Join-Path $root (($adapter+'_'+$safeDevice+'_'+$safeRelease+'_'+[guid]::NewGuid().ToString('N').Substring(0,8)).Trim('_'))}
    New-Item -ItemType Directory -Path $folder -Force | Out-Null
    $extension=[IO.Path]::GetExtension($uri.AbsolutePath);if($extension -notmatch '^\.(exe|cab|zip)$'){$extension='.exe'}
    $file=Join-Path $folder ('VendorDriverPackage'+$extension)
    try{
        if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage ('Downloading official '+[string]$Candidate.Source+' package')}
        if(Test-AMRDriverWorkerCancel){throw 'AMR_USER_CANCELLED'}
        $downloaded=$false;$lastError=''
        for($attempt=1;$attempt -le 3;$attempt++){
            $request=[System.Net.HttpWebRequest]::Create($uri);$request.Method='GET';$request.UserAgent='AMR-Windows-Utility-DriverCenter/6.8';$request.Timeout=180000;$request.ReadWriteTimeout=180000;$request.AllowAutoRedirect=$true;$request.MaximumAutomaticRedirections=5;$request.UseDefaultCredentials=$false
            $response=$null;$inputStream=$null;$outputStream=$null
            try{
                $response=$request.GetResponse();$finalUri=$response.ResponseUri
                if($finalUri.Scheme -ne 'https' -or $finalUri.Host -notin $allowedHosts){throw ('Vendor package redirected to an unapproved host: '+$finalUri.Host)}
                if([string]$response.ContentType -match '(?i)text/html|application/json'){throw 'Vendor package endpoint returned HTML/JSON instead of a package.'}
                if([int64]$response.ContentLength -gt 4GB){throw 'Vendor package response exceeds the 4 GB safety limit.'}
                $inputStream=$response.GetResponseStream();$outputStream=[IO.File]::Open($file,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None)
                $buffer=New-Object byte[] 65536;$received=[int64]0;$lastProgress=[int64]0
                while(($read=$inputStream.Read($buffer,0,$buffer.Length)) -gt 0){$outputStream.Write($buffer,0,$read);$received+=$read;if(Test-AMRDriverWorkerCancel){throw 'AMR_USER_CANCELLED'};if($received -gt 4GB){throw 'Vendor package exceeded the 4 GB safety limit while downloading.'};if($response.ContentLength -gt 0 -and ($received-$lastProgress -ge 1MB -or $received -eq [int64]$response.ContentLength)){ $pct=[int][math]::Floor(($received/[double]$response.ContentLength)*100);if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage ('Downloading OEM bundle: {0:N0} / {1:N0} bytes' -f $received,$response.ContentLength) -Percent $pct -BytesReceived $received -BytesTotal ([long]$response.ContentLength)};$lastProgress=$received }}
                $outputStream.Flush();if($received -le 0 -or ($response.ContentLength -gt 0 -and $received -ne [int64]$response.ContentLength)){throw 'Vendor package download was empty or content length did not match.'};$downloaded=$true;break
            }catch{if([string]$_.Exception.Message -eq 'AMR_USER_CANCELLED'){throw};$lastError=[string]$_.Exception.Message;if(Test-Path -LiteralPath $file){Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue};if($attempt -lt 3){Start-Sleep -Seconds (2*$attempt)}}finally{if($outputStream){$outputStream.Dispose()};if($inputStream){$inputStream.Dispose()};if($response){$response.Dispose()}}
        }
        if(-not $downloaded){throw ('Vendor package download failed after 3 attempts: '+$lastError)}
        if(-not(Test-Path -LiteralPath $file -PathType Leaf)){throw 'Vendor package download did not create a file.'}
        $info=Get-Item -LiteralPath $file;if($info.Length -le 0 -or $info.Length -gt 4GB){throw 'Vendor package size is empty or exceeds the 4 GB safety limit.'}
        if($Candidate.ExpectedSize -and [int64]$Candidate.ExpectedSize -gt 0 -and [int64]$Candidate.ExpectedSize -ne [int64]$info.Length){throw 'Downloaded package size does not match the official catalog metadata.'}
        $hashRecord=Get-FileHash -LiteralPath $file -Algorithm SHA256 -ErrorAction Stop
        $expected=[string]$Candidate.ExpectedHash;$hashAlgorithm=[string]$Candidate.HashAlgorithm
        if($expected){$actualExpected=(Get-FileHash -LiteralPath $file -Algorithm $hashAlgorithm -ErrorAction Stop).Hash;if($actualExpected -ine $expected){throw ('Vendor package '+$hashAlgorithm+' does not match the official catalog metadata.') }}
        if(Get-Command Write-AMRDriverWorkerProgress -ErrorAction SilentlyContinue){Write-AMRDriverWorkerProgress -Path $script:DriverWorkerProgressPath -Stage 'Validating official vendor package signature and publisher'}
        $signature=Get-AuthenticodeSignature -FilePath $file -ErrorAction Stop
        if([string]$signature.Status -ne 'Valid' -or -not $signature.SignerCertificate){throw ('Vendor package Authenticode signature is not valid: '+[string]$signature.Status)}
        $signer=[string]$signature.SignerCertificate.Subject
        $expectedPublisher=switch($adapter){'DellDriverPackCatalog'{'Dell'} 'HPDriverPackCatalog'{'HP|Hewlett'} default{'Lenovo'}}
        if($signer -notmatch ('(?i)'+$expectedPublisher)){throw ('Package signer does not identify the expected vendor '+$expectedPublisher+'. Actual signer: '+$signer)}
        $manifest=[pscustomobject]@{Product='AMR Verified OEM Driver Pack';CreatedAt=(Get-Date).ToString('o');SourceAdapter=$adapter;Source=[string]$Candidate.Source;DeviceInstanceId=[string]$Device.DeviceId;DeviceName=[string]$Device.DeviceName;Title=[string]$Candidate.Title;Model=[string]$Candidate.Model;Version=[string]$Candidate.Version;DriverDate=[string]$Candidate.DriverDate;PackageUrl=$url;PackagePath=$file;SizeBytes=[int64]$info.Length;SHA256=[string]$hashRecord.Hash;ExpectedHash=$expected;HashAlgorithm=$hashAlgorithm;Signer=$signer;SignerThumbprint=[string]$signature.SignerCertificate.Thumbprint;SignatureStatus=[string]$signature.Status;Installable=$false;VerificationState='Downloaded, official catalog hash checked when supplied, and Authenticode signature validated. OEM bundle extraction and device-INF validation are not yet performed.';SearchMatch=[string]$Candidate.MatchReason}
        $manifestPath=Join-Path $folder 'AMR_VendorPackage_Manifest.json';$manifest|ConvertTo-Json -Depth 7|Set-Content -LiteralPath $manifestPath -Encoding UTF8 -ErrorAction Stop
        $Candidate|Add-Member -NotePropertyName IsDownloaded -NotePropertyValue $true -Force
        $Candidate|Add-Member -NotePropertyName IsInstallable -NotePropertyValue $false -Force
        $Candidate|Add-Member -NotePropertyName PackageFolder -NotePropertyValue $folder -Force
        $Candidate|Add-Member -NotePropertyName PackagePath -NotePropertyValue $file -Force
        $Candidate|Add-Member -NotePropertyName ManifestPath -NotePropertyValue $manifestPath -Force
        $Candidate|Add-Member -NotePropertyName SHA256 -NotePropertyValue ([string]$hashRecord.Hash) -Force
        $Candidate|Add-Member -NotePropertyName CatalogSigner -NotePropertyValue $signer -Force
        $Candidate|Add-Member -NotePropertyName VerificationState -NotePropertyValue ([string]$manifest.VerificationState) -Force
        return [pscustomobject]@{Success=$true;Candidate=$Candidate;PackagePath=$file;ManifestPath=$manifestPath;PackageFolder=$folder;SizeBytes=[int64]$info.Length;SHA256=[string]$hashRecord.Hash;Signer=$signer;Installable=$false;Message='Official OEM driver pack downloaded and cryptographically verified. It remains a vendor bundle; AMR has not extracted and INF-validated its contents, so it is not installable through the current PnPUtil pipeline.'}
    }catch{if(Test-Path -LiteralPath $folder -PathType Container){Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue};throw}
}

function Show-AMRVendorPackageResults {
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][object[]]$Candidates)
    $dialog=New-Object System.Windows.Window;$dialog.Title='Direct Vendor Package Discovery – '+[string]$Device.DeviceName;$dialog.Width=1050;$dialog.Height=590;$dialog.MinWidth=820;$dialog.MinHeight=430;$dialog.WindowStartupLocation='CenterOwner';$dialog.ResizeMode='CanResize';$dialog.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#111C2B');$dialog.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#E7EDF5');if($script:Window -and $script:Window.IsVisible){$dialog.Owner=$script:Window}
    $root=New-Object System.Windows.Controls.DockPanel;$root.Margin=[System.Windows.Thickness]::new(14)
    $note=New-Object System.Windows.Controls.TextBlock;$note.Text='Multi-source vendor coverage: Dell Driver Pack Catalog, HP Client Driver Pack Catalog plus HP HPIA individual SoftPaqs, and Lenovo CDRT provide model/OS-scoped package candidates where published. HP ZBook platforms receive exact SystemID/model + Windows-release matching and prioritized HPIA platform SoftPaq discovery, including platform-listed biometric packages. HP Victus and other consumer HP models use exact HP Support Drivers product lookup when a business catalog entry is not published; no cross-model package substitution is made. MSI and GIGABYTE add exact motherboard-model metadata and official package links. Other supported OEM, motherboard, component, storage, peripheral and system-integrator vendors appear as official portal leads. Portal leads are not packages. OEM packages remain non-installable until extraction and INF/CAT validation; AMR will not execute vendor EXEs automatically.';$note.TextWrapping='Wrap';$note.Margin=[System.Windows.Thickness]::new(0,0,0,10);$note.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#FCD9A6');[System.Windows.Controls.DockPanel]::SetDock($note,'Top');[void]$root.Children.Add($note)
    $grid=New-Object System.Windows.Controls.ListView;$grid.SelectionMode='Single';$grid.ItemsSource=$Candidates;$grid.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#111B29');$grid.Foreground=[System.Windows.Media.Brushes]::White
    $view=New-Object System.Windows.Controls.GridView
    foreach($colDef in @(@('Rank',50,'ComparisonRank'),@('Vendor',75,'Source'),@('Driver / Package',250,'Title'),@('Model',150,'Model'),@('Version',80,'Version'),@('Date',90,'DriverDate'),@('OS',80,'OS'),@('Match',190,'MatchConfidence'),@('Downloaded',85,'IsDownloaded'))){$col=New-Object System.Windows.Controls.GridViewColumn;$col.Header=$colDef[0];$col.Width=[double]$colDef[1];$col.DisplayMemberBinding=[System.Windows.Data.Binding]::new([string]$colDef[2]);[void]$view.Columns.Add($col)};$grid.View=$view;[void]$root.Children.Add($grid)
    $bottom=New-Object System.Windows.Controls.StackPanel;$bottom.Orientation='Vertical';$bottom.Margin=[System.Windows.Thickness]::new(0,10,0,0);[System.Windows.Controls.DockPanel]::SetDock($bottom,'Bottom')
    $detail=New-Object System.Windows.Controls.TextBlock;$detail.TextWrapping='Wrap';$detail.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#93C5FD');$detail.Margin=[System.Windows.Thickness]::new(0,0,0,8);[void]$bottom.Children.Add($detail)
    $buttons=New-Object System.Windows.Controls.StackPanel;$buttons.Orientation='Horizontal';$buttons.HorizontalAlignment='Right'
    $download=New-Object System.Windows.Controls.Button;$download.Content='Download & Verify Selected';$download.Width=205;$download.Height=34;$download.Margin=[System.Windows.Thickness]::new(0,0,8,0);$download.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#2563EB');$download.Foreground=[System.Windows.Media.Brushes]::White
    $open=New-Object System.Windows.Controls.Button;$open.Content='Open Official Package URL';$open.Width=175;$open.Height=34;$open.Margin=[System.Windows.Thickness]::new(0,0,8,0);$open.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#245B46');$open.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#E8FFF3');$open.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#55A987');$open.BorderThickness=[System.Windows.Thickness]::new(1)
    $close=New-Object System.Windows.Controls.Button;$close.Content='Close';$close.Width=90;$close.Height=34;$close.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#252F3D');$close.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#E2EAF3');$close.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#48596D');$close.BorderThickness=[System.Windows.Thickness]::new(1);$close.Add_Click({$dialog.Close()})
    $open.Add_Click({if($grid.SelectedItem -and $grid.SelectedItem.PackageUrl){Start-Process -FilePath ([string]$grid.SelectedItem.PackageUrl) -ErrorAction SilentlyContinue}})
    $download.Add_Click(({
        if(-not $grid.SelectedItem -or [bool]$grid.SelectedItem.IsDownloaded){return}
        $selected=$grid.SelectedItem;$download.IsEnabled=$false;$open.IsEnabled=$false
        try{
            $null=Start-AMRDriverManagedWorker -Operation VendorPackageAcquisition -Device $Device -Candidate $selected
            $poll=New-Object System.Windows.Threading.DispatcherTimer;$poll.Interval=[TimeSpan]::FromMilliseconds(400)
            $poll.Add_Tick(({
                if(-not $script:DriverManagedJob){$poll.Stop();$download.IsEnabled=$true;$open.IsEnabled=$true;return}
                if($script:DriverManagedJob.State -in @('Completed','Failed','Stopped')){$poll.Stop();try{$acq=Complete-AMRDriverManagedWorker;if(-not $acq -or -not $acq.Success){throw 'Vendor package acquisition did not return a verified result.'};$detail.Text=($acq.Message+' Package: '+$acq.PackagePath+' | Signer: '+$acq.Signer+' | SHA-256: '+$acq.SHA256);$download.Content='Downloaded & Verified';$selected.IsDownloaded=$true;$selected.PackagePath=$acq.PackagePath;$selected.ManifestPath=$acq.ManifestPath;$selected.CatalogSigner=$acq.Signer;$selected.VerificationState=$acq.Message;Write-AMRLog ('Downloaded and verified '+$selected.Source+' OEM bundle for '+$Device.DeviceName+'.') SUCCESS Overview}catch{$detail.Text=('Vendor package acquisition failed: '+[string]$_.Exception.Message);Show-AMRMessageGlass ([string]$_.Exception.Message) 'Vendor Package Acquisition' OK Warning | Out-Null}finally{$download.IsEnabled=$true;$open.IsEnabled=$true}}
            }).GetNewClosure());$script:DriverManagedTimer=$poll;$poll.Start()
        }catch{$download.IsEnabled=$true;$open.IsEnabled=$true;Show-AMRMessageGlass ('Could not start vendor package acquisition: '+[string]$_.Exception.Message) 'Vendor Package Acquisition' OK Warning | Out-Null}
    }).GetNewClosure())
    [void]$buttons.Children.Add($download);[void]$buttons.Children.Add($open);[void]$buttons.Children.Add($close);[void]$bottom.Children.Add($buttons);[void]$root.Children.Add($bottom)
    $grid.Add_SelectionChanged({if($grid.SelectedItem){$item=$grid.SelectedItem;$detail.Text=('Driver/package: {0} | Source: {1} | Model: {2} | Package URL: {3} | Expected hash: {4} {5} | Match: {6} | Status: {7}' -f $item.Title,$item.Source,$item.Model,$item.PackageUrl,$item.HashAlgorithm,$item.ExpectedHash,$item.MatchReason,$item.VerificationState);$download.IsEnabled=((-not [bool]$item.IsDownloaded) -and [bool]$item.IsDownloadable);$open.IsEnabled=(-not [string]::IsNullOrWhiteSpace([string]$item.PackageUrl))}})
    $dialog.Content=$root;if($Candidates.Count -gt 0){$grid.SelectedIndex=0};[void]$dialog.ShowDialog()
}

function Repair-AMRDriverStaleRestoreState {
    # A13e: a finished or abandoned Restore Point operation must never keep Scan blocked.
    try {
        $opName = ''; try { $opName = [string]$script:DriverOperationState.Name } catch {}
        if ($opName -ne 'RestorePoint') { return }
        $pollRunning = $false
        try { $pollRunning = [bool]($script:DriverRestorePointPollTimer -and $script:DriverRestorePointPollTimer.IsEnabled) } catch {}
        if ($pollRunning) { return }
        $managed = $script:DriverManagedJob
        $active = $script:DriverRestorePointActiveJob
        foreach ($stale in @($managed,$active)) { if ($stale) { try { Stop-Job -Job $stale -ErrorAction SilentlyContinue } catch {}; try { Remove-Job -Job $stale -Force -ErrorAction SilentlyContinue } catch {} } }
        $script:DriverManagedJob = $null; $script:DriverRestorePointActiveJob = $null; $script:DriverRestorePointPollTimer = $null
        if ($script:DriverManagedTimer) { try { $script:DriverManagedTimer.Stop() } catch {}; $script:DriverManagedTimer = $null }
        if ($script:DriverManagedProgressTimer) { try { $script:DriverManagedProgressTimer.Stop() } catch {}; $script:DriverManagedProgressTimer = $null }
        $script:DriverOperationState = [pscustomobject]@{ Name='Idle'; State='Idle'; StartedAt=$null; Generation=[int]$script:DriverOperationState.Generation; CanCancel=$false; Status='Ready'; PartialShown=$false }
        try { Release-AMRDriverOperationLock } catch {}
        Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceScan -Stage StaleRestoreStateRepaired -Message 'A finished Restore Point operation was still marked active; its state and lock were cleared so Scan can run.' -Source 'Repair-AMRDriverStaleRestoreState'
    } catch {}
}

function Write-AMRDriverScanBlocked {
    param([string]$Gate,[string]$Detail = '')
    try { (C 'DriverScanStatus').Text = ('Scan is waiting: ' + $Detail) } catch {}
    try { Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceScan -Stage ScanBlocked -Message ('Scan did not start. Gate: {0}. {1}' -f $Gate,$Detail) -Source 'Start-AMRDriverScan' } catch {}
}

function Start-AMRDriverScan {
    Repair-AMRDriverStaleRestoreState
    if ($script:DriverManagedJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive) {
        $gateText = 'managedJob={0}; batchActive={1}; smartQueueActive={2}; operation={3}' -f [bool]$script:DriverManagedJob,[bool]$script:DriverBatchActive,[bool]$script:DriverSmartQueueActive,$(try { [string]$script:DriverOperationState.Name } catch { '' })
        Write-AMRDriverScanBlocked -Gate 'ManagedOperation' -Detail ('another driver operation is still marked active (' + $gateText + ').')
        return
    }
    $button = C 'ScanDriversBtn'
    if ($script:DriverActionJob -and $script:DriverActionJob.State -in @('Running','NotStarted')) {
        (C 'DriverScanStatus').Text = 'Wait for the current driver download or installation to finish before scanning again.'
        return
    }
    if ($script:DriverScanJob -and $script:DriverScanJob.State -in @('Running','NotStarted')) {
        return
    }
    if($script:DriverOperationState.State -eq 'Running'){ Write-AMRDriverScanBlocked -Gate 'OperationRunning' -Detail ('operation ' + [string]$script:DriverOperationState.Name + ' is still running.'); return }
    if (-not (Acquire-AMRDriverOperationLock -Operation 'Scan')) {
        $heldBy = ''; try { $heldBy = [string]$script:AMRDriverOpLockState.Operation } catch {}
        Write-AMRDriverScanBlocked -Gate 'OperationLock' -Detail ('the Driver Center operation lock is held by ' + $(if ($heldBy) { $heldBy } else { 'another operation' }) + '.')
        return
    }
    $script:DriverScanGeneration = [int]$script:DriverScanGeneration + 1
    $script:DriverCurrentScanId = [guid]::NewGuid().ToString('N')
    $script:DriverCurrentOperationId = $script:DriverCurrentScanId
    $script:DriverScanStartedAt = Get-Date
    try { Clear-AMRDriverDiagView } catch {}
    Write-AMRDriverDiagnostic -Severity INFO -Operation DeviceScan -Stage Started -Message 'Driver Center device discovery started.' -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -Source 'Start-AMRDriverScan' -Context @{Generation=$script:DriverScanGeneration;Computer=$env:COMPUTERNAME}

    try {
        $button.IsEnabled = $false
        $button.Content = 'Scanning…'
        $script:DriverAllDeviceRows = @()
        $script:DriverSmartSelectionReady = $false
        $script:DriverSmartSelectedKeys = @()
        $script:DriverSmartSelectionTime = $null
        (C 'DriverScanStatus').Text = 'Detecting computer model, motherboard, Windows version and Plug and Play devices…'
        (C 'DriverDeviceList').ItemsSource = $null
        (C 'DriverActionStatus').Text = ('Scanning for applicable updates. AMR driver package copies are saved under: ' + (Join-Path $script:DownloadDir 'Drivers'))
        (C 'DriverDownloadSelectedBtn').IsEnabled = $false
        (C 'DriverInstallSelectedBtn').IsEnabled = $false
        (C 'DriverCatalogSearchBtn').IsEnabled = $false

        $driverPackageRoot = Join-Path $script:DownloadDir 'Drivers'
        $driverWorkerFunctionNames = @('Get-AMRDriverVendorRegistry','Resolve-AMRDriverVendorName','Get-AMRDriverOEMModelProfile','Get-AMRDriverHardwareCoverage','Get-AMRDriverVendorSourceAdapters')
        $driverWorkerFunctionDefinitions = @()
        foreach($functionName in $driverWorkerFunctionNames) {
            $functionInfo = Get-Command -Name $functionName -CommandType Function -ErrorAction Stop
            $driverWorkerFunctionDefinitions += [pscustomobject]@{Name=$functionName;Definition=[string]$functionInfo.Definition}
        }
        $driverWorkerPayload = [pscustomobject]@{DriverPackageRoot=$driverPackageRoot;FunctionDefinitions=@($driverWorkerFunctionDefinitions)}
        if (-not $script:DriverOperationState.PSObject.Properties['PartialShown']) { $script:DriverOperationState | Add-Member -NotePropertyName PartialShown -NotePropertyValue $false -Force }
        $script:DriverOperationState.PartialShown = $false
        $script:DriverScanJob = Start-Job -ArgumentList $driverWorkerPayload -ScriptBlock {
            param($WorkerPayload)
            $DriverPackageRoot = [string]$WorkerPayload.DriverPackageRoot
            foreach($functionDefinition in @($WorkerPayload.FunctionDefinitions)) {
                $functionPath = 'Function:\' + [string]$functionDefinition.Name
                Set-Item -Path $functionPath -Value ([scriptblock]::Create([string]$functionDefinition.Definition)) -Force
            }
            $ErrorActionPreference = 'Stop'
            $driverWorkerStartedAt = Get-Date
            # CIM is preferred. Windows PowerShell 5.1's WMI provider is used only
            # as a compatibility fallback when the corresponding CIM query fails.
            try {
                $computer = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop | Select-Object -First 1
            } catch {
                $cimComputerError = $_.Exception.Message
                try { $computer = Get-WmiObject -Class Win32_ComputerSystem -ErrorAction Stop | Select-Object -First 1 }
                catch { throw ('Computer identity query failed through CIM and WMI. CIM: {0} | WMI: {1}' -f $cimComputerError,$_.Exception.Message) }
            }
            if (-not $computer) { throw 'Computer identity query returned no Win32_ComputerSystem instance.' }
            $board = $null
            $bios = $null
            try {
                $operatingSystem = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop | Select-Object -First 1
            } catch {
                $cimOsError = $_.Exception.Message
                try { $operatingSystem = Get-WmiObject -Class Win32_OperatingSystem -ErrorAction Stop | Select-Object -First 1 }
                catch { throw ('Windows identity query failed through CIM and WMI. CIM: {0} | WMI: {1}' -f $cimOsError,$_.Exception.Message) }
            }
            if (-not $operatingSystem) { throw 'Windows identity query returned no Win32_OperatingSystem instance.' }
            $boards = @()
            $bios = $null
            $systemProduct = $null
            $enclosureRows = @()
            $processors = @()
            $videoControllers = @()
            try { $boards = @(Get-CimInstance -ClassName Win32_BaseBoard -ErrorAction Stop) } catch {}
            $board = $boards | Select-Object -First 1
            try { $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop | Select-Object -First 1 } catch {}
            try { $systemProduct = Get-CimInstance -ClassName Win32_ComputerSystemProduct -ErrorAction Stop | Select-Object -First 1 } catch {}
            try { $enclosureRows = @(Get-CimInstance -ClassName Win32_SystemEnclosure -ErrorAction Stop) } catch {}
            try { $processors = @(Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop | ForEach-Object { [string]$_.Name } | Where-Object { $_ } | Select-Object -Unique) } catch {}
            try { $videoControllers = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop | ForEach-Object { [string]$_.Name } | Where-Object { $_ } | Select-Object -Unique) } catch {}

            # Build a conservative system identity profile. SMBIOS values are often generic
            # on custom-built systems, so the profile records confidence and never treats
            # a motherboard vendor as proof of the complete computer OEM.
            $systemManufacturer = [string]$computer.Manufacturer
            $systemModel = [string]$computer.Model
            $systemSku = [string]$computer.SystemSKUNumber
            $systemFamily = [string]$computer.SystemFamily
            $productVendor = if ($systemProduct) { [string]$systemProduct.Vendor } else { '' }
            $productName = if ($systemProduct) { [string]$systemProduct.Name } else { '' }
            $productVersion = if ($systemProduct) { [string]$systemProduct.Version } else { '' }
            $chassisCodes = @($enclosureRows | ForEach-Object { @($_.ChassisTypes) } | ForEach-Object { try { [int]$_ } catch {} } | Where-Object { $_ -gt 0 } | Select-Object -Unique)
            $portableChassisCodes = @(8,9,10,11,12,14,18,21,30,31,32)
            $desktopChassisCodes = @(3,4,5,6,7,13,15,16,17)
            $platformType = 'Unknown form factor'
            if (@($chassisCodes | Where-Object { $_ -in $portableChassisCodes }).Count -gt 0 -or [int]$computer.PCSystemType -eq 2) { $platformType = 'Portable / laptop-class system' }
            elseif (@($chassisCodes | Where-Object { $_ -in $desktopChassisCodes }).Count -gt 0 -or [int]$computer.PCSystemType -in @(1,3)) { $platformType = 'Desktop / workstation-class system' }
            elseif ([int]$computer.PCSystemType -eq 4 -or [int]$computer.PCSystemType -eq 5 -or [int]$computer.PCSystemType -eq 7) { $platformType = 'Server-class system' }
            $genericIdentityPattern = '(?i)to be filled|default string|system manufacturer|system product name|unknown|not specified|o\.e\.m\.|base board product|product name'
            $identityEvidence = @($systemManufacturer,$systemModel,$systemSku,$productVendor,$productName) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) -and [string]$_ -notmatch $genericIdentityPattern }
            $computerLooksBranded = ([string]$systemManufacturer -notmatch $genericIdentityPattern) -and ([string]$systemModel -notmatch $genericIdentityPattern) -and -not [string]::IsNullOrWhiteSpace($systemModel)
            $systemClass = if ($computerLooksBranded) { 'Branded OEM / prebuilt identity detected' } elseif ($board -and [string]$board.Manufacturer -and [string]$board.Manufacturer -notmatch $genericIdentityPattern) { 'Likely custom-built or SMBIOS-generic system; motherboard identity available' } else { 'System identity incomplete; component-level detection will be primary' }
            $identityConfidence = if ($computerLooksBranded -and $systemSku) { 'High' } elseif ($computerLooksBranded -or ($productVendor -and $productName -and $productName -notmatch $genericIdentityPattern)) { 'Moderate' } elseif ($identityEvidence.Count -gt 0) { 'Limited' } else { 'Low' }
            $boardSummary = @($boards | ForEach-Object { (([string]$_.Manufacturer).Trim() + ' ' + ([string]$_.Product).Trim()).Trim() } | Where-Object { $_ } | Select-Object -Unique)

            # Read the actual installed signed-driver inventory separately from PnP health.
            # Win32_PnPSignedDriver exposes provider, version, date, INF and signature state.
            $signedDriverMap = @{}
            try {
                $signedDrivers = Get-CimInstance -ClassName Win32_PnPSignedDriver -ErrorAction Stop
                foreach ($signedDriver in $signedDrivers) {
                    $driverKey = ([string]$signedDriver.DeviceID).ToUpperInvariant()
                    if (-not [string]::IsNullOrWhiteSpace($driverKey)) {
                        $signedDriverMap[$driverKey] = $signedDriver
                    }
                }
            } catch {}

            $errorMap = @{
                0 = 'OK'; 1 = 'Not configured'; 2 = 'Not started'; 3 = 'Driver corrupted'
                4 = 'Device not working'; 5 = 'Device failure'; 6 = 'Cannot communicate'
                7 = 'Driver required'; 8 = 'Driver load failed'; 9 = 'Invalid driver'
                10 = 'Cannot start'; 11 = 'Device failure'; 12 = 'Insufficient resources'
                13 = 'Device not found'; 14 = 'Restart required'; 15 = 'Re-enumeration required'
                16 = 'Resource conflict'; 17 = 'Reconfiguration required'; 18 = 'Reinstall driver'
                19 = 'Registry configuration issue'; 20 = 'VxD loader failure'; 21 = 'Restart required'
                22 = 'Disabled'; 23 = 'System failure'; 24 = 'Device not present'
                25 = 'Configuration pending'; 26 = 'Configuration pending'; 27 = 'No resources'
                28 = 'Driver not installed'; 29 = 'Firmware disabled'; 30 = 'IRQ conflict'
                31 = 'Driver cannot load'
            }

            $deviceRows = @()
            try {
                try {
                    $pnpDevices = @(Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction Stop)
                } catch {
                    $cimPnpError = $_.Exception.Message
                    try { $pnpDevices = @(Get-WmiObject -Class Win32_PnPEntity -ErrorAction Stop) }
                    catch { throw ('Plug and Play enumeration failed through CIM and WMI. CIM: {0} | WMI: {1}' -f $cimPnpError,$_.Exception.Message) }
                }
                if ($null -eq $pnpDevices) { throw 'Plug and Play enumeration returned a null result.' }
                if (@($pnpDevices).Count -eq 0) { throw 'Plug and Play enumeration completed but returned zero devices; refusing to report a misleading successful scan.' }
                foreach ($device in $pnpDevices) {
                    $errorCode = 0
                    try { if ($null -ne $device.ConfigManagerErrorCode) { $errorCode = [int]$device.ConfigManagerErrorCode } } catch {}
                    $statusText = if ($errorMap.ContainsKey($errorCode)) { [string]$errorMap[$errorCode] } else { if ($errorCode -eq 0) { 'OK' } else { 'Error' } }
                    $hardwareIds = @()
                    $compatibleIds = @()
                    try { $hardwareIds = @($device.HardwareID | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Select-Object -Unique) } catch {}
                    try { $compatibleIds = @($device.CompatibleID | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Select-Object -Unique) } catch {}
                    $installedDriver = $null
                    $deviceKey = ([string]$device.DeviceID).ToUpperInvariant()
                    if (-not [string]::IsNullOrWhiteSpace($deviceKey) -and $signedDriverMap.ContainsKey($deviceKey)) {
                        $installedDriver = $signedDriverMap[$deviceKey]
                    }
                    $driverDateText = 'Not available'
                    if ($installedDriver -and $installedDriver.DriverDate) {
                        try { $driverDateText = ([datetime]$installedDriver.DriverDate).ToString('yyyy-MM-dd') } catch { $driverDateText = [string]$installedDriver.DriverDate }
                    }
                    $idVendorHint = ''
                    $idVendorCode = ''
                    foreach ($hardwareId in @($hardwareIds)) {
                        if ($hardwareId -match '^PCI\\VEN_([0-9A-F]{4})') {
                            $vendorCode = $Matches[1]
                            $idVendorCode = 'PCI VEN_' + $vendorCode
                            $idVendorHint = switch ($vendorCode) {
                                '8086' { 'Intel'; break }
                                '10DE' { 'NVIDIA'; break }
                                '1002' { 'AMD'; break }
                                '10EC' { 'Realtek'; break }
                                '14E4' { 'Broadcom'; break }
                                '168C' { 'Qualcomm / Atheros'; break }
                                '1B4B' { 'Marvell'; break }
                                '1022' { 'AMD'; break }
                                '1106' { 'VIA'; break }
                                '1AF4' { 'VirtIO'; break }
                                default { '' }
                            }
                            if ($idVendorHint) { break }
                        } elseif ($hardwareId -match '^USB\\VID_([0-9A-F]{4})') {
                            $vendorCode = $Matches[1]
                            $idVendorCode = 'USB VID_' + $vendorCode
                            $idVendorHint = switch ($vendorCode) {
                                '8087' { 'Intel'; break }
                                '0BDA' { 'Realtek'; break }
                                '0A5C' { 'Broadcom'; break }
                                '0CF3' { 'Qualcomm / Atheros'; break }
                                default { '' }
                            }
                            if ($idVendorHint) { break }
                        }
                    }
                    $deviceRows += [pscustomobject]@{
                        DeviceName = [string]$device.Name
                        DeviceClass = [string]$device.PNPClass
                        Manufacturer = [string]$device.Manufacturer
                        HardwareIdVendorCode = $idVendorCode
                        HardwareIdVendorHint = $idVendorHint
                        StatusText = $statusText
                        ErrorCode = $errorCode
                        DriverProvider = $(if ($installedDriver -and $installedDriver.DriverProviderName) { [string]$installedDriver.DriverProviderName } else { 'Unknown' })
                        DriverVersion = $(if ($installedDriver -and $installedDriver.DriverVersion) { [string]$installedDriver.DriverVersion } else { 'Not installed / unavailable' })
                        DriverDate = $driverDateText
                        DriverInf = $(if ($installedDriver) { [string]$installedDriver.InfName } else { '' })
                        DriverIsSigned = $(if ($installedDriver) { [bool]$installedDriver.IsSigned } else { $false })
                        DeviceId = [string]$device.DeviceID
                        HardwareIds = $hardwareIds
                        CompatibleIds = $compatibleIds
                        Service = [string]$device.Service
                    }
                }

                # Supplemental modern PnP inventory: WMI can omit some present devices
                # (notably newly enumerated/unknown devices). Merge by InstanceId so no
                # duplicate rows are introduced. Only currently present devices are added.
                try {
                    if (Get-Command -Name Get-PnpDevice -CommandType Cmdlet -ErrorAction SilentlyContinue) {
                        $knownDeviceIds = @{}
                        foreach ($existingRow in @($deviceRows)) {
                            $knownId = ([string]$existingRow.DeviceId).ToUpperInvariant()
                            if ($knownId) { $knownDeviceIds[$knownId] = $true }
                        }
                        $modernPnpRows = @(Get-PnpDevice -PresentOnly -ErrorAction Stop)
                        foreach ($modernPnp in $modernPnpRows) {
                            $instanceId = [string]$modernPnp.InstanceId
                            if ([string]::IsNullOrWhiteSpace($instanceId)) { continue }
                            $instanceKey = $instanceId.ToUpperInvariant()
                            if ($knownDeviceIds.ContainsKey($instanceKey)) { continue }
                            $problemCode = 0
                            try { if ($modernPnp.PSObject.Properties['Problem'] -and $null -ne $modernPnp.Problem) { $problemCode = [int]$modernPnp.Problem } } catch {}
                            $modernHardwareIds = @()
                            $modernCompatibleIds = @()
                            try {
                                if (Get-Command -Name Get-PnpDeviceProperty -CommandType Cmdlet -ErrorAction SilentlyContinue) {
                                    $hardwareProperty = Get-PnpDeviceProperty -InstanceId $instanceId -KeyName 'DEVPKEY_Device_HardwareIds' -ErrorAction SilentlyContinue | Select-Object -First 1
                                    if ($hardwareProperty -and $hardwareProperty.Data) { $modernHardwareIds = @($hardwareProperty.Data | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Where-Object { $_ } | Select-Object -Unique) }
                                    $compatibleProperty = Get-PnpDeviceProperty -InstanceId $instanceId -KeyName 'DEVPKEY_Device_CompatibleIds' -ErrorAction SilentlyContinue | Select-Object -First 1
                                    if ($compatibleProperty -and $compatibleProperty.Data) { $modernCompatibleIds = @($compatibleProperty.Data | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Where-Object { $_ } | Select-Object -Unique) }
                                }
                            } catch {}
                            $modernName = [string]$modernPnp.FriendlyName
                            $modernClass = [string]$modernPnp.Class
                            $modernManufacturer = [string]$modernPnp.Manufacturer
                            $modernStatus = if ($problemCode -eq 0) { 'OK • PnP supplemental' } elseif ($errorMap.ContainsKey($problemCode)) { [string]$errorMap[$problemCode] } else { 'PnP problem ' + $problemCode }
                            $modernVendorHint = ''
                            $modernVendorCode = ''
                            foreach ($modernId in @($modernHardwareIds)) {
                                if ($modernId -match '^PCI\\VEN_([0-9A-F]{4})') { $modernVendorCode = 'PCI VEN_' + $Matches[1]; break }
                                if ($modernId -match '^USB\\VID_([0-9A-F]{4})') { $modernVendorCode = 'USB VID_' + $Matches[1]; break }
                            }
                            $deviceRows += [pscustomobject]@{
                                DeviceName = $(if ($modernName) { $modernName } else { 'Unknown Plug and Play device' })
                                DeviceClass = $modernClass
                                Manufacturer = $modernManufacturer
                                HardwareIdVendorCode = $modernVendorCode
                                HardwareIdVendorHint = $modernVendorHint
                                StatusText = $modernStatus
                                ErrorCode = $problemCode
                                DriverProvider = 'Unknown'
                                DriverVersion = 'Not installed / unavailable'
                                DriverDate = 'Not available'
                                DriverInf = ''
                                DriverIsSigned = $false
                                DeviceId = $instanceId
                                HardwareIds = $modernHardwareIds
                                CompatibleIds = $modernCompatibleIds
                                Service = ''
                            }
                            $knownDeviceIds[$instanceKey] = $true
                        }
                    }
                } catch {
                    # Optional enrichment must never invalidate a successful primary WMI scan.
                }
            } catch {
                throw ('Device enumeration could not complete. The scan is marked failed instead of presenting a synthetic device row. {0}' -f $_.Exception.Message)
            }

            $hardwareReadyAt = Get-Date
            # Initialize optional update state before publishing the first hardware-only result.
            foreach ($deviceRow in $deviceRows) {
                $deviceRow | Add-Member -NotePropertyName UpdateStatus -NotePropertyValue 'Windows Update check running in background' -Force
                $deviceRow | Add-Member -NotePropertyName AvailableVersion -NotePropertyValue '--' -Force
                $deviceRow | Add-Member -NotePropertyName AvailableUpdate -NotePropertyValue '' -Force
                $deviceRow | Add-Member -NotePropertyName UpdateId -NotePropertyValue '' -Force
                $deviceRow | Add-Member -NotePropertyName UpdateRevision -NotePropertyValue 0 -Force
                $deviceRow | Add-Member -NotePropertyName UpdateReady -NotePropertyValue $false -Force
                $deviceRow | Add-Member -NotePropertyName LocalPackageReady -NotePropertyValue $false -Force
                $deviceRow | Add-Member -NotePropertyName LocalPackageFolder -NotePropertyValue $null -Force
                $deviceRow | Add-Member -NotePropertyName UpdateDownloadSize -NotePropertyValue 0 -Force
                $deviceRow | Add-Member -NotePropertyName MatchCandidateCount -NotePropertyValue 0 -Force
                $deviceRow | Add-Member -NotePropertyName MatchConfidence -NotePropertyValue 'Pending Windows Update check' -Force
                $deviceRow | Add-Member -NotePropertyName MatchReason -NotePropertyValue '' -Force
                $deviceRow | Add-Member -NotePropertyName CandidateOptions -NotePropertyValue @() -Force
                $deviceRow | Add-Member -NotePropertyName RecommendedUpdateId -NotePropertyValue '' -Force
                $deviceRow | Add-Member -NotePropertyName RecommendedUpdateRevision -NotePropertyValue 0 -Force
            }
            [pscustomobject]@{
                ScanStage = 'HardwareReady'
                ComputerManufacturer = [string]$computer.Manufacturer
                ComputerModel = [string]$computer.Model
                BoardManufacturer = $(if ($board) { [string]$board.Manufacturer } else { '' })
                BoardProduct = $(if ($board) { [string]$board.Product } else { '' })
                WindowsCaption = [string]$operatingSystem.Caption
                WindowsVersion = [string]$operatingSystem.Version
                WindowsBuild = [string]$operatingSystem.BuildNumber
                WindowsArchitecture = [string]$operatingSystem.OSArchitecture
                InstalledDriverCount = $signedDriverMap.Count
                HardwareScanSeconds = [math]::Round(($hardwareReadyAt - $driverWorkerStartedAt).TotalSeconds,2)
                Devices = @($deviceRows)
            }

            # Query Microsoft's Windows Update Agent for driver updates currently offered
            # to this exact Windows installation. This is a read-only search: no download
            # or installation is performed. Match candidates by hardware/compatible IDs.
            $wuSearchStartedAt = Get-Date
            $wuDriverUpdates = @()
            $wuScanStatus = 'Unavailable'
            $wuScanMessage = ''
            try {
                $wuSession = New-Object -ComObject Microsoft.Update.Session
                $wuSearcher = $wuSession.CreateUpdateSearcher()
                $wuResult = $wuSearcher.Search("IsInstalled=0 and IsHidden=0 and Type='Driver'")
                for ($updateIndex = 0; $updateIndex -lt $wuResult.Updates.Count; $updateIndex++) {
                    $wuUpdate = $wuResult.Updates.Item($updateIndex)
                    $wuHardwareId = ''
                    $wuVersion = ''
                    $wuManufacturer = ''
                    $wuModel = ''
                    $wuClass = ''
                    try { $wuHardwareId = [string]$wuUpdate.DriverHardwareID } catch {}
                    try { $wuVersion = [string]$wuUpdate.DriverVersion } catch {}
                    try { $wuManufacturer = [string]$wuUpdate.DriverManufacturer } catch {}
                    try { $wuModel = [string]$wuUpdate.DriverModel } catch {}
                    try { $wuClass = [string]$wuUpdate.DriverClass } catch {}
                    $wuDriverDate = [datetime]::MinValue
                    try { if ($wuUpdate.DriverDate) { $wuDriverDate = [datetime]$wuUpdate.DriverDate } } catch {}
                    if (-not [string]::IsNullOrWhiteSpace($wuHardwareId)) {
                        $wuDriverUpdates += [pscustomobject]@{
                            Title = [string]$wuUpdate.Title
                            HardwareId = $wuHardwareId.Trim().ToUpperInvariant()
                            Version = $wuVersion
                            DriverDate = $wuDriverDate
                            Manufacturer = $wuManufacturer
                            Model = $wuModel
                            DriverClass = $wuClass
                            UpdateId = [string]$wuUpdate.Identity.UpdateID
                            UpdateRevision = [int]$wuUpdate.Identity.RevisionNumber
                            IsDownloaded = [bool]$wuUpdate.IsDownloaded
                            MaxDownloadSize = [int64]$wuUpdate.MaxDownloadSize
                        }
                    }
                }
                $wuScanStatus = 'Completed'
                $wuScanMessage = ('Windows Update returned {0} driver candidate(s).' -f $wuDriverUpdates.Count)
            } catch {
                $wuScanStatus = 'Failed'
                $wuScanMessage = [string]$_.Exception.Message
            }

            $wuSearchFinishedAt = Get-Date
            $matchedUpdateCount = 0
            foreach ($deviceRow in $deviceRows) {
                $deviceRow.UpdateStatus = $(if ($wuScanStatus -eq 'Completed') { 'No matching update offered' } else { 'Online check unavailable' })
                $deviceRow.MatchConfidence = 'No match'
                if ($wuScanStatus -ne 'Completed') { continue }
                $deviceHardwareIds = @($deviceRow.HardwareIds | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Where-Object { $_ } | Select-Object -Unique)
                $deviceCompatibleIds = @($deviceRow.CompatibleIds | ForEach-Object { ([string]$_).Trim().ToUpperInvariant() } | Where-Object { $_ } | Select-Object -Unique)
                $rankedMatches = @()

                # Rank every Windows Update candidate for this device instead of
                # accepting the first result returned by the update service.
                # Exact Hardware IDs outrank Compatible IDs; earlier (more
                # specific) IDs in the PnP list outrank broader identifiers.
                foreach ($candidate in $wuDriverUpdates) {
                    $matchTypeRank = 99
                    $matchIdIndex = 9999
                    $matchType = ''
                    for ($idIndex = 0; $idIndex -lt $deviceHardwareIds.Count; $idIndex++) {
                        if ($deviceHardwareIds[$idIndex] -eq [string]$candidate.HardwareId) {
                            $matchTypeRank = 0; $matchIdIndex = $idIndex; $matchType = 'Exact Hardware ID'; break
                        }
                    }
                    if ($matchTypeRank -eq 99) {
                        for ($idIndex = 0; $idIndex -lt $deviceCompatibleIds.Count; $idIndex++) {
                            if ($deviceCompatibleIds[$idIndex] -eq [string]$candidate.HardwareId) {
                                $matchTypeRank = 1; $matchIdIndex = $idIndex; $matchType = 'Compatible ID'; break
                            }
                        }
                    }
                    if ($matchTypeRank -eq 99) { continue }

                    $modelRank = 1
                    $candidateModel = ([string]$candidate.Model).Trim()
                    $deviceName = ([string]$deviceRow.DeviceName).Trim()
                    if ($candidateModel -and $deviceName -and ($candidateModel.IndexOf($deviceName,[StringComparison]::OrdinalIgnoreCase) -ge 0 -or $deviceName.IndexOf($candidateModel,[StringComparison]::OrdinalIgnoreCase) -ge 0)) { $modelRank = 0 }
                    $manufacturerRank = 1
                    $candidateManufacturer = ([string]$candidate.Manufacturer).Trim()
                    $deviceManufacturer = ([string]$deviceRow.Manufacturer).Trim()
                    if ($candidateManufacturer -and $deviceManufacturer -and ($candidateManufacturer.IndexOf($deviceManufacturer,[StringComparison]::OrdinalIgnoreCase) -ge 0 -or $deviceManufacturer.IndexOf($candidateManufacturer,[StringComparison]::OrdinalIgnoreCase) -ge 0)) { $manufacturerRank = 0 }
                    $versionSort = [version]'0.0'
                    try { if (-not [string]::IsNullOrWhiteSpace([string]$candidate.Version)) { $versionSort = [version]([string]$candidate.Version) } } catch {}
                    $rankedMatches += [pscustomobject]@{
                        Candidate = $candidate
                        MatchTypeRank = $matchTypeRank
                        MatchIdIndex = $matchIdIndex
                        MatchType = $matchType
                        ModelRank = $modelRank
                        ManufacturerRank = $manufacturerRank
                        VersionSort = $versionSort
                        DriverDate = [datetime]$candidate.DriverDate
                    }
                }

                $deviceRow.MatchCandidateCount = $rankedMatches.Count
                if ($rankedMatches.Count -gt 0) {
                    # Preserve the full ranked candidate inventory for Professional mode.
                    # The Smart experience still consumes only the top-ranked recommendation.
                    $orderedMatches = @($rankedMatches | Sort-Object @{ Expression = { $_.MatchTypeRank }; Ascending = $true }, @{ Expression = { $_.MatchIdIndex }; Ascending = $true }, @{ Expression = { $_.ModelRank }; Ascending = $true }, @{ Expression = { $_.ManufacturerRank }; Ascending = $true }, @{ Expression = { $_.VersionSort }; Descending = $true }, @{ Expression = { $_.DriverDate }; Descending = $true }, @{ Expression = { $_.Candidate.Title }; Ascending = $true })
                    $candidateOptions = @()
                    $candidateRank = 0
                    foreach ($rankedCandidate in $orderedMatches) {
                        $candidateRank++
                        $candidate = $rankedCandidate.Candidate
                        $candidateOptions += [pscustomobject]@{
                            Rank = $candidateRank
                            Title = [string]$candidate.Title
                            Version = [string]$candidate.Version
                            DriverDate = $(if ($candidate.DriverDate -and [datetime]$candidate.DriverDate -ne [datetime]::MinValue) { ([datetime]$candidate.DriverDate).ToString('yyyy-MM-dd') } else { 'Not supplied' })
                            Manufacturer = [string]$candidate.Manufacturer
                            Model = [string]$candidate.Model
                            DriverClass = [string]$candidate.DriverClass
                            UpdateId = [string]$candidate.UpdateId
                            UpdateRevision = [int]$candidate.UpdateRevision
                            HardwareId = [string]$candidate.HardwareId
                            MatchType = [string]$rankedCandidate.MatchType
                            MatchConfidence = $(if ($rankedCandidate.MatchTypeRank -eq 0) { 'High – exact Hardware ID' } else { 'Moderate – Compatible ID' })
                            MatchIdIndex = [int]$rankedCandidate.MatchIdIndex
                            ModelRank = [int]$rankedCandidate.ModelRank
                            ManufacturerRank = [int]$rankedCandidate.ManufacturerRank
                            IsDownloaded = [bool]$candidate.IsDownloaded
                            MaxDownloadSize = [int64]$candidate.MaxDownloadSize
                            Source = 'Microsoft Windows Update Agent'
                            SourceAdapter = 'WindowsUpdateAgent'
                            SourceUpdateId = [string]$candidate.UpdateId
                            IsInstallable = $false
                            VerificationState = 'Windows Update applicability offered; package validation still pending'
                            SourceType = 'MicrosoftWU'
                            MatchReason = ('{0}; ID priority #{1}; model match={2}; manufacturer match={3}' -f $rankedCandidate.MatchType,($rankedCandidate.MatchIdIndex + 1),($rankedCandidate.ModelRank -eq 0),($rankedCandidate.ManufacturerRank -eq 0))
                        }
                    }
                    $deviceRow.CandidateOptions = @($candidateOptions)
                    # Ranking is deterministic: ID quality/specificity first,
                    # then model/manufacturer hints, then version and date.
                    $bestMatch = $rankedMatches | Sort-Object @{ Expression = { $_.MatchTypeRank }; Ascending = $true }, @{ Expression = { $_.MatchIdIndex }; Ascending = $true }, @{ Expression = { $_.ModelRank }; Ascending = $true }, @{ Expression = { $_.ManufacturerRank }; Ascending = $true }, @{ Expression = { $_.VersionSort }; Descending = $true }, @{ Expression = { $_.DriverDate }; Descending = $true }, @{ Expression = { $_.Candidate.Title }; Ascending = $true } | Select-Object -First 1
                    $matchedUpdate = $bestMatch.Candidate
                    $matchedUpdateCount++
                    $deviceRow.MatchConfidence = $(if ($bestMatch.MatchTypeRank -eq 0) { 'High – exact hardware match' } else { 'Moderate – compatible ID match' })
                    $deviceRow.MatchReason = ('{0}; ID priority #{1}; {2} candidate(s) compared' -f $bestMatch.MatchType,($bestMatch.MatchIdIndex + 1),$rankedMatches.Count)
                    $deviceRow.UpdateStatus = ('Best of {0}: {1}' -f $rankedMatches.Count,$bestMatch.MatchType)
                    $deviceRow.AvailableVersion = $(if ($matchedUpdate.Version) { [string]$matchedUpdate.Version } else { 'Version not supplied' })
                    $deviceRow.AvailableUpdate = [string]$matchedUpdate.Title
                    $deviceRow.UpdateId = [string]$matchedUpdate.UpdateId
                    $deviceRow.UpdateRevision = [int]$matchedUpdate.UpdateRevision
                    $deviceRow.RecommendedUpdateId = [string]$matchedUpdate.UpdateId
                    $deviceRow.RecommendedUpdateRevision = [int]$matchedUpdate.UpdateRevision
                    $deviceRow.UpdateReady = [bool]$matchedUpdate.IsDownloaded
                    $deviceRow.LocalPackageReady = $false
                    $deviceRow.LocalPackageFolder = $null
                    try {
                        $safeDeviceName = ([string]$deviceRow.DeviceId -replace '[^A-Za-z0-9._-]','_')
                        if ($safeDeviceName.Length -gt 70) { $safeDeviceName = $safeDeviceName.Substring(0,70) }
                        $safeUpdateId = ([string]$matchedUpdate.UpdateId -replace '[^A-Fa-f0-9-]','')
                        $localFolder = Join-Path $DriverPackageRoot ('{0}_{1}_r{2}' -f $safeDeviceName,$safeUpdateId,[int]$matchedUpdate.UpdateRevision)
                        $manifestPath = Join-Path $localFolder 'AMR_DriverPackage_Manifest.json'
                        if (Test-Path -LiteralPath $manifestPath -PathType Leaf) {
                            $localManifest = Get-Content -LiteralPath $manifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                            $manifestFilesPresent = (@($localManifest.Files).Count -gt 0)
                            foreach ($manifestFile in @($localManifest.Files)) {
                                $manifestFileName = [string]$manifestFile.FileName
                                if ([IO.Path]::IsPathRooted($manifestFileName) -or [IO.Path]::GetFileName($manifestFileName) -ne $manifestFileName) { $manifestFilesPresent = $false; break }
                                $manifestFilePath = Join-Path $localFolder $manifestFileName
                                if (-not (Test-Path -LiteralPath $manifestFilePath -PathType Leaf)) { $manifestFilesPresent = $false; break }
                                $manifestFileItem = Get-Item -LiteralPath $manifestFilePath -ErrorAction Stop
                                if ([int64]$manifestFileItem.Length -ne [int64]$manifestFile.SizeBytes) { $manifestFilesPresent = $false; break }
                                $manifestFileHash = (Get-FileHash -LiteralPath $manifestFilePath -Algorithm SHA256 -ErrorAction Stop).Hash
                                if (-not $manifestFileHash.Equals([string]$manifestFile.SHA256,[StringComparison]::OrdinalIgnoreCase)) { $manifestFilesPresent = $false; break }
                            }
                            $expandedFilesPresent = (@($localManifest.ExpandedFiles).Count -gt 0)
                            foreach ($expandedFile in @($localManifest.ExpandedFiles)) {
                                $relativeExpanded = [string]$expandedFile.RelativePath
                                if ([IO.Path]::IsPathRooted($relativeExpanded) -or @($relativeExpanded -split '[\\/]') -contains '..') { $expandedFilesPresent = $false; break }
                                $expandedPath = Join-Path (Join-Path $localFolder '_AMR_Expanded') $relativeExpanded
                                if (-not (Test-Path -LiteralPath $expandedPath -PathType Leaf)) { $expandedFilesPresent = $false; break }
                                $expandedItem = Get-Item -LiteralPath $expandedPath -ErrorAction Stop
                                if ([int64]$expandedItem.Length -ne [int64]$expandedFile.SizeBytes) { $expandedFilesPresent = $false; break }
                                $expandedHash = (Get-FileHash -LiteralPath $expandedPath -Algorithm SHA256 -ErrorAction Stop).Hash
                                if (-not $expandedHash.Equals([string]$expandedFile.SHA256,[StringComparison]::OrdinalIgnoreCase)) { $expandedFilesPresent = $false; break }
                            }
                            $catalogTrusted = $false
                            $manifestDeviceId = if (-not [string]::IsNullOrWhiteSpace([string]$localManifest.DeviceId)) { [string]$localManifest.DeviceId } else { [string]$localManifest.DeviceInstanceId }
                            $catalogRelative = [string]$localManifest.CatalogFile
                            if ($catalogRelative -and -not [IO.Path]::IsPathRooted($catalogRelative) -and @($catalogRelative -split '[\\/]') -notcontains '..') {
                                $catalogPath = Join-Path (Join-Path $localFolder '_AMR_Expanded') $catalogRelative
                                if (Test-Path -LiteralPath $catalogPath -PathType Leaf) {
                                    try {
                                        $catalogAudit = Get-AuthenticodeSignature -FilePath $catalogPath -ErrorAction Stop
                                        $catalogTrusted = ([string]$catalogAudit.Status -eq 'Valid' -and [string]$catalogAudit.SignerCertificate.Thumbprint -ieq [string]$localManifest.CatalogSignerThumbprint)
                                    } catch {}
                                }
                            }
                            $manifestInfsPresent = (@($localManifest.InstallableInfFiles).Count -gt 0)
                            foreach ($relativeInf in @($localManifest.InstallableInfFiles)) {
                                $relativeInf = [string]$relativeInf
                                if ([IO.Path]::IsPathRooted($relativeInf) -or @($relativeInf -split '[\\/]') -contains '..') { $manifestInfsPresent = $false; break }
                                $infPath = Join-Path (Join-Path $localFolder '_AMR_Expanded') $relativeInf
                                if (-not (Test-Path -LiteralPath $infPath -PathType Leaf)) { $manifestInfsPresent = $false; break }
                            }
                            if ([bool]$localManifest.Installable -and [string]$localManifest.UpdateId -eq [string]$matchedUpdate.UpdateId -and [int]$localManifest.Revision -eq [int]$matchedUpdate.UpdateRevision -and $manifestDeviceId -ieq [string]$deviceRow.DeviceId -and $manifestInfsPresent -and $manifestFilesPresent -and $expandedFilesPresent -and $catalogTrusted) {
                                $deviceRow.LocalPackageReady = $true
                                $deviceRow.LocalPackageFolder = $localFolder
                                $deviceRow.UpdateReady = $true
                            }
                        }
                    } catch {}
                    $deviceRow.UpdateDownloadSize = [int64]$matchedUpdate.MaxDownloadSize
                    if ($deviceRow.LocalPackageReady) { $deviceRow.UpdateStatus = ('AMR package ready to install • best of {0}' -f $rankedMatches.Count) }
                    elseif ($deviceRow.UpdateReady) { $deviceRow.UpdateStatus = ('Windows Update cache ready • best of {0}' -f $rankedMatches.Count) }
                }
            }

            $enrichmentStartedAt = Get-Date
            $oemProfile = Get-AMRDriverOEMModelProfile -ComputerManufacturer ([string]$computer.Manufacturer) -ComputerModel ([string]$computer.Model) -SystemSKU $systemSku -SystemFamily $systemFamily -ProductVendor $productVendor -ProductName $productName -ProductVersion $productVersion -BoardManufacturer $(if($board){[string]$board.Manufacturer}else{''}) -BoardProduct $(if($board){[string]$board.Product}else{''}) -BoardInventory @($boardSummary)
            foreach($deviceRow in $deviceRows) {
                $coverage = Get-AMRDriverHardwareCoverage -Device $deviceRow
                foreach($property in $coverage.PSObject.Properties) { $deviceRow | Add-Member -NotePropertyName $property.Name -NotePropertyValue $property.Value -Force }
                if([string]::IsNullOrWhiteSpace([string]$deviceRow.HardwareIdVendorHint) -and -not [string]::IsNullOrWhiteSpace([string]$coverage.HardwareVendorName)) { $deviceRow | Add-Member -NotePropertyName HardwareIdVendorHint -NotePropertyValue ([string]$coverage.HardwareVendorName) -Force }
                if([string]::IsNullOrWhiteSpace([string]$deviceRow.HardwareIdVendorCode)) {
                    if($coverage.PciVendorId) { $deviceRow | Add-Member -NotePropertyName HardwareIdVendorCode -NotePropertyValue ('PCI VEN_'+[string]$coverage.PciVendorId) -Force }
                    elseif($coverage.UsbVendorId) { $deviceRow | Add-Member -NotePropertyName HardwareIdVendorCode -NotePropertyValue ('USB VID_'+[string]$coverage.UsbVendorId) -Force }
                    elseif($coverage.AcpiVendorCode) { $deviceRow | Add-Member -NotePropertyName HardwareIdVendorCode -NotePropertyValue ('ACPI '+[string]$coverage.AcpiVendorCode) -Force }
                }
                $deviceRow | Add-Member -NotePropertyName OEMMatchSummary -NotePropertyValue (([string]$oemProfile.OEMVendor+' '+[string]$oemProfile.Confidence).Trim()) -Force
                $deviceRow | Add-Member -NotePropertyName VendorSourceCandidates -NotePropertyValue @(Get-AMRDriverVendorSourceAdapters -Device $deviceRow -OEMProfile $oemProfile -WindowsContext (([string]$operatingSystem.Caption+' '+[string]$operatingSystem.OSArchitecture).Trim())) -Force
            }
            $enrichmentFinishedAt = Get-Date
            $biometricRows = @($deviceRows | Where-Object { [string]$_.ComponentCategory -eq 'Biometric / Smart Card' })
            $biometricIssueCount = @($biometricRows | Where-Object { [int]$_.ErrorCode -ne 0 }).Count
            $biometricSummary = if ($biometricRows.Count -gt 0 -and $biometricIssueCount -gt 0) {
                ('Biometric device(s) detected: {0}; {1} issue(s) require attention.' -f $biometricRows.Count,$biometricIssueCount)
            } elseif ($biometricRows.Count -gt 0) {
                ('Biometric device(s) detected: {0}; Plug and Play reports no current device error.' -f $biometricRows.Count)
            } else {
                'No fingerprint/biometric sensor is currently exposed to Plug and Play. This is not proof that the laptop has no sensor; check BIOS/UEFI, platform firmware and the exact OEM model package.'
            }

            [pscustomobject]@{
                ScanStage = 'Completed'
                BiometricDeviceCount = $biometricRows.Count
                BiometricIssueCount = $biometricIssueCount
                BiometricSummary = $biometricSummary
                OEMModelProfile = $oemProfile
                HardwareScanSeconds = [math]::Round(($hardwareReadyAt - $driverWorkerStartedAt).TotalSeconds,2)
                WUScanSeconds = [math]::Round(($wuSearchFinishedAt - $wuSearchStartedAt).TotalSeconds,2)
                EnrichmentSeconds = [math]::Round(($enrichmentFinishedAt - $enrichmentStartedAt).TotalSeconds,2)
                TotalWorkerSeconds = [math]::Round(($enrichmentFinishedAt - $driverWorkerStartedAt).TotalSeconds,2)
                InstalledDriverCount = $signedDriverMap.Count
                WUScanStatus = $wuScanStatus
                WUScanMessage = $wuScanMessage
                WUDriverCandidateCount = $wuDriverUpdates.Count
                WUMatchedDeviceCount = $matchedUpdateCount
                WUMultipleCandidateDeviceCount = @($deviceRows | Where-Object { [int]$_.MatchCandidateCount -gt 1 }).Count
                ComputerManufacturer = [string]$computer.Manufacturer
                ComputerModel = [string]$computer.Model
                ComputerSystemSKU = $systemSku
                ComputerSystemFamily = $systemFamily
                SystemProductVendor = $productVendor
                SystemProductName = $productName
                SystemProductVersion = $productVersion
                PlatformType = $platformType
                SystemClass = $systemClass
                IdentityConfidence = $identityConfidence
                SystemIdentitySummary = ('{0} • {1} (identity confidence: {2}) • SKU: {3} • Family: {4} • SMBIOS product: {5} {6} • BIOS: {7} • CPU: {8} • GPU(s): {9} • Board(s): {10}' -f $platformType,$systemClass,$identityConfidence,$(if($systemSku){$systemSku}else{'not supplied'}),$(if($systemFamily){$systemFamily}else{'not supplied'}),$productVendor,$productName,$(if($bios -and $bios.SMBIOSBIOSVersion){[string]$bios.SMBIOSBIOSVersion}else{'not supplied'}),$(if($processors.Count){$processors -join '; '}else{'not detected'}),$(if($videoControllers.Count){$videoControllers -join '; '}else{'not detected'}),$(if($boardSummary.Count){$boardSummary -join '; '}else{'not detected'}))
                ProcessorNames = @($processors)
                VideoControllerNames = @($videoControllers)
                BoardInventory = @($boardSummary)
                ChassisTypes = @($chassisCodes)
                BoardManufacturer = $(if ($board) { [string]$board.Manufacturer } else { '' })
                BoardProduct = $(if ($board) { [string]$board.Product } else { '' })
                BIOSVersion = $(if ($bios) { [string]$bios.SMBIOSBIOSVersion } else { '' })
                WindowsCaption = [string]$operatingSystem.Caption
                WindowsVersion = [string]$operatingSystem.Version
                WindowsBuild = [string]$operatingSystem.BuildNumber
                WindowsArchitecture = [string]$operatingSystem.OSArchitecture
                Devices = @($deviceRows)
                ScanTime = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
            }
        }

        $scanGeneration=[int]$script:DriverOperationState.Generation+1
        $script:DriverOperationState=[pscustomobject]@{Name='DeviceScan';State='Running';StartedAt=(Get-Date);Generation=$scanGeneration;ScanGeneration=[int]$script:DriverScanGeneration;CanCancel=$false;Status='Scanning devices and Windows Update';PartialShown=$false}
        if (-not $script:DriverScanTimer) {
            $script:DriverScanTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:DriverScanTimer.Interval = [TimeSpan]::FromMilliseconds(500)
            $script:DriverScanTimer.Add_Tick({
                $job = $script:DriverScanJob
                if (-not $job) {
                    $script:DriverScanTimer.Stop()
                    Release-AMRDriverOperationLock
                    try {
                        if ($script:DriverOperationState.Name -eq 'DeviceScan') { $script:DriverOperationState = [pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready'; PartialShown=$false } }
                        $scanButton = C 'ScanDriversBtn'
                        if ($scanButton) { $scanButton.IsEnabled = $true; $scanButton.Content = '⌕  Scan Device' }
                        (C 'DriverScanStatus').Text = 'Scan stopped because its background job reference was lost. Start a new scan; review Diagnostics if this repeats.'
                        Write-AMRDiagnostic -Severity 'ERROR' -Area 'DriverCenter' -Operation 'ScanJobMissing' -Message 'The scan timer fired but DriverScanJob was null; UI state was recovered.'
                        Write-AMRDriverDiagnostic -Severity ERROR -Operation DeviceScan -Stage JobReferenceLost -Message 'The scan timer lost its background job reference; the interface was recovered and a new scan is required.' -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -Source 'DriverScanTimer' -Result 'Failed'
                        Update-AMRDriverActionButtons
                    } catch { Write-AMRDiagnostic -Severity 'ERROR' -Area 'DriverCenter' -Operation 'ScanJobMissingRecovery' -Message 'Failed to recover the scan UI after the background job reference was lost.' -ErrorRecord $_ }
                    return
                }
                if ($job.State -eq 'Running') {
                    if (Test-AMRDriverOperationTimeout -Operation 'Scan' -StartedAt ([datetime]$script:DriverScanStartedAt)) {
                        try { Stop-Job -Job $job -ErrorAction SilentlyContinue; Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {}
                        $script:DriverScanJob = $null; $script:DriverScanTimer.Stop(); Release-AMRDriverOperationLock
                        if($script:DriverOperationState.Name -eq 'DeviceScan'){$script:DriverOperationState=[pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready';PartialShown=$false}}
                        Write-AMRDriverTimeoutEvent -Operation DeviceScan -Message 'Driver scan exceeded its 600-second timeout.' -OperationId ([string]$script:DriverCurrentScanId)
                        (C 'DriverScanStatus').Text = 'Driver scan timed out. The operation was stopped; review Diagnostics and scan again.'
                        $scanButton = C 'ScanDriversBtn'; if ($scanButton) { $scanButton.IsEnabled=$true; $scanButton.Content='⌕  Scan Device' }
                        Update-AMRDriverActionButtons
                        return
                    }
                    try {
                        $availableStages = @()
                        if (-not [bool](Get-AMRDiagProp $script:DriverOperationState 'PartialShown' $false)) {
                            $availableStages = @(Receive-Job -Job $job -Keep -ErrorAction SilentlyContinue)
                        }
                        $hardwareStage = @($availableStages | Where-Object { $_ -and $_.ScanStage -eq 'HardwareReady' } | Select-Object -Last 1)
                        if ($hardwareStage.Count -gt 0 -and -not [bool](Get-AMRDiagProp $script:DriverOperationState 'PartialShown' $false)) {
                            if (-not $script:DriverOperationState.PSObject.Properties['PartialShown']) { $script:DriverOperationState | Add-Member -NotePropertyName PartialShown -NotePropertyValue $false -Force }
                            $script:DriverOperationState.PartialShown = $true
                            $stage = $hardwareStage[0]
                            $stageDevices = @($stage.Devices)
                            Write-AMRDriverDiagnostic -Severity TRACE -Operation DeviceScan -Stage HardwareInventoryReady -Message 'Initial Plug and Play hardware inventory is available; Windows Update matching is continuing.' -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -Source 'HardwareDiscoveryWorker' -DurationMs ([long]((Get-Date)-$script:DriverScanStartedAt).TotalMilliseconds) -Context @{DeviceCount=$stageDevices.Count;Generation=$script:DriverScanGeneration;ComputerModel=[string]$stage.ComputerModel;Manufacturer=[string]$stage.ComputerManufacturer}
                            $script:DriverAllDeviceRows = @($stageDevices)
                            foreach ($driverSearchRow in @($script:DriverAllDeviceRows)) {
                                if ($driverSearchRow -and -not $driverSearchRow.PSObject.Properties['DriverSearchDisplay']) {
                                    $driverSearchRow | Add-Member -NotePropertyName DriverSearchDisplay -NotePropertyValue ([string]$driverSearchRow.AvailableUpdate) -Force
                                }
                                # A8 driver fix: the early HardwareReady rows have no update metadata yet; the progressive
                                # display read ProfessionalDiscoveredCandidates and failed under StrictMode.
                                if ($driverSearchRow) {
                                    foreach ($field in @(
                                        @{Name='ErrorCode';Value=0},@{Name='UpdateId';Value=''},@{Name='UpdateReady';Value=$false},
                                        @{Name='LocalPackageReady';Value=$false},@{Name='CandidateOptions';Value=@()},
                                        @{Name='ProfessionalDiscoveredCandidates';Value=@()},@{Name='VendorPackageCandidates';Value=@()},@{Name='ProfessionalSelectedCandidate';Value=$null},
                                        @{Name='AvailableUpdate';Value=''},@{Name='AvailableVersion';Value=''},
                                        @{Name='HardwareIds';Value=@()},@{Name='CompatibleIds';Value=@()}
                                    )) {
                                        if (-not $driverSearchRow.PSObject.Properties[$field.Name]) {
                                            $driverSearchRow | Add-Member -NotePropertyName $field.Name -NotePropertyValue $field.Value -Force
                                        }
                                    }
                                }
                            }
                            (C 'DriverComputerModel').Text = $(if([string]::IsNullOrWhiteSpace([string]$stage.ComputerModel)){'Model unavailable'}else{[string]$stage.ComputerModel})
                            (C 'DriverComputerManufacturer').Text = 'Manufacturer: ' + $(if($stage.ComputerManufacturer){[string]$stage.ComputerManufacturer}else{'Unknown'})
                            (C 'DriverBoardModel').Text = $(if($stage.BoardProduct){[string]$stage.BoardProduct}else{'Motherboard model unavailable'})
                            (C 'DriverBoardManufacturer').Text = 'Manufacturer: ' + $(if($stage.BoardManufacturer){[string]$stage.BoardManufacturer}else{'Unknown'})
                            (C 'DriverWindowsInfo').Text = ('{0} • {1} • Build {2} • {3}' -f $stage.WindowsCaption,$stage.WindowsVersion,$stage.WindowsBuild,$stage.WindowsArchitecture)
                            (C 'DriverDeviceCount').Text = [string]$stageDevices.Count
                            (C 'DriverProblemCount').Text = [string]@($stageDevices | Where-Object { [int]$_.ErrorCode -ne 0 }).Count
                            Set-AMRDriverExperienceMode -Mode $script:DriverExperienceMode
                            (C 'DriverScanStatus').Text = ('Hardware inventory ready: {0} devices detected. Windows Update driver matching is continuing in the background; the interface is available.' -f $stageDevices.Count)
                            (C 'DriverActionStatus').Text = 'Device inventory is ready. AMR is checking applicable Windows Update driver candidates in the background.'
                        }
                    } catch {
                        Write-AMRDiagnostic -Severity 'WARNING' -Area 'DriverCenter' -Operation 'ProgressiveHardwareDisplay' -Message ([string]$_.Exception.Message) -ErrorRecord $_
                        Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceScan -Stage PartialDisplayFailed -Message 'The progressive hardware inventory could not be displayed while the scan continued.' -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -Source 'DriverScanTimer' -ErrorRecord $_
                    }
                    return
                }
                if ($job.State -notin @('Completed','Failed','Stopped')) { return }

                $script:DriverScanTimer.Stop()
                Release-AMRDriverOperationLock
                try {
                    if ($job.State -ne 'Completed') {
                        $jobState = [string]$job.State
                        $jobReason = ''
                        try { if ($job.JobStateInfo -and $job.JobStateInfo.Reason) { $jobReason = [string]$job.JobStateInfo.Reason } } catch {}
                        $jobErrorLines = @()
                        try { foreach ($child in @($job.ChildJobs)) { foreach ($record in @($child.Error)) { $jobErrorLines += [string]$record.ToString() } } } catch {}
                        try { $null = Receive-Job -Job $job -ErrorAction SilentlyContinue -ErrorVariable receiveErrors 2>&1; foreach ($record in @($receiveErrors)) { $jobErrorLines += [string]$record.ToString() } } catch { $jobErrorLines += [string]$_.Exception.Message }
                        $detail = @('State: '+$jobState)
                        if ($jobReason) { $detail += 'Reason: '+$jobReason }
                        if ($jobErrorLines.Count -gt 0) { $detail += 'Worker errors: '+($jobErrorLines -join ' | ') }
                        $failureText = $detail -join ' | '
                        Write-AMRDiagnostic -Severity 'ERROR' -Area 'DriverCenter' -Operation 'ScanBackgroundJob' -Message $failureText -Target ('JobId='+[string]$job.Id)
                        throw ('Hardware scan background job did not complete. '+$failureText)
                    }

                    $receivedScanRecords = @(Receive-Job -Job $job -ErrorAction Stop)
                    $scanResult = @($receivedScanRecords | Where-Object { $_ -and $_.ScanStage -eq 'Completed' } | Select-Object -Last 1)
                    if($scanResult.Count -eq 0) { $scanResult = @($receivedScanRecords | Select-Object -Last 1) }
                    if ($scanResult.Count -eq 0 -or -not $scanResult[0]) { throw 'The hardware scan returned no final results.' }
                    $scanResult = $scanResult[0]

                    $devices = @($scanResult.Devices | Sort-Object @{ Expression = { if ([int]$_.ErrorCode -ne 0) { 0 } else { 1 } } }, DeviceClass, DeviceName)
                    $script:DriverOEMModelProfile = $scanResult.OEMModelProfile
                    foreach($deviceRow in $devices){
                        # Normalize scan-result state on the UI thread. Some provider/result paths
                        # can return a row without optional update metadata; strict mode must not
                        # let a missing UpdateReady property abort the DispatcherTimer callback.
                        if(-not $deviceRow.PSObject.Properties['UpdateReady']){$deviceRow | Add-Member -NotePropertyName UpdateReady -NotePropertyValue $false -Force}
                        if(-not $deviceRow.PSObject.Properties['UpdateId']){$deviceRow | Add-Member -NotePropertyName UpdateId -NotePropertyValue '' -Force}
                        if(-not $deviceRow.PSObject.Properties['UpdateRevision']){$deviceRow | Add-Member -NotePropertyName UpdateRevision -NotePropertyValue 0 -Force}
                        # Initialize optional per-device state before strict-mode UI handlers inspect it.
                        if(-not $deviceRow.PSObject.Properties['ProfessionalDiscoveredCandidates']){$deviceRow | Add-Member -NotePropertyName ProfessionalDiscoveredCandidates -NotePropertyValue @() -Force}
                        if(-not $deviceRow.PSObject.Properties['VendorPackageCandidates']){$deviceRow | Add-Member -NotePropertyName VendorPackageCandidates -NotePropertyValue @() -Force}
                        if(-not $deviceRow.PSObject.Properties['VendorPackageDiscoveryErrors']){$deviceRow | Add-Member -NotePropertyName VendorPackageDiscoveryErrors -NotePropertyValue @() -Force}
                        if(-not $deviceRow.PSObject.Properties['ProfessionalSelectedCandidate']){$deviceRow | Add-Member -NotePropertyName ProfessionalSelectedCandidate -NotePropertyValue $null -Force}
                        if(-not $deviceRow.PSObject.Properties['SourceAdapter']){$deviceRow | Add-Member -NotePropertyName SourceAdapter -NotePropertyValue '' -Force}
                        if(-not $deviceRow.PSObject.Properties['LocalPackageReady']){$deviceRow | Add-Member -NotePropertyName LocalPackageReady -NotePropertyValue $false -Force}
                        if(-not $deviceRow.PSObject.Properties['LocalPackageFolder']){$deviceRow | Add-Member -NotePropertyName LocalPackageFolder -NotePropertyValue '' -Force}
                        if(-not $deviceRow.PSObject.Properties['HardwareIds']){$deviceRow | Add-Member -NotePropertyName HardwareIds -NotePropertyValue @() -Force}
                        if(-not $deviceRow.PSObject.Properties['CompatibleIds']){$deviceRow | Add-Member -NotePropertyName CompatibleIds -NotePropertyValue @() -Force}
                        if(-not $deviceRow.PSObject.Properties['HardwareIdVendorHint']){$deviceRow | Add-Member -NotePropertyName HardwareIdVendorHint -NotePropertyValue '' -Force}
                        if(-not $deviceRow.PSObject.Properties['HardwareIdVendorCode']){$deviceRow | Add-Member -NotePropertyName HardwareIdVendorCode -NotePropertyValue '' -Force}
                    }
                    $issueCount = @($devices | Where-Object { [int]$_.ErrorCode -ne 0 }).Count
                    (C 'DriverComputerModel').Text = $(if ([string]::IsNullOrWhiteSpace($scanResult.ComputerModel)) { 'Model unavailable' } else { [string]$scanResult.ComputerModel })
                    (C 'DriverComputerManufacturer').Text = 'Manufacturer: ' + $(if ($scanResult.ComputerManufacturer) { $scanResult.ComputerManufacturer } else { 'Unknown' })
                    (C 'DriverBoardModel').Text = $(if ($scanResult.BoardProduct) { [string]$scanResult.BoardProduct } else { 'Motherboard model unavailable' })
                    (C 'DriverBoardManufacturer').Text = 'Manufacturer: ' + $(if ($scanResult.BoardManufacturer) { $scanResult.BoardManufacturer } else { 'Unknown' })
                    (C 'DriverSystemIdentitySummary').Text = ([string]$scanResult.SystemIdentitySummary + ' • OEM/model match: ' + [string]$script:DriverOEMModelProfile.IdentityClass + ' (' + [string]$script:DriverOEMModelProfile.Confidence + ')' + ' • Matched OEM: ' + $(if($script:DriverOEMModelProfile.OEMVendor){[string]$script:DriverOEMModelProfile.OEMVendor}else{'not resolved'}) + ' • Board vendor: ' + $(if($script:DriverOEMModelProfile.BoardVendor){[string]$script:DriverOEMModelProfile.BoardVendor}else{'not resolved'}))
                    (C 'DriverWindowsInfo').Text = ('{0} • {1} • Build {2} • {3}' -f $scanResult.WindowsCaption, $scanResult.WindowsVersion, $scanResult.WindowsBuild, $scanResult.WindowsArchitecture)
                    $script:DriverCatalogWindowsContext = (([string]$scanResult.WindowsCaption + ' ' + [string]$scanResult.WindowsArchitecture).Trim())
                    $script:DriverComputerModel = [string]$scanResult.ComputerModel
                    $script:DriverBoardModel = [string]$scanResult.BoardProduct
                    $script:DriverWindowsContext = [string]$script:DriverCatalogWindowsContext
                    (C 'DriverDeviceCount').Text = [string]$devices.Count
                    (C 'DriverProblemCount').Text = [string]$issueCount
                    $script:DriverAllDeviceRows = @($devices)
                    foreach ($driverSearchRow in @($script:DriverAllDeviceRows)) {
                        if ($driverSearchRow -and -not $driverSearchRow.PSObject.Properties['DriverSearchDisplay']) {
                            $driverSearchRow | Add-Member -NotePropertyName DriverSearchDisplay -NotePropertyValue ([string]$driverSearchRow.AvailableUpdate) -Force
                        }
                    }
                    (C 'DriverDeviceList').SelectedItems.Clear()
                    Set-AMRDriverExperienceMode -Mode $script:DriverExperienceMode
                    Update-AMRDriverActionButtons
                    $readyCount = @($devices | Where-Object { $_.UpdateReady }).Count
                    $updateMatchCount = [int]$scanResult.WUMatchedDeviceCount
                    $wuSummary = if ($scanResult.WUScanStatus -eq 'Completed') {
                        ('Microsoft Windows Update check completed: {0} applicable driver candidate(s), {1} device match(es), {2} device(s) had multiple candidates ranked, {3} already downloaded and ready.' -f $scanResult.WUDriverCandidateCount, $updateMatchCount, [int]$scanResult.WUMultipleCandidateDeviceCount, $readyCount)
                    } else {
                        ('Microsoft Windows Update check unavailable: {0}' -f $scanResult.WUScanMessage)
                    }
                    $identifiedVendorCount=@($devices | Where-Object { $_.HardwareVendorName }).Count
                    $directIdVendorCount=@($devices | Where-Object { $_.HardwareCoverageStatus -in @('PCI vendor identified','USB vendor identified','Audio codec vendor identified','ACPI vendor identified') }).Count
                    $unresolvedVendorCount=@($devices | Where-Object { -not $_.HardwareVendorName }).Count
                    $sourceLeadCount=@($devices | ForEach-Object { @($_.VendorSourceCandidates).Count } | Measure-Object -Sum).Sum
                    $biometricSummary = [string]$scanResult.BiometricSummary
                    $driverScanSummaryText = ('Scan completed {0}. {1} devices; {2} device issue(s); {3} installed driver records; {4} vendor identities resolved ({5} from direct hardware identifiers); {6} devices with unresolved vendor identity; {7} official source leads prepared. {8} {9} {10} Use Smart Select to review the available driver choices, then Smart Install to prepare only your approved selections.' -f $scanResult.ScanTime, $devices.Count, $issueCount, $scanResult.InstalledDriverCount, $identifiedVendorCount, $directIdVendorCount, $unresolvedVendorCount, $sourceLeadCount, $wuSummary, $biometricSummary, 'Exact Hardware ID matches remain primary; OEM/model context is supporting evidence and unverified source leads cannot install.')
                    try { (C 'DriverScanStatus').Text = '' } catch {}
                    try { Write-AMRDriverDiagnostic -Severity INFO -Operation DeviceScan -Stage ScanSummary -Message $driverScanSummaryText -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -Source 'DriverCenterScanSummary' } catch {}

                    $support = Get-AMRDriverSupportSource -ComputerManufacturer ([string]$scanResult.ComputerManufacturer) -BoardManufacturer ([string]$scanResult.BoardManufacturer)
                    $script:DriverSupportUrl = $support.Url
                    $script:DriverSupportName = $support.Name
                    $supportButton = C 'OpenOfficialSupportBtn'
                    $supportButton.IsEnabled = $true
                    $supportButton.Content = 'Open ' + $support.Name + ' ↗'
                    Write-AMRLog ("Driver Center scan completed. Computer='{0} {1}', SystemClass='{2}', Platform='{3}', IdentityConfidence='{4}', SKU='{5}', Board='{6}', Boards={7}, CPUs={8}, GPUs={9}, Devices={10}, Issues={11}, WU candidates={12}, WU device matches={13}, multi-candidate devices={14}, WU status={15}, Support='{16}', Hardware={17}s, WU={18}s, Enrichment={19}s, Total={20}s." -f $scanResult.ComputerManufacturer, $scanResult.ComputerModel, $scanResult.SystemClass, $scanResult.PlatformType, $scanResult.IdentityConfidence, $scanResult.ComputerSystemSKU, $scanResult.BoardProduct, @($scanResult.BoardInventory).Count, @($scanResult.ProcessorNames).Count, @($scanResult.VideoControllerNames).Count, $devices.Count, $issueCount, $scanResult.WUDriverCandidateCount, $scanResult.WUMatchedDeviceCount, $scanResult.WUMultipleCandidateDeviceCount, $scanResult.WUScanStatus, $support.Name, $scanResult.HardwareScanSeconds, $scanResult.WUScanSeconds, $scanResult.EnrichmentSeconds, $scanResult.TotalWorkerSeconds) SUCCESS Overview
                    Write-AMRDriverDiagnostic -Severity SUCCESS -Operation DeviceScan -Stage Completed -Message 'Device discovery and driver inventory scan completed.' -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -Source 'CIM/WMI + Windows Update' -DurationMs ([long]((Get-Date)-$script:DriverScanStartedAt).TotalMilliseconds) -Result 'Completed' -Context @{DeviceCount=$devices.Count;IssueCount=$issueCount;InstalledDriverCount=$scanResult.InstalledDriverCount;WUCandidateCount=$scanResult.WUDriverCandidateCount;WUMatchedDeviceCount=$scanResult.WUMatchedDeviceCount;WUStatus=$scanResult.WUScanStatus;BiometricDeviceCount=$scanResult.BiometricDeviceCount;BiometricIssueCount=$scanResult.BiometricIssueCount;Generation=$script:DriverScanGeneration}
                    try { $script:Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle,[Action]{ Start-AMRDriverAutoDiagnosis }) | Out-Null } catch {}
                } catch {
                    $scanFailure = $_
                    $failureMessage = [string]$scanFailure.Exception.Message
                    try { (C 'DriverScanStatus').Text = 'Scan failed: ' + $failureMessage } catch {}
                    Write-AMRLog ('Driver Center scan failed: ' + $failureMessage) ERROR Overview
                    Write-AMRDriverDiagnostic -Severity ERROR -Operation DeviceScan -Stage Failed -Message 'Driver Center device discovery failed.' -ScanId $script:DriverCurrentScanId -OperationId $script:DriverCurrentScanId -DurationMs ([long]((Get-Date)-$script:DriverScanStartedAt).TotalMilliseconds) -Result 'Failed' -ErrorRecord $scanFailure -Context @{Generation=$script:DriverScanGeneration}
                    Write-AMRDiagnostic -Severity 'ERROR' -Area 'DriverCenter' -Operation 'ScanResultProcessing' -Message $failureMessage -ErrorRecord $scanFailure -Target ('Generation='+[string]$script:DriverScanGeneration)
                } finally {
                    try { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {}
                    $script:DriverScanJob = $null
                    if (-not $script:DriverOperationState.PSObject.Properties['PartialShown']) { $script:DriverOperationState | Add-Member -NotePropertyName PartialShown -NotePropertyValue $false -Force }
                    $script:DriverOperationState.PartialShown = $false
                    if($script:DriverOperationState.Name -eq 'DeviceScan'){$script:DriverOperationState=[pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready'; PartialShown=$false }}
                    $scanButton = C 'ScanDriversBtn'
                    $scanButton.IsEnabled = $true
                    $scanButton.Content = '⌕  Scan Device'
                    # A13c (b): a failure while refreshing the buttons must be logged with its real message and
                    # must never leave the Scan button disabled or the operation lock held.
                    try { Release-AMRDriverOperationLock } catch {}
                    try { Update-AMRDriverActionButtons } catch {
                        $buttonRefreshError = $_
                        try { Write-AMRDriverDiagnostic -Severity ERROR -Operation DeviceScan -Stage ButtonRefreshFailed -Message ('Refreshing the Driver Center buttons after the scan failed: ' + $buttonRefreshError.Exception.Message) -ScanId $script:DriverCurrentScanId -Source 'Start-AMRDriverScan' -ErrorRecord $buttonRefreshError } catch {}
                        try { Write-AMRDiagnostic -Severity 'ERROR' -Area 'DriverCenter' -Operation 'ScanButtonRefresh' -Message ([string]$buttonRefreshError.Exception.Message) -ErrorRecord $buttonRefreshError } catch {}
                        try { $scanButton.IsEnabled = $true } catch {}
                    }
                }
            })
        }
        $script:DriverScanTimer.Start()
        Write-AMRLog 'Started asynchronous hardware and Windows device discovery.' INFO Overview
    } catch {
        $scanStartFailure = $_
        if ($script:DriverScanTimer) { $script:DriverScanTimer.Stop() }
        if ($script:DriverScanJob) { try { Stop-Job -Job $script:DriverScanJob -ErrorAction SilentlyContinue } catch {}; try { Remove-Job -Job $script:DriverScanJob -Force -ErrorAction SilentlyContinue } catch {} }
        $script:DriverScanJob = $null
        Release-AMRDriverOperationLock
        if($script:DriverOperationState.Name -eq 'DeviceScan'){$script:DriverOperationState=[pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready';PartialShown=$false}}
        $button.IsEnabled = $true
        $button.Content = '⌕  Scan Device'
        Update-AMRDriverActionButtons
        (C 'DriverScanStatus').Text = 'Could not start scan: ' + $scanStartFailure.Exception.Message
        Write-AMRLog ('Could not start Driver Center scan: ' + $scanStartFailure.Exception.Message) ERROR Overview
        Write-AMRDiagnostic -Severity 'ERROR' -Area 'DriverCenter' -Operation 'ScanStart' -Message ([string]$scanStartFailure.Exception.Message) -ErrorRecord $scanStartFailure -Target ('Generation='+[string]$script:DriverScanGeneration)
    }
}

# Driver update actions use Windows Update Agent only for updates explicitly offered
# to this machine. No third-party driver-pack executables are downloaded or run.
function Test-AMRDriverSearchTokens {
    param([string]$Text,[string[]]$Tokens)
    if (-not $Tokens -or $Tokens.Count -eq 0) { return $true }
    if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
    foreach ($token in $Tokens) {
        if ($Text.IndexOf([string]$token,[System.StringComparison]::OrdinalIgnoreCase) -lt 0) { return $false }
    }
    return $true
}

function Get-AMRDriverSearchObjectText {
    param([object]$InputObject)
    if ($null -eq $InputObject) { return '' }
    $parts = New-Object 'System.Collections.Generic.List[string]'
    foreach ($propertyName in @('Title','Name','DriverName','PackageName','DisplayName','Version','DriverVersion','Manufacturer','Model','DeviceName','DeviceClass','DriverClass','Description','Provider','Source','HardwareId','HardwareIds','CompatibleIds','PackageId','SoftPaqId','MatchReason','SearchTerms')) {
        try {
            $property = $InputObject.PSObject.Properties[$propertyName]
            if ($property -and $null -ne $property.Value) {
                if ($property.Value -is [System.Collections.IEnumerable] -and $property.Value -isnot [string]) {
                    $valueText = (@($property.Value | ForEach-Object { [string]$_ }) -join ' ')
                } else { $valueText = [string]$property.Value }
                if (-not [string]::IsNullOrWhiteSpace($valueText)) { [void]$parts.Add($valueText) }
            }
        } catch {}
    }
    return [string]::Join(' ',$parts.ToArray())
}

function Update-AMRDriverSearchView {
    param([string]$Query = [string]$script:DriverSearchQuery)

    $script:DriverSearchQuery = [string]$Query
    $list = C 'DriverDeviceList'
    if (-not $list) { return }

    $sourceRows = @($script:DriverAllDeviceRows)
    $tokens = @()
    if (-not [string]::IsNullOrWhiteSpace($Query)) {
        $tokens = @(([string]$Query).Trim() -split '\s+' | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    }

    # Normalize optional fields before filtering; this keeps StrictMode-safe behavior
    # for progressive scan rows and rows produced by older discovery paths.
    foreach ($row in $sourceRows) {
        if ($null -eq $row) { continue }
        foreach ($field in @(
            @{Name='ErrorCode';Value=0},@{Name='UpdateId';Value=''},@{Name='UpdateReady';Value=$false},
            @{Name='LocalPackageReady';Value=$false},@{Name='CandidateOptions';Value=@()},
            @{Name='ProfessionalDiscoveredCandidates';Value=@()},@{Name='VendorPackageCandidates';Value=@()},@{Name='ProfessionalSelectedCandidate';Value=$null},
            @{Name='AvailableUpdate';Value=''},@{Name='AvailableVersion';Value=''},
            @{Name='HardwareIds';Value=@()},@{Name='CompatibleIds';Value=@()}
        )) {
            if (-not $row.PSObject.Properties[$field.Name]) {
                $row | Add-Member -NotePropertyName $field.Name -NotePropertyValue $field.Value -Force
            }
        }
    }

    # In Smart mode the default view stays focused on actionable rows. As soon
    # as the user searches, include the complete detected inventory so installed
    # drivers without an offered update can also be found by name.
    if ($script:DriverExperienceMode -eq 'Smart' -and $tokens.Count -eq 0) {
        $sourceRows = @($sourceRows | Where-Object {
            ([int]$_.ErrorCode -ne 0) -or
            (-not [string]::IsNullOrWhiteSpace([string]$_.UpdateId)) -or
            [bool]$_.UpdateReady -or [bool]$_.LocalPackageReady -or
            @($_.CandidateOptions).Count -gt 0 -or
            @($_.ProfessionalDiscoveredCandidates).Count -gt 0 -or
            @($_.VendorPackageCandidates).Count -gt 0
        })
    }

    $visibleRows = New-Object 'System.Collections.Generic.List[object]'
    foreach ($row in $sourceRows) {
        if ($null -eq $row) { continue }
        $displayText = [string]$row.AvailableUpdate
        $isMatch = ($tokens.Count -eq 0)
        $matchedCandidateDisplay = ''
        $matchedCandidateRank = ''

        if ($tokens.Count -gt 0) {
            $rowTextParts = New-Object 'System.Collections.Generic.List[string]'
            foreach ($propertyName in @('DeviceName','DriverName','DriverDescription','DeviceClass','Manufacturer','StatusText','DriverProvider','DriverVersion','DriverDate','DriverInf','DeviceId','HardwareIdVendorCode','HardwareIdVendorHint','UpdateStatus','AvailableUpdate','AvailableVersion','MatchConfidence','MatchReason','Service','SourceAdapter')) {
                try {
                    $property = $row.PSObject.Properties[$propertyName]
                    if ($property -and $null -ne $property.Value) { [void]$rowTextParts.Add([string]$property.Value) }
                } catch {}
            }
            foreach ($idValue in @($row.HardwareIds) + @($row.CompatibleIds)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$idValue)) { [void]$rowTextParts.Add([string]$idValue) }
            }

            foreach ($collectionName in @('CandidateOptions','ProfessionalDiscoveredCandidates','VendorPackageCandidates','ProfessionalSelectedCandidate')) {
                try {
                    $collectionProperty = $row.PSObject.Properties[$collectionName]
                    if (-not $collectionProperty -or $null -eq $collectionProperty.Value) { continue }
                    foreach ($candidate in @($collectionProperty.Value)) {
                        if ($null -eq $candidate) { continue }
                        $candidateText = Get-AMRDriverSearchObjectText -InputObject $candidate
                        if ($candidateText) { [void]$rowTextParts.Add($candidateText) }
                        if (-not $matchedCandidateDisplay -and (Test-AMRDriverSearchTokens -Text $candidateText -Tokens $tokens)) {
                            foreach ($displayPropertyName in @('Title','DriverName','PackageName','Name','DisplayName')) {
                                try {
                                    $displayProperty = $candidate.PSObject.Properties[$displayPropertyName]
                                    if ($displayProperty -and -not [string]::IsNullOrWhiteSpace([string]$displayProperty.Value)) {
                                        $matchedCandidateDisplay = [string]$displayProperty.Value
                                        try {
                                            $rankProperty = $candidate.PSObject.Properties['Rank']
                                            if ($rankProperty -and $null -ne $rankProperty.Value) { $matchedCandidateRank = [string]$rankProperty.Value }
                                        } catch {}
                                        break
                                    }
                                } catch {}
                            }
                        }
                    }
                } catch {}
            }

            $rowText = [string]::Join(' ',$rowTextParts.ToArray())
            $isMatch = (-not [string]::IsNullOrWhiteSpace($matchedCandidateDisplay)) -or (Test-AMRDriverSearchTokens -Text $rowText -Tokens $tokens)
            if ($isMatch) {
                if ($matchedCandidateDisplay) {
                    if ($displayText -and $matchedCandidateDisplay -ine $displayText) {
                        $rankLabel = if ($matchedCandidateRank) { ' (candidate rank ' + $matchedCandidateRank + ')' } else { '' }
                        $displayText = ('Search match: {0}{1} | Recommended: {2}' -f $matchedCandidateDisplay,$rankLabel,[string]$row.AvailableUpdate)
                    } else { $displayText = $matchedCandidateDisplay }
                } elseif ([string]::IsNullOrWhiteSpace($displayText)) { $displayText = 'Matched device: ' + [string]$row.DeviceName }
            }
        }

        if (-not $row.PSObject.Properties['DriverSearchDisplay']) {
            $row | Add-Member -NotePropertyName DriverSearchDisplay -NotePropertyValue $displayText -Force
        } else { $row.DriverSearchDisplay = $displayText }

        if ($isMatch) { [void]$visibleRows.Add($row) }
    }

    # Keep the complete scan inventory in DriverAllDeviceRows. Only the ListView's
    # presentation array is filtered, so search never deletes or rewrites driver data.
    $list.ItemsSource = @($visibleRows.ToArray())
    try { $list.SelectedItems.Clear() } catch {}
    try { Update-AMRDriverActionButtons } catch {}
    if ($tokens.Count -gt 0) {
        $status = C 'DriverActionStatus'
        if ($status) {
            $status.Text = if ($visibleRows.Count -gt 0) {
                ('Driver search: {0} matching device/driver row(s) for "{1}". The original scan inventory is unchanged.' -f $visibleRows.Count,$Query)
            } else {
                ('No driver or device matched "{0}". Try a shorter driver name, vendor, hardware ID or version.' -f $Query)
            }
        }
    }
}

function Set-AMRDriverExperienceMode {
    param([ValidateSet('Smart','Advanced')][string]$Mode)

    $script:DriverExperienceMode = $Mode
    $smartButton = C 'DriverSmartModeBtn'
    $advancedButton = C 'DriverAdvancedModeBtn'
    $description = C 'DriverModeDescription'
    $modeEyebrow = C 'DriverModeEyebrow'
    $modeHeading = C 'DriverModeSectionHeading'
    $deviceList = C 'DriverDeviceList'
    $scrollViewer = C 'DriverCenterScrollViewer'
    $overviewSubTabs = C 'OverviewSubTabs'
    $smartActionsPanel = C 'DriverSmartActionsPanel'
    $professionalActionsPanel = C 'DriverProfessionalActionsPanel'

    # Defensive normalization for rows retained from earlier scans or alternate providers.
    foreach($row in @($script:DriverAllDeviceRows)) {
        if($row -and -not $row.PSObject.Properties['UpdateReady']){$row | Add-Member -NotePropertyName UpdateReady -NotePropertyValue $false -Force}
        if($row -and -not $row.PSObject.Properties['UpdateId']){$row | Add-Member -NotePropertyName UpdateId -NotePropertyValue '' -Force}
        if($row -and -not $row.PSObject.Properties['LocalPackageReady']){$row | Add-Member -NotePropertyName LocalPackageReady -NotePropertyValue $false -Force}
    }

    if ($Mode -eq 'Smart') {
        if ($smartButton) { $smartButton.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#344A43'); $smartButton.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#D6B77E'); $smartButton.FontWeight = 'Bold' }
        if ($advancedButton) { $advancedButton.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#1C293B'); $advancedButton.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#456A91'); $advancedButton.FontWeight = 'Normal' }
        if ($description) { $description.Text = '' }
        if ($modeEyebrow) { $modeEyebrow.Text = 'SMART ASSISTANT' }
        if ($modeHeading) { $modeHeading.Text = '' }
        if ($smartButton) { $smartButton.Content = '✦ Smart'; $smartButton.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#344A43'); $smartButton.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#F4D99B') }
        if ($advancedButton) { $advancedButton.Content = 'Professional'; $advancedButton.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#B9C9DC') }
        if ($scrollViewer) { $scrollViewer.Padding = [System.Windows.Thickness]::new(10,8,10,16) }
        if ($smartActionsPanel) { $smartActionsPanel.Visibility = 'Visible' }
        if ($professionalActionsPanel) { $professionalActionsPanel.Visibility = 'Collapsed' }

        # Keep only the practical columns visible to a non-technical user.
        if ($deviceList -and $deviceList.View -and $deviceList.View.Columns.Count -ge 13) {
            $widths = @(0,260,105,0,120,0,0,0,0,0,0,310,0,0)
            for ($i = 0; $i -lt $widths.Count; $i++) { $deviceList.View.Columns[$i].Width = $widths[$i] }
        }
        if ($deviceList) {
            $deviceList.MaxHeight = 100000
            $deviceList.MinHeight = 0
            $deviceList.Height = [double]::NaN
            $smartRows = @($script:DriverAllDeviceRows | Where-Object {
                ([int]$_.ErrorCode -ne 0) -or
                (-not [string]::IsNullOrWhiteSpace([string]$_.UpdateId)) -or
                [bool]$_.UpdateReady -or [bool]$_.LocalPackageReady -or
                @($_.CandidateOptions).Count -gt 0 -or
                @($_.ProfessionalDiscoveredCandidates).Count -gt 0 -or
                @($_.VendorPackageCandidates).Count -gt 0
            })
            Update-AMRDriverSearchView -Query ([string]$script:DriverSearchQuery)
            $deviceList.SelectedItems.Clear()
            $emptyMessage = C 'DriverScanStatus'
            if ($emptyMessage -and [string]::IsNullOrWhiteSpace([string]$script:DriverSearchQuery) -and $script:DriverAllDeviceRows.Count -gt 0 -and $smartRows.Count -eq 0) {
                $emptyMessage.Text = 'Scan complete: no device problems or applicable driver updates were found. Your current drivers appear to need no action.'
            }
        }

        foreach ($name in @('DriverCandidateManagerBtn','DriverSourceManagerBtn','DriverCatalogSearchBtn','DriverRollbackCheckBtn','OpenOfficialSupportBtn','DriverExportReportBtn','DriverExportHistoryBtn','DriverSelectReadyBtn','DriverClearSelectionBtn','DriverInstallBatchBtn','DriverInstallPlanBtn','DriverOpenRecoveryBtn','DriverDownloadSelectedBtn','DriverInstallSelectedBtn')) {
            $control = C $name
            if ($control) { $control.Visibility = 'Collapsed' }
        }
        foreach ($name in @('DriverComputerSummaryCard','DriverSummaryMetrics')) {
            $control = C $name
            if ($control) { $control.Visibility = 'Visible' }
        }
        $identityToggle = C 'DriverIdentityToggleBtn'; if ($identityToggle) { $identityToggle.Visibility='Visible'; $identityToggle.Content='◉'; $identityToggle.ToolTip='Show system identity and platform details' }
        $identityDetails = C 'DriverSystemIdentitySummary'; if ($identityDetails) { $identityDetails.Visibility='Collapsed' }
        foreach ($name in @('DriverRollbackStatus','DriverSelectionSummary')) {
            $control = C $name
            if ($control) { $control.Visibility = 'Collapsed' }
        }
        $smartSelectButton = C 'DriverSmartSelectBtn'
        if ($smartSelectButton) { $smartSelectButton.Visibility = 'Visible'; $smartSelectButton.Content = '✦ Smart Select' }
        $smartInstallButton = C 'DriverStartSmartInstallBtn'
        if ($smartInstallButton) { $smartInstallButton.Visibility = 'Visible'; $smartInstallButton.Content = 'Smart Install' }
    }
    else {
        if ($smartButton) { $smartButton.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#1C293B'); $smartButton.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#456A91'); $smartButton.FontWeight = 'Normal' }
        if ($advancedButton) { $advancedButton.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#344A43'); $advancedButton.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#D6B77E'); $advancedButton.FontWeight = 'Bold' }
        if ($description) { $description.Text = 'Full control for experienced users: inspect every detected device, compare candidates, manage official sources, review rollback options and build installation plans.' }
        if ($modeEyebrow) { $modeEyebrow.Text = 'PROFESSIONAL WORKSPACE  •  FULL CONTROL' }
        if ($modeHeading) { $modeHeading.Text = 'FULL DRIVER INVENTORY & CONTROL' }
        if ($smartButton) { $smartButton.Content = '✦ Smart'; $smartButton.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#B9C9DC') }
        if ($advancedButton) { $advancedButton.Content = 'Professional'; $advancedButton.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#F4D99B') }
        if ($scrollViewer) { $scrollViewer.Padding = [System.Windows.Thickness]::new(10,8,10,16) }
        if ($smartActionsPanel) { $smartActionsPanel.Visibility = 'Collapsed' }
        if ($professionalActionsPanel) { $professionalActionsPanel.Visibility = 'Visible' }

        if ($deviceList -and $deviceList.View -and $deviceList.View.Columns.Count -ge 13) {
            $widths = @(48,245,105,145,115,150,135,95,190,190,75,250,130,55)
            for ($i = 0; $i -lt $widths.Count; $i++) { $deviceList.View.Columns[$i].Width = $widths[$i] }
        }
        if ($deviceList) {
            $deviceList.MaxHeight = 100000
            $deviceList.MinHeight = 0
            $deviceList.Height = [double]::NaN
            if ($script:DriverAllDeviceRows -and $script:DriverAllDeviceRows.Count -gt 0) {
                Update-AMRDriverSearchView -Query ([string]$script:DriverSearchQuery)
                $deviceList.SelectedItems.Clear()
            } else {
                $deviceList.ItemsSource = @()
            }
        }
        foreach ($name in @('DriverCandidateManagerBtn','DriverSourceManagerBtn','DriverCatalogSearchBtn','DriverRollbackCheckBtn','OpenOfficialSupportBtn','DriverExportReportBtn','DriverExportHistoryBtn','DriverSelectReadyBtn','DriverClearSelectionBtn','DriverInstallBatchBtn','DriverInstallPlanBtn','DriverOpenRecoveryBtn','DriverDownloadSelectedBtn','DriverInstallSelectedBtn')) {
            $control = C $name
            if ($control) { $control.Visibility = 'Visible' }
        }
        $metricsCard = C 'DriverSummaryMetrics'; if ($metricsCard) { $metricsCard.Visibility='Collapsed' }
        $identityCard = C 'DriverComputerSummaryCard'; if ($identityCard) { $identityCard.Visibility='Visible' }
        $identityToggle = C 'DriverIdentityToggleBtn'; if ($identityToggle) { $identityToggle.Visibility='Visible'; $identityToggle.Content='◉'; $identityToggle.ToolTip='Show system identity and platform details' }
        $identityDetails = C 'DriverSystemIdentitySummary'; if ($identityDetails) { $identityDetails.Visibility='Collapsed' }
        foreach ($name in @('DriverRollbackStatus','DriverSelectionSummary')) {
            $control = C $name
            if ($control) { $control.Visibility = 'Visible' }
        }
        $smartSelectButton = C 'DriverSmartSelectBtn'
        if ($smartSelectButton) { $smartSelectButton.Visibility = 'Collapsed' }
        $smartInstallButton = C 'DriverStartSmartInstallBtn'
        if ($smartInstallButton) { $smartInstallButton.Visibility = 'Collapsed' }
        $downloadButton = C 'DriverDownloadSelectedBtn'
        $installButton = C 'DriverInstallSelectedBtn'
        if ($downloadButton) { $downloadButton.Content = 'Download & Save Package' }
        if ($installButton) { $installButton.Content = 'Install Ready Update' }
    }
    Update-AMRDriverActionButtons
}

# A3: plain-language reasons shown as tooltips (also on disabled buttons) and in the selection line. Display only; no enable logic changes.
function Get-AMRDriverButtonReasons {
    param([bool]$Busy,[int]$FoundCount,[int]$ReadyAvailableCount,[int]$SelectedCount,[int]$ReadySelectedCount,[bool]$HasCandidate,[bool]$IsReady,[bool]$HasSelected)
    $busyText = 'Another Driver Center operation is running. Wait for it to finish.'
    $noMatchText = 'The last scan found no driver update that matches a device in this computer, so nothing can be downloaded or become ready.'
    $notDownloadedText = ('{0} update(s) were found, but none is downloaded yet. Select a device that has an update and press Download & Save Package first.' -f $FoundCount)
    $noData = $(if ($FoundCount -eq 0) { $noMatchText } else { $notDownloadedText })
    $noReady = $(if ($Busy) { $busyText } elseif ($ReadyAvailableCount -eq 0) { $noData } else { 'Select one or more rows that are ready to install (Select All Ready selects them all).' })
    $download = $(if ($Busy) { $busyText } elseif (-not $HasSelected) { 'Select a device row first.' } elseif (-not $HasCandidate) { 'The selected device has no matched driver update in the last scan, so there is nothing to download.' } elseif ($IsReady) { 'This update is already downloaded. Use Install Ready Update.' } else { '' })
    $install = $(if ($Busy) { $busyText } elseif (-not $HasSelected) { 'Select a device row first.' } elseif (-not $HasCandidate) { 'The selected device has no matched driver update in the last scan, so there is nothing to install.' } elseif (-not $IsReady) { 'Download this update first (Download & Save Package).' } else { '' })
    $selectAll = $(if ($Busy) { $busyText } else { $noData })
    $summaryTail = ''
    if ($SelectedCount -gt 0 -and $ReadySelectedCount -eq 0) { $summaryTail = $(if ($FoundCount -eq 0) { ' • no matched update in the last scan' } else { ' • selected rows have no downloaded update' }) }
    return @{ Download=$download; Install=$install; SelectAll=$selectAll; Batch=$noReady; Plan=$noReady; SummaryTail=$summaryTail }
}

function Set-AMRDriverButtonHint {
    param([string]$Name,[bool]$Enabled,[string]$EnabledTip,[string]$DisabledTip)
    try {
        $hintButton = C $Name
        if (-not $hintButton) { return }
        [System.Windows.Controls.ToolTipService]::SetShowOnDisabled($hintButton,$true)
        $hintButton.ToolTip = $(if ($Enabled) { $EnabledTip } else { $DisabledTip })
    } catch {}
}

function Update-AMRDriverActionButtons {
    $list = C 'DriverDeviceList'
    # A10: the read-only diagnosis button is available after a scan, while no other Driver Center operation runs.
    $diagnosisButton = C 'DriverDiagnosisBtn'
    if ($diagnosisButton) {
        $diagnosisButton.IsEnabled = (@($script:DriverAllDeviceRows).Count -gt 0 -and -not $script:DriverScanJob -and -not $script:DriverActionJob -and -not $script:DriverManagedJob -and -not $script:DriverDiagJob -and -not $script:DriverRepairJob)
        if (-not $script:DriverDiagJob) { $diagnosisButton.Content = $(if ($script:DriverDiagLast) { 'Re-diagnose' } else { 'Diagnose Devices' }) }
    }
    try { Update-AMRDriverRepairButtons } catch {}
    # WPF can retain rows produced by older/alternate result paths. Normalize before
    # reading optional update properties while Set-StrictMode is active.
    $rowsToNormalize = @($script:DriverAllDeviceRows)
    if($list) { $rowsToNormalize += @($list.ItemsSource) }
    foreach($row in $rowsToNormalize) {
        try {
            if($row -and -not $row.PSObject.Properties['UpdateReady']){
                # A13c (c): record the real type of any row that lacked the property (first 3 only).
                if([int]$script:AMRRowDiagLogged -lt 3){ $script:AMRRowDiagLogged = [int]$script:AMRRowDiagLogged + 1; try { Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceScan -Stage RowMissingUpdateReady -Message ('A device row of type {0} had no UpdateReady property and was normalized.' -f $row.GetType().FullName) -Source 'Update-AMRDriverActionButtons' } catch {} }
                $row | Add-Member -NotePropertyName UpdateReady -NotePropertyValue $false -Force
            }
            if($row -and -not $row.PSObject.Properties['UpdateId']){$row | Add-Member -NotePropertyName UpdateId -NotePropertyValue '' -Force}
            if($row -and -not $row.PSObject.Properties['UpdateRevision']){$row | Add-Member -NotePropertyName UpdateRevision -NotePropertyValue 0 -Force}
            if($row -and -not $row.PSObject.Properties['HardwareIds']){$row | Add-Member -NotePropertyName HardwareIds -NotePropertyValue @() -Force}
        } catch {
            try { Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceScan -Stage RowNormalizeFailed -Message ('A device row could not be normalized: ' + $_.Exception.Message) -Source 'Update-AMRDriverActionButtons' } catch {}
        }
    }
    $selected = $list.SelectedItem
    $hasCandidate = $false
    $isReady = $false
    $hasHardwareId = $false
    if ($selected) {
        $hasCandidate = -not [string]::IsNullOrWhiteSpace([string](Get-AMRDiagProp $selected 'UpdateId' ''))
        $isReady = ($hasCandidate -and [bool](Get-AMRDiagProp $selected 'UpdateReady' $false))
        $hasHardwareId = (@(@(Get-AMRDiagProp $selected 'HardwareIds' @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }).Count -gt 0)
    }
    # A13c (a): every optional property below is read through the safe getter, so no row shape can throw under StrictMode.
    $selectedRows = @($list.SelectedItems)
    $readySelectedRows = @($selectedRows | Where-Object { $_ -and [bool](Get-AMRDiagProp $_ 'UpdateReady' $false) -and -not [string]::IsNullOrWhiteSpace([string](Get-AMRDiagProp $_ 'UpdateId' '')) })
    $readySelectedCount = $readySelectedRows.Count
    $allRows = @($list.ItemsSource)
    $readyAvailableRows = @($allRows | Where-Object { $_ -and [bool](Get-AMRDiagProp $_ 'UpdateReady' $false) -and -not [string]::IsNullOrWhiteSpace([string](Get-AMRDiagProp $_ 'UpdateId' '')) })
    $readyAvailableCount = $readyAvailableRows.Count
    $availableUpdateKeys = @{}
    foreach ($row in $allRows) {
        if ([string]::IsNullOrWhiteSpace([string](Get-AMRDiagProp $row 'UpdateId' ''))) { continue }
        $key = ('{0}|{1}' -f [string](Get-AMRDiagProp $row 'UpdateId' ''),[int](Get-AMRDiagProp $row 'UpdateRevision' 0))
        $availableUpdateKeys[$key] = $true
    }
    $selectedUpdateKeys = @{}
    foreach ($row in $readySelectedRows) {
        $key = ('{0}|{1}' -f [string](Get-AMRDiagProp $row 'UpdateId' ''),[int](Get-AMRDiagProp $row 'UpdateRevision' 0))
        $selectedUpdateKeys[$key] = $true
    }
    $summary = C 'DriverSelectionSummary'
    if ($summary) {
        $summary.Text = ('Selection: {0} row(s) selected • {1} ready row(s) • {2} unique package(s) selected / {3} available' -f $selectedRows.Count,$readySelectedCount,$selectedUpdateKeys.Count,$availableUpdateKeys.Count)
        $summary.ToolTip = ('{0} unique ready update(s) selected for batch installation.' -f $selectedUpdateKeys.Count)
    }
    $driverOperationBusy = [bool]$script:DriverActionJob -or [bool]$script:DriverScanJob -or [bool]$script:DriverManagedJob -or ($script:DriverOperationState.State -eq 'Running')
    (C 'DriverDownloadSelectedBtn').IsEnabled = ($hasCandidate -and -not $isReady -and -not $driverOperationBusy)
    (C 'DriverInstallSelectedBtn').IsEnabled = ($isReady -and -not $driverOperationBusy)
    try { (C 'ScanDriversBtn').IsEnabled = (-not $driverOperationBusy) } catch {}
    try { (C 'DriverRollbackCheckBtn').IsEnabled = ($null -ne $selected -and -not [string]::IsNullOrWhiteSpace([string]$selected.DeviceId) -and -not $driverOperationBusy) } catch {}
    (C 'DriverSelectReadyBtn').IsEnabled = ($readyAvailableCount -gt 0 -and -not $driverOperationBusy)
    (C 'DriverClearSelectionBtn').IsEnabled = ($selectedRows.Count -gt 0 -and -not $driverOperationBusy)
    (C 'DriverInstallBatchBtn').Content = ('Install Selected Ready ({0})' -f $selectedUpdateKeys.Count)
    (C 'DriverInstallBatchBtn').IsEnabled = ($selectedUpdateKeys.Count -gt 0 -and -not $driverOperationBusy -and -not $script:DriverBatchActive)
    try { (C 'DriverInstallPlanBtn').IsEnabled = ($selectedUpdateKeys.Count -gt 0 -and -not $driverOperationBusy -and -not $script:DriverBatchActive) } catch {}
    # A5: diagnostic only. One line each time the combination below changes, so the log shows why the buttons are enabled or not.
    try {
        $buttonStateKey = ('busy={0};scan={1};action={2};managed={3};op={4};batch={5};selected={6};readySel={7};readyAvail={8};cand={9};ready={10};dl={11};inst={12};selReady={13};batchBtn={14}' -f [bool]$driverOperationBusy,[bool]$script:DriverScanJob,[bool]$script:DriverActionJob,[bool]$script:DriverManagedJob,[string]$script:DriverOperationState.State,[bool]$script:DriverBatchActive,$selectedRows.Count,$readySelectedCount,$readyAvailableCount,$hasCandidate,$isReady,[bool](C 'DriverDownloadSelectedBtn').IsEnabled,[bool](C 'DriverInstallSelectedBtn').IsEnabled,[bool](C 'DriverSelectReadyBtn').IsEnabled,[bool](C 'DriverInstallBatchBtn').IsEnabled)
        if ($buttonStateKey -ne [string]$script:AMRButtonStateLast) {
            $script:AMRButtonStateLast = $buttonStateKey
            Write-AMRDriverDiagnostic -Severity DEBUG -Operation DriverButtons -Stage StateChanged -Message $buttonStateKey -Source 'Update-AMRDriverActionButtons'
        }
    } catch {}
    # A3: explain why a button is disabled (tooltip works on disabled buttons) and why 0 rows are ready.
    try {
        $hintReasons = Get-AMRDriverButtonReasons -Busy ([bool]($driverOperationBusy -or $script:DriverBatchActive)) -FoundCount $availableUpdateKeys.Count -ReadyAvailableCount $readyAvailableCount -SelectedCount $selectedRows.Count -ReadySelectedCount $readySelectedCount -HasCandidate $hasCandidate -IsReady $isReady -HasSelected ($null -ne $selected)
        Set-AMRDriverButtonHint -Name 'DriverDownloadSelectedBtn' -Enabled ([bool](C 'DriverDownloadSelectedBtn').IsEnabled) -EnabledTip 'Download the selected driver update and save the package. Nothing is installed.' -DisabledTip $hintReasons.Download
        Set-AMRDriverButtonHint -Name 'DriverInstallSelectedBtn' -Enabled ([bool](C 'DriverInstallSelectedBtn').IsEnabled) -EnabledTip 'Install the selected downloaded update after you confirm.' -DisabledTip $hintReasons.Install
        Set-AMRDriverButtonHint -Name 'DriverSelectReadyBtn' -Enabled ([bool](C 'DriverSelectReadyBtn').IsEnabled) -EnabledTip 'Select every downloaded update that is ready to install.' -DisabledTip $hintReasons.SelectAll
        Set-AMRDriverButtonHint -Name 'DriverInstallBatchBtn' -Enabled ([bool](C 'DriverInstallBatchBtn').IsEnabled) -EnabledTip 'Install the selected ready updates one at a time after you confirm.' -DisabledTip $hintReasons.Batch
        Set-AMRDriverButtonHint -Name 'DriverInstallPlanBtn' -Enabled ([bool](C 'DriverInstallPlanBtn').IsEnabled) -EnabledTip 'Review the proposed installation order for the selected ready updates.' -DisabledTip $hintReasons.Plan
        if ($summary -and $hintReasons.SummaryTail) { $summary.Text = [string]$summary.Text + $hintReasons.SummaryTail }
    } catch {}
    $smartCandidateCount = @($script:DriverAllDeviceRows | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.UpdateId) }).Count
    $smartSelectedCount = @((C 'DriverDeviceList').SelectedItems | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.UpdateId) }).Count
    $smartBusy = [bool]$script:DriverActionJob -or [bool]$script:DriverScanJob -or [bool]$script:DriverManagedJob -or ($script:DriverOperationState.State -eq 'Running') -or [bool]$script:DriverBatchActive -or [bool]$script:DriverSmartQueueActive
    try {
        $smartSelectButton = C 'DriverSmartSelectBtn'
        if ($smartSelectButton) { $smartSelectButton.IsEnabled = ($smartCandidateCount -gt 0 -and -not $smartBusy) }
        $smartButton = C 'DriverStartSmartInstallBtn'
        $smartButton.IsEnabled = ([bool]$script:DriverSmartSelectionReady -and $smartSelectedCount -gt 0 -and -not $smartBusy)
        if ($script:DriverSmartQueueActive) { $smartButton.Content = ('Preparing drivers… ({0}/{1})' -f $script:DriverSmartDownloadCompleted,$script:DriverSmartDownloadTotal) }
        elseif ($script:DriverSmartSelectionReady) { $smartButton.Content = ('Start Smart Install ({0})' -f $smartSelectedCount) }
        else { $smartButton.Content = 'Start Smart Install' }
    } catch {}
    (C 'DriverCatalogSearchBtn').IsEnabled = ($hasHardwareId -and -not $script:DriverActionJob -and -not $script:DriverScanJob -and -not $script:DriverManagedJob -and $script:DriverOperationState.State -ne 'Running')
    try {
        $candidateManager = C 'DriverCandidateManagerBtn'
        if ($candidateManager) { $candidateManager.IsEnabled = ($null -ne $selected -and (@($selected.CandidateOptions).Count -gt 0 -or @($selected.ProfessionalDiscoveredCandidates).Count -gt 0) -and -not $driverOperationBusy) }
        $sourceManager = C 'DriverSourceManagerBtn'
        if ($sourceManager) { $sourceManager.IsEnabled = ($null -ne $selected -and -not [string]::IsNullOrWhiteSpace([string]$selected.DeviceId) -and -not $driverOperationBusy) }
    } catch {}

    # Route support to the selected device vendor where possible.
    $supportButton = C 'OpenOfficialSupportBtn'
    if ($selected -and -not [string]::IsNullOrWhiteSpace([string]$script:DriverSupportUrl)) {
        $deviceSupport = Get-AMRDriverDeviceSupportSource -DeviceManufacturer ([string]$selected.Manufacturer) -DeviceName ([string]$selected.DeviceName) -ComputerModel ([string]$script:DriverComputerModel) -BoardModel ([string]$script:DriverBoardModel) -WindowsContext ([string]$script:DriverWindowsContext) -FallbackName ([string]$script:DriverSupportName) -FallbackUrl ([string]$script:DriverSupportUrl)
        $supportButton.Content = 'Open ' + $deviceSupport.Name + ' ↗'
        $supportButton.IsEnabled = -not [string]::IsNullOrWhiteSpace([string]$deviceSupport.Url)
        $supportButton.ToolTip = ($deviceSupport.RoutingNote + ' Search terms: ' + $deviceSupport.SearchTerms)
    } elseif (-not [string]::IsNullOrWhiteSpace([string]$script:DriverSupportUrl)) {
        $supportButton.Content = 'Open ' + $script:DriverSupportName + ' ↗'
        $supportButton.IsEnabled = $true
        $supportButton.ToolTip = 'Official support source for this computer or motherboard.'
    }
}

function Add-AMRDriverHistoryEntry {
    param(
        [string]$Action,
        [string]$Device,
        [string]$Update,
        [string]$Version,
        [string]$Status,
        [string]$Details,
        [string]$DeviceInstanceId = '',
        [string]$OperationId = ''
    )
    if ([string]::IsNullOrWhiteSpace($OperationId)) { $OperationId = [guid]::NewGuid().ToString('N') }
    $diagnosticDeviceId = if (-not [string]::IsNullOrWhiteSpace($DeviceInstanceId)) { $DeviceInstanceId } else { $Device }
    try {
        $entry = [pscustomobject]@{
            Timestamp = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
            Action = $Action
            Device = $Device
            Update = $Update
            Version = $Version
            Status = $Status
            Details = $Details
        }
        if (Test-Path -LiteralPath $script:DriverHistoryFile -PathType Leaf) {
            $entry | Export-Csv -LiteralPath $script:DriverHistoryFile -NoTypeInformation -Append -Encoding UTF8 -ErrorAction Stop
        } else {
            $entry | Export-Csv -LiteralPath $script:DriverHistoryFile -NoTypeInformation -Encoding UTF8 -ErrorAction Stop
        }
        Write-AMRDriverDiagnostic -Severity $(if ($Status -match '^(?i:success|installedandverified|installedrestartrequired)$') {'SUCCESS'} elseif ($Status -match '(?i)fail|error') {'ERROR'} else {'INFO'}) -Operation $Action -Stage HistoryRecorded -Message ('Driver history event recorded: ' + $Status) -DeviceId $diagnosticDeviceId -OperationId $OperationId -Source 'DriverCenterHistory' -Result $Status -Context @{DeviceName=$Device;Update=$Update;Version=$Version;Details=$Details}
    } catch {
        Write-AMRDriverDiagnostic -Severity WARNING -Operation $Action -Stage HistoryWriteFailed -Message 'Could not persist the Driver Center history CSV entry.' -DeviceId $diagnosticDeviceId -OperationId $OperationId -Source 'Add-AMRDriverHistoryEntry' -Result 'Failed' -ErrorRecord $_ -Context @{DeviceName=$Device;Update=$Update;Version=$Version}
        Write-AMRLog ('Could not write Driver Center history: ' + $_.Exception.Message) WARNING Overview
    }
}

# ---- A10: Smart Driver Center phases 1-2 ----
# ======================================================================================================================
# Smart Driver Center, phases 1-2 (READ-ONLY): whole-system device diagnosis.
# Nothing in this block changes the device, a driver, the registry, a service or any setting. It reads Plug and Play
# state, parent/child links, audio endpoints and recent System events, then explains what Windows reports.
# Evidence and confidence: every finding lists what supports it, what argues against it and what is unknown.
# ======================================================================================================================

# StrictMode-safe property read: returns $Default when the property is missing or null (rows may be older/partial objects).
function Get-AMRDiagProp {
    param($Object, [string]$Name, $Default = $null)
    try {
        if ($null -eq $Object) { return $Default }
        $property = $Object.PSObject.Properties[$Name]
        if ($property -and $null -ne $property.Value) { return $property.Value }
    } catch {}
    return $Default
}

# Problem code knowledge. Code NAMES follow Microsoft Learn "Device Manager Error Messages" (CM_PROB_*). The meaning, cause and
# suggested-fix wording is AMR's own and is guidance only; in these phases nothing is executed.
# Specificity: 'Direct' = the code alone states the situation; 'Ambiguous' = the code does not separate driver, firmware,
# resource or hardware causes, so the cause is reported with lower confidence.
function Get-AMRDriverProblemCodeInfo {
    param([int]$Code)
    $table = @{
        1  = @('CM_PROB_NOT_CONFIGURED','Windows reports the device is not configured correctly.','Driver setup did not finish, or no matching driver was configured.','Reinstall an exact-hardware-ID driver package from a trusted source.','Ambiguous','High')
        10 = @('CM_PROB_FAILED_START','Windows reports the device cannot start.','A faulty or incompatible driver, missing resources, firmware or the hardware itself. The code does not say which.','Check the driver version and recent driver changes; reinstall the exact-hardware-ID package; check firmware or the device if that fails.','Ambiguous','High')
        12 = @('CM_PROB_NORMAL_CONFLICT','Windows reports the device could not find enough free resources.','A resource conflict, or a firmware (BIOS/UEFI) resource assignment problem.','Review resource assignment and BIOS/UEFI settings. This is not a driver-package problem in most cases.','Ambiguous','Medium')
        14 = @('CM_PROB_NEED_RESTART','Windows reports the device cannot work until the computer restarts.','A driver or setting change is pending a restart.','Restart Windows when convenient, then diagnose again.','Direct','Low')
        16 = @('CM_PROB_PARTIAL_LOG_CONF','Windows reports it could not identify all the resources the device uses.','Incomplete resource configuration.','Review the device resources and driver package.','Ambiguous','Medium')
        18 = @('CM_PROB_REINSTALL','Windows reports the drivers for the device must be reinstalled.','The driver registration is damaged or incomplete.','Reinstall an exact-hardware-ID driver package from a trusted source.','Direct','High')
        19 = @('CM_PROB_REGISTRY','Windows reports the device configuration in the registry is incomplete or damaged.','Damaged driver configuration or a filter driver problem. The exact value is not named by the code.','Reinstall the driver package. Do not edit the registry by hand.','Ambiguous','High')
        21 = @('CM_PROB_WILL_BE_REMOVED','Windows reports the device is being removed.','The device is in the middle of being uninstalled.','Wait and diagnose again, or restart Windows.','Direct','Low')
        22 = @('CM_PROB_DISABLED','Windows reports the device is disabled.','A user, an app (for example an OEM utility), a script or an administrator disabled it. Who did it cannot be read from this code.','Enable the device if its function is needed, then verify the function works.','Direct','High')
        24 = @('CM_PROB_DEVICE_NOT_THERE','Windows reports the device is not present, not working properly, or lacks all its drivers.','The device is unplugged, powered off, failing, or its driver is missing.','Check the connection and power; then check that a driver is installed.','Ambiguous','Medium')
        28 = @('CM_PROB_FAILED_INSTALL','Windows reports no driver is installed for the device.','The driver was never installed, was removed (for example by an app) or its installation failed.','Find an exact-hardware-ID package from a trusted source and install it after review.','Direct','High')
        29 = @('CM_PROB_HARDWARE_DISABLED','Windows reports the device is disabled because its firmware did not give it the resources it needs.','The device is turned off in firmware (BIOS/UEFI) or by the platform.','Check the BIOS/UEFI setting. This cannot be fixed from Windows; firmware changes are never automatic.','Direct','High')
        31 = @('CM_PROB_FAILED_ADD','Windows reports the device is not working properly because it cannot load the driver.','Damaged, incompatible or blocked driver, or a missing dependency.','Check driver load events and dependencies; reinstall the exact-hardware-ID package.','Ambiguous','High')
        32 = @('CM_PROB_DISABLED_SERVICE','Windows reports the driver (service) for the device is disabled.','The driver service start type was set to disabled, by an app, a tool or an administrator.','Check whether the service was disabled on purpose; re-enable only if the device function is needed.','Direct','High')
        33 = @('CM_PROB_TRANSLATION_FAILED','Windows documents this as a resource translation failure.','Firmware or resource configuration.','See Microsoft documentation for this code.','Ambiguous','Medium')
        34 = @('CM_PROB_NO_SOFTCONFIG','Windows documents this as a device that needs manual configuration.','Device configuration is not automatic.','See Microsoft documentation for this code.','Ambiguous','Medium')
        35 = @('CM_PROB_BIOS_TABLE','Windows documents this as a firmware table problem.','The computer firmware does not provide a required table.','A BIOS/UEFI update may be needed. Firmware changes are never automatic.','Ambiguous','Medium')
        36 = @('CM_PROB_IRQ_TRANSLATION_FAILED','Windows documents this as an interrupt request translation failure.','Firmware or resource configuration.','See Microsoft documentation for this code.','Ambiguous','Medium')
        37 = @('CM_PROB_FAILED_DRIVER_ENTRY','Windows reports the driver failed to initialize.','Incompatible, damaged or recently changed driver.','Compare recent driver changes; reinstall the exact-hardware-ID package or roll back.','Ambiguous','High')
        38 = @('CM_PROB_DRIVER_FAILED_PRIOR_UNLOAD','Windows documents this as a previous driver instance that is still in memory.','The earlier driver did not unload.','Restart Windows, then diagnose again.','Ambiguous','Medium')
        39 = @('CM_PROB_DRIVER_FAILED_LOAD','Windows reports it cannot load the driver; it may be missing or damaged.','Missing or corrupted driver file, or a blocked driver.','Reinstall the exact-hardware-ID package.','Ambiguous','High')
        40 = @('CM_PROB_DRIVER_SERVICE_KEY_INVALID','Windows reports the driver service information is missing or incorrect.','Damaged driver service registration.','Reinstall the driver package. Do not edit the registry by hand.','Ambiguous','High')
        41 = @('CM_PROB_LEGACY_SERVICE_NO_DEVICES','Windows documents this as a legacy service that created no devices.','Legacy driver without a device.','See Microsoft documentation for this code.','Ambiguous','Low')
        42 = @('CM_PROB_DUPLICATE_DEVICE','Windows documents this as a duplicate device.','Two devices report the same identity.','See Microsoft documentation for this code.','Ambiguous','Medium')
        43 = @('CM_PROB_FAILED_POST_START','Windows reports it stopped the device because the device reported problems.','A driver, firmware or hardware fault. The code does not say which.','Check the driver version and firmware; reinstall the exact-hardware-ID package; suspect hardware if it keeps happening.','Ambiguous','High')
        44 = @('CM_PROB_HALTED','Windows documents this as a device stopped by an application or service.','An app or service halted the device.','Close the app or service that controls it, or restart Windows.','Ambiguous','Medium')
        45 = @('CM_PROB_PHANTOM','Windows reports the device is currently not connected.','A remembered device that is not plugged in or powered.','Reconnect the device. This is normal for a device that is not attached.','Direct','Low')
        46 = @('CM_PROB_SYSTEM_SHUTDOWN','Windows documents this as unavailable because the system is shutting down.','Transient state during shutdown.','No action; diagnose again later.','Direct','Low')
        47 = @('CM_PROB_HELD_FOR_EJECT','Windows documents this as a device prepared for safe removal.','The device was prepared for removal.','Reconnect the device if it should be used.','Direct','Low')
        48 = @('CM_PROB_DRIVER_BLOCKED','Windows reports the software for the device was blocked because of known problems.','Windows blocks this driver version for compatibility or security reasons.','Use a newer driver from the hardware maker. Do not bypass the block.','Direct','High')
        49 = @('CM_PROB_REGISTRY_TOO_LARGE','Windows documents this as the registry hive size limit being exceeded.','Too many device registrations.','See Microsoft documentation for this code.','Ambiguous','Medium')
        50 = @('CM_PROB_SETPROPERTIES_FAILED','Windows documents this as a failure to apply the device properties.','Driver or registry configuration.','See Microsoft documentation for this code.','Ambiguous','Medium')
        51 = @('CM_PROB_WAITING_ON_DEPENDENCY','Windows documents this as a device waiting on another device.','A parent or dependency device is not ready.','Check the dependency or parent device first.','Direct','Medium')
        52 = @('CM_PROB_UNSIGNED_DRIVER','Windows reports it cannot verify the digital signature of the driver.','Unsigned, modified or corrupt driver package.','Use a correctly signed package from the hardware maker. Do not disable signature enforcement.','Direct','High')
        53 = @('CM_PROB_USED_BY_DEBUGGER','Windows documents this as a device reserved for use by a debugger.','Kernel debugging configuration.','See Microsoft documentation for this code.','Direct','Low')
        54 = @('CM_PROB_DEVICE_RESET','Windows documents this as a device that is failing and being reset.','Hardware or driver instability.','See Microsoft documentation for this code.','Ambiguous','Medium')
        55 = @('CM_PROB_CONSOLE_LOCKED','Windows documents this as a device that cannot start while the console is locked.','Transient state.','No action; diagnose again later.','Direct','Low')
        56 = @('CM_PROB_NEED_CLASS_CONFIG','Windows documents this as a device needing class configuration.','Class setup is pending.','Restart Windows, then diagnose again.','Ambiguous','Medium')
        57 = @('CM_PROB_GUEST_ASSIGNMENT_FAILED','Windows documents this as a virtual machine device assignment failure.','Virtualization configuration.','See Microsoft documentation for this code.','Ambiguous','Low')
    }
    if ($Code -ne 0 -and $table.ContainsKey($Code)) {
        $e = $table[$Code]
        return [pscustomobject]@{ Known=$true; Code=$Code; Name=[string]$e[0]; Meaning=[string]$e[1]; Causes=[string]$e[2]; Fix=[string]$e[3]; Specificity=[string]$e[4]; Severity=[string]$e[5] }
    }
    if ($Code -ne 0) {
        return [pscustomobject]@{ Known=$false; Code=$Code; Name=('Unmapped problem code {0}' -f $Code); Meaning=('Windows reports Plug and Play problem code {0}. AMR has no built-in description for it.' -f $Code); Causes='Unknown from this code alone.'; Fix='Look up the code in Microsoft documentation and review the device events. Nothing was changed.'; Specificity='Ambiguous'; Severity='Medium' }
    }
    return [pscustomobject]@{ Known=$true; Code=0; Name='No problem'; Meaning='Windows reports no Plug and Play problem for this device.'; Causes=''; Fix=''; Specificity='Direct'; Severity='None' }
}

# Device family from the PnP class and name. Class is the stronger signal; the name is used only to refine it.
function Get-AMRDeviceFamily {
    param([string]$Class = '', [string]$Name = '', [string]$Category = '')
    $text = ('{0} {1} {2}' -f $Class,$Name,$Category)
    if ($Class -match '^(?i)AudioEndpoint$') { return 'Audio' }
    if ($Class -match '^(?i)(Biometric|SmartCardReader)$' -or $text -match '(?i)fingerprint|biometric|windows hello|\bface (recognition|authentication)|iris') { return 'Biometric' }
    if ($Class -match '^(?i)(Camera|Image)$') { if ($Name -match '(?i)\bIR\b|infrared|hello') { return 'Biometric' }; return 'Camera' }
    if ($Class -match '^(?i)MEDIA$') { return 'Audio' }
    if ($Class -match '^(?i)(System|Other|SoftwareComponent|Extension)$' -and $Name -match '(?i)audio|sound|\bSST\b|\bDSP\b|codec|high definition audio|smart sound') { return 'Audio' }
    if ($Class -match '^(?i)Bluetooth$') { return 'Bluetooth' }
    if ($Class -match '^(?i)Net$') { return 'Network' }
    if ($Class -match '^(?i)(Display|Monitor)$') { return 'Display' }
    if ($Class -match '^(?i)(HIDClass|Keyboard|Mouse)$') { return 'Input' }
    if ($Class -match '^(?i)USB$') { return 'USB' }
    if ($Class -match '^(?i)(DiskDrive|SCSIAdapter|HDC|StorageVolume|CDROM)$') { return 'Storage' }
    if ($Class -match '^(?i)Sensor$') { return 'Sensor' }
    if ($Class -match '^(?i)(Battery|Processor|Firmware)$') { return 'Power / platform' }
    if ($Class -match '^(?i)System$') { return 'System' }
    return 'Other'
}

function Get-AMRDeviceFamilyWeight {
    param([string]$Family)
    switch ($Family) {
        'Network' { return 95 } 'Storage' { return 90 } 'Audio' { return 90 } 'Display' { return 85 } 'Input' { return 85 }
        'Biometric' { return 80 } 'Camera' { return 75 } 'Bluetooth' { return 70 } 'System' { return 70 } 'USB' { return 60 }
        'Power / platform' { return 60 } 'Sensor' { return 40 } default { return 30 }
    }
}

# Runs in a background job (never on the UI thread). Read-only: Get-PnpDevice, Get-PnpDeviceProperty, Get-WinEvent.
# Healthy devices are read cheaply (state only). Devices with a problem, or in a relevant family, also get parent/child links.
function Get-AMRDriverSystemReadPass {
    param([int]$BudgetSeconds = 45, [int]$EventDays = 7)
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $problems = New-Object System.Collections.ArrayList
    $pnp = @()
    try { $pnp = @(Get-PnpDevice -PresentOnly -ErrorAction Stop) } catch { [void]$problems.Add('Get-PnpDevice failed: ' + $_.Exception.Message) }
    $relevantClasses = @('MEDIA','AudioEndpoint','Biometric','SmartCardReader','Camera','Image','Bluetooth')
    $devices = New-Object System.Collections.ArrayList
    $detailTargets = New-Object System.Collections.ArrayList
    $priorityTargets = New-Object System.Collections.ArrayList
    foreach ($d in $pnp) {
        if ($null -eq $d) { continue }
        $code = 0
        $codeKnown = $false
        $p = $d.PSObject.Properties['ConfigManagerErrorCode']
        if ($p -and $null -ne $p.Value) { try { $code = [int]$p.Value; $codeKnown = $true } catch {} }
        $id = ''; $p = $d.PSObject.Properties['InstanceId']; if ($p -and $null -ne $p.Value) { $id = [string]$p.Value }
        $name = ''; $p = $d.PSObject.Properties['FriendlyName']; if ($p -and $null -ne $p.Value) { $name = [string]$p.Value }
        if ([string]::IsNullOrWhiteSpace($name)) { $p = $d.PSObject.Properties['Name']; if ($p -and $null -ne $p.Value) { $name = [string]$p.Value } }
        $class = ''; $p = $d.PSObject.Properties['Class']; if ($p -and $null -ne $p.Value) { $class = [string]$p.Value }
        $status = ''; $p = $d.PSObject.Properties['Status']; if ($p -and $null -ne $p.Value) { $status = [string]$p.Value }
        if ([string]::IsNullOrWhiteSpace($id)) { continue }
        $record = [pscustomobject]@{
            InstanceId=$id; Name=$name; Class=$class; Status=$status; ProblemCode=$code; CodeKnown=$codeKnown
            ProblemStatus=''; Parent=''; Children=@(); DetailRead=$false
        }
        [void]$devices.Add($record)
        if ($code -ne 0 -or $status -eq 'Error' -or $status -eq 'Degraded') { [void]$priorityTargets.Add($record) }
        elseif (($status -and $status -ne 'OK') -or ($relevantClasses -contains $class)) { [void]$detailTargets.Add($record) }
    }
    $orderedTargets = New-Object System.Collections.ArrayList
    foreach ($target in $priorityTargets) { [void]$orderedTargets.Add($target) }
    foreach ($target in $detailTargets) { [void]$orderedTargets.Add($target) }
    $detailTargets = $orderedTargets
    $detailTotal = $detailTargets.Count
    $detailDone = 0
    $budgetExceeded = $false
    foreach ($record in @($detailTargets)) {
        if ($watch.Elapsed.TotalSeconds -gt $BudgetSeconds) { $budgetExceeded = $true; break }
        if ($detailDone -ge 120) { $budgetExceeded = $true; break }
        try {
            $props = @(Get-PnpDeviceProperty -InstanceId $record.InstanceId -KeyName 'DEVPKEY_Device_Parent','DEVPKEY_Device_Children','DEVPKEY_Device_ProblemCode','DEVPKEY_Device_ProblemStatus' -ErrorAction Stop)
            foreach ($prop in $props) {
                $key = ''; $kp = $prop.PSObject.Properties['KeyName']; if ($kp -and $null -ne $kp.Value) { $key = [string]$kp.Value }
                $data = $null; $dp = $prop.PSObject.Properties['Data']; if ($dp) { $data = $dp.Value }
                if ($null -eq $data) { continue }
                if ($key -eq 'DEVPKEY_Device_Parent') { $record.Parent = [string]$data }
                elseif ($key -eq 'DEVPKEY_Device_Children') { $record.Children = @($data | ForEach-Object { [string]$_ }) }
                elseif ($key -eq 'DEVPKEY_Device_ProblemCode' -and -not $record.CodeKnown) { try { $record.ProblemCode = [int]$data; $record.CodeKnown = $true } catch {} }
                elseif ($key -eq 'DEVPKEY_Device_ProblemStatus') { try { $record.ProblemStatus = ('0x{0:X8}' -f [int]$data) } catch { $record.ProblemStatus = [string]$data } }
            }
            $record.DetailRead = $true
        } catch {
            if ($problems.Count -lt 10) { [void]$problems.Add(('Property read failed for {0}: {1}' -f $record.InstanceId,$_.Exception.Message)) }
        }
        $detailDone++
    }
    # A12: Driver Store evidence (read-only pnputil /enum-devices /drivers) for up to 5 problem devices other than Code 22.
    $storeWatch = [System.Diagnostics.Stopwatch]::StartNew()
    foreach ($record in @($devices | Where-Object { $_.ProblemCode -ne 0 -and $_.ProblemCode -ne 22 } | Select-Object -First 5)) {
        if ($storeWatch.Elapsed.TotalSeconds -gt 12 -or $watch.Elapsed.TotalSeconds -gt ($BudgetSeconds + 10)) { break }
        try {
            $storeText = (& pnputil.exe /enum-devices /instanceid $record.InstanceId /drivers 2>&1 | Out-String)
            $infs = @([regex]::Matches($storeText,'(?i)oem\d+\.inf') | ForEach-Object { $_.Value.ToLowerInvariant() } | Select-Object -Unique)
            $summary = $(if ($infs.Count -gt 0) { 'Driver Store lists: ' + ($infs -join ', ') + ' for this device.' } else { 'Driver Store lists no driver package for this device.' })
            $record | Add-Member -NotePropertyName DriverStore -NotePropertyValue $summary -Force
        } catch { $record | Add-Member -NotePropertyName DriverStore -NotePropertyValue '' -Force }
    }
    $events = New-Object System.Collections.ArrayList
    try {
        $filter = @{ LogName='System'; ProviderName=@('Microsoft-Windows-Kernel-PnP','Microsoft-Windows-UserPnp','Microsoft-Windows-DriverFrameworks-UserMode','Service Control Manager'); StartTime=(Get-Date).AddDays(-$EventDays); Level=@(1,2,3) }
        foreach ($evt in @(Get-WinEvent -FilterHashtable $filter -MaxEvents 300 -ErrorAction Stop)) {
            $message = ''
            try { $message = ([string]$evt.Message -replace '\s+',' ').Trim() } catch {}
            if ($message.Length -gt 400) { $message = $message.Substring(0,400) }
            [void]$events.Add([pscustomobject]@{ TimeCreated=[string]$evt.TimeCreated; Provider=[string]$evt.ProviderName; Id=[int]$evt.Id; Level=[int]$evt.Level; Message=$message })
        }
    } catch {
        if ($_.Exception.Message -notmatch 'No events were found') { [void]$problems.Add('Event read failed: ' + $_.Exception.Message) }
    }
    return [pscustomobject]@{
        Devices=@($devices); Events=@($events); ElapsedMs=[long]$watch.ElapsedMilliseconds
        DetailReads=$detailDone; DetailTotal=$detailTotal; BudgetExceeded=$budgetExceeded; Problems=@($problems); EventDays=$EventDays
    }
}

# Turns the read-only snapshot (plus the Driver Center scan rows, for update information) into ordered findings.
# Order: devices with a problem first (essential families first), then update-only, then light checks. Healthy devices are only counted.
function New-AMRDriverSystemDiagnosis {
    param([Parameter(Mandatory=$true)]$Snapshot, $Rows = @())
    $devices = @(Get-AMRDiagProp $Snapshot 'Devices' @())
    $events = @(Get-AMRDiagProp $Snapshot 'Events' @())
    $byId = @{}
    foreach ($device in $devices) {
        $key = ([string](Get-AMRDiagProp $device 'InstanceId' '')).ToUpperInvariant()
        if ($key) { $byId[$key] = $device }
    }
    $rowById = @{}
    foreach ($row in @($Rows)) {
        $key = ([string](Get-AMRDiagProp $row 'DeviceId' '')).ToUpperInvariant()
        if ($key) { $rowById[$key] = $row }
    }
    $items = New-Object System.Collections.ArrayList
    $healthy = 0
    foreach ($device in $devices) {
        $id = [string](Get-AMRDiagProp $device 'InstanceId' '')
        $key = $id.ToUpperInvariant()
        $name = [string](Get-AMRDiagProp $device 'Name' '')
        $class = [string](Get-AMRDiagProp $device 'Class' '')
        $status = [string](Get-AMRDiagProp $device 'Status' '')
        $code = 0
        try { $code = [int](Get-AMRDiagProp $device 'ProblemCode' 0) } catch {}
        $row = $null
        if ($rowById.ContainsKey($key)) { $row = $rowById[$key] }
        $category = ''
        if ($row) { $category = [string](Get-AMRDiagProp $row 'ComponentCategory' '') }
        $family = Get-AMRDeviceFamily -Class $class -Name $name -Category $category
        $tier = 0
        $tierLabel = ''
        $assessment = ''
        $fix = ''
        $codeInfo = Get-AMRDriverProblemCodeInfo -Code $code
        $score = 0
        $evidence = New-Object System.Collections.ArrayList
        $against = New-Object System.Collections.ArrayList
        $unknown = New-Object System.Collections.ArrayList
        if ($code -ne 0) {
            $tier = 1; $tierLabel = 'Problem'
            $assessment = $codeInfo.Meaning
            $fix = $codeInfo.Fix
            [void]$evidence.Add(('Windows reports problem code {0} ({1}).' -f $code,$codeInfo.Name))
            if ($codeInfo.Specificity -eq 'Direct') { $score += 3 } else { $score += 1; [void]$unknown.Add('The code alone does not separate driver, firmware, resource and hardware causes.') }
            if (-not $codeInfo.Known) { $score -= 1; [void]$unknown.Add('This code is not in the built-in description table.') }
            if ($codeInfo.Causes) { [void]$evidence.Add('Typical causes: ' + $codeInfo.Causes) }
            $problemStatus = [string](Get-AMRDiagProp $device 'ProblemStatus' '')
            if ($problemStatus) { [void]$evidence.Add('Problem status: ' + $problemStatus + '.') }
            [void]$unknown.Add('Who or what changed the device (an app, a tool, an administrator) cannot be read from this data.')
            $storeNote = [string](Get-AMRDiagProp $device 'DriverStore' '')
            if ($storeNote) { [void]$evidence.Add($storeNote + ' (read-only check)') }
        } elseif ($status -eq 'Error' -or $status -eq 'Degraded') {
            $tier = 1; $tierLabel = 'Problem'
            $assessment = ('Windows reports the device status as {0}, but its problem code was not read, so the cause is not known.' -f $status)
            $fix = 'Run the diagnosis again; if it repeats, check the device in Device Manager. Nothing was changed.'
            [void]$evidence.Add(('Device status: {0}.' -f $status))
            [void]$unknown.Add('The problem code was not available for this device.')
        } elseif ($row) {
            $updateId = [string](Get-AMRDiagProp $row 'UpdateId' '')
            $updateReady = $false; try { $updateReady = [bool](Get-AMRDiagProp $row 'UpdateReady' $false) } catch {}
            $driverInf = [string](Get-AMRDiagProp $row 'DriverInf' '')
            $signed = $true; try { $signed = [bool](Get-AMRDiagProp $row 'DriverIsSigned' $true) } catch {}
            $hardwareIds = @(Get-AMRDiagProp $row 'HardwareIds' @())
            if ($updateId -or $updateReady) {
                $tier = 2; $tierLabel = 'Update available'
                $assessment = 'Windows Update offered a hardware-ID-matched driver. An available update is not evidence that the installed driver is faulty.'
                $fix = 'Review the candidate against the installed version before installing.'
                [void]$evidence.Add('A matched driver update was found by the Driver Center scan.')
                $score = 2
            } elseif ($driverInf -and -not $signed) {
                $tier = 3; $tierLabel = 'Light check'
                $assessment = 'The installed driver is not confirmed as signed by the inventory. This needs verification; it is not proof of a bad driver.'
                $fix = 'Verify the package signature. Do not disable signature enforcement.'
                [void]$evidence.Add('Inventory reports an INF but no confirmed signed state.')
                $score = 1
            } elseif (-not $driverInf -and $hardwareIds.Count -gt 0 -and $class -notmatch '(?i)^(SoftwareComponent|System|Extension|AudioEndpoint|Volume|VolumeSnapshot|Printer|WPD|Monitor|HIDClass|Keyboard|Mouse)$') {
                $tier = 3; $tierLabel = 'Light check'
                $assessment = 'A hardware device is present, but the signed-driver inventory shows no INF for it. It may use an inbox driver, or the inventory may be incomplete.'
                $fix = 'Refresh the inventory and check the device before concluding a driver is missing.'
                [void]$evidence.Add('No INF record in the signed-driver inventory.')
                $score = 1
            }
        }
        if ($tier -eq 0) { $healthy++; continue }

        $parentId = [string](Get-AMRDiagProp $device 'Parent' '')
        $parentText = ''
        $parentCode = 0
        if ($parentId) {
            $parentKey = $parentId.ToUpperInvariant()
            if ($byId.ContainsKey($parentKey)) {
                $parentDevice = $byId[$parentKey]
                try { $parentCode = [int](Get-AMRDiagProp $parentDevice 'ProblemCode' 0) } catch {}
                $parentText = ('{0} ({1})' -f [string](Get-AMRDiagProp $parentDevice 'Name' $parentId),$(if ($parentCode -ne 0) { 'problem code ' + $parentCode } else { 'no problem reported' }))
            } else { $parentText = $parentId + ' (not in the present-device list)' }
            if ($tier -eq 1) {
                if ($parentCode -ne 0) { $score += 1; [void]$evidence.Add('The parent device also reports a problem: ' + $parentText + '. The parent is the likelier starting point.') }
                else { [void]$evidence.Add('Parent device: ' + $parentText + '.') }
            }
        } elseif ($tier -eq 1) { [void]$unknown.Add('Parent device not read (no relation data for this device).') }
        $childrenText = ''
        $childIds = @(Get-AMRDiagProp $device 'Children' @())
        if ($childIds.Count -gt 0) {
            $childNames = @()
            foreach ($childId in ($childIds | Select-Object -First 5)) {
                $childKey = ([string]$childId).ToUpperInvariant()
                if ($byId.ContainsKey($childKey)) {
                    $childDevice = $byId[$childKey]
                    $childCode = 0; try { $childCode = [int](Get-AMRDiagProp $childDevice 'ProblemCode' 0) } catch {}
                    $childNames += ('{0}{1}' -f [string](Get-AMRDiagProp $childDevice 'Name' $childId),$(if ($childCode -ne 0) { ' [code ' + $childCode + ']' } else { '' }))
                }
            }
            if ($childNames.Count -gt 0) { $childrenText = $childNames -join '; '; if ($tier -eq 1) { [void]$evidence.Add('Child devices: ' + $childrenText + '.') } }
        }

        $matchedEvents = New-Object System.Collections.ArrayList
        $weakEvents = 0
        if ($tier -eq 1) {
            foreach ($evt in $events) {
                $message = [string](Get-AMRDiagProp $evt 'Message' '')
                if (-not $message) { continue }
                if ($id -and $message.IndexOf($id,[System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                    if ($matchedEvents.Count -lt 3) { [void]$matchedEvents.Add($evt) }
                } elseif ($name -and $name.Length -ge 5 -and $message.IndexOf($name,[System.StringComparison]::OrdinalIgnoreCase) -ge 0) { $weakEvents++ }
            }
            if ($matchedEvents.Count -gt 0) { $score += 2; [void]$evidence.Add(('{0} recent System event(s) name this exact device instance.' -f $matchedEvents.Count)) }
            else { [void]$unknown.Add('No recent System event names this exact device instance.') }
            if ($weakEvents -gt 0) { [void]$evidence.Add(('{0} recent event(s) mention the device name only; weak evidence, not used for confidence.' -f $weakEvents)) }
        }
        $confidence = 'Low'
        if ($score -ge 3) { $confidence = 'High' } elseif ($score -eq 2) { $confidence = 'Medium' }
        $severityRank = 0
        switch ($codeInfo.Severity) { 'High' { $severityRank = 3 } 'Medium' { $severityRank = 2 } 'Low' { $severityRank = 1 } default { $severityRank = 0 } }
        [void]$items.Add([pscustomobject]@{
            DeviceName=$name; DeviceId=$id; Class=$class; Family=$family; Status=$status; ProblemCode=$code; CodeName=$codeInfo.Name
            Tier=$tier; TierLabel=$tierLabel; Assessment=$assessment; SuggestedAction=$fix; Confidence=$confidence
            Evidence=@($evidence); Against=@($against); Unknown=@($unknown); Parent=$parentText; Children=$childrenText
            EventEvidence=@($matchedEvents); SortWeight=(Get-AMRDeviceFamilyWeight -Family $family); SeverityRank=$severityRank
        })
    }
    $ordered = @($items | Sort-Object @{Expression={$_.Tier};Ascending=$true}, @{Expression={$_.SeverityRank};Ascending=$false}, @{Expression={$_.SortWeight};Ascending=$false}, @{Expression={$_.DeviceName};Ascending=$true})

    # Family hypotheses (evidence, counter-evidence, unknowns, bounded confidence).
    $hypotheses = New-Object System.Collections.ArrayList
    $endpoints = @($devices | Where-Object { [string](Get-AMRDiagProp $_ 'Class' '') -match '^(?i)AudioEndpoint$' })
    $endpointsOk = @($endpoints | Where-Object { [string](Get-AMRDiagProp $_ 'Status' '') -eq 'OK' })
    $problemFamilies = @($ordered | Where-Object { $_.Tier -eq 1 } | Group-Object -Property Family)
    foreach ($group in $problemFamilies) {
        $family = [string]$group.Name
        $members = @($group.Group | Where-Object { $_.Class -notmatch '^(?i)AudioEndpoint$' })
        if ($members.Count -eq 0) { $members = @($group.Group) }
        $hEvidence = New-Object System.Collections.ArrayList
        $hAgainst = New-Object System.Collections.ArrayList
        $hUnknown = New-Object System.Collections.ArrayList
        foreach ($m in $members) { [void]$hEvidence.Add(('{0}: code {1} ({2}).' -f $m.DeviceName,$m.ProblemCode,$m.CodeName)) }
        $hScore = 1
        if (@($members | Where-Object { $_.Confidence -eq 'High' }).Count -gt 0) { $hScore = 2 }
        $title = ''
        $suggest = ''
        if ($family -eq 'Audio') {
            if ($endpointsOk.Count -eq 0) {
                $title = 'Audio may be unavailable: a sound component reports a problem and no working audio endpoint is present.'
                [void]$hEvidence.Add(('Audio endpoints present and working: 0 of {0}.' -f $endpoints.Count))
                $hScore += 1
                $suggest = 'Resolve the reported component first (see its suggested action), then check that endpoints appear.'
            } else {
                $title = 'Audio may be partly affected: a sound component reports a problem, but working audio endpoints exist.'
                [void]$hAgainst.Add(('{0} working audio endpoint(s) are present.' -f $endpointsOk.Count))
                $suggest = 'Check whether the missing function is one you use; the working endpoints suggest basic audio is available.'
            }
            [void]$hUnknown.Add('The link between a sound component and endpoint appearance is an engineering model, not a Microsoft-documented chain.')
        } else {
            $title = ('{0} function may be affected: {1} device(s) report a problem.' -f $family,$members.Count)
            $peers = @($devices | Where-Object { (Get-AMRDeviceFamily -Class ([string](Get-AMRDiagProp $_ 'Class' '')) -Name ([string](Get-AMRDiagProp $_ 'Name' ''))) -eq $family -and [int](Get-AMRDiagProp $_ 'ProblemCode' 0) -eq 0 -and [string](Get-AMRDiagProp $_ 'Status' '') -eq 'OK' })
            if ($peers.Count -gt 0) { [void]$hAgainst.Add(('{0} other {1} device(s) are working.' -f $peers.Count,$family)) }
            $suggest = 'See the suggested action on each device.'
            [void]$hUnknown.Add('This family rule is an engineering model; it has not been checked against a real fault on this computer.')
        }
        # Engineered rules never exceed Medium until they are confirmed on real logs.
        $hConfidence = 'Low'
        if ($hScore -ge 2) { $hConfidence = 'Medium' }
        [void]$hypotheses.Add([pscustomobject]@{ Family=$family; Title=$title; Confidence=$hConfidence; Evidence=@($hEvidence); Against=@($hAgainst); Unknown=@($hUnknown); Suggestion=$suggest })
    }
    # Healthy audio component but no endpoint at all: reported as a low-confidence observation only.
    $audioControllers = @($devices | Where-Object { (Get-AMRDeviceFamily -Class ([string](Get-AMRDiagProp $_ 'Class' '')) -Name ([string](Get-AMRDiagProp $_ 'Name' ''))) -eq 'Audio' -and [string](Get-AMRDiagProp $_ 'Class' '') -notmatch '^(?i)AudioEndpoint$' })
    $audioProblem = @($problemFamilies | Where-Object { $_.Name -eq 'Audio' })
    if ($audioProblem.Count -eq 0 -and $audioControllers.Count -gt 0 -and $endpointsOk.Count -eq 0) {
        [void]$hypotheses.Add([pscustomobject]@{
            Family='Audio'; Title='No working audio endpoint is present although sound components report no problem.'; Confidence='Low'
            Evidence=@(('Sound components present: {0}; working endpoints: 0.' -f $audioControllers.Count)); Against=@()
            Unknown=@('Endpoints can be absent when no output device is attached or an endpoint is disabled in Sound settings. Cause not determined.'); Suggestion='Check Sound settings; no driver problem is reported.'
        })
    }
    $counts = [pscustomobject]@{
        TotalDevices=$devices.Count; Healthy=$healthy
        Problem=@($ordered | Where-Object { $_.Tier -eq 1 }).Count
        UpdateOnly=@($ordered | Where-Object { $_.Tier -eq 2 }).Count
        LightCheck=@($ordered | Where-Object { $_.Tier -eq 3 }).Count
        AudioEndpointsWorking=$endpointsOk.Count; AudioEndpointsTotal=$endpoints.Count
    }
    $coverage = New-Object System.Collections.ArrayList
    [void]$coverage.Add(('Devices read: {0}. Relation reads (parent/child): {1} of {2}{3}.' -f $devices.Count,[int](Get-AMRDiagProp $Snapshot 'DetailReads' 0),[int](Get-AMRDiagProp $Snapshot 'DetailTotal' 0),$(if ([bool](Get-AMRDiagProp $Snapshot 'BudgetExceeded' $false)) { ' (time budget reached; the rest were skipped)' } else { '' })))
    [void]$coverage.Add(('System events read: {0} (last {1} days, warnings and above, up to 300).' -f $events.Count,[int](Get-AMRDiagProp $Snapshot 'EventDays' 7)))
    foreach ($problem in @(Get-AMRDiagProp $Snapshot 'Problems' @() | Select-Object -First 5)) { [void]$coverage.Add('Read problem: ' + [string]$problem) }
    return [pscustomobject]@{ Items=@($ordered); Hypotheses=@($hypotheses); Counts=$counts; Coverage=@($coverage); ElapsedMs=[long](Get-AMRDiagProp $Snapshot 'ElapsedMs' 0) }
}

function Format-AMRDriverSystemDiagnosisText {
    param([Parameter(Mandatory=$true)]$Diagnosis, [int]$MaxItems = 8)
    $c = $Diagnosis.Counts
    $lines = New-Object System.Collections.ArrayList
    [void]$lines.Add(('Read-only diagnosis of {0} device(s). Problems: {1}. Update only: {2}. Light check: {3}. Healthy: {4}.' -f $c.TotalDevices,$c.Problem,$c.UpdateOnly,$c.LightCheck,$c.Healthy))
    [void]$lines.Add('Nothing was changed on this computer.')
    $problemItems = @($Diagnosis.Items | Where-Object { $_.Tier -eq 1 })
    if ($problemItems.Count -gt 0) {
        [void]$lines.Add('')
        [void]$lines.Add('PROBLEMS (essential first)')
        foreach ($item in ($problemItems | Select-Object -First $MaxItems)) {
            [void]$lines.Add(('- {0} [{1}] code {2} {3}' -f $item.DeviceName,$item.Family,$item.ProblemCode,$item.CodeName))
            [void]$lines.Add(('  Meaning: {0}' -f $item.Assessment))
            [void]$lines.Add(('  Suggested: {0}  (confidence: {1})' -f $item.SuggestedAction,$item.Confidence))
            if ($item.Parent) { [void]$lines.Add('  Parent: ' + $item.Parent) }
        }
        if ($problemItems.Count -gt $MaxItems) { [void]$lines.Add(('  ... and {0} more problem device(s); all are in the Driver diagnostics log and the CSV export.' -f ($problemItems.Count - $MaxItems))) }
    }
    if (@($Diagnosis.Hypotheses).Count -gt 0) {
        [void]$lines.Add('')
        [void]$lines.Add('WHAT THIS MAY MEAN')
        foreach ($h in @($Diagnosis.Hypotheses | Select-Object -First 5)) {
            [void]$lines.Add(('- {0} (confidence: {1})' -f $h.Title,$h.Confidence))
            foreach ($u in @($h.Against | Select-Object -First 2)) { [void]$lines.Add('  Against: ' + $u) }
            foreach ($u in @($h.Unknown | Select-Object -First 1)) { [void]$lines.Add('  Not known: ' + $u) }
        }
    }
    if ($c.UpdateOnly -gt 0 -or $c.LightCheck -gt 0) {
        [void]$lines.Add('')
        [void]$lines.Add(('Lower priority: {0} device(s) have an available update and {1} need a light check. They are in the CSV export.' -f $c.UpdateOnly,$c.LightCheck))
    }
    [void]$lines.Add('')
    foreach ($note in @($Diagnosis.Coverage)) { [void]$lines.Add($note) }
    return ($lines -join "`n")
}

function Show-AMRDriverSystemDiagnosis {
    param([switch]$Auto)
    if ($script:DriverDiagJob) { return }
    if ($script:DriverScanJob -or $script:DriverActionJob -or $script:DriverManagedJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive) {
        if ($Auto) { return }
        Show-AMRMessageGlass 'Wait for the active Driver Center operation to finish before running a diagnosis.' 'Driver Operation Busy' OK Information | Out-Null
        return
    }
    if (@($script:DriverAllDeviceRows).Count -eq 0) {
        if ($Auto) { return }
        Show-AMRMessageGlass 'Run Scan Device first. The diagnosis uses the scan results and changes nothing.' 'Driver Diagnosis' OK Information | Out-Null
        return
    }
    $button = C 'DriverDiagnosisBtn'
    try {
        if ($button) { $button.IsEnabled = $false; $button.Content = 'Diagnosing...' }
        $statusText = C 'DriverActionStatus'
        # A1: this progress note is written to the driver log instead of the Driver Center page.
        try { Write-AMRDriverDiagnostic -Severity INFO -Operation SystemDiagnosis -Stage Progress -Message 'Reading all devices, device relations and recent events in the background. Nothing will be changed.' -Source 'AMRDriverSystemDiagnosis' } catch {}
        $script:DriverDiagStartedAt = Get-Date
        $script:DriverDiagAutoMode = [bool]$Auto
        try { Set-AMRDriverDiagBadge -Text $(if ($Auto) { 'Automatic diagnosis running in the background...' } else { 'Diagnosing...' }) -Color '#E9D8B5' } catch {}
        $definition = [string](Get-Command -Name Get-AMRDriverSystemReadPass -CommandType Function -ErrorAction Stop).Definition
        $script:DriverDiagJob = Start-Job -ArgumentList $definition -ScriptBlock {
            param($ReadPassDefinition)
            Set-Item -Path 'Function:\Get-AMRDriverSystemReadPass' -Value ([scriptblock]::Create([string]$ReadPassDefinition)) -Force
            Get-AMRDriverSystemReadPass
        }
        Write-AMRDriverDiagnostic -Severity INFO -Operation SystemDiagnosis -Stage Started -Message 'Read-only whole-system driver diagnosis started.' -Source 'AMRDriverSystemDiagnosis'
        if (-not $script:DriverDiagTimer) {
            $script:DriverDiagTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:DriverDiagTimer.Interval = [TimeSpan]::FromMilliseconds(500)
            $script:DriverDiagTimer.Add_Tick({
                try {
                    $job = $script:DriverDiagJob
                    $finish = $false
                    $snapshot = $null
                    $failure = ''
                    if (-not $job) { $finish = $true; $failure = 'The diagnosis job reference was lost.' }
                    elseif ($job.State -eq 'Running' -or $job.State -eq 'NotStarted') {
                        if (((Get-Date) - [datetime]$script:DriverDiagStartedAt).TotalSeconds -gt 150) {
                            try { Stop-Job -Job $job -ErrorAction SilentlyContinue } catch {}
                            $finish = $true; $failure = 'The diagnosis exceeded its 150-second limit and was stopped.'
                        }
                    } else {
                        $finish = $true
                        if ($job.State -eq 'Completed') {
                            $received = @(Receive-Job -Job $job -ErrorAction SilentlyContinue)
                            $withDevices = @($received | Where-Object { $_ -and $_.PSObject.Properties['Devices'] } | Select-Object -Last 1)
                            if ($withDevices.Count -gt 0) { $snapshot = $withDevices[0] } else { $failure = 'The diagnosis job returned no data.' }
                        } else { $failure = ('The diagnosis job ended as {0}.' -f [string]$job.State) }
                    }
                    if (-not $finish) { return }
                    $script:DriverDiagTimer.Stop()
                    if ($job) { try { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {} }
                    $script:DriverDiagJob = $null
                    Complete-AMRDriverSystemDiagnosis -Snapshot $snapshot -Failure $failure
                } catch {
                    try { $script:DriverDiagTimer.Stop() } catch {}
                    $script:DriverDiagJob = $null
                    Write-AMRDriverDiagnostic -Severity ERROR -Operation SystemDiagnosis -Stage Failed -Message 'The diagnosis polling step failed.' -Source 'AMRDriverSystemDiagnosis' -ErrorRecord $_
                    try { Update-AMRDriverActionButtons } catch {}
                }
            })
        }
        $script:DriverDiagTimer.Start()
    } catch {
        $script:DriverDiagJob = $null
        Write-AMRDriverDiagnostic -Severity ERROR -Operation SystemDiagnosis -Stage Failed -Message 'The diagnosis could not be started.' -Source 'AMRDriverSystemDiagnosis' -ErrorRecord $_
        if (-not $Auto) { Show-AMRGlassDialog -Message ('The diagnosis could not be started: ' + $_.Exception.Message) -Title 'AMR | Driver Diagnosis' -Icon Warning | Out-Null }
        try { Set-AMRDriverDiagBadge -Text 'Diagnosis could not start' -Color '#FCA5A5' } catch {}
        try { Update-AMRDriverActionButtons } catch {}
    }
}

function Complete-AMRDriverSystemDiagnosis {
    param($Snapshot, [string]$Failure = '')
    $button = C 'DriverDiagnosisBtn'
    try {
        if ($Failure -or $null -eq $Snapshot) {
            Write-AMRDriverDiagnostic -Severity WARNING -Operation SystemDiagnosis -Stage Failed -Message ('Diagnosis did not complete: ' + $Failure) -Source 'AMRDriverSystemDiagnosis' -Result 'Failed'
            $statusText = C 'DriverActionStatus'
            if ($statusText) { $statusText.Text = 'Diagnosis did not complete. Nothing was changed.' }
            try { Set-AMRDriverDiagBadge -Text 'Diagnosis did not complete' -Color '#FCA5A5' -Summary 'Nothing was changed. Press Re-diagnose to try again.' } catch {}
            if (-not $script:DriverDiagAutoMode) { Show-AMRGlassDialog -Message ('Diagnosis did not complete: ' + $Failure + "`n`nNothing was changed.") -Title 'AMR | Driver Diagnosis' -Icon Warning | Out-Null }
            return
        }
        $rows = @($script:DriverAllDeviceRows)
        $diagnosis = New-AMRDriverSystemDiagnosis -Snapshot $Snapshot -Rows $rows
        $script:DriverDiagLast = $diagnosis
        $script:DriverDiagSnapshot = $Snapshot
        # Attach the result to matching scan rows so the existing CSV export carries it (Add-Member keeps the row shape).
        foreach ($item in @($diagnosis.Items)) {
            $itemKey = ([string]$item.DeviceId).ToUpperInvariant()
            foreach ($row in $rows) {
                if (-not $row) { continue }
                if (([string](Get-AMRDiagProp $row 'DeviceId' '')).ToUpperInvariant() -ne $itemKey) { continue }
                $fields = [ordered]@{
                    DiagnosisTier=[string]$item.TierLabel; DiagnosisCategory=[string]$item.CodeName
                    DiagnosisConfidence=[string]$item.Confidence; DiagnosisAssessment=[string]$item.Assessment
                    DiagnosisRecommendedAction=[string]$item.SuggestedAction
                }
                foreach ($fieldName in $fields.Keys) { $row | Add-Member -NotePropertyName $fieldName -NotePropertyValue $fields[$fieldName] -Force }
                break
            }
        }
        foreach ($item in @($diagnosis.Items | Where-Object { $_.Tier -eq 1 })) {
            Write-AMRDriverDiagnostic -Severity WARNING -Operation SystemDiagnosis -Stage DeviceFinding -Message ('{0}: {1}' -f $item.CodeName,$item.Assessment) -DeviceId ([string]$item.DeviceId) -Source 'AMRDriverSystemDiagnosis' -Result ([string]$item.Confidence) -Context @{Family=$item.Family;ProblemCode=$item.ProblemCode;Parent=$item.Parent;Children=$item.Children;Evidence=(@($item.Evidence) -join ' | ');Unknown=(@($item.Unknown) -join ' | ')}
        }
        foreach ($h in @($diagnosis.Hypotheses)) {
            Write-AMRDriverDiagnostic -Severity INFO -Operation SystemDiagnosis -Stage Hypothesis -Message ([string]$h.Title) -Source 'AMRDriverSystemDiagnosis' -Result ([string]$h.Confidence) -Context @{Family=$h.Family;Evidence=(@($h.Evidence) -join ' | ');Against=(@($h.Against) -join ' | ');Unknown=(@($h.Unknown) -join ' | ')}
        }
        $counts = $diagnosis.Counts
        Write-AMRDriverDiagnostic -Severity INFO -Operation SystemDiagnosis -Stage Completed -Message ('Read-only diagnosis completed: {0} device(s), {1} problem(s), {2} update-only, {3} light check, {4} healthy; read pass {5} ms.' -f $counts.TotalDevices,$counts.Problem,$counts.UpdateOnly,$counts.LightCheck,$counts.Healthy,$diagnosis.ElapsedMs) -Source 'AMRDriverSystemDiagnosis' -DurationMs ([long]$diagnosis.ElapsedMs) -Result 'Completed' -Context @{Coverage=(@($diagnosis.Coverage) -join ' | ')}
        $statusText = C 'DriverActionStatus'
        if ($statusText) { $statusText.Text = ('Diagnosis completed: {0} device(s), {1} problem(s). Nothing was changed.' -f $counts.TotalDevices,$counts.Problem) }
        $script:DriverRepairCandidates = @(Get-AMRDriverRepairCandidates -Diagnosis $diagnosis -Snapshot $Snapshot)
        foreach ($cand in $script:DriverRepairCandidates) { Write-AMRDriverDiagnostic -Severity INFO -Operation SystemDiagnosis -Stage RepairEligible -Message ('Essential Code 22 device eligible for repair: ' + [string]$cand.DeviceName) -DeviceId ([string]$cand.DeviceId) -Source 'AMRDriverSystemDiagnosis' }
        try { Show-AMRDriverDiagResult -Diagnosis $diagnosis } catch {
            Write-AMRDriverDiagnostic -Severity WARNING -Operation SystemDiagnosis -Stage CardsFailed -Message ('Result cards failed, showing text: ' + $_.Exception.Message) -Source 'AMRDriverSystemDiagnosis'
            if (-not $script:DriverDiagAutoMode) { Show-AMRGlassDialog -Message (Format-AMRDriverSystemDiagnosisText -Diagnosis $diagnosis -MaxItems 8) -Title 'AMR | Driver Diagnosis (read-only)' | Out-Null }
        }
    } catch {
        Write-AMRDriverDiagnostic -Severity ERROR -Operation SystemDiagnosis -Stage Failed -Message 'Diagnosis result processing failed.' -Source 'AMRDriverSystemDiagnosis' -ErrorRecord $_
        try { Set-AMRDriverDiagBadge -Text 'Diagnosis could not be shown' -Color '#FCA5A5' } catch {}
        if (-not $script:DriverDiagAutoMode) { Show-AMRGlassDialog -Message ('Diagnosis could not be shown: ' + $_.Exception.Message + "`n`nNothing was changed.") -Title 'AMR | Driver Diagnosis' -Icon Warning | Out-Null }
    } finally {
        try { Update-AMRDriverActionButtons } catch {}
    }
}

# ===== A12: glass dialog, in-panel diagnosis cards, automatic diagnosis, Code 22 repair, restore-point prompt =====
# Shared glass dialog (style A: transparent layered glass; style B: solid rounded for weaker graphics; last resort: MessageBox).
# Returns the same literal strings a MessageBox would ('OK', 'Yes', 'No'). Used for Driver results only in A12.
function New-AMRGlassBrush {
    param([string]$Color)
    $converter = New-Object System.Windows.Media.BrushConverter
    return [System.Windows.Media.Brush]$converter.ConvertFromString($Color)
}

function New-AMRGlassButtonStyle {
    param([string]$Role = 'Blue',[switch]$Animated)
    $c = @{ Top='#F23A6FE0'; Bottom='#F21B3FA0'; Edge='#CC3F6FE0'; HoverTop='#FF2F63DB'; HoverBottom='#FF16379A'; PressTop='#FF1F4FB8'; PressBottom='#FF122C78'; HoverEdge='#FF5B8CF5'; Sheen='#26FFFFFF' }
    if ($Role -eq 'Red') { $c = @{ Top='#D9E5646B'; Bottom='#D9A52030'; Edge='#99FFC2C6'; HoverTop='#F2F2808A'; HoverBottom='#F2C22A3C'; PressTop='#FFB8303F'; PressBottom='#FF7F1624'; HoverEdge='#FFFFFFFF'; Sheen='#55FFFFFF' } }
    # A4: -Animated adds a 220 ms hover (glow fades in, tiny lift). Used only by the Candidate and Source manager windows.
    $rootOpen = '<Grid>'
    $overlayXaml = ''
    # A5: the plain (A3) hover block is the default; -Animated replaces it with the 220 ms animated block below.
    $hoverTriggerXaml = @"
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="GlassButtonBorder" Property="Background">
              <Setter.Value><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="$($c.HoverTop)" Offset="0"/><GradientStop Color="$($c.HoverBottom)" Offset="1"/></LinearGradientBrush></Setter.Value>
            </Setter>
            <Setter TargetName="GlassButtonBorder" Property="BorderBrush" Value="$($c.HoverEdge)"/>
          </Trigger>
"@
    $pressTarget = 'GlassButtonBorder'
    if ($Animated) {
        $rootOpen = '<Grid x:Name="GlassButtonRoot" RenderTransformOrigin="0.5,0.5"><Grid.RenderTransform><TransformGroup><ScaleTransform ScaleX="1" ScaleY="1"/><TranslateTransform Y="0"/></TransformGroup></Grid.RenderTransform>'
        $overlayXaml = @"
          <Border x:Name="GlassButtonHover" BorderBrush="$($c.HoverEdge)" BorderThickness="1" CornerRadius="9" Opacity="0" IsHitTestVisible="False" SnapsToDevicePixels="True">
            <Border.Background>
              <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="$($c.HoverTop)" Offset="0"/><GradientStop Color="$($c.HoverBottom)" Offset="1"/></LinearGradientBrush>
            </Border.Background>
          </Border>
"@
        $pressTarget = 'GlassButtonHover'
        $hoverTriggerXaml = @"
          <MultiTrigger>
            <MultiTrigger.Conditions>
              <Condition Property="IsMouseOver" Value="True"/>
              <Condition Property="IsEnabled" Value="True"/>
            </MultiTrigger.Conditions>
            <MultiTrigger.EnterActions>
              <BeginStoryboard>
                <Storyboard>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonHover" Storyboard.TargetProperty="Opacity" To="1" Duration="0:0:0.22"/>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1.03" Duration="0:0:0.22"/>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1.03" Duration="0:0:0.22"/>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="-1" Duration="0:0:0.22"/>
                </Storyboard>
              </BeginStoryboard>
            </MultiTrigger.EnterActions>
            <MultiTrigger.ExitActions>
              <BeginStoryboard>
                <Storyboard>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonHover" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.22"/>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.22"/>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[0].(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.22"/>
                  <DoubleAnimation Storyboard.TargetName="GlassButtonRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TransformGroup.Children)[1].(TranslateTransform.Y)" To="0" Duration="0:0:0.22"/>
                </Storyboard>
              </BeginStoryboard>
            </MultiTrigger.ExitActions>
          </MultiTrigger>
          <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="GlassButtonBorder" Property="BorderBrush" Value="$($c.HoverEdge)"/></Trigger>
"@
    }
    $styleXaml = @"
<Style xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" TargetType="{x:Type Button}">
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Foreground" Value="#FFFFFFFF"/>
  <Setter Property="FontWeight" Value="SemiBold"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="{x:Type Button}">
        $rootOpen
          <Border x:Name="GlassButtonBorder" BorderBrush="$($c.Edge)" BorderThickness="1" CornerRadius="9" SnapsToDevicePixels="True">
            <Border.Background>
              <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="$($c.Top)" Offset="0"/><GradientStop Color="$($c.Bottom)" Offset="1"/></LinearGradientBrush>
            </Border.Background>
          </Border>
$overlayXaml
          <Border x:Name="GlassButtonSheen" CornerRadius="9,9,0,0" Margin="1,1,1,0" VerticalAlignment="Top" Height="14" IsHitTestVisible="False">
            <Border.Background>
              <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="$($c.Sheen)" Offset="0"/><GradientStop Color="#00FFFFFF" Offset="1"/></LinearGradientBrush>
            </Border.Background>
          </Border>
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="14,3" RecognizesAccessKey="True"/>
        </Grid>
        <ControlTemplate.Triggers>
$hoverTriggerXaml
          <Trigger Property="IsKeyboardFocused" Value="True"><Setter TargetName="GlassButtonBorder" Property="BorderBrush" Value="$($c.HoverEdge)"/></Trigger>
          <Trigger Property="IsPressed" Value="True">
            <Setter TargetName="$pressTarget" Property="Background">
              <Setter.Value><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="$($c.PressTop)" Offset="0"/><GradientStop Color="$($c.PressBottom)" Offset="1"/></LinearGradientBrush></Setter.Value>
            </Setter>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
"@
    return [Windows.Markup.XamlReader]::Parse($styleXaml)
}

function Invoke-AMRGlassDialogTier {
    param([string]$Tier,[string]$Message,[string]$Title,[string]$Buttons,[string]$Icon)
    $perfDlg = Get-AMRPerfNow
    $state = @{ Result = $(if ($Buttons -eq 'YesNo') { 'No' } else { 'OK' }) }
    $window = New-Object System.Windows.Window
    $window.WindowStyle = 'None'
    $window.ResizeMode = 'NoResize'
    $window.ShowInTaskbar = $false
    $window.SizeToContent = 'Height'
    $window.Width = 580
    $workHeight = 700
    try { $workHeight = [double][System.Windows.SystemParameters]::WorkArea.Height } catch {}
    $window.MaxHeight = [math]::Max(300, [math]::Floor($workHeight * 0.85))
    $window.WindowStartupLocation = 'CenterScreen'
    try { if ($script:Window -and $script:Window.IsVisible) { $window.Owner = $script:Window; $window.WindowStartupLocation = 'CenterOwner' } } catch {}
    $root = New-Object System.Windows.Controls.Border
    $root.CornerRadius = New-Object System.Windows.CornerRadius(14)
    $root.BorderThickness = New-Object System.Windows.Thickness(1)
    if ($Tier -eq 'A') {
        $window.AllowsTransparency = $true
        $window.Background = [System.Windows.Media.Brushes]::Transparent
        $gradient = New-Object System.Windows.Media.LinearGradientBrush
        $gradient.StartPoint = New-Object System.Windows.Point(0,0); $gradient.EndPoint = New-Object System.Windows.Point(1,1)
        $gradient.GradientStops.Add((New-Object System.Windows.Media.GradientStop((New-AMRGlassBrush '#F0202B3A').Color, 0.0))) | Out-Null
        $gradient.GradientStops.Add((New-Object System.Windows.Media.GradientStop((New-AMRGlassBrush '#F0111823').Color, 1.0))) | Out-Null
        $root.Background = $gradient
        $root.BorderBrush = New-AMRGlassBrush '#66E9D8B5'
        $root.Margin = New-Object System.Windows.Thickness(6)
    } else {
        $window.Background = New-AMRGlassBrush '#FF141B27'
        $root.Background = New-AMRGlassBrush '#FF18212E'
        $root.BorderBrush = New-AMRGlassBrush '#88E9D8B5'
    }
    $grid = New-Object System.Windows.Controls.Grid
    foreach ($h in @('Auto','*','Auto')) { $rd = New-Object System.Windows.Controls.RowDefinition; $rd.Height = [System.Windows.GridLength]::Auto; if ($h -eq '*') { $rd.Height = New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star) }; $grid.RowDefinitions.Add($rd) }
    # Title row (drag handle + close).
    $titleGrid = New-Object System.Windows.Controls.Grid
    $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)
    $c2 = New-Object System.Windows.Controls.ColumnDefinition; $c2.Width = [System.Windows.GridLength]::Auto
    $titleGrid.ColumnDefinitions.Add($c1); $titleGrid.ColumnDefinitions.Add($c2)
    $titleGrid.Margin = New-Object System.Windows.Thickness(18,12,10,6)
    $titleText = New-Object System.Windows.Controls.TextBlock
    $glyph = ''; switch ($Icon) { 'Warning' { $glyph = ([string][char]0x26A0) + '  ' } 'Error' { $glyph = ([string][char]0x2716) + '  ' } 'Information' { $glyph = ([string][char]0x2139) + '  ' } 'Question' { $glyph = '?  ' } }
    $titleText.Text = ($glyph + $Title); $titleText.FontSize = 14; $titleText.FontWeight = 'Bold'; $titleText.Foreground = New-AMRGlassBrush '#E9D8B5'; $titleText.VerticalAlignment = 'Center'; $titleText.TextTrimming = 'CharacterEllipsis'
    [System.Windows.Controls.Grid]::SetColumn($titleText,0)
    $closeButton = New-Object System.Windows.Controls.Button
    $closeButton.Content = [string][char]0x2715; $closeButton.Width = 30; $closeButton.Height = 26; $closeButton.Background = [System.Windows.Media.Brushes]::Transparent
    $closeButton.Foreground = New-AMRGlassBrush '#CBD5E1'; $closeButton.BorderThickness = New-Object System.Windows.Thickness(0); $closeButton.Cursor = [System.Windows.Input.Cursors]::Hand
    # A13d: soft round close button. Hover is a translucent red glow (no pale default square), visual only.
    try {
        $closeButton.Width = 28; $closeButton.Height = 28; $closeButton.FocusVisualStyle = $null
        $closeTemplateXaml = @"
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" TargetType="{x:Type Button}">
  <Grid>
    <Border x:Name="CloseFace" CornerRadius="14" Background="#00000000" BorderBrush="#00000000" BorderThickness="1">
      <ContentPresenter x:Name="CloseGlyph" HorizontalAlignment="Center" VerticalAlignment="Center" TextElement.Foreground="#FFCBD5E1"/>
    </Border>
  </Grid>
  <ControlTemplate.Triggers>
    <Trigger Property="IsMouseOver" Value="True">
      <Setter TargetName="CloseFace" Property="Background" Value="#55E5646B"/>
      <Setter TargetName="CloseFace" Property="BorderBrush" Value="#99E5646B"/>
      <Setter TargetName="CloseGlyph" Property="TextElement.Foreground" Value="#FFFFD9DC"/>
    </Trigger>
    <Trigger Property="IsPressed" Value="True">
      <Setter TargetName="CloseFace" Property="Background" Value="#88B52A38"/>
    </Trigger>
  </ControlTemplate.Triggers>
</ControlTemplate>
"@
        $closeButton.Template = [Windows.Markup.XamlReader]::Parse($closeTemplateXaml)
    } catch {
        try { Write-AMRDriverDiagnostic -Severity WARNING -Operation GlassDialog -Stage CloseStyleFallback -Message ('Close button used the default template: ' + $_.Exception.Message) -Source 'AMRGlassDialog' } catch {}
    }
    [System.Windows.Controls.Grid]::SetColumn($closeButton,1)
    $titleGrid.Children.Add($titleText) | Out-Null; $titleGrid.Children.Add($closeButton) | Out-Null
    [System.Windows.Controls.Grid]::SetRow($titleGrid,0)
    $titleGrid.Add_MouseLeftButtonDown({ param($s,$e) try { $w = [System.Windows.Window]::GetWindow($s); if ($w) { $w.DragMove() } } catch {} })
    # Body.
    $scroll = New-Object System.Windows.Controls.ScrollViewer
    $scroll.VerticalScrollBarVisibility = 'Auto'; $scroll.Margin = New-Object System.Windows.Thickness(18,4,18,8)
    $body = New-Object System.Windows.Controls.TextBlock
    $body.Text = $Message; $body.TextWrapping = 'Wrap'; $body.FontSize = 12; $body.Foreground = New-AMRGlassBrush '#E2E8F0'; $body.LineHeight = 18
    $scroll.Content = $body
    [System.Windows.Controls.Grid]::SetRow($scroll,1)
    # Buttons.
    $buttonPanel = New-Object System.Windows.Controls.StackPanel
    $buttonPanel.Orientation = 'Horizontal'; $buttonPanel.HorizontalAlignment = 'Right'; $buttonPanel.Margin = New-Object System.Windows.Thickness(18,6,18,16)
    [System.Windows.Controls.Grid]::SetRow($buttonPanel,2)
    $makeButton = {
        param([string]$Text,[string]$Value,[bool]$IsDefault)
        $b = New-Object System.Windows.Controls.Button
        $b.Content = $Text; $b.MinWidth = 96; $b.Height = 32; $b.Margin = New-Object System.Windows.Thickness(8,0,0,0)
        $b.Foreground = New-AMRGlassBrush '#F4F7FA'; $b.Background = New-AMRGlassBrush $(if ($IsDefault) { '#FF2F5E85' } else { '#FF303846' })
        $b.BorderBrush = New-AMRGlassBrush '#FF526176'; $b.Cursor = [System.Windows.Input.Cursors]::Hand; $b.Tag = $Value
        $b.IsDefault = $false
        try { $b.Style = New-AMRGlassButtonStyle -Role $(if ($Value -eq 'No') { 'Red' } else { 'Blue' }) -Animated } catch { try { Write-AMRDriverDiagnostic -Severity WARNING -Operation GlassDialog -Stage ButtonFallback -Message ('Dialog button kept the default look: ' + $_.Exception.Message) -Source 'AMRGlassDialog' } catch {} }
        return $b
    }
    $buttonList = @()
    if ($Buttons -eq 'YesNo') { $buttonList += (& $makeButton 'Yes' 'Yes' $false); $buttonList += (& $makeButton 'No' 'No' $true) } else { $buttonList += (& $makeButton 'OK' 'OK' $true) }
    foreach ($b in $buttonList) {
        $b.Add_Click({ param($s,$e) $state['Result'] = [string]$s.Tag; [System.Windows.Window]::GetWindow($s).Close() }.GetNewClosure())
        $buttonPanel.Children.Add($b) | Out-Null
    }
    $closeButton.Add_Click({ param($s,$e) [System.Windows.Window]::GetWindow($s).Close() })
    $window.Add_PreviewKeyDown({ param($s,$e) if ($e.Key -eq [System.Windows.Input.Key]::Escape) { $e.Handled = $true; $s.Close() } })
    $grid.Children.Add($titleGrid) | Out-Null; $grid.Children.Add($scroll) | Out-Null; $grid.Children.Add($buttonPanel) | Out-Null
    $root.Child = $grid
    $window.Content = $root
    $defaultButton = $buttonList[$buttonList.Count - 1]
    $window.Add_ContentRendered({ try { $defaultButton.Focus() | Out-Null } catch {} }.GetNewClosure())
    Add-AMRPerfSince ('dialog.build.tier' + $Tier) $perfDlg
    [void]$window.ShowDialog()
    return [string]$state['Result']
}

function Show-AMRGlassDialog {
    param([string]$Message,[string]$Title='AMR | Driver Center',[ValidateSet('OK','YesNo')][string]$Buttons='OK',[string]$Icon='Information')
    $tiers = @('A','B')
    try { if (([int]([System.Windows.Media.RenderCapability]::Tier -shr 16)) -lt 2) { $tiers = @('B') } } catch {}
    foreach ($tier in $tiers) {
        try {
            $result = Invoke-AMRGlassDialogTier -Tier $tier -Message $Message -Title $Title -Buttons $Buttons -Icon $Icon
            if ($result) { return [string](@($result)[-1]) }
        } catch {
            try { Write-AMRDriverDiagnostic -Severity WARNING -Operation GlassDialog -Stage Fallback -Message ('Glass dialog style {0} failed: {1}' -f $tier,$_.Exception.Message) -Source 'AMRGlassDialog' } catch {}
        }
    }
    $mbButtons = [System.Windows.MessageBoxButton]::OK; if ($Buttons -eq 'YesNo') { $mbButtons = [System.Windows.MessageBoxButton]::YesNo }
    $mbIcon = [System.Windows.MessageBoxImage]::Information; if ($Icon -eq 'Warning') { $mbIcon = [System.Windows.MessageBoxImage]::Warning }
    return [string](Show-AMRMessage $Message $Title $mbButtons $mbIcon)
}

# Drop-in replacement for Show-AMRMessage on selected result and consent windows (same text, buttons, return values).
# Returns a real [System.Windows.MessageBoxResult]. Any other button set, or any failure, uses the original MessageBox.
function Show-AMRMessageGlass {
    param(
        [string]$Message,
        [string]$Title='Amr | windows_utility',
        [System.Windows.MessageBoxButton]$Buttons=[System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]$Icon=[System.Windows.MessageBoxImage]::Information
    )
    try {
        if ($Buttons -eq [System.Windows.MessageBoxButton]::OK -or $Buttons -eq [System.Windows.MessageBoxButton]::YesNo) {
            $iconName = 'Information'
            if ($Icon -eq [System.Windows.MessageBoxImage]::Warning) { $iconName = 'Warning' } elseif ($Icon -eq [System.Windows.MessageBoxImage]::Error) { $iconName = 'Error' } elseif ($Icon -eq [System.Windows.MessageBoxImage]::Question) { $iconName = 'Question' }
            $answer = Show-AMRGlassDialog -Message $Message -Title $Title -Buttons $(if ($Buttons -eq [System.Windows.MessageBoxButton]::YesNo) { 'YesNo' } else { 'OK' }) -Icon $iconName
            if ($answer -eq 'Yes') { return [System.Windows.MessageBoxResult]::Yes }
            if ($answer -eq 'No') { return [System.Windows.MessageBoxResult]::No }
            return [System.Windows.MessageBoxResult]::OK
        }
    } catch {
        try { Write-AMRDriverDiagnostic -Severity WARNING -Operation GlassDialog -Stage Fallback -Message ('Glass message failed, using MessageBox: ' + $_.Exception.Message) -Source 'AMRGlassDialog' } catch {}
    }
    return (Show-AMRMessage $Message $Title $Buttons $Icon)
}

# A2: "Open in Driver Update" button on each problem card. Selection and navigation only; nothing is installed or changed.
function Find-AMRDriverRowByDevice {
    param($Rows,[string]$DeviceId,[string]$DeviceName)
    $byName = New-Object System.Collections.ArrayList
    foreach ($candidateRow in @($Rows)) {
        if ($null -eq $candidateRow) { continue }
        $rowId = [string](Get-AMRDiagProp $candidateRow 'DeviceId' '')
        if (-not [string]::IsNullOrWhiteSpace($DeviceId) -and -not [string]::IsNullOrWhiteSpace($rowId) -and [string]::Equals($rowId,$DeviceId,[System.StringComparison]::OrdinalIgnoreCase)) { return $candidateRow }
        $rowName = [string](Get-AMRDiagProp $candidateRow 'DeviceName' '')
        if (-not [string]::IsNullOrWhiteSpace($DeviceName) -and [string]::Equals($rowName,$DeviceName,[System.StringComparison]::OrdinalIgnoreCase)) { [void]$byName.Add($candidateRow) }
    }
    # Name is only a fallback and only when it is unambiguous.
    if ($byName.Count -eq 1) { return $byName[0] }
    return $null
}

function Invoke-AMRDriverProblemGoto {
    param($Info)
    $deviceId = [string](Get-AMRDiagProp $Info 'DeviceId' '')
    $deviceName = [string](Get-AMRDiagProp $Info 'DeviceName' '')
    $label = $(if ([string]::IsNullOrWhiteSpace($deviceName)) { 'this device' } else { $deviceName })
    $list = C 'DriverDeviceList'
    if (-not $list) { return }
    if ($script:DriverScanJob -or $script:DriverActionJob -or $script:DriverManagedJob -or $script:DriverRepairJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive) {
        Show-AMRGlassDialog -Message 'Wait for the active Driver Center operation to finish first.' -Title 'AMR | Driver Center' | Out-Null
        return
    }
    $row = Find-AMRDriverRowByDevice -Rows @($list.ItemsSource) -DeviceId $deviceId -DeviceName $deviceName
    if (-not $row) {
        # The row may be hidden by the search box or by the Smart filter. Clear the search text and look again.
        $inventoryRow = Find-AMRDriverRowByDevice -Rows @($script:DriverAllDeviceRows) -DeviceId $deviceId -DeviceName $deviceName
        if ($inventoryRow) {
            try { if ($script:SmartSearchBox -and -not [string]::IsNullOrWhiteSpace([string]$script:SmartSearchBox.Text)) { $script:SmartSearchBox.Text = '' } } catch {}
            Update-AMRDriverSearchView -Query ''
            $row = Find-AMRDriverRowByDevice -Rows @($list.ItemsSource) -DeviceId $deviceId -DeviceName $deviceName
        }
    }
    if (-not $row) {
        Write-AMRDriverDiagnostic -Severity INFO -Operation ProblemGoto -Stage RowNotFound -Message ('No Driver Update row matched the problem device "{0}".' -f $label) -DeviceId $deviceId -Source 'Invoke-AMRDriverProblemGoto'
        Show-AMRGlassDialog -Message ("The device list has no row for $label in the current scan.`n`nRun Scan Device again, then Diagnose. Nothing was changed.") -Title 'AMR | Driver Center' -Icon Information | Out-Null
        return
    }
    Set-AMRDriverTab -Tab 'Update'
    $list.SelectedItems.Clear()
    $list.SelectedItem = $row
    $script:DriverGotoRow = $row
    try {
        $script:Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Loaded,[Action]{
            try {
                $gotoList = C 'DriverDeviceList'; $gotoRow = $script:DriverGotoRow
                if ($gotoList -and $gotoRow) { $gotoList.UpdateLayout(); $gotoList.ScrollIntoView($gotoRow) }
                $gotoPane = C 'DriverUpdatePane'; if ($gotoPane) { $gotoPane.BringIntoView() }
            } catch {}
        }) | Out-Null
    } catch {}
    $hasUpdate = -not [string]::IsNullOrWhiteSpace([string](Get-AMRDiagProp $row 'UpdateId' ''))
    $isReady = ($hasUpdate -and [bool](Get-AMRDiagProp $row 'UpdateReady' $false))
    $smartMode = ($script:DriverExperienceMode -eq 'Smart')
    $outcome = 'NoUpdate'
    $statusText = C 'DriverActionStatus'
    if ($isReady) {
        $outcome = 'UpdateReady'
        if ($statusText) { $statusText.Text = $(if ($smartMode) { ('Selected "{0}". A ready update exists. Use Start Smart Install when you want to install it.' -f $label) } else { ('Selected "{0}". A ready update exists. Use Install Ready Update when you want to install it.' -f $label) }) }
    } elseif ($hasUpdate) {
        $outcome = 'UpdateNotReady'
        if ($statusText) { $statusText.Text = $(if ($smartMode) { ('Selected "{0}". An update was found but is not prepared yet. Use Smart Select, then Start Smart Install.' -f $label) } else { ('Selected "{0}". An update was found but is not downloaded yet. Use Download & Save Package first.' -f $label) }) }
    } else {
        $tail = $(if ($smartMode) { 'Switch to Professional mode to compare candidates or check other sources for it.' } else { 'You can use Source Manager or Check Rollback on it.' })
        Show-AMRGlassDialog -Message ("No ready driver update exists for $label in the current scan, so there is nothing to install for it from here.`n`nThe device is selected in Driver Update. $tail`nNothing was changed.") -Title 'AMR | Driver Center' -Icon Information | Out-Null
    }
    Write-AMRDriverDiagnostic -Severity INFO -Operation ProblemGoto -Stage Selected -Message ('Selected "{0}" in Driver Update from its problem card (outcome {1}). Nothing was installed or changed.' -f $label,$outcome) -DeviceId $deviceId -Source 'Invoke-AMRDriverProblemGoto'
}

function Start-AMRProblemGotoHover {
    param($Button,[bool]$On)
    $glyph = $Button.Content
    if (-not $glyph -or -not ($glyph.RenderTransform -is [System.Windows.Media.TransformGroup])) { return }
    $ease = New-Object System.Windows.Media.Animation.CubicEase; $ease.EasingMode = 'EaseOut'
    $scaleTo = $(if ($On) { 1.14 } else { 1.0 }); $angleTo = $(if ($On) { -8.0 } else { 0.0 })
    $scaleX = New-Object System.Windows.Media.Animation.DoubleAnimation; $scaleX.To = $scaleTo; $scaleX.Duration = [TimeSpan]::FromMilliseconds(220); $scaleX.EasingFunction = $ease
    $scaleY = New-Object System.Windows.Media.Animation.DoubleAnimation; $scaleY.To = $scaleTo; $scaleY.Duration = [TimeSpan]::FromMilliseconds(220); $scaleY.EasingFunction = $ease
    $turn = New-Object System.Windows.Media.Animation.DoubleAnimation; $turn.To = $angleTo; $turn.Duration = [TimeSpan]::FromMilliseconds(220); $turn.EasingFunction = $ease
    $glyph.RenderTransform.Children[0].BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$scaleX)
    $glyph.RenderTransform.Children[0].BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$scaleY)
    $glyph.RenderTransform.Children[1].BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$turn)
}

function New-AMRProblemGotoButton {
    param([string]$DeviceId,[string]$DeviceName)
    $button = New-Object System.Windows.Controls.Button
    $button.Width = 44; $button.Height = 44; $button.Padding = New-Object System.Windows.Thickness(0)
    $button.Margin = New-Object System.Windows.Thickness(12,0,0,0)
    $button.HorizontalAlignment = 'Right'; $button.VerticalAlignment = 'Top'
    $button.Background = New-AMRGlassBrush '#33D8B56D'; $button.BorderBrush = New-AMRGlassBrush '#99D8B56D'
    $button.BorderThickness = New-Object System.Windows.Thickness(1)
    $button.ToolTip = 'Open this device in Driver Update. It is selected for you; nothing is installed or changed.'
    $button.Tag = [pscustomobject]@{ DeviceId = $DeviceId; DeviceName = $DeviceName }
    # Chip icon (vector, no font dependency): hardware with pins.
    $icon = New-Object System.Windows.Shapes.Path
    $icon.Data = [System.Windows.Media.Geometry]::Parse('M7,7 H17 V17 H7 Z M10,10 H14 V14 H10 Z M9.5,2.5 V5 M14.5,2.5 V5 M9.5,19 V21.5 M14.5,19 V21.5 M2.5,9.5 H5 M2.5,14.5 H5 M19,9.5 H21.5 M19,14.5 H21.5')
    $icon.Width = 24; $icon.Height = 24; $icon.Stretch = [System.Windows.Media.Stretch]::None
    $icon.Stroke = New-AMRGlassBrush '#FFE9D8B5'; $icon.StrokeThickness = 1.7
    $icon.StrokeStartLineCap = [System.Windows.Media.PenLineCap]::Round; $icon.StrokeEndLineCap = [System.Windows.Media.PenLineCap]::Round; $icon.StrokeLineJoin = [System.Windows.Media.PenLineJoin]::Round
    $icon.HorizontalAlignment = 'Center'; $icon.VerticalAlignment = 'Center'
    $icon.RenderTransformOrigin = New-Object System.Windows.Point(0.5,0.5)
    $group = New-Object System.Windows.Media.TransformGroup
    [void]$group.Children.Add((New-Object System.Windows.Media.ScaleTransform(1.0,1.0)))
    [void]$group.Children.Add((New-Object System.Windows.Media.RotateTransform(0.0)))
    $icon.RenderTransform = $group
    $button.Content = $icon
    $button.Add_MouseEnter({ try { Start-AMRProblemGotoHover -Button $this -On $true } catch {} })
    $button.Add_MouseLeave({ try { Start-AMRProblemGotoHover -Button $this -On $false } catch {} })
    $button.Add_Click({ try { Invoke-AMRDriverProblemGoto -Info $this.Tag } catch { try { Write-AMRDriverDiagnostic -Severity WARNING -Operation ProblemGoto -Stage Failed -Message ('The problem card button failed: ' + $_.Exception.Message) -Source 'Invoke-AMRDriverProblemGoto' } catch {} } })
    return $button
}

# ----- In-panel result cards (problems first). Read-only view of $script:DriverDiagLast. -----
function Add-AMRDriverDiagCard {
    param($Item,$Panel)
    # A13c: large premium card. Same data as before (device, family, code, assessment, suggestion,
    # confidence, evidence/against/unknown/parent). No shadow effects, so many cards stay light on any hardware.
    $deep = [string][char]0x26A0
    $confidence = [string](Get-AMRDiagProp $Item 'Confidence' '')
    $accent = '#FF64748B'; if ($confidence -eq 'High') { $accent = '#FFD8B56D' } elseif ($confidence -eq 'Medium') { $accent = '#FF8FA9C9' }
    $baseFill = $null; $baseEdge = $null
    try { $baseFill = $script:Window.TryFindResource('ActivationInnerGlassBrush'); $baseEdge = $script:Window.TryFindResource('ActivationGlassEdgeBrush') } catch {}
    if (-not $baseFill) { $baseFill = New-AMRGlassBrush '#40202C3A' }
    if (-not $baseEdge) { $baseEdge = New-AMRGlassBrush '#FF526176' }
    $accentBrush = New-AMRGlassBrush $accent

    $card = New-Object System.Windows.Controls.Border
    $card.Margin = New-Object System.Windows.Thickness(0,0,0,14)
    $card.CornerRadius = New-Object System.Windows.CornerRadius(14); $card.BorderThickness = New-Object System.Windows.Thickness(1)
    $card.Background = $baseFill
    $card.BorderBrush = $baseEdge

    $grid = New-Object System.Windows.Controls.Grid
    $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = New-Object System.Windows.GridLength(6)
    $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)
    $grid.ColumnDefinitions.Add($c0); $grid.ColumnDefinitions.Add($c1)
    $bar = New-Object System.Windows.Controls.Border
    $bar.CornerRadius = New-Object System.Windows.CornerRadius(14,0,0,14); $bar.Background = New-AMRGlassBrush $accent
    [System.Windows.Controls.Grid]::SetColumn($bar,0)
    $grid.Children.Add($bar) | Out-Null

    $stack = New-Object System.Windows.Controls.StackPanel
    $stack.Margin = New-Object System.Windows.Thickness(18,16,18,16)
    [System.Windows.Controls.Grid]::SetColumn($stack,1)

    # Header: icon + device name + chips
    $head = New-Object System.Windows.Controls.StackPanel; $head.Orientation = 'Horizontal'
    $icon = New-Object System.Windows.Controls.Border
    $icon.Width = 40; $icon.Height = 40; $icon.CornerRadius = New-Object System.Windows.CornerRadius(20); $icon.Margin = New-Object System.Windows.Thickness(0,0,14,0)
    $icon.Background = New-AMRGlassBrush '#26FFFFFF'; $icon.BorderThickness = New-Object System.Windows.Thickness(1); $icon.BorderBrush = New-AMRGlassBrush $accent
    $glyph = New-Object System.Windows.Controls.TextBlock; $glyph.Text = $deep; $glyph.FontSize = 19; $glyph.Foreground = New-AMRGlassBrush $accent
    $glyph.HorizontalAlignment = 'Center'; $glyph.VerticalAlignment = 'Center'
    $icon.Child = $glyph
    $titleBox = New-Object System.Windows.Controls.StackPanel; $titleBox.VerticalAlignment = 'Center'
    $title = New-Object System.Windows.Controls.TextBlock
    $title.TextWrapping = 'Wrap'; $title.FontSize = 16; $title.FontWeight = 'Bold'; $title.Foreground = New-AMRGlassBrush '#FFF1F5F9'
    $title.Text = [string](Get-AMRDiagProp $Item 'DeviceName' 'Unknown device')
    $titleBox.Children.Add($title) | Out-Null
    $chips = New-Object System.Windows.Controls.WrapPanel; $chips.Margin = New-Object System.Windows.Thickness(0,6,0,0)
    $chipTexts = New-Object System.Collections.ArrayList
    $family = [string](Get-AMRDiagProp $Item 'Family' ''); if ($family) { [void]$chipTexts.Add($family) }
    $codeValue = 0; try { $codeValue = [int](Get-AMRDiagProp $Item 'ProblemCode' 0) } catch {}
    if ($codeValue -ne 0) { [void]$chipTexts.Add(('Code {0}  ·  {1}' -f $codeValue,[string](Get-AMRDiagProp $Item 'CodeName' ''))) }
    if ($confidence) { [void]$chipTexts.Add(('Confidence: ' + $confidence)) }
    foreach ($chipText in $chipTexts) {
        $chip = New-Object System.Windows.Controls.Border
        $chip.CornerRadius = New-Object System.Windows.CornerRadius(9); $chip.Padding = New-Object System.Windows.Thickness(10,3,10,3); $chip.Margin = New-Object System.Windows.Thickness(0,0,8,4)
        $chip.Background = New-AMRGlassBrush '#1FFFFFFF'; $chip.BorderThickness = New-Object System.Windows.Thickness(1); $chip.BorderBrush = New-AMRGlassBrush '#33FFFFFF'
        $chipLabel = New-Object System.Windows.Controls.TextBlock; $chipLabel.Text = $chipText; $chipLabel.FontSize = 11; $chipLabel.FontWeight = 'SemiBold'; $chipLabel.Foreground = New-AMRGlassBrush '#FFE2E8F0'
        $chip.Child = $chipLabel
        $chips.Children.Add($chip) | Out-Null
    }
    $titleBox.Children.Add($chips) | Out-Null
    $head.Children.Add($icon) | Out-Null; $head.Children.Add($titleBox) | Out-Null
    # A2: header row = original header (col 0) + gold "open in Driver Update" button (col 1). Falls back to the original header on any failure.
    $headHost = $head
    try {
        $gotoDeviceId = [string](Get-AMRDiagProp $Item 'DeviceId' ''); $gotoDeviceName = [string](Get-AMRDiagProp $Item 'DeviceName' '')
        if (-not [string]::IsNullOrWhiteSpace($gotoDeviceId) -or -not [string]::IsNullOrWhiteSpace($gotoDeviceName)) {
            $gotoButton = New-AMRProblemGotoButton -DeviceId $gotoDeviceId -DeviceName $gotoDeviceName
            $gotoGrid = New-Object System.Windows.Controls.Grid
            $gotoCol0 = New-Object System.Windows.Controls.ColumnDefinition; $gotoCol0.Width = New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)
            $gotoCol1 = New-Object System.Windows.Controls.ColumnDefinition; $gotoCol1.Width = [System.Windows.GridLength]::Auto
            $gotoGrid.ColumnDefinitions.Add($gotoCol0); $gotoGrid.ColumnDefinitions.Add($gotoCol1)
            [System.Windows.Controls.Grid]::SetColumn($head,0); [System.Windows.Controls.Grid]::SetColumn($gotoButton,1)
            $gotoGrid.Children.Add($head) | Out-Null; $gotoGrid.Children.Add($gotoButton) | Out-Null
            $headHost = $gotoGrid
        }
    } catch {
        $headHost = $head
        try { if ($head.Parent) { $head.Parent.Children.Remove($head) } } catch {}
        try { Write-AMRDriverDiagnostic -Severity WARNING -Operation ProblemGoto -Stage ButtonFallback -Message ('Problem card button could not be built: ' + $_.Exception.Message) -Source 'Add-AMRDriverDiagCard' } catch {}
    }
    $stack.Children.Add($headHost) | Out-Null

    # What Windows reports
    $assessLabel = New-Object System.Windows.Controls.TextBlock; $assessLabel.Text = 'WHAT WE FOUND'; $assessLabel.FontSize = 10; $assessLabel.FontWeight = 'Bold'
    $assessLabel.Foreground = New-AMRGlassBrush '#FFD8B56D'; $assessLabel.Margin = New-Object System.Windows.Thickness(0,14,0,4)
    $assess = New-Object System.Windows.Controls.TextBlock
    $assess.TextWrapping = 'Wrap'; $assess.FontSize = 13; $assess.LineHeight = 19; $assess.Foreground = New-AMRGlassBrush '#FFCBD5E1'; $assess.Text = [string](Get-AMRDiagProp $Item 'Assessment' '')
    $stack.Children.Add($assessLabel) | Out-Null; $stack.Children.Add($assess) | Out-Null

    # Suggested action block
    $sugBox = New-Object System.Windows.Controls.Border
    $sugBox.CornerRadius = New-Object System.Windows.CornerRadius(10); $sugBox.Padding = New-Object System.Windows.Thickness(14,11,14,11); $sugBox.Margin = New-Object System.Windows.Thickness(0,14,0,0)
    $sugBox.Background = New-AMRGlassBrush '#40000000'; $sugBox.BorderThickness = New-Object System.Windows.Thickness(1); $sugBox.BorderBrush = New-AMRGlassBrush '#55D8B56D'
    $sugStack = New-Object System.Windows.Controls.StackPanel
    $sugLabel = New-Object System.Windows.Controls.TextBlock; $sugLabel.Text = 'SUGGESTED FIX'; $sugLabel.FontSize = 10; $sugLabel.FontWeight = 'Bold'; $sugLabel.Foreground = New-AMRGlassBrush '#FFD8B56D'
    $suggest = New-Object System.Windows.Controls.TextBlock
    $suggest.TextWrapping = 'Wrap'; $suggest.FontSize = 13; $suggest.LineHeight = 19; $suggest.Foreground = New-AMRGlassBrush '#FFF1F5F9'; $suggest.Margin = New-Object System.Windows.Thickness(0,4,0,0)
    $suggest.Text = [string](Get-AMRDiagProp $Item 'SuggestedAction' '')
    $sugStack.Children.Add($sugLabel) | Out-Null; $sugStack.Children.Add($suggest) | Out-Null
    $sugBox.Child = $sugStack
    $stack.Children.Add($sugBox) | Out-Null

    # Details (evidence, against, unknown, parent): unchanged content
    $detailLines = New-Object System.Collections.ArrayList
    foreach ($line in @(Get-AMRDiagProp $Item 'Evidence' @())) { [void]$detailLines.Add('Evidence: ' + [string]$line) }
    foreach ($line in @(Get-AMRDiagProp $Item 'Against' @())) { [void]$detailLines.Add('Against: ' + [string]$line) }
    foreach ($line in @(Get-AMRDiagProp $Item 'Unknown' @())) { [void]$detailLines.Add('Not known: ' + [string]$line) }
    $parentText = [string](Get-AMRDiagProp $Item 'Parent' ''); if ($parentText) { [void]$detailLines.Add('Parent: ' + $parentText) }
    if ($detailLines.Count -gt 0) {
        $expander = New-Object System.Windows.Controls.Expander
        $expander.Header = 'Details'; $expander.Foreground = New-AMRGlassBrush '#FF94A3B8'; $expander.FontSize = 12; $expander.FontWeight = 'SemiBold'; $expander.Margin = New-Object System.Windows.Thickness(0,12,0,0)
        $detailText = New-Object System.Windows.Controls.TextBlock
        $detailText.TextWrapping = 'Wrap'; $detailText.FontSize = 11; $detailText.LineHeight = 17; $detailText.Foreground = New-AMRGlassBrush '#FF94A3B8'; $detailText.Margin = New-Object System.Windows.Thickness(16,6,0,0)
        $detailText.Text = ($detailLines -join "`n")
        $expander.Content = $detailText
        $stack.Children.Add($expander) | Out-Null
    }
    $grid.Children.Add($stack) | Out-Null
    $card.Child = $grid

    # Light hover: edge brush swap only (no animation, no effects). Cards appear with the Problems pane fade.
    $card.Add_MouseEnter({ try { $this.BorderBrush = $accentBrush } catch {} }.GetNewClosure())
    $card.Add_MouseLeave({ try { $this.BorderBrush = $baseEdge } catch {} }.GetNewClosure())
    $Panel.Children.Add($card) | Out-Null
}

function Add-AMRDriverDiagCardBatch {
    $panel = C 'DriverDiagCards'
    $more = C 'DriverDiagShowMoreBtn'
    if (-not $panel -or -not $script:DriverDiagLast) { return }
    $problems = @($script:DriverDiagLast.Items | Where-Object { $_.Tier -eq 1 })
    $start = [int]$script:DriverDiagCardsShown
    $end = [math]::Min($problems.Count, $start + 10)
    for ($i = $start; $i -lt $end; $i++) { Add-AMRDriverDiagCard -Item $problems[$i] -Panel $panel }
    $script:DriverDiagCardsShown = $end
    if ($more) {
        if ($end -lt $problems.Count) { $more.Visibility = 'Visible'; $more.Content = ('Show 10 more ({0} remaining)' -f ($problems.Count - $end)) } else { $more.Visibility = 'Collapsed' }
    }
}

# ----- A13e: two glass tabs above the driver list: "Driver Update" and "Problems". Pure visual switch. -----
# Switch cost rules: no card or list rebuild, no opacity animation over the device list (its template has shadow
# effects, so animating it forces a re-render every frame). Only the small tab pill slides, and the Problems pane
# (flat cards, no effects) fades in.
$script:DriverTabCurrent = 'Update'
function Set-AMRDriverTabStyle {
    param([string]$Tab,[bool]$Animate = $true)
    $upd = C 'DriverTabUpdateBtn'; $prob = C 'DriverTabProblemsBtn'; $pill = C 'DriverTabPill'
    if ($upd) { $upd.Tag = $(if ($Tab -eq 'Update') { 'Active' } else { '' }) }
    if ($prob) { $prob.Tag = $(if ($Tab -eq 'Problems') { 'Active' } else { '' }) }
    if ($pill -and $pill.RenderTransform -is [System.Windows.Media.TranslateTransform]) {
        $target = $(if ($Tab -eq 'Problems') { 168.0 } else { 0.0 })
        if ($Animate) {
            $ease = New-Object System.Windows.Media.Animation.CubicEase; $ease.EasingMode = 'EaseOut'
            $slide = New-Object System.Windows.Media.Animation.DoubleAnimation
            $slide.To = $target; $slide.Duration = [TimeSpan]::FromMilliseconds(220); $slide.EasingFunction = $ease
            $pill.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$slide)
        } else {
            $pill.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$null)
            $pill.RenderTransform.X = $target
        }
    }
}

function Set-AMRDriverTab {
    param([ValidateSet('Update','Problems')][string]$Tab)
    $updatePane = C 'DriverUpdatePane'; $problemsPane = C 'DriverProblemsPane'
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        if (-not $updatePane -or -not $problemsPane) { return }
        if ($script:DriverTabCurrent -eq $Tab) { return }
        $script:DriverTabCurrent = $Tab
        if ($Tab -eq 'Update') {
            $problemsPane.Visibility = 'Collapsed'
            $updatePane.Visibility = 'Visible'
        } else {
            $updatePane.Visibility = 'Collapsed'
            $problemsPane.Visibility = 'Visible'
            try {
                $ease = New-Object System.Windows.Media.Animation.CubicEase; $ease.EasingMode = 'EaseOut'
                $fade = New-Object System.Windows.Media.Animation.DoubleAnimation
                $fade.From = 0.0; $fade.To = 1.0; $fade.Duration = [TimeSpan]::FromMilliseconds(190); $fade.EasingFunction = $ease
                $problemsPane.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade)
            } catch { try { $problemsPane.Opacity = 1.0 } catch {} }
        }
        try { Set-AMRDriverTabStyle -Tab $Tab } catch { try { Set-AMRDriverTabStyle -Tab $Tab -Animate $false } catch {} }
        # Real cost of the switch: time until WPF finished layout and the next render pass.
        $switchWatch = $watch
        try { $script:Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Render,[Action]{
            try { $switchWatch.Stop(); Write-AMRDriverDiagnostic -Severity $(if ($switchWatch.ElapsedMilliseconds -ge 120) { 'WARNING' } else { 'TRACE' }) -Operation DriverTabs -Stage SwitchTiming -Message ('Driver tab switch to {0} reached render in {1} ms.' -f $Tab,$switchWatch.ElapsedMilliseconds) -Source 'Set-AMRDriverTab' -DurationMs ([long]$switchWatch.ElapsedMilliseconds) } catch {}
        }.GetNewClosure()) | Out-Null } catch {}
    } catch {
        try {
            if ($updatePane) { $updatePane.Visibility = $(if ($Tab -eq 'Update') { 'Visible' } else { 'Collapsed' }) }
            if ($problemsPane) { $problemsPane.Visibility = $(if ($Tab -eq 'Problems') { 'Visible' } else { 'Collapsed' }); $problemsPane.Opacity = 1.0 }
            Set-AMRDriverTabStyle -Tab $Tab -Animate $false
        } catch {}
        try { Write-AMRDriverDiagnostic -Severity WARNING -Operation DriverTabs -Stage SwitchFallback -Message ('Driver tab switch used the plain fallback: ' + $_.Exception.Message) -Source 'Set-AMRDriverTab' } catch {}
    }
}

function Set-AMRDriverProblemsTabLabel {
    param([int]$Count = -1)
    try {
        $btn = C 'DriverTabProblemsBtn'; if (-not $btn) { return }
        $btn.Content = $(if ($Count -gt 0) { ('Problems  ·  {0}' -f $Count) } else { 'Problems' })
    } catch {}
}

function Clear-AMRDriverDiagView {
    try {
        $script:DriverDiagLast = $null; $script:DriverDiagSnapshot = $null; $script:DriverDiagCardsShown = 0; $script:DriverRepairCandidates = @()
        $panel = C 'DriverDiagPanel'; $cards = C 'DriverDiagCards'
        if ($cards) { $cards.Children.Clear() }
        if ($panel) { $panel.Visibility = 'Collapsed' }
        $repair = C 'DriverRepairBtn'; if ($repair) { $repair.Visibility = 'Collapsed' }
        $empty = C 'DriverProblemsEmpty'; if ($empty) { $empty.Visibility = 'Visible' }
        Set-AMRDriverProblemsTabLabel -Count 0
    } catch {}
}

function Set-AMRDriverDiagBadge {
    param([string]$Text,[string]$Color = '#7DD3FC',[string]$Summary = '')
    $panel = C 'DriverDiagPanel'; $badge = C 'DriverDiagBadge'; $summaryText = C 'DriverDiagSummary'
    if ($panel) { $panel.Visibility = 'Visible' }
    try { $empty = C 'DriverProblemsEmpty'; if ($empty) { $empty.Visibility = 'Collapsed' } } catch {}
    if ($badge) { $badge.Text = $Text; $badge.Foreground = New-AMRGlassBrush $Color }
    if ($summaryText) { $summaryText.Text = $Summary; $summaryText.Visibility = $(if ($Summary) { 'Visible' } else { 'Collapsed' }) }
}

function Show-AMRDriverDiagResult {
    param($Diagnosis)
    $counts = $Diagnosis.Counts
    $cards = C 'DriverDiagCards'
    if ($cards) { $cards.Children.Clear() }
    $script:DriverDiagCardsShown = 0
    $summary = ('{0} device(s) read. Problems: {1}. Update only: {2}. Light check: {3}. Healthy: {4}. Nothing was changed.' -f $counts.TotalDevices,$counts.Problem,$counts.UpdateOnly,$counts.LightCheck,$counts.Healthy)
    if ([int]$counts.Problem -gt 0) { Set-AMRDriverDiagBadge -Text ([string][char]0x26A0 + (' {0} problem device(s) found' -f $counts.Problem)) -Color '#FBBF24' -Summary $summary }
    else { Set-AMRDriverDiagBadge -Text ([string][char]0x2713 + ' No device problems found') -Color '#86EFAC' -Summary $summary }
    Add-AMRDriverDiagCardBatch
    try { Set-AMRDriverProblemsTabLabel -Count ([int]$counts.Problem) } catch {}
}

# ----- Importance rule + Code 22 repair (the only device change in A12). -----
function Get-AMRDriverRepairCandidates {
    param($Diagnosis,$Snapshot)
    $result = New-Object System.Collections.ArrayList
    if (-not $Diagnosis -or -not $Snapshot) { return @() }
    $devices = @(Get-AMRDiagProp $Snapshot 'Devices' @())
    foreach ($item in @($Diagnosis.Items | Where-Object { $_.Tier -eq 1 -and [int]$_.ProblemCode -eq 22 })) {
        # Essential family only (weight >= 80: network, storage, audio, display, input, biometric).
        if ([int]$item.SortWeight -lt 80) { continue }
        # No working peer in the same family means the function is actually missing.
        $peers = @($devices | Where-Object {
            $peerId = [string](Get-AMRDiagProp $_ 'InstanceId' '')
            $peerCode = 0; try { $peerCode = [int](Get-AMRDiagProp $_ 'ProblemCode' 0) } catch {}
            ($peerId -ne [string]$item.DeviceId) -and $peerCode -eq 0 -and [string](Get-AMRDiagProp $_ 'Status' '') -eq 'OK' -and
            ((Get-AMRDeviceFamily -Class ([string](Get-AMRDiagProp $_ 'Class' '')) -Name ([string](Get-AMRDiagProp $_ 'Name' ''))) -eq [string]$item.Family)
        })
        if ($peers.Count -gt 0) { continue }
        # Parent must be read and healthy.
        if ([string]::IsNullOrWhiteSpace([string]$item.Parent) -or [string]$item.Parent -match 'problem code|not in the present') { continue }
        [void]$result.Add($item)
    }
    return @($result)
}

function New-AMRRepairToneStream {
    $rate = 22050; $samples = [int]($rate * 0.35)
    $stream = New-Object System.IO.MemoryStream
    $writer = New-Object System.IO.BinaryWriter($stream)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes('RIFF')); $writer.Write([int](36 + $samples * 2)); $writer.Write([System.Text.Encoding]::ASCII.GetBytes('WAVEfmt '))
    $writer.Write([int]16); $writer.Write([int16]1); $writer.Write([int16]1); $writer.Write([int]$rate); $writer.Write([int]($rate * 2)); $writer.Write([int16]2); $writer.Write([int16]16)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes('data')); $writer.Write([int]($samples * 2))
    for ($i = 0; $i -lt $samples; $i++) {
        $envelope = [math]::Min(1.0, [math]::Min($i / 800.0, ($samples - $i) / 800.0))
        $writer.Write([int16]([math]::Round(0.04 * 32767 * $envelope * [math]::Sin(2 * [math]::PI * 440 * $i / $rate))))
    }
    $writer.Flush(); $stream.Position = 0
    return $stream
}

# Runs in a background job. Mode 'Repair' enables the device; mode 'Undo' disables it again. Returns step records.
function Invoke-AMRDriverRepairWork {
    param([string[]]$InstanceIds,[string]$Mode = 'Repair')
    $out = New-Object System.Collections.ArrayList
    $anyChange = $false
    foreach ($id in $InstanceIds) {
        $steps = New-Object System.Collections.ArrayList
        $rec = [ordered]@{ InstanceId=$id; Name=''; BeforeCode=-1; BeforeStatus=''; AfterCode=-1; AfterStatus=''; Outcome='NotRun'; Verification=''; Error=''; Steps=$steps; Class='' }
        try {
            $dev = Get-PnpDevice -InstanceId $id -ErrorAction Stop
            $rec.Name = [string]$dev.FriendlyName; if (-not $rec.Name) { $rec.Name = [string]$dev.Name }
            $rec.Class = [string]$dev.Class
            $rec.BeforeStatus = [string]$dev.Status
            $code = 0; try { $code = [int]$dev.ConfigManagerErrorCode } catch {}
            $rec.BeforeCode = $code
            [void]$steps.Add(('Before: status {0}, problem code {1}.' -f $rec.BeforeStatus,$code))
            if ($Mode -eq 'Undo') {
                if ($code -eq 22) { $rec.Outcome = 'Skipped'; [void]$steps.Add('Already disabled; nothing to undo.') }
                else {
                    Disable-PnpDevice -InstanceId $id -Confirm:$false -ErrorAction Stop
                    $anyChange = $true
                    Start-Sleep -Seconds 1
                    $after = Get-PnpDevice -InstanceId $id -ErrorAction Stop
                    $rec.AfterStatus = [string]$after.Status; try { $rec.AfterCode = [int]$after.ConfigManagerErrorCode } catch {}
                    $rec.Outcome = $(if ($rec.AfterCode -eq 22) { 'Undone' } else { 'UndoNotConfirmed' })
                    [void]$steps.Add(('Disabled again. After: status {0}, problem code {1}.' -f $rec.AfterStatus,$rec.AfterCode))
                }
            } else {
                if ($code -ne 22) { $rec.Outcome = 'Skipped'; [void]$steps.Add('State changed since the diagnosis (problem code is not 22); nothing was changed.') }
                else {
                    Enable-PnpDevice -InstanceId $id -Confirm:$false -ErrorAction Stop
                    $anyChange = $true
                    [void]$steps.Add('Enable-PnpDevice finished without an error.')
                    Start-Sleep -Seconds 2
                    $after = Get-PnpDevice -InstanceId $id -ErrorAction Stop
                    $rec.AfterStatus = [string]$after.Status; try { $rec.AfterCode = [int]$after.ConfigManagerErrorCode } catch {}
                    [void]$steps.Add(('After: status {0}, problem code {1}.' -f $rec.AfterStatus,$rec.AfterCode))
                    if ($rec.AfterCode -eq 0 -and $rec.AfterStatus -eq 'OK') {
                        $rec.Outcome = 'Enabled'; $rec.Verification = 'Verified: Windows reports the device as working (problem code 0).'
                        $isAudio = ($rec.Class -match '^(?i)(MEDIA|SoftwareComponent|System|Extension|AudioEndpoint)$' -and $rec.Name -match '(?i)audio|sound|codec|\bSST\b')
                        if ($isAudio) {
                            $endpoints = 0
                            for ($try = 0; $try -lt 3; $try++) {
                                $endpoints = @(Get-PnpDevice -Class AudioEndpoint -PresentOnly -ErrorAction SilentlyContinue | Where-Object { [string]$_.Status -eq 'OK' }).Count
                                if ($endpoints -gt 0) { break }
                                Start-Sleep -Seconds 2
                            }
                            [void]$steps.Add(('Working audio endpoints: {0}.' -f $endpoints))
                            if ($endpoints -gt 0) {
                                try {
                                    $tone = New-AMRRepairToneStream
                                    $player = New-Object System.Media.SoundPlayer($tone)
                                    $player.PlaySync()
                                    [void]$steps.Add('A short low-volume test tone played without an error. The system volume was not changed. Whether it was audible is not measured (no peak meter).')
                                    $rec.Verification = 'Partial verification: device works (code 0) and endpoints exist; tone played without error, audibility not measured.'
                                } catch {
                                    [void]$steps.Add('The test tone could not be played: ' + $_.Exception.Message)
                                    $rec.Verification = 'Partial verification: device works (code 0); the tone test could not run.'
                                }
                            } else { $rec.Verification = 'Partial verification: device works (code 0), but no working audio endpoint appeared within 6 seconds.' }
                        }
                    } else { $rec.Outcome = 'NotWorking'; $rec.Verification = 'Not verified: the device still reports a problem after enabling.' }
                }
            }
        } catch {
            $rec.Outcome = 'Failed'; $rec.Error = $_.Exception.Message
            [void]$steps.Add('Failed: ' + $_.Exception.Message)
        }
        [void]$out.Add([pscustomobject]$rec)
    }
    $rescan = ''
    if ($anyChange) {
        try { $null = & pnputil.exe /scan-devices 2>&1; $rescan = 'Device rescan requested (pnputil /scan-devices).' } catch { $rescan = 'Device rescan failed: ' + $_.Exception.Message }
    }
    return [pscustomobject]@{ Records=@($out); Rescan=$rescan; Mode=$Mode }
}


function Update-AMRDriverRepairButtons {
    try {
        $repair = C 'DriverRepairBtn'; $undo = C 'DriverRepairUndoBtn'
        $busy = [bool]($script:DriverScanJob -or $script:DriverActionJob -or $script:DriverManagedJob -or $script:DriverDiagJob -or $script:DriverRepairJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive)
        $count = @($script:DriverRepairCandidates).Count
        if ($repair) {
            $repair.Visibility = $(if ($count -gt 0) { 'Visible' } else { 'Collapsed' })
            $repair.IsEnabled = ($count -gt 0 -and -not $busy)
            $repair.Content = ('Repair essential device ({0})' -f $count)
        }
        if ($undo) {
            $undo.Visibility = $(if (@($script:DriverRepairUndoIds).Count -gt 0) { 'Visible' } else { 'Collapsed' })
            $undo.IsEnabled = (-not $busy)
        }
    } catch {}
}

function Start-AMRDriverRepairJob {
    param([string]$Mode)
    if ($script:DriverRepairJob) { return }
    $ids = @()
    if ($Mode -eq 'Undo') { $ids = @($script:DriverRepairUndoIds) } else { $ids = @($script:DriverRepairCandidates | Select-Object -First 3 | ForEach-Object { [string]$_.DeviceId }) }
    if ($ids.Count -eq 0) { return }
    if ($script:DriverScanJob -or $script:DriverActionJob -or $script:DriverManagedJob -or $script:DriverDiagJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive) {
        Show-AMRGlassDialog -Message 'Wait for the active Driver Center operation to finish first.' -Title 'AMR | Driver Center' | Out-Null
        return
    }
    if (-not (Test-AMRAdmin)) {
        Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceRepair -Stage Unavailable -Message 'Repair is unavailable: Administrator rights are required to enable a device. Nothing was changed.' -Source 'AMRDriverRepair' -Result 'NotAdmin'
        Show-AMRGlassDialog -Message "Repair needs Administrator rights to enable a device.`n`nClose the utility and start it again as Administrator. Nothing was changed." -Title 'AMR | Administrator required' -Icon Warning | Out-Null
        return
    }
    try {
        $script:DriverRepairMode = $Mode
        $script:DriverRepairStartedAt = Get-Date
        foreach ($id in $ids) { Write-AMRDriverDiagnostic -Severity INFO -Operation DeviceRepair -Stage Started -Message ('{0} started for a device (InstanceId in DeviceId; undo = disable the same InstanceId).' -f $Mode) -DeviceId $id -Source 'AMRDriverRepair' }
        $statusText = C 'DriverActionStatus'
        if ($statusText) { $statusText.Text = $(if ($Mode -eq 'Undo') { 'Undoing the repair in the background...' } else { 'Repairing the essential device in the background and verifying it...' }) }
        $workDefinition = [string](Get-Command -Name Invoke-AMRDriverRepairWork -CommandType Function -ErrorAction Stop).Definition
        $toneDefinition = [string](Get-Command -Name New-AMRRepairToneStream -CommandType Function -ErrorAction Stop).Definition
        $script:DriverRepairJob = Start-Job -ArgumentList $workDefinition,$toneDefinition,$ids,$Mode -ScriptBlock {
            param($WorkDef,$ToneDef,$Ids,$RunMode)
            Set-Item -Path 'Function:\New-AMRRepairToneStream' -Value ([scriptblock]::Create([string]$ToneDef)) -Force
            Set-Item -Path 'Function:\Invoke-AMRDriverRepairWork' -Value ([scriptblock]::Create([string]$WorkDef)) -Force
            Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
            Invoke-AMRDriverRepairWork -InstanceIds $Ids -Mode $RunMode
        }
        Update-AMRDriverRepairButtons
        $diagButton = C 'DriverDiagnosisBtn'; if ($diagButton) { $diagButton.IsEnabled = $false }
        if (-not $script:DriverRepairTimer) {
            $script:DriverRepairTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:DriverRepairTimer.Interval = [TimeSpan]::FromMilliseconds(500)
            $script:DriverRepairTimer.Add_Tick({
                try {
                    $job = $script:DriverRepairJob
                    $finish = $false; $payload = $null; $failure = ''
                    if (-not $job) { $finish = $true; $failure = 'The repair job reference was lost.' }
                    elseif ($job.State -eq 'Running' -or $job.State -eq 'NotStarted') {
                        if (((Get-Date) - [datetime]$script:DriverRepairStartedAt).TotalSeconds -gt 150) { try { Stop-Job -Job $job -ErrorAction SilentlyContinue } catch {}; $finish = $true; $failure = 'The repair exceeded its 150-second limit and was stopped.' }
                    } else {
                        $finish = $true
                        if ($job.State -eq 'Completed') {
                            $received = @(Receive-Job -Job $job -ErrorAction SilentlyContinue)
                            $withRecords = @($received | Where-Object { $_ -and $_.PSObject.Properties['Records'] } | Select-Object -Last 1)
                            if ($withRecords.Count -gt 0) { $payload = $withRecords[0] } else { $failure = 'The repair job returned no data.' }
                        } else { $failure = ('The repair job ended as {0}.' -f [string]$job.State) }
                    }
                    if (-not $finish) { return }
                    $script:DriverRepairTimer.Stop()
                    if ($job) { try { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {} }
                    $script:DriverRepairJob = $null
                    Complete-AMRDriverRepair -Payload $payload -Failure $failure
                } catch {
                    try { $script:DriverRepairTimer.Stop() } catch {}
                    $script:DriverRepairJob = $null
                    Write-AMRDriverDiagnostic -Severity ERROR -Operation DeviceRepair -Stage Failed -Message 'The repair polling step failed.' -Source 'AMRDriverRepair' -ErrorRecord $_
                    try { Update-AMRDriverActionButtons } catch {}
                }
            })
        }
        $script:DriverRepairTimer.Start()
    } catch {
        $script:DriverRepairJob = $null
        Write-AMRDriverDiagnostic -Severity ERROR -Operation DeviceRepair -Stage Failed -Message 'The repair could not be started.' -Source 'AMRDriverRepair' -ErrorRecord $_
        Show-AMRGlassDialog -Message ('The repair could not be started: ' + $_.Exception.Message + "`n`nNothing was changed.") -Title 'AMR | Driver repair' -Icon Warning | Out-Null
        try { Update-AMRDriverActionButtons } catch {}
    }
}

function Complete-AMRDriverRepair {
    param($Payload,[string]$Failure = '')
    $mode = [string]$script:DriverRepairMode
    try {
        if ($Failure -or $null -eq $Payload) {
            Write-AMRDriverDiagnostic -Severity WARNING -Operation DeviceRepair -Stage Failed -Message ('Repair did not complete: ' + $Failure + ' The device state is unknown; run Diagnose again.') -Source 'AMRDriverRepair' -Result 'Failed'
            $statusText = C 'DriverActionStatus'; if ($statusText) { $statusText.Text = 'The repair did not complete. Run Diagnose again to see the current state.' }
            Show-AMRGlassDialog -Message ("The repair did not complete: $Failure`n`nThe device state is unknown. Run Diagnose again to see the current state. Undo remains available if the device was enabled.") -Title 'AMR | Driver repair' -Icon Warning | Out-Null
            return
        }
        $lines = New-Object System.Collections.ArrayList
        $oneLine = New-Object System.Collections.ArrayList
        $newUndo = New-Object System.Collections.ArrayList
        foreach ($rec in @($Payload.Records)) {
            $sev = 'INFO'; if ($rec.Outcome -eq 'Enabled' -or $rec.Outcome -eq 'Undone') { $sev = 'SUCCESS' } elseif ($rec.Outcome -in @('Failed','NotWorking','UndoNotConfirmed')) { $sev = 'WARNING' }
            Write-AMRDriverDiagnostic -Severity $sev -Operation DeviceRepair -Stage $rec.Outcome -Message ('{0}: {1} {2}' -f $mode,$rec.Name,($rec.Steps -join ' | ')) -DeviceId ([string]$rec.InstanceId) -Source 'AMRDriverRepair' -Result ([string]$rec.Outcome) -Context @{BeforeCode=$rec.BeforeCode;AfterCode=$rec.AfterCode;Verification=$rec.Verification;Error=$rec.Error}
            [void]$lines.Add([string]$rec.Name)
            foreach ($s in @($rec.Steps)) { [void]$lines.Add('  - ' + [string]$s) }
            if ($rec.Verification) { [void]$lines.Add('  Result: ' + [string]$rec.Verification) }
            [void]$lines.Add('')
            switch ([string]$rec.Outcome) {
                'Enabled' { [void]$oneLine.Add(('{0}: enabled. {1}' -f $rec.Name,$rec.Verification)); [void]$newUndo.Add([string]$rec.InstanceId) }
                'NotWorking' { [void]$oneLine.Add(('{0}: enabled but still reports a problem.' -f $rec.Name)); [void]$newUndo.Add([string]$rec.InstanceId) }
                'Undone' { [void]$oneLine.Add(('{0}: disabled again (undo done).' -f $rec.Name)) }
                'Skipped' { [void]$oneLine.Add(('{0}: skipped, state changed.' -f $rec.Name)) }
                default { [void]$oneLine.Add(('{0}: {1}.' -f $rec.Name,$rec.Outcome)) }
            }
        }
        if ($mode -eq 'Undo') { $script:DriverRepairUndoIds = @() } else { $script:DriverRepairUndoIds = @($newUndo) }
        if ($Payload.Rescan) { Write-AMRDriverDiagnostic -Severity INFO -Operation DeviceRepair -Stage Rescan -Message ([string]$Payload.Rescan) -Source 'AMRDriverRepair' }
        $statusText = C 'DriverActionStatus'
        if ($statusText) { $statusText.Text = ($oneLine -join ' ') }
        if ([string]$script:DriverExperienceMode -eq 'Advanced') {
            [void]$lines.Add([string]$Payload.Rescan)
            [void]$lines.Add('Undo: the Undo repair button disables the same device again (available in this session).')
            Show-AMRGlassDialog -Message (($lines -join "`n").Trim()) -Title 'AMR | Driver repair steps' | Out-Null
        }
        $script:DriverRepairCandidates = @()
    } catch {
        Write-AMRDriverDiagnostic -Severity ERROR -Operation DeviceRepair -Stage Failed -Message 'Repair result processing failed.' -Source 'AMRDriverRepair' -ErrorRecord $_
    } finally {
        try { Update-AMRDriverActionButtons } catch {}
        try { Update-AMRDriverRepairButtons } catch {}
        # Re-diagnose automatically after a repair (rescan is part of repair).
        try { $script:Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle,[Action]{ Start-AMRDriverAutoDiagnosis }) | Out-Null } catch {}
    }
}

function Start-AMRDriverAutoDiagnosis {
    if ($script:DriverDiagJob -or $script:DriverScanJob -or $script:DriverActionJob -or $script:DriverManagedJob -or $script:DriverRepairJob -or $script:DriverBatchActive -or $script:DriverSmartQueueActive) { return }
    if (@($script:DriverAllDeviceRows).Count -eq 0) { return }
    try { Show-AMRDriverSystemDiagnosis -Auto } catch {
        Write-AMRDriverDiagnostic -Severity WARNING -Operation SystemDiagnosis -Stage Failed -Message ('Automatic diagnosis could not start: ' + $_.Exception.Message) -Source 'AMRDriverSystemDiagnosis'
    }
}

# ----- Restore-point prompt on opening Driver Center (once per session, skipped when a recorded point is under 24 h old). -----
function Get-AMRDriverRecentRestoreReceiptAgeHours {
    try {
        $path = [string]$script:DriverRestorePointStateFile
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { return $null }
        $state = Get-Content -LiteralPath $path -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        $created = [datetime]$state.CreationTime
        return [double]((Get-Date) - $created).TotalHours
    } catch { return $null }
}

function Invoke-AMRDriverRestorePrompt {
    if ($script:DriverRestorePromptShown) { return }
    $script:DriverRestorePromptShown = $true
    try {
        $age = Get-AMRDriverRecentRestoreReceiptAgeHours
        if ($null -ne $age -and $age -lt 24) {
            Write-AMRDriverDiagnostic -Severity INFO -Operation RestorePrompt -Stage Skipped -Message ('Restore-point prompt skipped: the recorded Driver Safety Point is {0:N1} hours old (under 24 h).' -f $age) -Source 'AMRRestorePrompt'
            return
        }
        if (-not (Test-AMRAdmin)) {
            Write-AMRDriverDiagnostic -Severity INFO -Operation RestorePrompt -Stage Skipped -Message 'Restore-point prompt skipped: Administrator rights are required to create one.' -Source 'AMRRestorePrompt'
            return
        }
        $answer = Show-AMRGlassDialog -Message "Driver Center can change drivers. Create a Windows System Restore point first so you can go back if needed?`n`nA point is created only if you choose Yes. Nothing is installed or changed by this step." -Title 'AMR | Create a restore point?' -Buttons YesNo -Icon Warning
        Write-AMRDriverDiagnostic -Severity INFO -Operation RestorePrompt -Stage Answered -Message ('Restore-point prompt answered: ' + $answer) -Source 'AMRRestorePrompt' -Result $answer
        if ($answer -eq 'Yes') {
            $script:DriverRestorePromptApproved = $true
            $button = C 'DriverCreateRestorePointBtn'
            if ($button -and $button.IsEnabled) { $button.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent))) }
            $script:DriverRestorePromptApproved = $false
        }
    } catch {
        $script:DriverRestorePromptApproved = $false
        Write-AMRDriverDiagnostic -Severity WARNING -Operation RestorePrompt -Stage Failed -Message ('Restore-point prompt failed: ' + $_.Exception.Message) -Source 'AMRRestorePrompt'
    }
}

(C 'OverviewSubTabs').Add_SelectionChanged({
    param($sender,$e)
    try {
        if ($e.OriginalSource -isnot [System.Windows.Controls.TabControl]) { return }
        if ($sender.SelectedItem -ne (C 'DriverCenterTab')) { return }
        if ($script:DriverRestorePromptShown) { return }
        $script:Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle,[Action]{ Invoke-AMRDriverRestorePrompt }) | Out-Null
    } catch {}
})

