                if ([bool]$installer.IsBusy) { throw 'Windows Update is already installing or removing an update. Wait for that operation to finish, then try again.' }
                $installer.Updates = $collection
                $installProgressStart = [pscustomobject]@{ Percent=5; Stage='Installing'; Updated=(Get-Date).ToString('o') }
                $installProgressStart | ConvertTo-Json -Compress | Set-Content -LiteralPath ($ProgressFile + '.tmp') -Encoding UTF8
                Move-Item -LiteralPath ($ProgressFile + '.tmp') -Destination $ProgressFile -Force
                $installStarted = Get-Date
                $installResult = $installer.Install()
                if ($null -eq $installResult) { throw 'Windows Update Install() returned no installation result object.' }
