            $workerSourceLine = ''
            try { $workerLine = [int]$workerError.InvocationInfo.ScriptLineNumber; $workerSourceLine = [string]$workerError.InvocationInfo.Line } catch {}
            $workerStack = [string]$workerError.ScriptStackTrace
            $workerExceptionText = ''
            try { $workerExceptionText = [string]$workerError.Exception.ToString() } catch {}
            [pscustomobject]@{
                Success=$false
                Action=[string]$RequestedAction
                Message=[string]$workerError.Exception.Message
                ErrorDetails=$workerExceptionText
                HResult=$workerHResult
                ErrorLine=$workerLine
                ErrorStage=[string]$workerStage
                ErrorSourceLine=$workerSourceLine
                ScriptStackTrace=$workerStack
                RebootRequired=$false
                ResultCode=-1
            }
        } finally {
            # Release WUA COM proxies deterministically in the worker process.
            $releasedComObjects = New-Object System.Collections.ArrayList
            foreach ($comCandidate in @($itemResult,$installResult,$installer,$downloadResult,$downloader,$collection,$target,$candidate,$verifyCandidate,$verifyResult,$verifySearcher,$searchResult,$searcher,$session)) {
                if ($null -eq $comCandidate) { continue }
                try {
                    if ([Runtime.InteropServices.Marshal]::IsComObject($comCandidate)) {
                        $alreadyReleased = $false
