                        }
                        if (-not $alreadyReleased) {
                            [void]$releasedComObjects.Add($comCandidate)
                            [void][Runtime.InteropServices.Marshal]::ReleaseComObject($comCandidate)
                        }
                    }
                } catch {}
            }
        }
    }
    $actionGeneration=[int]$script:DriverOperationState.Generation+1
    $script:DriverOperationState=[pscustomobject]@{Name=$(if($Action -eq 'Install'){'DriverInstall'}else{'DriverDownload'});State='Running';StartedAt=(Get-Date);Generation=$actionGeneration;ScanGeneration=[int]$script:DriverScanGeneration;CanCancel=$false;Status=$(if($Action -eq 'Install'){'Installing approved driver'}else{'Downloading and verifying driver package'})}

    if (-not $script:DriverActionTimer) {
        $script:DriverActionTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:DriverActionTimer.Interval = [TimeSpan]::FromMilliseconds(500)
        $script:DriverActionTimer.Add_Tick({
            $job = $script:DriverActionJob
            if (-not $job) {
                $script:DriverActionTimer.Stop()
                Release-AMRDriverOperationLock
                $lostActionType=[string]$script:DriverActionType
                $lostOperationId=[string]$script:DriverCurrentOperationId
                if ($script:DriverActionProgressFile) {
                    try { Remove-Item -LiteralPath $script:DriverActionProgressFile -Force -ErrorAction SilentlyContinue } catch {}
                    try { Remove-Item -LiteralPath ($script:DriverActionProgressFile + '.tmp') -Force -ErrorAction SilentlyContinue } catch {}
                    try { Remove-Item -LiteralPath ($script:DriverActionProgressFile + '.cancel') -Force -ErrorAction SilentlyContinue } catch {}
                }
                $script:DriverActionProgressFile=$null
                $script:DriverActionJob=$null
                $script:DriverActionCancelRequested=$false
                try { $finCancelButton=C 'DriverCancelManagedOperationBtn'; if($finCancelButton -and -not $script:DriverManagedJob){$finCancelButton.Visibility='Collapsed';$finCancelButton.IsEnabled=$false} } catch {}
                $script:DriverActionUpdateId=$null; $script:DriverActionUpdateRevision=0
                $script:DriverActionType=$null
                $script:DriverActionDeviceName=$null
                $script:DriverActionDeviceId=$null
                $script:DriverActionSource=$null
                $script:DriverActionUpdateTitle=$null
                $script:DriverActionVersion=$null
                $script:DriverCurrentOperationId=$null
                $script:DriverSmartQueueActive=$false; $script:DriverSmartDownloadQueue=@()
                $script:DriverBatchActive=$false; $script:DriverBatchQueue=@()
                if ($script:DriverOperationState.Name -in @('DriverDownload','DriverInstall')) {
                    $script:DriverOperationState=[pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready';PartialShown=$false}
                }
                try {
                    (C 'DriverOperationProgress').Visibility='Collapsed'
                    (C 'DriverOperationProgress').IsIndeterminate=$false
                    (C 'DriverOperationProgress').Value=0
                    (C 'DriverActionStatus').Text=('The {0} worker reference was lost. The operation state was reset; check Diagnostics and rescan before retrying.' -f $(if($lostActionType){$lostActionType}else{'driver'}))
                } catch {}
                Write-AMRDriverDiagnostic -Severity ERROR -Operation ('Driver'+$(if($lostActionType){$lostActionType}else{'Action'})) -Stage WorkerReferenceLost -Message 'The dispatcher timer found no active driver action job reference; UI state and operation lock were recovered.' -OperationId $lostOperationId -Source 'Phase1ActionRecovery' -Result 'Recovered'
                Update-AMRDriverActionButtons
                return
            }
            if ($script:DriverActionProgressFile -and (Test-Path -LiteralPath $script:DriverActionProgressFile -PathType Leaf)) {
                try {
                    $progressData = Get-Content -LiteralPath $script:DriverActionProgressFile -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                    $progressStage = [string]$progressData.Stage
                    if ($progressStage -and $progressStage -ne [string]$script:DriverActionLastLoggedStage) {
                        $script:DriverActionLastLoggedStage = $progressStage
                        $progressContext = @{Stage=$progressStage}
                        foreach ($progressPropertyName in @('Percent','BytesDownloaded','BytesTotal','SpeedBytesPerSecond','FileIndex','FileCount')) {
                            if ($progressData.PSObject.Properties[$progressPropertyName]) { $progressContext[$progressPropertyName] = $progressData.$progressPropertyName }
                        }
                        Write-AMRDriverDiagnostic -Severity TRACE -Operation ('Driver' + [string]$script:DriverActionType) -Stage $progressStage -Message 'Driver action worker reported a new progress stage.' -DeviceId ([string]$script:DriverActionDeviceId) -OperationId $script:DriverCurrentOperationId -Source 'DriverActionWorker' -Context $progressContext
                    }
                    try {
                        $actionCancelButton = C 'DriverCancelManagedOperationBtn'
                        if ($actionCancelButton -and [string]$script:DriverActionType -eq 'Download') {
                            $actionCancellable = (($progressStage -eq 'DirectDownload') -and -not $script:DriverActionCancelRequested)
                            $actionCancelButton.Visibility = $(if ($actionCancellable) { 'Visible' } else { 'Collapsed' })
                            $actionCancelButton.IsEnabled = [bool]$actionCancellable
                        }
                    } catch {}
                    $progressPercent = [int][Math]::Max(0,[Math]::Min(100,[double]$progressData.Percent))
                    $progressIndeterminate = ([string]$progressData.Stage -in @('WuaFallbackDownloadStarting','Installing'))
                    (C 'DriverOperationProgress').IsIndeterminate = [bool]$progressIndeterminate
                    (C 'DriverOperationProgress').Value = if ($progressIndeterminate) { [Math]::Max(5,$progressPercent) } else { $progressPercent }
                    if ($script:DriverActionType -eq 'Download') {
                        $doneMb = [Math]::Max(0,[double]$progressData.BytesDownloaded / 1MB)
                        $totalMb = [Math]::Max(0,[double]$progressData.BytesTotal / 1MB)
                        $speedMb = [Math]::Max(0,[double]$progressData.SpeedBytesPerSecond / 1MB)
                        if ([string]$progressData.Stage -eq 'DirectDownload') {
                            $fileIndex = [int]$progressData.FileIndex
                            $fileCount = [int]$progressData.FileCount
                            if ($totalMb -gt 0) {
                                (C 'DriverActionStatus').Text = ('AMR direct download: file {0}/{1}  |  {2:N1} / {3:N1} MB  |  {4:N2} MB/s' -f $fileIndex,$fileCount,$doneMb,$totalMb,$speedMb)
                            } else {
                                (C 'DriverActionStatus').Text = ('AMR direct download: file {0}/{1}  |  {2:N1} MB received  |  {3:N2} MB/s' -f $fileIndex,$fileCount,$doneMb,$speedMb)
                            }
                        } elseif ([string]$progressData.Stage -eq 'DirectDownloadCompleted') {
                            (C 'DriverActionStatus').Text = 'AMR download completed; validating and preparing the local driver package…'
                        } elseif ([string]$progressData.Stage -eq 'WuaCacheDownloadCompleted' -or [string]$progressData.Stage -eq 'WuaFallbackDownloadCompleted') {
                            (C 'DriverActionStatus').Text = 'Windows Update download completed; verifying the cached update…'
                        } elseif ([string]$progressData.Stage -eq 'DirectPreparationFallback') {
                            (C 'DriverActionStatus').Text = 'AMR could not prepare a safe local package; switching to Windows Update fallback…'
                        } elseif ([string]$progressData.Stage -eq 'WuaFallbackDownloadStarting') {
                            (C 'DriverActionStatus').Text = 'Windows Update fallback is downloading the selected driver package…'
                        } elseif ([string]$progressData.Stage -in @('WuaCacheDownload','WuaFallbackDownload')) {
                            if ($totalMb -gt 0) { (C 'DriverActionStatus').Text = ('Windows Update fallback download: {0}%  |  {1:N1} / {2:N1} MB  |  {3:N2} MB/s' -f $progressPercent,$doneMb,$totalMb,$speedMb) } else { (C 'DriverActionStatus').Text = ('Windows Update fallback download: {0}%  |  {1:N1} MB received  |  {2:N2} MB/s' -f $progressPercent,$doneMb,$speedMb) }
                        } elseif ($totalMb -gt 0) {
                            (C 'DriverActionStatus').Text = ('Downloading via Windows Update fallback: {0}%  |  {1:N1} / {2:N1} MB  |  {3:N2} MB/s' -f $progressPercent,$doneMb,$totalMb,$speedMb)
                        } else {
                            (C 'DriverActionStatus').Text = ('Downloading via Windows Update fallback: {0}%  |  {1:N1} MB received  |  {2:N2} MB/s' -f $progressPercent,$doneMb,$speedMb)
                        }
                    } else {
                        $stageText = if ([string]$progressData.Stage -eq 'Completed') { 'Finalizing' } else { 'Installing' }
                        (C 'DriverActionStatus').Text = ('{0} driver via Windows Update: {1}%' -f $stageText,$progressPercent)
                    }
                } catch {}
            }
            $actionTimeoutOperation=[string]$script:DriverActionType
            $actionTimeoutGraceSeconds=if($actionTimeoutOperation -eq 'Install'){300}else{0}
            $actionTimeoutExpired=(Test-AMRDriverOperationTimeout -Operation $actionTimeoutOperation -StartedAt ([datetime]$script:DriverActionStartedAt))
            if ($actionTimeoutExpired -and $actionTimeoutGraceSeconds -gt 0) {
                # The WUA worker has its own 180-minute RequestAbort path. Give it five
                # minutes to return that result before the UI watchdog terminates the job.
                $configuredTimeout=[int]$script:AMRDriverTimeouts[$actionTimeoutOperation]
                $actionTimeoutExpired=(((Get-Date)-[datetime]$script:DriverActionStartedAt).TotalSeconds -ge ($configuredTimeout+$actionTimeoutGraceSeconds))
            }
            if ($job.State -eq 'Running' -and $actionTimeoutExpired) {
                try { Stop-Job -Job $job -ErrorAction SilentlyContinue; Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {}
                $script:DriverActionJob=$null; $script:DriverActionTimer.Stop(); Release-AMRDriverOperationLock
                if($script:DriverActionProgressFile){try{Remove-Item -LiteralPath $script:DriverActionProgressFile -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath ($script:DriverActionProgressFile+'.tmp') -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath ($script:DriverActionProgressFile+'.cancel') -Force -ErrorAction SilentlyContinue}catch{}}
                $timedOutAction=[string]$script:DriverActionType
                $script:DriverActionProgressFile=$null; $script:DriverActionType=$null; $script:DriverActionUpdateId=$null; $script:DriverActionUpdateRevision=0
                $script:DriverSmartQueueActive=$false; $script:DriverSmartDownloadQueue=@(); $script:DriverBatchActive=$false; $script:DriverBatchQueue=@()
                if($script:DriverOperationState.Name -in @('DriverDownload','DriverInstall')){$script:DriverOperationState=[pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready'; PartialShown=$false }}
                (C 'DriverOperationProgress').Visibility='Collapsed'; (C 'DriverOperationProgress').IsIndeterminate=$false
                Write-AMRDriverTimeoutEvent -Operation ('Driver'+$timedOutAction) -Message $(if($timedOutAction -eq 'Install'){'Driver installation exceeded its configured timeout plus the Windows Update abort grace period and was stopped.'}else{'Driver action exceeded its configured timeout and was stopped.'}) -OperationId ([string]$script:DriverCurrentOperationId)
                (C 'DriverActionStatus').Text='Driver operation timed out and was stopped. Review Diagnostics and retry only after checking device state.'
                Update-AMRDriverActionButtons
                return
            }
            if ($job.State -notin @('Completed','Failed','Stopped')) { return }
            $script:DriverActionTimer.Stop()
            try {
                if ($job.State -ne 'Completed') {
                    $jobOutput = Receive-Job -Job $job -ErrorAction SilentlyContinue 2>&1 | Out-String
                    throw "Driver update operation failed. $jobOutput"
                }
                $actionResult = Receive-Job -Job $job -ErrorAction Stop | Select-Object -Last 1
                if (-not $actionResult) { throw 'The driver update operation returned no result.' }
                # A8 driver fix: results of different actions (Download / Install / failure) carry different
                # optional properties; under StrictMode a missing one aborted the completion handler
                # ('DirectFailure', 'RestorePointStatus' cannot be found). Missing ones are added as empty values only.
                if ($actionResult -isnot [System.Collections.IDictionary]) {
                    foreach ($optionalName in @('Action','Success','Message','ResultCode','HResult','RebootRequired','OutcomeStatus','InstallReady','LocalInstallReady','WuaReady',
                        'SavedCopy','SavedFolder','SavedCopyMessage','WuaDownloadError','WuaDownloadErrorDetails','WuaDownloadHResult','WuaDownloadErrorLine','WuaDownloadStackTrace',
                        'DirectFailure','DirectFailureDetails','DirectFailureHResult','DirectFailureLine','DirectFailureStackTrace',
                        'RestorePointStatus','PreInstallVerification','SignatureAudit','PostInstallVerification','InstalledDriverVersion','InstalledDriverInf',
                        'PreviousDriverVersion','PreviousDriverBackupStatus','PreviousDriverBackupPath','DeviceConfigManagerErrorCode',
                        'ErrorStage','ErrorLine','ErrorSourceLine','ErrorDetails','ScriptStackTrace')) {
                        if (-not $actionResult.PSObject.Properties[$optionalName]) {
                            $actionResult | Add-Member -NotePropertyName $optionalName -NotePropertyValue $null -Force
                        }
                    }
                    if (-not $actionResult.PSObject.Properties['SavedFiles']) { $actionResult | Add-Member -NotePropertyName SavedFiles -NotePropertyValue @() -Force }
                }
                if (-not [bool]$actionResult.Success) {
                    $failureText = [string]$actionResult.Message
                    if ($actionResult.HResult) { $failureText += ("`nHRESULT: 0x{0:X8}" -f [int]$actionResult.HResult) }
                    if ($actionResult.ErrorStage) { $failureText += ("`nStage: " + [string]$actionResult.ErrorStage) }
                    if ($actionResult.ErrorLine) { $failureText += ("`nWorker line: " + [string]$actionResult.ErrorLine) }
                    if ($actionResult.ErrorSourceLine) { $failureText += ("`nSource: " + [string]$actionResult.ErrorSourceLine.Trim()) }
                    if ($actionResult.ScriptStackTrace) { $failureText += ("`nScriptStackTrace: " + [string]$actionResult.ScriptStackTrace) }
                    if ($actionResult.ErrorDetails) { $failureText += ("`nException: " + [string]$actionResult.ErrorDetails) }
                    throw $failureText
                }
                $matchedRows = @($script:DriverAllDeviceRows | Where-Object {
                    [string]$_.UpdateId -eq [string]$script:DriverActionUpdateId -and
                    [int]$_.UpdateRevision -eq [int]$script:DriverActionUpdateRevision -and
                    [string]$_.DeviceId -ieq [string]$script:DriverActionDeviceId
                })
                foreach ($matchedRow in $matchedRows) {
                    if ($actionResult.Action -eq 'Download') {
                        $matchedRow.UpdateReady = [bool]$actionResult.InstallReady
                        $matchedRow.LocalPackageReady = [bool]$actionResult.LocalInstallReady
                        $matchedRow.LocalPackageFolder = if ($actionResult.LocalInstallReady) { [string]$actionResult.SavedFolder } else { $null }
                        if ([bool]$actionResult.LocalInstallReady) {
                            $matchedRow.UpdateStatus = 'AMR package ready to install'
                        } elseif ([bool]$actionResult.WuaReady) {
                            $matchedRow.UpdateStatus = 'Windows Update fallback ready to install'
                        } else {
                            $matchedRow.UpdateStatus = 'Download incomplete - retry required'
                        }
                    } else {
                        $matchedRow.UpdateReady = $false
                        $matchedRow.UpdateStatus = switch ([string]$actionResult.OutcomeStatus) {
                            'InstalledAndVerified' { 'Installed and verified' }
                            'InstalledRestartRequired' { 'Installed - restart required' }
                            'CompletedVerificationPending' { 'Completed - verification pending' }
                            'CompletedWithErrors' { 'Completed with errors - verify' }
                            default { 'Installation result requires verification' }
                        }
                    }
                }
                (C 'DriverDeviceList').Items.Refresh()
                if ($actionResult.Action -eq 'Download') {
                    (C 'DriverActionStatus').Text = [string]$actionResult.Message
                    if ($actionResult.SavedFolder) { $script:LastDriverPackageFolder = [string]$actionResult.SavedFolder }
                } else {
                    $restoreSummary = if ($actionResult.RestorePointStatus) { ' Restore point: ' + [string]$actionResult.RestorePointStatus + '.' } else { '' }
                    $preInstallSummary = if ($actionResult.PreInstallVerification) { ' Pre-install trust check: ' + [string]$actionResult.PreInstallVerification } else { '' }
                    $signatureSummary = if ($actionResult.SignatureAudit) { ' Post-install signature audit: ' + [string]$actionResult.SignatureAudit + '.' } else { '' }
                    $postInstallSummary = if ($actionResult.PostInstallVerification) { ' Post-install verification: ' + [string]$actionResult.PostInstallVerification } else { '' }
                    $previousBackupSummary = if ($actionResult.PreviousDriverBackupStatus) { ' Previous driver recovery: ' + [string]$actionResult.PreviousDriverBackupStatus + $(if ($actionResult.PreviousDriverBackupPath) { ' Folder: ' + [string]$actionResult.PreviousDriverBackupPath } else { '' }) } else { '' }
                    (C 'DriverActionStatus').Text = [string]$actionResult.Message + $preInstallSummary + $restoreSummary + $previousBackupSummary + $signatureSummary + $postInstallSummary + $(if ($actionResult.RebootRequired) { ' Restart Windows to complete the update, then scan again.' } elseif ([string]$actionResult.OutcomeStatus -ne 'InstalledAndVerified') { ' Run Scan Device again before treating the driver as installed.' } else { ' Driver state verified.' })
                }
                $historyDetails = 'ResultCode=' + $actionResult.ResultCode
                if ($actionResult.Action -eq 'Download') {
                    $historyDetails += '; SavedCopy=' + [string][bool]$actionResult.SavedCopy
                    if ($actionResult.SavedFolder) { $historyDetails += '; SavedFolder=' + [string]$actionResult.SavedFolder }
                    if ($actionResult.SavedCopyMessage) { $historyDetails += '; SavedCopyMessage=' + [string]$actionResult.SavedCopyMessage }
                    if ($actionResult.WuaDownloadError) { $historyDetails += '; WuaDownloadError=' + [string]$actionResult.WuaDownloadError }
                    if ($actionResult.WuaDownloadErrorDetails) { $historyDetails += '; WuaDownloadException=' + [string]$actionResult.WuaDownloadErrorDetails }
                    if ($actionResult.WuaDownloadHResult) { $historyDetails += ('; WuaDownloadHRESULT=0x{0:X8}' -f [int]$actionResult.WuaDownloadHResult) }
                    if ($actionResult.WuaDownloadErrorLine) { $historyDetails += '; WuaDownloadLine=' + [string]$actionResult.WuaDownloadErrorLine }
                    if ($actionResult.WuaDownloadStackTrace) { $historyDetails += '; WuaDownloadScriptStackTrace=' + [string]$actionResult.WuaDownloadStackTrace }
                    if ($actionResult.DirectFailure) { $historyDetails += '; AMRInternalEngineFallbackReason=' + [string]$actionResult.DirectFailure }
                    if ($actionResult.DirectFailureDetails) { $historyDetails += '; AMRInternalEngineException=' + [string]$actionResult.DirectFailureDetails }
                    if ($actionResult.DirectFailureHResult) { $historyDetails += ('; AMRInternalEngineHRESULT=0x{0:X8}' -f [int]$actionResult.DirectFailureHResult) }
                    if ($actionResult.DirectFailureLine) { $historyDetails += '; AMRInternalEngineLine=' + [string]$actionResult.DirectFailureLine }
                    if ($actionResult.DirectFailureStackTrace) { $historyDetails += '; AMRInternalEngineScriptStackTrace=' + [string]$actionResult.DirectFailureStackTrace }
                    if ($null -ne $actionResult.LocalInstallReady) { $historyDetails += '; LocalInstallReady=' + [string][bool]$actionResult.LocalInstallReady }
                    if ($null -ne $actionResult.WuaReady) { $historyDetails += '; WuaReady=' + [string][bool]$actionResult.WuaReady }
                    foreach ($savedFile in @($actionResult.SavedFiles)) {
                        if ($savedFile) { $historyDetails += ('; File={0}; SizeBytes={1}; SHA256={2}' -f $savedFile.FileName,$savedFile.SizeBytes,$savedFile.SHA256) }
                    }
                }
                if ($actionResult.RestorePointStatus) { $historyDetails += '; RestorePoint=' + $actionResult.RestorePointStatus }
                if ($actionResult.PreInstallVerification) { $historyDetails += '; PreInstallVerification=' + $actionResult.PreInstallVerification }
                if ($actionResult.SignatureAudit) { $historyDetails += '; PostInstallSignatureAudit=' + $actionResult.SignatureAudit }
                if ($actionResult.PostInstallVerification) { $historyDetails += '; PostInstallVerification=' + [string]$actionResult.PostInstallVerification }
                if ($actionResult.InstalledDriverVersion) { $historyDetails += '; ActiveDriverVersion=' + [string]$actionResult.InstalledDriverVersion }
                if ($actionResult.InstalledDriverInf) { $historyDetails += '; ActiveDriverInf=' + [string]$actionResult.InstalledDriverInf }
                if ($actionResult.PreviousDriverVersion) { $historyDetails += '; PreviousDriverVersion=' + [string]$actionResult.PreviousDriverVersion }
                if ($actionResult.PreviousDriverBackupStatus) { $historyDetails += '; PreviousDriverBackup=' + [string]$actionResult.PreviousDriverBackupStatus }
                if ($actionResult.PreviousDriverBackupPath) { $historyDetails += '; PreviousDriverBackupPath=' + [string]$actionResult.PreviousDriverBackupPath }
                if ($null -ne $actionResult.DeviceConfigManagerErrorCode) { $historyDetails += '; DeviceConfigManagerErrorCode=' + [string]$actionResult.DeviceConfigManagerErrorCode }
                $historyStatus = if ($actionResult.OutcomeStatus) { [string]$actionResult.OutcomeStatus } else { 'Success' }
                if ($actionResult.HResult) { $historyDetails += ('; HResult=0x{0:X8}' -f [int]$actionResult.HResult) }
                Add-AMRDriverHistoryEntry -Action $actionResult.Action -Device ([string]$script:DriverActionDeviceName) -Update ([string]$script:DriverActionUpdateTitle) -Version ([string]$script:DriverActionVersion) -Status $historyStatus -Details $historyDetails -DeviceInstanceId ([string]$script:DriverActionDeviceId) -OperationId $script:DriverCurrentOperationId
                $completionLogLevel = if ($historyStatus -in @('Success','InstalledAndVerified','InstalledRestartRequired')) { 'SUCCESS' } else { 'WARNING' }
                Write-AMRLog ("Driver update {0} completed with status {1}. UpdateId={2}; ResultCode={3}; RebootRequired={4}." -f $actionResult.Action,$historyStatus,$script:DriverActionUpdateId,$actionResult.ResultCode,$actionResult.RebootRequired) $completionLogLevel Overview
                Write-AMRDriverDiagnostic -Severity $(if ($completionLogLevel -eq 'SUCCESS') {'SUCCESS'} else {'WARNING'}) -Operation ('Driver' + [string]$actionResult.Action) -Stage Completed -Message ('Driver operation completed with status ' + $historyStatus + '.') -DeviceId ([string]$script:DriverActionDeviceId) -OperationId $script:DriverCurrentOperationId -Source ([string]$script:DriverActionSource) -DurationMs ([long]((Get-Date)-$script:DriverActionStartedAt).TotalMilliseconds) -Result $historyStatus -Context @{UpdateId=$script:DriverActionUpdateId;ResultCode=$actionResult.ResultCode;RebootRequired=[bool]$actionResult.RebootRequired;PostInstallVerification=$actionResult.PostInstallVerification;InstalledDriverVersion=$actionResult.InstalledDriverVersion;DirectFailure=$actionResult.DirectFailure;DirectFailureLine=$actionResult.DirectFailureLine;DirectFailureHResult=$actionResult.DirectFailureHResult;WuaDownloadError=$actionResult.WuaDownloadError;WuaDownloadErrorLine=$actionResult.WuaDownloadErrorLine;WuaDownloadHResult=$actionResult.WuaDownloadHResult}
                if ($actionResult.Action -eq 'Install' -and $actionResult.RebootRequired -and -not $script:DriverBatchActive) {
                    Show-AMRMessageGlass 'The driver installation completed and Windows reports that a restart is required. Save your work and restart when convenient.' 'Restart Required' OK Information | Out-Null
                }
                if ($script:DriverBatchActive -and $actionResult.Action -eq 'Install') {
                    $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$script:DriverActionDeviceName; Update=[string]$script:DriverActionUpdateTitle; Success=($historyStatus -in @('InstalledAndVerified','InstalledRestartRequired')); VerificationPending=($historyStatus -eq 'CompletedVerificationPending'); RebootRequired=[bool]$actionResult.RebootRequired; Status=[string]$historyStatus }
                    if ([bool]$actionResult.RebootRequired) { $script:DriverBatchRebootRequired = $true }
                }
            } catch {
                if ($script:DriverActionCancelRequested -and [string]$_.Exception.Message -like '*Download cancelled by the user*') {
                    (C 'DriverActionStatus').Text = 'Download cancelled. The partial package was removed; nothing was installed.'
                    try { Add-AMRDriverHistoryEntry -Action 'Download' -Device ([string]$script:DriverActionDeviceName) -Update ([string]$script:DriverActionUpdateTitle) -Version ([string]$script:DriverActionVersion) -Status 'Cancelled' -Details 'Cancelled by the user; the partial package was removed.' -DeviceInstanceId ([string]$script:DriverActionDeviceId) -OperationId $script:DriverCurrentOperationId } catch {}
                    Write-AMRLog 'Driver download cancelled by the user; the partial package was removed.' WARNING Overview
                    if ($script:DriverSmartQueueActive) { $script:DriverSmartDownloadQueue = @() }
                } else {
                (C 'DriverActionStatus').Text = 'Driver operation failed: ' + $_.Exception.Message
                Add-AMRDriverHistoryEntry -Action ([string]$script:DriverActionType) -Device ([string]$script:DriverActionDeviceName) -Update ([string]$script:DriverActionUpdateTitle) -Version ([string]$script:DriverActionVersion) -Status 'Failed' -Details ([string]$_.Exception.Message) -DeviceInstanceId ([string]$script:DriverActionDeviceId) -OperationId $script:DriverCurrentOperationId
                Write-AMRLog ('Driver update action failed: ' + $_.Exception.Message) ERROR Overview
                Write-AMRDriverDiagnostic -Severity ERROR -Operation ('Driver' + [string]$script:DriverActionType) -Stage Failed -Message 'Driver download/install operation failed.' -DeviceId ([string]$script:DriverActionDeviceId) -OperationId $script:DriverCurrentOperationId -DurationMs ([long]((Get-Date)-$script:DriverActionStartedAt).TotalMilliseconds) -Result 'Failed' -ErrorRecord $_ -Context @{UpdateId=$script:DriverActionUpdateId;UpdateTitle=$script:DriverActionUpdateTitle;Version=$script:DriverActionVersion}
                if ([string]$script:DriverActionType -eq 'Install') {
                    $recoveryRoot=Join-Path $env:ProgramData 'AMR Windows Utility\DriverRecovery'
                    $recoveryPrompt="The driver installation failed. Recovery options:`n`n1. Device Manager > device Properties > Driver > Roll Back Driver (if Windows enables it).`n2. Use Smart Restore to target the exact verified AMR System Restore point you created manually, if available.`n3. Review previous-driver exports under:`n$recoveryRoot`n`nOpen Device Manager now?"
                    if((Show-AMRMessageGlass $recoveryPrompt 'Driver Installation Recovery' YesNo Warning) -eq 'Yes'){try{Start-Process -FilePath 'devmgmt.msc' -ErrorAction Stop}catch{Show-AMRMessageGlass ('Could not open Device Manager: '+[string]$_.Exception.Message) 'Recovery' OK Warning | Out-Null}}
                }
                if ($script:DriverBatchActive -and $script:DriverActionType -eq 'Install') {
                    $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$script:DriverActionDeviceName; Update=[string]$script:DriverActionUpdateTitle; Success=$false; RebootRequired=$false; Status='Failed'; Details=[string]$_.Exception.Message }
                } elseif ($script:DriverSmartQueueActive -and [string]$script:DriverActionType -eq 'Download') {
                    (C 'DriverActionStatus').Text = ('Smart Install could not prepare {0}: {1}. AMR will continue with the remaining candidates.' -f [string]$script:DriverActionDeviceName,[string]$_.Exception.Message)
                    Write-AMRLog ('Smart Install package preparation failed and will be skipped: ' + [string]$_.Exception.Message) WARNING Overview
                } else {
                    Show-AMRMessageGlass ('Driver update operation failed:`n' + $_.Exception.Message) 'Driver Center' OK Error | Out-Null
                }
                }
            } finally {
                $wasBatchInstall = ($script:DriverBatchActive -and [string]$script:DriverActionType -eq 'Install')
                $wasSmartDownload = ($script:DriverSmartQueueActive -and [string]$script:DriverActionType -eq 'Download')
                try { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch {}
                Release-AMRDriverOperationLock
                $script:DriverActionJob = $null
                $script:DriverActionCancelRequested = $false
                try { $doneCancelButton = C 'DriverCancelManagedOperationBtn'; if ($doneCancelButton -and -not $script:DriverManagedJob) { $doneCancelButton.Visibility = 'Collapsed'; $doneCancelButton.IsEnabled = $false } } catch {}
                if($script:DriverOperationState.Name -in @('DriverDownload','DriverInstall')){$script:DriverOperationState=[pscustomobject]@{Name='Idle';State='Idle';StartedAt=$null;Generation=[int]$script:DriverOperationState.Generation;CanCancel=$false;Status='Ready'; PartialShown=$false }}
                $script:DriverActionUpdateId = $null
                $script:DriverActionUpdateRevision = 0
                $script:DriverActionType = $null
                $script:DriverActionDeviceName = $null
                $script:DriverActionDeviceId = $null
                $script:DriverActionSource = $null
                $script:DriverActionUpdateTitle = $null
                $script:DriverActionVersion = $null
                $script:DriverCurrentOperationId = $null
                (C 'DriverOperationProgress').Visibility = 'Collapsed'
                (C 'DriverOperationProgress').Value = 0
                if ($script:DriverActionProgressFile) {
                    try { Remove-Item -LiteralPath $script:DriverActionProgressFile -Force -ErrorAction SilentlyContinue } catch {}
                    try { Remove-Item -LiteralPath ($script:DriverActionProgressFile + '.tmp') -Force -ErrorAction SilentlyContinue } catch {}
                    try { Remove-Item -LiteralPath ($script:DriverActionProgressFile + '.cancel') -Force -ErrorAction SilentlyContinue } catch {}
                }
                $script:DriverActionProgressFile = $null
                Update-AMRDriverActionButtons
                if ($wasSmartDownload) {
                    if ($script:DriverSmartQueueActive) {
                        $script:DriverSmartDownloadCompleted++
                        if (@($script:DriverSmartDownloadQueue).Count -gt 0) {
                            if (-not (Start-AMRNextSmartDownloadQueueItem)) {
                                $script:DriverSmartQueueActive = $false
                                $script:DriverSmartDownloadQueue = @()
                                $script:DriverSmartDownloadTotal = 0
                                $script:DriverSmartDownloadCompleted = 0
                                (C 'DriverActionStatus').Text = 'Smart Install could not start the remaining preparation workers. Unprocessed candidates remain unverified, not failed; review Diagnostics and retry.'
                                Update-AMRDriverActionButtons
                                Complete-AMRSmartInstallPreparation
                            }
                        } else {
                            $script:DriverSmartQueueActive = $false
                            $script:DriverSmartDownloadTotal = 0
                            $script:DriverSmartDownloadCompleted = 0
                            $script:DriverSmartDownloadQueue = @()
                            Complete-AMRSmartInstallPreparation
                        }
                    }
                }
                if ($wasBatchInstall) {
                    $script:DriverBatchCompleted++
                    while (@($script:DriverBatchQueue).Count -gt 0 -and -not $script:DriverActionJob -and -not $script:DriverBatchRebootRequired) {
                        $script:DriverBatchQueueIterations = [int]$script:DriverBatchQueueIterations + 1
                        if ($script:DriverBatchQueueIterations -gt [int]$script:AMRDriverMaxQueueIterations) {
                            $script:DriverBatchQueue = @(); $script:DriverBatchActive = $false
                            Write-AMRDriverDiagnostic -Severity ERROR -Operation BatchInstall -Stage QueueGuard -Message 'Batch Install queue stopped after exceeding the safety iteration limit.' -Source 'Phase1QueueGuard' -Result 'Stopped'
                            (C 'DriverActionStatus').Text = 'Batch Install queue stopped by its safety limit. Review Diagnostics before retrying.'
                            break
                        }
                        $nextBatchDevice = $script:DriverBatchQueue[0]
                        if (@($script:DriverBatchQueue).Count -gt 1) { $script:DriverBatchQueue = @($script:DriverBatchQueue | Select-Object -Skip 1) } else { $script:DriverBatchQueue = @() }
                        try {
                            Start-AMRDriverUpdateAction -Action Install -Device $nextBatchDevice -SkipConfirmation -FromBatch
                            if (-not $script:DriverActionJob) {
                                $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$nextBatchDevice.DeviceName; Update=[string]$nextBatchDevice.AvailableUpdate; Success=$false; RebootRequired=$false; Status='Failed to start'; Details='The update action did not create a background job.' }
                                $script:DriverBatchCompleted++
                            }
                        } catch {
                            $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$nextBatchDevice.DeviceName; Update=[string]$nextBatchDevice.AvailableUpdate; Success=$false; RebootRequired=$false; Status='Failed to start'; Details=[string]$_.Exception.Message }
                            $script:DriverBatchCompleted++
                        }
                    }
                    if ((@($script:DriverBatchQueue).Count -eq 0 -or $script:DriverBatchRebootRequired) -and -not $script:DriverActionJob) {
                        if ($script:DriverBatchRebootRequired -and @($script:DriverBatchQueue).Count -gt 0) {
                            foreach ($deferredDevice in @($script:DriverBatchQueue)) { $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$deferredDevice.DeviceName; Update=[string]$deferredDevice.AvailableUpdate; Success=$false; RebootRequired=$false; Status='Deferred - restart required'; Details='Queue paused at a Windows restart boundary. Restart Windows, scan again, and review remaining updates.' } }
                            $script:DriverBatchQueue = @()
                        }
                        Complete-AMRDriverBatchSummary
                    }
                }
            }
        })
    }
    } catch { Release-AMRDriverOperationLock; throw }
    $script:DriverActionUpdateId = $updateId
    $script:DriverActionUpdateRevision = [int]$revision
    $script:DriverActionType = $Action
    $script:DriverCurrentOperationId = [guid]::NewGuid().ToString('N')
    $script:DriverActionStartedAt = Get-Date
    $script:DriverActionLastLoggedStage = $null
    Write-AMRDriverDiagnostic -Severity INFO -Operation ('Driver' + $Action) -Stage Started -Message ('Driver ' + $Action.ToLowerInvariant() + ' operation started.') -DeviceId ([string]$selected.DeviceId) -OperationId $script:DriverCurrentOperationId -Source ([string]$selected.SourceAdapter) -Context @{DeviceName=[string]$selected.DeviceName;UpdateId=$updateId;Revision=$revision;Version=[string]$selected.AvailableVersion;FromBatch=[bool]$FromBatch}
    $script:DriverActionDeviceName = [string]$selected.DeviceName
    $script:DriverActionDeviceId = [string]$selected.DeviceId
    $script:DriverActionSource = [string]$selected.SourceAdapter
    $script:DriverActionUpdateTitle = [string]$selected.AvailableUpdate
    $script:DriverActionVersion = [string]$selected.AvailableVersion
    $script:DriverActionTimer.Start()
}

function Select-AMRReadyDriverUpdates {
    $list = C 'DriverDeviceList'
    $list.SelectedItems.Clear()
    foreach ($row in @($list.ItemsSource | Where-Object { $_.UpdateReady -and -not [string]::IsNullOrWhiteSpace([string]$_.UpdateId) })) {
        [void]$list.SelectedItems.Add($row)
    }
    Update-AMRDriverActionButtons
    (C 'DriverActionStatus').Text = ('Selected {0} downloaded update(s) ready for installation. Review the highlighted rows, then choose Install Selected Ready.' -f @($list.SelectedItems | Where-Object { $_.UpdateReady }).Count)
}

function Clear-AMRDriverSelection {
    (C 'DriverDeviceList').SelectedItems.Clear()
    Update-AMRDriverActionButtons
    (C 'DriverActionStatus').Text = 'Driver selection cleared.'
}

function Get-AMRDriverInstallPlan {
    param([object[]]$Rows)
    # A conservative, explainable ordering heuristic. This is not a claim of vendor dependency metadata.
    $seen = @{}; $unique = @()
    foreach ($row in @($Rows)) {
        if (-not $row -or [string]::IsNullOrWhiteSpace([string]$row.UpdateId)) { continue }
        $key = ('{0}|{1}' -f [string]$row.UpdateId,[int]$row.UpdateRevision)
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        # Driver rows can originate from different providers and may not expose every optional class field.
        # Read optional properties through PSObject.Properties to avoid WPF dispatcher exceptions.
        $deviceClassValue = if ($row.PSObject.Properties['DeviceClass']) { [string]$row.PSObject.Properties['DeviceClass'].Value } else { '' }
        $driverClassValue = if ($row.PSObject.Properties['DriverClass']) { [string]$row.PSObject.Properties['DriverClass'].Value } else { '' }
        $deviceNameValue = if ($row.PSObject.Properties['DeviceName']) { [string]$row.PSObject.Properties['DeviceName'].Value } else { '' }
        $classText = ($deviceClassValue + ' ' + $driverClassValue + ' ' + $deviceNameValue).ToLowerInvariant()
        $priority = 50; $group = 'Other devices'; $reason = 'No special dependency class detected; install after platform-level drivers.'
        if ($classText -match 'system|chipset|smbus|pci|processor|motherboard') { $priority=10; $group='Platform / chipset'; $reason='Platform-level device class; schedule early.' }
        elseif ($classText -match 'storage|sata|raid|scsi|nvme|controller') { $priority=20; $group='Storage / controllers'; $reason='Storage/controller class; schedule before peripheral drivers.' }
        elseif ($classText -match 'network|ethernet|wireless|wi-fi|bluetooth') { $priority=30; $group='Network / connectivity'; $reason='Connectivity class; schedule after platform and storage.' }
        elseif ($classText -match 'display|video|graphics') { $priority=40; $group='Display / graphics'; $reason='Graphics class; schedule after platform drivers.' }
        elseif ($classText -match 'audio|sound|media') { $priority=45; $group='Audio / media'; $reason='Audio/media class; schedule after platform drivers.' }
        $unique += [pscustomobject]@{ Row=$row; Priority=$priority; Group=$group; Reason=$reason; Key=$key }
    }
    return @($unique | Sort-Object Priority, @{Expression={[string]$_.Row.DeviceName}})
}

function Show-AMRDriverInstallPlan {
    $selectedRows = @((C 'DriverDeviceList').SelectedItems | Where-Object { $_.UpdateReady -and -not [string]::IsNullOrWhiteSpace([string]$_.UpdateId) })
    if ($selectedRows.Count -eq 0) { Show-AMRMessageGlass 'Select one or more Ready driver packages first.' 'Install Planning' OK Information | Out-Null; return }
    $plan = @(Get-AMRDriverInstallPlan -Rows $selectedRows)
    if ($plan.Count -eq 0) { return }
    $lines = @(); $index=0
    foreach ($entry in $plan) {
        $index++
        $row=$entry.Row
        $version=if ([string]::IsNullOrWhiteSpace([string]$row.AvailableVersion)) {'version not reported'} else {[string]$row.AvailableVersion}
        $lines += ('{0}. [{1}] {2} — {3} ({4})' -f $index,$entry.Group,[string]$row.DeviceName,[string]$row.AvailableUpdate,$version)
    }
    $body = "AMR proposed installation order`n`n" + ($lines -join "`n") + "`n`nPlanning rules: platform/chipset → storage/controllers → network → graphics → audio → other devices. This is a conservative class-based heuristic, not a vendor-provided dependency graph. Each package is revalidated immediately before installation. If Windows requests a restart, the remaining queue will pause until you restart and scan again. AMR does not create a System Restore point automatically. Create one manually first if you want a recovery point; AMR also attempts to export the currently installed OEM driver package for each device when Windows permits it.`n`nContinue with this plan?"
    if ((Show-AMRMessageGlass $body 'Review Driver Installation Plan' YesNo Warning) -ne 'Yes') { return }
    Start-AMRDriverBatchInstall -ApprovedPlan $plan
}

function Complete-AMRDriverBatchSummary {
    $batchSuccessCount = @($script:DriverBatchResults | Where-Object { $_.Success }).Count
    $batchPendingCount = @($script:DriverBatchResults | Where-Object { $_.Status -eq 'CompletedVerificationPending' }).Count
    $deferredCount = @($script:DriverBatchResults | Where-Object { $_.Status -eq 'Deferred - restart required' }).Count
    $batchFailureCount = @($script:DriverBatchResults | Where-Object { $_.Status -notin @('InstalledAndVerified','InstalledRestartRequired','CompletedVerificationPending','Deferred - restart required') }).Count
    $batchRebootText = if ($script:DriverBatchRebootRequired) { ' Windows requires a restart to complete one or more updates. No restart was performed.' } else { ' No restart was requested by Windows.' }
    (C 'DriverActionStatus').Text = ('Batch plan paused/completed: {0} verified, {1} completed but verification pending, {2} failed, {3} deferred.{4} Run Scan Device again to verify active versions.' -f $batchSuccessCount,$batchPendingCount,$batchFailureCount,$deferredCount,$batchRebootText)
    $batchSummary = "Batch driver installation plan paused/completed.`n`nSucceeded and verified: $batchSuccessCount`nCompleted - verification pending: $batchPendingCount`nFailed: $batchFailureCount`nDeferred after restart boundary: $deferredCount`n$batchRebootText`n`nA verification-pending result means Windows reported the installation operation completed, but AMR could not yet confirm the active device driver/version. It is not counted as a confirmed failure. Run Scan Device again before deciding whether another installation is needed."
    $script:DriverBatchActive = $false
    $script:DriverBatchQueue = @()
    $script:DriverBatchTotal = 0
    $script:DriverBatchCompleted = 0
    $script:DriverBatchRebootRequired = $false
    $script:DriverBatchRestorePointStatus = $null
    $script:DriverBatchResults = @()
    Update-AMRDriverActionButtons
    Show-AMRMessageGlass $batchSummary 'Batch Installation Results' OK Information | Out-Null
}

function Start-AMRDriverBatchInstall {
    param([object[]]$ApprovedPlan)
    if ($script:DriverManagedJob -or $script:DriverActionJob -or $script:DriverScanJob -or $script:DriverOperationState.State -eq 'Running' -or $script:DriverBatchActive -or $script:DriverSmartQueueActive) { return }
    $selectedRows = @((C 'DriverDeviceList').SelectedItems | Where-Object { $_.UpdateReady -and -not [string]::IsNullOrWhiteSpace([string]$_.UpdateId) })
    if ($selectedRows.Count -eq 0) {
        Show-AMRMessageGlass 'Select one or more rows marked Ready to install. Use Select All Ready to select every downloaded update.' 'Selection Required' OK Information | Out-Null
        return
    }
    $admin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    if (-not $admin) {
        Show-AMRMessageGlass 'Installing device drivers requires administrator permissions. Reopen AMR as Administrator, scan again, then retry.' 'Administrator permission required' OK Warning | Out-Null
        return
    }
    # Use the reviewed plan when supplied; otherwise create the same deterministic plan.
    $plan = if ($ApprovedPlan -and $ApprovedPlan.Count -gt 0) { @($ApprovedPlan) } else { @(Get-AMRDriverInstallPlan -Rows $selectedRows) }
    $uniqueRows = @($plan | ForEach-Object { $_.Row })
    if ($uniqueRows.Count -eq 0) { return }
    $preview = @($uniqueRows | Select-Object -First 12 | ForEach-Object { '• ' + [string]$_.DeviceName + ' — ' + [string]$_.AvailableUpdate + ' (' + [string]$_.AvailableVersion + ')' }) -join "`n"
    if ($uniqueRows.Count -gt 12) { $preview += "`n• … and $($uniqueRows.Count - 12) more update(s)" }
    $confirmText = "Install $($uniqueRows.Count) selected ready driver update(s) in AMR's planned order, one at a time?`n`n$preview`n`nEach update will be revalidated by Windows Update before installation. Failed items will be recorded and the remaining queue will continue. If Windows requests a restart, AMR pauses the remaining queue; restart and scan again before continuing. AMR will NOT restart automatically. Continue?"
    if (-not ($ApprovedPlan -and $ApprovedPlan.Count -gt 0)) {
        if ((Show-AMRMessageGlass $confirmText 'Confirm Batch Driver Installation' YesNo Warning) -ne 'Yes') { return }
    }

    $script:DriverBatchQueueIterations = 0
    $script:DriverBatchActive = $true
    $script:DriverBatchTotal = $uniqueRows.Count
    $script:DriverBatchCompleted = 0
    $script:DriverBatchResults = @()
    $script:DriverBatchRestorePointStatus = $null
    $script:DriverBatchRebootRequired = $false
    if ($uniqueRows.Count -gt 1) { $script:DriverBatchQueue = @($uniqueRows | Select-Object -Skip 1) } else { $script:DriverBatchQueue = @() }
    (C 'DriverActionStatus').Text = ('Batch installation starting: {0} update(s), sequential processing.' -f $uniqueRows.Count)
    try { Start-AMRDriverUpdateAction -Action Install -Device $uniqueRows[0] -SkipConfirmation -FromBatch }
    catch {
        $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$uniqueRows[0].DeviceName; Update=[string]$uniqueRows[0].AvailableUpdate; Success=$false; RebootRequired=$false; Status='Failed to start'; Details=[string]$_.Exception.Message }
    }
    if (-not $script:DriverActionJob) {
        if (@($script:DriverBatchResults).Count -eq 0) {
            $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$uniqueRows[0].DeviceName; Update=[string]$uniqueRows[0].AvailableUpdate; Success=$false; RebootRequired=$false; Status='Failed to start'; Details='The first batch installation worker did not start.' }
        }
        $script:DriverBatchCompleted++
        while (@($script:DriverBatchQueue).Count -gt 0 -and -not $script:DriverActionJob) {
            $script:DriverBatchQueueIterations++
            if ($script:DriverBatchQueueIterations -gt [int]$script:AMRDriverMaxQueueIterations) {
                foreach ($remainingDevice in @($script:DriverBatchQueue)) {
                    $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$remainingDevice.DeviceName; Update=[string]$remainingDevice.AvailableUpdate; Success=$false; RebootRequired=$false; Status='Not processed - safety limit'; Details='Batch queue safety limit reached before a worker could start.' }
                }
                $script:DriverBatchQueue = @()
                break
            }
            $nextDevice = $script:DriverBatchQueue[0]
            if (@($script:DriverBatchQueue).Count -gt 1) { $script:DriverBatchQueue = @($script:DriverBatchQueue | Select-Object -Skip 1) } else { $script:DriverBatchQueue = @() }
            try { Start-AMRDriverUpdateAction -Action Install -Device $nextDevice -SkipConfirmation -FromBatch }
            catch {
                $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$nextDevice.DeviceName; Update=[string]$nextDevice.AvailableUpdate; Success=$false; RebootRequired=$false; Status='Failed to start'; Details=[string]$_.Exception.Message }
            }
            if (-not $script:DriverActionJob) {
                if (@($script:DriverBatchResults | Where-Object { $_.Device -eq [string]$nextDevice.DeviceName -and $_.Update -eq [string]$nextDevice.AvailableUpdate }).Count -eq 0) {
                    $script:DriverBatchResults += [pscustomobject]@{ Device=[string]$nextDevice.DeviceName; Update=[string]$nextDevice.AvailableUpdate; Success=$false; RebootRequired=$false; Status='Failed to start'; Details='The batch installation worker did not start.' }
                }
                $script:DriverBatchCompleted++
            }
        }
        if (-not $script:DriverActionJob) { Complete-AMRDriverBatchSummary }
    }
}

function Open-AMRDriverRecoveryFolder {
    $root = Join-Path $env:ProgramData 'AMR Windows Utility\DriverRecovery'
    try {
        if (-not (Test-Path -LiteralPath $root -PathType Container)) {
            Show-AMRMessageGlass 'No previous-driver recovery exports have been created yet. AMR creates an export automatically before an installation when Windows exposes an exportable OEM driver package.' 'Driver Recovery Backups' OK Information | Out-Null
            return
        }
        Start-Process -FilePath 'explorer.exe' -ArgumentList @($root) -ErrorAction Stop
    } catch { Show-AMRMessageGlass ('Could not open the driver recovery folder: ' + [string]$_.Exception.Message) 'Driver Recovery Backups' OK Error | Out-Null }
}

function Invoke-AMRDriverRollbackCheck {
    $selected = (C 'DriverDeviceList').SelectedItem
    if (-not $selected -or [string]::IsNullOrWhiteSpace([string]$selected.DeviceId)) {
        Show-AMRMessageGlass 'Select a device row first.' 'Driver Rollback' OK Information | Out-Null
        return
    }
    if($script:DriverManagedJob -or $script:DriverActionJob -or $script:DriverScanJob){return}
    $deviceSnapshot=$selected
    try {
        $null=Start-AMRDriverManagedWorker -Operation RollbackCheck -Device $deviceSnapshot
        (C 'DriverRollbackStatus').Text='Checking Windows Driver Store and AMR recovery manifests in the background…'
        (C 'DriverActionStatus').Text='Rollback availability check is running in the background.'
        $poll=New-Object System.Windows.Threading.DispatcherTimer
        $poll.Interval=[TimeSpan]::FromMilliseconds(450)
        $poll.Add_Tick(({
            if(-not $script:DriverManagedJob){$poll.Stop();return}
            if($script:DriverManagedJob.State -in @('Completed','Failed','Stopped')){
                $poll.Stop()
                try {
                    $result=Complete-AMRDriverManagedWorker
                    if(-not $result){throw 'Rollback availability check returned no result.'}
                    (C 'DriverRollbackStatus').Text=[string]$result.Status
                    (C 'DriverActionStatus').Text='Rollback availability check completed. No driver was changed.'
                    Write-AMRLog ("Rollback availability checked for '{0}' ({1}). {2}" -f $result.DeviceName,$result.DeviceId,$result.CandidateText) INFO Overview
                    $confirm="Selected device:`n$($result.DeviceName)`n`n$($result.CurrentInf)`n`n$($result.Status)`n`nOpen Device Manager now? AMR will not change or remove any driver."
                    if((Show-AMRMessageGlass $confirm 'Check Driver Rollback' YesNo Information) -eq 'Yes'){Start-Process -FilePath 'devmgmt.msc' -ErrorAction Stop}
                } catch {
                    (C 'DriverRollbackStatus').Text='Rollback check failed: '+[string]$_.Exception.Message
                    Show-AMRMessageGlass ([string]$_.Exception.Message) 'Driver Rollback' OK Error | Out-Null
                }
            }
        }).GetNewClosure())
        $script:DriverManagedTimer=$poll; $poll.Start()
    } catch {
        (C 'DriverRollbackStatus').Text='Could not start rollback check: '+[string]$_.Exception.Message
        Show-AMRMessageGlass ([string]$_.Exception.Message) 'Driver Rollback' OK Error | Out-Null
    }
}

(C 'DriverRollbackCheckBtn').Add_Click({ Invoke-AMRDriverRollbackCheck })
