$script:AppsView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($script:SoftwareCatalog)

# Build category navigation entries with live catalog counts.
# Counts switch to installed-only totals whenever Show Installed is active.
$script:SelectedSoftwareCategory = 'All Applications'
$script:ShowInstalledOnly = $false
$script:SoftwareCategoryNames = @(
    $script:SoftwareCatalog |
        ForEach-Object { [string]$_.Category } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Sort-Object -Unique
)
$script:SoftwareCategories = @(
    [pscustomobject]@{ Name = 'All Applications'; DisplayText = 'All Applications'; CategoryNumber = '' }
) + @(
    for ($categoryIndex = 0; $categoryIndex -lt $script:SoftwareCategoryNames.Count; $categoryIndex++) {
        $categoryName = [string]$script:SoftwareCategoryNames[$categoryIndex]
        [pscustomobject]@{ Name = $categoryName; DisplayText = $categoryName; CategoryNumber = ('{0}' -f ($categoryIndex + 1)) }
    }
)
# Compact category navigation: keep category tiles plain and small.
$categoryTextFactory = New-Object System.Windows.FrameworkElementFactory([System.Windows.Controls.TextBlock])
$categoryTextFactory.Name = 'AMRCategoryLabel'
$categoryTextFactory.SetBinding([System.Windows.Controls.TextBlock]::TextProperty, [System.Windows.Data.Binding]::new('DisplayText'))
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::TextWrappingProperty, [System.Windows.TextWrapping]::NoWrap)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::TextTrimmingProperty, [System.Windows.TextTrimming]::CharacterEllipsis)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::FontSizeProperty, [double]12.0)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::MaxWidthProperty, 160.0)
$categoryTextFactory.SetValue([System.Windows.Controls.TextBlock]::VerticalAlignmentProperty, [System.Windows.VerticalAlignment]::Center)
$categoryTemplate = [System.Windows.DataTemplate]::new()
$categoryTemplate.VisualTree = $categoryTextFactory
(C 'SoftwareCategoryList').ItemTemplate = $categoryTemplate
(C 'SoftwareCategoryList').ItemsSource = $script:SoftwareCategories
(C 'SoftwareCategoryList').SelectedIndex = 0

function Update-AMRSoftwareCategoryCounts {
    $counts = @{}
    foreach ($entry in $script:SoftwareCategories) { $counts[[string]$entry.Name] = 0 }
    if ($script:ShowInstalledOnly) {
        foreach ($item in $script:InstalledAppsInventory) {
            if (-not [bool]$item.IsUserFacing -or -not [bool]$item.CanUninstall) { continue }
            $category = [string]$item.Category
            if ($category -and $counts.ContainsKey($category)) { $counts[$category] = [int]$counts[$category] + 1 }
        }
        $allCount = @($script:InstalledAppsInventory | Where-Object { [bool]$_.IsUserFacing -and [bool]$_.CanUninstall }).Count
    } else {
        foreach ($item in $script:SoftwareCatalog) {
            $category = [string]$item.Category
            if ($category -and $counts.ContainsKey($category)) { $counts[$category] = [int]$counts[$category] + 1 }
        }
        $allCount = $script:SoftwareCatalog.Count
    }
    foreach ($entry in $script:SoftwareCategories) {
        $count = if ($entry.Name -eq 'All Applications') { $allCount } else { [int]$counts[[string]$entry.Name] }
        $entry.DisplayText = '{0} ({1})' -f $entry.Name, $count
    }
    try { (C 'SoftwareCategoryList').Items.Refresh() } catch {}
}

Update-AMRSoftwareCategoryCounts
try { (C 'UninstallSelectedBtn').Visibility = 'Collapsed' } catch {}

# Universal installed-app inventory is deliberately separate from SoftwareCatalog.
# Unknown apps must never enter Smart Install / Update / Repair pipelines.
$script:InstalledAppsInventory = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:InstalledAppsView = $null

function New-AMRInstalledInventoryRecord {
    param(
        [string]$Name, [string]$Publisher='', [string]$DisplayVersion='', [string]$InstallDate='',
        [string]$InstallLocation='', [string]$DisplayIcon='', [string]$ShortcutPath='', [string]$UninstallString='', [string]$QuietUninstallString='',
        [bool]$WindowsInstaller=$false, [string]$RegistryKeyPath='', [string]$RegistryHive='',
        [string]$RegistryView='', [string]$AppxPackageFullName='', [string]$PackageFamilyName='',
        [string]$WingetId='', [string]$ChocoId='', [string]$ScoopName='', [string]$Source='',
        [bool]$IsCatalogApp=$false, [string]$CatalogId='', [bool]$IsInstalled=$true,
        [bool]$CanUninstall=$false, [string]$UninstallMethod='', [string]$UninstallReason='',
        [string]$PortableExecutablePath='', [string]$PortableRootFolder='', [bool]$IsPortable=$false,
        [string]$IdentityKey='', [string]$Confidence='High'
    )
    if ([string]::IsNullOrWhiteSpace($IdentityKey)) {
        $IdentityKey = if ($RegistryKeyPath) { 'REG:' + $RegistryKeyPath.ToLowerInvariant() }
            elseif ($AppxPackageFullName) { 'APPX:' + $AppxPackageFullName.ToLowerInvariant() }
            elseif ($WingetId) { 'WINGET:' + $WingetId.ToLowerInvariant() }
            elseif ($ChocoId) { 'CHOCO:' + $ChocoId.ToLowerInvariant() }
            elseif ($ScoopName) { 'SCOOP:' + $ScoopName.ToLowerInvariant() }
            elseif ($PortableExecutablePath) { 'PORTABLE:' + $PortableExecutablePath.ToLowerInvariant() }
            else { 'OTHER:' + (($Name -replace '\s+',' ').Trim().ToLowerInvariant()) }
    }
    $initials = (($Name -split '\s+' | Where-Object { $_ } | Select-Object -First 2 | ForEach-Object { $_.Substring(0,1) }) -join '').ToUpperInvariant()
    return [pscustomobject][ordered]@{
        Name=$Name; Publisher=$Publisher; DisplayVersion=$DisplayVersion; InstallDate=$InstallDate
        Category=''; IsUniversalInventory=$false; DetailsExpanded=$false; DisplayInstallPath=''; HasCopyableInstallPath=$false; InstallLocation=$InstallLocation; DisplayIcon=$DisplayIcon; ShortcutPath=$ShortcutPath; UninstallString=$UninstallString; QuietUninstallString=$QuietUninstallString
        WindowsInstaller=$WindowsInstaller; RegistryKeyPath=$RegistryKeyPath; RegistryHive=$RegistryHive; RegistryView=$RegistryView
        AppxPackageFullName=$AppxPackageFullName; PackageFamilyName=$PackageFamilyName; WingetId=$WingetId
        ChocoId=$ChocoId; ScoopName=$ScoopName; Source=$Source; IsCatalogApp=$IsCatalogApp; CatalogId=$CatalogId
        IsInstalled=$IsInstalled; IsSelected=$false; CanUninstall=$CanUninstall; UninstallMethod=$UninstallMethod
        UninstallReason=$UninstallReason; Initials=$initials; Icon=$null; Id=$(if($CatalogId){$CatalogId}elseif($WingetId){$WingetId}elseif($AppxPackageFullName){$AppxPackageFullName}else{$IdentityKey})
        IdentityKey=$IdentityKey; Confidence=$Confidence; PortableExecutablePath=$PortableExecutablePath
        PortableRootFolder=$PortableRootFolder; IsPortable=$IsPortable
        DisplayName=$Name; CardDisplayName=$Name; IsUserFacing=$false; UserFacingReason='Not evaluated'; UserFacingScore=0; PackageNonRemovable=$false
    }
}

function Get-AMRInstalledPresentationName {
    param([object]$Record)

    $name = [string]$Record.Name
    if ([string]::IsNullOrWhiteSpace($name)) { return 'Unknown application' }

    # AppX package identities often expose internal package names rather than the
    # concise product name users expect in an installed-applications list.
    $appxNames = @{
        'Microsoft.WindowsCalculator' = 'Calculator'
        'Microsoft.WindowsCamera' = 'Camera'
        'Microsoft.Windows.Photos' = 'Photos'
        'Microsoft.WindowsNotepad' = 'Notepad'
        'Microsoft.WindowsTerminal' = 'Windows Terminal'
        'Microsoft.WindowsAlarms' = 'Clock'
        'Microsoft.WindowsSoundRecorder' = 'Sound Recorder'
        'Microsoft.YourPhone' = 'Phone Link'
        'Microsoft.WindowsStore' = 'Microsoft Store'
        'Microsoft.ScreenSketch' = 'Snipping Tool'
        'Microsoft.GetHelp' = 'Get Help'
        'Microsoft.Getstarted' = 'Tips'
        'Microsoft.MicrosoftStickyNotes' = 'Sticky Notes'
        'Microsoft.Paint' = 'Paint'
        'Microsoft.WindowsMaps' = 'Maps'
        'Microsoft.BingWeather' = 'Weather'
        'Microsoft.Todos' = 'Microsoft To Do'
        'MSTeams' = 'Microsoft Teams'
        'MicrosoftTeams' = 'Microsoft Teams'
        'Microsoft.OutlookForWindows' = 'Outlook (new)'
        'Microsoft.Windows.DevHome' = 'Dev Home'
        'Microsoft.PowerAutomateDesktop' = 'Power Automate'
        'MicrosoftCorporationII.QuickAssist' = 'Quick Assist'
        'Microsoft.WindowsFeedbackHub' = 'Feedback Hub'
        'Microsoft.ZuneMusic' = 'Media Player'
        'Microsoft.ZuneVideo' = 'Movies & TV'
    }
    if ($appxNames.ContainsKey($name)) { return [string]$appxNames[$name] }

    $display = ($name -replace '\s+', ' ').Trim()
    # Remove only redundant architecture labels; preserve meaningful edition/product text.
    $display = $display -replace '(?i)\s*\((?:x64|x86|64[- ]bit|32[- ]bit|arm64)\)\s*$', ''
    $display = $display -replace '(?i)\s+(?:x64|x86|64[- ]bit|32[- ]bit)\s*$', ''
    $display = $display -replace '(?i)\s+-\s+(?:x64|x86|64[- ]bit|32[- ]bit)\s*$', ''
    $display = ($display -replace '\s{2,}', ' ').Trim(' ', '-', ',')
    if ([string]::IsNullOrWhiteSpace($display)) { $display = $name }
    return $display
}

function Get-AMRInstalledCanonicalNameKey {
    param([string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return '' }
    $key = (($Name -replace '\s+', ' ').Trim() -replace '(?i)\s*\((?:x64|x86|64[- ]bit|32[- ]bit|arm64)\)\s*$', '')
    $key = ($key -replace '(?i)\s+(?:x64|x86|64[- ]bit|32[- ]bit)\s*$', '')
    $key = ($key -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
    $aliases = @{
        'aimp3'='aimp'; 'aimp4'='aimp';
        'vlc'='vlcmediaplayer'; 'videolanvlc'='vlcmediaplayer';
        'itunes64bit'='itunes'; 'appleitunes'='itunes';
        'teamviewerfull'='teamviewer'; 'teamviewermachinewide'='teamviewer';
        'internetdownloadmanager'='internetdownloadmanager'; 'idman'='internetdownloadmanager'; 'idm'='internetdownloadmanager';
        'anydesk'='anydesk'; 'ndisk'='ndisk'
    }
    if ($aliases.ContainsKey($key)) { return [string]$aliases[$key] }
    return $key
}

function Remove-AMRDuplicateInstalledInventoryRecords {
    param([object[]]$Records)

    # Keep one uninstallable installation record per normalized product identity.
    # Native Windows uninstall registrations win over package-manager/portable
    # discovery because they carry the real registered uninstall command.
    $groups = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    $duplicatesRemoved = 0
    foreach ($record in @($Records)) {
        if ($null -eq $record) { continue }
        $key = Get-AMRInstalledCanonicalNameKey -Name ([string]$record.Name)
        if ([string]::IsNullOrWhiteSpace($key)) { continue }
        $score = 0
        if ([bool]$record.IsInstalled) { $score += 100 }
        if ([bool]$record.CanUninstall) { $score += 1000 }
        if ([string]$record.Source -eq 'Windows Registry') { $score += 500 }
        elseif ([string]$record.Source -eq 'AppX/MSIX') { $score += 400 }
        elseif ([string]$record.Source -eq 'WinGet') { $score += 250 }
        elseif ([string]$record.Source -eq 'Chocolatey') { $score += 200 }
        elseif ([string]$record.Source -eq 'Scoop') { $score += 180 }
        elseif ([string]$record.Source -eq 'Portable candidate') { $score += 50 }
        if (-not [string]::IsNullOrWhiteSpace([string]$record.UninstallString)) { $score += 80 }
        if (-not [string]::IsNullOrWhiteSpace([string]$record.QuietUninstallString)) { $score += 30 }
        if (-not [string]::IsNullOrWhiteSpace([string]$record.InstallLocation)) { $score += 20 }
        if (-not [string]::IsNullOrWhiteSpace([string]$record.DisplayIcon)) { $score += 10 }
        if (-not [string]::IsNullOrWhiteSpace([string]$record.Publisher)) { $score += 5 }

        if (-not $groups.ContainsKey($key)) {
            $groups[$key] = [pscustomobject]@{ Record=$record; Score=$score }
            continue
        }
        $duplicatesRemoved++
        $current = $groups[$key]
        if ($score -gt [int]$current.Score) {
            $groups[$key] = [pscustomobject]@{ Record=$record; Score=$score }
        }
    }

    $result = New-Object 'System.Collections.Generic.List[object]'
    foreach ($group in $groups.Values) { [void]$result.Add($group.Record) }
    if ($duplicatesRemoved -gt 0) {
        Write-AMRLog ("Show Installed duplicate cleanup: removed {0} duplicate inventory record(s); kept one uninstallable record per application identity." -f $duplicatesRemoved) INFO Software
    }
    return @($result.ToArray())
}

function Get-AMRInstalledCardShortName {
    param([string]$DisplayName,[string]$Publisher='')

    $name = (($DisplayName -replace '\s+',' ').Trim())
    if ([string]::IsNullOrWhiteSpace($name)) { return 'App' }
    $name = $name -replace '(?i)\s*\((?:x64|x86|64[- ]bit|32[- ]bit|arm64)\)\s*$',''

    # Preserve the product's meaningful release year, but discard architecture,
    # language, installer, build and marketing suffixes from the compact card.
    if ($name -match '(?i)^(?:Autodesk\s+)?AutoCAD\s*(20\d{2})?(?:\s*[-–|].*)?$') {
        if ($Matches[1]) { return ('AutoCAD ' + $Matches[1]) }
        return 'AutoCAD'
    }
    if ($name -match '(?i)^(?:Mozilla\s+)?Firefox(?:\s+(?:\d{2,4}|x64|x86|64[- ]bit|32[- ]bit))?(?:\s*[-–|].*)?$') { return 'Firefox' }
    if ($name -match '(?i)^WinRAR(?:\s+.*)?$') { return 'WinRAR' }

    $key = ($name -replace '[^a-zA-Z0-9]+','').ToLowerInvariant()
    $known = @{
        'microsoftedge'='Edge'; 'edgebrowser'='Edge'; 'microsoftonedrive'='OneDrive'; 'onedrive'='OneDrive'
        'internetdownloadmanager'='IDM'; 'idm'='IDM'; 'idman'='IDM'; 'vlcmediaplayer'='VLC'; 'videolanvlcmediaplayer'='VLC'; 'vlc'='VLC'
        'aimp'='AIMP'; 'aimp3'='AIMP'; 'aimp4'='AIMP'; 'teamviewer'='TeamViewer'; 'teamviewerfull'='TeamViewer'
        'anydesk'='AnyDesk'; 'itunes'='iTunes'; 'appleitunes'='iTunes'; 'googlechrome'='Chrome'; 'chrome'='Chrome'
        'mozillafirefox'='Firefox'; 'firefox'='Firefox'; 'operagx'='Opera GX'; 'opera'='Opera'
        'microsoftteams'='Teams'; 'msteams'='Teams'; 'microsoftoutlooknew'='Outlook'; 'outlooknew'='Outlook'
        'microsoftvisualstudiocode'='VS Code'; 'visualstudiocode'='VS Code'; 'microsoftvisualstudio'='Visual Studio'
        'microsoftpowerautomatedesktop'='Power Automate'; 'powerautomatedesktop'='Power Automate'
        'adobeacrobatreader'='Acrobat Reader'; 'adobeacrobatreaderdc'='Acrobat Reader'; 'adobephotoshop'='Photoshop'; 'adobeillustrator'='Illustrator'
        'autodeskrevit'='Revit'; 'autodeskautocad'='AutoCAD'; 'autodesknavisworks'='Navisworks'; 'autodeskinventor'='Inventor'
        'microsoftwindowscalculator'='Calculator'; 'microsoftwindowsterminal'='Terminal'; 'microsoftwindowsphotos'='Photos'; 'microsoftwindowsnotepad'='Notepad'
        'microsoftstore'='Store'; 'microsoftteamsclassic'='Teams'; 'googledrive'='Google Drive'; 'dropbox'='Dropbox'; 'sharex'='ShareX'
        'obsstudio'='OBS Studio'; 'obsprojectobsstudio'='OBS Studio'; 'handbrake'='HandBrake'; 'kdenlive'='Kdenlive'
        'discord'='Discord'; 'telegramdesktop'='Telegram'; 'whatsappdesktop'='WhatsApp'; 'spotify'='Spotify'; 'steam'='Steam'
        'epicgameslauncher'='Epic Games'; 'epicgames'='Epic Games'; 'winrar'='WinRAR'; '7zip'='7-Zip'
    }
    if ($known.ContainsKey($key)) { return [string]$known[$key] }

    $compact = $name
    # Remove vendor prefixes only when they are redundant for a known product.
    $compact = $compact -replace '(?i)^Microsoft\s+(?=(?:Edge|OneDrive|Teams|Outlook|Power Automate|Visual Studio|Windows Terminal|Windows Calculator|Windows Photos|Windows Notepad)\b)',''
    $compact = $compact -replace '(?i)^Google\s+(?=Chrome\b)',''
    $compact = $compact -replace '(?i)^Mozilla\s+(?=Firefox\b)',''
    $compact = $compact -replace '(?i)^Apple\s+(?=iTunes\b)',''
    $compact = $compact -replace '(?i)^Adobe\s+(?=Acrobat|Photoshop|Illustrator)',''
    $compact = $compact -replace '(?i)^Autodesk\s+(?=AutoCAD|Revit|Navisworks|Inventor|Maya|3ds\s*Max)',''
    $compact = $compact -replace '(?i)\s*\((?:x64|x86|64[- ]bit|32[- ]bit|arm64|English| en-us)\)\s*$',''
    $compact = $compact -replace '(?i)\s+(?:x64|x86|64[- ]bit|32[- ]bit|arm64)\s*$',''
    $compact = $compact -replace '(?i)\s+(?:English|English\s+US|en-US|Multilingual)\s*$',''
    $compact = $compact -replace '(?i)\s+(?:installer|setup|installation|update|updater|maintenance\s+service)\s*$',''
    $compact = $compact -replace '(?i)\s*[-–|]\s*(?:x64|x86|64[- ]bit|32[- ]bit|English|en-US|Stable|Release|Final).*$',''
    $compact = $compact -replace '(?i)\s*\((?:Community|Professional|Enterprise|Standard)\)\s*$',''
    $compact = $compact -replace '(?i)\s+(?:version|ver\.?|v)\s*\d+(?:\.\d+)*\s*$',''
    $compact = $compact -replace '(?i)\s+\d+(?:\.\d+){1,4}\s*$',''
    $compact = $compact -replace '(?i)\s+\d{2,4}\s*$',''
    $compact = ($compact -replace '\s{2,}',' ').Trim(' ','-','_',',')

    # Keep a meaningful four-digit product year; remove trailing numeric build/version noise.
    if ($compact -match '(?i)^(.*?\bAutoCAD)\s+(20\d{2})\b') { return (($Matches[1] + ' ' + $Matches[2]).Trim()) }
    if ($compact.Length -le 26) { return $compact }

    $words = @($compact -split '\s+' | Where-Object { $_ })
    $stop = @('the','for','with','and','edition','version','application','software','installer','setup','update')
    $kept = @($words | Where-Object { $stop -notcontains $_.ToLowerInvariant() })
    if ($kept.Count -ge 2) {
        $candidate = ($kept | Select-Object -First 3) -join ' '
        if ($candidate.Length -le 26) { return $candidate }
        $candidate = ($kept | Select-Object -First 2) -join ' '
        if ($candidate.Length -le 26) { return $candidate }
    }
    if ($kept.Count -ge 1) { return [string]$kept[0] }
    return ($compact.Substring(0,23).TrimEnd() + '…')
}

function Set-AMRInstalledAppPresentation {
    param([object[]]$Records)

    $eligibleCount = 0
    $appxConsumerAllowList = @(
        'Microsoft.WindowsCalculator','Microsoft.WindowsCamera','Microsoft.Windows.Photos',
        'Microsoft.WindowsNotepad','Microsoft.WindowsTerminal','Microsoft.WindowsAlarms',
        'Microsoft.WindowsSoundRecorder','Microsoft.YourPhone','Microsoft.WindowsStore',
        'Microsoft.ScreenSketch','Microsoft.GetHelp','Microsoft.Getstarted',
        'Microsoft.MicrosoftStickyNotes','Microsoft.Paint','Microsoft.WindowsMaps',
        'Microsoft.BingWeather','Microsoft.Todos','MSTeams','MicrosoftTeams',
        'Microsoft.OutlookForWindows','Microsoft.Windows.DevHome',
        'Microsoft.PowerAutomateDesktop','MicrosoftCorporationII.QuickAssist',
        'Microsoft.WindowsFeedbackHub','Microsoft.ZuneMusic','Microsoft.ZuneVideo'
    )
    $appxSystemPattern = '(?i)^(?:MicrosoftWindows\.|Microsoft\.Windows\.|Microsoft\.(?:AAD\.BrokerPlugin|AccountsControl|BioEnrollment|LockApp|SecHealthUI|Win32WebViewHost|VCLibs\.|NET\.Native\.|UI\.Xaml\.|Services\.Store\.))'
    $componentPattern = '(?i)(?:\bMicrosoft Visual C\+\+|\bVisual C\+\+|\bMicrosoft \.NET|\b\.NET (?:Runtime|Host|SDK)|\bASP\.NET Core|\bWindows (?:Desktop|App) Runtime|\bWebView2 Runtime|\bEdge WebView2|\bRedistributable\b|\bRuntime\b|\bDeveloper Pack\b|\bTargeting Pack\b|\bWindows SDK\b|\bDevice Driver\b|\bDriver Package\b|\bDriver Component\b|\b(?:Intel|NVIDIA|AMD|Realtek|Synaptics|ELAN).*?(?:Graphics|Audio|Bluetooth|Wireless|Ethernet|Touchpad|Card Reader) Driver\b|\bManagement Engine Components\b|\bFirmware\b|\bChipset\b|\bDevice Support\b|\bSystem Component\b|\bUpdate Health Tools\b|\bEdge Update\b|\bGoogle Update Helper\b|\bMozilla Maintenance Service\b|\bClick-to-Run Extensibility\b|\bLanguage Pack\b|\bLanguage Experience Pack\b|\bWindows Assessment and Deployment Kit\b|\bWindows Kits\b|\bHotfix for\b|^Update for\b|^Security Update for\b)'

    foreach ($record in @($Records)) {
        if ($null -eq $record) { continue }
        foreach ($property in @(
            @{Name='DisplayName';Value=[string]$record.Name},
            @{Name='IsUserFacing';Value=$false},
            @{Name='UserFacingReason';Value='Not evaluated'},
            @{Name='UserFacingScore';Value=0},
            @{Name='PackageNonRemovable';Value=$false}
        )) {
            if (-not $record.PSObject.Properties[$property.Name]) {
                $record | Add-Member -NotePropertyName $property.Name -NotePropertyValue $property.Value
            }
        }

        $displayName = Get-AMRInstalledPresentationName -Record $record
        $record.DisplayName = $displayName
        # Card text uses a product-aware short label; the full DisplayName and
        # original Name remain untouched for the details popup and uninstall logic.
        $cardName = Get-AMRInstalledCardShortName -DisplayName $displayName -Publisher ([string]$record.Publisher)
        if ($record.PSObject.Properties['CardDisplayName']) { $record.CardDisplayName = $cardName }
        else { $record | Add-Member -NotePropertyName CardDisplayName -NotePropertyValue $cardName }
        $record.Initials = (($displayName -split '\s+' | Where-Object { $_ } | Select-Object -First 2 | ForEach-Object { $_.Substring(0,1) }) -join '').ToUpperInvariant()
        $record.IsUserFacing = $false
        $record.UserFacingScore = 0
        $reason = ''

        if (-not [bool]$record.IsInstalled) {
            $reason = 'Windows inventory did not confirm this application as installed.'
        } elseif (-not [bool]$record.CanUninstall) {
            $reason = 'No supported uninstall action is available for this entry.'
        } elseif ([bool]$record.PackageNonRemovable) {
            $reason = 'Windows marks this AppX/MSIX package as non-removable.'
        } elseif ([string]$record.Name -match $componentPattern) {
            $reason = 'Runtime, driver, update, SDK, language, or shared system component; hidden from the user application list.'
        } elseif ([string]$record.Source -eq 'AppX/MSIX') {
            $appxName = [string]$record.Name
            if ($appxName -match $appxSystemPattern -and $appxConsumerAllowList -notcontains $appxName) {
                $reason = 'Windows inbox/system package rather than a standalone user application.'
            } else {
                $record.IsUserFacing = $true
                $record.UserFacingScore = 90
                $reason = 'Removable current-user application package; not classified as a Windows shared component.'
            }
        } elseif ([string]$record.Source -eq 'Portable candidate' -and -not [bool]$record.IsPortable) {
            $reason = 'Portable executable is not inside a managed application folder with a safe removal boundary.'
        } else {
            $record.IsUserFacing = $true
            $record.UserFacingScore = if ([string]$record.Source -eq 'Windows Registry') { 100 } else { 85 }
            $reason = 'Removable end-user application entry; retained regardless of publisher or installer source.'
        }

        $record.UserFacingReason = $reason
        if ($record.IsUserFacing) { $eligibleCount++ }
    }
    return [int]$eligibleCount
}

function Get-AMRUniversalInstalledInventory {
    [CmdletBinding()]
    param(
        [string]$WingetRawOutput = '',
        [switch]$SkipWingetScan
    )
    $records = New-Object 'System.Collections.Generic.List[object]'
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $readProperty = { param($object, [string]$propertyName) $property = $object.PSObject.Properties[$propertyName]; if ($property) { return $property.Value }; return $null }
    $registrySpecs = @(
        @{ Path='HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKLM'; View='64-bit' },
        @{ Path='HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKLM'; View='32-bit' },
        @{ Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKCU'; View='User' },
        @{ Path='HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Hive='HKCU'; View='User-32-bit' }
    )
    foreach ($spec in $registrySpecs) {
        try {
            foreach ($entry in @(Get-ItemProperty -Path $spec.Path -ErrorAction SilentlyContinue)) {
                $name = [string](& $readProperty $entry 'DisplayName')
                if ([string]::IsNullOrWhiteSpace($name)) { continue }
                $systemComponent = & $readProperty $entry 'SystemComponent'
                $releaseType = [string](& $readProperty $entry 'ReleaseType')
                $parentKeyName = [string](& $readProperty $entry 'ParentKeyName')
                $noDisplay = & $readProperty $entry 'NoDisplay'
                $protectedComponent = ($systemComponent -eq 1) -or (-not [string]::IsNullOrWhiteSpace($releaseType)) -or (-not [string]::IsNullOrWhiteSpace($parentKeyName)) -or ($noDisplay -eq 1)
                $keyPath = [string](& $readProperty $entry 'PSPath')
                if ([string]::IsNullOrWhiteSpace($keyPath)) { continue }
                $uninstall = [string](& $readProperty $entry 'UninstallString')
                $quiet = [string](& $readProperty $entry 'QuietUninstallString')
                $msiValue = & $readProperty $entry 'WindowsInstaller'
                $msi = $false; try { $msi = ([int]$msiValue -eq 1) } catch {}
                $hasCommand = $msi -or -not [string]::IsNullOrWhiteSpace($uninstall) -or -not [string]::IsNullOrWhiteSpace($quiet)
                $can = $hasCommand -and -not $protectedComponent
                $method = if ($msi) {'MSI'} elseif ($hasCommand) {'Registry'} else {''}
                $reason = if ($protectedComponent) {'Windows marks this as a system/hidden/parent component; automatic removal is blocked to protect shared dependencies.'} elseif ($can) {'Registered native uninstaller is available.'} else {'Windows has no registered uninstall command for this entry.'}
                $record = New-AMRInstalledInventoryRecord -Name $name -Publisher ([string](& $readProperty $entry 'Publisher')) -DisplayVersion ([string](& $readProperty $entry 'DisplayVersion')) -InstallDate ([string](& $readProperty $entry 'InstallDate')) -InstallLocation ([string](& $readProperty $entry 'InstallLocation')) -DisplayIcon ([string](& $readProperty $entry 'DisplayIcon')) -UninstallString $uninstall -QuietUninstallString $quiet -WindowsInstaller $msi -RegistryKeyPath $keyPath -RegistryHive $spec.Hive -RegistryView $spec.View -Source 'Windows Registry' -CanUninstall $can -UninstallMethod $method -UninstallReason $reason -IdentityKey ('REG:' + $keyPath.ToLowerInvariant())
                if ($seen.Add($record.IdentityKey)) { [void]$records.Add($record) }
            }
        } catch {}
    }

    # AppX/MSIX: current-user packages only. AllUsers staged registrations are not
    # represented as installed apps and must not be removed on behalf of other users.
    try {
        # Reuse the all-users list collected moments ago by Update-AMRInstalledCatalogState when it
        # carries per-user install state for every package; otherwise (or if no package is registered
        # for the current user in it) run the original current-user query exactly as before.
        $currentUserAppxPackages = $null
        $appxDiagSource = 'Get-AppxPackage (current user)'
        $appxDiagReason = 'no AllUsers snapshot was stored in this worker run'
        $appxDiagSnapshotCount = -1
        $appxDiagDerivedCount = -1
        $allUsersAppxVariable = Get-Variable -Name 'AMRAppxAllUsersSnapshot' -Scope Script -ErrorAction SilentlyContinue
        if ($allUsersAppxVariable -and $null -ne $allUsersAppxVariable.Value) {
            try { $appxDiagSnapshotCount = @($allUsersAppxVariable.Value).Count } catch {}
            try {
                $currentUserSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
                $derivedAppxPackages = New-Object 'System.Collections.Generic.List[object]'
                $canDeriveAppx = $true
                foreach ($candidatePackage in @($allUsersAppxVariable.Value)) {
                    $userInfoProperty = $candidatePackage.PSObject.Properties['PackageUserInformation']
                    if (-not $userInfoProperty -or $null -eq $userInfoProperty.Value) { $canDeriveAppx = $false; break }
                    foreach ($userInfo in @($userInfoProperty.Value)) {
                        if ([string]$userInfo.UserSecurityId.Sid -eq $currentUserSid -and [string]$userInfo.InstallState -eq 'Installed') {
                            [void]$derivedAppxPackages.Add($candidatePackage)
                            break
                        }
                    }
                }
                $appxDiagDerivedCount = $derivedAppxPackages.Count
                if ($canDeriveAppx -and $derivedAppxPackages.Count -gt 0) { $currentUserAppxPackages = @($derivedAppxPackages.ToArray()); $appxDiagSource = 'derived from the AllUsers snapshot'; $appxDiagReason = '' }
                elseif (-not $canDeriveAppx) { $appxDiagReason = 'a snapshot package had no PackageUserInformation, so the original query was used' }
                else { $appxDiagReason = 'no snapshot package was Installed for the current user SID, so the original query was used' }
            } catch { $currentUserAppxPackages = $null; try { $appxDiagReason = 'derivation threw ' + $_.Exception.GetType().FullName + ': ' + $_.Exception.Message } catch {} }
        }
        if ($null -eq $currentUserAppxPackages) { $currentUserAppxPackages = @(Get-AppxPackage -ErrorAction SilentlyContinue) }
        try { Write-AMRLog ('AppX current-user package list | Source={0} | Packages={1} | AllUsersSnapshotPackages={2} | DerivedPackages={3} | FallbackReason={4}' -f $appxDiagSource,@($currentUserAppxPackages).Count,$appxDiagSnapshotCount,$appxDiagDerivedCount,$(if ($appxDiagReason) { $appxDiagReason } else { 'none' })) INFO Software } catch {}
        foreach ($pkg in $currentUserAppxPackages) {
            if ([string]::IsNullOrWhiteSpace([string]$pkg.PackageFullName)) { continue }
            $appxFramework = & $readProperty $pkg 'IsFramework'
            $appxResource = & $readProperty $pkg 'IsResourcePackage'
            $appxBundle = & $readProperty $pkg 'IsBundle'
            $appxNonRemovable = & $readProperty $pkg 'NonRemovable'
            $appxProtected = [bool]$appxFramework -or [bool]$appxResource -or [bool]$appxBundle -or [bool]$appxNonRemovable
            $appxCanRemove = -not $appxProtected
            $appxReason = if ($appxProtected) {'Framework/resource/bundle/non-removable package is protected as a shared dependency.'} else {'Exact current-user AppX/MSIX package identity is available.'}
            $record = New-AMRInstalledInventoryRecord -Name ([string](& $readProperty $pkg 'Name')) -Publisher ([string](& $readProperty $pkg 'Publisher')) -DisplayVersion ([string](& $readProperty $pkg 'Version')) -AppxPackageFullName ([string](& $readProperty $pkg 'PackageFullName')) -PackageFamilyName ([string](& $readProperty $pkg 'PackageFamilyName')) -InstallLocation ([string](& $readProperty $pkg 'InstallLocation')) -Source 'AppX/MSIX' -CanUninstall $appxCanRemove -UninstallMethod 'AppX' -UninstallReason $appxReason -IdentityKey ('APPX:' + ([string]$pkg.PackageFullName).ToLowerInvariant())
            $record.PackageNonRemovable = [bool]$appxNonRemovable
            if ($seen.Add($record.IdentityKey)) { [void]$records.Add($record) }
        }
    } catch {}

    # WinGet, Chocolatey and Scoop are supplemental identity sources. Their records
    # are retained only when not already represented by a native uninstall identity.
    try {
        $lines = @()
        if ($SkipWingetScan) {
            if (-not [string]::IsNullOrWhiteSpace($WingetRawOutput)) {
                $lines = @($WingetRawOutput -split "`r?`n")
            }
        } else {
            $wg = Get-Command winget.exe -ErrorAction SilentlyContinue
            if ($wg) {
                $out = & $wg.Source list --disable-interactivity --accept-source-agreements 2>$null
                $lines = @($out | ForEach-Object { [string]$_ })
            }
        }
        if ($lines.Count -gt 0) {
            $header = -1; $idStart = -1; $verStart = -1
            for ($i=0; $i -lt $lines.Count; $i++) {
                $mi=[regex]::Match($lines[$i],'(?i)\bId\b'); $mv=[regex]::Match($lines[$i],'(?i)\bVersion\b')
                if ($mi.Success -and $mv.Success -and $mv.Index -gt $mi.Index) { $header=$i; $idStart=$mi.Index; $verStart=$mv.Index; break }
            }
            if ($header -ge 0) {
                for ($i=$header+1; $i -lt $lines.Count; $i++) {
                    $line=$lines[$i]; if ($line.Length -le $idStart) { continue }
                    $len=[Math]::Min(($verStart-$idStart),($line.Length-$idStart)); if ($len -le 0) { continue }
                    $id=$line.Substring($idStart,$len).Trim()
                    $wingetDisplayName = $line.Substring(0,$idStart).Trim()
                    if ([string]::IsNullOrWhiteSpace($wingetDisplayName)) { $wingetDisplayName = $id }
                    if ($id -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$') { continue }
                    $norm=($id -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                    $already=$false
                    foreach($r in $records){ if((([string]$r.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()) -eq $norm){$already=$true;break} }
                    if(-not $already){ $rec=New-AMRInstalledInventoryRecord -Name $wingetDisplayName -WingetId $id -Source 'WinGet' -CanUninstall $true -UninstallMethod 'WinGet' -UninstallReason 'Exact WinGet package ID was reported by winget list.' -IdentityKey ('WINGET:'+$id.ToLowerInvariant()) -Confidence 'Medium'; if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)} }
                }
            }
        }
    } catch {}
    $chocoRoots=@(); if($env:ChocolateyInstall){$chocoRoots+= $env:ChocolateyInstall}; if($env:ProgramData){$chocoRoots+= (Join-Path $env:ProgramData 'chocolatey')}
    foreach($root in @($chocoRoots | Select-Object -Unique)){
        $lib=Join-Path $root 'lib'; if(-not(Test-Path -LiteralPath $lib -PathType Container)){continue}
        foreach($folder in @(Get-ChildItem -LiteralPath $lib -Directory -ErrorAction SilentlyContinue)){
            if(@(Get-ChildItem -LiteralPath $folder.FullName -Filter '*.nuspec' -File -ErrorAction SilentlyContinue).Count -gt 0){
                $id=$folder.Name; $norm=($id -replace '[^a-zA-Z0-9]','').ToLowerInvariant(); $exists=$false
                foreach($r in $records){if((([string]$r.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()) -eq $norm){$exists=$true;break}}
                if(-not $exists){$rec=New-AMRInstalledInventoryRecord -Name $id -ChocoId $id -Source 'Chocolatey' -CanUninstall $true -UninstallMethod 'Chocolatey' -UninstallReason 'Exact local Chocolatey package folder and nuspec were found.' -IdentityKey ('CHOCO:'+$id.ToLowerInvariant()) -Confidence 'Medium'; if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)}}
            }
        }
    }
    $scoopRoots=@(); if($env:SCOOP){$scoopRoots+=$env:SCOOP}; if($env:SCOOP_GLOBAL){$scoopRoots+=$env:SCOOP_GLOBAL}; if($env:USERPROFILE){$scoopRoots+=(Join-Path $env:USERPROFILE 'scoop')}; if($env:ProgramData){$scoopRoots+=(Join-Path $env:ProgramData 'scoop')}
    foreach($root in @($scoopRoots | Select-Object -Unique)){
        $apps=Join-Path $root 'apps'; if(-not(Test-Path -LiteralPath $apps -PathType Container)){continue}
        foreach($folder in @(Get-ChildItem -LiteralPath $apps -Directory -ErrorAction SilentlyContinue)){
            $id=$folder.Name -replace '\\current$',''; $norm=($id -replace '[^a-zA-Z0-9]','').ToLowerInvariant(); $exists=$false
            foreach($r in $records){if((([string]$r.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()) -eq $norm){$exists=$true;break}}
            if(-not $exists){$rec=New-AMRInstalledInventoryRecord -Name $id -ScoopName $id -InstallLocation $folder.FullName -Source 'Scoop' -CanUninstall $true -UninstallMethod 'Scoop' -UninstallReason 'Exact Scoop app directory was found.' -IdentityKey ('SCOOP:'+$id.ToLowerInvariant()) -Confidence 'Medium'; if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)}}
        }
    }

    # Portable discovery is restricted to executables inside explicitly managed
    # PortableApps roots. Desktop and Start Menu shortcuts are intentionally not
    # treated as installed applications and never create Show Installed cards.
    $portableRoots=@(); if($env:USERPROFILE){$portableRoots+=(Join-Path $env:USERPROFILE 'PortableApps')}; if($env:ProgramData){$portableRoots+=(Join-Path $env:ProgramData 'PortableApps')}; $portableRoots+='C:\PortableApps'
    $targets=New-Object 'System.Collections.Generic.List[string]'
    foreach($root in @($portableRoots | Select-Object -Unique)){
        if(Test-Path -LiteralPath $root -PathType Container){foreach($exe in @(Get-ChildItem -LiteralPath $root -Filter '*.exe' -File -Recurse -ErrorAction SilentlyContinue)){[void]$targets.Add($exe.FullName)}}
    }
    $blocked=@('setup.exe','uninstall.exe','unins000.exe','update.exe','crashpad_handler.exe','vc_redist.x64.exe','vc_redist.x86.exe')
    foreach($target in @($targets | Select-Object -Unique)){
        try {
            $leaf=[IO.Path]::GetFileName($target); if($blocked -contains $leaf.ToLowerInvariant()){continue}
            $root=[IO.Path]::GetDirectoryName($target); $base=[IO.Path]::GetFileNameWithoutExtension($target)
            if($root -match '(?i)\\(Windows|System32|SysWOW64|Program Files|Program Files \(x86\))($|\\)'){continue}
            $managedPortable = $false; $portableAppRoot = $root
            foreach($allowedRoot in @($portableRoots | Select-Object -Unique)){
                try {
                    $allowedFull=[IO.Path]::GetFullPath($allowedRoot).TrimEnd('\')+'\'
                    $targetFull=[IO.Path]::GetFullPath($target)
                    if($targetFull.StartsWith($allowedFull,[StringComparison]::OrdinalIgnoreCase)){
                        $relative=$targetFull.Substring($allowedFull.Length); $firstPart=($relative -split '[\\/]')[0]
                        if(-not [string]::IsNullOrWhiteSpace($firstPart)){$portableAppRoot=Join-Path $allowedRoot $firstPart;if(Test-Path -LiteralPath $portableAppRoot -PathType Container){$managedPortable=$true;break}else{$portableAppRoot=$root}}
                    }
                } catch {}
            }
            $existing=$false; foreach($r in $records){if($r.InstallLocation -and ([string]$r.InstallLocation).TrimEnd('\') -ieq $portableAppRoot.TrimEnd('\')){$existing=$true;break}}
            if($existing){continue}
            $portableReason = if($managedPortable){'Exact application folder is inside a designated PortableApps root; removal is limited to this folder.'}else{'Portable executable found via shortcut or Downloads. Its containing folder is not a managed PortableApps root, so deletion is disabled.'}
            $rec=New-AMRInstalledInventoryRecord -Name $base -InstallLocation $portableAppRoot -Source 'Portable candidate' -CanUninstall $managedPortable -UninstallMethod $(if($managedPortable){'Portable'}else{''}) -UninstallReason $portableReason -PortableExecutablePath $target -PortableRootFolder $portableAppRoot -IsPortable $true -IdentityKey ('PORTABLE:'+$portableAppRoot.ToLowerInvariant()) -Confidence 'Low'
            if($seen.Add($rec.IdentityKey)){[void]$records.Add($rec)}
        } catch {}
    }
    $deduplicatedRecords = @(Remove-AMRDuplicateInstalledInventoryRecords -Records $records.ToArray())

    # Restore catalog categories for installed records. Registry display names often
    # include architecture/year/vendor text (e.g. Firefox 64, AutoCAD 2024); match
    # against the longest catalog product identity before applying conservative fallbacks.
    $catalogCategoryIndex = New-Object 'System.Collections.Generic.List[object]'
    foreach ($catalogItem in @($script:SoftwareCatalog)) {
        $catalogCategory = [string]$catalogItem.Category
        if ([string]::IsNullOrWhiteSpace($catalogCategory)) { continue }
        foreach ($catalogName in @([string]$catalogItem.Name, [string]$catalogItem.Id, [string]$catalogItem.ChocoId)) {
            if ([string]::IsNullOrWhiteSpace($catalogName)) { continue }
            $catalogKey = ($catalogName -split '\.')[-1]
            $catalogKey = ($catalogKey -replace '(?i)^(?:Microsoft|Mozilla|Google|Apple|Autodesk|VideoLAN|RARLab)[ ._-]+','')
            $catalogKey = ($catalogKey -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
            if ($catalogKey.Length -ge 3) {
                [void]$catalogCategoryIndex.Add([pscustomobject]@{ Key=$catalogKey; Category=$catalogCategory })
            }
        }
    }
    foreach ($record in $deduplicatedRecords) {
        $recordKey = ([string]$record.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
        $recordKey = $recordKey -replace '(?i)^(?:microsoft|mozilla|google|apple|autodesk|videolan|rar lab)',''
        $recordKey = $recordKey -replace '(?:32|64)$',''
        $recordKey = $recordKey -replace '(?:19|20)\d{2}$',''
        $bestCategory = $null
        $bestLength = 0
        foreach ($candidate in $catalogCategoryIndex) {
            if ($recordKey -eq $candidate.Key -or ($recordKey.StartsWith($candidate.Key) -and $recordKey.Length -le ($candidate.Key.Length + 6))) {
                if ($candidate.Key.Length -gt $bestLength) {
                    $bestCategory = [string]$candidate.Category
                    $bestLength = [int]$candidate.Key.Length
                }
            }
        }
        if ([string]::IsNullOrWhiteSpace($bestCategory)) {
            if ($recordKey -match '^(?:firefox|chrome|edge|brave|opera|vivaldi|torbrowser|chromium|waterfox|librewolf)') { $bestCategory = '01. Web Browsers' }
            elseif ($recordKey -match '^(?:winrar|7zip|peazip|nanazip|bandizip|winzip|izarc|bzip2|zstandard|tar)') { $bestCategory = '04. Compression' }
        }
        if ($bestCategory) { $record.Category = $bestCategory }
    }

    $visibleCount = Set-AMRInstalledAppPresentation -Records $deduplicatedRecords
    Write-AMRLog ("Show Installed curation: {0} removable user-facing application(s) retained from {1} unique inventory record(s) ({2} raw record(s) scanned)." -f $visibleCount,$deduplicatedRecords.Count,$records.Count) INFO Software
    return @($deduplicatedRecords | Sort-Object DisplayName,Name)
}

function Set-AMRInstalledCatalogMatches {
    param(
        [object[]]$Catalog,
        [object]$InstalledIdentities,
        [object]$WingetIdentities,
        [object]$ChocoIdentities,
        [object]$ScoopIdentities,
        [string]$WingetRawOutput
    )

    # Canonical aliases for known catalog/installer naming differences.
    $identityAliases = @{
        'everythingsearch' = @('everything')
        'visualstudiocode' = @('vscode','microsoftvisualstudiocode')
        'microsoftedgewebview2runtime' = @('webview2runtime','microsoftedgewebview2')
        'googlechrome' = @('chrome')
        'microsoftedge' = @('edge')
        'discord' = @('discord')
        '7zip' = @('7zip')
        'vlcmediaplayer' = @('vlc')
        'sumatrapdf' = @('sumatrapdf')
        'sharex' = @('sharex')
    }

    $installedCount = 0
    foreach ($app in $Catalog) {
        $isInstalled = $false
        $candidateIdentities = New-Object 'System.Collections.Generic.List[string]'
        foreach ($identity in @([string]$app.Name, [string]$app.Id, [string]$app.ChocoId)) {
            if ([string]::IsNullOrWhiteSpace($identity)) { continue }
            $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
            if ($normalized.Length -ge 3 -and -not $candidateIdentities.Contains($normalized)) { $candidateIdentities.Add($normalized) }
        }

        # The final segment of a package ID often matches its Windows display name
        # (for example, Vendor.ProductName vs. Product Name).
        if (-not [string]::IsNullOrWhiteSpace([string]$app.Id) -and [string]$app.Id -match '\.') {
            $idSuffix = ([string]$app.Id -split '\.')[-1]
            $normalizedSuffix = ($idSuffix -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
            if ($normalizedSuffix.Length -ge 3 -and -not $candidateIdentities.Contains($normalizedSuffix)) { $candidateIdentities.Add($normalizedSuffix) }
        }

        foreach ($baseIdentity in @($candidateIdentities.ToArray())) {
            if ($identityAliases.ContainsKey($baseIdentity)) {
                foreach ($alias in $identityAliases[$baseIdentity]) {
                    $normalizedAlias = ($alias -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                    if ($normalizedAlias.Length -ge 3 -and -not $candidateIdentities.Contains($normalizedAlias)) { $candidateIdentities.Add($normalizedAlias) }
                }
            }
        }

        # Strong package-manager evidence: exact WinGet package ID, Chocolatey ID,
        # or Scoop app-folder identity.
        $normalizedCatalogId = ([string]$app.Id -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
        $normalizedChocoId = ([string]$app.ChocoId -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
        if ($normalizedCatalogId.Length -ge 3 -and $wingetIdentities.Contains($normalizedCatalogId)) { $isInstalled = $true }
        if (-not $isInstalled -and $normalizedChocoId.Length -ge 3 -and $chocoIdentities.Contains($normalizedChocoId)) { $isInstalled = $true }
        if (-not $isInstalled) {
            foreach ($candidate in $candidateIdentities) {
                if ($scoopIdentities.Contains($candidate)) { $isInstalled = $true; break }
            }
        }

        # Windows registry and AppX identities, using exact normalized matches first.
        if (-not $isInstalled) {
            foreach ($normalized in $candidateIdentities) {
                if ($installedIdentities.Contains($normalized)) { $isInstalled = $true; break }
                # Accept only a version/architecture suffix after a complete known identity.
                foreach ($observed in $installedIdentities) {
                    if ($observed.Length -gt $normalized.Length -and $observed.StartsWith($normalized, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $suffix = $observed.Substring($normalized.Length)
                        if ($suffix -match '^\d+(x64|x86|64bit|32bit)?$') { $isInstalled = $true; break }
                    }
                }
                if ($isInstalled) { break }
            }
        }

        # Fallback for WinGet CLI versions whose table headings/layout differ.
        if (-not $isInstalled -and -not [string]::IsNullOrWhiteSpace($wingetRawOutput) -and -not [string]::IsNullOrWhiteSpace([string]$app.Id)) {
            $escapedId = [regex]::Escape([string]$app.Id)
            if ($wingetRawOutput -match ('(?im)(?<![A-Za-z0-9_.-])' + $escapedId + '(?![A-Za-z0-9_.-])')) { $isInstalled = $true }
        }

        $app.IsInstalled = $isInstalled
        if ($isInstalled) { $installedCount++ }
    }

    return $installedCount
}

function Update-AMRInstalledCatalogState {
    # Build a multi-source local inventory once, then match it against the catalog.
    # Evidence sources: Windows uninstall registry, AppX/MSIX, WinGet, Chocolatey and Scoop.
    # Provisioned AppX packages are intentionally excluded: provisioned does not mean installed.
    $installedIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $wingetIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $chocoIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $scoopIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

    # 1. Windows uninstall inventory: machine/user and 64-bit/32-bit registry locations.
    $registryEntryCount = 0
    $uninstallPaths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($registryPath in $uninstallPaths) {
        try {
            foreach ($entry in @(Get-ItemProperty -Path $registryPath -ErrorAction SilentlyContinue)) {
                $displayNameProperty = $entry.PSObject.Properties['DisplayName']
                $childNameProperty = $entry.PSObject.Properties['PSChildName']
                $displayNameValue = if ($displayNameProperty -and $null -ne $displayNameProperty.Value) { [string]$displayNameProperty.Value } else { '' }
                $childNameValue = if ($childNameProperty -and $null -ne $childNameProperty.Value) { [string]$childNameProperty.Value } else { '' }
                if (-not [string]::IsNullOrWhiteSpace($displayNameValue)) { $registryEntryCount++ }
                foreach ($identity in @($displayNameValue, $childNameValue)) {
                    if (-not [string]::IsNullOrWhiteSpace($identity)) {
                        $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                        if ($normalized.Length -ge 3) { [void]$installedIdentities.Add($normalized) }
                    }
                }
            }
        } catch {
            Write-AMRLog "Could not read installed software inventory from '$registryPath': $($_.Exception.Message)" WARNING Software
        }
    }

    # 2. AppX/MSIX packages installed for the current user or any user on this PC.
    $appxPackageCount = 0
    try {
        $appxPackages = @(Get-AppxPackage -AllUsers -ErrorAction Stop)
        # Kept for Get-AMRUniversalInstalledInventory in the same worker run, which needs the
        # current-user subset of this same list instead of a second Get-AppxPackage call.
        $script:AMRAppxAllUsersSnapshot = $appxPackages
        try {
            $appxSnapshotWithUserInfo = 0
            foreach ($appxSnapshotPackage in $appxPackages) {
                $appxSnapshotUserInfo = $appxSnapshotPackage.PSObject.Properties['PackageUserInformation']
                if ($appxSnapshotUserInfo -and $null -ne $appxSnapshotUserInfo.Value) { $appxSnapshotWithUserInfo++ }
            }
            Write-AMRLog ('AppX AllUsers snapshot stored | Packages={0} | WithPackageUserInformation={1}' -f @($appxPackages).Count,$appxSnapshotWithUserInfo) INFO Software
        } catch {}
    } catch {
        Write-AMRLog "All-user AppX inventory was unavailable; falling back to the current user: $($_.Exception.Message)" WARNING Software
        try { Write-AMRLog ('AppX AllUsers query failed | ExceptionType={0} | Line={1}' -f $_.Exception.GetType().FullName,[string]$_.InvocationInfo.ScriptLineNumber) WARNING Software } catch {}
        try { $appxPackages = @(Get-AppxPackage -ErrorAction SilentlyContinue) } catch { $appxPackages = @() }
    }
    foreach ($package in $appxPackages) {
        # When Windows exposes per-user package states, count only packages registered
        # as Installed for at least one user; do not count packages merely Staged.
        $userInfoProperty = $package.PSObject.Properties['PackageUserInformation']
        if ($userInfoProperty -and $null -ne $userInfoProperty.Value) {
            $hasInstalledUser = $false
            foreach ($userInfo in @($userInfoProperty.Value)) {
                if ([string]$userInfo.InstallState -eq 'Installed') { $hasInstalledUser = $true; break }
            }
            if (-not $hasInstalledUser) { continue }
        }
        $appxPackageCount++
        foreach ($identity in @([string]$package.Name, [string]$package.PackageFamilyName, [string]$package.PackageFullName)) {
            if (-not [string]::IsNullOrWhiteSpace($identity)) {
                $normalized = ($identity -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                if ($normalized.Length -ge 3) { [void]$installedIdentities.Add($normalized) }
            }
        }
    }

    # 3. WinGet's own installed-package inventory. Parse only the ID column when possible;
    # the exact-ID fallback handles CLI table-layout differences without loose name matching.
    $wingetRawOutput = ''
    $wingetAvailable = $false
    try {
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if ($winget) {
            $wingetAvailable = $true
            $wingetToken = [guid]::NewGuid().ToString('N')
            $wingetStdoutPath = Join-Path $env:TEMP ("AMR_ShowInstalled_{0}.out" -f $wingetToken)
            $wingetStderrPath = Join-Path $env:TEMP ("AMR_ShowInstalled_{0}.err" -f $wingetToken)
            $wingetProcess = $null
            $wingetExitCode = -1
            try {
                $wingetProcess = Start-Process -FilePath $winget.Source -ArgumentList 'list --disable-interactivity --accept-source-agreements' -PassThru -WindowStyle Hidden -RedirectStandardOutput $wingetStdoutPath -RedirectStandardError $wingetStderrPath -ErrorAction Stop
                if (-not $wingetProcess.WaitForExit(15000)) {
                    try { Stop-Process -Id $wingetProcess.Id -Force -ErrorAction SilentlyContinue } catch {}
                    throw 'WinGet installed-package inventory timed out after 15 seconds.'
                }
                $wingetProcess.WaitForExit()
                $wingetExitCode = [int]$wingetProcess.ExitCode
                $wingetStdout = if (Test-Path -LiteralPath $wingetStdoutPath) { [string](Get-Content -LiteralPath $wingetStdoutPath -Raw -ErrorAction SilentlyContinue) } else { '' }
                $wingetStderr = if (Test-Path -LiteralPath $wingetStderrPath) { [string](Get-Content -LiteralPath $wingetStderrPath -Raw -ErrorAction SilentlyContinue) } else { '' }
                $wingetRawOutput = $wingetStdout
                $wingetOutput = @($wingetStdout -split "`r?`n")
            } finally {
                if ($wingetProcess) { try { $wingetProcess.Dispose() } catch {} }
                foreach ($tempOutput in @($wingetStdoutPath,$wingetStderrPath)) {
                    if (Test-Path -LiteralPath $tempOutput) { Remove-Item -LiteralPath $tempOutput -Force -ErrorAction SilentlyContinue }
                }
            }
            if ($wingetExitCode -eq 0) {
                $headerIndex = -1
                $idColumnStart = -1
                $versionColumnStart = -1
                for ($lineIndex = 0; $lineIndex -lt $wingetOutput.Count; $lineIndex++) {
                    $lineText = [string]$wingetOutput[$lineIndex]
                    $idHeader = [regex]::Match($lineText, '(?i)\bId\b')
                    $versionHeader = [regex]::Match($lineText, '(?i)\bVersion\b')
                    if ($idHeader.Success -and $versionHeader.Success -and $versionHeader.Index -gt $idHeader.Index) {
                        $headerIndex = $lineIndex
                        $idColumnStart = $idHeader.Index
                        $versionColumnStart = $versionHeader.Index
                        break
                    }
                }
                if ($headerIndex -ge 0) {
                    for ($lineIndex = ($headerIndex + 1); $lineIndex -lt $wingetOutput.Count; $lineIndex++) {
                        $lineText = [string]$wingetOutput[$lineIndex]
                        if ($lineText.Length -le $idColumnStart) { continue }
                        $fieldLength = [Math]::Min(($versionColumnStart - $idColumnStart), ($lineText.Length - $idColumnStart))
                        if ($fieldLength -le 0) { continue }
                        $packageId = $lineText.Substring($idColumnStart, $fieldLength).Trim()
                        if ($packageId -match '^[A-Za-z0-9][A-Za-z0-9._-]*$') {
                            $normalizedId = ($packageId -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                            if ($normalizedId.Length -ge 3) { [void]$wingetIdentities.Add($normalizedId) }
                        }
                    }
                }
            } else {
                Write-AMRLog ("WinGet installed-package inventory returned exit code {0}; registry/AppX detection will still be used. {1}" -f $wingetExitCode,$wingetStderr) WARNING Software
            }
        }
    } catch {
        Write-AMRLog "Could not read WinGet installed-package inventory: $($_.Exception.Message)" WARNING Software
    }

    # 4. Chocolatey local package folders are authoritative for Chocolatey-managed installs.
    $chocoRoots = @()
    if (-not [string]::IsNullOrWhiteSpace($env:ChocolateyInstall)) { $chocoRoots += $env:ChocolateyInstall }
    $chocoRoots += (Join-Path $env:ProgramData 'chocolatey')
    foreach ($chocoRoot in @($chocoRoots | Select-Object -Unique)) {
        $chocoLib = Join-Path $chocoRoot 'lib'
        if (-not (Test-Path -LiteralPath $chocoLib -PathType Container)) { continue }
        try {
            foreach ($packageFolder in @(Get-ChildItem -LiteralPath $chocoLib -Directory -ErrorAction SilentlyContinue)) {
                $nuspecFiles = @(Get-ChildItem -LiteralPath $packageFolder.FullName -Filter '*.nuspec' -File -ErrorAction SilentlyContinue)
                if ($nuspecFiles.Count -gt 0) {
                    $normalizedFolder = ($packageFolder.Name -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                    if ($normalizedFolder.Length -ge 3) { [void]$chocoIdentities.Add($normalizedFolder) }
                }
            }
        } catch {
            Write-AMRLog "Could not read Chocolatey package inventory at '$chocoLib': $($_.Exception.Message)" WARNING Software
        }
    }

    # 5. Scoop app folders (user and global installations).
    $scoopRoots = @()
    if (-not [string]::IsNullOrWhiteSpace($env:SCOOP)) { $scoopRoots += $env:SCOOP }
    if (-not [string]::IsNullOrWhiteSpace($env:SCOOP_GLOBAL)) { $scoopRoots += $env:SCOOP_GLOBAL }
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) { $scoopRoots += (Join-Path $env:USERPROFILE 'scoop') }
    if (-not [string]::IsNullOrWhiteSpace($env:ProgramData)) { $scoopRoots += (Join-Path $env:ProgramData 'scoop') }
    foreach ($scoopRoot in @($scoopRoots | Select-Object -Unique)) {
        $appsPath = Join-Path $scoopRoot 'apps'
        if (-not (Test-Path -LiteralPath $appsPath -PathType Container)) { continue }
        try {
            foreach ($appFolder in @(Get-ChildItem -LiteralPath $appsPath -Directory -ErrorAction SilentlyContinue)) {
                $normalizedFolder = ($appFolder.Name -replace '[^a-zA-Z0-9]', '').ToLowerInvariant()
                if ($normalizedFolder.Length -ge 3) { [void]$scoopIdentities.Add($normalizedFolder) }
            }
        } catch {
            Write-AMRLog "Could not read Scoop package inventory at '$appsPath': $($_.Exception.Message)" WARNING Software
        }
    }

    $installedCount = Set-AMRInstalledCatalogMatches `
        -Catalog $script:SoftwareCatalog `
        -InstalledIdentities $installedIdentities `
        -WingetIdentities $wingetIdentities `
        -ChocoIdentities $chocoIdentities `
        -ScoopIdentities $scoopIdentities `
        -WingetRawOutput $wingetRawOutput

    Write-AMRLog ("Installed inventory scanned: {0} registry entries, {1} AppX/MSIX packages, {2} WinGet IDs, {3} Chocolatey packages, {4} Scoop apps. Catalog matches: {5}." -f $registryEntryCount,$appxPackageCount,$wingetIdentities.Count,$chocoIdentities.Count,$scoopIdentities.Count,$installedCount) INFO Software
    return [pscustomobject]@{
        Count = [int]$installedCount
        WingetRawOutput = [string]$wingetRawOutput
    }
}


# ----------------------------------------------------------
# Background installed-inventory scanner
# The inventory scan runs in a dedicated runspace. Only the
# final IsInstalled flags are copied back on the WPF UI thread.
# ----------------------------------------------------------
$script:StartupManagerEntries = @()

$script:InstalledScanState = @{
    Current = $null
    Inventory = @()
    Ready = $false
    Count = 0
    Error = ''
    PendingShow = $false
    RescanRequested = $false
    CacheLoaded = $false
}
$script:InstalledCacheSignature = ''
$script:InstalledCacheSavedUtc = [DateTime]::MinValue
$script:InstalledScanSignatureAtStart = ''
# A1: the light change check (every 10 min, on window activation and on entry) replaces the old 12 h age rule; this long limit is only a safety net.
$script:InstalledCacheMaxAgeHours = 100

# Persistent snapshot: the last completed inventory is loaded immediately on the
# next launch, while a fresh scan refreshes it in the background.
$script:InstalledInventoryCacheDir = Join-Path $script:AppRoot 'Cache'
$script:InstalledInventoryCacheFile = Join-Path $script:InstalledInventoryCacheDir 'InstalledInventoryCache.json'
try { New-Item -ItemType Directory -Force -Path $script:InstalledInventoryCacheDir | Out-Null } catch {}

function Get-AMRInstalledCatalogFingerprint {
    try {
        $catalogIds = @($script:SoftwareCatalog | ForEach-Object { [string]$_.Id }) -join "`n"
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($catalogIds)
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() }
        finally { $sha.Dispose() }
    } catch { return '' }
}

function Import-AMRInstalledInventoryCache {
    param([switch]$Quiet)
    $cachePath = [string]$script:InstalledInventoryCacheFile
    # A1: the JSON read + parse + per-record fixups ran in a worker started at the top of the script; the UI only validates and applies.
    $prefetched = $null
    $prefetchJob = $script:AMRInstalledCachePrefetchJob
    $script:AMRInstalledCachePrefetchJob = $null
    if ($null -ne $prefetchJob) {
        $perfIc = Get-AMRPerfNow
        $pf = Complete-AMRStartupPrefetchWorker -Job $prefetchJob -WaitMs 20000
        Add-AMRPerfSince 'installed.cacheImport.prefetchWait' $perfIc
        if ($pf.Ok -and @($pf.Items).Count -gt 0) {
            $pfFirst = @($pf.Items)[0]
            if ($pfFirst -and $pfFirst.PSObject.Properties['Status']) { $prefetched = $pfFirst }
        }
        try { Write-AMRLog ('Installed cache prefetch: status={0}; read {1} ms, parse {2} ms, fixups {3} ms in the worker; waited {4} ms on the UI thread.' -f $(if ($prefetched) { $prefetched.Status } else { 'unavailable' }),$(if ($prefetched) { $prefetched.ReadMs } else { 0 }),$(if ($prefetched) { $prefetched.ParseMs } else { 0 }),$(if ($prefetched) { $prefetched.FixupMs } else { 0 }),$pf.WaitedMs) INFO Software } catch {}
    }
    if ($null -ne $prefetched -and [string]$prefetched.Status -eq 'missing') { return $false }
    $usePrefetched = ($null -ne $prefetched -and [string]$prefetched.Status -eq 'ok')
    if (-not $usePrefetched) {
        if (-not (Test-Path -LiteralPath $cachePath -PathType Leaf)) { return $false }
    }
    try {
        $perfIc = Get-AMRPerfNow
        $fixupDone = $false
        if ($usePrefetched) {
            $cache = $prefetched.Cache
            $fixupDone = [bool]$prefetched.FixupDone
        } else {
            $cache = Get-Content -LiteralPath $cachePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        }
        Add-AMRPerfSince 'installed.cacheImport.readJson' $perfIc
        $perfIc = Get-AMRPerfNow
        if ([int]$cache.SchemaVersion -ne 1) { return $false }
        $fingerprint = Get-AMRInstalledCatalogFingerprint
        if ([string]::IsNullOrWhiteSpace($fingerprint) -or [string]$cache.CatalogFingerprint -ne $fingerprint) { return $false }
        $flags = @($cache.InstalledFlags)
        if ($flags.Count -ne $script:SoftwareCatalog.Count) { return $false }
        $records = @($cache.Inventory)
        if ($records.Count -gt 20000) { return $false }
        for ($index = 0; $index -lt $script:SoftwareCatalog.Count; $index++) {
            $script:SoftwareCatalog[$index].IsInstalled = [bool]$flags[$index]
        }
        if (-not $fixupDone) {
        foreach ($record in $records) {
            if (-not $record.PSObject.Properties['Icon']) { $record | Add-Member -NotePropertyName Icon -NotePropertyValue $null }
            else { $record.Icon = $null }
            if (-not $record.PSObject.Properties['IsUniversalInventory']) { $record | Add-Member -NotePropertyName IsUniversalInventory -NotePropertyValue $true } else { $record.IsUniversalInventory = $true }
            if (-not $record.PSObject.Properties['DetailsExpanded']) { $record | Add-Member -NotePropertyName DetailsExpanded -NotePropertyValue $false } else { $record.DetailsExpanded = $false }
            if (-not $record.PSObject.Properties['Category']) { $record | Add-Member -NotePropertyName Category -NotePropertyValue '' }
        }
        }
        Add-AMRPerfSince 'installed.cacheImport.flagsAndRecordFixup' $perfIc
        $perfIc = Get-AMRPerfNow
        $records = @(Remove-AMRDuplicateInstalledInventoryRecords -Records $records)
        Add-AMRPerfSince 'installed.cacheImport.dedupe' $perfIc
        $perfIc = Get-AMRPerfNow
        $visibleCount = Set-AMRInstalledAppPresentation -Records $records
        Add-AMRPerfSince 'installed.cacheImport.presentation' $perfIc
        $script:InstalledScanState.Inventory = @($records)
        $script:InstalledScanState.Count = [int]$visibleCount
        $script:InstalledScanState.Ready = $true
        $script:InstalledScanState.CacheLoaded = $true
        try {
            if ($cache.PSObject.Properties['ChangeSignature']) { $script:InstalledCacheSignature = [string]$cache.ChangeSignature }
            if ($cache.PSObject.Properties['SavedAtUtc']) { $script:InstalledCacheSavedUtc = [DateTime]::Parse([string]$cache.SavedAtUtc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() }
        } catch { $script:InstalledCacheSignature = ''; $script:InstalledCacheSavedUtc = [DateTime]::MinValue }
        if (-not $Quiet) {
            Write-AMRLog ("Loaded cached installed-app snapshot: {0} total record(s), {1} removable user-facing app(s). A background refresh has been scheduled." -f $records.Count,$visibleCount) INFO Software
        }
        return $true
    } catch {
        if (-not $Quiet) { Write-AMRLog "Installed-app cache could not be loaded and will be rebuilt: $($_.Exception.Message)" WARNING Software }
        return $false
    }
}

function Get-AMRInstalledChangeSignature {
    # Cheap change detector for the installed-app catalog (no process launch, no AppX/winget call).
    # Hashes the NAMES of the entries that appear/disappear when an app is installed or removed:
    # the four Uninstall registry views, the per-user and machine AppX package registrations,
    # and the Chocolatey / Scoop package folders. Missing keys simply contribute nothing.
    try {
        $sb = New-Object System.Text.StringBuilder
        $regSources = @(
            @('LM','Software\Microsoft\Windows\CurrentVersion\Uninstall'),
            @('LM','Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall'),
            @('CU','Software\Microsoft\Windows\CurrentVersion\Uninstall'),
            @('CU','Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall'),
            @('CU','Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\Repository\Packages'),
            @('LM','Software\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\Applications')
        )
        foreach ($src in $regSources) {
            $names = @()
            try {
                $root = if ($src[0] -eq 'LM') { [Microsoft.Win32.Registry]::LocalMachine } else { [Microsoft.Win32.Registry]::CurrentUser }
                $key = $root.OpenSubKey([string]$src[1])
                if ($key) { try { $names = @($key.GetSubKeyNames()) } finally { $key.Close() } }
            } catch { $names = @() }
            if ([string]$src[1] -match 'AppModel\\Repository\\Packages$' -or [string]$src[1] -match 'AppxAllUserStore\\Applications$') {
                # A1: an AppX/MSIX package name embeds its version (Name_Version_Arch__Publisher). Drop the version so a Store app UPDATE
                # (new version, same app) is not treated as an install/uninstall; a real install or removal still changes the name set.
                try { $names = @($names | ForEach-Object { [regex]::Replace([string]$_,'^([^_]+)_[^_]+_','$1_') } | Sort-Object -Unique) } catch { }
            }
            [void]$sb.Append('R|').Append([string]$src[0]).Append('|').Append([string]$src[1]).Append('|').Append($names.Count).Append("`n")
            foreach ($n in ($names | Sort-Object)) { [void]$sb.Append($n).Append("`n") }
        }
        $dirs = New-Object 'System.Collections.Generic.List[string]'
        if ($env:ChocolateyInstall) { $dirs.Add((Join-Path $env:ChocolateyInstall 'lib')) }
        if ($env:ProgramData) { $dirs.Add((Join-Path $env:ProgramData 'chocolatey\lib')) }
        if ($env:SCOOP) { $dirs.Add((Join-Path $env:SCOOP 'apps')) }
        if ($env:USERPROFILE) { $dirs.Add((Join-Path $env:USERPROFILE 'scoop\apps')) }
        foreach ($d in ($dirs | Select-Object -Unique)) {
            $names = @()
            try { if ([System.IO.Directory]::Exists($d)) { $names = @([System.IO.Directory]::GetDirectories($d) | ForEach-Object { [System.IO.Path]::GetFileName($_) }) } } catch { $names = @() }
            [void]$sb.Append('D|').Append($d).Append('|').Append($names.Count).Append("`n")
            foreach ($n in ($names | Sort-Object)) { [void]$sb.Append($n).Append("`n") }
        }
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($sb.ToString())
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() }
        finally { $sha.Dispose() }
    } catch { return '' }
}

function Test-AMRInstalledRefreshNeeded {
    # True when the persisted catalog may be out of date and a full scan is justified.
    # False when the saved catalog is valid, younger than the age limit, and nothing was installed/removed.
    param([string]$Context = '')
    $perf = Get-AMRPerfNow
    $needed = $true; $reason = 'no-saved-catalog'
    try {
        if ($script:InstalledScanState.CacheLoaded -and $script:InstalledScanState.Ready) {
            if ([string]::IsNullOrWhiteSpace([string]$script:InstalledCacheSignature)) { $reason = 'no-saved-signature' }
            elseif (([DateTime]::UtcNow - [DateTime]$script:InstalledCacheSavedUtc).TotalHours -ge [double]$script:InstalledCacheMaxAgeHours -or ([DateTime]::UtcNow - [DateTime]$script:InstalledCacheSavedUtc).TotalHours -lt 0) { $reason = 'older-than-limit' }
            else {
                $current = Get-AMRInstalledChangeSignature
                if ([string]::IsNullOrWhiteSpace($current)) { $reason = 'signature-unavailable' }
                elseif ($current -ne [string]$script:InstalledCacheSignature) { $reason = 'apps-changed' }
                else { $needed = $false; $reason = 'unchanged' }
            }
        }
    } catch { $needed = $true; $reason = 'check-failed' }
    Add-AMRPerfSince 'installed.changeCheck' $perf
    Write-AMRLog ('Installed catalog check ({0}): refresh={1}; reason={2}.' -f $Context,$needed,$reason) INFO Software
    return $needed
}

# A1: the cache write (copy of every record, ConvertTo-Json, file write) ran on the UI thread (656 ms and 360 ms stalls right after a scan in the A24 log).
# It now runs in a worker; the UI only builds a small request (fingerprint, flags, record references).
$script:AMRInstalledCacheSaveWorkerText = @'
param([string]$Path,[string]$Fingerprint,[string]$SavedAtUtc,[string]$Signature,[int]$Count,[object[]]$Flags,[object[]]$Inventory)
$ErrorActionPreference = 'Stop'
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$temporaryPath = $Path + '.tmp'
try {
    $snapshot = $null
    for ($attempt = 0; $attempt -lt 3 -and $null -eq $snapshot; $attempt++) {
        try { $snapshot = @($Inventory | ForEach-Object { $_ | Select-Object * -ExcludeProperty Icon }) }
        catch { Start-Sleep -Milliseconds 40 }
    }
    if ($null -eq $snapshot) { throw 'Could not copy the installed inventory records.' }
    $snapshotMs = $watch.ElapsedMilliseconds
    $payload = [ordered]@{
        SchemaVersion = 1
        CatalogFingerprint = $Fingerprint
        SavedAtUtc = $SavedAtUtc
        ChangeSignature = $Signature
        Count = $Count
        InstalledFlags = $Flags
        Inventory = $snapshot
    }
    $json = ConvertTo-Json -InputObject $payload -Depth 7
    $jsonMs = $watch.ElapsedMilliseconds - $snapshotMs
    Set-Content -LiteralPath $temporaryPath -Value $json -Encoding UTF8 -ErrorAction Stop
    Move-Item -LiteralPath $temporaryPath -Destination $Path -Force -ErrorAction Stop
    [pscustomobject]@{ Ok = $true; Error = ''; SnapshotMs = $snapshotMs; JsonMs = $jsonMs; TotalMs = $watch.ElapsedMilliseconds; Chars = $json.Length }
} catch {
    try { if ([System.IO.File]::Exists($temporaryPath)) { [System.IO.File]::Delete($temporaryPath) } } catch {}
    [pscustomobject]@{ Ok = $false; Error = $_.Exception.Message; SnapshotMs = 0; JsonMs = 0; TotalMs = $watch.ElapsedMilliseconds; Chars = 0 }
}
'@
$script:AMRInstalledCacheSaveState = @{ Job = $null; Timer = $null; Pending = $null; NewSignature = ''; PrevSignature = ''; PrevSavedUtc = [DateTime]::MinValue }

function Start-AMRInstalledCacheSaveWorker {
    param($Request)
    $saveState = $script:AMRInstalledCacheSaveState
    $runspace = $null; $ps = $null
    try {
        $saveState.PrevSignature = [string]$script:InstalledCacheSignature
        $saveState.PrevSavedUtc = [DateTime]$script:InstalledCacheSavedUtc
        $saveState.NewSignature = [string]$Request.Signature
        $runspace = [runspacefactory]::CreateRunspace()
        $runspace.ApartmentState = 'MTA'
        $runspace.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $runspace
        [void]$ps.AddScript($script:AMRInstalledCacheSaveWorkerText,$true)
        [void]$ps.AddArgument([string]$script:InstalledInventoryCacheFile)
        [void]$ps.AddArgument([string]$Request.Fingerprint)
        [void]$ps.AddArgument([string]$Request.SavedAtUtc)
        [void]$ps.AddArgument([string]$Request.Signature)
        [void]$ps.AddArgument([int]$Request.Count)
        [void]$ps.AddArgument([object[]]$Request.Flags)
        [void]$ps.AddArgument([object[]]$Request.Inventory)
        $saveState.Job = [pscustomobject]@{ PowerShell = $ps; Runspace = $runspace; Async = $ps.BeginInvoke() }
        # Same in-memory values the synchronous save set after writing; reverted below if the write fails.
        $script:InstalledCacheSignature = [string]$Request.Signature
        $script:InstalledCacheSavedUtc = [DateTime]::UtcNow
        if (-not $saveState.Timer) {
            $saveState.Timer = New-Object System.Windows.Threading.DispatcherTimer
            $saveState.Timer.Interval = [TimeSpan]::FromMilliseconds(250)
            $saveState.Timer.Add_Tick({ try { Complete-AMRInstalledCacheSave } catch {} })
        }
        $saveState.Timer.Start()
        return $true
    } catch {
        try { if ($ps) { $ps.Dispose() } } catch {}
        try { if ($runspace) { $runspace.Close(); $runspace.Dispose() } } catch {}
        $saveState.Job = $null
        Write-AMRLog "Could not start the installed-app cache save worker: $($_.Exception.Message)" WARNING Software
        return $false
    }
}

function Complete-AMRInstalledCacheSave {
    $saveState = $script:AMRInstalledCacheSaveState
    $job = $saveState.Job
    if (-not $job) { if ($saveState.Timer) { $saveState.Timer.Stop() }; return }
    if (-not $job.Async.IsCompleted) { return }
    $saveState.Timer.Stop()
    $saveState.Job = $null
    $result = $null
    $endError = ''
    try { $result = @($job.PowerShell.EndInvoke($job.Async)) | Select-Object -First 1 } catch { $endError = $_.Exception.Message }
    try { $job.PowerShell.Dispose() } catch {}
    try { $job.Runspace.Close(); $job.Runspace.Dispose() } catch {}
    if ($result -and $result.PSObject.Properties['Ok'] -and [bool]$result.Ok) {
        Write-AMRLog ('Installed-app cache saved in the background: copy {0} ms, json {1} ms, total {2} ms, {3} chars.' -f $result.SnapshotMs,$result.JsonMs,$result.TotalMs,$result.Chars) INFO Software
    } else {
        $failure = if ($result -and $result.PSObject.Properties['Error']) { [string]$result.Error } else { $endError }
        if ([string]$script:InstalledCacheSignature -eq [string]$saveState.NewSignature) {
            $script:InstalledCacheSignature = [string]$saveState.PrevSignature
            $script:InstalledCacheSavedUtc = [DateTime]$saveState.PrevSavedUtc
        }
        Write-AMRLog "Could not save installed-app cache: $failure" WARNING Software
    }
    $pending = $saveState.Pending
    $saveState.Pending = $null
    if ($pending) { [void](Start-AMRInstalledCacheSaveWorker -Request $pending) }
}

function Save-AMRInstalledInventoryCache {
    try {
        $fingerprint = Get-AMRInstalledCatalogFingerprint
        if ([string]::IsNullOrWhiteSpace($fingerprint)) { return $false }
        $request = [pscustomobject]@{
            Fingerprint = $fingerprint
            SavedAtUtc = [DateTime]::UtcNow.ToString('o')
            Signature = [string]$script:InstalledScanSignatureAtStart
            Count = [int]$script:InstalledScanState.Count
            Flags = @($script:SoftwareCatalog | ForEach-Object { [bool]$_.IsInstalled })
            Inventory = @($script:InstalledScanState.Inventory)
        }
        if ($script:AMRInstalledCacheSaveState.Job) { $script:AMRInstalledCacheSaveState.Pending = $request; return $true }
        return (Start-AMRInstalledCacheSaveWorker -Request $request)
    } catch {
        Write-AMRLog "Could not save installed-app cache: $($_.Exception.Message)" WARNING Software
        return $false
    }
}

# A1: light change check for the Installed catalog. It computes the same cheap change signature as Test-AMRInstalledRefreshNeeded
# (registry key NAMES for the Uninstall and AppX views plus Chocolatey/Scoop folder names; no process, no AppX/winget call) in a
# worker, every 10 minutes and whenever the window is activated (at most once per 30 s). Only a changed signature starts the
# existing full refresh; the UI thread only compares two strings.
$script:AMRInstalledWatch = @{ Runspace = $null; Job = $null; Timer = $null; PollTimer = $null; FollowUpTimer = $null; LastStartUtc = [DateTime]::MinValue; LastRefreshSig = ''; Started = $false }
function Start-AMRInstalledLightCheck {
    param([string]$Reason = 'periodic')
    $w = $script:AMRInstalledWatch
    if ($w.Job) { return }
    $state = $script:InstalledScanState
    if (-not $state.Ready -or $state.Current) { return }
    if ([string]::IsNullOrWhiteSpace([string]$script:InstalledCacheSignature)) { return }
    if (([DateTime]::UtcNow - [DateTime]$w.LastStartUtc).TotalSeconds -lt 30) { return }
    $w.LastStartUtc = [DateTime]::UtcNow
    $ps = $null
    try {
        if (-not $w.Runspace) {
            $rs = [runspacefactory]::CreateRunspace()
            $rs.ApartmentState = 'MTA'
            $rs.Open()
            $w.Runspace = $rs
        }
        $funcText = (Get-Command Get-AMRInstalledChangeSignature -ErrorAction Stop).ScriptBlock.ToString()
        $workerText = "function Get-AMRInstalledChangeSignature {`n" + $funcText + "`n}`n`$sw = [System.Diagnostics.Stopwatch]::StartNew()`n`$sig = Get-AMRInstalledChangeSignature`n[pscustomobject]@{ Signature = [string]`$sig; Ms = [int]`$sw.ElapsedMilliseconds }"
        $ps = [powershell]::Create()
        $ps.Runspace = $w.Runspace
        [void]$ps.AddScript($workerText,$true)
        $w.Job = [pscustomobject]@{ PowerShell = $ps; Async = $ps.BeginInvoke(); Reason = $Reason }
        if (-not $w.Timer) {
            $w.Timer = New-Object System.Windows.Threading.DispatcherTimer
            $w.Timer.Interval = [TimeSpan]::FromMilliseconds(250)
            $w.Timer.Add_Tick({ try { Complete-AMRInstalledLightCheck } catch {} })
        }
        $w.Timer.Start()
    } catch {
        try { if ($ps) { $ps.Dispose() } } catch {}
        $w.Job = $null
        Write-AMRLog ('Installed light check could not start: ' + $_.Exception.Message) WARNING Software
    }
}
function Complete-AMRInstalledLightCheck {
    $w = $script:AMRInstalledWatch
    $job = $w.Job
    if (-not $job) { if ($w.Timer) { $w.Timer.Stop() }; return }
    if (-not $job.Async.IsCompleted) { return }
    $w.Timer.Stop()
    $w.Job = $null
    $sig = ''; $ms = -1
    try { $r = @($job.PowerShell.EndInvoke($job.Async)) | Select-Object -First 1; if ($r) { $sig = [string]$r.Signature; $ms = [int]$r.Ms } } catch {}
    try { $job.PowerShell.Dispose() } catch {}
    $state = $script:InstalledScanState
    if ([string]::IsNullOrWhiteSpace($sig)) { return }
    if (-not $state.Ready -or $state.Current) { return }
    if ($sig -eq [string]$script:InstalledCacheSignature) {
        Write-AMRLog ('Installed light check ({0}, {1} ms in the worker): no install or removal detected.' -f $job.Reason,$ms) INFO Software
        return
    }
    if ($sig -eq [string]$w.LastRefreshSig) {
        Write-AMRLog ('Installed light check ({0}): signature differs from the saved one but a refresh was already run for it; not repeating.' -f $job.Reason) INFO Software
        return
    }
    $w.LastRefreshSig = $sig
    Write-AMRLog ('Installed light check ({0}, {1} ms in the worker): an install or removal was detected; refreshing the installed catalog now.' -f $job.Reason,$ms) INFO Software
    Start-AMRInstalledCatalogScan -Refresh
    # One more check 60 s later catches anything installed while this refresh was running.
    try {
        if (-not $w.FollowUpTimer) {
            $w.FollowUpTimer = New-Object System.Windows.Threading.DispatcherTimer
            $w.FollowUpTimer.Interval = [TimeSpan]::FromSeconds(60)
            $w.FollowUpTimer.Add_Tick({ try { $script:AMRInstalledWatch.FollowUpTimer.Stop(); Start-AMRInstalledLightCheck -Reason 'follow-up' } catch {} })
        }
        $w.FollowUpTimer.Stop(); $w.FollowUpTimer.Start()
    } catch {}
}
function Start-AMRInstalledChangeWatcher {
    $w = $script:AMRInstalledWatch
    if ($w.Started) { return }
    $w.Started = $true
    $w.LastStartUtc = [DateTime]::UtcNow
    $w.PollTimer = New-Object System.Windows.Threading.DispatcherTimer
    $w.PollTimer.Interval = [TimeSpan]::FromMinutes(10)
    $w.PollTimer.Add_Tick({ try { Start-AMRInstalledLightCheck -Reason 'periodic' } catch {} })
    $w.PollTimer.Start()
    $script:Window.Add_Activated({ try { Start-AMRInstalledLightCheck -Reason 'window-activated' } catch {} })
    Write-AMRLog 'Installed change watcher started: light signature check every 10 minutes and on window activation (worker thread).' INFO Software
}

# ----------------------------------------------------------
# AMR Smart Icon Engine ALPHA3 - Installed Apps Bridge
# Separate local icon worker. Existing Alpha icons are preserved.
# ----------------------------------------------------------

$script:AMRLocalAdapterSource = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String('')
)

$script:AMRLocalCollectorSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:AMRLocalMergerSource = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String('')
)

. ([scriptblock]::Create($script:AMRLocalAdapterSource))

$script:AMRLocalIconWorkerState = @{
    Started = $false
    Runspace = $null
    PowerShell = $null
    Async = $null
    Timer = $null
    # A6: decoded (frozen) icons are published by the worker into ReadyQueue, exactly like the
    # catalog icon worker, and kept in Store (keyed by the stable installed AppId) for the whole
    # session so any later visit, restore-from-memory or rebuilt inventory can reuse them.
    ReadyQueue = (New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]')
    Store = @{}
    Attempted = @{}
    SubmittedIds = @()
    WorkerOk = $false
    Rerun = $false
    VisitCount = 0
    RunDelivered = 0
    RunApplied = 0
    RunAvailable = 0
    Index = @{}
    IndexInventory = $null
    IndexCount = -1
}
$script:AMRInstalledIconProofPending = $false
$script:AMRInstalledIconProofSource = ''

# Map every record of the CURRENT Installed inventory by its stable AppId (a rebuilt inventory
# or a restored view is picked up automatically because the map follows the live collection).
function Get-AMRInstalledIconRecordIndex {
    $State = $script:AMRLocalIconWorkerState
    $Inventory = $script:InstalledAppsInventory
    if ($null -ne $State.IndexInventory -and [object]::ReferenceEquals($State.IndexInventory,$Inventory) -and $State.IndexCount -eq $Inventory.Count) {
        return $State.Index
    }
    $Index = @{}
    foreach ($Record in $Inventory) {
        $SafeId = ''
        try { $SafeId = [string](Get-AMRShowInstalledSafeId -Record $Record) } catch { $SafeId = '' }
        if ([string]::IsNullOrWhiteSpace($SafeId)) { continue }
        if (-not $Index.ContainsKey($SafeId)) { $Index[$SafeId] = New-Object 'System.Collections.Generic.List[object]' }
        $Index[$SafeId].Add($Record)
    }
    $State.Index = $Index
    $State.IndexInventory = $Inventory
    $State.IndexCount = $Inventory.Count
    return $Index
}

# Put a ready (frozen) icon on every current record with that AppId that still has none.
function Set-AMRInstalledRecordIcon {
    param([string]$AppId,[object]$Source)
    $Applied = 0
    $Index = Get-AMRInstalledIconRecordIndex
    if (-not $Index.ContainsKey($AppId)) { return 0 }
    foreach ($Record in $Index[$AppId]) {
        try {
            if ($null -eq $Record.Icon) {
                $Record.Icon = $Source
                $Applied++
                if ($script:ShowInstalledOnly) { [void](Sync-AMRRealizedSoftwareIconItem -Item $Record) }
            }
        } catch {
            Write-AMRLog "Could not apply stored installed icon for '$AppId': $($_.Exception.Message)" WARNING Software
        }
    }
    return $Applied
}

# Re-apply everything already decoded this session to the current inventory (restore, re-entry, rebuild).
function Restore-AMRInstalledIconsFromStore {
    $State = $script:AMRLocalIconWorkerState
    $Applied = 0
    if ($State.Store.Count -gt 0) {
        $Index = Get-AMRInstalledIconRecordIndex
        foreach ($AppId in @($Index.Keys)) {
            if ($State.Store.ContainsKey($AppId)) {
                $Applied += [int](Set-AMRInstalledRecordIcon -AppId $AppId -Source $State.Store[$AppId])
            }
        }
    }
    if ($Applied -gt 0 -and $script:ShowInstalledOnly) { [void](Queue-AMRSoftwareIconSync) }
    return $Applied
}

function Get-AMRInstalledIconStats {
    $State = $script:AMRLocalIconWorkerState
    $Total = 0; $With = 0; $NoIcon = 0
    $Index = $null
    try { $Index = Get-AMRInstalledIconRecordIndex } catch {}
    foreach ($Record in $script:InstalledAppsInventory) {
        try {
            if (-not ($Record.IsUserFacing -and $Record.CanUninstall)) { continue }
            $Total++
            if ($null -ne $Record.Icon) { $With++ }
            else {
                $SafeId = [string](Get-AMRShowInstalledSafeId -Record $Record)
                if ($State.Attempted.ContainsKey($SafeId)) { $NoIcon++ }
            }
        } catch {}
    }
    return [pscustomobject]@{ Total = $Total; With = $With; NoIcon = $NoIcon; Pending = ($Total - $With - $NoIcon) }
}

# UI-level proof for the log: once the Installed grid is idle, count the realized cards that
# actually show an image, and the cards whose record has an icon but the card does not show it.
function Write-AMRInstalledIconUiProof {
    param([string]$Source)
    if ($script:AMRInstalledIconProofPending) { return }
    $script:AMRInstalledIconProofPending = $true
    $script:AMRInstalledIconProofSource = $Source
    try {
        $null = $script:Window.Dispatcher.BeginInvoke([Action]{
            $script:AMRInstalledIconProofPending = $false
            try {
                if (-not $script:ShowInstalledOnly) { return }
                $grid = C 'SoftwareGrid'
                $realized = 0; $shown = 0; $missingUi = 0; $noIcon = 0
                $limit = [Math]::Min([int]$grid.Items.Count,200)
                for ($i = 0; $i -lt $limit; $i++) {
                    $container = $grid.ItemContainerGenerator.ContainerFromIndex($i)
                    if ($null -eq $container) { continue }
                    $item = $grid.Items[$i]
                    $elements = Find-AMRSoftwareIconElements -Parent $container
                    $realized++
                    $recordIcon = $null
                    if ($null -ne $item -and $item.PSObject.Properties['Icon']) { $recordIcon = $item.Icon }
                    if ($null -ne $elements.Image -and $null -ne $elements.Image.Source) { $shown++ }
                    elseif ($null -ne $recordIcon) { $missingUi++ }
                    else { $noIcon++ }
                }
                $stats = Get-AMRInstalledIconStats
                Write-AMRLog ("Installed icons UI check ({0}): realizedCards={1}; showingIcon={2}; recordHasIconButCardEmpty={3}; cardsWithoutLocalIcon={4}; records={5}; recordsWithIcon={6}; safetySyncQueued={7}." -f $script:AMRInstalledIconProofSource,$realized,$shown,$missingUi,$noIcon,$stats.Total,$stats.With,[bool]($missingUi -gt 0)) INFO Software
                if ($missingUi -gt 0) { [void](Queue-AMRSoftwareIconSync) }
            } catch {
                Write-AMRLog "Installed icons UI check failed: $($_.Exception.Message)" WARNING Software
            }
        }, [System.Windows.Threading.DispatcherPriority]::ApplicationIdle)
    } catch { $script:AMRInstalledIconProofPending = $false }
}

function Start-AMRInstalledLocalIconRefresh {
    param([string]$Source = 'build')

    $State = $script:AMRLocalIconWorkerState
    if ($Source -ne 'rerun') { $State.VisitCount++ }
    $Visit = [int]$State.VisitCount

    # 1) Everything decoded earlier this session is re-applied immediately, whatever the entry path was.
    $FromStore = 0
    try { $FromStore = [int](Restore-AMRInstalledIconsFromStore) }
    catch { Write-AMRLog "Installed icon store re-apply failed: $($_.Exception.Message)" WARNING Software }

    # 2) A worker is already preparing icons: it is never cancelled when the user leaves Installed.
    #    Ask it to run once more when it finishes so records added meanwhile are covered too.
    if ($State.Started) {
        $State.Rerun = $true
        $Stats = Get-AMRInstalledIconStats
        Write-AMRLog ("Installed icon visit #{0} ({1}): records={2}; withIcon={3}; appliedFromStore={4}; pendingDiscovery={5}; engine=already running (follow-up pass queued)." -f $Visit,$Source,$Stats.Total,$Stats.With,$FromStore,$Stats.Pending) INFO Software
        return
    }

    $State.Started = $true

    try {
        $Candidates = @(
            foreach ($Record in $script:InstalledAppsInventory) {
                if ($Record.IsUserFacing -and $Record.CanUninstall -and $null -eq $Record.Icon) {
                    $SafeId = [string](Get-AMRShowInstalledSafeId -Record $Record)
                    if (-not [string]::IsNullOrWhiteSpace($SafeId) -and -not $State.Attempted.ContainsKey($SafeId)) {
                        $Record
                    }
                }
            }
        )

        if ($Candidates.Count -eq 0) {
            $State.Started = $false
            $Stats = Get-AMRInstalledIconStats
            Write-AMRLog ("Installed icon visit #{0} ({1}): records={2}; withIcon={3}; appliedFromStore={4}; noLocalIcon={5}; engine=idle (nothing left to discover)." -f $Visit,$Source,$Stats.Total,$Stats.With,$FromStore,$Stats.NoIcon) INFO Software
            if ($script:ShowInstalledOnly) { Write-AMRInstalledIconUiProof -Source $Source }
            return
        }

        $Apps = @(ConvertTo-AMRShowInstalledApp -Inventory $Candidates)

        $KnownIds = @{}
        foreach ($Record in $Candidates) {
            $SafeId = Get-AMRShowInstalledSafeId -Record $Record
            if (-not [string]::IsNullOrWhiteSpace($SafeId)) { $KnownIds[$SafeId] = $true }
        }

        $Apps = @(
            foreach ($App in $Apps) {
                if ($KnownIds.ContainsKey([string]$App.AppId)) {
                    $App
                }
            }
        )

        if ($Apps.Count -eq 0) {
            $State.Started = $false
            Write-AMRLog 'Local icon engine: adapter returned no eligible records.' INFO Software
            return
        }

        $CachePath = Join-Path $script:IconDir 'LocalInstalled'
        $CatalogPath = Join-Path $CachePath 'UnifiedIconCatalog.json'

        # Discovery AND image decoding both run in the background runspace. Decoded images are frozen
        # (cross-thread safe) and published to ReadyQueue; the UI thread only assigns them.
        $Worker = {
            param(
                [object[]]$WorkerApps,
                [string]$WorkerCachePath,
                [string]$WorkerCatalogPath,
                [string]$CollectorSource,
                [string]$MergerSource,
                [object]$ReadyQueue
            )

            . ([scriptblock]::Create($CollectorSource))
            . ([scriptblock]::Create($MergerSource))

            $Collection = @(
                Invoke-AMRLocalIconCollection `
                    -Apps $WorkerApps `
                    -CachePath $WorkerCachePath
            )

            $Catalog = New-AMRUnifiedIconCatalog `
                -Apps $WorkerApps `
                -CollectionResults $Collection `
                -OutputPath $WorkerCatalogPath

            try { Add-Type -AssemblyName PresentationCore -ErrorAction Stop } catch {}

            foreach ($Entry in @($Catalog.Entries)) {
                if ($Entry.Status -ne 'Available' -or $Entry.SelectedSource -ne 'LocalInstalledApp') { continue }
                $IconPath = [string]$Entry.IconPath
                if ([string]::IsNullOrWhiteSpace($IconPath)) { continue }
                try {
                    $FileStream = [System.IO.File]::Open([System.IO.Path]::GetFullPath($IconPath),[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite)
                    try {
                        $Decoder = [System.Windows.Media.Imaging.BitmapDecoder]::Create(
                            $FileStream,
                            [System.Windows.Media.Imaging.BitmapCreateOptions]::IgnoreImageCache,
                            [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                        )
                        if ($null -ne $Decoder -and $Decoder.Frames.Count -ge 1) {
                            $Frame = $Decoder.Frames[0]
                            if ($Frame.CanFreeze) { $Frame.Freeze() }
                            $ReadyQueue.Enqueue([pscustomobject]@{ AppId = [string]$Entry.AppId; Source = $Frame })
                        }
                    } finally { $FileStream.Dispose() }
                } catch {}
            }

            return @($Catalog.Entries)
        }

        $Runspace = [RunspaceFactory]::CreateRunspace()
        $Runspace.ApartmentState = [Threading.ApartmentState]::MTA
        $Runspace.ThreadOptions = [Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $Runspace.Open()

        $PowerShell = [PowerShell]::Create()
        $PowerShell.Runspace = $Runspace

        [void]$PowerShell.AddScript($Worker.ToString())
        [void]$PowerShell.AddArgument($Apps)
        [void]$PowerShell.AddArgument($CachePath)
        [void]$PowerShell.AddArgument($CatalogPath)
        [void]$PowerShell.AddArgument($script:AMRLocalCollectorSource)
        [void]$PowerShell.AddArgument($script:AMRLocalMergerSource)
        [void]$PowerShell.AddArgument($State.ReadyQueue)

        $State.SubmittedIds = @($KnownIds.Keys)
        $State.WorkerOk = $false
        $State.RunDelivered = 0
        $State.RunApplied = 0
        $State.RunAvailable = 0
        $Async = $PowerShell.BeginInvoke()

        $State.Runspace = $Runspace
        $State.PowerShell = $PowerShell
        $State.Async = $Async
        $State.StartedUtc = [DateTime]::UtcNow

        # Delivery timer: it keeps running until the worker has finished AND every decoded icon was
        # delivered, no matter which surface is showing. It never cancels because the user left Installed.
        $Timer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
        $Timer.Interval = [TimeSpan]::FromMilliseconds(50)

        $Timer.Add_Tick({
            $State = $script:AMRLocalIconWorkerState

            # Small steady batches of ready frozen images (same shape as the catalog icon delivery).
            $perfDeliverStart = Get-AMRPerfNow
            for ($delivery = 0; $delivery -lt 4; $delivery++) {
                $Ready = $null
                if (-not $State.ReadyQueue.TryDequeue([ref]$Ready)) { break }
                if ($null -eq $Ready) { continue }
                $ReadyId = [string]$Ready.AppId
                $State.Store[$ReadyId] = $Ready.Source
                $State.RunDelivered++
                $perfItemStart = Get-AMRPerfNow
                try { $State.RunApplied += [int](Set-AMRInstalledRecordIcon -AppId $ReadyId -Source $Ready.Source) }
                catch { Write-AMRLog "Could not apply local icon for '$ReadyId': $($_.Exception.Message)" WARNING Software }
                Add-AMRPerfSince -Key 'icons.installedApplyItem' -Start $perfItemStart
                Set-AMRPerfMark 'installedIcon'
            }
            if ($perfDeliverStart -ne 0) { Add-AMRPerfSince -Key 'icons.installedDeliverTick' -Start $perfDeliverStart }

            if ($State.Async) {
                if (-not $State.Async.IsCompleted) { return }
                try {
                    $Entries = @($State.PowerShell.EndInvoke($State.Async))
                    $State.RunAvailable = @(
                        $Entries | Where-Object {
                            $_.Status -eq 'Available' -and
                            $_.SelectedSource -eq 'LocalInstalledApp' -and
                            -not [string]::IsNullOrWhiteSpace([string]$_.IconPath)
                        }
                    ).Count
                    $State.WorkerOk = $true
                    $workerSecs = 0.0; try { $workerSecs = ([DateTime]::UtcNow - [DateTime]$State.StartedUtc).TotalSeconds } catch {}
                    Write-AMRLog (
                        'Local icon discovery completed in {2:N1} s. Records: {0}; icons available: {1}. Frozen icons are delivered progressively and kept for later visits.' -f
                        $Entries.Count,$State.RunAvailable,$workerSecs
                    ) INFO Software
                }
                catch {
                    Write-AMRLog "Local icon worker completion failed: $($_.Exception.Message)" WARNING Software
                }
                finally {
                    try { $State.PowerShell.Dispose() } catch {}
                    try { $State.Runspace.Close() } catch {}
                    try { $State.Runspace.Dispose() } catch {}
                    $State.PowerShell = $null
                    $State.Runspace = $null
                    $State.Async = $null
                }
            }

            if ($State.ReadyQueue.IsEmpty) {
                try { $State.Timer.Stop() } catch {}
                $State.Timer = $null
                $State.Started = $false
                if ($State.WorkerOk) {
                    foreach ($SubmittedId in @($State.SubmittedIds)) {
                        if (-not $State.Store.ContainsKey($SubmittedId)) { $State.Attempted[$SubmittedId] = $true }
                    }
                }
                $State.SubmittedIds = @()
                $Stats = Get-AMRInstalledIconStats
                Write-AMRLog (
                    'Progressive local icon application completed. Delivered={0}; appliedToRecords={1}; records={2}; withIcon={3}; noLocalIcon={4}; onInstalledSurface={5}.' -f
                    $State.RunDelivered,$State.RunApplied,$Stats.Total,$Stats.With,$Stats.NoIcon,[bool]$script:ShowInstalledOnly
                ) INFO Software
                if ($script:ShowInstalledOnly) { Write-AMRInstalledIconUiProof -Source 'engine-completed' }
                if ($State.Rerun) {
                    $State.Rerun = $false
                    Start-AMRInstalledLocalIconRefresh -Source 'rerun'
                }
            }
        })

        $State.Timer = $Timer
        $Timer.Start()

        $Stats = Get-AMRInstalledIconStats
        Write-AMRLog (
            'Local icon engine started in background for {0} installed record(s). Visit #{1} ({2}); records={3}; withIcon={4}; appliedFromStore={5}.' -f
            $Apps.Count,$Visit,$Source,$Stats.Total,$Stats.With,$FromStore
        ) INFO Software
    }
    catch {
        $State.Started = $false
        Write-AMRLog "Could not start local icon engine: $($_.Exception.Message)" WARNING Software
    }
}

# Initialize software icon synchronization state before any dispatcher callback can use it.
$script:SoftwareIconScrollSyncPending = $false
$script:AMRLastSoftwareScrollTicks = [long]0
$script:AMRScanDeferStartTicks = [long]0
$script:SoftwareIconSyncQueued = $false

# Show Installed: lively, non-blocking feedback while the inventory worker scans.
# The original button palette and layout are restored as soon as the scan completes.
$script:ShowInstalledButtonBusyState = [pscustomobject]@{
    Active = $false
    OriginalContent = $null
    OriginalBackground = $null
    OriginalBorderBrush = $null
    OriginalEffect = $null
    OriginalRenderTransform = $null
    OriginalRenderTransformOrigin = $null
    SpinnerTransform = $null
    ButtonScaleTransform = $null
    BusyEffect = $null
    BusyBorder = $null
}

function Set-AMRShowInstalledButtonBusy {
    param(
        [Parameter(Mandatory=$true)][bool]$Busy,
        [string]$Label = 'Show Installed'
    )

    $button = C 'ShowInstalledBtn'
    if (-not $button) { return }
    $state = $script:ShowInstalledButtonBusyState

    if ($Busy) {
        if ($state.Active) { return }

        $state.OriginalContent = $button.Content
        $state.OriginalBackground = $button.Background
        $state.OriginalBorderBrush = $button.BorderBrush
        $state.OriginalEffect = $button.Effect
        $state.OriginalRenderTransform = $button.RenderTransform
        $state.OriginalRenderTransformOrigin = $button.RenderTransformOrigin

        $content = [System.Windows.Controls.StackPanel]::new()
        $content.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $content.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $content.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $spinner = [System.Windows.Controls.TextBlock]::new()
        $spinner.Text = '↻'
        $spinner.FontSize = 16
        $spinner.FontWeight = [System.Windows.FontWeights]::Bold
        $spinner.Margin = [System.Windows.Thickness]::new(0,0,7,0)
        $spinner.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $spinner.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
        $spinnerTransform = [System.Windows.Media.RotateTransform]::new(0)
        $spinner.RenderTransform = $spinnerTransform

        $labelBlock = [System.Windows.Controls.TextBlock]::new()
        $labelBlock.Text = $Label
        $labelBlock.FontSize = 12
        $labelBlock.FontWeight = [System.Windows.FontWeights]::SemiBold
        $labelBlock.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        [void]$content.Children.Add($spinner)
        [void]$content.Children.Add($labelBlock)
        $button.Content = $content

        # Match the current toggle mode: teal while entering Installed, violet
        # while returning to the full catalog.
        if ($script:ShowInstalledButtonMode -eq 'Installed') {
            $busyBaseColor = [System.Windows.Media.Color]::FromRgb(133,101,196)
            $busyGlowColor = [System.Windows.Media.Color]::FromRgb(218,198,255)
        } else {
            $busyBaseColor = [System.Windows.Media.Color]::FromRgb(69,107,101)
            $busyGlowColor = [System.Windows.Media.Color]::FromRgb(167,216,206)
        }
        $busyBorder = [System.Windows.Media.SolidColorBrush]::new($busyBaseColor)
        $button.BorderBrush = $busyBorder
        $borderPulse = [System.Windows.Media.Animation.ColorAnimation]::new()
        $borderPulse.From = $busyBaseColor
        $borderPulse.To = $busyGlowColor
        $borderPulse.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds(0.8))
        $borderPulse.AutoReverse = $true
        $borderPulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        [void]$busyBorder.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $borderPulse)

        $busyEffect = [System.Windows.Media.Effects.DropShadowEffect]::new()
        $busyEffect.Color = if ($script:ShowInstalledButtonMode -eq 'Installed') {
            [System.Windows.Media.Color]::FromRgb(177,139,255)
        } else {
            [System.Windows.Media.Color]::FromRgb(111,190,177)
        }
        $busyEffect.ShadowDepth = 0
        $busyEffect.BlurRadius = 10
        $busyEffect.Opacity = 0.42
        $button.Effect = $busyEffect

        # Subtle breathing scale on the button surface; preserve and restore its
        # original transform after the installed-app loading cycle.
        $buttonScale = [System.Windows.Media.ScaleTransform]::new(1.0,1.0)
        $button.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
        $button.RenderTransform = $buttonScale
        $scalePulse = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $scalePulse.From = 1.0
        $scalePulse.To = 1.025
        $scalePulse.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds(0.8))
        $scalePulse.AutoReverse = $true
        $scalePulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        [void]$buttonScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $scalePulse)
        [void]$buttonScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $scalePulse)

        $glowPulse = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $glowPulse.From = 0.28
        $glowPulse.To = 0.78
        $glowPulse.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds(0.8))
        $glowPulse.AutoReverse = $true
        $glowPulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        [void]$busyEffect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty, $glowPulse)

        $blurPulse = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $blurPulse.From = 8
        $blurPulse.To = 15
        $blurPulse.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds(0.8))
        $blurPulse.AutoReverse = $true
        $blurPulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        [void]$busyEffect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::BlurRadiusProperty, $blurPulse)

        $spin = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $spin.From = 0
        $spin.To = 360
        $spin.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds(0.9))
        $spin.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        [void]$spinnerTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $spin)

        $state.SpinnerTransform = $spinnerTransform
        $state.ButtonScaleTransform = $buttonScale
        $state.BusyEffect = $busyEffect
        $state.BusyBorder = $busyBorder
        $state.Active = $true
        $button.IsEnabled = $true
        return
    }

    if ($state.Active) {
        try {
            if ($state.SpinnerTransform) {
                $state.SpinnerTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null)
            }
            if ($state.BusyBorder) {
                $state.BusyBorder.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $null)
            }
            if ($state.BusyEffect) {
                $state.BusyEffect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty, $null)
                $state.BusyEffect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::BlurRadiusProperty, $null)
            }
            if ($state.ButtonScaleTransform) {
                $state.ButtonScaleTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
                $state.ButtonScaleTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)
            }
            $button.Background = $state.OriginalBackground
            $button.BorderBrush = $state.OriginalBorderBrush
            $button.Effect = $state.OriginalEffect
            $button.RenderTransform = $state.OriginalRenderTransform
            $button.RenderTransformOrigin = $state.OriginalRenderTransformOrigin
        } catch {
            Write-AMRLog "Could not fully restore Show Installed button visuals: $($_.Exception.Message)" WARNING Software
        }
        $state.Active = $false
        $state.SpinnerTransform = $null
        $state.ButtonScaleTransform = $null
        $state.BusyEffect = $null
        $state.BusyBorder = $null
        $state.OriginalRenderTransform = $null
        $state.OriginalRenderTransformOrigin = $null
    }

    $button.Content = $Label
    $button.IsEnabled = $true
}

# Give the toggle a distinct, persistent visual identity while the installed
# catalog is active, with a lightweight hover breathing/glow interaction.
$script:ShowInstalledButtonMode = 'All'
$script:ShowInstalledButtonHoverEffect = $null
$script:ShowInstalledButtonHoverTransform = $null
function Set-AMRShowInstalledButtonMode {
    param([ValidateSet('All','Installed')][string]$Mode = 'All')
    $button = C 'ShowInstalledBtn'
    if (-not $button) { return }
    $script:ShowInstalledButtonMode = $Mode
    if ($script:ShowInstalledButtonBusyState.Active) { return }

    if ($Mode -eq 'Installed') {
        $button.Background = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(48,38,76))
        $button.Foreground = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(218,198,255))
        $button.BorderBrush = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(133,101,196))
        $button.ToolTip = 'Return to the full software catalog.'
    } else {
        $button.Background = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(38,59,58))
        $button.Foreground = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(167,216,206))
        $button.BorderBrush = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(69,107,101))
        $button.ToolTip = 'Show only applications detected as installed on this PC.'
    }
}

$showInstalledButton = C 'ShowInstalledBtn'
if ($showInstalledButton) {
    $showInstalledButton.RenderTransformOrigin = [System.Windows.Point]::new(0.5,0.5)
    $showInstalledButton.Add_MouseEnter({
        $button = C 'ShowInstalledBtn'
        if (-not $button -or $script:ShowInstalledButtonBusyState.Active) { return }
        $scale = [System.Windows.Media.ScaleTransform]::new(1.0,1.0)
        $button.RenderTransform = $scale
        $script:ShowInstalledButtonHoverTransform = $scale
        $pulse = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $pulse.From = 1.0
        $pulse.To = 1.065
        $pulse.Duration = [System.Windows.Duration]::new([TimeSpan]::FromSeconds(0.42))
        $pulse.AutoReverse = $true
        $pulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        [void]$scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $pulse)
        [void]$scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $pulse)
        $glow = [System.Windows.Media.Effects.DropShadowEffect]::new()
        $glow.Color = if ($script:ShowInstalledButtonMode -eq 'Installed') {
            [System.Windows.Media.Color]::FromRgb(177,139,255)
        } else {
            [System.Windows.Media.Color]::FromRgb(111,190,177)
        }
        $glow.ShadowDepth = 0
        $glow.BlurRadius = 13
        $glow.Opacity = 0.62
        $button.Effect = $glow
        $script:ShowInstalledButtonHoverEffect = $glow
    }.GetNewClosure())
    $showInstalledButton.Add_MouseLeave({
        $button = C 'ShowInstalledBtn'
        if (-not $button -or $script:ShowInstalledButtonBusyState.Active) { return }
        if ($script:ShowInstalledButtonHoverTransform) {
            $script:ShowInstalledButtonHoverTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
            $script:ShowInstalledButtonHoverTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)
        }
        $button.RenderTransform = [System.Windows.Media.ScaleTransform]::new(1.0,1.0)
        $button.Effect = $null
        $script:ShowInstalledButtonHoverTransform = $null
        $script:ShowInstalledButtonHoverEffect = $null
    }.GetNewClosure())
}

# V14: preserve the original catalog categories in Show Installed, map installed
# records to catalog categories in O(n), and keep installed cards compact/expandable.
$script:InstalledGridPageBuildState = $null
$script:CatalogGridPageBuildState = $null
$script:InstalledViewPreparationState = $null
# Reuse catalog ID/name indexes across Show Installed switches.
$script:InstalledCatalogLookupSource = $null
$script:InstalledCatalogLookupById = $null
$script:InstalledCatalogLookupByName = $null
$script:SuppressSoftwareCategorySelectionChanged = $false

function Get-AMRShowInstalledDiagnosticDetails {
    param(
        [Parameter(Mandatory=$true)]$ErrorRecord,
        [Parameter(Mandatory=$true)][string]$Stage
    )

    $lineNumber = 0
    $commandName = ''
    $positionMessage = ''
    $stackTrace = ''
    $errorId = ''
    $targetObject = ''
    try { $lineNumber = [int]$ErrorRecord.InvocationInfo.ScriptLineNumber } catch {}
    try { $commandName = [string]$ErrorRecord.InvocationInfo.MyCommand.Name } catch {}
    try { $positionMessage = [string]$ErrorRecord.InvocationInfo.PositionMessage } catch {}
    try { $stackTrace = [string]$ErrorRecord.ScriptStackTrace } catch {}
    try { $errorId = [string]$ErrorRecord.FullyQualifiedErrorId } catch {}
    try { $targetObject = [string]$ErrorRecord.TargetObject } catch {}

    $details = @(
        ('Stage: {0}' -f $Stage)
        ('Exception: {0}' -f $ErrorRecord.Exception.ToString())
        ('Script line: {0}' -f $lineNumber)
        ('Command: {0}' -f $commandName)
        ('Error ID: {0}' -f $errorId)
        ('Target object: {0}' -f $targetObject)
        'Position:'
        $positionMessage
        'PowerShell stack trace:'
        $stackTrace
    )
    return ($details -join [Environment]::NewLine)
}

function Start-AMRInstalledGridPageBuild {
    param(
        [Parameter(Mandatory=$true)]$View,
        [bool]$WasInstalledViewVisible,
        [int]$InstalledCount,
        [string]$RestoreCategory = '',
        [double]$RestoreScrollOffset = 0,
        [int]$InventoryGeneration = -1
    )

    if ($script:InstalledGridPageBuildState) {
        $existingBuild = $script:InstalledGridPageBuildState
        if ([int]$existingBuild.InventoryGeneration -eq [int]$script:InstalledInventoryGeneration -and
            [object]::ReferenceEquals($existingBuild.View,$View)) {
            if ($existingBuild.Timer -and -not $existingBuild.Timer.IsEnabled) {
                $existingBuild.Timer.Start()
                Write-AMRLog 'Resumed the existing Installed page-build state; duplicate build was suppressed.' INFO Software
            } elseif ($existingBuild.Timer) {
                Write-AMRLog 'Duplicate Installed page-build request ignored; an equivalent build is already active.' INFO Software
            }
            return
        }
        try { if ($existingBuild.Timer) { $existingBuild.Timer.Stop() } } catch {}
        try { if ($existingBuild.ViewEnumerator) { $existingBuild.ViewEnumerator.Dispose() } } catch {}
    }

    # Do not enumerate the entire CollectionView synchronously on the WPF UI thread.
    # The dispatcher state machine groups it directly in short time-budgeted slices.
    $categoryNames = @($script:SoftwareCategoryNames)
    $groups = @{}
    $categoryOrdinals = @{}
    for ($categoryIndex = 0; $categoryIndex -lt $categoryNames.Count; $categoryIndex++) {
        $categoryName = [string]$categoryNames[$categoryIndex]
        $groups[$categoryName] = New-Object 'System.Collections.Generic.List[object]'
        $categoryOrdinals[$categoryName] = [int]($categoryIndex + 1)
    }

    $state = [pscustomobject]@{
        View = $View
        ViewEnumerator = $View.GetEnumerator()
        CategoryNames = $categoryNames
        Groups = $groups
        CategoryOrdinals = $categoryOrdinals
        Uncategorised = (New-Object 'System.Collections.Generic.List[object]')
        OrderedItems = (New-Object 'System.Collections.Generic.List[object]')
        Index = 0
        Phase = 'Collect'
        CategoryIndex = 0
        GroupIndex = 0
        CurrentGroup = $null
        GroupItemIndex = 0
        FirstInGroup = $true
        AppIndexInGroup = 0
        CurrentOrdinal = 0
        Mode = 'Installed'
        ScrollPrefetchPending = $false
        BatchSize = 64
        TickBudgetMilliseconds = 5
        Timer = $null
        FirstPageCommitted = $false
        PageItems = $null
        WasInstalledViewVisible = $WasInstalledViewVisible
        InstalledCount = $InstalledCount
        InventoryGeneration = if ($InventoryGeneration -ge 0) { $InventoryGeneration } else { [int]$script:InstalledInventoryGeneration }
        RestoreCategory = $RestoreCategory
        RestoreScrollOffset = $RestoreScrollOffset
    }
    # Never let Installed scroll paging read the previous All Applications source.
    $script:SoftwareGridPageMode = 'Installed'
    $script:SoftwareGridPageSource = @()
    $script:SoftwareGridPageIndex = 0
    $script:InstalledGridPageBuildState = $state

    $timer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
    $timer.Interval = [TimeSpan]::FromMilliseconds(15)
    $timer.Add_Tick({ Complete-AMRInstalledGridPageBuildBatch })
    $state.Timer = $timer
    $timer.Start()
}

function Publish-AMRInstalledFirstPage {
    param([Parameter(Mandatory=$true)]$State)

    if (-not $script:ShowInstalledOnly) { return }
    if ($State.OrderedItems.Count -lt 4) { return }
    try {
        if (-not $State.FirstPageCommitted) {
            $pageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
            for ($index = 0; $index -lt 4; $index++) {
                [void]$pageItems.Add($State.OrderedItems[$index])
            }
            $State.PageItems = $pageItems
            $State.FirstPageCommitted = $true
            $script:SoftwareGridPageMode = 'Installed'
            $script:SoftwareGridPageIndex = 4
            $script:SoftwareGridPageSize = 4
            $script:SoftwareGridPageItems = $pageItems
            (C 'SoftwareGrid').ItemsSource = $pageItems
            Invoke-AMRSoftwareGridViewTransition
            Queue-AMRSoftwareIconSync
            (C 'SoftwareScrollViewer').ScrollToTop()
            Write-AMRLog ('Installed view first row published for inventory generation ' + [string]$State.InventoryGeneration + '; additional rows will appear progressively.') INFO Software
            return
        }

        # Keep the early reveal capped at 64, then satisfy scroll demand directly
        # from this Installed build's OrderedItems as additional rows become ready.
        if ($State.PageItems.Count -lt 64) {
            $available = $State.OrderedItems.Count - $State.PageItems.Count
            if ($available -ge 4) {
                $appendEnd = [Math]::Min([Math]::Min($State.PageItems.Count + 4,64),$State.OrderedItems.Count)
                while ($State.PageItems.Count -lt $appendEnd) {
                    [void]$State.PageItems.Add($State.OrderedItems[$State.PageItems.Count])
                }
                $script:SoftwareGridPageItems = $State.PageItems
                $script:SoftwareGridPageIndex = [int]$State.PageItems.Count
            }
        }
        Invoke-AMRSoftwareGridPrefetchDemand -State $State
    } catch {
        $State.FirstPageCommitted = $false
        $State.PageItems = $null
        Write-AMRLog ('Could not publish the Installed cards progressively: ' + $_.Exception.Message) WARNING Software
    }
}

function Complete-AMRInstalledGridPageBuildBatch {
    $state = $script:InstalledGridPageBuildState
    if (-not $state -or -not $script:ShowInstalledOnly) { return }

    try {
        switch ($state.Phase) {
            'Collect' {
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                while ($watch.ElapsedMilliseconds -lt $state.TickBudgetMilliseconds) {
                    if (-not $state.ViewEnumerator.MoveNext()) {
                        try { $state.ViewEnumerator.Dispose() } catch {}
                        $state.ViewEnumerator = $null
                        $state.Phase = 'CategoryStart'
                        $state.Index = 0
                        break
                    }
                    $item = $state.ViewEnumerator.Current
                    $category = [string]$item.Category
                    if ($state.Groups.ContainsKey($category)) {
                        [void]$state.Groups[$category].Add($item)
                    } elseif ([string]::IsNullOrWhiteSpace($category)) {
                        [void]$state.Uncategorised.Add($item)
                    }
                }
                return
            }
            'CategoryStart' {
                while ($state.CategoryIndex -lt $state.CategoryNames.Count) {
                    $categoryName = [string]$state.CategoryNames[$state.CategoryIndex]
                    $groupItems = $state.Groups[$categoryName]
                    if ($groupItems.Count -eq 0) {
                        $state.CategoryIndex++
                        continue
                    }

                    if ($state.GroupIndex -gt 0) {
                        $remainder = $state.OrderedItems.Count % 4
                        if ($remainder -ne 0) {
                            $padCount = 4 - $remainder
                            for ($pad = 0; $pad -lt $padCount; $pad++) {
                                $spacer = [pscustomobject]@{
                                    IsCategorySpacer = $true
                                    IsCategoryStart = $false
                                    IsCategoryHeaderRow = $false
                                    CategoryNumber = ''
                                    Category = ''
                                    Icon = $null
                                    Initials = ''
                                }
                                [void]$state.OrderedItems.Add($spacer)
                            }
                        }
                    }

                    $state.CurrentGroup = $groupItems
                    $state.GroupItemIndex = 0
                    $state.FirstInGroup = $true
                    $state.AppIndexInGroup = 0
                    $state.CurrentOrdinal = [int]$state.CategoryOrdinals[$categoryName]
                    $state.Phase = 'CategoryItems'
                    return
                }
                $state.Phase = 'Uncategorised'
                $state.Index = 0
                return
            }
            'CategoryItems' {
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                $endIndex = [Math]::Min(
                    $state.GroupItemIndex + $state.BatchSize,
                    $state.CurrentGroup.Count
                )
                while ($state.GroupItemIndex -lt $endIndex -and $watch.ElapsedMilliseconds -lt $state.TickBudgetMilliseconds) {
                    $app = $state.CurrentGroup[$state.GroupItemIndex]
                    foreach ($propertyName in @('IsCategorySpacer','IsCategoryStart','IsCategoryHeaderRow','CategoryNumber')) {
                        if (-not $app.PSObject.Properties[$propertyName]) {
                            $app | Add-Member -NotePropertyName $propertyName -NotePropertyValue $null
                        }
                    }
                    $app.IsCategorySpacer = $false
                    $app.IsCategoryStart = [bool]($state.FirstInGroup -and $state.CurrentOrdinal -gt 1)
                    $app.IsCategoryHeaderRow = [bool]($state.CurrentOrdinal -gt 1 -and $state.AppIndexInGroup -lt 4)
                    $app.CategoryNumber = if ($state.CurrentOrdinal -gt 1) { [string]$state.CurrentOrdinal } else { '' }
                    [void]$state.OrderedItems.Add($app)
                    $state.FirstInGroup = $false
                    $state.AppIndexInGroup++
                    $state.GroupItemIndex++
                    if (-not $state.FirstPageCommitted -and $state.OrderedItems.Count -ge 4) {
                        Publish-AMRInstalledFirstPage -State $state
                        return
                    }
                }
                Publish-AMRInstalledFirstPage -State $state
                if ($state.GroupItemIndex -ge $state.CurrentGroup.Count) {
                    $state.GroupIndex++
                    $state.CategoryIndex++
                    $state.Phase = 'CategoryStart'
                }
                return
            }
            'Uncategorised' {
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                $endIndex = [Math]::Min($state.Index + $state.BatchSize, $state.Uncategorised.Count)
                while ($state.Index -lt $endIndex -and $watch.ElapsedMilliseconds -lt $state.TickBudgetMilliseconds) {
                    $app = $state.Uncategorised[$state.Index]
                    foreach ($propertyName in @('IsCategorySpacer','IsCategoryStart','IsCategoryHeaderRow','CategoryNumber')) {
                        if (-not $app.PSObject.Properties[$propertyName]) {
                            $app | Add-Member -NotePropertyName $propertyName -NotePropertyValue $null
                        }
                    }
                    $app.IsCategorySpacer = $false
                    $app.IsCategoryStart = $false
                    $app.IsCategoryHeaderRow = $false
                    $app.CategoryNumber = ''
                    [void]$state.OrderedItems.Add($app)
                    $state.Index++
                    if (-not $state.FirstPageCommitted -and $state.OrderedItems.Count -ge 4) {
                        Publish-AMRInstalledFirstPage -State $state
                        return
                    }
                }
                Publish-AMRInstalledFirstPage -State $state
                if ($state.Index -ge $state.Uncategorised.Count) {
                    $state.Phase = 'Commit'
                }
                return
            }
            'Commit' {
                $state.Timer.Stop()
                try { if ($state.ViewEnumerator) { $state.ViewEnumerator.Dispose() } } catch {}
                $state.ViewEnumerator = $null
                $script:SoftwareGridPageMode = 'Installed'
                $script:SoftwareGridPageSource = $state.OrderedItems.ToArray()
                $script:SoftwareGridPageSize = 4
                $script:InstalledRefreshPending = $false
                $script:InstalledViewCache = [pscustomobject]@{
                    InventoryGeneration = [int]$state.InventoryGeneration
                    SearchText = [string](C 'SearchBox').Text
                    SelectedCategory = [string]$state.RestoreCategory
                    Inventory = $script:InstalledAppsInventory
                    View = $script:InstalledAppsView
                    PageSource = $script:SoftwareGridPageSource
                    PageItems = $script:SoftwareGridPageItems
                    PageIndex = [int]$script:SoftwareGridPageIndex
                    ScrollOffset = [double]$state.RestoreScrollOffset
                }
                if ($state.FirstPageCommitted -and $state.PageItems) {
                    # Keep the first rendered row alive; the completed source now feeds progressive paging.
                    $script:SoftwareGridPageItems = $state.PageItems
                    $script:SoftwareGridPageIndex = [int]$state.PageItems.Count
                } else {
                    $newPageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
                    $script:SoftwareGridPageIndex = 0
                    $initialEnd = [Math]::Min(4, $script:SoftwareGridPageSource.Count)
                    while ($script:SoftwareGridPageIndex -lt $initialEnd) {
                        [void]$newPageItems.Add($script:SoftwareGridPageSource[$script:SoftwareGridPageIndex])
                        $script:SoftwareGridPageIndex++
                    }
                    $script:SoftwareGridPageItems = $newPageItems
                    (C 'SoftwareGrid').ItemsSource = $script:SoftwareGridPageItems
                    Invoke-AMRSoftwareGridViewTransition
                    Queue-AMRSoftwareIconSync
                    (C 'SoftwareScrollViewer').ScrollToTop()
                }
                Start-AMRSoftwareGridWarmup
                if ($script:InstalledViewCache) {
                    $script:InstalledViewCache.PageItems = $script:SoftwareGridPageItems
                    $script:InstalledViewCache.PageIndex = [int]$script:SoftwareGridPageIndex
                    $script:InstalledViewCache.PageSource = $script:SoftwareGridPageSource
                }

                $script:SuppressSoftwareCategorySelectionChanged = $true
                try {
                    if ($state.RestoreCategory) {
                        $categoryItem = @($script:SoftwareCategories | Where-Object {
                            [string]$_.Name -eq $state.RestoreCategory
                        } | Select-Object -First 1)
                        if ($categoryItem.Count -gt 0) {
                            $script:SelectedSoftwareCategory = $state.RestoreCategory
                            (C 'SoftwareCategoryList').SelectedItem = $categoryItem[0]
                        }
                    } else {
                        $script:SelectedSoftwareCategory = 'All Applications'
                        (C 'SoftwareCategoryList').SelectedIndex = 0
                    }
                } finally {
                    $script:SuppressSoftwareCategorySelectionChanged = $false
                }

                Start-AMRInstalledLocalIconRefresh -Source 'build'
                $button = C 'ShowInstalledBtn'
                $button.Content = "Show All ($($state.InstalledCount))"
                $button.ToolTip = 'Return to the full software catalog.'
                $button.IsEnabled = $true
                (C 'UninstallSelectedBtn').Visibility = 'Visible'
                if ($state.RestoreCategory) {
                    $restoreOffset = [double]$state.RestoreScrollOffset
                    $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                        try { (C 'SoftwareScrollViewer').ScrollToVerticalOffset($restoreOffset) } catch {}
                    }, [System.Windows.Threading.DispatcherPriority]::Loaded)
                }
                Write-AMRLog "Universal installed inventory displayed: $($state.InstalledCount) record(s)." INFO Software
                $script:ProgressText.Text = ''
                Set-AMRShowInstalledButtonBusy -Busy $false -Label "Show All ($($state.InstalledCount))"
                Set-AMRShowInstalledButtonMode -Mode Installed
                $button.Content = "Show All ($($state.InstalledCount))"
                $button.ToolTip = 'Return to the full software catalog.'
                $script:InstalledGridPageBuildState = $null
                return
            }
        }
    } catch {
        try { if ($state.Timer) { $state.Timer.Stop() } } catch {}
        try { if ($state.ViewEnumerator) { $state.ViewEnumerator.Dispose() } } catch {}
        $state.ViewEnumerator = $null
        if (-not $state.WasInstalledViewVisible) {
            Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
            Reset-AMRInstalledViewAfterPreparationFailure
        }
        $diagnosticDetails = Get-AMRShowInstalledDiagnosticDetails -ErrorRecord $_ -Stage 'Installed card/page preparation'
        Write-AMRLog "Could not prepare the Show Installed cards:`n$diagnosticDetails" ERROR Software
        Show-AMRMessageGlass "Could not prepare the installed-applications cards:`n`n$diagnosticDetails" 'Installed Apps' OK Error | Out-Null
        $script:InstalledGridPageBuildState = $null
    }
}
function Initialize-AMRInstalledViewContext {
    param(
        [Parameter(Mandatory=$true)]$Inventory,
        [string]$RestoreCategory = ''
    )

    # This helper runs in the original script scope, not the DispatcherTimer
    # closure module. Keep all script-scoped view state changes here.
    $script:InstalledAppsView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($Inventory)
    $script:SelectedSoftwareCategory = if ($RestoreCategory) { $RestoreCategory } else { 'All Applications' }
    $script:InstalledAppsView.Filter = [System.Predicate[object]]{ param($item)
        if (-not [bool]$item.IsUserFacing -or -not [bool]$item.CanUninstall) { return $false }
        $selectedCategory = [string]$script:SelectedSoftwareCategory
        if ($selectedCategory -and $selectedCategory -ne 'All Applications' -and [string]$item.Category -ne $selectedCategory) { return $false }
        $searchText = (C 'SearchBox').Text
        if ([string]::IsNullOrWhiteSpace($searchText)) { return $true }
        $escaped = [regex]::Escape($searchText)
        return ([string]$item.DisplayName -match "(?i)$escaped") -or ([string]$item.Name -match "(?i)$escaped") -or ([string]$item.Id -match "(?i)$escaped") -or ([string]$item.Publisher -match "(?i)$escaped")
    }

    $script:SuppressSoftwareCategorySelectionChanged = $true
    try {
        (C 'SoftwareCategoryList').ItemsSource = $script:SoftwareCategories
    } finally {
        $script:SuppressSoftwareCategorySelectionChanged = $false
    }
    Update-AMRSoftwareCategoryCounts
    return $script:InstalledAppsView
}

function Clear-AMRInstalledViewPreparationState {
    $script:InstalledViewPreparationState = $null
}

function Reset-AMRInstalledViewAfterPreparationFailure {
    $script:ShowInstalledOnly = $false
    $script:SoftwareGridTransitionPending = $true

    # A failed Installed preparation must not strand a paused catalog builder.
    # Restore its original category and exact partial page when its search input
    # is still current; otherwise discard it and rebuild from the current view.
    $pausedCatalogBuild = $script:CatalogGridPageBuildState
    if ($pausedCatalogBuild -and
        [object]::ReferenceEquals($pausedCatalogBuild.View,$script:AppsView) -and
        [string]$pausedCatalogBuild.SearchText -ceq [string](C 'SearchBox').Text) {
        $script:SuppressSoftwareCategorySelectionChanged = $true
        try {
            $script:SelectedSoftwareCategory = [string]$pausedCatalogBuild.SelectedCategory
            $savedCategoryItem = @($script:SoftwareCategories | Where-Object { [string]$_.Name -eq [string]$pausedCatalogBuild.SelectedCategory } | Select-Object -First 1)
            if ($savedCategoryItem.Count -gt 0) { (C 'SoftwareCategoryList').SelectedItem = $savedCategoryItem[0] }
            else { (C 'SoftwareCategoryList').SelectedIndex = 0 }
        } finally { $script:SuppressSoftwareCategorySelectionChanged = $false }
        $script:SoftwareGridPageMode = 'Catalog'
        $catalogGrid = C 'SoftwareGrid'
        if ($pausedCatalogBuild.FirstPageCommitted -and $pausedCatalogBuild.PageItems) {
            $script:SoftwareGridPageItems = $pausedCatalogBuild.PageItems
            $script:SoftwareGridPageIndex = [int]$pausedCatalogBuild.PageItems.Count
            if (-not [object]::ReferenceEquals($catalogGrid.ItemsSource,$pausedCatalogBuild.PageItems)) {
                $catalogGrid.ItemsSource = $pausedCatalogBuild.PageItems
            }
        }
        try {
            $restoreOffset = [double]$pausedCatalogBuild.ScrollOffset
            $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                try { (C 'SoftwareScrollViewer').ScrollToVerticalOffset($restoreOffset) } catch {}
            }, [System.Windows.Threading.DispatcherPriority]::Loaded)
        } catch {}
        if ($pausedCatalogBuild.Timer) { $pausedCatalogBuild.Timer.Start() }
    } else {
        if ($pausedCatalogBuild) {
            try { if ($pausedCatalogBuild.Timer) { $pausedCatalogBuild.Timer.Stop() } } catch {}
            try { if ($pausedCatalogBuild.ViewEnumerator) { $pausedCatalogBuild.ViewEnumerator.Dispose() } } catch {}
            $script:CatalogGridPageBuildState = $null
        }
        if ($script:AppsView) {
            $script:AppsView.Refresh()
            Reset-AMRSoftwareGridPages -View $script:AppsView
        }
    }

    Invoke-AMRSoftwareGridViewTransition
    Resume-AMRSoftwareCatalogPaging -DelayMilliseconds 600
}

function Set-AMRInstalledViewVisible {
    param(
        [int]$InstalledCount,
        [switch]$PreserveCurrentView
    )

    Suspend-AMRSoftwareCatalogPaging
    if ($script:CatalogGridPageBuildState) {
        # Keep the exact enumerator and partial ordered items while Installed owns
        # the visible surface. Resume only after the catalog surface returns.
        try { if ($script:CatalogGridPageBuildState.Timer) { $script:CatalogGridPageBuildState.Timer.Stop() } } catch {}
        Write-AMRLog 'Paused the in-progress catalog builder without disposing its enumerator or partial ordered items.' INFO Software
    }

    # A background inventory refresh may complete while the user is on Show All.
    # Never resume a paused Installed build that belongs to an older inventory generation.
    if ($script:InstalledViewPreparationState -and
        [int]$script:InstalledViewPreparationState.InventoryGeneration -ne [int]$script:InstalledInventoryGeneration) {
        try { if ($script:InstalledViewPreparationState.Timer) { $script:InstalledViewPreparationState.Timer.Stop() } } catch {}
        $script:InstalledViewPreparationState = $null
        Write-AMRLog 'Discarded paused Installed mapping state because the inventory generation changed.' INFO Software
    }
    if ($script:InstalledGridPageBuildState -and
        [int]$script:InstalledGridPageBuildState.InventoryGeneration -ne [int]$script:InstalledInventoryGeneration) {
        try { if ($script:InstalledGridPageBuildState.Timer) { $script:InstalledGridPageBuildState.Timer.Stop() } } catch {}
        try { if ($script:InstalledGridPageBuildState.ViewEnumerator) { $script:InstalledGridPageBuildState.ViewEnumerator.Dispose() } } catch {}
        $script:InstalledGridPageBuildState = $null
        Write-AMRLog 'Discarded paused Installed card-ordering state because the inventory generation changed.' INFO Software
    }

    # If the user switched away while Installed was still being prepared, resume that exact work.
    # Do not clear the partially processed inventory or restart its dispatcher batches.
    if (-not $PreserveCurrentView -and $script:InstalledViewPreparationState -and $script:InstalledViewPreparationState.Timer) {
        $script:ShowInstalledOnly = $true
        if ($script:ProgressText) { $script:ProgressText.Text = 'Resuming installed applications...' }
        $script:InstalledViewPreparationState.Timer.Start()
        Write-AMRLog 'Resumed the paused Installed inventory-to-card preparation at its previous index.' INFO Software
        return
    }
    if (-not $PreserveCurrentView -and $script:InstalledGridPageBuildState -and $script:InstalledGridPageBuildState.Timer) {
        $script:ShowInstalledOnly = $true
        $buildState = $script:InstalledGridPageBuildState
        if ($buildState.FirstPageCommitted -and $buildState.PageItems) {
            $script:SoftwareGridPageMode = 'Installed'
            $script:SoftwareGridPageItems = $buildState.PageItems
            $script:SoftwareGridPageIndex = [int]$buildState.PageItems.Count
            $activeInstalledGrid = C 'SoftwareGrid'
            if (-not [object]::ReferenceEquals($activeInstalledGrid.ItemsSource,$script:SoftwareGridPageItems)) {
                $activeInstalledGrid.ItemsSource = $script:SoftwareGridPageItems
            }
            Invoke-AMRSoftwareGridViewTransition
        }
        if ($script:ProgressText) { $script:ProgressText.Text = 'Resuming installed application cards...' }
        $buildState.Timer.Start()
        Write-AMRLog 'Resumed the paused Installed category-ordering/page build at its previous phase and index.' INFO Software
        return
    }

    # Reattach the already-prepared Installed view when its inventory and filter are unchanged.
    # A deferred background inventory update increments the generation and invalidates
    # this cache, so the next explicit entry builds once from the fresh snapshot.
    $savedInstalledView = $script:InstalledViewCache
    if (-not $PreserveCurrentView -and $savedInstalledView -and
        [int]$savedInstalledView.InventoryGeneration -eq [int]$script:InstalledInventoryGeneration -and
        [string]$savedInstalledView.SearchText -ceq [string](C 'SearchBox').Text) {
        try {
            $script:ShowInstalledOnly = $true
            $script:InstalledAppsInventory = $savedInstalledView.Inventory
            $script:InstalledAppsView = $savedInstalledView.View
            $script:SoftwareGridPageMode = 'Installed'
            $script:SoftwareGridPageSource = $savedInstalledView.PageSource
            $script:SoftwareGridPageItems = $savedInstalledView.PageItems
            $script:SoftwareGridPageIndex = [int]$savedInstalledView.PageIndex
            $script:SoftwareGridPageSize = 4
            $script:SelectedSoftwareCategory = [string]$savedInstalledView.SelectedCategory
            # The cache generation and search text were validated above. Refreshing
            # this CollectionView here is unnecessary and can regenerate every card
            # container during a simple view switch, producing a visible second pass.
            $activeInstalledGrid = C 'SoftwareGrid'
            if (-not [object]::ReferenceEquals($activeInstalledGrid.ItemsSource,$script:SoftwareGridPageItems)) {
                $activeInstalledGrid.ItemsSource = $script:SoftwareGridPageItems
            }
            $script:SuppressSoftwareCategorySelectionChanged = $true
            try {
                $categoryItem = @($script:SoftwareCategories | Where-Object { [string]$_.Name -eq [string]$savedInstalledView.SelectedCategory } | Select-Object -First 1)
                if ($categoryItem.Count -gt 0) { (C 'SoftwareCategoryList').SelectedItem = $categoryItem[0] }
                else { (C 'SoftwareCategoryList').SelectedIndex = 0 }
            } finally { $script:SuppressSoftwareCategorySelectionChanged = $false }
            Invoke-AMRSoftwareGridViewTransition
            Start-AMRSoftwareGridWarmup
            $button = C 'ShowInstalledBtn'
            if ($button) {
                $button.Content = "Show All ($InstalledCount)"
                $button.ToolTip = 'Return to the full software catalog.'
                $button.IsEnabled = $true
            }
            (C 'UninstallSelectedBtn').Visibility = 'Visible'
            Set-AMRShowInstalledButtonBusy -Busy $false -Label "Show All ($InstalledCount)"
            Set-AMRShowInstalledButtonMode -Mode Installed
            if ($script:ProgressText) { $script:ProgressText.Text = '' }
            $scroll = C 'SoftwareScrollViewer'
            if ($scroll) {
                $restoreOffset = [double]$savedInstalledView.ScrollOffset
                $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                    try { (C 'SoftwareScrollViewer').ScrollToVerticalOffset($restoreOffset) } catch {}
                }, [System.Windows.Threading.DispatcherPriority]::Loaded)
            }
            # A6: a restore must also guarantee icons (re-apply the stored frozen icons, resume discovery for the rest).
            try { Start-AMRInstalledLocalIconRefresh -Source 'memory-restore' }
            catch { Write-AMRLog "Installed icon pass after restore failed: $($_.Exception.Message)" WARNING Software }
            Write-AMRLog ('Installed entry: path=restore; generation={0}; cards={1}.' -f [int]$script:InstalledInventoryGeneration,@($script:InstalledAppsInventory).Count) INFO Software
            Write-AMRLog 'Restored the existing Installed card collection from memory; inventory mapping and card ordering were skipped.' INFO Software
            return
        } catch {
            Write-AMRLog ("Installed view cache restore failed; rebuilding safely: " + $_.Exception.Message) WARNING Software
            Clear-AMRInstalledViewCache -Reason 'restore-failed'
        }
    }

    if (-not $PreserveCurrentView) {
        $entryReason = 'unknown'
        if ($null -eq $savedInstalledView) {
            $entryReason = $(if ([string]$script:AMRInstalledViewCacheClearReason) { 'saved view was cleared: ' + [string]$script:AMRInstalledViewCacheClearReason } else { 'no completed Installed view saved yet' })
        } elseif ([int]$savedInstalledView.InventoryGeneration -ne [int]$script:InstalledInventoryGeneration) {
            $entryReason = ('inventory generation differs (saved={0}; current={1})' -f [int]$savedInstalledView.InventoryGeneration,[int]$script:InstalledInventoryGeneration)
        } elseif ([string]$savedInstalledView.SearchText -cne [string](C 'SearchBox').Text) {
            $entryReason = 'search text differs'
        } else { $entryReason = 'restore failed' }
        Write-AMRLog ('Installed entry: path=build; reason={0}.' -f $entryReason) INFO Software
    }

    # Use one loading path for both cached and freshly scanned inventory.
    # Keep the button animation alive while inventory records and cards are
    # prepared in small UI-thread batches, allowing WPF to render between batches.
    if (-not $script:ShowInstalledOnly -and -not $script:ShowInstalledButtonBusyState.Active) {
        Set-AMRShowInstalledButtonBusy -Busy $true -Label 'Scanning...'
    }

    $wasInstalledViewVisible = [bool]$script:ShowInstalledOnly
    $restoreCategory = ''
    $restoreScrollOffset = 0.0
    if ($PreserveCurrentView) {
        $restoreCategory = [string]$script:SelectedSoftwareCategory
        try { $restoreScrollOffset = [double](C 'SoftwareScrollViewer').VerticalOffset } catch {}
    }

    $script:ShowInstalledOnly = $true
    $inventoryGenerationAtStart = [int]$script:InstalledInventoryGeneration
    $inventorySnapshot = @(
        foreach ($inventoryRecord in @($script:InstalledScanState.Inventory)) {
            if ($inventoryRecord -and [bool]$inventoryRecord.IsUserFacing -and [bool]$inventoryRecord.CanUninstall) { $inventoryRecord }
        }
    )
    $InstalledCount = [int]$inventorySnapshot.Count
    # Capture the original collection before creating the DispatcherTimer closure.
    # GetNewClosure() has its own script scope, so $script: references inside the
    # callback must not be used to reach this collection.
    $installedAppsInventory = $script:InstalledAppsInventory
    $installedAppsInventory.Clear()

    # Build catalog lookup tables incrementally instead of blocking the UI
    # before the first dispatcher tick. Preserve ID-first/name-fallback matching.
    $catalogLookupCached = [bool](
        $script:InstalledCatalogLookupById -and
        $script:InstalledCatalogLookupByName -and
        [object]::ReferenceEquals($script:InstalledCatalogLookupSource,$script:SoftwareCatalog)
    )
    $work = [pscustomobject]@{
        Inventory = $inventorySnapshot
        Index = 0
        CatalogSnapshot = $script:SoftwareCatalog
        CatalogIndex = if ($catalogLookupCached) { $script:SoftwareCatalog.Count } else { 0 }
        CatalogById = if ($catalogLookupCached) { $script:InstalledCatalogLookupById } else { @{} }
        CatalogByName = if ($catalogLookupCached) { $script:InstalledCatalogLookupByName } else { @{} }
        LookupReady = $catalogLookupCached
        LookupCachePublished = $catalogLookupCached
        TickBudgetMilliseconds = 5
        InventoryGeneration = $inventoryGenerationAtStart
        Timer = $null
    }
    $script:InstalledViewPreparationState = $work

    $timer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
    $timer.Interval = [TimeSpan]::FromMilliseconds(15)
    $work.Timer = $timer

    $timer.Add_Tick({
        try {
            $watch = [System.Diagnostics.Stopwatch]::StartNew()

            # Phase A: incrementally build lookup tables, yielding to WPF every
            # few milliseconds even when the software catalog is large.
            while (-not $work.LookupReady -and $watch.ElapsedMilliseconds -lt $work.TickBudgetMilliseconds) {
                if ($work.CatalogIndex -ge $work.CatalogSnapshot.Count) {
                    $work.LookupReady = $true
                    break
                }
                $catalogApp = $work.CatalogSnapshot[$work.CatalogIndex]
                $catalogId = [string]$catalogApp.Id
                if ($catalogId) { $work.CatalogById[$catalogId.ToLowerInvariant()] = $catalogApp }
                $catalogName = ([string]$catalogApp.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                if ($catalogName -and -not $work.CatalogByName.ContainsKey($catalogName)) { $work.CatalogByName[$catalogName] = $catalogApp }
                # Add vendor-free aliases so registry names such as Firefox 64 or
                # Autodesk AutoCAD 2024 still resolve to the catalog's category.
                $catalogAlias = $catalogName -replace '^(?:microsoft|mozilla|google|apple|autodesk|videolan|rarlab)',''
                $catalogAlias = $catalogAlias -replace '(?:32|64)$',''
                $catalogAlias = $catalogAlias -replace '(?:19|20)\d{2}$',''
                if ($catalogAlias.Length -ge 3 -and -not $work.CatalogByName.ContainsKey($catalogAlias)) { $work.CatalogByName[$catalogAlias] = $catalogApp }
                $work.CatalogIndex++
            }
            if (-not $work.LookupReady) { return }
            if (-not $work.LookupCachePublished) {
                # The catalog is static for this app session. Retain its lookup
                # indexes so subsequent Show Installed switches skip rebuilding
                # 1,920 ID/name entries before matching the already-known inventory.
                $script:InstalledCatalogLookupSource = $work.CatalogSnapshot
                $script:InstalledCatalogLookupById = $work.CatalogById
                $script:InstalledCatalogLookupByName = $work.CatalogByName
                $work.LookupCachePublished = $true
            }

            $batchEnd = [Math]::Min($work.Index + 64, $work.Inventory.Count)
            while ($work.Index -lt $batchEnd -and $watch.ElapsedMilliseconds -lt $work.TickBudgetMilliseconds) {
                $record = $work.Inventory[$work.Index]
                $work.Index++

                $record.IsUniversalInventory = $true
                $record.DetailsExpanded = $false
                # Preserve a category assigned by the inventory-side canonical matcher.
                $copyablePath = if (-not [string]::IsNullOrWhiteSpace([string]$record.InstallLocation)) { [string]$record.InstallLocation } elseif (-not [string]::IsNullOrWhiteSpace([string]$record.PortableRootFolder)) { [string]$record.PortableRootFolder } elseif (-not [string]::IsNullOrWhiteSpace([string]$record.PortableExecutablePath)) { [string]$record.PortableExecutablePath } elseif (-not [string]::IsNullOrWhiteSpace([string]$record.PackageFamilyName)) { [string]$record.PackageFamilyName } else { '' }
                $record.HasCopyableInstallPath = -not [string]::IsNullOrWhiteSpace($copyablePath)
                $record.DisplayInstallPath = if ($record.HasCopyableInstallPath) { $copyablePath } else { 'Not recorded by Windows' }
                $recordNorm = ([string]$record.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                $match = $null
                $recordId = [string]$record.Id
                if ($recordId -and $work.CatalogById.ContainsKey($recordId.ToLowerInvariant())) { $match = $work.CatalogById[$recordId.ToLowerInvariant()] }
                elseif ($recordNorm -and $work.CatalogByName.ContainsKey($recordNorm)) { $match = $work.CatalogByName[$recordNorm] }
                if ($null -eq $match -and [string]::IsNullOrWhiteSpace([string]$record.Category)) {
                    $recordAlias = $recordNorm -replace '^(?:microsoft|mozilla|google|apple|autodesk|videolan|rarlab)',''
                    $recordAlias = $recordAlias -replace '(?:32|64)$',''
                    $recordAlias = $recordAlias -replace '(?:19|20)\d{2}$',''
                    if ($recordAlias.Length -ge 3 -and $work.CatalogByName.ContainsKey($recordAlias)) { $match = $work.CatalogByName[$recordAlias] }
                    elseif ($recordAlias -match '^(?:firefox|chrome|edge|brave|opera|vivaldi|torbrowser|chromium|waterfox|librewolf)') {
                        $record.Category = '01. Web Browsers'
                    } elseif ($recordAlias -match '^(?:winrar|7zip|peazip|nanazip|bandizip|winzip|izarc|bzip2|zstandard|tar)') {
                        $record.Category = '04. Compression'
                    }
                }
                if ($null -ne $match) {
                    $record.IsCatalogApp = $true
                    $record.CatalogId = [string]$match.Id
                    $record.Category = [string]$match.Category
                    if ($null -eq $record.Icon) { $record.Icon = $match.Icon }
                }
                [void]$installedAppsInventory.Add($record)
            }

            if ($work.Index -lt $work.Inventory.Count) { return }

            $work.Timer.Stop()
            Clear-AMRInstalledViewPreparationState
            $installedAppsView = Initialize-AMRInstalledViewContext -Inventory $installedAppsInventory -RestoreCategory $restoreCategory

            # Build category ordering and the first visible card page in separate
            # Dispatcher batches; do not block WPF while preparing the card set.
            Start-AMRInstalledGridPageBuild `
                -View $installedAppsView `
                -WasInstalledViewVisible $wasInstalledViewVisible `
                -InstalledCount $installedAppsInventory.Count `
                -RestoreCategory $restoreCategory `
                -RestoreScrollOffset $restoreScrollOffset `
                -InventoryGeneration $inventoryGenerationAtStart
        }
        catch {
            try { $work.Timer.Stop() } catch {}
            Clear-AMRInstalledViewPreparationState
            if (-not $wasInstalledViewVisible) {
                Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
                Reset-AMRInstalledViewAfterPreparationFailure
            }
            $diagnosticDetails = Get-AMRShowInstalledDiagnosticDetails -ErrorRecord $_ -Stage 'Installed view preparation'
            Write-AMRLog "Could not prepare the Show Installed view:`n$diagnosticDetails" ERROR Software
            Show-AMRMessageGlass "Could not prepare the installed-applications view:`n`n$diagnosticDetails" 'Installed Apps' OK Error | Out-Null
        }
    }.GetNewClosure())

    $timer.Start()
}


# A7: the Installed inventory is compared by application identity + version (+ the two flags that decide
# whether a card exists). Display-only fields (name text, publisher, source, uninstall method) no longer
# invalidate the cached Installed view; a real install, uninstall or version change still does.
function Get-AMRInstalledInventorySignature {
    param([object]$Record)
    $identity = [string](Get-AMRShowInstalledProperty $Record 'IdentityKey')
    if ([string]::IsNullOrWhiteSpace($identity)) { $identity = [string](Get-AMRShowInstalledProperty $Record 'Id') }
    if ([string]::IsNullOrWhiteSpace($identity)) { $identity = [string](Get-AMRShowInstalledProperty $Record 'Name') }
    return ('{0}|{1}|{2}|{3}' -f $identity,[string](Get-AMRShowInstalledProperty $Record 'DisplayVersion'),[bool](Get-AMRShowInstalledProperty $Record 'CanUninstall'),[bool](Get-AMRShowInstalledProperty $Record 'IsUserFacing'))
}

# A7: every place that discards the saved Installed view records why, so the next entry can log the reason.
$script:AMRInstalledViewCacheClearReason = ''
function Clear-AMRInstalledViewCache {
    param([string]$Reason)
    $script:InstalledViewCache = $null
    $script:AMRInstalledViewCacheClearReason = $Reason
}

# A8 (measurement only): every helper below swallows its own errors and never changes behavior.
function Get-AMRPerfNow { try { return [long][AMR.PerfStats]::Now() } catch { return [long]0 } }
function Add-AMRPerfSince {
    param([string]$Key,[long]$Start)
    if ($Start -eq 0) { return }
    try { [AMR.PerfStats]::Add($Key,[AMR.PerfStats]::Now() - $Start) } catch {}
}
# A11 (measurement only): readable tab names. A TabItem whose Header is not a plain string (for example the Driver Center tab) was logged as 'System.Windows.Controls.TextBlock'.
function Get-AMRPerfTabHeader {
    param($Item)
    try {
        if ($null -eq $Item) { return '' }
        $perfHeader = $Item.Header
        if ($perfHeader -is [string] -and -not [string]::IsNullOrWhiteSpace($perfHeader)) { return [string]$perfHeader }
        $perfName = ''
        try { $perfName = [string]$Item.Name } catch {}
        if (-not [string]::IsNullOrWhiteSpace($perfName)) { return $perfName }
        if ($perfHeader -is [System.Windows.Controls.TextBlock]) { return [string]$perfHeader.Text }
        return [string]$perfHeader
    } catch { return '' }
}
function Get-AMRPerfTabContext {
    try {
        $perfMain = C 'MainNavigationTabs'
        $perfText = ''
        if ($perfMain -and $perfMain.SelectedItem) { $perfText = Get-AMRPerfTabHeader $perfMain.SelectedItem }
        $perfSub = C 'OverviewSubTabs'
        if ($perfText -eq 'System' -and $perfSub -and $perfSub.SelectedItem) { $perfText += '/' + (Get-AMRPerfTabHeader $perfSub.SelectedItem) }
        return $perfText
    } catch { return '' }
}
$script:AMRPerfMarks = New-Object 'System.Collections.Generic.List[string]'
function Set-AMRPerfMark {
    param([string]$Name)
    try {
        $markStamp = [int](([Environment]::TickCount -band 0x7FFFFFFF) % 100000)
        $script:AMRPerfMarks.Add(('{0}@{1}' -f $Name,$markStamp))
        if ($script:AMRPerfMarks.Count -gt 10) { $script:AMRPerfMarks.RemoveAt(0) }
    } catch {}
}
# UI-thread stall detector: a normal-priority timer that should fire every 100 ms. If it fires much later,
# the UI thread was busy; the log then lists the most recent named activities (marks) to attribute it.
$script:AMRStallLastTicks = [long]0
$script:AMRStallLogged = 0
# A9: this variable is read (if ($script:AMRStallTimer)) before it is ever assigned. Under StrictMode that read throws and the
# surrounding catch hid it, so the stall timer never started in A8. Initialize it.
$script:AMRStallTimer = $null
function Start-AMRUiStallWatch {
    try {
        if ($script:AMRStallTimer) { return }
        $script:AMRStallTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:AMRStallTimer.Interval = [TimeSpan]::FromMilliseconds(100)
        $script:AMRStallLastTicks = [DateTime]::UtcNow.Ticks
        $script:AMRStallTimer.Add_Tick({
            try {
                $nowTicks = [DateTime]::UtcNow.Ticks
                $lateMs = [int](($nowTicks - $script:AMRStallLastTicks) / 10000) - 100
                $script:AMRStallLastTicks = $nowTicks
                if ($lateMs -ge 90 -and $lateMs -lt 20000) {
                    try { [AMR.PerfStats]::Count('ui.stallsOver90ms',1) } catch {}
                    try { [AMR.PerfStats]::Add('ui.stallMs',[long]($lateMs * [System.Diagnostics.Stopwatch]::Frequency / 1000)) } catch {}
                    if ($script:AMRStallLogged -lt 150) {
                        $script:AMRStallLogged++
                        $softwareActive = $false
                        try { $softwareActive = [bool]((C 'SoftwareGrid').IsVisible) } catch {}
                        Write-AMRLog ('UI stall: the UI thread was busy about {0} ms (softwareGridVisible={1}; installedOnly={2}; tab={4}; recent={3}).' -f $lateMs,$softwareActive,[bool]$script:ShowInstalledOnly,($script:AMRPerfMarks -join ','),(Get-AMRPerfTabContext)) INFO Software
                    }
                }
            } catch {}
        })
        $script:AMRStallTimer.Start()
    } catch {}
}
$script:AMRSearchStartTicks = [long]0

function Complete-AMRInstalledCatalogScan {
    param($JobState)

    $job = $JobState.Current
    if (-not $job) { return }

    $outputItems = @()
    $workerError = ''
    $workerDiagEndInvoke = ''
    $workerDiagStreams = ''
    $workerDiagStage = ''
    $workerDiagStreamErrorCount = 0
    try {
        $outputItems = @($job.PowerShell.EndInvoke($job.AsyncResult))
    } catch {
        # Diagnostics only: keep the full exception (type, inner exceptions, stack) for the failure log below.
        try { $workerDiagEndInvoke = Get-AMRShowInstalledDiagnosticDetails -ErrorRecord $_ -Stage 'Inventory worker EndInvoke' } catch {}
        $workerError = $_.Exception.Message
    }
    try { $workerDiagStage = [string]$job.Diag['Stage'] } catch {}
    try { $workerDiagStreamErrorCount = [int]$job.PowerShell.Streams.Error.Count } catch {}

    if (-not $workerError -and $job.PowerShell.Streams.Error.Count -gt 0) {
        # Diagnostics only: describe each non-terminating error record (first 5), including the failing line and stack.
        try {
            $streamDetailParts = New-Object 'System.Collections.Generic.List[string]'
            $streamDetailIndex = 0
            foreach ($streamRecord in @($job.PowerShell.Streams.Error)) {
                $streamDetailIndex++
                if ($streamDetailIndex -gt 5) { break }
                $streamDetailParts.Add(('--- Error record {0} ---{1}{2}' -f $streamDetailIndex,[Environment]::NewLine,(Get-AMRShowInstalledDiagnosticDetails -ErrorRecord $streamRecord -Stage 'Inventory worker error stream')))
            }
            $workerDiagStreams = ($streamDetailParts -join [Environment]::NewLine)
        } catch {}
        $workerError = (($job.PowerShell.Streams.Error | ForEach-Object { $_.ToString() }) -join "`n")
    }

    $payload = $null
    foreach ($outputItem in $outputItems) {
        if ($null -ne $outputItem -and $outputItem.PSObject.Properties['InstalledFlags']) {
            $payload = $outputItem
        }
    }
    if (-not $payload -and -not $workerError) {
        $workerError = 'The background inventory worker completed without returning a valid result.'
    }

    try { $job.PowerShell.Dispose() } catch {}
    try { $job.Runspace.Close(); $job.Runspace.Dispose() } catch {}
    $JobState.Current = $null

    if ($payload -and -not $workerError) {
        $flags = @($payload.InstalledFlags)
        if ($flags.Count -ne $script:SoftwareCatalog.Count) {
            $workerError = "Inventory result size mismatch. Expected $($script:SoftwareCatalog.Count), received $($flags.Count)."
        } else {
            $changedInstalledCards = New-Object 'System.Collections.Generic.HashSet[string]'
            for ($index = 0; $index -lt $script:SoftwareCatalog.Count; $index++) {
                $catalogCard = $script:SoftwareCatalog[$index]
                $previousInstalled = $catalogCard.IsInstalled
                $newInstalled = [bool]$flags[$index]
                if ($null -eq $previousInstalled -or [bool]$previousInstalled -ne $newInstalled) { [void]$changedInstalledCards.Add([string]$catalogCard.Id) }
                $catalogCard.IsInstalled = $newInstalled
            }

            # Catalog cards use PSCustomObject records, so refresh the visible
            # catalog after the background scan to re-evaluate IsInstalled bindings.
            # Preserve the current scroll position, category, search text and filters.
            if (-not $script:ShowInstalledOnly -and $script:AppsView) {
                try {
                    # The catalog card objects are the same objects whose IsInstalled flags
                    # were updated above. Refresh only the active collection view and re-notify
                    # realized card bindings; do not rebuild the catalog page or reset paging.
                    $script:AppsView.Refresh()
                    $visibleCards = $script:SoftwareGridPageItems
                    for ($cardIndex = 0; $cardIndex -lt $visibleCards.Count; $cardIndex++) {
                        # Re-notify only cards whose installed state actually changed.
                        # Category spacer/header rows are PSCustomObjects without an Id property.
                        $visibleCard = $visibleCards[$cardIndex]
                        if ($null -eq $visibleCard -or $null -eq $visibleCard.PSObject.Properties['Id']) { continue }
                        if ($changedInstalledCards.Contains([string]$visibleCard.Id)) {
                            $visibleCards[$cardIndex] = $visibleCard
                        }
                    }
                } catch {
                    # Diagnostics only (file log, never the in-app Logs tab).
                    try {
                        $diagOuterError = $_
                        $diagItemType = '<n/a>'; $diagItemProps = ''
                        try {
                            if ($null -ne $visibleCards -and $cardIndex -ge 0 -and $cardIndex -lt $visibleCards.Count) {
                                $diagItem = $visibleCards[$cardIndex]
                                if ($null -eq $diagItem) { $diagItemType = '<null>' } else { $diagItemType = $diagItem.GetType().FullName; $diagItemProps = (($diagItem.PSObject.Properties | Select-Object -First 12 | ForEach-Object { $_.Name }) -join ',') }
                            }
                        } catch { $diagItemType = '<inspect failed: ' + $_.Exception.Message + '>' }
                        $diagCount = $(if ($null -ne $visibleCards) { [string]$visibleCards.Count } else { '<null>' })
                        $diagCollType = $(if ($null -ne $visibleCards) { $visibleCards.GetType().FullName } else { '<null>' })
                        Write-AMRDiagnostic -Severity 'WARNING' -Area 'Software' -Operation 'InstalledIndicatorRefreshFailure' -Message ("Indicator refresh failed | CardIndex={0} | PageItems={1} | CollectionType={2} | ItemType={3} | ItemProperties={4} | ChangedCards={5} | AppsViewNull={6}" -f $cardIndex,$diagCount,$diagCollType,$diagItemType,$diagItemProps,$changedInstalledCards.Count,($null -eq $script:AppsView)) -ErrorRecord $diagOuterError
                    } catch { }
                    Write-AMRLog "Could not refresh installed indicators in the software catalog: $($_.Exception.Message)" WARNING Software
                }
            }

            $previousInventory = $JobState.Inventory
            $freshInventory = $payload.Inventory
            $inventoryChanged = $true
            $wasReadyBeforeScan = [bool]$JobState.Ready
            $compareAdded = -1
            $compareRemoved = -1
            $compareSample = ''
            if ($JobState.Ready) {
                try {
                    # Multiset comparison in linear time (no sorting on the UI thread).
                    $previousCounts = [System.Collections.Generic.Dictionary[string,int]]::new([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($record in $previousInventory) {
                        $signature = Get-AMRInstalledInventorySignature -Record $record
                        if ($previousCounts.ContainsKey($signature)) { $previousCounts[$signature] = [int]$previousCounts[$signature] + 1 }
                        else { $previousCounts[$signature] = 1 }
                    }
                    $freshCounts = [System.Collections.Generic.Dictionary[string,int]]::new([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($record in $freshInventory) {
                        $signature = Get-AMRInstalledInventorySignature -Record $record
                        if ($freshCounts.ContainsKey($signature)) { $freshCounts[$signature] = [int]$freshCounts[$signature] + 1 }
                        else { $freshCounts[$signature] = 1 }
                    }
                    $compareAdded = 0
                    $compareRemoved = 0
                    foreach ($pair in $freshCounts.GetEnumerator()) {
                        $before = 0
                        [void]$previousCounts.TryGetValue($pair.Key,[ref]$before)
                        if ([int]$pair.Value -gt $before) {
                            $compareAdded += ([int]$pair.Value - $before)
                            if (-not $compareSample) { $compareSample = 'added ' + $pair.Key }
                        }
                    }
                    foreach ($pair in $previousCounts.GetEnumerator()) {
                        $after = 0
                        [void]$freshCounts.TryGetValue($pair.Key,[ref]$after)
                        if ([int]$pair.Value -gt $after) {
                            $compareRemoved += ([int]$pair.Value - $after)
                            if (-not $compareSample) { $compareSample = 'removed ' + $pair.Key }
                        }
                    }
                    $inventoryChanged = ($compareAdded -gt 0 -or $compareRemoved -gt 0)
                } catch {
                    $inventoryChanged = $true
                    $compareSample = 'compare failed: ' + $_.Exception.Message
                }
            }
            Write-AMRLog ('Installed scan compare: changed={0}; added={1}; removed={2}; records={3}; firstDifference={4}.' -f $inventoryChanged,$compareAdded,$compareRemoved,@($freshInventory).Count,$(if ($compareSample) { $compareSample } else { 'none' })) INFO Software

            $JobState.Ready = $true
            $JobState.Count = [int](@($freshInventory | Where-Object { $_.IsUserFacing -and $_.CanUninstall }).Count)
            $JobState.Inventory = $freshInventory
            if ($inventoryChanged) {
                # A7: the very first scan of a session has nothing built from an older inventory, so it must not
                # invalidate anything (that was the cold-start false generation change).
                $hasStaleDerivedState = [bool]($script:InstalledViewCache -or $script:InstalledAppsView -or $script:InstalledViewPreparationState -or $script:InstalledGridPageBuildState)
                if ($wasReadyBeforeScan -or $hasStaleDerivedState) {
                    $script:InstalledInventoryGeneration = [int]$script:InstalledInventoryGeneration + 1
                    Clear-AMRInstalledViewCache -Reason $(if ($wasReadyBeforeScan) { 'inventory-content-changed' } else { 'first-scan-with-existing-view' })
                    Write-AMRLog ('Installed inventory generation is now {0}.' -f [int]$script:InstalledInventoryGeneration) INFO Software
                } else {
                    Write-AMRLog 'First Installed scan of this session: generation kept (nothing was built from an older inventory).' INFO Software
                }
            }
            $JobState.Error = ''
            [void](Save-AMRInstalledInventoryCache)

            # Rebuild the visible Installed cards only when the actual inventory changed.
            # An unchanged background refresh must not interrupt or restart a warm view.
            if ($inventoryChanged -and $script:ShowInstalledOnly -and -not $JobState.PendingShow -and
                ($script:InstalledAppsView -or $script:InstalledViewPreparationState -or $script:InstalledGridPageBuildState)) {
                # Never clear/repopulate the currently visible Installed collection
                # underneath the user. Keep the displayed snapshot stable; the fresh
                # inventory is already saved in InstalledScanState and will be used
                # on the next explicit entry into Show Installed.
                $script:InstalledRefreshPending = $true
                Write-AMRLog 'Installed inventory changed during an active Installed view; deferred visual refresh to the next entry to prevent cards disappearing and being recreated.' INFO Software
            }
            foreach ($entry in @($payload.Logs)) {
                if ($entry -and $entry.Message) {
                    $level = if ($entry.Level) { [string]$entry.Level } else { 'INFO' }
                    $area = if ($entry.Area) { [string]$entry.Area } else { 'Software' }
                    Write-AMRLog ([string]$entry.Message) $level $area
                }
            }
        }
    }

    if ($workerError) {
        # Keep a previously loaded/completed snapshot usable if only the refresh failed.
        # A first-run failure still leaves Ready=false and reports the error normally.
        $JobState.Error = $workerError
        Write-AMRLog "Background installed-app scan failed: $workerError" ERROR Software
        # Diagnostics only (no behavior change): explain where and why the worker failed.
        try {
            $diagFlagCount = -1; $diagInventoryCount = -1; $diagPayloadLogCount = -1
            if ($payload) {
                try { $diagFlagCount = @($payload.InstalledFlags).Count } catch {}
                try { $diagInventoryCount = @($payload.Inventory).Count } catch {}
                try { $diagPayloadLogCount = @($payload.Logs).Count } catch {}
            }
            Write-AMRLog ('Inventory worker failure diagnostics | LastWorkerStage={0} | PayloadReturned={1} | InstalledFlags={2} | InventoryRecords={3} | WorkerLogEntries={4} | StreamErrorRecords={5} | OutputItems={6}' -f $workerDiagStage,[bool]$payload,$diagFlagCount,$diagInventoryCount,$diagPayloadLogCount,$workerDiagStreamErrorCount,@($outputItems).Count) WARNING Software
            if ($workerDiagEndInvoke) { Write-AMRLog ("Inventory worker EndInvoke exception:`n" + $workerDiagEndInvoke) WARNING Software }
            if ($workerDiagStreams) { Write-AMRLog ("Inventory worker error stream:`n" + $workerDiagStreams) WARNING Software }
            if ($payload) {
                # The worker's own log lines are normally dropped when the scan is reported as failed.
                $diagLogShown = 0
                foreach ($entry in @($payload.Logs)) {
                    if ($diagLogShown -ge 60) { break }
                    if ($entry -and $entry.Message) { $diagLogShown++; Write-AMRLog ('Inventory worker log (scan reported failed) [{0}] {1}' -f [string]$entry.Level,[string]$entry.Message) INFO Software }
                }
            }
        } catch {}
        if ($JobState.PendingShow) {
            Resume-AMRSoftwareCatalogPaging -DelayMilliseconds 600
            Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
            $JobState.PendingShow = $false
            $script:SoftwareGridTransitionPending = $true
            Invoke-AMRSoftwareGridViewTransition
            Show-AMRMessageGlass "Could not finish the installed-app scan:`n`n$workerError" 'Installed Apps Scan' OK Error | Out-Null
        }
    }

    # If a refresh was requested while an older scan was running (for example,
    # immediately after uninstall), run a fresh scan before publishing the view.
    if ($JobState.RescanRequested) {
        $JobState.RescanRequested = $false
        $JobState.Ready = $false
        Start-AMRInstalledCatalogScan -ShowWhenReady:([bool]$JobState.PendingShow)
        return
    }

    if ($JobState.Ready -and $JobState.PendingShow) {
        $JobState.PendingShow = $false
        Set-AMRInstalledViewVisible -InstalledCount $JobState.Count
    }
}

function Start-AMRInstalledCatalogScan {
    param(
        [switch]$ShowWhenReady,
        [switch]$Refresh
    )

    $state = $script:InstalledScanState
    if ($ShowWhenReady) { $state.PendingShow = $true }

    if ($state.Current) {
        if ($Refresh) { $state.RescanRequested = $true }
        return
    }

    if ($state.Ready -and -not $Refresh) {
        if ($state.PendingShow) {
            $state.PendingShow = $false
            Set-AMRInstalledViewVisible -InstalledCount $state.Count
        }
        return
    }

    # Taken BEFORE the scan so an app installed while the scan runs is caught by the next check.
    $script:InstalledScanSignatureAtStart = Get-AMRInstalledChangeSignature

    $catalogSnapshot = @(
        foreach ($app in $script:SoftwareCatalog) {
            [pscustomobject]@{
                Name = [string]$app.Name
                Id = [string]$app.Id
                ChocoId = [string]$app.ChocoId
                Category = [string]$app.Category
                IsInstalled = $false
            }
        }
    )

    try {
        $inventoryCommand = Get-Command Update-AMRInstalledCatalogState -ErrorAction Stop
        $inventoryFunctionBody = $inventoryCommand.ScriptBlock.ToString()
        $matchCommand = Get-Command Set-AMRInstalledCatalogMatches -ErrorAction Stop
        $matchFunctionBody = $matchCommand.ScriptBlock.ToString()
        $universalCommand = Get-Command Get-AMRUniversalInstalledInventory -ErrorAction Stop
        $universalFunctionBody = $universalCommand.ScriptBlock.ToString()
        $recordCommand = Get-Command New-AMRInstalledInventoryRecord -ErrorAction Stop
        $recordFunctionBody = $recordCommand.ScriptBlock.ToString()
        $presentationCommand = Get-Command Set-AMRInstalledAppPresentation -ErrorAction Stop
        $presentationFunctionBody = $presentationCommand.ScriptBlock.ToString()
        $presentationNameCommand = Get-Command Get-AMRInstalledPresentationName -ErrorAction Stop
        $presentationNameFunctionBody = $presentationNameCommand.ScriptBlock.ToString()
        $cardShortNameCommand = Get-Command Get-AMRInstalledCardShortName -ErrorAction Stop
        $cardShortNameFunctionBody = $cardShortNameCommand.ScriptBlock.ToString()
        # Get-AMRUniversalInstalledInventory calls these two functions, so the worker runspace needs them too.
        $canonicalKeyCommand = Get-Command Get-AMRInstalledCanonicalNameKey -ErrorAction Stop
        $canonicalKeyFunctionBody = $canonicalKeyCommand.ScriptBlock.ToString()
        $dedupeCommand = Get-Command Remove-AMRDuplicateInstalledInventoryRecords -ErrorAction Stop
        $dedupeFunctionBody = $dedupeCommand.ScriptBlock.ToString()

        $workerScript = @'
param($CatalogSnapshot, $InventoryFunctionBody, $MatchFunctionBody, $UniversalFunctionBody, $RecordFunctionBody, $PresentationFunctionBody, $PresentationNameFunctionBody, $CardShortNameFunctionBody, $CanonicalKeyFunctionBody, $DedupeFunctionBody)
$ErrorActionPreference = 'Continue'
function Set-AMRWorkerStage { param([string]$Name) try { $global:AMRWorkerDiag['Stage'] = $Name } catch {} }
$script:AMRWorkerWatch = [System.Diagnostics.Stopwatch]::StartNew()
$script:SoftwareCatalog = @($CatalogSnapshot)
$script:InventoryLogs = New-Object 'System.Collections.Generic.List[object]'
function Write-AMRLog {
    param([string]$Message, [string]$Level, [string]$Area)
    try {
        [void]$script:InventoryLogs.Add([pscustomobject]@{
            Message = [string]$Message
            Level = [string]$Level
            Area = [string]$Area
        })
    } catch {}
}
$matchDefinition = "function Set-AMRInstalledCatalogMatches {`r`n" + $MatchFunctionBody + "`r`n}"
Invoke-Expression $matchDefinition
$definition = "function Update-AMRInstalledCatalogState {`r`n" + $InventoryFunctionBody + "`r`n}"
Invoke-Expression $definition
$recordDefinition = "function New-AMRInstalledInventoryRecord {`r`n" + $RecordFunctionBody + "`r`n}"
Invoke-Expression $recordDefinition
$presentationNameDefinition = "function Get-AMRInstalledPresentationName {`r`n" + $PresentationNameFunctionBody + "`r`n}"
Invoke-Expression $presentationNameDefinition
$cardShortNameDefinition = "function Get-AMRInstalledCardShortName {`r`n" + $CardShortNameFunctionBody + "`r`n}"
Invoke-Expression $cardShortNameDefinition
$presentationDefinition = "function Set-AMRInstalledAppPresentation {`r`n" + $PresentationFunctionBody + "`r`n}"
Invoke-Expression $presentationDefinition
$canonicalKeyDefinition = "function Get-AMRInstalledCanonicalNameKey {`r`n" + $CanonicalKeyFunctionBody + "`r`n}"
Invoke-Expression $canonicalKeyDefinition
$dedupeDefinition = "function Remove-AMRDuplicateInstalledInventoryRecords {`r`n" + $DedupeFunctionBody + "`r`n}"
Invoke-Expression $dedupeDefinition
$universalDefinition = "function Get-AMRUniversalInstalledInventory {`r`n" + $UniversalFunctionBody + "`r`n}"
Invoke-Expression $universalDefinition
Set-AMRWorkerStage 'Update-AMRInstalledCatalogState'
$scanResult = Update-AMRInstalledCatalogState
try { Write-AMRLog ('Inventory worker stage done: Update-AMRInstalledCatalogState at {0} ms (Count={1}, WingetRawOutputLength={2}).' -f $script:AMRWorkerWatch.ElapsedMilliseconds,$scanResult.Count,([string]$scanResult.WingetRawOutput).Length) INFO Software } catch {}
$flags = @($script:SoftwareCatalog | ForEach-Object { [bool]$_.IsInstalled })
# Reuse the WinGet output collected above; do not launch a second WinGet CLI scan.
Set-AMRWorkerStage 'Get-AMRUniversalInstalledInventory'
$inventory = @(Get-AMRUniversalInstalledInventory -WingetRawOutput ([string]$scanResult.WingetRawOutput) -SkipWingetScan)
try { Write-AMRLog ('Inventory worker stage done: Get-AMRUniversalInstalledInventory at {0} ms ({1} record(s)).' -f $script:AMRWorkerWatch.ElapsedMilliseconds,$inventory.Count) INFO Software } catch {}
Set-AMRWorkerStage 'returning-result'
[pscustomobject]@{
    Count = [int]$scanResult.Count
    InstalledFlags = $flags
    Inventory = $inventory
    Logs = @($script:InventoryLogs.ToArray())
}
'@

        $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $runspace.Open()
        $workerDiag = [hashtable]::Synchronized(@{ Stage = 'queued' })
        try { $runspace.SessionStateProxy.SetVariable('AMRWorkerDiag', $workerDiag) } catch {}
        $powerShell = [PowerShell]::Create()
        $powerShell.Runspace = $runspace
        [void]$powerShell.AddScript($workerScript)
        [void]$powerShell.AddArgument($catalogSnapshot)
        [void]$powerShell.AddArgument($inventoryFunctionBody)
        [void]$powerShell.AddArgument($matchFunctionBody)
        [void]$powerShell.AddArgument($universalFunctionBody)
        [void]$powerShell.AddArgument($recordFunctionBody)
        [void]$powerShell.AddArgument($presentationFunctionBody)
        [void]$powerShell.AddArgument($presentationNameFunctionBody)
        [void]$powerShell.AddArgument($cardShortNameFunctionBody)
        [void]$powerShell.AddArgument($canonicalKeyFunctionBody)
        [void]$powerShell.AddArgument($dedupeFunctionBody)
        $asyncResult = $powerShell.BeginInvoke()

        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromMilliseconds(150)
        $jobState = $state
        $job = [pscustomobject]@{
            PowerShell = $powerShell
            Runspace = $runspace
            AsyncResult = $asyncResult
            Timer = $timer
            Diag = $workerDiag
        }
        $state.Current = $job

        $timer.Add_Tick({
            $activeJob = $jobState.Current
            if (-not $activeJob) {
                $timer.Stop()
                return
            }
            if (-not $activeJob.AsyncResult.IsCompleted) { return }
            # A7: while the user is actively scrolling, applying the scan result waits until the scroll
            # has been quiet for 400 ms (never longer than 8 s, and never when the user is waiting for it).
            $deferredMs = 0
            try {
                if (-not $jobState.PendingShow) {
                    $nowTicks = [DateTime]::UtcNow.Ticks
                    if (($nowTicks - $script:AMRLastSoftwareScrollTicks) -lt 4000000) {
                        if ($script:AMRScanDeferStartTicks -eq 0) { $script:AMRScanDeferStartTicks = $nowTicks }
                        if (($nowTicks - $script:AMRScanDeferStartTicks) -lt 80000000) { return }
                    }
                }
                if ($script:AMRScanDeferStartTicks -ne 0) { $deferredMs = [int](([DateTime]::UtcNow.Ticks - $script:AMRScanDeferStartTicks) / 10000) }
            } catch {}
            $script:AMRScanDeferStartTicks = 0
            if ($deferredMs -gt 0) { Write-AMRLog ('Installed scan result applied after scrolling settled (waited {0} ms).' -f $deferredMs) INFO Software }
            $timer.Stop()
            Complete-AMRInstalledCatalogScan -JobState $jobState
        }.GetNewClosure())

        $timer.Start()
        Write-AMRLog 'Installed-app inventory scan started in the background. The interface remains available.' INFO Software
    } catch {
        $state.Error = $_.Exception.Message
        $state.Ready = $false
        $state.Current = $null
        Resume-AMRSoftwareCatalogPaging -DelayMilliseconds 600
        $script:SoftwareGridTransitionPending = $true
        Invoke-AMRSoftwareGridViewTransition
        Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
        Write-AMRLog "Could not start the background installed-app scan: $($_.Exception.Message)" ERROR Software
        if ($state.PendingShow) {
            $state.PendingShow = $false
            Show-AMRMessageGlass "Could not start the installed-app scan:`n`n$($_.Exception.Message)" 'Installed Apps Scan' OK Error | Out-Null
        }
    }
}

$script:AppsView.Filter = [System.Predicate[object]]{
    param($item)
    if ($script:ShowInstalledOnly -and -not $item.IsInstalled) { return $false }

    $selectedCategory = [string]$script:SelectedSoftwareCategory
    if (-not [string]::IsNullOrWhiteSpace($selectedCategory) -and
        $selectedCategory -ne 'All Applications' -and
        [string]$item.Category -ne $selectedCategory) { return $false }

    $searchText = (C 'SearchBox').Text
    if ([string]::IsNullOrWhiteSpace($searchText)) { return $true }
    $escaped = [regex]::Escape($searchText)
    return ($item.Name -match "(?i)$escaped") -or ($item.Id -match "(?i)$escaped")
}

# Keep the existing four-column UniformGrid and card template. Populate the
# grid incrementally so opening Software does not create the full catalog at once.
# Note: this is progressive paging, not true WPF virtualization. The current
# four-column UniformGrid remains non-virtualized; true recycling needs a panel refactor.
$script:SoftwareGridPageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:SoftwareGridPageSource = @()
$script:SoftwareGridPageIndex = 0
$script:SoftwareGridPageSize = 4
$script:SoftwareGridPageBusy = $false
$script:SoftwareGridPageDispatchPending = $false
$script:SoftwareGridWarmupTimer = $null
# Catalog paging is suspended while the Installed view is being prepared/displayed.
# Installed cards keep their own small progressive batches; only catalog prefetch is paused.
$script:SoftwareGridPagingPaused = $false
$script:SoftwareGridPageMode = 'Catalog'
$script:SoftwareGridResumeTimer = $null
# Set only for an intentional Show All / Show Installed view switch.
$script:SoftwareGridTransitionPending = $false
# Keep both views as live UI state. Switching tabs must not rebuild their cards.
$script:SoftwareCatalogViewCache = $null
$script:InstalledViewCache = $null
$script:InstalledInventoryGeneration = 0
$script:InstalledRefreshPending = $false

function Save-AMRSoftwareCatalogViewState {
    try {
        # A first row can already be visible while the catalog state machine is
        # still collecting/ordering the remaining categories. That is NOT a
        # complete cache: restoring it would permanently truncate Show All.
        if ($script:CatalogGridPageBuildState) {
            $script:SoftwareCatalogViewCache = $null
            try { $script:CatalogGridPageBuildState.ScrollOffset = [double](C 'SoftwareScrollViewer').VerticalOffset } catch {}
            Write-AMRLog 'Catalog build is still in progress; its enumerator, ordered items, and visible page will be paused and retained for Show All.' INFO Software
            return
        }

        $viewItemCount = 0
        try { $viewItemCount = [int]$script:AppsView.Count } catch { $viewItemCount = [int]$script:SoftwareCatalog.Count }
        if ($script:SoftwareGridPageSource.Count -lt $viewItemCount) {
            $script:SoftwareCatalogViewCache = $null
            Write-AMRLog ("Catalog cache rejected as incomplete: source has {0} entries for {1} filtered catalog items." -f $script:SoftwareGridPageSource.Count,$viewItemCount) WARNING Software
            return
        }

        $scroll = C 'SoftwareScrollViewer'
        $script:SoftwareCatalogViewCache = [pscustomobject]@{
            BuildComplete = $true
            ViewItemCount = $viewItemCount
            PageItems = $script:SoftwareGridPageItems
            PageSource = $script:SoftwareGridPageSource
            PageIndex = [int]$script:SoftwareGridPageIndex
            PageSize = [int]$script:SoftwareGridPageSize
            ScrollOffset = if ($scroll) { [double]$scroll.VerticalOffset } else { 0.0 }
            SelectedCategory = [string]$script:SelectedSoftwareCategory
            SearchText = [string](C 'SearchBox').Text
        }
        Write-AMRLog ("Saved completed catalog view state: {0}/{1} cards prepared; {2} filtered items." -f $script:SoftwareGridPageIndex, $script:SoftwareGridPageSource.Count,$viewItemCount) INFO Software
    } catch {
        $script:SoftwareCatalogViewCache = $null
        Write-AMRLog ("Could not save catalog view state: " + $_.Exception.Message) WARNING Software
    }
}

function Restore-AMRSoftwareCatalogViewState {
    $cache = $script:SoftwareCatalogViewCache
    if (-not $cache -or -not $cache.BuildComplete) { return $false }
    if ([string](C 'SearchBox').Text -cne [string]$cache.SearchText) { return $false }
    try {
        $currentViewItemCount = [int]$script:AppsView.Count
        if ([int]$cache.ViewItemCount -ne $currentViewItemCount -or
            $cache.PageIndex -gt $cache.PageSource.Count) {
            Write-AMRLog 'Catalog cache rejected because its source no longer matches the active filtered view.' WARNING Software
            return $false
        }
    } catch {
        Write-AMRLog ('Catalog cache validation failed; a complete rebuild will be used: ' + $_.Exception.Message) WARNING Software
        return $false
    }
    try {
        if ($script:SoftwareGridWarmupTimer) { try { $script:SoftwareGridWarmupTimer.Stop() } catch {}; $script:SoftwareGridWarmupTimer = $null }
        $script:SoftwareGridPageItems = $cache.PageItems
        $script:SoftwareGridPageSource = $cache.PageSource
        $script:SoftwareGridPageIndex = [int]$cache.PageIndex
        $script:SoftwareGridPageSize = [int]$cache.PageSize
        $script:SoftwareGridPageMode = 'Catalog'
        $activeCatalogGrid = C 'SoftwareGrid'
        if (-not [object]::ReferenceEquals($activeCatalogGrid.ItemsSource,$script:SoftwareGridPageItems)) {
            $activeCatalogGrid.ItemsSource = $script:SoftwareGridPageItems
        }
        $script:SuppressSoftwareCategorySelectionChanged = $true
        try {
            $script:SelectedSoftwareCategory = [string]$cache.SelectedCategory
            $categoryItem = @($script:SoftwareCategories | Where-Object { [string]$_.Name -eq [string]$cache.SelectedCategory } | Select-Object -First 1)
            if ($categoryItem.Count -gt 0) { (C 'SoftwareCategoryList').SelectedItem = $categoryItem[0] }
            else { (C 'SoftwareCategoryList').SelectedIndex = 0 }
        } finally { $script:SuppressSoftwareCategorySelectionChanged = $false }
        $scroll = C 'SoftwareScrollViewer'
        if ($scroll) {
            $restoreOffset = [double]$cache.ScrollOffset
            $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                try { (C 'SoftwareScrollViewer').ScrollToVerticalOffset($restoreOffset) } catch {}
            }, [System.Windows.Threading.DispatcherPriority]::Loaded)
        }
        Invoke-AMRSoftwareGridViewTransition
        Write-AMRLog 'Restored the existing catalog card collection without rebuilding it.' INFO Software
        return $true
    } catch {
        Write-AMRLog ("Catalog view restore failed; a normal rebuild will be used: " + $_.Exception.Message) WARNING Software
        return $false
    }
}

function Suspend-AMRSoftwareCatalogPaging {
    $script:SoftwareGridPagingPaused = $true
    if ($script:SoftwareGridResumeTimer) {
        try { $script:SoftwareGridResumeTimer.Stop() } catch {}
        $script:SoftwareGridResumeTimer = $null
    }
    if ($script:SoftwareGridPageMode -eq 'Catalog' -and $script:SoftwareGridWarmupTimer) {
        try { $script:SoftwareGridWarmupTimer.Stop() } catch {}
        $script:SoftwareGridWarmupTimer = $null
    }
    Write-AMRLog 'Software catalog paging suspended while Installed view is active or preparing.' INFO Software
}

function Resume-AMRSoftwareCatalogPaging {
    param([int]$DelayMilliseconds = 250)

    if ($script:SoftwareGridResumeTimer) {
        try { $script:SoftwareGridResumeTimer.Stop() } catch {}
        $script:SoftwareGridResumeTimer = $null
    }

    # Keep paging paused until WPF has completed the view swap and had time to
    # process input, layout, and rendering before background catalog work resumes.
    $script:SoftwareGridPagingPaused = $true
    $timer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
    $timer.Interval = [TimeSpan]::FromMilliseconds([Math]::Max(150, $DelayMilliseconds))
    $timer.Add_Tick({
        $activeTimer = $script:SoftwareGridResumeTimer
        if ($activeTimer) { $activeTimer.Stop() }
        $script:SoftwareGridResumeTimer = $null
        if ($script:ShowInstalledOnly) { return }
        $script:SoftwareGridPageMode = 'Catalog'
        $script:SoftwareGridPagingPaused = $false
        Start-AMRSoftwareGridWarmup
        Write-AMRLog 'Software catalog paging resumed after the UI transition settled.' INFO Software
    })
    $script:SoftwareGridResumeTimer = $timer
    $timer.Start()
}

function Add-AMRSoftwareGridPage {
    # Resolve the source from the active view. During a build, OrderedItems is
    # the only safe source; the committed array may belong to the previous view.
    if ($script:SoftwareGridPagingPaused -and $script:SoftwareGridPageMode -eq 'Catalog') { return }
    if ($script:SoftwareGridTransitionPending -and $script:SoftwareGridPageMode -eq 'Installed') { return }
    if ($script:SoftwareGridPageBusy) { return }

    $buildState = $null
    if ($script:SoftwareGridPageMode -eq 'Installed') {
        if (-not $script:ShowInstalledOnly) { return }
        $buildState = $script:InstalledGridPageBuildState
    } else {
        if ($script:ShowInstalledOnly) { return }
        $buildState = $script:CatalogGridPageBuildState
    }

    $source = $script:SoftwareGridPageSource
    if ($buildState) {
        if (-not $buildState.FirstPageCommitted -or -not $buildState.PageItems) {
            $buildState.ScrollPrefetchPending = $true
            return
        }
        $source = $buildState.OrderedItems
        if (-not [object]::ReferenceEquals($script:SoftwareGridPageItems,$buildState.PageItems)) {
            $script:SoftwareGridPageItems = $buildState.PageItems
            $script:SoftwareGridPageIndex = [int]$buildState.PageItems.Count
        }
    }

    if ($buildState -and ([int]$source.Count - [int]$script:SoftwareGridPageIndex) -lt 4) {
        $buildState.ScrollPrefetchPending = $true
        return
    }

    $script:SoftwareGridPageBusy = $true
    try {
        $end = [Math]::Min($script:SoftwareGridPageIndex + 4, $source.Count)
        while ($script:SoftwareGridPageIndex -lt $end) {
            [void]$script:SoftwareGridPageItems.Add($source[$script:SoftwareGridPageIndex])
            $script:SoftwareGridPageIndex++
        }
        if ($buildState) {
            $distanceToEnd = 0.0
            try {
                $scroll = C 'SoftwareScrollViewer'
                $distanceToEnd = [double]$scroll.ScrollableHeight - [double]$scroll.VerticalOffset
            } catch {}
            $buildState.ScrollPrefetchPending = ($distanceToEnd -le 420)
        } else {
            try {
                $scroll = C 'SoftwareScrollViewer'
                if ($scroll -and ($scroll.ScrollableHeight - $scroll.VerticalOffset) -le 420) {
                    Start-AMRSoftwareGridWarmup
                }
            } catch {}
        }
    } finally {
        $script:SoftwareGridPageBusy = $false
    }
}

function Invoke-AMRSoftwareGridPrefetchDemand {
    param([Parameter(Mandatory=$true)]$State)

    if (-not $State.ScrollPrefetchPending -or -not $State.FirstPageCommitted -or -not $State.PageItems) { return }
    if ($State.Mode -eq 'Catalog' -and $script:ShowInstalledOnly) { return }
    if ($State.Mode -eq 'Installed' -and -not $script:ShowInstalledOnly) { return }

    $scroll = C 'SoftwareScrollViewer'
    if (-not $scroll) { return }
    $distanceToEnd = [double]$scroll.ScrollableHeight - [double]$scroll.VerticalOffset
    if ($distanceToEnd -gt 420) {
        $State.ScrollPrefetchPending = $false
        return
    }

    $available = [int]$State.OrderedItems.Count - [int]$State.PageItems.Count
    if ($available -lt 4) { return }
    $appendEnd = [Math]::Min([int]$State.PageItems.Count + 4,[int]$State.OrderedItems.Count)
    while ($State.PageItems.Count -lt $appendEnd) {
        [void]$State.PageItems.Add($State.OrderedItems[$State.PageItems.Count])
    }
    $script:SoftwareGridPageItems = $State.PageItems
    $script:SoftwareGridPageIndex = [int]$State.PageItems.Count
    # Keep demand active; the next Background tick rechecks after WPF layout.
}

function Start-AMRSoftwareGridWarmup {
    if ($script:SoftwareGridPagingPaused -and $script:SoftwareGridPageMode -eq 'Catalog') { return }
    # Fill the initial viewport one complete four-card row at a time. This avoids
    # an empty/short grid while keeping every dispatcher turn intentionally small.
    try {
        if ($script:SoftwareGridWarmupTimer) {
            try { $script:SoftwareGridWarmupTimer.Stop() } catch {}
        }

        $timer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
        $timer.Interval = [TimeSpan]::FromMilliseconds(50)
        $timer.Add_Tick({
            try {
                if ($script:SoftwareGridPageIndex -ge $script:SoftwareGridPageSource.Count) {
                    $script:SoftwareGridWarmupTimer.Stop()
                    $script:SoftwareGridWarmupTimer = $null
                    return
                }

                Add-AMRSoftwareGridPage
                $grid = C 'SoftwareGrid'
                $scroll = C 'SoftwareScrollViewer'
                # Let WPF perform layout naturally between dispatcher ticks; forcing UpdateLayout here stalls input during progressive card creation.

                # Stop warmup once the viewport is filled with a small safety
                # buffer. Further rows are requested by the scroll prefetch hook.
                if ($scroll -and ($scroll.ScrollableHeight - $scroll.VerticalOffset) -gt 220) {
                    $script:SoftwareGridWarmupTimer.Stop()
                    $script:SoftwareGridWarmupTimer = $null
                }
            } catch {
                try { $script:SoftwareGridWarmupTimer.Stop() } catch {}
                $script:SoftwareGridWarmupTimer = $null
                Write-AMRLog "Software grid warmup stopped: $($_.Exception.Message)" WARNING Software
            }
        })
        $script:SoftwareGridWarmupTimer = $timer
        $timer.Start()
    } catch {
        Write-AMRLog "Could not start progressive Software grid warmup: $($_.Exception.Message)" WARNING Software
    }
}

function Get-AMRSoftwareVisualElements {
    param(
        [Parameter(Mandatory=$true)][System.Windows.DependencyObject]$Root,
        [Parameter(Mandatory=$true)][type]$ElementType
    )

    $foundElements = New-Object System.Collections.ArrayList
    $walk = {
        param($node)
        if ($null -eq $node) { return }
        if ($ElementType.IsInstanceOfType($node)) { [void]$foundElements.Add($node) }
        try {
            $childCount = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node)
            for ($childIndex = 0; $childIndex -lt $childCount; $childIndex++) {
                $child = [System.Windows.Media.VisualTreeHelper]::GetChild($node, $childIndex)
                & $walk $child
            }
        } catch { }
    }
    & $walk $Root
    return ,$foundElements
}

# A9: plain variable initialization only. These flags are tested with -not before they are ever assigned; under StrictMode that
# read threw and the surrounding try/catch logged a warning and skipped the feature (entrance animation, whole-card selection).
$script:SoftwareConsoleEntrancePlayed = $false
$script:SoftwareCategoriesEntrancePlayed = $false
$script:SoftwareCardSelectionHandlerAttached = $false
function Invoke-AMRSoftwarePremiumEntrance {
    # One-time, low-cost entrance only. Never animate individual software cards
    # or traverse the catalog visual tree; tab navigation and catalog refreshes
    # must remain independent from entrance effects.
    try {
        $console = C 'AppManagementConsole'
        if ($console -and -not $script:SoftwareConsoleEntrancePlayed) {
            $script:SoftwareConsoleEntrancePlayed = $true

            $consoleTransform = New-Object System.Windows.Media.TranslateTransform -ArgumentList 0,14
            $console.RenderTransform = $consoleTransform
            $console.Opacity = 0.94

            $consoleFade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $consoleFade.From = 0.94
            $consoleFade.To = 1.0
            $consoleFade.Duration = [TimeSpan]::FromMilliseconds(320)
            $consoleFade.EasingFunction = New-Object System.Windows.Media.Animation.QuadraticEase
            $consoleFade.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $consoleRise = New-Object System.Windows.Media.Animation.DoubleAnimation
            $consoleRise.From = 14
            $consoleRise.To = 0
            $consoleRise.Duration = [TimeSpan]::FromMilliseconds(360)
            $consoleRise.EasingFunction = New-Object System.Windows.Media.Animation.QuadraticEase
            $consoleRise.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $console.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $consoleFade, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
            $consoleTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $consoleRise, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
        }

        # A single subtle category-surface reveal; no per-category or per-card
        # animations and no Dispatcher callback are created.
        $categoryList = C 'SoftwareCategoryList'
        if ($categoryList -and -not $script:SoftwareCategoriesEntrancePlayed) {
            $script:SoftwareCategoriesEntrancePlayed = $true

            $categoryTransform = New-Object System.Windows.Media.TranslateTransform -ArgumentList 0,5
            $categoryList.RenderTransform = $categoryTransform
            $categoryList.Opacity = 0.96

            $categoryFade = New-Object System.Windows.Media.Animation.DoubleAnimation
            $categoryFade.From = 0.96
            $categoryFade.To = 1.0
            $categoryFade.Duration = [TimeSpan]::FromMilliseconds(260)
            $categoryFade.EasingFunction = New-Object System.Windows.Media.Animation.QuadraticEase
            $categoryFade.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $categoryRise = New-Object System.Windows.Media.Animation.DoubleAnimation
            $categoryRise.From = 5
            $categoryRise.To = 0
            $categoryRise.Duration = [TimeSpan]::FromMilliseconds(280)
            $categoryRise.EasingFunction = New-Object System.Windows.Media.Animation.QuadraticEase
            $categoryRise.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

            $categoryList.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $categoryFade, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
            $categoryTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $categoryRise, [System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
        }
    } catch {
        try { Write-AMRLog ("Software premium entrance animation was skipped: {0}" -f $_.Exception.Message) WARNING Software } catch {}
    }
}


function Start-AMRSoftwareGridTransitionOut {
    # Start visual feedback synchronously on the click, before inventory or
    # collection preparation begins. Keep the old cards visible but gently dimmed.
    try {
        $grid = C 'SoftwareGrid'
        if (-not ($grid -is [System.Windows.UIElement])) { return }
        $transform = $grid.RenderTransform
        if (-not ($transform -is [System.Windows.Media.TranslateTransform])) {
            $transform = [System.Windows.Media.TranslateTransform]::new(0.0, 0.0)
            $grid.RenderTransform = $transform
        }
        $ease = [System.Windows.Media.Animation.CubicEase]::new()
        $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
        $fade = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $fade.To = 0.62
        $fade.Duration = [TimeSpan]::FromMilliseconds(115)
        $fade.EasingFunction = $ease
        $slide = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $slide.To = -5.0
        $slide.Duration = [TimeSpan]::FromMilliseconds(115)
        $slide.EasingFunction = $ease
        $grid.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
        $transform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$slide,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
    } catch {
        try { Write-AMRLog ('Software transition-out animation skipped: ' + $_.Exception.Message) WARNING Software } catch {}
    }
}

function Invoke-AMRSoftwareGridViewTransition {
    # Restore the new view with a noticeable but lightweight cross-fade + drift.
    if (-not $script:SoftwareGridTransitionPending) { return }
    $script:SoftwareGridTransitionPending = $false
    try {
        $grid = C 'SoftwareGrid'
        if (-not ($grid -is [System.Windows.UIElement])) { return }
        $transform = $grid.RenderTransform
        if (-not ($transform -is [System.Windows.Media.TranslateTransform])) {
            $transform = [System.Windows.Media.TranslateTransform]::new(0.0, 0.0)
            $grid.RenderTransform = $transform
        }
        $ease = [System.Windows.Media.Animation.CubicEase]::new()
        $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $fade = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $fade.From = 0.78
        $fade.To = 1.0
        $fade.Duration = [TimeSpan]::FromMilliseconds(105)
        $fade.EasingFunction = $ease
        $slide = [System.Windows.Media.Animation.DoubleAnimation]::new()
        $slide.From = 3.0
        $slide.To = 0.0
        $slide.Duration = [TimeSpan]::FromMilliseconds(115)
        $slide.EasingFunction = $ease
        $grid.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
        $transform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$slide,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
    } catch {
        try { Write-AMRLog ('Software view transition skipped: ' + $_.Exception.Message) WARNING Software } catch {}
    }
}

function Start-AMRCatalogGridPageBuild {
    param([Parameter(Mandatory=$true)]$View)

    # Cancel any older catalog build before starting a new filtered/search result.
    if ($script:CatalogGridPageBuildState) {
        $oldState = $script:CatalogGridPageBuildState
        try { if ($oldState.Timer) { $oldState.Timer.Stop() } } catch {}
        try { if ($oldState.ViewEnumerator) { $oldState.ViewEnumerator.Dispose() } } catch {}
        $script:CatalogGridPageBuildState = $null
    }

    $categoryNames = @($script:SoftwareCategoryNames)
    $groups = @{}
    $categoryOrdinals = @{}
    for ($categoryIndex = 0; $categoryIndex -lt $categoryNames.Count; $categoryIndex++) {
        $categoryName = [string]$categoryNames[$categoryIndex]
        $groups[$categoryName] = New-Object 'System.Collections.Generic.List[object]'
        $categoryOrdinals[$categoryName] = [int]($categoryIndex + 1)
    }

    $state = [pscustomobject]@{
        View = $View
        # A7: enumerate a snapshot of the view (same items, same order). A background scan result calls
        # AppsView.Refresh(); a live enumerator then threw 'Collection was modified' in the middle of the build.
        ViewEnumerator = ([object[]]@($View)).GetEnumerator()
        CategoryNames = $categoryNames
        Groups = $groups
        CategoryOrdinals = $categoryOrdinals
        Uncategorised = (New-Object 'System.Collections.Generic.List[object]')
        OrderedItems = (New-Object 'System.Collections.Generic.List[object]')
        Phase = 'Collect'
        CategoryIndex = 0
        GroupIndex = 0
        CurrentGroup = $null
        GroupItemIndex = 0
        FirstInGroup = $true
        AppIndexInGroup = 0
        CurrentOrdinal = 0
        Index = 0
        Mode = 'Catalog'
        ScrollPrefetchPending = $false
        SearchText = [string](C 'SearchBox').Text
        SelectedCategory = [string]$script:SelectedSoftwareCategory
        ScrollOffset = 0.0
        TickBudgetMilliseconds = 4
        Timer = $null
        FirstPageCommitted = $false
        PageItems = $null
    }
    # A new catalog generation must not page from the previous view's source.
    $script:SoftwareGridPageMode = 'Catalog'
    $script:SoftwareGridPageSource = @()
    $script:SoftwareGridPageIndex = 0
    $script:CatalogGridPageBuildState = $state

    $timer = [System.Windows.Threading.DispatcherTimer]::new([System.Windows.Threading.DispatcherPriority]::Background)
    $timer.Interval = [TimeSpan]::FromMilliseconds(15)
    $timer.Add_Tick({ Complete-AMRCatalogGridPageBuildBatch })
    $state.Timer = $timer
    $timer.Start()
}

function Publish-AMRCatalogFirstPage {
    param([Parameter(Mandatory=$true)]$State)

    if ($script:ShowInstalledOnly) { return }
    if (-not $State.FirstPageCommitted) {
        if ($State.OrderedItems.Count -lt 8) { return }
        $pageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
        for ($index = 0; $index -lt 8; $index++) {
            [void]$pageItems.Add($State.OrderedItems[$index])
        }
        $State.PageItems = $pageItems
        $State.FirstPageCommitted = $true
        $script:SoftwareGridPageMode = 'Catalog'
        $script:SoftwareGridPageIndex = 8
        $script:SoftwareGridPageSize = 4
        $script:SoftwareGridPageItems = $pageItems
        (C 'SoftwareGrid').ItemsSource = $pageItems
        Invoke-AMRSoftwareGridViewTransition
        Queue-AMRSoftwareIconSync
        (C 'SoftwareScrollViewer').ScrollToTop()
        return
    }

    # Reveal the first 64 cards in small rows. After that, continue only when
    # the user is near the end of the currently visible catalog.
    if ($State.PageItems.Count -lt 64) {
        $available = $State.OrderedItems.Count - $State.PageItems.Count
        if ($available -ge 4) {
            $appendEnd = [Math]::Min([Math]::Min($State.PageItems.Count + 4,64),$State.OrderedItems.Count)
            while ($State.PageItems.Count -lt $appendEnd) {
                [void]$State.PageItems.Add($State.OrderedItems[$State.PageItems.Count])
            }
            $script:SoftwareGridPageItems = $State.PageItems
            $script:SoftwareGridPageIndex = [int]$State.PageItems.Count
        }
    }
    Invoke-AMRSoftwareGridPrefetchDemand -State $State
}

function Complete-AMRCatalogGridPageBuildBatch {
    $state = $script:CatalogGridPageBuildState
    if (-not $state -or $script:ShowInstalledOnly) { return }

    try {
        switch ($state.Phase) {
            'Collect' {
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                while ($watch.ElapsedMilliseconds -lt $state.TickBudgetMilliseconds) {
                    if (-not $state.ViewEnumerator.MoveNext()) {
                        try { $state.ViewEnumerator.Dispose() } catch {}
                        $state.ViewEnumerator = $null
                        $state.Phase = 'CategoryStart'
                        break
                    }
                    $item = $state.ViewEnumerator.Current
                    $category = [string]$item.Category
                    if ($state.Groups.ContainsKey($category)) {
                        [void]$state.Groups[$category].Add($item)
                    } else {
                        # Preserve every catalog record even if its category is
                        # blank or was added/changed after the navigation list
                        # was initialized. All Applications must never drop it.
                        [void]$state.Uncategorised.Add($item)
                    }
                }
                return
            }
            'CategoryStart' {
                while ($state.CategoryIndex -lt $state.CategoryNames.Count) {
                    $categoryName = [string]$state.CategoryNames[$state.CategoryIndex]
                    $groupItems = $state.Groups[$categoryName]
                    if ($groupItems.Count -eq 0) {
                        $state.CategoryIndex++
                        continue
                    }
                    if ($state.GroupIndex -gt 0) {
                        $remainder = $state.OrderedItems.Count % 4
                        if ($remainder -ne 0) {
                            $padCount = 4 - $remainder
                            for ($pad = 0; $pad -lt $padCount; $pad++) {
                                [void]$state.OrderedItems.Add([pscustomobject]@{
                                    IsCategorySpacer = $true; IsCategoryStart = $false
                                    IsCategoryHeaderRow = $false; CategoryNumber = ''
                                    Category = ''; Icon = $null; Initials = ''
                                })
                            }
                        }
                    }
                    $state.CurrentGroup = $groupItems
                    $state.GroupItemIndex = 0
                    $state.FirstInGroup = $true
                    $state.AppIndexInGroup = 0
                    $state.CurrentOrdinal = [int]$state.CategoryOrdinals[$categoryName]
                    $state.Phase = 'CategoryItems'
                    return
                }
                $state.Phase = 'Uncategorised'
                $state.Index = 0
                return
            }
            'CategoryItems' {
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                while ($state.GroupItemIndex -lt $state.CurrentGroup.Count -and $watch.ElapsedMilliseconds -lt $state.TickBudgetMilliseconds) {
                    $app = $state.CurrentGroup[$state.GroupItemIndex]
                    foreach ($propertyName in @('IsCategorySpacer','IsCategoryStart','IsCategoryHeaderRow','CategoryNumber')) {
                        if (-not $app.PSObject.Properties[$propertyName]) {
                            $app | Add-Member -NotePropertyName $propertyName -NotePropertyValue $null
                        }
                    }
                    $app.IsCategorySpacer = $false
                    $app.IsCategoryStart = [bool]($state.FirstInGroup -and $state.CurrentOrdinal -gt 1)
                    $app.IsCategoryHeaderRow = [bool]($state.CurrentOrdinal -gt 1 -and $state.AppIndexInGroup -lt 4)
                    $app.CategoryNumber = if ($state.CurrentOrdinal -gt 1) { [string]$state.CurrentOrdinal } else { '' }
                    [void]$state.OrderedItems.Add($app)
                    $state.FirstInGroup = $false
                    $state.AppIndexInGroup++
                    $state.GroupItemIndex++
                    if (-not $state.FirstPageCommitted -and $state.OrderedItems.Count -ge 8) {
                        Publish-AMRCatalogFirstPage -State $state
                        return
                    }
                }
                Publish-AMRCatalogFirstPage -State $state
                if ($state.GroupItemIndex -ge $state.CurrentGroup.Count) {
                    $state.GroupIndex++
                    $state.CategoryIndex++
                    $state.Phase = 'CategoryStart'
                }
                return
            }
            'Uncategorised' {
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                while ($state.Index -lt $state.Uncategorised.Count -and $watch.ElapsedMilliseconds -lt $state.TickBudgetMilliseconds) {
                    $app = $state.Uncategorised[$state.Index]
                    foreach ($propertyName in @('IsCategorySpacer','IsCategoryStart','IsCategoryHeaderRow','CategoryNumber')) {
                        if (-not $app.PSObject.Properties[$propertyName]) {
                            $app | Add-Member -NotePropertyName $propertyName -NotePropertyValue $null
                        }
                    }
                    $app.IsCategorySpacer = $false
                    $app.IsCategoryStart = $false
                    $app.IsCategoryHeaderRow = $false
                    $app.CategoryNumber = ''
                    [void]$state.OrderedItems.Add($app)
                    $state.Index++
                    if (-not $state.FirstPageCommitted -and $state.OrderedItems.Count -ge 8) {
                        Publish-AMRCatalogFirstPage -State $state
                        return
                    }
                }
                Publish-AMRCatalogFirstPage -State $state
                if ($state.Index -ge $state.Uncategorised.Count) { $state.Phase = 'Commit' }
                return
            }
            'Commit' {
                $state.Timer.Stop()
                try { if ($state.ViewEnumerator) { $state.ViewEnumerator.Dispose() } } catch {}
                $state.ViewEnumerator = $null
                $script:SoftwareGridPageMode = 'Catalog'
                $script:SoftwareGridPageSource = $state.OrderedItems.ToArray()
                $script:SoftwareGridPageSize = 4
                if ($state.FirstPageCommitted -and $state.PageItems) {
                    $script:SoftwareGridPageItems = $state.PageItems
                    $script:SoftwareGridPageIndex = [int]$state.PageItems.Count
                } else {
                    $pageItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
                    $initialEnd = [Math]::Min(8, $script:SoftwareGridPageSource.Count)
                    for ($index = 0; $index -lt $initialEnd; $index++) { [void]$pageItems.Add($script:SoftwareGridPageSource[$index]) }
                    $script:SoftwareGridPageItems = $pageItems
                    $script:SoftwareGridPageIndex = $initialEnd
                    (C 'SoftwareGrid').ItemsSource = $pageItems
                    Invoke-AMRSoftwareGridViewTransition
                    Queue-AMRSoftwareIconSync
                    (C 'SoftwareScrollViewer').ScrollToTop()
                }
                Start-AMRSoftwareGridWarmup
                $script:CatalogGridPageBuildState = $null
                $searchElapsedText = ''
                try {
                    if ($script:AMRSearchStartTicks -ne 0) {
                        $searchElapsedMs = [int](([DateTime]::UtcNow.Ticks - $script:AMRSearchStartTicks) / 10000)
                        if ($searchElapsedMs -lt 30000) { $searchElapsedText = (' Elapsed since the last search apply: {0} ms.' -f $searchElapsedMs) }
                        $script:AMRSearchStartTicks = 0
                    }
                } catch {}
                Write-AMRLog ('Software catalog page source prepared incrementally: ' + [string]$script:SoftwareGridPageSource.Count + ' item(s).' + $searchElapsedText) INFO Software
                return
            }
        }
    } catch {
        try { if ($state.Timer) { $state.Timer.Stop() } } catch {}
        try { if ($state.ViewEnumerator) { $state.ViewEnumerator.Dispose() } } catch {}
        $script:CatalogGridPageBuildState = $null
        Write-AMRLog ('Could not prepare the software catalog incrementally: ' + $_.Exception.Message) ERROR Software
    }
}

function Reset-AMRSoftwareGridPages {
    param([Parameter(Mandatory=$true)]$View)

    # A filter/search/refresh rebuild invalidates cached catalog snapshots.
    $script:SoftwareCatalogViewCache = $null
    if ($script:ShowInstalledOnly) { Clear-AMRInstalledViewCache -Reason 'grid-reset-on-installed' }

    if ($script:SoftwareGridWarmupTimer) {
        try { $script:SoftwareGridWarmupTimer.Stop() } catch {}
        $script:SoftwareGridWarmupTimer = $null
    }
    if ($script:CatalogGridPageBuildState) {
        $oldState = $script:CatalogGridPageBuildState
        try { if ($oldState.Timer) { $oldState.Timer.Stop() } } catch {}
        try { if ($oldState.ViewEnumerator) { $oldState.ViewEnumerator.Dispose() } } catch {}
        $script:CatalogGridPageBuildState = $null
    }

    $script:SoftwareGridPageMode = if ($script:ShowInstalledOnly) { 'Installed' } else { 'Catalog' }
    $script:SoftwareGridPageSource = @()
    $script:SoftwareGridPageIndex = 0
    $script:SoftwareGridPageSize = 4
    if ($script:ShowInstalledOnly) {
        if ($script:InstalledGridPageBuildState) {
            $installedBuild = $script:InstalledGridPageBuildState
            try { if ($installedBuild.Timer) { $installedBuild.Timer.Stop() } } catch {}
            try { if ($installedBuild.ViewEnumerator) { $installedBuild.ViewEnumerator.Dispose() } } catch {}
            $script:InstalledGridPageBuildState = $null
        }
        $installedCount = 0
        try { $installedCount = @($script:InstalledAppsInventory | Where-Object { $_.IsUserFacing -and $_.CanUninstall }).Count } catch {}
        Start-AMRInstalledGridPageBuild -View $View -WasInstalledViewVisible $true -InstalledCount $installedCount -RestoreCategory ([string]$script:SelectedSoftwareCategory) -RestoreScrollOffset 0 -InventoryGeneration ([int]$script:InstalledInventoryGeneration)
        return
    }
    Start-AMRCatalogGridPageBuild -View $View
}

(C 'SoftwareCategoryList').Add_SelectionChanged({
    if ($script:SuppressSoftwareCategorySelectionChanged) { return }
    $selected = (C 'SoftwareCategoryList').SelectedItem
    if ($null -ne $selected) {
        $categoryList = C 'SoftwareCategoryList'
        $categoryContainer = $categoryList.ItemContainerGenerator.ContainerFromItem($selected)
        Invoke-AMRNavigationTilePressAnimation -Element $categoryContainer
        $script:SelectedSoftwareCategory = [string]$selected.Name
        Clear-AMRInstalledViewCache -Reason 'category-selected'
        if ($script:ShowInstalledOnly -and $script:InstalledAppsView) {
            $script:InstalledAppsView.Refresh()
            Reset-AMRSoftwareGridPages -View $script:InstalledAppsView
        } else {
            $script:AppsView.Refresh()
            Reset-AMRSoftwareGridPages -View $script:AppsView
        }
    }
})

# Search is applied 200 ms after the last keystroke instead of once per keystroke.
# The view caches are still cleared immediately; the filter reads the live SearchBox text.
$script:SoftwareSearchDebounceTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:SoftwareSearchDebounceTimer.Interval = [TimeSpan]::FromMilliseconds(200)
$script:SoftwareSearchDebounceTimer.Add_Tick({
    $script:SoftwareSearchDebounceTimer.Stop()
    try {
        Clear-AMRInstalledViewCache -Reason 'search-applied'
        $script:SoftwareCatalogViewCache = $null
        $searchStart = Get-AMRPerfNow
        $script:AMRSearchStartTicks = [DateTime]::UtcNow.Ticks
        Set-AMRPerfMark 'searchApply'
        if ($script:ShowInstalledOnly -and $script:InstalledAppsView) {
            $script:InstalledAppsView.Refresh()
            $searchRefreshed = Get-AMRPerfNow
            Reset-AMRSoftwareGridPages -View $script:InstalledAppsView
        } else {
            $script:AppsView.Refresh()
            $searchRefreshed = Get-AMRPerfNow
            Reset-AMRSoftwareGridPages -View $script:AppsView
        }
        if ($searchStart -ne 0) {
            Add-AMRPerfSince -Key 'search.viewRefresh' -Start $searchStart
            Add-AMRPerfSince -Key 'search.resetPages' -Start $searchRefreshed
            $searchRefreshMs = 0.0; $searchResetMs = 0.0
            try {
                $searchRefreshMs = [math]::Round(($searchRefreshed - $searchStart) * 1000.0 / [System.Diagnostics.Stopwatch]::Frequency,1)
                $searchResetMs = [math]::Round(((Get-AMRPerfNow) - $searchRefreshed) * 1000.0 / [System.Diagnostics.Stopwatch]::Frequency,1)
            } catch {}
            Write-AMRLog ('Software search applied: textLength={0}; installedOnly={1}; viewRefreshMs={2}; resetPagesMs={3}.' -f ([string](C 'SearchBox').Text).Length,[bool]$script:ShowInstalledOnly,$searchRefreshMs,$searchResetMs) INFO Software
        }
    } catch {
        Write-AMRLog "Software search refresh failed: $($_.Exception.Message)" WARNING Software
    }
})
(C 'SearchBox').Add_TextChanged({
    Clear-AMRInstalledViewCache -Reason 'search-typing'
    $script:SoftwareCatalogViewCache = $null
    $script:SoftwareSearchDebounceTimer.Stop()
    $script:SoftwareSearchDebounceTimer.Start()
})
(C 'ShowInstalledBtn').Add_Click({
    if (-not $script:ShowInstalledOnly) {
        if ($script:InstalledScanState.PendingShow) {
            # A second click while the first inventory scan is pending cancels only the view switch;
            # the background scan may finish and populate the cache for a later, instant entry.
            $script:InstalledScanState.PendingShow = $false
            Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
            if ($script:ProgressText) { $script:ProgressText.Text = '' }
            $script:SoftwareGridTransitionPending = $true
            Invoke-AMRSoftwareGridViewTransition
            Set-AMRShowInstalledButtonMode -Mode All
            Resume-AMRSoftwareCatalogPaging -DelayMilliseconds 500
            Write-AMRLog 'Cancelled the pending Installed view switch; the background inventory scan continues for cache refresh.' INFO Software
            return
        }
        Save-AMRSoftwareCatalogViewState
        Suspend-AMRSoftwareCatalogPaging
        Start-AMRSoftwareGridTransitionOut
        $script:SoftwareGridTransitionPending = $true
        Set-AMRShowInstalledButtonBusy -Busy $true -Label 'Loading Installed...'
        if ($script:InstalledScanState.Ready) {
            # A validated cache is useful immediately. Do not make the user wait
            # for an already-running startup refresh; its fresh result will replace
            # this snapshot through Complete-AMRInstalledCatalogScan.
            $script:ProgressText.Text = 'Showing saved inventory; checking for changes...'
            if ($script:InstalledScanState.Current) {
                $script:InstalledScanState.PendingShow = $false
                Set-AMRInstalledViewVisible -InstalledCount $script:InstalledScanState.Count
            } else {
                Set-AMRInstalledViewVisible -InstalledCount $script:InstalledScanState.Count
                # A22 rescanned (7-15 s CPU) on every toggle. Now only when an install/removal was detected,
                # the saved catalog is older than the age limit, or it is missing. The Refresh button always scans.
                if (Test-AMRInstalledRefreshNeeded -Context 'toggle') { Start-AMRInstalledCatalogScan -Refresh }
            }
        } else {
            $script:ProgressText.Text = 'Scanning installed applications. Your current catalog stays visible until the first installed row is ready...'
            # First launch without a valid snapshot: wait for the first complete scan.
            Start-AMRInstalledCatalogScan -ShowWhenReady
        }
    } else {
        # Allow switching back even while Installed cards are still preparing; their timer state is paused and retained below.
        if ($script:ShowInstalledButtonBusyState.Active) {
            Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
        }
        # Freeze all Installed-side UI mutations BEFORE the outgoing animation.
        # Previously these timers were stopped 190ms later, so they could publish
        # another batch or replace the visible first row while the transition ran.
        if ($script:CatalogGridPageBuildState) {
            # Keep the paused catalog enumerator and its partial ordered list.
            try { if ($script:CatalogGridPageBuildState.Timer) { $script:CatalogGridPageBuildState.Timer.Stop() } } catch {}
        }
        try {
            if ($script:InstalledViewCache) { $script:InstalledViewCache.ScrollOffset = [double](C 'SoftwareScrollViewer').VerticalOffset }
        } catch {}
        if ($script:InstalledViewPreparationState -and $script:InstalledViewPreparationState.Timer) {
            try { $script:InstalledViewPreparationState.Timer.Stop() } catch {}
            Write-AMRLog 'Paused Installed inventory mapping immediately before leaving the view.' INFO Software
        }
        if ($script:InstalledGridPageBuildState -and $script:InstalledGridPageBuildState.Timer) {
            try { $script:InstalledGridPageBuildState.Timer.Stop() } catch {}
            Write-AMRLog 'Paused Installed card ordering immediately before leaving the view.' INFO Software
        }
        if ($script:SoftwareGridWarmupTimer -and $script:SoftwareGridPageMode -eq 'Installed') {
            try { $script:SoftwareGridWarmupTimer.Stop() } catch {}
            $script:SoftwareGridWarmupTimer = $null
            Write-AMRLog 'Paused Installed card warmup immediately before leaving the view.' INFO Software
        }
        Start-AMRSoftwareGridTransitionOut
        $script:SoftwareGridTransitionPending = $true
        Set-AMRShowInstalledButtonBusy -Busy $true -Label 'Loading All...'
        # IMPORTANT: do not call GetNewClosure() for this DispatcherTimer.
        # A closure creates a child script scope; $script:ShowInstalledOnly would
        # then be written in that child scope while AppsView.Filter reads the
        # original script scope. The original filter would remain Installed-only.
        # Keep the timer in the original script scope and execute this handler
        # there so the toggle state and the CollectionView filter stay in sync.
        $script:ShowAllReturnTimer = [System.Windows.Threading.DispatcherTimer]::new()
        $script:ShowAllReturnTimer.Interval = [TimeSpan]::FromMilliseconds(190)
        $script:ShowAllReturnTimer.Add_Tick({
            $timer = $script:ShowAllReturnTimer
            if ($timer) { $timer.Stop() }
            try {
                # Installed-side dispatcher work was paused synchronously before
                # the outgoing animation; keep its partial state intact here.
                $script:InstalledScanState.PendingShow = $false

                # Clear the flag in the same script scope used by AppsView.Filter,
                # then refresh and rebuild the full catalog from that view.
                $script:ShowInstalledOnly = $false
                $script:SoftwareGridTransitionPending = $true
                Set-AMRShowInstalledButtonMode -Mode All

                $restoredCatalog = $false
                $pausedCatalogBuild = $script:CatalogGridPageBuildState
                if ($pausedCatalogBuild -and
                    [object]::ReferenceEquals($pausedCatalogBuild.View,$script:AppsView) -and
                    [string]$pausedCatalogBuild.SearchText -ceq [string](C 'SearchBox').Text) {
                    # AppsView was not refreshed on entry to Installed, so the paused
                    # enumerator is still valid. Restore the catalog's own category
                    # selection (Installed has its own current selection) and resume in place.
                    $script:SuppressSoftwareCategorySelectionChanged = $true
                    try {
                        $script:SelectedSoftwareCategory = [string]$pausedCatalogBuild.SelectedCategory
                        $savedCategoryItem = @($script:SoftwareCategories | Where-Object { [string]$_.Name -eq [string]$pausedCatalogBuild.SelectedCategory } | Select-Object -First 1)
                        if ($savedCategoryItem.Count -gt 0) { (C 'SoftwareCategoryList').SelectedItem = $savedCategoryItem[0] }
                        else { (C 'SoftwareCategoryList').SelectedIndex = 0 }
                    } finally { $script:SuppressSoftwareCategorySelectionChanged = $false }
                    $script:SoftwareGridPageMode = 'Catalog'
                    $script:SoftwareGridPageSource = @()
                    $catalogGrid = C 'SoftwareGrid'
                    if ($pausedCatalogBuild.FirstPageCommitted -and $pausedCatalogBuild.PageItems) {
                        $script:SoftwareGridPageItems = $pausedCatalogBuild.PageItems
                        $script:SoftwareGridPageIndex = [int]$pausedCatalogBuild.PageItems.Count
                        if (-not [object]::ReferenceEquals($catalogGrid.ItemsSource,$pausedCatalogBuild.PageItems)) {
                            $catalogGrid.ItemsSource = $pausedCatalogBuild.PageItems
                        }
                    }
                    try {
                        $restoreOffset = [double]$pausedCatalogBuild.ScrollOffset
                        $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                            try { (C 'SoftwareScrollViewer').ScrollToVerticalOffset($restoreOffset) } catch {}
                        }, [System.Windows.Threading.DispatcherPriority]::Loaded)
                    } catch {}
                    if ($pausedCatalogBuild.Timer) { $pausedCatalogBuild.Timer.Start() }
                    Invoke-AMRSoftwareGridViewTransition
                    $restoredCatalog = $true
                    Write-AMRLog 'Resumed the paused All Applications builder and its existing card collection without re-enumerating the catalog.' INFO Software
                } else {
                    # Search/category changes while Installed was visible invalidate
                    # the paused enumerator; rebuild only in that case.
                    if ($pausedCatalogBuild) {
                        try { if ($pausedCatalogBuild.Timer) { $pausedCatalogBuild.Timer.Stop() } } catch {}
                        try { if ($pausedCatalogBuild.ViewEnumerator) { $pausedCatalogBuild.ViewEnumerator.Dispose() } } catch {}
                        $script:CatalogGridPageBuildState = $null
                    }
                    if ($script:SoftwareCatalogViewCache -and
                        [string]$script:SoftwareCatalogViewCache.SearchText -ceq [string](C 'SearchBox').Text) {
                        $script:SelectedSoftwareCategory = [string]$script:SoftwareCatalogViewCache.SelectedCategory
                    }
                    $script:AppsView.Refresh()
                    $restoredCatalog = Restore-AMRSoftwareCatalogViewState
                    if (-not $restoredCatalog) {
                        Reset-AMRSoftwareGridPages -View $script:AppsView
                    }
                }

                (C 'SoftwareCategoryList').ItemsSource = $script:SoftwareCategories
                Update-AMRSoftwareCategoryCounts
                (C 'ShowInstalledBtn').Content = 'Show Installed'
                (C 'ShowInstalledBtn').ToolTip = 'Show only applications detected as installed on this PC.'
                (C 'UninstallSelectedBtn').Visibility = 'Collapsed'
                Write-AMRLog 'Installed-app filter disabled; the saved catalog view was restored when available.' INFO Software
            }
            catch {
                Write-AMRLog "Could not restore the full software catalog: $($_.Exception.Message)" ERROR Software
                try {
                    $script:ShowInstalledOnly = $false
                    if ($script:AppsView) { $script:AppsView.Refresh() }
                    if ($script:AppsView) { Reset-AMRSoftwareGridPages -View $script:AppsView }
                } catch {
                    Write-AMRLog "Fallback full-catalog rebuild also failed: $($_.Exception.Message)" ERROR Software
                }
            }
            finally {
                Set-AMRShowInstalledButtonBusy -Busy $false -Label 'Show Installed'
                Set-AMRShowInstalledButtonMode -Mode All
                $button = C 'ShowInstalledBtn'
                if ($button) {
                    $button.Content = 'Show Installed'
                    $button.ToolTip = 'Show only applications detected as installed on this PC.'
                    $button.IsEnabled = $true
                }
                $script:ShowAllReturnTimer = $null
                Resume-AMRSoftwareCatalogPaging -DelayMilliseconds 250
            }
        })
        $script:ShowAllReturnTimer.Start()
    }
})
(C 'SoftwareGrid').ItemsSource = $script:SoftwareGridPageItems
# Copy button lives inside the installed-card DataTemplate; handle its routed click once at the grid.
(C 'SoftwareScrollViewer').AddHandler([System.Windows.Controls.Button]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($sender, $e)
    $copyButton = $e.OriginalSource
    if ($null -eq $copyButton -or [string]$copyButton.Name -ne 'InstalledCopyPathBtn') { return }
    $pathToCopy = [string]$copyButton.Tag
    if ([string]::IsNullOrWhiteSpace($pathToCopy) -or $pathToCopy -eq 'Not recorded by Windows') { return }
    try { [System.Windows.Clipboard]::SetText($pathToCopy) } catch { Show-AMRMessageGlass ('Could not copy installation path: ' + [string]$_.Exception.Message) 'Copy Install Path' OK Warning | Out-Null }
}, $true)
# Explicitly control the installed details panel on the UI thread. PSCustomObject
# inventory rows do not implement INotifyPropertyChanged, so XAML-only triggers
# can fail to refresh after the arrow is clicked.
(C 'SoftwareScrollViewer').AddHandler([System.Windows.Controls.Primitives.ToggleButton]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($sender, $e)
    $toggle = $e.OriginalSource
    if ($null -eq $toggle -or [string]$toggle.Name -ne 'InstalledDetailsToggle') { return }
    try {
        $node = [System.Windows.DependencyObject]$toggle
        $card = $null
        while ($null -ne $node) {
            if ($node -is [System.Windows.Controls.Border] -and $node.Child -is [System.Windows.Controls.Grid]) { $card = $node; break }
            $node = [System.Windows.Media.VisualTreeHelper]::GetParent($node)
        }
        if ($null -eq $card) { return }
        $popup = $toggle.FindName('InstalledDetailsPopup')
        if ($null -eq $popup) { return }
        $isExpanded = [bool]$toggle.IsChecked
        # Popup is hosted in its own WPF window, so it renders above every
        # neighboring item container without changing the card/grid layout.
        # SetCurrentValue keeps the XAML IsOpen binding alive (a plain assignment removed it, so recycled cards showed stale popups).
        $popup.SetCurrentValue([System.Windows.Controls.Primitives.Popup]::IsOpenProperty, [bool]$isExpanded)
        # The popup body is a lazy Control template (built on first open): realize it now so the copy button exists.
        try { if ($isExpanded -and $popup.Child -is [System.Windows.FrameworkElement]) { [void]$popup.Child.ApplyTemplate() } } catch {}
        $copyButton = Find-AMRNamedVisualChild -Parent $popup.Child -Name 'InstalledCopyPathBtn'
        if ($null -ne $copyButton -and $copyButton.Uid -ne 'AMR_COPY_HANDLER_ATTACHED') {
            $copyButton.Uid = 'AMR_COPY_HANDLER_ATTACHED'
            # Same hover lift, glow and press pop as the Activation copy button (reuses its motion helpers; Activation itself is not modified).
            try { Set-AMRActivationCopyButtonMotion -Button $copyButton } catch {}
            # Round 20: the glyph becomes a TextBlock with its own RotateTransform so it can spin on copy without touching the button's hover scale transform.
            try {
                $copyGlyph = New-Object System.Windows.Controls.TextBlock
                $copyGlyph.Text = [string]$copyButton.Content
                $copyGlyph.FontSize = [double]$copyButton.FontSize
                $copyGlyph.FontWeight = $copyButton.FontWeight
                $copyGlyph.Foreground = $copyButton.Foreground
                $copyGlyph.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
                $copyGlyph.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
                $copyGlyph.RenderTransformOrigin = New-Object System.Windows.Point(0.5, 0.5)
                $copyGlyph.RenderTransform = New-Object System.Windows.Media.RotateTransform(0.0)
                $copyButton.Content = $copyGlyph
            } catch {}
            $copyButton.AddHandler([System.Windows.Controls.Button]::ClickEvent, [System.Windows.RoutedEventHandler]{
                param($copySender, $copyEvent)
                $pathToCopy = [string]$copySender.Tag
                if ([string]::IsNullOrWhiteSpace($pathToCopy) -or $pathToCopy -eq 'Not recorded by Windows') { return }
                try { [System.Windows.Clipboard]::SetText($pathToCopy); Invoke-AMRPopupCopyButtonFeedback -Button $copySender } catch { Show-AMRMessageGlass ('Could not copy installation path: ' + [string]$_.Exception.Message) 'Copy Install Path' OK Warning | Out-Null }
            }, $true)
        }
        $toggle.Content = if ($isExpanded) { '⌃' } else { '⌄' }
        $toggle.ToolTip = if ($isExpanded) { 'Hide installation details' } else { 'Show installation details' }
        $item = $toggle.DataContext
        if ($null -ne $item -and $item.PSObject.Properties['DetailsExpanded']) { $item.DetailsExpanded = $isExpanded }
        # Only one details popup is open at a time; remember it so scroll/resize can close it.
        if ($isExpanded) {
            if ($null -ne $script:AMRDetailsOpenToggle -and -not [object]::ReferenceEquals($script:AMRDetailsOpenToggle,$toggle)) { Close-AMRInstalledDetails }
            $script:AMRDetailsOpenToggle = $toggle
            $script:AMRDetailsOpenPopup = $popup
        } elseif ([object]::ReferenceEquals($script:AMRDetailsOpenToggle,$toggle)) {
            $script:AMRDetailsOpenToggle = $null
            $script:AMRDetailsOpenPopup = $null
        }
        Start-AMRDetailsArrowTurn -Toggle $toggle
    } catch { Write-AMRLog ("Could not toggle installed application details: $($_.Exception.Message)") WARNING Software }
}, $true)

# --- Show Installed details arrow: close-on-scroll popup handling, small arrow turn, hover marquee for long names ---
$script:AMRDetailsOpenToggle = $null
$script:AMRDetailsOpenPopup = $null
$script:AMRMarqueeTb = $null
$script:AMRMarqueeLastSrc = $null

function Close-AMRInstalledDetails {
    $closeToggle = $script:AMRDetailsOpenToggle
    $script:AMRDetailsOpenToggle = $null
    $script:AMRDetailsOpenPopup = $null
    if ($null -eq $closeToggle) { return }
    try {
        if ($closeToggle.IsChecked) { $closeToggle.IsChecked = $false }
        $closeToggle.Content = [string][char]0x2304
        $closeToggle.ToolTip = 'Show installation details'
        $closeItem = $closeToggle.DataContext
        if ($null -ne $closeItem -and $closeItem.PSObject.Properties['DetailsExpanded']) { $closeItem.DetailsExpanded = $false }
    } catch {}
}

function Start-AMRDetailsArrowTurn {
    param($Toggle)
    # One short turn of the arrow glyph (about 160 ms). The new glyph is already set, so it turns from the old direction.
    try {
        $glyph = $Toggle.Template.FindName('ArrowGlyph', $Toggle)
        if ($null -eq $glyph) { return }
        $turn = $glyph.RenderTransform
        if (-not ($turn -is [System.Windows.Media.RotateTransform]) -or $turn.IsFrozen) {
            $turn = New-Object System.Windows.Media.RotateTransform(0.0)
            $glyph.RenderTransform = $turn
        }
        $turnAnim = New-Object System.Windows.Media.Animation.DoubleAnimation(180.0, 0.0, [TimeSpan]::FromMilliseconds(160))
        $turnEase = New-Object System.Windows.Media.Animation.CubicEase
        $turnEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $turnAnim.EasingFunction = $turnEase
        $turn.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $turnAnim)
    } catch {}
}

function Find-AMRFirstTextBlock {
    # Template elements built with FrameworkElementFactory keep an empty Name property, so the category label is found by type.
    param([System.Windows.DependencyObject]$Parent)
    if ($null -eq $Parent) { return $null }
    try {
        $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Parent)
        for ($i = 0; $i -lt $count; $i++) {
            $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Parent, $i)
            if ($child -is [System.Windows.Controls.TextBlock]) { return $child }
            $found = Find-AMRFirstTextBlock -Parent $child
            if ($null -ne $found) { return $found }
        }
    } catch {}
    return $null
}

function Invoke-AMRPopupCopyButtonFeedback {
    # Popup copy button: r17 press pop + amber glow pulse (same values as the Activation copy button, but they settle on the hover values
    # while the pointer is still over the button) plus a 360 degree glyph spin (620 ms, ease out) on the glyph's own RotateTransform.
    # No button translate/tilt wobble: the button has only the hover ScaleTransform, so the three motions never share a transform.
    param([System.Windows.Controls.Button]$Button)
    if (-not $Button) { return }
    $hovered = [bool]$Button.IsMouseOver
    if ($Button.RenderTransform -is [System.Windows.Media.ScaleTransform] -and -not $Button.RenderTransform.IsFrozen) {
        $popScale = $Button.RenderTransform
        $popEnd = 1.0; if ($hovered) { $popEnd = 1.055 }
        $press = [System.Windows.Media.Animation.DoubleAnimation]::new(0.93, $popEnd, [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(175)))
        $press.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
        $press.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $popScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $press)
        $popScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $press)
    }
    $popEffect = $Button.Effect
    if ($popEffect -is [System.Windows.Media.Effects.DropShadowEffect] -and -not $popEffect.IsFrozen) {
        $glowEnd = 0.12; if ($hovered) { $glowEnd = 0.62 }
        $pulse = [System.Windows.Media.Animation.DoubleAnimation]::new(0.9, $glowEnd, [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(210)))
        $popEffect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty, $pulse)
    }
    $popGlyph = $Button.Content
    if ($popGlyph -is [System.Windows.Controls.TextBlock] -and $popGlyph.RenderTransform -is [System.Windows.Media.RotateTransform] -and -not $popGlyph.RenderTransform.IsFrozen) {
        $spin = [System.Windows.Media.Animation.DoubleAnimation]::new(0.0, 360.0, [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(620)))
        $spin.EasingFunction = [System.Windows.Media.Animation.CubicEase]::new()
        $spin.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $popGlyph.RenderTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $spin)
    }
}

# --- Hidden "delete" command (About page): wipes C:\ProgramData\AMR-Utility only (nothing else), after a glass confirmation. ---
function Remove-AMRWipeTree {
    # Deletes everything inside $Directory. Links/junctions are removed as links and never followed, so nothing outside the tree can be touched.
    param([System.IO.DirectoryInfo]$Directory,$State)
    foreach ($entry in @($Directory.GetFileSystemInfos())) {
        $isLink = (([int]$entry.Attributes -band [int][System.IO.FileAttributes]::ReparsePoint) -ne 0)
        $isDir = ($entry -is [System.IO.DirectoryInfo])
        try {
            if ($isDir -and -not $isLink) {
                $failedBefore = [int]$State.FailedCount
                Remove-AMRWipeTree -Directory $entry -State $State
                if ([int]$State.FailedCount -gt $failedBefore) { continue }
                try { [System.IO.File]::SetAttributes($entry.FullName, [System.IO.FileAttributes]::Directory) } catch {}
                $entry.Delete()
            } elseif ($isDir) {
                [System.IO.Directory]::Delete($entry.FullName)
            } else {
                try { [System.IO.File]::SetAttributes($entry.FullName, [System.IO.FileAttributes]::Normal) } catch {}
                $entry.Delete()
            }
            $State.Deleted = [int]$State.Deleted + 1
        } catch {
            $State.FailedCount = [int]$State.FailedCount + 1
            if ($State.Failed.Count -lt 40) { [void]$State.Failed.Add([string]$entry.FullName + '  (' + [string]$_.Exception.Message + ')') }
        }
    }
}

function Invoke-AMRWipeAppData {
    param([string]$Root,[string]$ExpectedRoot)
    $result = [pscustomobject]@{ Aborted = $false; Reason = ''; Deleted = 0; FailedCount = 0; Failed = (New-Object 'System.Collections.Generic.List[string]') }
    try {
        if ([string]::IsNullOrWhiteSpace($Root) -or [string]::IsNullOrWhiteSpace($ExpectedRoot)) { $result.Aborted = $true; $result.Reason = 'The data folder path is empty.'; return $result }
        $full = [System.IO.Path]::GetFullPath($Root).TrimEnd([char]'\',[char]'/')
        $expected = [System.IO.Path]::GetFullPath($ExpectedRoot).TrimEnd([char]'\',[char]'/')
        if (-not [string]::Equals($full, $expected, [System.StringComparison]::OrdinalIgnoreCase)) { $result.Aborted = $true; $result.Reason = 'The target path does not match the expected data folder.'; return $result }
        if ([System.IO.Path]::GetFileName($expected) -ne 'AMR-Utility') { $result.Aborted = $true; $result.Reason = 'The target folder name is not AMR-Utility.'; return $result }
        $parent = [System.IO.Path]::GetDirectoryName($expected)
        if ([string]::IsNullOrWhiteSpace($parent)) { $result.Aborted = $true; $result.Reason = 'The target has no parent folder.'; return $result }
        if (-not [System.IO.Directory]::Exists($full)) { return $result }
        $rootInfo = New-Object System.IO.DirectoryInfo($full)
        if (([int]$rootInfo.Attributes -band [int][System.IO.FileAttributes]::ReparsePoint) -ne 0) { $result.Aborted = $true; $result.Reason = 'The data folder is a link; nothing was deleted.'; return $result }
        Remove-AMRWipeTree -Directory $rootInfo -State $result
    } catch {
        $result.Aborted = $true; $result.Reason = [string]$_.Exception.Message
    }
    return $result
}

function Show-AMRWipeConfirmDialog {
    # Glass confirmation in the About / S1 glass family. Enter confirms only as a fresh key press (not a repeat) at least 1 s after the dialog is shown;
    # Esc or Cancel aborts. No button is focusable, so a stray Space cannot press one.
    param([string]$TargetPath)
    $state = @{ Accepted = $false; Watch = $null }
    $window = New-Object System.Windows.Window
    $window.WindowStyle = 'None'; $window.ResizeMode = 'NoResize'; $window.ShowInTaskbar = $false; $window.SizeToContent = 'Height'; $window.Width = 560
    $window.WindowStartupLocation = 'CenterScreen'
    try { if ($script:Window -and $script:Window.IsVisible) { $window.Owner = $script:Window; $window.WindowStartupLocation = 'CenterOwner' } } catch {}
    $glassFill = $null; $glassEdge = $null
    try { $glassFill = $script:Window.TryFindResource('AMRSoftGlassBrush'); $glassEdge = $script:Window.TryFindResource('AMRSoftGlassEdgeBrush') } catch {}
    $transparentOk = $true
    try { if (([int]([System.Windows.Media.RenderCapability]::Tier -shr 16)) -lt 2) { $transparentOk = $false } } catch {}
    $root = New-Object System.Windows.Controls.Border
    $root.CornerRadius = New-Object System.Windows.CornerRadius(14)
    $root.BorderThickness = New-Object System.Windows.Thickness(1)
    $root.Padding = New-Object System.Windows.Thickness(22,18,22,18)
    if ($transparentOk) {
        $window.AllowsTransparency = $true
        $window.Background = [System.Windows.Media.Brushes]::Transparent
        $root.Margin = New-Object System.Windows.Thickness(6)
        if ($null -ne $glassFill) { $root.Background = $glassFill } else { $root.Background = New-AMRGlassBrush '#F0191C21' }
    } else {
        $window.Background = New-AMRGlassBrush '#FF191C21'
        $root.Background = New-AMRGlassBrush '#FF1A1D22'
    }
    if ($null -ne $glassEdge) { $root.BorderBrush = $glassEdge } else { $root.BorderBrush = New-AMRGlassBrush '#33FFFFFF' }
    $stack = New-Object System.Windows.Controls.StackPanel
    $title = New-Object System.Windows.Controls.TextBlock
    $title.Text = ([string][char]0x26A0) + '  Delete all AMR data'; $title.FontSize = 17; $title.FontWeight = 'SemiBold'; $title.Foreground = New-AMRGlassBrush '#F2CDD0'
    $title.Margin = New-Object System.Windows.Thickness(0,0,0,10)
    $ask = New-Object System.Windows.Controls.TextBlock
    $ask.Text = 'Do you agree to delete all data?'; $ask.FontSize = 14; $ask.FontWeight = 'SemiBold'; $ask.Foreground = New-AMRGlassBrush '#E5F1FF'
    $ask.Margin = New-Object System.Windows.Thickness(0,0,0,6)
    $what = New-Object System.Windows.Controls.TextBlock
    $what.Text = 'This permanently deletes everything inside this folder:'; $what.FontSize = 12; $what.Foreground = New-AMRGlassBrush '#B8CDE4'; $what.TextWrapping = 'Wrap'
    $what.Margin = New-Object System.Windows.Thickness(0,0,0,8)
    $pathBox = New-Object System.Windows.Controls.Border
    $pathBox.Background = New-AMRGlassBrush '#33000000'; $pathBox.BorderBrush = New-AMRGlassBrush '#26FFFFFF'; $pathBox.BorderThickness = New-Object System.Windows.Thickness(1)
    $pathBox.CornerRadius = New-Object System.Windows.CornerRadius(8); $pathBox.Padding = New-Object System.Windows.Thickness(10,8,10,8)
    $pathText = New-Object System.Windows.Controls.TextBlock
    $pathText.Text = $TargetPath; $pathText.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas'); $pathText.FontSize = 12.5; $pathText.Foreground = New-AMRGlassBrush '#F4EAD5'; $pathText.TextWrapping = 'Wrap'
    $pathBox.Child = $pathText
    $detail = New-Object System.Windows.Controls.TextBlock
    $detail.Text = 'All backups and restore data (driver and Windows Update backups, the Tweaks baseline, quarantined items), logs, exports, icons and downloaded installers are included. This cannot be undone.'
    $detail.FontSize = 12; $detail.Foreground = New-AMRGlassBrush '#C7DDF4'; $detail.TextWrapping = 'Wrap'; $detail.LineHeight = 18
    $detail.Margin = New-Object System.Windows.Thickness(0,10,0,10)
    $hint = New-Object System.Windows.Controls.TextBlock
    $hint.Text = 'Press Enter to delete   |   Esc to cancel'; $hint.FontSize = 11; $hint.Foreground = New-AMRGlassBrush '#8FA3B8'
    $hint.VerticalAlignment = 'Center'
    $buttonRow = New-Object System.Windows.Controls.DockPanel
    $buttonRow.LastChildFill = $false
    $buttonRow.Margin = New-Object System.Windows.Thickness(0,4,0,0)
    $makeButton = {
        param([string]$Text,[string]$Role)
        $b = New-Object System.Windows.Controls.Button
        $b.Content = $Text; $b.MinWidth = 120; $b.Height = 32; $b.Margin = New-Object System.Windows.Thickness(8,0,0,0)
        $b.Foreground = New-AMRGlassBrush '#F4F7FA'; $b.Cursor = [System.Windows.Input.Cursors]::Hand
        $b.Focusable = $false; $b.IsTabStop = $false; $b.IsDefault = $false; $b.IsCancel = $false
        try { $b.Style = New-AMRGlassButtonStyle -Role $Role -Animated } catch { $b.Background = New-AMRGlassBrush '#FF303846'; $b.BorderBrush = New-AMRGlassBrush '#FF526176' }
        return $b
    }
    $cancelButton = & $makeButton 'Cancel' 'Blue'
    $deleteButton = & $makeButton 'Delete all data' 'Red'
    [System.Windows.Controls.DockPanel]::SetDock($deleteButton, [System.Windows.Controls.Dock]::Right)
    [System.Windows.Controls.DockPanel]::SetDock($cancelButton, [System.Windows.Controls.Dock]::Right)
    [System.Windows.Controls.DockPanel]::SetDock($hint, [System.Windows.Controls.Dock]::Left)
    [void]$buttonRow.Children.Add($hint); [void]$buttonRow.Children.Add($deleteButton); [void]$buttonRow.Children.Add($cancelButton)
    foreach ($child in @($title,$ask,$what,$pathBox,$detail,$buttonRow)) { [void]$stack.Children.Add($child) }
    $root.Child = $stack
    $window.Content = $root
    $window.Focusable = $true
    $cancelButton.Add_Click({ param($s,$e) [System.Windows.Window]::GetWindow($s).Close() })
    $deleteButton.Add_Click({
        param($s,$e)
        $w = $state['Watch']
        if ($null -ne $w -and $w.ElapsedMilliseconds -ge 1000) { $state['Accepted'] = $true; [System.Windows.Window]::GetWindow($s).Close() }
    }.GetNewClosure())
    $window.Add_PreviewKeyDown({
        param($s,$e)
        if ($e.Key -eq [System.Windows.Input.Key]::Escape) { $e.Handled = $true; $s.Close(); return }
        if ($e.Key -eq [System.Windows.Input.Key]::Enter -or $e.Key -eq [System.Windows.Input.Key]::Return) {
            $e.Handled = $true
            $w = $state['Watch']
            if (-not $e.IsRepeat -and $null -ne $w -and $w.ElapsedMilliseconds -ge 1000) { $state['Accepted'] = $true; $s.Close() }
            return
        }
        if ($e.Key -eq [System.Windows.Input.Key]::Space) { $e.Handled = $true }
    }.GetNewClosure())
    $window.Add_ContentRendered({
        param($s,$e)
        $state['Watch'] = [System.Diagnostics.Stopwatch]::StartNew()
        try { [void]$s.Focus() } catch {}
    }.GetNewClosure())
    $root.Add_MouseLeftButtonDown({ param($s,$e) try { if ($e.OriginalSource -isnot [System.Windows.Controls.Primitives.ButtonBase]) { [System.Windows.Window]::GetWindow($s).DragMove() } } catch {} })
    [void]$window.ShowDialog()
    return [bool]$state['Accepted']
}

function Start-AMRWipeFinishHelper {
    # Used only when something stayed locked after the in-process delete: a hidden PowerShell waits for this process to exit, retries the same guarded delete, then removes the empty folder.
    param([string]$Target)
    try {
        $quotedTarget = "'" + $Target.Replace("'", "''") + "'"
        $helperText = "function Remove-AMRWipeTree {`n" + ${function:Remove-AMRWipeTree}.ToString() + "`n}`nfunction Invoke-AMRWipeAppData {`n" + ${function:Invoke-AMRWipeAppData}.ToString() + "`n}`n" +
            '$ErrorActionPreference = ''SilentlyContinue''' + "`n" +
            ('$p = Get-Process -Id {0} -ErrorAction SilentlyContinue; if ($p) {{ [void]$p.WaitForExit(120000) }}' -f $PID) + "`n" +
            ('for ($i = 0; $i -lt 14; $i++) {{ $r = Invoke-AMRWipeAppData -Root {0} -ExpectedRoot {0}; if ($r.Aborted -or $r.FailedCount -eq 0) {{ break }}; Start-Sleep -Milliseconds 700 }}' -f $quotedTarget) + "`n" +
            ('try {{ if ([System.IO.Directory]::Exists({0})) {{ [System.IO.Directory]::Delete({0}) }} }} catch {{}}' -f $quotedTarget) + "`n"
        $encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($helperText))
        if ($encoded.Length -gt 30000) { return $false }
        Start-Process -FilePath 'powershell.exe' -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-EncodedCommand',$encoded) -WindowStyle Hidden -ErrorAction Stop | Out-Null
        return $true
    } catch { return $false }
}

function Invoke-AMRWipeFromHotkey {
    $programData = [string]$env:ProgramData
    if ([string]::IsNullOrWhiteSpace($programData)) { [void](Show-AMRMessageGlass 'ProgramData could not be resolved. Nothing was deleted.' 'Delete all data' OK Warning); return }
    $target = Join-Path $programData 'AMR-Utility'
    if (-not [string]::Equals([System.IO.Path]::GetFullPath($target).TrimEnd('\','/'), [System.IO.Path]::GetFullPath([string]$script:AppRoot).TrimEnd('\','/'), [System.StringComparison]::OrdinalIgnoreCase)) {
        [void](Show-AMRMessageGlass 'The data folder does not match the expected location. Nothing was deleted.' 'Delete all data' OK Warning); return
    }
    if (-not (Show-AMRWipeConfirmDialog -TargetPath $target)) { return }
    try { [AMRLogDiskWriter]::FlushNow() } catch {}
    $previousCursor = $null
    try { $previousCursor = $script:Window.Cursor; $script:Window.Cursor = [System.Windows.Input.Cursors]::Wait } catch {}
    $wipe = $null
    try { $wipe = Invoke-AMRWipeAppData -Root $target -ExpectedRoot $target } finally { try { $script:Window.Cursor = $previousCursor } catch {} }
    if ($wipe.Aborted) {
        [void](Show-AMRMessageGlass ("Nothing was deleted (or the delete stopped early): " + [string]$wipe.Reason + "`n`nItems removed before it stopped: " + [string]$wipe.Deleted) 'Delete all data' OK Warning)
        return
    }
    if ([int]$wipe.FailedCount -eq 0) {
        # Empty standard folders are recreated (exactly what startup does) so the running app keeps working; no file is restored.
        try { New-Item -ItemType Directory -Force -Path $script:BackupDir,$script:LogDir,$script:ExportDir,$script:IconDir,$script:DownloadDir | Out-Null } catch {}
        [void](Show-AMRMessageGlass ("All data was deleted from:`n" + $target + "`n`nItems removed: " + [string]$wipe.Deleted + "`n`nThe app is still running, so it may write new log lines and cache files again. Close and reopen it for a fully clean start.") 'Delete all data' OK Information)
        return
    }
    $listText = (@($wipe.Failed | Select-Object -First 8) -join "`n")
    $helperStarted = Start-AMRWipeFinishHelper -Target $target
    if ($helperStarted) {
        [void](Show-AMRMessageGlass ("Not everything could be deleted now. Items removed: " + [string]$wipe.Deleted + ". Items still in use or protected: " + [string]$wipe.FailedCount + ".`n`n" + $listText + "`n`nThe app will close now. A background helper will retry the delete after it exits and remove the empty folder. If you reopen the app straight away, run the delete again to check.") 'Delete all data' OK Warning)
        try { $script:Window.Close() } catch {}
    } else {
        [void](Show-AMRMessageGlass ("Not everything could be deleted. Items removed: " + [string]$wipe.Deleted + ". Items still in use or protected: " + [string]$wipe.FailedCount + ".`n`n" + $listText + "`n`nThe background helper could not be started. Close the app and use the delete command again.") 'Delete all data' OK Warning)
    }
}

function Stop-AMRMarquee {
    $stopTb = $script:AMRMarqueeTb
    $script:AMRMarqueeTb = $null
    $script:AMRMarqueeLastSrc = $null
    if ($null -eq $stopTb) { return }
    try {
        $stopTransform = $stopTb.RenderTransform
        if ($stopTransform -is [System.Windows.Media.TranslateTransform] -and -not $stopTransform.IsFrozen) {
            $stopTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
        }
        $stopClip = $stopTb.Clip
        if ($stopClip -is [System.Windows.Media.RectangleGeometry] -and $stopClip.Transform -is [System.Windows.Media.TranslateTransform] -and -not $stopClip.Transform.IsFrozen) {
            $stopClip.Transform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
        }
        $stopTb.Clip = $null
        $stopTb.RenderTransform = [System.Windows.Media.Transform]::Identity
        $stopTb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
    } catch {}
}

function New-AMRMarqueeKeyFrames {
    param([double]$Distance, [double]$SlideSeconds)
    $marqueeAnim = New-Object System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
    $marqueeAnim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $holdStart = 0.45; $holdEnd = 0.35
    $marqueeTimes = @(0.0, $holdStart, ($holdStart + $SlideSeconds), ($holdStart + $SlideSeconds + $holdEnd))
    $marqueeValues = @(0.0, 0.0, $Distance, $Distance)
    for ($frameIndex = 0; $frameIndex -lt 4; $frameIndex++) {
        $frameKey = [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromSeconds([double]$marqueeTimes[$frameIndex]))
        [void]$marqueeAnim.KeyFrames.Add((New-Object System.Windows.Media.Animation.LinearDoubleKeyFrame([double]$marqueeValues[$frameIndex], $frameKey)))
    }
    return $marqueeAnim
}

function Start-AMRMarquee {
    param($Tb)
    if ($null -eq $Tb -or [object]::ReferenceEquals($Tb, $script:AMRMarqueeTb)) { return }
    Stop-AMRMarquee
    try {
        # Only single-line text that is really cut off, left-to-right, and only while the pointer is over its card/row.
        if ($Tb.TextWrapping -ne [System.Windows.TextWrapping]::NoWrap) { return }
        if ($Tb.FlowDirection -ne [System.Windows.FlowDirection]::LeftToRight) { return }
        if ($Tb.ActualWidth -lt 8 -or [string]::IsNullOrEmpty($Tb.Text)) { return }
        $pixelsPerDip = 1.0
        try { $pixelsPerDip = [System.Windows.Media.VisualTreeHelper]::GetDpi($Tb).PixelsPerDip } catch {}
        $typeface = New-Object System.Windows.Media.Typeface($Tb.FontFamily, $Tb.FontStyle, $Tb.FontWeight, $Tb.FontStretch)
        $formatted = New-Object System.Windows.Media.FormattedText($Tb.Text, [System.Globalization.CultureInfo]::CurrentUICulture, [System.Windows.FlowDirection]::LeftToRight, $typeface, [double]$Tb.FontSize, [System.Windows.Media.Brushes]::White, [double]$pixelsPerDip)
        $overflow = [double]$formatted.WidthIncludingTrailingWhitespace - [double]$Tb.ActualWidth
        if ($overflow -le 2.0) { return }
        $travel = [Math]::Ceiling($overflow + 6.0)
        $slideSeconds = [Math]::Max(0.7, $travel / 45.0)
        $marqueeShift = New-Object System.Windows.Media.TranslateTransform(0.0, 0.0)
        $marqueeClip = New-Object System.Windows.Media.RectangleGeometry((New-Object System.Windows.Rect(0.0, 0.0, [double]$Tb.ActualWidth, [double]$Tb.ActualHeight)))
        $clipShift = New-Object System.Windows.Media.TranslateTransform(0.0, 0.0)
        $marqueeClip.Transform = $clipShift
        $Tb.TextTrimming = [System.Windows.TextTrimming]::None
        $Tb.RenderTransform = $marqueeShift
        $Tb.Clip = $marqueeClip
        # The clip moves with the text, so it is shifted the opposite way to stay on the original box.
        $marqueeShift.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, (New-AMRMarqueeKeyFrames -Distance (-$travel) -SlideSeconds $slideSeconds))
        $clipShift.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, (New-AMRMarqueeKeyFrames -Distance $travel -SlideSeconds $slideSeconds))
        $script:AMRMarqueeTb = $Tb
    } catch { try { Stop-AMRMarquee } catch {} }
}

try {
    $detailsScroll = C 'SoftwareScrollViewer'
    # Scroll or resize closes any open details popup (it is a floating window and cannot follow its card) and stops the marquee.
    $detailsScroll.Add_ScrollChanged({
        param($sender, $eventArgs)
        if ($eventArgs.VerticalChange -ne 0 -or $eventArgs.HorizontalChange -ne 0) {
            if ($null -ne $script:AMRDetailsOpenToggle) { Close-AMRInstalledDetails }
            if ($null -ne $script:AMRMarqueeTb) { Stop-AMRMarquee }
        }
    })
    $detailsScroll.Add_SizeChanged({
        if ($null -ne $script:AMRDetailsOpenToggle) { Close-AMRInstalledDetails }
        if ($null -ne $script:AMRMarqueeTb) { Stop-AMRMarquee }
    })
    # A click outside closes the popup by itself; bring the arrow back in sync (skip when the click is on the arrow, its own click handles it).
    $script:Window.AddHandler([System.Windows.UIElement]::PreviewMouseLeftButtonDownEvent, [System.Windows.Input.MouseButtonEventHandler]{
        if ($null -eq $script:AMRDetailsOpenToggle) { return }
        if ($script:AMRDetailsOpenToggle.IsMouseOver) { return }
        $null = $script:Window.Dispatcher.BeginInvoke([Action]{
            try {
                $syncPopup = $script:AMRDetailsOpenPopup
                if ($null -ne $syncPopup -and -not $syncPopup.IsOpen) { Close-AMRInstalledDetails }
            } catch {}
        }, [System.Windows.Threading.DispatcherPriority]::Background)
    }, $true)

    $marqueeMoveHandler = [System.Windows.Input.MouseEventHandler]{
        param($sender, $eventArgs)
        try {
            $moveSource = $eventArgs.OriginalSource
            if ([object]::ReferenceEquals($moveSource, $script:AMRMarqueeLastSrc)) { return }
            $script:AMRMarqueeLastSrc = $moveSource
            $marqueeTarget = $null
            $moveNode = $moveSource
            for ($depth = 0; $depth -lt 16 -and $null -ne $moveNode; $depth++) {
                if ($moveNode -is [System.Windows.FrameworkElement]) {
                    if ($moveNode.Name -eq 'SoftwareCardSurface') { $marqueeTarget = Find-AMRNamedVisualChild -Parent $moveNode -Name 'SoftwareNameText'; break }
                    if ($moveNode -is [System.Windows.Controls.ListBoxItem]) { $marqueeTarget = Find-AMRFirstTextBlock -Parent $moveNode; break }
                }
                if ($moveNode -isnot [System.Windows.Media.Visual]) { break }
                $moveNode = [System.Windows.Media.VisualTreeHelper]::GetParent($moveNode)
            }
            if ($null -ne $marqueeTarget) { Start-AMRMarquee -Tb $marqueeTarget }
            elseif ($null -ne $script:AMRMarqueeTb) { Stop-AMRMarquee }
        } catch {}
    }
    $marqueeLeaveHandler = [System.Windows.Input.MouseEventHandler]{ if ($null -ne $script:AMRMarqueeTb) { Stop-AMRMarquee } }
    $marqueeCategoryList = C 'SoftwareCategoryList'
    foreach ($marqueeHost in @($detailsScroll, $marqueeCategoryList)) {
        if ($null -eq $marqueeHost) { continue }
        $marqueeHost.AddHandler([System.Windows.UIElement]::PreviewMouseMoveEvent, $marqueeMoveHandler)
        $marqueeHost.AddHandler([System.Windows.UIElement]::MouseLeaveEvent, $marqueeLeaveHandler)
    }
} catch { Write-AMRLog ('Could not attach Software details/marquee handlers: ' + $_.Exception.Message) WARNING Software }


# Hidden "delete" key sequence (About page only): D E L E T E typed within 2 s between keys, no modifiers, focus not in a text control.
# Keys are matched on the Key enum (layout independent). The sequence only opens the glass confirmation; nothing is deleted before Enter there.
try {
    $script:AMRWipeSequence = @([System.Windows.Input.Key]::D,[System.Windows.Input.Key]::E,[System.Windows.Input.Key]::L,[System.Windows.Input.Key]::E,[System.Windows.Input.Key]::T,[System.Windows.Input.Key]::E)
    $script:AMRWipeIndex = 0
    $script:AMRWipeLastMs = [long]0
    $script:AMRWipeBusy = $false
    $script:AMRWipeClock = [System.Diagnostics.Stopwatch]::StartNew()
    $script:AMRWipeTabs = C 'MainNavigationTabs'
    $script:Window.AddHandler([System.Windows.UIElement]::PreviewKeyDownEvent, [System.Windows.Input.KeyEventHandler]{
        param($sender, $keyArgs)
        try {
            if ($script:AMRWipeBusy -or $keyArgs.IsRepeat) { return }
            $wipeTabs = $script:AMRWipeTabs
            if ($null -eq $wipeTabs -or $null -eq $wipeTabs.SelectedItem -or [string]$wipeTabs.SelectedItem.Header -ne 'About') { $script:AMRWipeIndex = 0; return }
            if ([System.Windows.Input.Keyboard]::Modifiers -ne [System.Windows.Input.ModifierKeys]::None) { $script:AMRWipeIndex = 0; return }
            $focused = [System.Windows.Input.Keyboard]::FocusedElement
            # The shared search box at the top is visible on the About page (placeholder 'Search about this application...') and is where a typed word most likely goes,
            # so typing in THAT box counts too. Any other text control (or a combo box) still blocks the sequence.
            $focusIsSearchBox = $false
            try { $focusIsSearchBox = ($null -ne $script:SmartSearchBox -and [object]::ReferenceEquals($focused, $script:SmartSearchBox)) } catch {}
            if (-not $focusIsSearchBox -and ($focused -is [System.Windows.Controls.Primitives.TextBoxBase] -or $focused -is [System.Windows.Controls.ComboBox] -or $focused -is [System.Windows.Controls.PasswordBox])) { $script:AMRWipeIndex = 0; return }
            $nowMs = [long]$script:AMRWipeClock.ElapsedMilliseconds
            if (($nowMs - [long]$script:AMRWipeLastMs) -gt 2000) { $script:AMRWipeIndex = 0 }
            $script:AMRWipeLastMs = $nowMs
            $pressed = $keyArgs.Key
            if ($pressed -eq [System.Windows.Input.Key]::ImeProcessed) { $pressed = $keyArgs.ImeProcessedKey }
            if ($pressed -eq $script:AMRWipeSequence[[int]$script:AMRWipeIndex]) { $script:AMRWipeIndex = [int]$script:AMRWipeIndex + 1 }
            elseif ($pressed -eq $script:AMRWipeSequence[0]) { $script:AMRWipeIndex = 1 }
            else { $script:AMRWipeIndex = 0 }
            if ([int]$script:AMRWipeIndex -ge $script:AMRWipeSequence.Count) {
                $script:AMRWipeIndex = 0
                $script:AMRWipeBusy = $true
                $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                    try {
                        # Remove the six typed letters from the shared search box so the About filter does not keep them.
                        try {
                            $typedBox = $script:SmartSearchBox
                            if ($null -ne $typedBox -and [string]$typedBox.Text -match '(?i)delete$') { $typedBox.Text = [string]$typedBox.Text.Substring(0, $typedBox.Text.Length - 6) }
                        } catch {}
                        Invoke-AMRWipeFromHotkey
                    } catch { try { Write-AMRLog ('Delete command failed: ' + $_.Exception.Message) WARNING System } catch {} } finally { $script:AMRWipeBusy = $false }
                }, [System.Windows.Threading.DispatcherPriority]::Background)
            }
        } catch {}
    })
} catch { try { Write-AMRLog ('Could not attach the About key sequence: ' + $_.Exception.Message) WARNING System } catch {} }

Reset-AMRSoftwareGridPages -View $script:AppsView

# Make the complete Software card a one-click selection surface. Buttons,
# checkboxes and the details arrow retain their own click behavior.
try {
    $softwareCardGrid = C 'SoftwareGrid'
    if ($softwareCardGrid -and -not $script:SoftwareCardSelectionHandlerAttached) {
        $script:SoftwareCardSelectionHandler = [System.Windows.Input.MouseButtonEventHandler]{
            param($sender,$eventArgs)
            try {
                $node = $eventArgs.OriginalSource
                while ($null -ne $node -and $node -ne $sender) {
                    if ($node -is [System.Windows.Controls.Primitives.ButtonBase] -or
                        $node -is [System.Windows.Controls.Primitives.TextBoxBase] -or
                        $node -is [System.Windows.Controls.Primitives.Selector]) {
                        return
                    }
                    if ($node -is [System.Windows.FrameworkElement]) {
                        $candidate = $node.DataContext
                        if ($null -ne $candidate -and $candidate.PSObject.Properties['IsSelected']) {
                            $candidate.IsSelected = -not [bool]$candidate.IsSelected
                            $eventArgs.Handled = $true
                            return
                        }
                    }
                    try { $node = [System.Windows.Media.VisualTreeHelper]::GetParent($node) }
                    catch { try { $node = [System.Windows.LogicalTreeHelper]::GetParent($node) } catch { $node = $null } }
                }
            } catch {
                try { Write-AMRLog ('Software card selection click was ignored: ' + $_.Exception.Message) WARNING Software } catch {}
            }
        }.GetNewClosure()
        $softwareCardGrid.AddHandler(
            [System.Windows.UIElement]::MouseLeftButtonUpEvent,
            $script:SoftwareCardSelectionHandler,
            $true
        )
        $script:SoftwareCardSelectionHandlerAttached = $true
    }
} catch {
    Write-AMRLog ('Could not attach whole-card selection interaction: ' + $_.Exception.Message) WARNING Software
}

try {
    $script:AMRStartupPhaseTimings['InitialCatalogPreparedMs'] = [int]$script:AMRStartupStopwatch.ElapsedMilliseconds
    Write-AMRLog ('Startup timing checkpoint: ' + (($script:AMRStartupPhaseTimings.GetEnumerator() | ForEach-Object { '{0}={1}ms' -f $_.Key,$_.Value }) -join '; ')) INFO Startup
} catch {}

# Keep a consistent four-column Software card layout in normal and maximized states.
function Find-AMRVisualChildByType {
    param(
        [System.Windows.DependencyObject]$Parent,
        [type]$ChildType
    )
    if ($null -eq $Parent) { return $null }
    $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Parent)
    for ($i = 0; $i -lt $count; $i++) {
        $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Parent, $i)
        if ($ChildType.IsAssignableFrom($child.GetType())) { return $child }
        $found = Find-AMRVisualChildByType -Parent $child -ChildType $ChildType
        if ($null -ne $found) { return $found }
    }
    return $null
}

# Re-apply icon state to realized cards. The catalog uses PSCustomObject models,
# which do not raise PropertyChanged when Icon is assigned by the background worker.
# WPF can therefore recycle a card while retaining a stale/empty visual state.
function Write-AMRSoftwareVirtualizationRuntimeAudit {
    param([System.Windows.Controls.ItemsControl]$Grid)
    if (-not $script:SoftwareVirtualPanelReady -or $null -eq $Grid) { return }
    try {
        $panel = Find-AMRVisualChildByType -Parent $Grid -ChildType ([AMR.SoftwareVirtualizingUniformGridPanel])
        if ($null -eq $panel) {
            Write-AMRLog ('VIRTUALIZATION_RUNTIME surface=' + [string]$Grid.Uid + ' panel=not-found') WARNING Software
            return
        }
        $scrollHost = $script:Window.FindName('SoftwareScrollViewer')
        $hostConnected = ($null -ne $scrollHost -and [bool]$panel.ScrollHostConnected)
        Write-AMRLog (
            'VIRTUALIZATION_RUNTIME surface={0} realized={1} total={2} first={3} last={4} scrollHostConnected={5} viewportHeight={6:N0} extentHeight={7:N0} columns=4 recyclingGenerator={8} mode=viewport-physical' -f
            [string]$Grid.Uid,[int]$panel.RealizedItemCount,[int]$panel.TotalItemCount,
            [int]$panel.FirstRealizedIndex,[int]$panel.LastRealizedIndex,[bool]$hostConnected,
            [double]$panel.LogicalViewportHeight,[double]$panel.LogicalExtentHeight,[bool]$panel.RecyclingGeneratorAvailable
        ) INFO Software
    } catch {
        Write-AMRLog ('VIRTUALIZATION_RUNTIME audit failed: ' + $_.Exception.Message) WARNING Software
    }
}

Add-AMRStartupMark 'L22261 before-SoftwareVirtualizationAudit'
$script:SoftwareVirtualizationAuditHandler = {
    param($sender,$eventArgs)
    try {
        $auditGrid = $sender
        $auditAction = {
            Write-AMRSoftwareVirtualizationRuntimeAudit -Grid $auditGrid
        }.GetNewClosure()
        $null = $auditGrid.Dispatcher.BeginInvoke([Action]$auditAction, [System.Windows.Threading.DispatcherPriority]::ContextIdle)
    } catch {}
}
if ($script:SoftwareVirtualPanelReady) {
    try { $script:SoftwareCatalogGrid.Add_Loaded($script:SoftwareVirtualizationAuditHandler) } catch {}
    try { $script:InstalledSoftwareGrid.Add_Loaded($script:SoftwareVirtualizationAuditHandler) } catch {}
}

function Find-AMRNamedVisualChild {
    param([System.Windows.DependencyObject]$Parent,[string]$Name)
    if ($null -eq $Parent) { return $null }
    if ($Parent -is [System.Windows.FrameworkElement] -and $Parent.Name -eq $Name) { return $Parent }
    try {
        $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Parent)
        for ($i = 0; $i -lt $count; $i++) {
            $found = Find-AMRNamedVisualChild -Parent ([System.Windows.Media.VisualTreeHelper]::GetChild($Parent,$i)) -Name $Name
            if ($null -ne $found) { return $found }
        }
    } catch {}
    return $null
}

# Single walk that finds both named icon elements of a card (the image and the initials
# placeholder) instead of two separate recursive searches.
function Find-AMRSoftwareIconElements {
    param([System.Windows.DependencyObject]$Parent)
    $result = @{ Image = $null; Initials = $null }
    $stack = New-Object 'System.Collections.Generic.Stack[System.Windows.DependencyObject]'
    if ($null -ne $Parent) { $stack.Push($Parent) }
    try {
        while ($stack.Count -gt 0) {
            $node = $stack.Pop()
            if ($node -is [System.Windows.FrameworkElement]) {
                $nodeName = $node.Name
                if ($null -eq $result.Image -and $nodeName -eq 'SoftwareIconImage') { $result.Image = $node }
                elseif ($null -eq $result.Initials -and $nodeName -eq 'SoftwareIconInitials') { $result.Initials = $node }
                if ($null -ne $result.Image -and $null -ne $result.Initials) { break }
            }
            $childCount = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node)
            for ($childIndex = $childCount - 1; $childIndex -ge 0; $childIndex--) {
                $stack.Push([System.Windows.Media.VisualTreeHelper]::GetChild($node,$childIndex))
            }
        }
    } catch {}
    return $result
}

function Set-AMRSoftwareIconImageSource {
    param(
        [Parameter(Mandatory=$true)][System.Windows.Controls.Image]$Image,
        [object]$Source
    )
    try {
        $oldSource = $Image.Source
        if ([object]::ReferenceEquals($oldSource,$Source)) { return }
        $Image.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$null)
        # SetCurrentValue keeps the template binding, so a recycled card re-binds to its new item.
        $Image.SetCurrentValue([System.Windows.Controls.Image]::SourceProperty,$Source)
        if ($null -ne $Source) {
            $Image.Opacity = 0.0
            $fade = [System.Windows.Media.Animation.DoubleAnimation]::new()
            $fade.From = 0.0
            $fade.To = 1.0
            $fade.Duration = [TimeSpan]::FromMilliseconds(190)
            $fade.EasingFunction = [System.Windows.Media.Animation.QuadraticEase]::new()
            $fade.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $Image.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade,[System.Windows.Media.Animation.HandoffBehavior]::SnapshotAndReplace)
        } else {
            $Image.Opacity = 1.0
        }
    } catch {
        try { $Image.SetCurrentValue([System.Windows.Controls.Image]::SourceProperty,$Source); $Image.Opacity = 1.0 } catch {}
    }
}

function Sync-AMRRealizedSoftwareIcons {
    $perfStart = [long]0
    try { $perfStart = [AMR.PerfStats]::Now() } catch {}
    try {
        $grid = C 'SoftwareGrid'
        if ($null -eq $grid) { return }
        $generator = $grid.ItemContainerGenerator

        # Virtualized grid: visit only the cards that actually exist (about 30-60), never all
        # catalog items. The panel is looked up once per grid and cached.
        $panel = $null
        if ($null -ne $script:SoftwareIconSyncPanelGrid -and [object]::ReferenceEquals($script:SoftwareIconSyncPanelGrid,$grid)) { $panel = $script:SoftwareIconSyncPanel }
        if ($null -eq $panel) {
            try { $panel = Find-AMRVisualChildByType -Parent $grid -ChildType ([AMR.SoftwareVirtualizingUniformGridPanel]) } catch { $panel = $null }
            if ($null -ne $panel) { $script:SoftwareIconSyncPanel = $panel; $script:SoftwareIconSyncPanelGrid = $grid }
        }

        if ($null -ne $panel) {
            $indexes = $panel.GetRealizedItemIndexes()
        } else {
            $indexes = 0..($grid.Items.Count - 1)
        }
        foreach ($i in $indexes) {
            $container = $generator.ContainerFromIndex($i)
            if ($null -eq $container) { continue }
            $item = $grid.Items[$i]
            # Containers are recycled, so their template elements never change: walk each container's
            # visual tree once and reuse the result (the walk is what made every pass cost tens of ms).
            $iconElements = $script:SoftwareIconElementCache[$container]
            if ($null -eq $iconElements) {
                $iconElements = Find-AMRSoftwareIconElements -Parent $container
                if ($null -ne $iconElements.Image -and $null -ne $iconElements.Initials) {
                    if ($script:SoftwareIconElementCache.Count -gt 400) { $script:SoftwareIconElementCache.Clear() }
                    $script:SoftwareIconElementCache[$container] = $iconElements
                }
            }
            $image = $iconElements.Image
            $initials = $iconElements.Initials
            if ($null -ne $image) { Set-AMRSoftwareIconImageSource -Image $image -Source $item.Icon }
            if ($null -ne $initials) {
                $initials.SetCurrentValue([System.Windows.UIElement]::VisibilityProperty,$(if ($null -eq $item.Icon) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }))
            }
        }
        try { [AMR.PerfStats]::Count('icons.syncCardsVisited', @($indexes).Count) } catch {}
    } catch {} finally {
        if ($perfStart -ne 0) { try { [AMR.PerfStats]::Add('icons.syncAll', [AMR.PerfStats]::Now() - $perfStart) } catch {} }
    }
}

# Update only the realized card whose model changed; do not walk every card for
# each decoded icon. This keeps the dispatcher work proportional to one card.
function Queue-AMRSoftwareIconSync {
    if ($script:SoftwareIconSyncQueued) { return }
    $script:SoftwareIconSyncQueued = $true

    try {
        # One pass when the UI is idle. A7: if the user scrolled in the last 250 ms the pass waits 300 ms
        # (once) so it never lands in the middle of a scroll; it is still always executed.
        $null = $script:Window.Dispatcher.BeginInvoke([Action]{
            $waitMs = 0
            try {
                if ((([DateTime]::UtcNow.Ticks - $script:AMRLastSoftwareScrollTicks) / 10000) -lt 250) { $waitMs = 300 }
            } catch {}
            if ($waitMs -gt 0) {
                try {
                    $syncTimer = New-Object System.Windows.Threading.DispatcherTimer
                    $syncTimer.Interval = [TimeSpan]::FromMilliseconds($waitMs)
                    $syncTimer.Add_Tick({
                        $syncTimer.Stop()
                        try { Sync-AMRRealizedSoftwareIcons }
                        finally { $script:SoftwareIconSyncQueued = $false }
                    }.GetNewClosure())
                    $syncTimer.Start()
                } catch {
                    try { Sync-AMRRealizedSoftwareIcons } finally { $script:SoftwareIconSyncQueued = $false }
                }
            } else {
                try { Sync-AMRRealizedSoftwareIcons }
                finally { $script:SoftwareIconSyncQueued = $false }
            }
        }, [System.Windows.Threading.DispatcherPriority]::ApplicationIdle)
    } catch {
        $script:SoftwareIconSyncQueued = $false
    }
}
function Sync-AMRRealizedSoftwareIconItem {
    param([object]$Item)

    if ($null -eq $Item) { return }

    try {
        $grid = C 'SoftwareGrid'
        if ($null -eq $grid) { return }

        $generator = $grid.ItemContainerGenerator

        # Resolve the container directly instead of scanning every catalog item
        # for each delivered icon. Non-realized items are still handled by the
        # existing deferred full-sync path when their card becomes visible.
        $container = $generator.ContainerFromItem($Item)

        if ($null -eq $container) {
            # An icon may arrive for a catalog item that has not been added to
            # the current paged ItemsSource yet. Its model retains the decoded
            # icon, and the DataTemplate binding applies it when the card is added.
            # Under virtualization an unrealized card needs nothing here: the template binding
            # reads the item's current Icon at the moment the card is realized.
            return
        }

        $image = Find-AMRNamedVisualChild -Parent $container -Name 'SoftwareIconImage'
        $initials = Find-AMRNamedVisualChild -Parent $container -Name 'SoftwareIconInitials'

        if ($null -ne $image) {
            Set-AMRSoftwareIconImageSource -Image $image -Source $Item.Icon
        }

        if ($null -ne $initials) {
            $initials.SetCurrentValue([System.Windows.UIElement]::VisibilityProperty,$(if ($null -eq $Item.Icon) {
                [System.Windows.Visibility]::Visible
            } else {
                [System.Windows.Visibility]::Collapsed
            }))
        }
    } catch {}
}

try {
    $softwareScroll = C 'SoftwareScrollViewer'
    Start-AMRUiStallWatch
    $softwareScroll.Add_ScrollChanged({
        param($sender, $eventArgs)
        if ($eventArgs.VerticalChange -ne 0) { $script:AMRLastSoftwareScrollTicks = [DateTime]::UtcNow.Ticks }
        $perfScrollStart = [long]0
        try { $perfScrollStart = [AMR.PerfStats]::Now() } catch {}
        # Do not walk the whole ItemsControl on every scroll event. In this
        # non-virtualized UniformGrid that would repeatedly inspect every card.
        # Icons are synchronized after a page is created and when an individual
        # icon is delivered; scrolling only schedules the next small page.
        if ((-not $script:SoftwareGridPagingPaused -or $script:SoftwareGridPageMode -eq 'Installed') -and $eventArgs.VerticalChange -gt 0 -and $sender.VerticalOffset -gt 0 -and $sender.VerticalOffset -ge ($sender.ScrollableHeight - 420) -and -not $script:SoftwareGridPageDispatchPending) {
            # Queue at most one page append; avoid a burst of duplicate dispatcher work.
            $script:SoftwareGridPageDispatchPending = $true
            $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                $perfPageStart = [long]0
                try { $perfPageStart = [AMR.PerfStats]::Now() } catch {}
                try { Add-AMRSoftwareGridPage }
                finally {
                    $script:SoftwareGridPageDispatchPending = $false
                    if ($perfPageStart -ne 0) { try { [AMR.PerfStats]::Add('ps.addGridPage', [AMR.PerfStats]::Now() - $perfPageStart) } catch {} }
                }
            }, [System.Windows.Threading.DispatcherPriority]::Background)
        }
        if ($perfScrollStart -ne 0) { try { [AMR.PerfStats]::Add('ps.scrollChangedHandler', [AMR.PerfStats]::Now() - $perfScrollStart) } catch {} }
    })
} catch { Write-AMRLog ("Could not attach progressive Software paging: $($_.Exception.Message)") WARNING Software }

# Diagnostics only (file-only, no UI change). Timing is folded in memory by AMR.PerfStats and
# written to the diagnostics file by one 5 s Background timer, only when something was recorded.
try {
    $script:Window.AddHandler([System.Windows.UIElement]::PreviewMouseLeftButtonDownEvent, [System.Windows.Input.MouseButtonEventHandler]{
        try { $script:PerfLastClickTicks = [AMR.PerfStats]::Now() } catch {}
    }, $true)
    $script:Window.AddHandler([System.Windows.Controls.Primitives.Selector]::SelectionChangedEvent, [System.Windows.Controls.SelectionChangedEventHandler]{
        param($sender, $e)
        try {
            $source = $e.OriginalSource
            if ($source -isnot [System.Windows.Controls.TabControl]) { return }
            $nowTicks = [AMR.PerfStats]::Now()
            $name = [string]$source.Name
            $header = ''
            try { $header = Get-AMRPerfTabHeader $source.SelectedItem } catch {}
            $key = 'tab:' + $name + '->' + $header
            $clickTicks = [long]$script:PerfLastClickTicks
            if ($clickTicks -gt 0 -and ($nowTicks - $clickTicks) -lt ([System.Diagnostics.Stopwatch]::Frequency * 2)) {
                [AMR.PerfStats]::Add($key + '.clickToHandlersDone', $nowTicks - $clickTicks)
                $startTicks = $clickTicks
            } else { $startTicks = $nowTicks }
            # Dispatcher callbacks do not see this handler's locals (StrictMode would throw), so pass state via a script-scope queue.
            $script:PerfIdleQueue.Enqueue(@($key, [long]$startTicks))
            $script:PerfLoadedQueue.Enqueue(@($key, [long]$startTicks))
            $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                try {
                    if ($script:PerfLoadedQueue.Count -gt 0) {
                        $pendingLoaded = $script:PerfLoadedQueue.Dequeue()
                        [AMR.PerfStats]::Add([string]$pendingLoaded[0] + '.toLoaded', [AMR.PerfStats]::Now() - [long]$pendingLoaded[1])
                    }
                } catch {}
            }, [System.Windows.Threading.DispatcherPriority]::Loaded)
            $null = $script:Window.Dispatcher.BeginInvoke([Action]{
                try {
                    if ($script:PerfIdleQueue.Count -gt 0) {
                        $pendingIdle = $script:PerfIdleQueue.Dequeue()
                        [AMR.PerfStats]::Add([string]$pendingIdle[0] + '.toIdle', [AMR.PerfStats]::Now() - [long]$pendingIdle[1])
                    }
                } catch {}
            }, [System.Windows.Threading.DispatcherPriority]::ApplicationIdle)
        } catch {}
    }, $true)
    # Initialized up front: StrictMode throws on reading an unset script variable.
    $script:PerfLastGc0 = 0; $script:PerfLastGc1 = 0; $script:PerfLastGc2 = 0; $script:PerfLastCpuMs = [long]0; $script:PerfExtraErrLogged = $false
    $script:PerfFlushTimer = New-Object System.Windows.Threading.DispatcherTimer([System.Windows.Threading.DispatcherPriority]::Background)
    $script:PerfFlushTimer.Interval = [TimeSpan]::FromSeconds(5)
    $script:PerfFlushTimer.Add_Tick({
        try {
            $line = [AMR.PerfStats]::Take()
            if ($null -ne $line) {
                # A21/A22 (measurement only): GC collections, process CPU time and working set during this window.
                try {
                    $perfProc = [System.Diagnostics.Process]::GetCurrentProcess()
                    $perfCpuNow = [long]$perfProc.TotalProcessorTime.TotalMilliseconds
                    $perfG0 = [int][GC]::CollectionCount(0); $perfG1 = [int][GC]::CollectionCount(1); $perfG2 = [int][GC]::CollectionCount(2)
                    $perfWsMb = [int]([long]$perfProc.WorkingSet64 / 1048576)
                    $perfD0 = $perfG0 - [int]$script:PerfLastGc0; $perfD1 = $perfG1 - [int]$script:PerfLastGc1; $perfD2 = $perfG2 - [int]$script:PerfLastGc2
                    $perfDc = $perfCpuNow - [long]$script:PerfLastCpuMs
                    $line = $line + ' ; gc.gen0=' + $perfD0 + ' ; gc.gen1=' + $perfD1 + ' ; gc.gen2=' + $perfD2 + ' ; proc.cpuMs=' + $perfDc + ' ; proc.workingSetMB=' + $perfWsMb
                    $script:PerfLastGc0 = $perfG0; $script:PerfLastGc1 = $perfG1; $script:PerfLastGc2 = $perfG2; $script:PerfLastCpuMs = $perfCpuNow
                } catch { try { $line = $line + ' ; perf.extraError=1'; if (-not $script:PerfExtraErrLogged) { $script:PerfExtraErrLogged = $true; Write-AMRLog ('PerfStats extra counters failed: ' + $_.Exception.Message) WARNING System } } catch {} }
                Write-AMRDiagnostic -Severity 'INFO' -Area 'PerfStats' -Operation 'Window5s' -Message $line }
        } catch {}
    })
    $script:PerfFlushTimer.Start()
    try { Write-AMRDiagnostic -Severity 'INFO' -Area 'PerfStats' -Operation 'BuildLabel' -Message 'Build variant: A1 (numbering restarted; built on the previous series A25. A1: the A23 BelowNormal priority guard removed from every worker; Cleanup app detection (uninstall registry + AppX lookups) prefetched in a worker; Installed cache read/parse prefetched in a worker and saved in a worker; light Installed change check every 10 min and on window activation (AppX versions ignored in the change signature, age safety net 100 h); first Overview refresh runs right after the first render; native PDH GPU sampling with Get-Counter fallback; startup markers ProcessStartToScriptMs, cleanup.*, CatalogLoopMs, CatalogIconDecodeMs; previous A25 = A25 (Installed icon engine duration logged; installed.cacheImport.* markers; built on A24 = A24 (Windows Update history query moved off the UI thread (was 1.1 s at startup); GPU inventory query moved off the pre-window startup path; GPU sensor sample selection uses loops instead of pipelines (same result); built on A23 = A23 (single data folder ProgramData\AMR-Utility incl. Windows Update backups; Installed-app catalog persisted and refreshed only when an install/removal is detected, the saved catalog is older than 12 h, or it is missing; BelowNormal priority for background workers; startup markers startup.loaded.*, installed.changeCheck; built on A22 = A22 (fixes an A21 regression: shared brush helper broke the Show Installed button; Overview apply path lighter on the UI thread with the same 750 ms live cadence (cached controls and brushes, loops instead of pipelines, gauge geometry only when changed); Backup cards get their items at startup; glass dialog styles warmed at idle; new log-only markers (kit.sel.*, smart.contentFilterWalk, ov.apply.history, dialog.build.*, recycle.*, gc.*, proc.*); built on A20 = A20 (Cleanup tab: scan, clean, Inspect, Large Files, Recycle Bin and Tool Kit temp clear run in isolated workers so the window never freezes; Cleanup result and message dialogs use the same glass style as Software/System; built on A19 = A19 (Control Center warm-up log Area fixed (ToolKit was not an allowed Area, so the warm-up lines never logged); log-only Backup measurement markers (cc.prewarm.*, backup.updateCards.*, backup.cards.*), no behavior change; built on A18 = A18 (Startup Apps: persistent cache with change detection, lighter shadows, Refresh hover; built on A17; Startup Apps: match index, icon file map, brush cache, hydration retry; built on A16; Control Center: Backup column rule unified with the other pages, card warm-up at idle; built on A15; Control Center page title and counter raised beside the search panel, cards raised; built on A14; main tab strip keeps the original layout and is anchored after first layout so the growing search panel does not move it; results count moved up beside the page title; built on A12 <- A11 <- A10 <- A9 <- A8 <- A7 <- A6; Control Center entry in the Tool Kit sidebar that drops down Optimize, Security, System, Networks, Utilities and Backup, four cards per row, Backup cards restyled like Toolkit cards; Toolkit tabs native cards; Driver Backup redesign, glass buttons; driver download cancel, Rollback Check cancel fixes, glass MessageBoxes; Candidate Manager glass redesign, Source Manager hover/scrollbar/button animation) | previous A11 (Control Center tab inside Tool Kit with Logs-style top tabs) | previous A3 (built on A2; reasons for disabled driver buttons) | previous A2 (built on A1 and A13h; problem card open-in-Driver-Update button, softer Driver Downloads and Diagnose hover) | previous A1 (built on A13h; Driver Center layout: scan summary and diagnosis note in driver log, equal tab panes, Driver Downloads/Diagnose buttons) | previous A13e (A13d + Scan PartialShown fix after restore point, glass tabs with sliding pill, cheaper tab switch, app-palette problem cards, Scan blocked diagnostics and stale restore state repair)' } catch {}
} catch { }

$script:UpdateSoftwareGridColumns = {
    $uniformGrid = Find-AMRVisualChildByType -Parent (C 'SoftwareGrid') -ChildType ([System.Windows.Controls.Primitives.UniformGrid])
    if ($null -ne $uniformGrid) {
        $newColumnCount = 4 # Fixed four-column layout prevents maximize/restore from reflowing the catalog.
        if ($uniformGrid.Columns -ne $newColumnCount) {
            $uniformGrid.Columns = $newColumnCount
            if ($script:AppsView) {
                $savedOffset = 0.0
                try { $savedOffset = (C 'SoftwareScrollViewer').VerticalOffset } catch {}
                Reset-AMRSoftwareGridPages -View $script:AppsView
                try {
                    $null = $script:Window.Dispatcher.BeginInvoke([Action]{ (C 'SoftwareScrollViewer').ScrollToVerticalOffset($savedOffset) }, [System.Windows.Threading.DispatcherPriority]::Loaded)
                } catch {}
            }
        }
    }
}
$script:SoftwareResizeUpdatePending = $false
try { Enable-AMRGridTouchScroll -Window $script:Window -Grid (C 'DriverDeviceList') -HorizontalOnly } catch { try { Write-AMRDriverDiagnostic -Severity WARNING -Operation TouchScroll -Stage HookFallback -Message ('Horizontal touchpad scroll not enabled: ' + $_.Exception.Message) -Source 'AMRTouchScroll' } catch {} }
$script:Window.Add_Loaded({ & $script:UpdateSoftwareGridColumns })
$script:Window.Add_Loaded({
    try {
        $script:AMRCCPrewarmTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:AMRCCPrewarmTimer.Interval = [TimeSpan]::FromSeconds(5)
        $script:AMRCCPrewarmTimer.Add_Tick({
            try { $script:AMRCCPrewarmTimer.Stop() } catch {}
            Start-AMRControlCenterPrewarm
        })
        $script:AMRCCPrewarmTimer.Start()
    } catch {
        try { Write-AMRLog ('Control Center warm-up not scheduled: ' + $_.Exception.Message) WARNING System } catch {}
    }
})
# Main tab strip anchor: the strip is laid out exactly as before (centered in the top row). Once, after the first layout, its measured
# position is frozen with Top alignment + the same offset, so a growing search panel (category selector appearing) cannot move the tabs.
# Any failure leaves the original centered layout untouched.
$script:Window.Add_Loaded({
    try {
        $mainTabs = C 'MainNavigationTabs'
        if (-not $mainTabs) { return }
        $strip = $mainTabs.Template.FindName('PART_MainTabStrip', $mainTabs)
        $panel = $mainTabs.Template.FindName('PART_SmartSearchPanel', $mainTabs)
        if (-not $strip -or -not $panel) { return }
        if ($strip.ActualHeight -lt 10 -or $panel.ActualHeight -lt 10) { return }
        $stripSlot = $strip.ActualHeight + $strip.Margin.Top + $strip.Margin.Bottom
        $panelSlot = $panel.ActualHeight + $panel.Margin.Top + $panel.Margin.Bottom
        $combo = $script:SmartCategoryFilter
        if ($combo -and $combo.Visibility -eq [System.Windows.Visibility]::Visible) {
            # Measure the normal (selector hidden) state regardless of when this runs.
            $panelSlot -= ($combo.ActualHeight + $combo.Margin.Top + $combo.Margin.Bottom)
        }
        $rowHeight = [Math]::Max($stripSlot, $panelSlot)
        $offset = [Math]::Max(0.0, ($rowHeight - $stripSlot) / 2.0)
        $strip.Margin = New-Object System.Windows.Thickness($strip.Margin.Left, ($strip.Margin.Top + $offset), $strip.Margin.Right, $strip.Margin.Bottom)
        $strip.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
        # Control Center pages: raise the page title/counter into the free strip between the tabs and the (taller) search panel.
        # free = distance between the bottom of the tabs and the top of the page area once the category selector is shown.
        try {
            $comboExtra = 35.0
            if ($combo -and $combo.Height -gt 0) { $comboExtra = [double]$combo.Height + [double]$combo.Margin.Top }
            $rowBig = [Math]::Max($stripSlot, $panelSlot + $comboExtra)
            $free = $rowBig - $strip.ActualHeight
            $lift = [Math]::Max(0.0, [Math]::Min(52.0, 6.0 + $free))
            foreach ($pg in @('Optimize','Backup','Utilities','Security','System','Networks')) {
                $hdr = C ('CCHeader' + $pg); $scr = C $(if ($pg -eq 'Backup') { 'BackupCenterScrollViewer' } else { 'CCScroll' + $pg })
                if ($hdr -and $scr) {
                    $hdr.Margin = New-Object System.Windows.Thickness(20, (14.0 - $lift), 20, 0)
                    $scr.Margin = New-Object System.Windows.Thickness(0, (52.0 - $lift), 0, 0)
                }
            }
        } catch {
            try { Write-AMRLog ('Control Center header lift skipped: ' + $_.Exception.Message) WARNING UI } catch {}
        }
    } catch {
        try { Write-AMRLog ('Main tab strip anchor skipped: ' + $_.Exception.Message) WARNING UI } catch {}
    }
})
$script:Window.Add_StateChanged({
    # Let WPF finish the maximize/restore frame before changing the grid. Coalesce
    # repeated state notifications so only one responsive reflow is queued.
    if ($script:SoftwareResizeUpdatePending) { return }
    $script:SoftwareResizeUpdatePending = $true
    try {
        $null = $script:Window.Dispatcher.BeginInvoke([Action]{
            try { & $script:UpdateSoftwareGridColumns }
            finally { $script:SoftwareResizeUpdatePending = $false }
        }, [System.Windows.Threading.DispatcherPriority]::ContextIdle)
    } catch {
        $script:SoftwareResizeUpdatePending = $false
        & $script:UpdateSoftwareGridColumns
    }
})

(C 'DeselectAllBtn').Add_Click({
    if ($script:InstallRunning) {
        Write-AMRLog "Cannot clear selection while an installation queue is running." WARNING Software
        return
    }

    if ($script:ShowInstalledOnly) {
        foreach ($app in $script:InstalledAppsInventory) {
            if ($null -ne $app -and $app.PSObject.Properties['IsSelected']) { $app.IsSelected = $false }
        }
        if ($script:InstalledAppsView) {
            $script:InstalledAppsView.Refresh()
            Reset-AMRSoftwareGridPages -View $script:InstalledAppsView
        }
    } else {
        foreach ($app in $script:SoftwareCatalog) {
            if ($null -ne $app -and $app.PSObject.Properties['IsSelected']) { $app.IsSelected = $false }
        }
        if ($script:AppsView) {
            $script:AppsView.Refresh()
            Reset-AMRSoftwareGridPages -View $script:AppsView
        }
    }

    Write-AMRLog "Software selection cleared in the active view." INFO Software
})

# Shared engine state
Add-AMRStartupMark 'L22513 before-InstallEngineState'
$script:InstallRunning = $false
$script:InstallPowerShell = $null
$script:InstallRunspace = $null
$script:InstallAsyncResult = $null
$script:InstallOutput = $null
$script:InstallResultQueue = $null
$script:InstallCompletionFile = $null
$script:InstallLogQueue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[string]'
$script:InstallTimer = $null
$script:InstallActionName = ''
$script:InstallSelectedSnapshot = @()

# Worker code runs in dedicated Runspace & reports progress
$script:InstallWorkerCode = @'
param(
    [object[]]$Apps,
    [string]$ActionCommand,
    [string]$ActionName,
    [bool]$Interactive,
    [string]$DownloadDir,
    [System.Collections.Concurrent.ConcurrentQueue[string]]$LogQueue,
    [string]$CompletionFilePath
)

$ErrorActionPreference = "Stop"
$script:ChocoCheckedPath = $null

function Write-WorkerLog {
    param([string]$Message, [string]$Level = "INFO", [int]$Percent = -1)
    $stamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss.fff"
    $pctPrefix = if ($Percent -ge 0) { "PROG:$Percent|" } else { "" }
    [void]$LogQueue.Enqueue("${pctPrefix}[$stamp] [$Level] [Software] $Message")
}

# Last-resort worker trap: preserve the original terminating error and publish a
# diagnostic completion record instead of losing the runspace failure silently.
trap {
    $fatalRecord = $_
    $fatalMessage = [string]$fatalRecord.Exception.Message
    $fatalType = [string]$fatalRecord.Exception.GetType().FullName
    $fatalStack = [string]$fatalRecord.ScriptStackTrace
    if ([string]::IsNullOrWhiteSpace($fatalMessage)) { $fatalMessage = [string]$fatalRecord }
    try { Write-WorkerLog ("WORKER-FATAL | Type={0} | Error={1} | Stack={2}" -f $fatalType,$fatalMessage,$fatalStack) 'ERROR' } catch {}
    try {
        $fatalResults = @()
        if (Get-Variable -Name results -Scope 0 -ErrorAction SilentlyContinue) { $fatalResults = $results.ToArray() }
        $fatalSummary = [pscustomobject]@{
            ActionName = [string]$ActionName
            SuccessCount = if (Get-Variable successCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$successCount } else { 0 }
            UnverifiedCount = if (Get-Variable unverifiedCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$unverifiedCount } else { 0 }
            CancelledCount = if (Get-Variable cancelledCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$cancelledCount } else { 0 }
            FailedCount = if (Get-Variable failedCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$failedCount } else { 1 }
            SkippedCount = if (Get-Variable skippedCount -Scope 0 -ErrorAction SilentlyContinue) { [int]$skippedCount } else { 0 }
            RebootNeeded = $false
            Results = $fatalResults
            WorkerError = $fatalMessage
            WorkerErrorType = $fatalType
            WorkerStackTrace = $fatalStack
        }
        $fatalJson = ConvertTo-Json -InputObject $fatalSummary -Depth 8 -Compress
        if (-not [string]::IsNullOrWhiteSpace($CompletionFilePath)) {
            $fatalTemp = $CompletionFilePath + '.fatal.' + [guid]::NewGuid().ToString('N')
            $fatalEncoding = New-Object System.Text.UTF8Encoding($false)
            [System.IO.File]::WriteAllText($fatalTemp, [string]$fatalJson, $fatalEncoding)
            if ([System.IO.File]::Exists($CompletionFilePath)) { [System.IO.File]::Delete($CompletionFilePath) }
            [System.IO.File]::Move($fatalTemp, $CompletionFilePath)
        }
    } catch {
        try { Write-WorkerLog ("WORKER-FATAL-PUBLISH-ERROR | {0}" -f $_.Exception.Message) 'ERROR' } catch {}
    }
    break
}

function Normalize-WorkerIdentity {
    param([string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    return (($Value -replace '[^a-zA-Z0-9]', '').ToLowerInvariant())
}

function Invoke-WorkerCapture {
    param([string]$FilePath,[string[]]$ArgumentList,[ValidateRange(1,7200)][int]$TimeoutSeconds=15)
    $token=[guid]::NewGuid().ToString('N')
    $stdoutPath=Join-Path ([IO.Path]::GetTempPath()) ("AMR_SW_{0}.out" -f $token)
    $stderrPath=Join-Path ([IO.Path]::GetTempPath()) ("AMR_SW_{0}.err" -f $token)
    $process=$null; $startedAt=Get-Date
    try {
        $quotedArguments = foreach ($argument in $ArgumentList) {
            $argument = [string]$argument
            if ($argument.Length -eq 0 -or $argument -match '[\s"]') {
                $escaped = [regex]::Replace($argument, '(\\*)"', '$1$1\"')
                $escaped = [regex]::Replace($escaped, '(\\+)$', '$1$1')
                '"' + $escaped + '"'
            } else { $argument }
        }
        $argumentLine = ($quotedArguments -join ' ')
        $params=@{FilePath=$FilePath;ArgumentList=$argumentLine;PassThru=$true;RedirectStandardOutput=$stdoutPath;RedirectStandardError=$stderrPath;WindowStyle='Hidden';ErrorAction='Stop'}
        $process=Start-Process @params
        if (-not $process.WaitForExit($TimeoutSeconds*1000)) {
            Write-WorkerLog ("[Capture] {0} PID={1} timed out after {2}s." -f $FilePath,$process.Id,$TimeoutSeconds) 'WARNING'
            try { $null = & "$env:SystemRoot\System32\taskkill.exe" /PID $process.Id /T /F 2>&1; $null=$process.WaitForExit(5000) } catch { try {$process.Kill();[void]$process.WaitForExit(3000)}catch{} }
            return [pscustomobject]@{ExitCode=-2;TimedOut=$true;Output='';Error='Process timed out.';ProcessId=$process.Id;ElapsedSeconds=[math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)}
        }
        $process.WaitForExit(); $process.Refresh()
        $out=if(Test-Path -LiteralPath $stdoutPath){Get-Content -LiteralPath $stdoutPath -Raw -ErrorAction SilentlyContinue}else{''}
        $err=if(Test-Path -LiteralPath $stderrPath){Get-Content -LiteralPath $stderrPath -Raw -ErrorAction SilentlyContinue}else{''}
        return [pscustomobject]@{ExitCode=[int]$process.ExitCode;TimedOut=$false;Output=[string]$out;Error=[string]$err;ProcessId=$process.Id;ElapsedSeconds=[math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)}
    } catch {return [pscustomobject]@{ExitCode=-1;TimedOut=$false;Output='';Error=$_.Exception.Message;ProcessId=-1;ElapsedSeconds=[math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)}}
    finally {if($process){try{$process.Dispose()}catch{}};foreach($f in @($stdoutPath,$stderrPath)){if(Test-Path -LiteralPath $f){Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue}}}
}

function Test-WorkerInstalled {
    param(
        [string]$AppName,
        [string]$AppId = '',
        [string]$ChocoId = '',
        [switch]$SkipWinget
    )

    if ([string]::IsNullOrWhiteSpace($AppName) -and [string]::IsNullOrWhiteSpace($AppId)) { return $false }
    $cleanTarget = Normalize-WorkerIdentity $AppName
    $cleanId = Normalize-WorkerIdentity $AppId
    $cleanChoco = Normalize-WorkerIdentity $ChocoId

    # Keep worker-side identity matching consistent with the Show Installed catalog
    # filter. Registry display names frequently differ from catalog labels (for
    # example, catalog "Everything Search" vs. uninstall entry "Everything 1.4.x").
    $identityCandidates = New-Object 'System.Collections.Generic.List[string]'
    foreach ($identity in @($cleanTarget, $cleanId, $cleanChoco)) {
        if (-not [string]::IsNullOrWhiteSpace($identity) -and -not $identityCandidates.Contains($identity)) {
            $identityCandidates.Add($identity)
        }
    }
    $workerIdentityAliases = @{
        'everythingsearch' = @('everything')
        'visualstudiocode' = @('vscode')
        'microsoftedgewebview2runtime' = @('webview2runtime','microsoftedgewebview2')
        'vlcmediaplayer' = @('vlc')
        'sumatrapdf' = @('sumatrapdf')
        'sharex' = @('sharex')
    }
    foreach ($baseIdentity in @($identityCandidates.ToArray())) {
        if ($workerIdentityAliases.ContainsKey($baseIdentity)) {
            foreach ($alias in $workerIdentityAliases[$baseIdentity]) {
                $normalizedAlias = Normalize-WorkerIdentity ([string]$alias)
                if ($normalizedAlias -and -not $identityCandidates.Contains($normalizedAlias)) {
                    $identityCandidates.Add($normalizedAlias)
                }
            }
        }
    }

    # 1. Exact Winget inventory check with a bounded wait.
    if (-not $SkipWinget -and -not [string]::IsNullOrWhiteSpace($AppId)) {
        $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
        if ($winget) {
            $check = Invoke-WorkerCapture -FilePath $winget.Source -ArgumentList @('list','--id',$AppId,'--exact','--accept-source-agreements') -TimeoutSeconds 12
            if (-not $check.TimedOut -and $check.ExitCode -eq 0 -and $check.Output -match [regex]::Escape($AppId)) { return $true }
        }
    }

    # 2. AppX/MSIX packages. Compare exact package identity fields only.
    if (-not [string]::IsNullOrWhiteSpace($AppId)) {
        try {
            $appx = @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object {
                $_.Name -ieq $AppId -or $_.PackageFamilyName -ieq $AppId
            })
            if ($appx.Count -gt 0) { return $true }
        } catch {}
    }

    # 3. Both registry views and both user/machine uninstall hives.
    $paths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($path in $paths) {
        try {
            foreach ($item in @(Get-ItemProperty -Path $path -ErrorAction SilentlyContinue)) {
                $displayNameProperty = $item.PSObject.Properties['DisplayName']
                $childNameProperty = $item.PSObject.Properties['PSChildName']
                $displayName = if ($displayNameProperty) { [string]$displayNameProperty.Value } else { '' }
                $childName = if ($childNameProperty) { [string]$childNameProperty.Value } else { '' }
                $candidate = Normalize-WorkerIdentity $displayName
                $candidateChild = Normalize-WorkerIdentity $childName
                foreach ($expectedIdentity in $identityCandidates) {
                    if ([string]::IsNullOrWhiteSpace($expectedIdentity)) { continue }
                    foreach ($observedIdentity in @($candidate, $candidateChild)) {
                        if ([string]::IsNullOrWhiteSpace($observedIdentity)) { continue }
                        if ($observedIdentity -eq $expectedIdentity) { return $true }
                        # Accept version/architecture suffixes only after a complete
                        # known identity, never arbitrary partial-name matches.
                        if ($observedIdentity.Length -gt $expectedIdentity.Length -and
                            $observedIdentity.StartsWith($expectedIdentity, [StringComparison]::OrdinalIgnoreCase)) {
                            $suffix = $observedIdentity.Substring($expectedIdentity.Length)
                            if ($suffix -match '^\d+(x64|x86|64bit|32bit)?$') { return $true }
                        }
                    }
                }
            }
        } catch {}
    }
    return $false
}

function Wait-WorkerInstalled {
    param([string]$AppName,[string]$AppId='',[string]$ChocoId='',[int]$TimeoutSeconds=45,[int]$PollSeconds=3)
    if (Test-WorkerInstalled -AppName $AppName -AppId $AppId -ChocoId $ChocoId) { return $true }
    $deadline=(Get-Date).AddSeconds([Math]::Max(1,$TimeoutSeconds))
    do {
        if (Test-WorkerInstalled -AppName $AppName -AppId $AppId -ChocoId $ChocoId -SkipWinget) { return $true }
        Start-Sleep -Seconds ([Math]::Max(1,$PollSeconds))
    } while ((Get-Date) -lt $deadline)
    return (Test-WorkerInstalled -AppName $AppName -AppId $AppId -ChocoId $ChocoId -SkipWinget)
}

function Resolve-WorkerWingetId {
    param([string]$AppName, [string]$ConfiguredId)

    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $winget) { return $ConfiguredId }

    # First trust the catalog ID when Winget can see that exact installed package.
    if (-not [string]::IsNullOrWhiteSpace($ConfiguredId)) {
        try {
            $byId = Invoke-WorkerCapture -FilePath $winget.Source -ArgumentList @('list','--id',$ConfiguredId,'--exact','--accept-source-agreements') -TimeoutSeconds 20
            if (-not $byId.TimedOut -and $byId.ExitCode -eq 0 -and $byId.Output -match [regex]::Escape($ConfiguredId)) { return $ConfiguredId }
        } catch {}
    }

    # Catalog IDs can change or differ from the ID used by an already-installed package.
    # Resolve the exact display name to the installed Winget ID before upgrade/repair.
    if ([string]::IsNullOrWhiteSpace($AppName)) { return $ConfiguredId }
    try {
        $listedResult = Invoke-WorkerCapture -FilePath $winget.Source -ArgumentList @('list','--name',$AppName,'--exact','--accept-source-agreements') -TimeoutSeconds 20
        if (-not $listedResult.TimedOut -and $listedResult.ExitCode -eq 0) {
            foreach ($line in @($listedResult.Output -split "`r?`n")) {
                $text = ([string]$line).Trim()
                # Winget table columns can be separated by only one space when a name fills its column.
                # Since --name --exact was used, parse the ID immediately after the exact display name.
                if ($text.StartsWith($AppName.Trim(), [StringComparison]::OrdinalIgnoreCase)) {
                    $tail = $text.Substring($AppName.Trim().Length).TrimStart()
                    $columns = @($tail -split '\s+')
                    if ($columns.Count -ge 2 -and $columns[0] -and $columns[0] -notin @('Id','Version')) {
                        Write-WorkerLog "Resolved installed Winget ID for ${AppName}: $($columns[0])" "INFO"
                        return [string]$columns[0]
                    }
                }
            }
        }
    } catch {}
    return $ConfiguredId
}

function Invoke-WorkerMsiRepair {
    param([string]$AppName, [bool]$Interactive, [int]$BasePercent, [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800)

    $paths = @(
        "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )
    $entry = $null
    try {
        $entry = Get-ItemProperty -Path $paths -ErrorAction SilentlyContinue |
            Where-Object {
                $nameProperty = $_.PSObject.Properties['DisplayName']
                $installerProperty = $_.PSObject.Properties['WindowsInstaller']
                $nameValue = if ($nameProperty) { [string]$nameProperty.Value } else { '' }
                $installerValue = if ($installerProperty) { $installerProperty.Value } else { 0 }
                (-not [string]::IsNullOrWhiteSpace($nameValue)) -and
                ($nameValue.Trim() -ieq $AppName.Trim()) -and
                ([int]$installerValue -eq 1)
            } |
            Select-Object -First 1
    } catch {}

    if (-not $entry) { return $null }
    $productCode = $null
    $candidate = [string]$entry.UninstallString
    if ($candidate -match '(?i)\{[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\}') {
        $productCode = $Matches[0]
    } elseif ([string]$entry.PSChildName -match '^\{[0-9a-fA-F-]{36}\}$') {
        $productCode = [string]$entry.PSChildName
    }
    if (-not $productCode) { return $null }

    $args = @('/fa', $productCode)
    if (-not $Interactive) { $args += @('/qn', '/norestart') }
    Write-WorkerLog "[MSI Repair] Running native Windows Installer repair for $AppName ($productCode)." "INFO" -Percent ($BasePercent + 10)
    try {
        $proc = Invoke-ProcessResult -FilePath 'msiexec.exe' -ArgumentList $args -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
        $ok = Test-ExitSuccess -ExitCode $proc.ExitCode
        return [pscustomobject]@{ Success=$ok; ExitCode=$proc.ExitCode; Started=$true; Reboot=($proc.ExitCode -in @(1641,3010)) }
    } catch {
        Write-WorkerLog "[MSI Repair] $AppName failed: $_" "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success=$false; ExitCode=-1; Started=$true; Reboot=$false }
    }
}

function Get-ChocoPath {
    if ($script:ChocoCheckedPath -and (Test-Path -LiteralPath $script:ChocoCheckedPath)) {
        return $script:ChocoCheckedPath
    }

    $command = Get-Command choco.exe -ErrorAction SilentlyContinue
    if ($command) {
        $script:ChocoCheckedPath = $command.Source
        return $script:ChocoCheckedPath
    }

    $defaultPath = Join-Path $env:ProgramData "chocolatey\bin\choco.exe"
    if (Test-Path -LiteralPath $defaultPath) {
        $script:ChocoCheckedPath = $defaultPath
        return $script:ChocoCheckedPath
    }
    return $null
}

function Ensure-Chocolatey {
    $existing = Get-ChocoPath
    if ($existing) { return $existing }

    Write-WorkerLog "Chocolatey is missing; attempting one-time initialization." "WARNING"
    $setupFile = Join-Path $DownloadDir ("choco_setup_{0}.ps1" -f [guid]::NewGuid().ToString("N"))

    try {
        [Net.ServicePointManager]::SecurityProtocol =
            [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

        Invoke-WebRequest -Uri "https://community.chocolatey.org/install.ps1" `
            -OutFile $setupFile -UseBasicParsing -ErrorAction Stop

        if (!(Test-Path -LiteralPath $setupFile) -or (Get-Item -LiteralPath $setupFile).Length -lt 1000) {
            throw "Chocolatey bootstrap script is missing or incomplete."
        }

        Write-WorkerLog '[Chocolatey] Running official bootstrap with a 15-minute execution limit.' 'INFO'
        $process = Invoke-ProcessResult -FilePath 'powershell.exe' `
            -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$setupFile`"") `
            -ShowWindow:$false -TimeoutSeconds 900

        $machinePath = [Environment]::GetEnvironmentVariable('Path', 'Machine')
        $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        $env:Path = "$machinePath;$userPath"

        $found = Get-ChocoPath
        if (-not $process.TimedOut -and $process.ExitCode -eq 0 -and $found) {
            Write-WorkerLog "Chocolatey initialized successfully." "SUCCESS"
            return $found
        }

        $failureReason = if ($process.TimedOut) { 'timed out after 900 seconds' } else { "exit code $($process.ExitCode)" }
        throw "Chocolatey setup failed ($failureReason); choco.exe was not verified."
    }
    catch {
        Write-WorkerLog "Chocolatey initialization error: $_" "ERROR"
        return $null
    }
    finally {
        if (Test-Path -LiteralPath $setupFile) {
            Remove-Item -LiteralPath $setupFile -Force -ErrorAction SilentlyContinue
        }
    }
}

function Invoke-ProcessResult {
    param(
        [string]$FilePath,
        [string[]]$ArgumentList,
        [bool]$ShowWindow,
        [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800
    )

    $process = $null
    $startedAt = Get-Date
    try {
        $startParams = @{
            FilePath = $FilePath
            ArgumentList = $ArgumentList
            PassThru = $true
            ErrorAction = 'Stop'
        }
        if (-not $ShowWindow) { $startParams['WindowStyle'] = 'Hidden' }
        $process = Start-Process @startParams
        Write-WorkerLog ("[Process] Started PID={0}; File={1}; Timeout={2}s." -f $process.Id,$FilePath,$TimeoutSeconds) 'INFO'
        $exited = $process.WaitForExit($TimeoutSeconds * 1000)
        if (-not $exited) {
            Write-WorkerLog ("[Process] PID={0} exceeded {1}s; attempting process-tree termination." -f $process.Id,$TimeoutSeconds) 'ERROR'
            try {
                $null = & "$env:SystemRoot\System32\taskkill.exe" /PID $process.Id /T /F 2>&1
                $null = $process.WaitForExit(10000)
                if (-not $process.HasExited) { $process.Kill(); [void]$process.WaitForExit(5000) }
            } catch {
                try { if (-not $process.HasExited) { $process.Kill(); [void]$process.WaitForExit(5000) } } catch {}
            }
            return [pscustomobject]@{
                ExitCode = -2; TimedOut = $true; ProcessId = $process.Id
                FilePath = $FilePath; ElapsedSeconds = [math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)
            }
        }
        $process.Refresh()
        return [pscustomobject]@{
            ExitCode = [int]$process.ExitCode; TimedOut = $false; ProcessId = $process.Id
            FilePath = $FilePath; ElapsedSeconds = [math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)
        }
    } catch {
        Write-WorkerLog ("[Process] Could not execute '{0}': {1}" -f $FilePath,$_.Exception.Message) 'ERROR'
        return [pscustomobject]@{
            ExitCode = -1; TimedOut = $false; ProcessId = $(if ($process) {$process.Id} else {-1})
            FilePath = $FilePath; ElapsedSeconds = [math]::Round(((Get-Date)-$startedAt).TotalSeconds,1)
        }
    } finally {
        if ($process) { try { $process.Dispose() } catch {} }
    }
}

function Test-ExitSuccess {
    param([int]$ExitCode)
    return ($ExitCode -in @(0, 1641, 3010))
}

function Invoke-WingetUnelevated {
    param(
        [string]$WingetPath,
        [string[]]$Arguments,
        [bool]$ShowWindow = $false,
        [int]$TimeoutSeconds = 1800
    )

    $tempRoot = [IO.Path]::GetTempPath()
    $jobId = [guid]::NewGuid().ToString('N')
    $helperPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.ps1" -f $jobId)
    $payloadPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.json" -f $jobId)
    $resultPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.exit" -f $jobId)
    $pidPath = Join-Path $tempRoot ("AMR_Winget_UserContext_{0}.pid" -f $jobId)
    $helperCode = @"
param([Parameter(Mandatory=`$true)][string]`$PayloadPath, [Parameter(Mandatory=`$true)][string]`$ResultPath, [Parameter(Mandatory=`$true)][string]`$PidPath)
`$exitCode = -1
try {
    `$payload = Get-Content -LiteralPath `$PayloadPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
    `$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    `$principal = New-Object -TypeName Security.Principal.WindowsPrincipal -ArgumentList `$identity
    if (`$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Explorer helper is still elevated; refusing to run an elevation-prohibited installer.' }
    [IO.File]::WriteAllText(`$PidPath, [string]`$PID)
    `$proc = Start-Process -FilePath ([string]`$payload.WingetPath) -ArgumentList ([string[]]`$payload.Arguments) -Wait -PassThru -NoNewWindow -ErrorAction Stop
    `$exitCode = [int]`$proc.ExitCode
} catch {
    try { [IO.File]::WriteAllText(`$ResultPath, ('ERROR: ' + `$_.Exception.Message)) } catch {}
    exit
}
try { [IO.File]::WriteAllText(`$ResultPath, [string]`$exitCode) } catch {}
"@
    $payload = [pscustomobject]@{ WingetPath=$WingetPath; Arguments=@($Arguments); ResultPath=$resultPath }
    $shell = $null
    $shellWindow = $null
    $started = $false
    try {
        Set-Content -LiteralPath $helperPath -Value $helperCode -Encoding UTF8 -ErrorAction Stop
        $payload | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $payloadPath -Encoding UTF8 -ErrorAction Stop
        $powerShellExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if (-not (Test-Path -LiteralPath $powerShellExe)) { throw 'Windows PowerShell executable was not found.' }
        $parameters = '-NoProfile -ExecutionPolicy Bypass -File "{0}" -PayloadPath "{1}" -ResultPath "{2}" -PidPath "{3}"' -f $helperPath, $payloadPath, $resultPath, $pidPath
        $show = if ($ShowWindow) { 1 } else { 0 }

        # Use Explorer's shell process to launch a standard-user helper from this elevated worker.
        $shell = New-Object -ComObject Shell.Application
        try {
            $explorerWindows = @($shell.Windows() | Where-Object { $_.FullName -match '(?i)\\explorer\.exe$' })
            if ($explorerWindows.Count -gt 0) { $shellWindow = $explorerWindows[0].Application }
        } catch { $shellWindow = $null }
        if ($shellWindow) {
            [void]$shellWindow.ShellExecute($powerShellExe, $parameters, $tempRoot, 'open', $show)
        } else {
            [void]$shell.ShellExecute($powerShellExe, $parameters, $tempRoot, 'open', $show)
        }
        $started = $true

        $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
        while (-not (Test-Path -LiteralPath $resultPath) -and (Get-Date) -lt $deadline) { Start-Sleep -Milliseconds 200 }
        if (-not (Test-Path -LiteralPath $resultPath)) {
            if (Test-Path -LiteralPath $pidPath) {
                $helperPid=0
                $pidText=(Get-Content -LiteralPath $pidPath -Raw -ErrorAction SilentlyContinue).Trim()
                if ([int]::TryParse($pidText,[ref]$helperPid) -and $helperPid -gt 0) {
                    Write-WorkerLog "[Winget/User] Timeout reached; terminating helper process tree PID $helperPid." 'ERROR'
                    try { $null = & "$env:SystemRoot\System32\taskkill.exe" /PID $helperPid /T /F 2>&1 } catch {}
                }
            }
            return [pscustomobject]@{ Started=$true; Success=$false; ExitCode=-1; TimedOut=$true }
        }
        $rawResult = (Get-Content -LiteralPath $resultPath -Raw -ErrorAction Stop).Trim()
        if ($rawResult -match '^ERROR:') {
            Write-WorkerLog "[Winget/User] Unelevated helper failed: $rawResult" 'ERROR'
            return [pscustomobject]@{ Started=$true; Success=$false; ExitCode=-1; TimedOut=$false }
        }
        $exitCode = -1
        if (-not [int]::TryParse($rawResult, [ref]$exitCode)) { $exitCode = -1 }
        return [pscustomobject]@{ Started=$true; Success=(Test-ExitSuccess -ExitCode $exitCode); ExitCode=$exitCode; TimedOut=$false }
    } catch {
        Write-WorkerLog "[Winget/User] Could not launch unelevated Winget: $($_.Exception.Message)" 'ERROR'
        return [pscustomobject]@{ Started=$started; Success=$false; ExitCode=-1; TimedOut=$false }
    } finally {
        if ($shellWindow) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shellWindow) } catch {} }
        if ($shell) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell) } catch {} }
        foreach ($file in @($helperPath,$payloadPath,$resultPath,$pidPath)) {
            if (Test-Path -LiteralPath $file) { Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Install-ViaWinget {
    param(
        [string]$TargetId,
        [string]$ActionCommand,
        [string]$ExtraFlags = "",
        [bool]$Interactive = $false,
        [int]$BasePercent = 0,
        [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800
    )

    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $winget) {
        Write-WorkerLog "Winget is unavailable." "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Started = $false; Reboot = $false; FallbackSafe = $true }
    }

    $cmd = if ($ActionCommand -eq "repair") { "install" } else { $ActionCommand }
    # WhatsApp is currently distributed through the Microsoft Store source, not the community winget source.
    $wingetSource = if ($TargetId -eq '9NKSQGP7F2NH') { 'msstore' } else { 'winget' }
    Write-WorkerLog "[Winget] Using source '$wingetSource' for $TargetId." "INFO" -Percent $BasePercent
    $argumentList = @($cmd, "--id", $TargetId, "--exact",
                      "--source", $wingetSource, "--accept-source-agreements",
                      "--accept-package-agreements")

    if ($ActionCommand -eq "repair") { $argumentList += "--force" }

    if ($Interactive) {
        $argumentList += "--interactive"
    } else {
        $argumentList += @("--silent", "--disable-interactivity")
    }

    if ($ExtraFlags) {
        $argumentList += ($ExtraFlags -split "\s+" | Where-Object { $_ })
    }

    # Spotify's WinGet manifest prohibits elevation. This utility self-elevates,
    # so launch Spotify directly through Explorer's standard-user token for every action.
    if ($TargetId -eq 'Spotify.Spotify') {
        Write-WorkerLog "[Winget/User] Spotify requires a non-elevated context; launching directly as the signed-in user." "INFO" -Percent ($BasePercent + 5)
        $userResult = Invoke-WingetUnelevated -WingetPath $winget.Source -Arguments $argumentList -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
        if ($userResult.Success) {
            Write-WorkerLog "[Winget/User] Spotify completed in the standard-user context (exit $($userResult.ExitCode))." "SUCCESS" -Percent ($BasePercent + 20)
            return [pscustomobject]@{ Success=$true; ExitCode=$userResult.ExitCode; Started=$true; Reboot=($userResult.ExitCode -in @(1641,3010)); FallbackSafe=$false }
        }
        $reason = if ($userResult.TimedOut) { ('timed out after {0} seconds' -f $TimeoutSeconds) } else { "failed (exit $($userResult.ExitCode))" }
        Write-WorkerLog "[Winget/User] Spotify $reason; no elevated retry or concurrent fallback will be launched." "ERROR" -Percent $BasePercent
        return [pscustomobject]@{ Success=$false; ExitCode=$userResult.ExitCode; Started=[bool]$userResult.Started; Reboot=$false; FallbackSafe=$false }
    }

    try {
        Write-WorkerLog "[Winget] Executing $cmd $TargetId" "INFO" -Percent ($BasePercent + 5)
        $proc = Invoke-ProcessResult -FilePath $winget.Source -ArgumentList $argumentList -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
        $ok = Test-ExitSuccess -ExitCode $proc.ExitCode
        $reboot = ($proc.ExitCode -in @(1641, 3010))
        if ($ok) {
            Write-WorkerLog "[Winget] Completed $TargetId (exit $($proc.ExitCode))." "SUCCESS" -Percent ($BasePercent + 20)
        } elseif ($proc.ExitCode -eq -1978335146) {
            Write-WorkerLog "[Winget] $TargetId prohibits elevated execution (0x8A150056); retrying once through the user's Explorer shell." "WARNING" -Percent $BasePercent
            $userResult = Invoke-WingetUnelevated -WingetPath $winget.Source -Arguments $argumentList -ShowWindow:$Interactive -TimeoutSeconds $TimeoutSeconds
            if ($userResult.Success) {
                Write-WorkerLog "[Winget/User] Completed $TargetId in the non-elevated user context (exit $($userResult.ExitCode))." "SUCCESS" -Percent ($BasePercent + 20)
                return [pscustomobject]@{ Success=$true; ExitCode=$userResult.ExitCode; Started=$true; Reboot=($userResult.ExitCode -in @(1641,3010)); FallbackSafe=$false }
            }
            if ($userResult.TimedOut) {
                Write-WorkerLog ("[Winget/User] $TargetId exceeded the configured {0} second wait window; no fallback will be launched." -f $TimeoutSeconds) "ERROR" -Percent $BasePercent
            } else {
                Write-WorkerLog "[Winget/User] $TargetId failed in the non-elevated context (exit $($userResult.ExitCode)); no concurrent fallback will be launched." "ERROR" -Percent $BasePercent
            }
            return [pscustomobject]@{ Success=$false; ExitCode=$userResult.ExitCode; Started=$true; Reboot=$false; FallbackSafe=$false }
        } else {
            Write-WorkerLog "[Winget] Returned code $($proc.ExitCode) for $TargetId." "WARNING" -Percent $BasePercent
        }
        $fallbackSafe = (-not $proc.TimedOut) -and ($proc.ExitCode -in $wingetNotFoundOrFetchErrors)
        return [pscustomobject]@{ Success = $ok; ExitCode = $proc.ExitCode; Started = $true; Reboot = $reboot; FallbackSafe = $fallbackSafe }
    }
    catch {
        Write-WorkerLog "[Winget] Error for $TargetId : $_" "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Started = $false; Reboot = $false; FallbackSafe = $true }
    }
}

function Install-ViaChocolatey {
    param(
        [string]$ChocoId,
        [ValidateSet("install", "upgrade")][string]$Action = "install",
        [bool]$Interactive = $false,
        [int]$BasePercent = 0,
        [ValidateRange(30,7200)][int]$TimeoutSeconds = 1800
    )

    if ([string]::IsNullOrWhiteSpace($ChocoId)) {
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false; Started = $false; FallbackSafe = $true }
    }

    $choco = Ensure-Chocolatey
    if (-not $choco) {
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false; Started = $false; FallbackSafe = $true }
    }

    $argumentList = @($Action, $ChocoId, "-y", "--no-progress")
    if (-not $Interactive) { $argumentList += "--no-color" }

    try {
        Write-WorkerLog "[Chocolatey] Executing $Action $ChocoId" "INFO" -Percent ($BasePercent + 10)
        $proc = Invoke-WorkerCapture -FilePath $choco -ArgumentList $argumentList -TimeoutSeconds $TimeoutSeconds
        $ok = (-not $proc.TimedOut) -and (Test-ExitSuccess -ExitCode $proc.ExitCode)
        $reboot = ($proc.ExitCode -in @(1641, 3010))
        $sourceUnavailable = (-not $proc.TimedOut) -and (($proc.Output + ' ' + $proc.Error) -match '(?im)(unable to find package|could not find package|package.+not found|no package found)')
        if ($ok) {
            Write-WorkerLog "[Chocolatey] Completed $ChocoId (exit $($proc.ExitCode), PID $($proc.ProcessId))." 'SUCCESS' -Percent ($BasePercent + 20)
        } else {
            $detail = (($proc.Error + ' ' + $proc.Output) -replace '\s+',' ').Trim()
            $detail = [regex]::Replace($detail,'(?i)(https?://[^\s?]+)\?[^\s]+','$1?[REDACTED]')
            if ($detail.Length -gt 500) { $detail = $detail.Substring(0,500) }
            Write-WorkerLog ("[Chocolatey] Returned code {0} for {1}; sourceUnavailable={2}; detail={3}" -f $proc.ExitCode,$ChocoId,$sourceUnavailable,$detail) 'WARNING' -Percent $BasePercent
        }
        return [pscustomobject]@{ Success = $ok; ExitCode = $proc.ExitCode; Reboot = $reboot; Started = $true; TimedOut=[bool]$proc.TimedOut; FallbackSafe=[bool]$sourceUnavailable }
    }
    catch {
        Write-WorkerLog "[Chocolatey] Error for $ChocoId : $_" "WARNING" -Percent $BasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false; Started = $true; FallbackSafe = $false }
    }
}

function Test-InstallerSignature {
    param([string]$Path, [string]$ExpectedPublisher)

    try {
        $signature = Get-AuthenticodeSignature -FilePath $Path
        if ($signature.Status -ne "Valid") { return $false }
        if ([string]::IsNullOrWhiteSpace($ExpectedPublisher)) { return $true }
        return ($signature.SignerCertificate.Subject -like "*$ExpectedPublisher*")
    } catch {
        return $false
    }
}

function Test-WorkerAppxPublisher {
    param([string]$PackagePath,[string]$ExpectedPublisher)
    $archive=$null; $reader=$null
    try {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
        $archive=[System.IO.Compression.ZipFile]::OpenRead($PackagePath)
        $entry=$archive.GetEntry('AppxManifest.xml')
        if(-not $entry){throw 'AppxManifest.xml was not found in the package.'}
        $entryStream=$entry.Open(); $reader=New-Object -TypeName System.IO.StreamReader -ArgumentList $entryStream
        $xml=New-Object System.Xml.XmlDocument; $xml.XmlResolver=$null; $xml.LoadXml($reader.ReadToEnd())
        $identity=$xml.SelectSingleNode("//*[local-name()='Identity']")
        if(-not $identity){throw 'Package Identity element is missing.'}
        $publisher=[string]$identity.GetAttribute('Publisher')
        if([string]::IsNullOrWhiteSpace($publisher)){throw 'Package manifest has no Publisher.'}
        if($ExpectedPublisher -and $publisher -notlike ("*{0}*" -f $ExpectedPublisher)){throw ("Publisher '{0}' does not match expected '{1}'." -f $publisher,$ExpectedPublisher)}
        return $true
    } catch {Write-WorkerLog ("[Direct] AppX/MSIX manifest validation failed: {0}" -f $_.Exception.Message) 'ERROR';return $false}
    finally {if($reader){try{$reader.Dispose()}catch{}};if($archive){try{$archive.Dispose()}catch{}}}
}

function Install-ViaDirectDownload {
    param(
        [string]$AppName,
        [string]$Url,
        [string]$InstallerArgs,
        [string]$ExpectedPublisher,
        [string]$ExpectedSha256 = '',
        [string]$ExpectedInstallerType = '',
        [string]$InteractiveInstallerArgs = '',
        [string[]]$AllowedHosts = @(),
        [ValidateRange(30,7200)][int]$InstallerTimeoutSeconds = 1800,
        [bool]$Interactive = $false,
        [int]$AppBasePercent = 0,
        [int]$AppStepWeight = 33
    )

    if ([string]::IsNullOrWhiteSpace($Url)) {
        Write-WorkerLog "[Direct] No direct URL configured for $AppName; tier skipped." "WARNING" -Percent $AppBasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false }
    }

    $downloadPath = $null
    $client = $null
    try {
        $uri = [uri]$Url
        if ($uri.Scheme -ne 'https') { throw 'HTTPS is required for direct downloads.' }
        if (@($AllowedHosts).Count -gt 0 -and $uri.Host -notin @($AllowedHosts)) {
            throw ("Download host '{0}' is not in this application's approved host list." -f $uri.Host)
        }

        [Net.ServicePointManager]::SecurityProtocol =
            [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

        $downloadPath = Join-Path $DownloadDir ("{0}_{1}.bin" -f
            ($AppName -replace "[^\w-]", "_"), [guid]::NewGuid().ToString("N"))

        Write-WorkerLog "[Direct] Downloading $AppName..." "INFO" -Percent ($AppBasePercent + 5)
        
        $client = New-Object System.Net.WebClient
        $client.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
        
        $script:LastReportedPct = -1
        $progressHandler = {
            param($sender, $e)
            $downloadPct = $e.ProgressPercentage
            if ($downloadPct -ne $script:LastReportedPct -and ($downloadPct % 5 -eq 0)) {
                $script:LastReportedPct = $downloadPct
                $calculatedGlobalPct = $AppBasePercent + [math]::Round(($downloadPct / 100) * ($AppStepWeight * 0.6))
                $bytesMB = [math]::Round($e.BytesReceived / 1MB, 1)
                $totalMB = [math]::Round($e.TotalBytesToReceive / 1MB, 1)
                Write-WorkerLog "[Direct] $AppName Downloading ($downloadPct% - $bytesMB MB / $totalMB MB)..." "INFO" -Percent $calculatedGlobalPct
            }
        }
        $client.add_DownloadProgressChanged($progressHandler)
        
        $downloadCompleted = $false
        $downloadLastError = $null
        for ($downloadAttempt = 1; $downloadAttempt -le 3; $downloadAttempt++) {
            if ($downloadAttempt -gt 1) {
                Write-WorkerLog "[Direct] Retry $downloadAttempt/3 for $AppName after a transient download failure." 'WARNING' -Percent ($AppBasePercent + 5)
                if (Test-Path -LiteralPath $downloadPath) { Remove-Item -LiteralPath $downloadPath -Force -ErrorAction SilentlyContinue }
                if ($client) { try { $client.Dispose() } catch {} }
                $client = New-Object System.Net.WebClient
                $client.Headers.Add('User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)')
                $client.add_DownloadProgressChanged($progressHandler)
            }
            $downloadTask = $client.DownloadFileTaskAsync($Url, $downloadPath)
            $downloadWaitCompleted = $false
            try { $downloadWaitCompleted = $downloadTask.Wait([TimeSpan]::FromMinutes(10)) } catch { $downloadWaitCompleted = $true }
            if (-not $downloadWaitCompleted) {
                try { $client.CancelAsync() } catch {}
                try { [void]$downloadTask.Wait(5000) } catch {}
                $downloadLastError = 'Download timed out after 10 minutes.'
                Write-WorkerLog "[Direct] Attempt $downloadAttempt timed out for $AppName." 'WARNING' -Percent $AppBasePercent
            } elseif ($downloadTask.IsFaulted) {
                $downloadLastError = $downloadTask.Exception.GetBaseException().Message
                Write-WorkerLog "[Direct] Attempt $downloadAttempt failed: $downloadLastError" 'WARNING' -Percent $AppBasePercent
            } elseif ($downloadTask.IsCanceled) {
                $downloadLastError = 'Download was cancelled.'
                Write-WorkerLog "[Direct] Attempt $downloadAttempt was cancelled." 'WARNING' -Percent $AppBasePercent
            } elseif ((Test-Path -LiteralPath $downloadPath) -and (Get-Item -LiteralPath $downloadPath).Length -ge 10240) {
                $downloadCompleted = $true
                break
            } else {
                $downloadLastError = 'Downloaded payload is empty or too small.'
            }
            if ($downloadAttempt -lt 3) { Start-Sleep -Seconds ([int](2 * $downloadAttempt)) }
        }
        if (-not $downloadCompleted) { throw ("Download failed after 3 attempts: {0}" -f $downloadLastError) }

        $stream = [IO.File]::OpenRead($downloadPath)
        try {
            $header = New-Object byte[] 8
            $read = $stream.Read($header, 0, 8)
        } finally {
            $stream.Dispose()
        }

        $kind = $null
        if ($read -ge 2 -and $header[0] -eq 0x4D -and $header[1] -eq 0x5A) {
            $kind = "exe"
        } elseif ($read -ge 4 -and $header[0] -eq 0xD0 -and $header[1] -eq 0xCF -and
                  $header[2] -eq 0x11 -and $header[3] -eq 0xE0) {
            $kind = "msi"
        } elseif ($read -ge 8 -and $header[0] -eq 0xD0 -and $header[1] -eq 0xCF) {
            $kind = 'msi'
        } elseif ($read -ge 4 -and $header[0] -eq 0x50 -and $header[1] -eq 0x4B -and
                  $ExpectedInstallerType -in @('appx','msix')) {
            # AppX/MSIX are ZIP-based signed packages. Windows deployment validates
            # package signature and publisher when Add-AppxPackage stages the package.
            $kind = $ExpectedInstallerType.ToLowerInvariant()
        } elseif ($ExpectedInstallerType -in @('appx','msix') -and $uri.AbsolutePath -match '(?i)\.(appx|msix)$') {
            $kind = $Matches[1].ToLowerInvariant()
        }

        if (-not $kind) { throw 'Downloaded file is not recognized as a supported EXE, MSI, APPX or MSIX installer.' }

        $finalPath = [IO.Path]::ChangeExtension($downloadPath, ".$kind")
        Move-Item -LiteralPath $downloadPath -Destination $finalPath -Force
        $downloadPath = $finalPath

        if ($ExpectedInstallerType -and $ExpectedInstallerType.ToLowerInvariant() -notin @('exe','msi','appx','msix')) {
            throw "Catalog InstallerType must be 'exe', 'msi', 'appx' or 'msix'; received '$ExpectedInstallerType'."
        }
        if ($ExpectedInstallerType -and $kind -ne $ExpectedInstallerType.ToLowerInvariant()) {
            throw ("Installer type mismatch: catalog expects {0}, downloaded payload is {1}." -f $ExpectedInstallerType,$kind)
        }
        if ($ExpectedSha256) {
            if ($ExpectedSha256 -notmatch '^[A-Fa-f0-9]{64}$') { throw 'Catalog SHA-256 value is malformed.' }
            $actualHash = (Get-FileHash -LiteralPath $downloadPath -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($actualHash -ine $ExpectedSha256) { throw ("SHA-256 mismatch. Expected {0}; received {1}." -f $ExpectedSha256,$actualHash) }
            Write-WorkerLog "[Direct] SHA-256 integrity check passed for $AppName." 'SUCCESS' -Percent ($AppBasePercent + 15)
        }
        if ($kind -in @('exe','msi')) {
            if (-not (Test-InstallerSignature -Path $downloadPath -ExpectedPublisher $ExpectedPublisher)) {
                throw 'Installer signature or publisher verification failed.'
            }
        } else {
            if (-not (Test-WorkerAppxPublisher -PackagePath $downloadPath -ExpectedPublisher $ExpectedPublisher)) { throw 'AppX/MSIX manifest publisher validation failed.' }
            Write-WorkerLog "[Direct] Manifest publisher matched; Windows AppX Deployment will enforce package signature and trust policy." 'INFO' -Percent ($AppBasePercent + 15)
        }

        Write-WorkerLog "[Direct] Executing installer for $AppName..." "INFO" -Percent ($AppBasePercent + [math]::Round($AppStepWeight * 0.8))

        # Interactive Install must not inherit silent switches from the catalog's default install recipe.
        $effectiveInstallerArgs = [string]$InstallerArgs
        if ($Interactive -and -not [string]::IsNullOrWhiteSpace($InteractiveInstallerArgs)) {
            $effectiveInstallerArgs = [string]$InteractiveInstallerArgs
        } elseif ($Interactive -and $effectiveInstallerArgs) {
            $effectiveInstallerArgs = $effectiveInstallerArgs -replace '(?i)(^|\s)(--silent|/silent|/S|/quiet|--quiet|/verysilent|/qn)(?=\s|$)', ' '
            $effectiveInstallerArgs = ($effectiveInstallerArgs -replace '\s{2,}', ' ').Trim()
        }

        if ($kind -in @('appx','msix')) {
            if ($Interactive) { Write-WorkerLog "[Direct] $kind uses native Windows package deployment; no separate wizard is provided by the package format." 'INFO' }
            $escapedPackagePath = $downloadPath.Replace("'", "''")
            $deploymentCommand = "try { Add-AppxPackage -Path '$escapedPackagePath' -ErrorAction Stop; exit 0 } catch { [Console]::Error.WriteLine(`$_.Exception.Message); exit 1 }"
            $encodedDeployment = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($deploymentCommand))
            $powerShellExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
            $proc = Invoke-WorkerCapture -FilePath $powerShellExe -ArgumentList @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-EncodedCommand',$encodedDeployment) -TimeoutSeconds $InstallerTimeoutSeconds
            if ($proc.TimedOut) { Write-WorkerLog "[Direct] $kind deployment timed out for $AppName." 'ERROR' }
            elseif ($proc.ExitCode -ne 0) { Write-WorkerLog ("[Direct] $kind deployment failed: {0}" -f $proc.Error) 'ERROR' }
        } elseif ($kind -eq "msi") {
            $msiArgs = @("/i", "`"$downloadPath`"")
            if (-not $Interactive) { $msiArgs += @("/qn", "/norestart") }
            if ($effectiveInstallerArgs) { $msiArgs += ($effectiveInstallerArgs -split "\s+" | Where-Object { $_ }) }
            $proc = Invoke-ProcessResult -FilePath "msiexec.exe" -ArgumentList $msiArgs -ShowWindow:$Interactive -TimeoutSeconds $InstallerTimeoutSeconds
        } else {
            # Keep the EXE argument string intact so quoted paths (e.g. AnyDesk --install "C:\Program Files...") survive.
            $exeArgs = @()
            if ($effectiveInstallerArgs) { $exeArgs = @($effectiveInstallerArgs) }
            $proc = Invoke-ProcessResult -FilePath $downloadPath -ArgumentList $exeArgs -ShowWindow:$Interactive -TimeoutSeconds $InstallerTimeoutSeconds
        }

        $ok = Test-ExitSuccess -ExitCode $proc.ExitCode
        $reboot = ($proc.ExitCode -in @(1641, 3010))
        if ($ok) {
            Write-WorkerLog "[Direct] Installer finished for $AppName (exit $($proc.ExitCode))." "SUCCESS" -Percent ($AppBasePercent + $AppStepWeight)
        } else {
            Write-WorkerLog "[Direct] Installer failed for $AppName (exit $($proc.ExitCode))." "ERROR" -Percent $AppBasePercent
        }
        return [pscustomobject]@{ Success = $ok; ExitCode = $proc.ExitCode; Reboot = $reboot }
    }
    catch {
        Write-WorkerLog "[Direct] $AppName failed: $_" "ERROR" -Percent $AppBasePercent
        return [pscustomobject]@{ Success = $false; ExitCode = -1; Reboot = $false }
    }
    finally {
        if ($client) { try { $client.Dispose() } catch {} }
        if ($downloadPath -and (Test-Path -LiteralPath $downloadPath)) {
            Remove-Item -LiteralPath $downloadPath -Force -ErrorAction SilentlyContinue
        }
    }
}

$successCount = 0
$unverifiedCount = 0
$cancelledCount = 0
$failedCount  = 0
$skippedCount = 0
$rebootNeeded = $false
$results = New-Object System.Collections.Generic.List[object]
$openedVendorPortals = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

$totalApps = $Apps.Count
$appIndex = 0

$wingetNotFoundOrFetchErrors = @(
    -1,           # Winget unavailable or process did not start
    0x80190194,   # HTTP 404 unsigned HRESULT
    -2145844844,  # HTTP 404 signed Int32 HRESULT
    -1978335212,  # 0x8A150014 - NO_APPLICATIONS_FOUND
    -1978335209,  # 0x8A150017 - NO_MANIFEST_FOUND
    -1978335214   # 0x8A150012 - SOURCE_NAME_DOES_NOT_EXIST
)

foreach ($app in $Apps) {
    $name = [string]$app.Name
    try {
    $appStartedAt = Get-Date
    $appIndex++
    $appBasePercent = [math]::Round((($appIndex - 1) / $totalApps) * 100)
    $appStepWeight  = [math]::Round((1 / $totalApps) * 100)
    
    $configuredId = [string]$app.Id
    $chocoId = [string]$app.ChocoId
    $wasInstalled = Test-WorkerInstalled -AppName $name -AppId $configuredId -ChocoId $chocoId
    $id = if ($ActionCommand -in @('upgrade','repair')) { Resolve-WorkerWingetId -AppName $name -ConfiguredId $configuredId } else { $configuredId }

    if ($ActionCommand -in @('upgrade','repair') -and -not $wasInstalled) {
        Write-WorkerLog "[$name] not detected as installed; $ActionCommand skipped." "INFO" -Percent ($appBasePercent + $appStepWeight)
        $skippedCount++
        [void]$results.Add([pscustomobject]@{ Name=$name; Status="NotInstalled"; ExitCode=0 })
        continue
    }

    if ($ActionCommand -eq "install" -and $wasInstalled) {
        Write-WorkerLog "[$name] already detected in system registry; skipped." "SUCCESS" -Percent ($appBasePercent + $appStepWeight)
        $skippedCount++
        [void]$results.Add([pscustomobject]@{ Name=$name; Status="Skipped"; ExitCode=0 })
        continue
    }

    # Account-gated commercial products are handed off to the vendor portal, including upgrade/repair requests.
    # This is never reported as an installed app; the main AMR window stays alive.
    if (-not [string]::IsNullOrWhiteSpace([string]$app.BrowserUrl)) {
        $opened = $false
        if ($openedVendorPortals.Contains([string]$app.BrowserUrl)) {
            $opened = $true
            Write-WorkerLog "[$name] vendor portal was already opened for another selected product; avoiding a duplicate browser window." 'INFO' -Percent ($appBasePercent + $appStepWeight)
        }
        $browserTargets = @([string]$app.BrowserUrl,[string]$app.CatalogUrl,[string]$app.GoogleUrl) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        foreach ($targetUrl in $browserTargets) {
            if ($opened) { break }
            try {
                $edgePath = $null
                $edgeCommand = Get-Command msedge.exe -ErrorAction SilentlyContinue
                if ($edgeCommand) { $edgePath = [string]$edgeCommand.Source }
                if ([string]::IsNullOrWhiteSpace($edgePath)) {
                    $edgeCandidates = @(
                        (Join-Path $env:ProgramFiles 'Microsoft/Edge/Application/msedge.exe'),
                        (Join-Path ${env:ProgramFiles(x86)} 'Microsoft/Edge/Application/msedge.exe'),
                        (Join-Path $env:LOCALAPPDATA 'Microsoft/Edge/Application/msedge.exe')
                    )
                    $edgePath = @($edgeCandidates | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_ -PathType Leaf) } | Select-Object -First 1)[0]
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$edgePath)) { Start-Process -FilePath $edgePath -ArgumentList @('--new-window',$targetUrl) -ErrorAction Stop | Out-Null }
                else { Start-Process -FilePath $targetUrl -ErrorAction Stop | Out-Null }
                $opened = $true
                [void]$openedVendorPortals.Add([string]$app.BrowserUrl)
                Write-WorkerLog "[$name] opened vendor download page in the browser: $targetUrl" 'SUCCESS' -Percent ($appBasePercent + $appStepWeight)
                break
            } catch { Write-WorkerLog "[$name] could not open fallback URL '$targetUrl': $($_.Exception.Message)" 'WARNING' -Percent $appBasePercent }
        }
        if ($opened) {
            $skippedCount++
            [void]$results.Add([pscustomobject]@{ Name=$name; Status='ExternalDownloadOpened'; ExitCode=0 })
        } else {
            $failedCount++
            [void]$results.Add([pscustomobject]@{ Name=$name; Status='BrowserOpenFailed'; ExitCode=-1 })
        }
        continue
    }

    Write-WorkerLog ("APP-BEGIN | Name={0} | Action={1} | WingetId={2} | ChocolateyId={3} | Interactive={4}" -f $name,$ActionCommand,$configuredId,$chocoId,$Interactive) 'INFO' -Percent $appBasePercent
    Write-WorkerLog "Processing $name ($appIndex of $totalApps)..." "INFO" -Percent $appBasePercent
    $done = $false
    $packageManagerSucceeded = $false
    $appReboot = $false
    $lastExitCode = -1
    $chocoResult = $null

    # Tier 1: native MSI repair when the installed product exposes a Windows Installer product code.
    # Other installers use Winget's force-reinstall path as a best-effort repair fallback.
    if ($ActionCommand -eq 'repair') {
        $wingetResult = Invoke-WorkerMsiRepair -AppName $name -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
        if ($null -eq $wingetResult) {
            Write-WorkerLog "[$name] No native MSI repair entry found; attempting Winget force-reinstall as best-effort repair." "INFO" -Percent $appBasePercent
            $wingetResult = Install-ViaWinget -TargetId $id -ActionCommand $ActionCommand -ExtraFlags "" -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
        }
    } else {
        $wingetResult = Install-ViaWinget -TargetId $id -ActionCommand $ActionCommand -ExtraFlags "" -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
    }
    $lastExitCode = $wingetResult.ExitCode
    if ($wingetResult.Reboot) { $appReboot = $true }

    # Winget uses a non-zero HRESULT when an upgrade is not applicable.
    # This normally means there is no newer applicable version, not that installation failed.
    if ($ActionCommand -eq "upgrade" -and $wingetResult.ExitCode -eq -1978335189) {
        Write-WorkerLog "[$name] Already up to date (Winget: no applicable update found); no action required." "SUCCESS" -Percent ($appBasePercent + $appStepWeight)
        $skippedCount++
        [void]$results.Add([pscustomobject]@{ Name=$name; Status="UpToDate"; ExitCode=$wingetResult.ExitCode })
        continue
    }

    if ($ActionCommand -eq "install" -and $wingetResult.ExitCode -eq -1978335189) {
        # Winget can return UPDATE_NOT_APPLICABLE when the package is already present.
        # Never count this as skipped unless registry/AppX/Winget inventory confirms it.
        $confirmedInstalled = Test-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -SkipWinget
        if ($confirmedInstalled) {
            Write-WorkerLog "[$name] Winget reported no applicable install action and local inventory confirms it is already installed; skipped." "SUCCESS" -Percent ($appBasePercent + $appStepWeight)
            $skippedCount++
            [void]$results.Add([pscustomobject]@{ Name=$name; Status="Skipped"; ExitCode=$wingetResult.ExitCode })
            continue
        }
        Write-WorkerLog "[$name] Winget returned UPDATE_NOT_APPLICABLE, but local installed-state verification did not confirm the app; marking this attempt failed without launching a conflicting fallback." "WARNING" -Percent $appBasePercent
    }

    if ($wingetResult.Success) {
        $done = $true
        if ($ActionCommand -eq 'install') {
            $verified = Wait-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -TimeoutSeconds 45
            if (-not $verified) {
                $done = $false; $packageManagerSucceeded = $true
                Write-WorkerLog "[$name] Winget exited successfully, but installed-state verification timed out. Marked SuccessUnverified; no fallback installer will run." 'WARNING' -Percent $appBasePercent
            }
        }
    } else {
        if ($wingetResult.Started -and ($wingetResult.ExitCode -notin $wingetNotFoundOrFetchErrors)) {
            # Do not launch a second installer after a real installer process failed or was cancelled.
            Write-WorkerLog "[$name] Winget installer started but failed (exit $($wingetResult.ExitCode)); fallback blocked to avoid concurrent or conflicting installation." "WARNING" -Percent $appBasePercent
        } else {
            Write-WorkerLog "[$name] Winget package/source unavailable; moving to Tier 2 (Chocolatey)." "INFO" -Percent $appBasePercent
        }
    }

    # Tier 2: Chocolatey fallback. In Interactive mode it is deliberately skipped because
    # Chocolatey package scripts commonly enforce silent installer switches regardless of console visibility.
    # A package manager that returned success owns the install attempt even when
    # registry/AppX visibility is delayed; never launch a second installer in that case.
    $allowFallback = (-not $wingetResult.Success) -and [bool]$wingetResult.FallbackSafe
    if (-not $done -and $allowFallback -and $ActionCommand -ne "repair" -and -not $Interactive -and -not [string]::IsNullOrWhiteSpace($chocoId)) {
        $chocoAction = if ($ActionCommand -eq "install") { "install" } else { "upgrade" }
        $chocoResult = Install-ViaChocolatey -ChocoId $chocoId -Action $chocoAction -Interactive:$Interactive -BasePercent $appBasePercent -TimeoutSeconds ([int]$app.InstallTimeoutSeconds)
        $lastExitCode = $chocoResult.ExitCode
        if ($chocoResult.Reboot) { $appReboot = $true }

        if ($chocoResult.Success) {
            $done = $true
            if ($ActionCommand -eq 'install') {
                $verified = Wait-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -TimeoutSeconds 45
                if (-not $verified) { $done = $false; $packageManagerSucceeded = $true; Write-WorkerLog "[$name] Chocolatey exit code was successful, but installed-state verification timed out. Marked SuccessUnverified; no second installer will run." 'WARNING' -Percent $appBasePercent }
            }
        } else {
            Write-WorkerLog "[$name] Chocolatey failed (exit $($chocoResult.ExitCode)); direct fallback requires a classified package-source miss." 'WARNING' -Percent $appBasePercent
        }
    }

    if (-not $done -and $allowFallback -and $Interactive -and $ActionCommand -ne "repair") {
        Write-WorkerLog "[$name] Chocolatey fallback skipped in Interactive mode to avoid package scripts forcing silent installation." "INFO" -Percent $appBasePercent
    }

    # Tier 3: Direct Download. Direct installers are permitted only for fresh installs. An EXE/MSI URL does not
    # guarantee a safe in-place upgrade and must never be used as an implicit upgrade path.
    $allowDirectFallback = (-not $packageManagerSucceeded) -and $allowFallback -and ($null -eq $chocoResult -or [bool]$chocoResult.FallbackSafe)
    if (-not $done -and $allowDirectFallback -and $ActionCommand -eq "install") {

        $directResult = Install-ViaDirectDownload -AppName $name -Url ([string]$app.DirectUrl) `
            -InstallerArgs ([string]$app.DirectArgs) -ExpectedPublisher ([string]$app.Publisher) `
            -ExpectedSha256 ([string]$app.Sha256) -ExpectedInstallerType ([string]$app.InstallerType) `
            -InteractiveInstallerArgs ([string]$app.InteractiveArgs) -AllowedHosts @($app.AllowedHosts) `
            -InstallerTimeoutSeconds ([int]$app.InstallTimeoutSeconds) `
            -Interactive:$Interactive -AppBasePercent $appBasePercent -AppStepWeight $appStepWeight
        $lastExitCode = $directResult.ExitCode
        if ($directResult.Reboot) { $appReboot = $true }

        if ($directResult.Success) {
            if (Wait-WorkerInstalled -AppName $name -AppId $id -ChocoId $chocoId -TimeoutSeconds 45) {
                $done = $true
            } else {
                $packageManagerSucceeded = $true
                Write-WorkerLog "[$name] Direct installer exited successfully, but installed-state verification timed out. Marked SuccessUnverified." 'WARNING' -Percent $appBasePercent
            }
        }
    }

    if ($appReboot) { $rebootNeeded = $true }

    if ($lastExitCode -in @(1602,1223)) {
        $cancelledCount++
        Write-WorkerLog "[$name] installation cancelled by user (exit $lastExitCode); no fallback will run." 'WARNING' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='Cancelled'; ExitCode=$lastExitCode })
    } elseif ($done) {
        $successCount++
        $successStatus = if ($appReboot) { 'NeedsReboot' } else { 'SuccessVerified' }
        Write-WorkerLog "[$name] completed and installed-state verification passed." 'SUCCESS' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status=$successStatus; ExitCode=$lastExitCode })
    } elseif ($packageManagerSucceeded) {
        $unverifiedCount++
        Write-WorkerLog "[$name] installer/package manager reported success, but verification evidence is unavailable. Review diagnostics; no duplicate install was attempted." 'WARNING' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='SuccessUnverified'; ExitCode=$lastExitCode })
    } else {
        $failedCount++
        Write-WorkerLog "[$name] failed in all applicable tiers; continuing queue." 'ERROR' -Percent ($appBasePercent + $appStepWeight)
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='Failed'; ExitCode=$lastExitCode })
    }
    $appElapsed = [math]::Round(((Get-Date) - $appStartedAt).TotalSeconds,1)
    Write-WorkerLog ("APP-END | Name={0} | ElapsedSeconds={1} | ExitCode={2} | Verified={3}" -f $name,$appElapsed,$lastExitCode,$done) 'INFO'
    } catch {
        $failedCount++
        $appError = $_.Exception.Message
        Write-WorkerLog ("APP-EXCEPTION | Name={0} | Error={1} | Queue will continue." -f $name,$appError) 'ERROR'
        [void]$results.Add([pscustomobject]@{ Name=$name; Status='FailedException'; ExitCode=-1; Error=$appError })
        continue
    }
}

$workerSummary = [pscustomobject]@{
    ActionName   = $ActionName
    SuccessCount = $successCount
    UnverifiedCount = $unverifiedCount
    CancelledCount = $cancelledCount
    FailedCount  = $failedCount
    SkippedCount = $skippedCount
    RebootNeeded = $rebootNeeded
    Results      = $results.ToArray()
}
# Publish completion through an atomic file handoff. This avoids PowerShell 5.1
# generic-collection marshaling and shared-object visibility edge cases between runspaces.
try {
    $workerSummaryJson = ConvertTo-Json -InputObject $workerSummary -Depth 8 -Compress
    if ([string]::IsNullOrWhiteSpace($workerSummaryJson)) { throw 'Worker summary serialization returned an empty payload.' }
    if ([string]::IsNullOrWhiteSpace($CompletionFilePath)) { throw 'Completion file path was not supplied to the worker.' }
    $completionTempPath = $CompletionFilePath + '.tmp.' + [guid]::NewGuid().ToString('N')
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($completionTempPath, [string]$workerSummaryJson, $utf8NoBom)
    if ([System.IO.File]::Exists($CompletionFilePath)) { [System.IO.File]::Delete($CompletionFilePath) }
    [System.IO.File]::Move($completionTempPath, $CompletionFilePath)
    Write-WorkerLog ("WORKER-PUBLISH | Summary payload committed ({0} characters)." -f $workerSummaryJson.Length) 'INFO'
} catch {
    Write-WorkerLog ("WORKER-PUBLISH-ERROR | {0}" -f $_.Exception.Message) 'ERROR'
    throw
}
Write-WorkerLog "Queue completed." "SUCCESS" -Percent 100
'@

function Set-AMRInstallButtonsEnabled {
    param([bool]$Enabled)

    foreach ($name in @('InstallSelectedBtn','InstallInteractiveBtn','UpdateSelectedBtn','RepairSelectedBtn','UninstallSelectedBtn','DeselectAllBtn')) {
        $button = C $name
        if ($button) { $button.IsEnabled = $Enabled }
    }
}

function Update-AMRInstallProgressFromLogLine {
    param([string]$Line)

    if ([string]::IsNullOrWhiteSpace($Line)) { return $Line }
    $displayLine = $Line
    if ($Line -match '^PROG:(\d+)\|(.*)$') {
        $percent = [math]::Max(0, [math]::Min(100, [int]$matches[1]))
        $displayLine = [string]$matches[2]
        $script:ProgressBar.IsIndeterminate = $false
        $script:ProgressBar.Value = $percent
        return ("{0}%  |  {1}" -f $percent, $displayLine)
    }

    # Package managers and native installers do not consistently expose a numeric
    # percentage. Animate the bar during those waits instead of leaving it frozen
    # at an old milestone or inventing a percentage.
    if ($Line -match '(?i)\[(Winget|Chocolatey|Direct)\].*(Executing|Downloading|Installer started|Running native Windows Installer)') {
        $script:ProgressBar.IsIndeterminate = $true
        return ('Working  |  ' + $Line)
    } elseif ($Line -match '(?i)(Completed|finished|failed|returned code|timed out|APP-END|APP-EXCEPTION|Queue completed)') {
        $script:ProgressBar.IsIndeterminate = $false
    }
    return $displayLine
}

function Write-AMRInstallLogBatch {
    param([string[]]$Lines)
    if (-not $Lines -or $Lines.Count -eq 0) { return }

    $displayLines = New-Object 'System.Collections.Generic.List[string]'
    $latest = $null
    foreach ($rawLine in $Lines) {
        if ([string]::IsNullOrWhiteSpace($rawLine)) { continue }
        $displayLine = Update-AMRInstallProgressFromLogLine -Line $rawLine
        [void]$displayLines.Add([string]$displayLine)
        $latest = [string]$displayLine
    }
    if ($displayLines.Count -eq 0) { return }

    try {
        Add-Content -LiteralPath $script:LogFile -Value $displayLines.ToArray() -Encoding UTF8 -ErrorAction Stop
    } catch {
        Write-AMRDiagnostic -Severity 'ERROR' -Area 'Software' -Operation 'AppendInstallLogBatch' -Message 'Could not persist a batch of installer log lines.' -ErrorRecord $_ -Target $script:LogFile
    }

    # Installer progress lines go through the same bounded UI queue (shown in the summary view).
    foreach ($installDisplayLine in $displayLines) {
        try {
            [void]$script:LogUIQueue.Enqueue([pscustomobject]@{
                Line = [string]$installDisplayLine
                Area = 'Software'
                Level = 'INFO'
                Message = [string]$installDisplayLine
                Major = $true
            })
        } catch {}
    }
    if ($latest) {
        if ($script:Status) { $script:Status.Text = $latest }
        if ($script:ProgressText) { $script:ProgressText.Text = $latest }
    }
}

function Complete-AMRInstallQueue {
    param($Result, [string]$ErrorText = '')

    if ($script:InstallTimer) {
        $script:InstallTimer.Stop()
        $script:InstallTimer = $null
    }

    $completionLogBatch = New-Object 'System.Collections.Generic.List[string]'
    $line = $null
    while ($script:InstallLogQueue.TryDequeue([ref]$line)) {
        if ($line) { [void]$completionLogBatch.Add([string]$line) }
        $line = $null
    }
    if ($completionLogBatch.Count -gt 0) {
        Write-AMRInstallLogBatch -Lines $completionLogBatch.ToArray()
    }

    if ($script:InstallPowerShell) {
        try { $script:InstallPowerShell.Dispose() } catch {}
        $script:InstallPowerShell = $null
    }
    if ($script:InstallRunspace) {
        try { $script:InstallRunspace.Close(); $script:InstallRunspace.Dispose() } catch {}
        $script:InstallRunspace = $null
    }

    $script:InstallAsyncResult = $null
    $script:InstallOutput = $null
    $script:InstallResultQueue = $null
    if ($script:InstallCompletionFile) { try { Remove-Item -LiteralPath $script:InstallCompletionFile -Force -ErrorAction SilentlyContinue } catch {}; $script:InstallCompletionFile = $null }
    $script:InstallRunning = $false

    foreach ($app in $script:SoftwareCatalog) { $app.IsSelected = $false }
    $script:AppsView.Refresh()
    Set-AMRInstallButtonsEnabled -Enabled $true

    if ($ErrorText) {
        $script:ProgressBar.IsIndeterminate = $false
        $script:ProgressBar.Value = 0
        $script:ProgressText.Text = "Installation failed with error."
        Write-AMRLog "Installation worker failed: $ErrorText" ERROR Software
        Show-AMRMessageGlass "The installation worker stopped unexpectedly:`n`n$ErrorText" "Engine Error" OK Error | Out-Null
        return
    }

    if (-not $Result) {
        Show-AMRMessageGlass "The operation finished without returning a result." "Engine Warning" OK Warning | Out-Null
        return
    }

    # Do not assume an installer exit code alone proves the app is registered.
    # Re-scan after verified or pending-verification successes so catalog flags,
    # the Installed view and the persistent snapshot reflect Windows' actual state.
    if ([int]$Result.SuccessCount -gt 0 -or [int]$Result.UnverifiedCount -gt 0) {
        try {
            Start-AMRInstalledCatalogScan -Refresh -ShowWhenReady:([bool]$script:ShowInstalledOnly)
        } catch {
            Write-AMRLog ("Could not schedule the post-install inventory refresh: {0}" -f $_.Exception.Message) WARNING Software
        }
    }

    $summary = "$($Result.ActionName) Summary:`n`n" +
               "✔ Verified successes: $($Result.SuccessCount)`n" +
               "⚠ Success, verification pending: $($Result.UnverifiedCount)`n" +
               "↩ Cancelled: $($Result.CancelledCount)`n" +
               "⏭ Skipped (already installed): $($Result.SkippedCount)`n" +
               "❌ Failed: $($Result.FailedCount)"

    if ($Result.RebootNeeded) {
        $summary += "`n`n⚠ One or more installers requested a restart (1641/3010)."
    }

    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 100
    $script:ProgressText.Text = "Finished: $($Result.SuccessCount) Verified, $($Result.UnverifiedCount) Unverified, $($Result.CancelledCount) Cancelled, $($Result.SkippedCount) Skipped, $($Result.FailedCount) Failed."
    Write-AMRLog "Queue finished. Verified: $($Result.SuccessCount), Unverified: $($Result.UnverifiedCount), Cancelled: $($Result.CancelledCount), Skipped: $($Result.SkippedCount), Failed: $($Result.FailedCount)." SUCCESS Software
    Show-AMRMessageGlass $summary "Operation Summary" OK Information | Out-Null
}

function Execute-SmartMultiTierInstallAsync {
    param(
        [string]$ActionCommand,
        [string]$ActionName,
        [string]$ExtraFlags = '',
        [switch]$Interactive
    )

    if ($script:InstallRunning) {
        Write-AMRLog "An installation queue is already running." WARNING Software
        return
    }

    if ($ActionCommand -notin @('install','upgrade','repair')) {
        Show-AMRMessageGlass "Unsupported software action: $ActionCommand" "Invalid Action" OK Error | Out-Null
        return
    }

    $selectedSnapshot = @(
        $script:SoftwareCatalog |
        Where-Object { $_.IsSelected -eq $true } |
        ForEach-Object {
            [pscustomobject]@{
                Name       = [string]$_.Name
                Category   = [string]$_.Category
                Id         = [string]$_.Id
                ChocoId    = [string]$_.ChocoId
                DirectUrl  = [string]$_.DirectUrl
                DirectArgs = [string]$_.DirectArgs
                Publisher  = [string]$_.Publisher
                BrowserUrl = [string]$_.BrowserUrl
                CatalogUrl = [string]$_.CatalogUrl
                GoogleUrl  = [string]$_.GoogleUrl
                Sha256     = [string]$_.Sha256
                InstallerType = [string]$_.InstallerType
                InteractiveArgs = [string]$_.InteractiveArgs
                AllowedHosts = @($_.AllowedHosts)
                InstallTimeoutSeconds = if ($_.InstallTimeoutSeconds) { [int]$_.InstallTimeoutSeconds } else { 1800 }
            }
        }
    )

    # A13h: in Show Installed mode the cards are records of $script:InstalledAppsInventory, not catalog items.
    # Update and Repair read the checked installed records there. Install actions and catalog mode are unchanged.
    if ($ActionCommand -in @('upgrade','repair') -and $script:ShowInstalledOnly) {
        try {
            $installedSelectedSnapshot = New-Object 'System.Collections.Generic.List[object]'
            $installedSeenNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($installedRecord in @($script:InstalledAppsInventory | Where-Object { $_.IsSelected -eq $true -and $_.IsInstalled -eq $true })) {
                $installedName = [string]$installedRecord.Name
                if ([string]::IsNullOrWhiteSpace($installedName) -or -not $installedSeenNames.Add($installedName)) { continue }
                $catalogMatch = $null
                if ($installedRecord.IsCatalogApp -eq $true -and -not [string]::IsNullOrWhiteSpace([string]$installedRecord.CatalogId)) {
                    $catalogMatch = $script:SoftwareCatalog | Where-Object { [string]$_.Id -eq [string]$installedRecord.CatalogId } | Select-Object -First 1
                }
                if ($catalogMatch) {
                    $installedSelectedSnapshot.Add([pscustomobject]@{
                        Name       = [string]$catalogMatch.Name
                        Category   = [string]$catalogMatch.Category
                        Id         = [string]$catalogMatch.Id
                        ChocoId    = [string]$catalogMatch.ChocoId
                        DirectUrl  = [string]$catalogMatch.DirectUrl
                        DirectArgs = [string]$catalogMatch.DirectArgs
                        Publisher  = [string]$catalogMatch.Publisher
                        BrowserUrl = [string]$catalogMatch.BrowserUrl
                        CatalogUrl = [string]$catalogMatch.CatalogUrl
                        GoogleUrl  = [string]$catalogMatch.GoogleUrl
                        Sha256     = [string]$catalogMatch.Sha256
                        InstallerType = [string]$catalogMatch.InstallerType
                        InteractiveArgs = [string]$catalogMatch.InteractiveArgs
                        AllowedHosts = @($catalogMatch.AllowedHosts)
                        InstallTimeoutSeconds = if ($catalogMatch.InstallTimeoutSeconds) { [int]$catalogMatch.InstallTimeoutSeconds } else { 1800 }
                    })
                } else {
                    $installedSelectedSnapshot.Add([pscustomobject]@{
                        Name       = $installedName
                        Category   = [string]$installedRecord.Category
                        Id         = [string]$installedRecord.WingetId
                        ChocoId    = [string]$installedRecord.ChocoId
                        DirectUrl  = ''
                        DirectArgs = ''
                        Publisher  = [string]$installedRecord.Publisher
                        BrowserUrl = ''
                        CatalogUrl = ''
                        GoogleUrl  = ''
                        Sha256     = ''
                        InstallerType = ''
                        InteractiveArgs = ''
                        AllowedHosts = @()
                        InstallTimeoutSeconds = 1800
                    })
                }
            }
            if ($installedSelectedSnapshot.Count -gt 0) {
                $selectedSnapshot = @($installedSelectedSnapshot.ToArray())
                Write-AMRLog "Software $ActionName uses $($selectedSnapshot.Count) selected installed app(s) in Show Installed mode." INFO Software
            }
        } catch {
            Write-AMRLog "Installed-mode selection read failed: $($_.Exception.Message)" WARNING Software
        }
    }

    if ($selectedSnapshot.Count -eq 0) {
        Show-AMRMessageGlass "Please select at least one application." "Selection Required" OK Warning | Out-Null
        return
    }

    $script:InstallRunning = $true
    $script:InstallActionName = $ActionName
    $script:InstallSelectedSnapshot = $selectedSnapshot
    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 0
    $script:ProgressText.Text = "Initializing $ActionName..."
    Set-AMRInstallButtonsEnabled -Enabled $false

    Write-AMRLog "Starting $ActionName for $($selectedSnapshot.Count) application(s)." INFO Software

    try {
        $discardedLine = $null
        while ($script:InstallLogQueue.TryDequeue([ref]$discardedLine)) {
            $discardedLine = $null
        }

        $script:InstallRunspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $script:InstallRunspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $script:InstallRunspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $script:InstallRunspace.Open()

        $script:InstallCompletionFile = Join-Path ([IO.Path]::GetTempPath()) ('AMR_SW_COMPLETION_' + [guid]::NewGuid().ToString('N') + '.json')
        $script:InstallPowerShell = [PowerShell]::Create()
        $script:InstallPowerShell.Runspace = $script:InstallRunspace

        [void]$script:InstallPowerShell.AddScript($script:InstallWorkerCode)
        [void]$script:InstallPowerShell.AddArgument($selectedSnapshot)
        [void]$script:InstallPowerShell.AddArgument($ActionCommand)
        [void]$script:InstallPowerShell.AddArgument($ActionName)
        [void]$script:InstallPowerShell.AddArgument([bool]$Interactive)
        [void]$script:InstallPowerShell.AddArgument($script:DownloadDir)
        [void]$script:InstallPowerShell.AddArgument($script:InstallLogQueue)
        [void]$script:InstallPowerShell.AddArgument([string]$script:InstallCompletionFile)
        $script:InstallOutput = $null
        # Start asynchronously; the worker commits one summary to its unique completion file.
        $script:InstallAsyncResult = $script:InstallPowerShell.BeginInvoke()

        $script:InstallTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:InstallTimer.Interval = [TimeSpan]::FromMilliseconds(150)
        $script:InstallTimer.Add_Tick({
            $installLogBatch = New-Object 'System.Collections.Generic.List[string]'
            $queuedLine = $null
            $installBatchLimit = 120
            while ($installLogBatch.Count -lt $installBatchLimit -and $script:InstallLogQueue.TryDequeue([ref]$queuedLine)) {
                if ($queuedLine) { [void]$installLogBatch.Add([string]$queuedLine) }
                $queuedLine = $null
            }
            if ($installLogBatch.Count -gt 0) {
                Write-AMRInstallLogBatch -Lines $installLogBatch.ToArray()
            }

            if ($script:InstallAsyncResult -and $script:InstallAsyncResult.IsCompleted) {
                if ($script:InstallTimer) { $script:InstallTimer.Stop() }
                $resultObject = $null
                $errorMessage = ''
                try {
                    # Read the atomically committed worker summary from its unique file.
                    $summaryPayload = [string]::Empty
                    if ($script:InstallCompletionFile -and [System.IO.File]::Exists($script:InstallCompletionFile)) {
                        $summaryPayload = [System.IO.File]::ReadAllText($script:InstallCompletionFile)
                        if ([string]::IsNullOrWhiteSpace($summaryPayload)) {
                            $errorMessage = 'The installation worker published an empty completion payload.'
                        } else {
                            try {
                                $resultObject = ConvertFrom-Json -InputObject $summaryPayload -ErrorAction Stop
                                # Normal completion summaries do not contain WorkerError fields.
                                # Under StrictMode, reading a missing PSCustomObject property throws;
                                # inspect the property collection before reading optional diagnostics.
                                if ($null -ne $resultObject) {
                                    $workerErrorProperty = $resultObject.PSObject.Properties['WorkerError']
                                    if ($workerErrorProperty -and -not [string]::IsNullOrWhiteSpace([string]$workerErrorProperty.Value)) {
                                        $workerDiagnostic = "Worker fatal error: $([string]$workerErrorProperty.Value)"
                                        $workerErrorTypeProperty = $resultObject.PSObject.Properties['WorkerErrorType']
                                        $workerStackProperty = $resultObject.PSObject.Properties['WorkerStackTrace']
                                        if ($workerErrorTypeProperty -and $workerErrorTypeProperty.Value) { $workerDiagnostic += " | Type=$([string]$workerErrorTypeProperty.Value)" }
                                        if ($workerStackProperty -and $workerStackProperty.Value) { $workerDiagnostic += " | Stack=$([string]$workerStackProperty.Value)" }
                                        $errorMessage = $workerDiagnostic
                                    }
                                }
                            } catch {
                                $errorMessage = 'The installation worker published an unreadable completion payload: ' + $_.Exception.Message
                            }
                        }
                    } else {
                        $workerState = 'Unknown'
                        $workerReason = ''
                        try {
                            if ($script:InstallPowerShell -and $script:InstallPowerShell.InvocationStateInfo) {
                                $workerState = [string]$script:InstallPowerShell.InvocationStateInfo.State
                                if ($script:InstallPowerShell.InvocationStateInfo.Reason) {
                                    $workerReason = [string]$script:InstallPowerShell.InvocationStateInfo.Reason.Exception.Message
                                }
                            }
                        } catch {}
                        $errorMessage = "The installation worker ended without committing its completion file. WorkerState=$workerState. $workerReason Check WORKER-PUBLISH diagnostics and the PowerShell error stream."
                    }
                } catch {
                    $errorMessage = $_.Exception.Message
                }

                if ($script:InstallPowerShell.Streams.Error.Count -gt 0) {
                    $streamErrors = ($script:InstallPowerShell.Streams.Error | ForEach-Object {
                        $detail = $_.ToString()
                        if ($_.InvocationInfo -and $_.InvocationInfo.PositionMessage) { $detail += "`n" + $_.InvocationInfo.PositionMessage }
                        if ($_.ScriptStackTrace) { $detail += "`nStack: " + $_.ScriptStackTrace }
                        $detail
                    }) -join "`n--- Worker Error ---`n"
                    Write-AMRLog ("WORKER-ERROR-STREAM | " + $streamErrors) ERROR Software
                    if (-not $resultObject) { $errorMessage = $streamErrors }
                    else { Write-AMRLog "Worker reported non-terminating errors: $streamErrors" WARNING Software }
                }

                if (-not $resultObject -and -not $errorMessage) {
                    $errorMessage = "The worker completed but did not return a valid summary object."
                }

                Complete-AMRInstallQueue -Result $resultObject -ErrorText $errorMessage
            }
        })
        $script:InstallTimer.Start()
    }
    catch {
        Complete-AMRInstallQueue -Result $null -ErrorText $_.Exception.Message
    }
}

Add-AMRStartupMark 'L23960 before-SafeUninstallEngine'
# --- SAFE SOFTWARE UNINSTALL ENGINE ---
function Show-AMRUninstallChoice {
    param([string[]]$ApplicationNames)

    $dialog = New-Object System.Windows.Window
    $dialog.Title = 'AMR | Uninstall Options'
    $dialog.Owner = $script:Window
    $dialog.WindowStartupLocation = 'CenterOwner'
    $dialog.SizeToContent = 'WidthAndHeight'
    $dialog.MinWidth = 500
    $dialog.MaxWidth = 620
    $dialog.ResizeMode = 'NoResize'
    $dialog.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#18181B')
    $dialog.Foreground = [System.Windows.Media.Brushes]::White
    $dialog.ShowInTaskbar = $false

    $root = New-Object System.Windows.Controls.StackPanel
    $root.Margin = '20'
    $heading = New-Object System.Windows.Controls.TextBlock
    $heading.Text = 'Choose how AMR should remove the selected app(s)'
    $heading.FontSize = 17; $heading.FontWeight = 'Bold'; $heading.Foreground = [System.Windows.Media.Brushes]::White
    $root.Children.Add($heading) | Out-Null
    $names = New-Object System.Windows.Controls.TextBlock
    $names.Text = ($ApplicationNames | ForEach-Object { '• ' + $_ }) -join "`n"
    $names.Margin = '0,8,0,12'; $names.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#A1A1AA')
    $names.TextWrapping = 'Wrap'; $names.MaxHeight = 90
    $root.Children.Add($names) | Out-Null

    # Use a restrained, static button template so WPF's default theme does not
    # apply the overly bright hover/focus animation to these destructive choices.
    function New-AMRUninstallButtonStyle {
        param([string]$HoverColor, [string]$PressedColor, [string]$BorderColor = '#465365', [string]$HoverBorderColor = '#718096')
        $styleXaml = @"
<Style xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="{x:Type Button}" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Setter Property="BorderThickness" Value="1"/>
  <Setter Property="BorderBrush" Value="$BorderColor"/>
  <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
  <Setter Property="Template">
    <Setter.Value>
      <ControlTemplate TargetType="{x:Type Button}">
        <Border x:Name="ButtonBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="7" SnapsToDevicePixels="True">
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="8,2" RecognizesAccessKey="True"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="ButtonBorder" Property="Background" Value="$HoverColor"/>
            <Setter TargetName="ButtonBorder" Property="BorderBrush" Value="$HoverBorderColor"/>
          </Trigger>
          <Trigger Property="IsPressed" Value="True">
            <Setter TargetName="ButtonBorder" Property="Background" Value="$PressedColor"/>
          </Trigger>
          <Trigger Property="IsEnabled" Value="False">
            <Setter TargetName="ButtonBorder" Property="Opacity" Value="0.55"/>
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Setter.Value>
  </Setter>
</Style>
"@
        return [Windows.Markup.XamlReader]::Parse($styleXaml)
    }

    $result = @{ Choice = 'Cancel' }
    $preserve = New-Object System.Windows.Controls.Button
    $preserve.Content = 'Uninstall — keep app data where the native method supports it'
    $preserve.Height = 40; $preserve.Margin = '0,0,0,8'; $preserve.Padding = '12,8'
    $preserve.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#293B50')
    $preserve.Foreground = [System.Windows.Media.Brushes]::White; $preserve.FontWeight = 'SemiBold'
    $preserve.Cursor = [System.Windows.Input.Cursors]::Hand
    $preserve.Style = New-AMRUninstallButtonStyle -HoverColor '#354B63' -PressedColor '#1D2B3B'
    $preserve.Add_Click({ $result.Choice = 'UninstallOnly'; $dialog.Close() }.GetNewClosure())
    $root.Children.Add($preserve) | Out-Null

    $complete = New-Object System.Windows.Controls.Button
    $complete.Content = 'Complete — run native uninstaller (no AMR extra cleanup)'
    $complete.Height = 40; $complete.Margin = '0,0,0,8'; $complete.Padding = '12,8'
    $complete.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#B94A52')
    $complete.Foreground = [System.Windows.Media.Brushes]::White; $complete.FontWeight = 'SemiBold'
    $complete.Cursor = [System.Windows.Input.Cursors]::Hand
    $complete.Style = New-AMRUninstallButtonStyle -HoverColor '#C65A62' -PressedColor '#963842' -BorderColor '#D9777E' -HoverBorderColor '#E58B91'
    $complete.Add_Click({ $result.Choice = 'Complete'; $dialog.Close() }.GetNewClosure())
    $root.Children.Add($complete) | Out-Null

    $note = New-Object System.Windows.Controls.TextBlock
    $note.Text = 'Win32 cleanup is controlled by the vendor uninstaller; AMR cannot guarantee its data behavior. AppX Keep Data requests data preservation where supported. Portable apps are removed as exact folders after a separate confirmation. AMR performs no extra registry or folder cleanup.'
    $note.TextWrapping = 'Wrap'; $note.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#FBBF24'); $note.Margin = '0,4,0,10'
    $root.Children.Add($note) | Out-Null
    $cancel = New-Object System.Windows.Controls.Button
    $cancel.Content = 'Cancel'; $cancel.HorizontalAlignment = 'Right'; $cancel.Width = 110; $cancel.Height = 34
    $cancel.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#B94A52'); $cancel.Foreground = [System.Windows.Media.Brushes]::White
    $cancel.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#D9777E')
    $cancel.Cursor = [System.Windows.Input.Cursors]::Hand
    $cancel.Style = New-AMRUninstallButtonStyle -HoverColor '#C65A62' -PressedColor '#963842' -BorderColor '#D9777E' -HoverBorderColor '#E58B91'
    $cancel.Add_Click({ $dialog.Close() })
    $root.Children.Add($cancel) | Out-Null
    $dialog.Content = $root
    [void]$dialog.ShowDialog()
    return [string]$result.Choice
}

function Get-AMRExactUninstallEntry {
    param([string]$AppName)
    $paths = @(
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($path in $paths) {
        try {
            $entry = Get-ItemProperty -Path $path -ErrorAction SilentlyContinue | Where-Object {
                $_.PSObject.Properties['DisplayName'] -and ([string]$_.DisplayName).Trim().Equals($AppName.Trim(), [StringComparison]::OrdinalIgnoreCase)
            } | Select-Object -First 1
            if ($entry) { return $entry }
        } catch {}
    }
    return $null
}

function Get-AMRSafeCleanupCandidates {
    param($App)
    $candidates = New-Object System.Collections.Generic.List[string]
    $entry = Get-AMRExactUninstallEntry -AppName ([string]$App.Name)
    # InstallLocation is optional in Windows uninstall registry entries. Access it
    # through PSObject.Properties so entries without that value cannot throw.
    $installLocationProperty = if ($entry) { $entry.PSObject.Properties['InstallLocation'] } else { $null }
    if ($installLocationProperty -and -not [string]::IsNullOrWhiteSpace([string]$installLocationProperty.Value)) {
        try {
            $full = [IO.Path]::GetFullPath([string]$installLocationProperty.Value).TrimEnd('\')
            $leaf = [IO.Path]::GetFileName($full)
            $normLeaf = ($leaf -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
            $normName = ([string]$App.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
            $protectedRoots = @($env:USERPROFILE, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData, $env:WINDIR) | Where-Object { $_ }
            $isProtectedRoot = $false
            foreach ($rootPath in $protectedRoots) {
                try { if ($full.Equals([IO.Path]::GetFullPath($rootPath).TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase)) { $isProtectedRoot = $true } } catch {}
            }
            if (-not $isProtectedRoot -and $normLeaf -eq $normName -and (Test-Path -LiteralPath $full -PathType Container)) { $candidates.Add($full) }
        } catch {}
    }
    # AppData is included only when the folder name is an exact normalized match.
    $appDataRoots = @((Join-Path $env:APPDATA ''), (Join-Path $env:LOCALAPPDATA '')) | Where-Object { $_ }
    $normalizedName = ([string]$App.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
    foreach ($rootPath in $appDataRoots) {
        try {
            if (Test-Path -LiteralPath $rootPath) {
                foreach ($folder in @(Get-ChildItem -LiteralPath $rootPath -Directory -ErrorAction SilentlyContinue)) {
                    $normalizedLeaf = ($folder.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                    if ($normalizedLeaf -eq $normalizedName -and -not $candidates.Contains($folder.FullName)) { $candidates.Add($folder.FullName) }
                }
            }
        } catch {}
    }
    return @($candidates)
}

function Remove-AMRExactUninstallRegistryEntry {
    param([string]$AppName)
    $entry = Get-AMRExactUninstallEntry -AppName $AppName
    if (-not $entry) { return $false }
    $keyPath = [string]$entry.PSPath
    if ([string]::IsNullOrWhiteSpace($keyPath)) { return $false }
    # Re-check the exact DisplayName immediately before deleting this one uninstall metadata key.
    try {
        $current = Get-ItemProperty -LiteralPath $keyPath -ErrorAction Stop
        if (-not $current.PSObject.Properties['DisplayName'] -or
            -not ([string]$current.DisplayName).Trim().Equals($AppName.Trim(), [StringComparison]::OrdinalIgnoreCase)) { return $false }
        Remove-Item -LiteralPath $keyPath -Recurse -Force -ErrorAction Stop
        Write-AMRLog "Removed exact uninstall registry metadata for '$AppName'." SUCCESS Software
        return $true
    } catch {
        Write-AMRLog "Could not remove exact uninstall registry metadata for '$AppName': $($_.Exception.Message)" WARNING Software
        return $false
    }
}

function Wait-AMRUninstallProcess {
    param(
        [Parameter(Mandatory=$true)]$Process,
        [Parameter(Mandatory=$true)][string]$AppName
    )

    if (-not $Process) { throw 'The uninstaller process was not created.' }
    $script:ProgressBar.IsIndeterminate = $true
    $script:ProgressText.Text = "Uninstalling $AppName... waiting for the uninstaller to finish."

    # Keep WPF responsive while a native uninstaller runs. The indeterminate bar
    # intentionally communicates activity, not a fabricated percentage.
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(180)
    $tickHandler = {
        try {
            $Process.Refresh()
            if ($Process.HasExited) {
                $timer.Stop()
                $frame.Continue = $false
            }
        } catch {
            $timer.Stop()
            $frame.Continue = $false
        }
    }.GetNewClosure()
    $timer.Add_Tick($tickHandler)
    try {
        $timer.Start()
        [System.Windows.Threading.Dispatcher]::PushFrame($frame)
        $Process.Refresh()
        if (-not $Process.HasExited) { [void]$Process.WaitForExit() }
        return [int]$Process.ExitCode
    } finally {
        try { $timer.Stop(); $timer.Remove_Tick($tickHandler) } catch {}
        $script:ProgressBar.IsIndeterminate = $false
    }
}

function Invoke-AMRExactNativeUninstall {
    param(
        $App,
        [bool]$KeepData = $true,
        [bool]$Complete = $false
    )

    # Keep a full attempt trail. A failed registry uninstaller must NOT prevent
    # trying the exact package-manager identity configured for this catalog item.
    $attempts = New-Object System.Collections.Generic.List[string]
    $entry = Get-AMRExactUninstallEntry -AppName ([string]$App.Name)

    if ($entry) {
        $isMsi = $false
        try { $isMsi = ([int]$entry.WindowsInstaller -eq 1) } catch {}
        $quietUninstallText = ''
        $normalUninstallText = ''
        if ($entry.PSObject.Properties['QuietUninstallString']) { $quietUninstallText = [string]$entry.QuietUninstallString }
        if ($entry.PSObject.Properties['UninstallString']) { $normalUninstallText = [string]$entry.UninstallString }
        $uninstallText = if (-not [string]::IsNullOrWhiteSpace($quietUninstallText)) {
            $quietUninstallText
        } else { $normalUninstallText }
        $productCode = $null
        if ($uninstallText -match '(?i)\{[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\}') { $productCode = $Matches[0] }
        if (-not $productCode -and [string]$entry.PSChildName -match '^\{[0-9a-fA-F-]{36}\}$') { $productCode = [string]$entry.PSChildName }

        if (($isMsi -or $productCode) -and $productCode) {
            try {
                $msiArgs = @('/x', $productCode)
                if (-not $KeepData) { $msiArgs += @('/qn', '/norestart') }
                else { $msiArgs += @('/passive', '/norestart') }
                $proc = Start-Process -FilePath 'msiexec.exe' -ArgumentList $msiArgs -PassThru -ErrorAction Stop
                $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
                try { $proc.Dispose() } catch {}
                if ($uninstallExitCode -in @(0,1641,3010)) {
                    return [pscustomobject]@{ Success=$true; Detail="Native MSI uninstall succeeded (exit $uninstallExitCode)." }
                }
                $attempts.Add("MSI uninstall returned exit code $uninstallExitCode")
            } catch { $attempts.Add("MSI uninstall error: $($_.Exception.Message)") }
        } elseif (-not [string]::IsNullOrWhiteSpace($uninstallText)) {
            try {
                # Parse quoted executable paths correctly; never use Invoke-Expression.
                if ($uninstallText -match '^\s*"(?<exe>[^"]+)"\s*(?<args>.*)$') {
                    $exe = $Matches.exe; $args = [string]$Matches.args
                } elseif ($uninstallText -match '^\s*(?<exe>.+?\.exe)\s*(?<args>.*)$') {
                    $exe = $Matches.exe.Trim('"'); $args = [string]$Matches.args
                } else {
                    throw "Could not safely parse uninstall command: $uninstallText"
                }
                if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) {
                    throw "Uninstaller executable was not found: $exe"
                }
                # Resolve the product installation directory for uninstallers that
                # require their original working directory (notably NSIS).
                $installDir = ''
                $installLocationProperty = $entry.PSObject.Properties['InstallLocation']
                if ($installLocationProperty) { $installDir = [string]$installLocationProperty.Value }
                if ([string]::IsNullOrWhiteSpace($installDir)) {
                    try {
                        $installDir = Split-Path -Parent $exe
                    } catch { $installDir = '' }
                }
                if ([string]$App.Id -ieq 'MetaBrainz.Picard' -and
                    (Test-Path -LiteralPath 'HKLM:\Software\MusicBrainz\Picard')) {
                    try {
                        $picardInstall = (Get-ItemProperty -LiteralPath 'HKLM:\\Software\\Musicbrainz\\Picard' -Name InstallDir -ErrorAction Stop).InstallDir
                        if (-not [string]::IsNullOrWhiteSpace([string]$picardInstall) -and
                            (Test-Path -LiteralPath ([string]$picardInstall) -PathType Container)) {
                            $installDir = [string]$picardInstall
                        }
                    } catch {}
                }

                # MusicBrainz Picard's Windows installer is NSIS-based. Its own
                # installer source explicitly launches uninst.exe with:
                #   /S _?=<original install directory>
                # Running the registry UninstallString unchanged opens the
                # interactive uninstaller and can leave this utility waiting.
                # Apply the same verified NSIS convention to uninst.exe entries.
                $isNsisUninstaller = ([IO.Path]::GetFileName($exe) -ieq 'uninst.exe')
                if (-not $isNsisUninstaller) {
                    # Some NSIS builds use uninstall.exe. Detect the NSIS marker
                    # before adding NSIS-only switches to avoid guessing.
                    try {
                        $probeLength = [int][Math]::Min((Get-Item -LiteralPath $exe -ErrorAction Stop).Length, 2097152)
                        if ($probeLength -gt 0) {
                            $stream = [IO.File]::OpenRead($exe)
                            try {
                                $buffer = New-Object byte[] $probeLength
                                [void]$stream.Read($buffer, 0, $probeLength)
                                $probeText = [Text.Encoding]::ASCII.GetString($buffer)
                                if ($probeText -match '(?i)Nullsoft Install System') { $isNsisUninstaller = $true }
                            } finally { $stream.Dispose() }
                        }
                    } catch {}
                }

                $uninstallArgsText = [string]$args
                if ($isNsisUninstaller) {
                    if ($uninstallArgsText -notmatch '(?i)(^|\s)/S(\s|$)') {
                        $uninstallArgsText = ($uninstallArgsText + ' /S').Trim()
                    }
                    if (-not [string]::IsNullOrWhiteSpace($installDir) -and $uninstallArgsText -notmatch '(?i)_\?=') {
                        $uninstallArgsText += (' _?="' + $installDir.TrimEnd('\') + '"')
                    }
                    $attempts.Add("Detected NSIS uninstaller; supplied silent mode and original install directory.")
                }

                $proc = Start-Process -FilePath $exe -ArgumentList $uninstallArgsText -PassThru -ErrorAction Stop
                $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
                try { $proc.Dispose() } catch {}
                if ($uninstallExitCode -in @(0,1641,3010)) {
                    return [pscustomobject]@{ Success=$true; Detail="Native uninstaller succeeded (exit $uninstallExitCode)." }
                }
                $attempts.Add("Native uninstaller returned exit code $uninstallExitCode")
            } catch { $attempts.Add("Native uninstaller error: $($_.Exception.Message)") }
        } else {
            $attempts.Add('Exact registry entry exists but has no usable uninstall command.')
        }
    } else {
        $attempts.Add('No exact DisplayName registry uninstall entry was found.')
    }

    # AppX/MSIX: exact package identity only. Do not remove packages by partial name.
    try {
        $appxIds = @([string]$App.Id, [string]$App.Name) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        $appxPackage = Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object {
            $pkg = $_
            foreach ($identity in $appxIds) {
                if ($pkg.Name -ieq $identity -or $pkg.PackageFamilyName -ieq $identity -or $pkg.PackageFullName -ieq $identity) { return $true }
            }
            return $false
        } | Select-Object -First 1
        if ($appxPackage) {
            try {
                if ($KeepData) {
                    $removeCommand = Get-Command Remove-AppxPackage -ErrorAction Stop
                    if (-not $removeCommand.Parameters.ContainsKey('PreserveApplicationData')) {
                        $attempts.Add('AppX package found, but this Windows version cannot preserve its application data.')
                    } else {
                        Remove-AppxPackage -Package ([string]$appxPackage.PackageFullName) -PreserveApplicationData -ErrorAction Stop
                        return [pscustomobject]@{ Success=$true; Detail='Exact AppX/MSIX package removed for current user; app data preservation requested.' }
                    }
                } else {
                    Remove-AppxPackage -Package ([string]$appxPackage.PackageFullName) -ErrorAction Stop
                    return [pscustomobject]@{ Success=$true; Detail='Exact AppX/MSIX package removed for current user.' }
                }
            } catch { $attempts.Add("AppX/MSIX uninstall error: $($_.Exception.Message)") }
        }
    } catch { $attempts.Add("AppX/MSIX detection error: $($_.Exception.Message)") }

    # Scoop: match an exact installed app directory, then invoke Scoop by that exact name.
    try {
        $scoopCandidates = @([string]$App.Name, [string]$App.Id, [string]$App.ChocoId) |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
            ForEach-Object { ($_ -replace '[^a-zA-Z0-9]','').ToLowerInvariant() } |
            Where-Object { $_.Length -ge 3 } | Select-Object -Unique
        $scoopRoots = @()
        if ($env:SCOOP) { $scoopRoots += $env:SCOOP }
        if ($env:SCOOP_GLOBAL) { $scoopRoots += $env:SCOOP_GLOBAL }
        if ($env:USERPROFILE) { $scoopRoots += (Join-Path $env:USERPROFILE 'scoop') }
        if ($env:ProgramData) { $scoopRoots += (Join-Path $env:ProgramData 'scoop') }
        $scoopAppName = $null
        foreach ($rootPath in @($scoopRoots | Select-Object -Unique)) {
            $appsPath = Join-Path $rootPath 'apps'
            if (-not (Test-Path -LiteralPath $appsPath -PathType Container)) { continue }
            foreach ($folder in @(Get-ChildItem -LiteralPath $appsPath -Directory -ErrorAction SilentlyContinue)) {
                $observed = ($folder.Name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
                if ($scoopCandidates -contains $observed) { $scoopAppName = [string]$folder.Name; break }
            }
            if ($scoopAppName) { break }
        }
        if ($scoopAppName) {
            $scoop = Get-Command scoop -ErrorAction SilentlyContinue
            if ($scoop) {
                $scoopArgs = @('uninstall', $scoopAppName)
                if ($Complete) { $scoopArgs += '--purge' }
                & $scoop.Source @scoopArgs 2>&1 | Out-Null
                $scoopExitCode = $LASTEXITCODE
                if ($scoopExitCode -eq 0) { return [pscustomobject]@{ Success=$true; Detail="Scoop removed exact app '$scoopAppName' (exit 0)." } }
                $attempts.Add("Scoop uninstall returned exit code $scoopExitCode for '$scoopAppName'.")
            } else { $attempts.Add('Scoop app folder matched, but the Scoop command is unavailable.') }
        }
    } catch { $attempts.Add("Scoop uninstall error: $($_.Exception.Message)") }

    # WinGet fallback is attempted even when a registry entry exists but its native
    # uninstaller failed. Use the catalog's exact package ID, never a fuzzy name.
    $winget = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($winget -and -not [string]::IsNullOrWhiteSpace([string]$App.Id)) {
        try {
            $wgArgs = @('uninstall','--id',[string]$App.Id,'--exact','--accept-source-agreements')
            if ($Complete) { $wgArgs += '--purge' }
            $wgArgs += @('--silent','--disable-interactivity')
            $proc = Start-Process -FilePath $winget.Source -ArgumentList $wgArgs -PassThru -WindowStyle Hidden -ErrorAction Stop
            $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
            try { $proc.Dispose() } catch {}
            if ($uninstallExitCode -in @(0,1641,3010)) { return [pscustomobject]@{ Success=$true; Detail="WinGet exact-ID uninstall succeeded (exit $uninstallExitCode)." } }
            $attempts.Add("WinGet exact-ID uninstall returned exit code $uninstallExitCode.")
        } catch { $attempts.Add("WinGet uninstall error: $($_.Exception.Message)") }
    }

    # Chocolatey exact package ID fallback.
    $choco = Get-Command choco.exe -ErrorAction SilentlyContinue
    if ($choco -and -not [string]::IsNullOrWhiteSpace([string]$App.ChocoId)) {
        try {
            $proc = Start-Process -FilePath $choco.Source -ArgumentList @('uninstall',[string]$App.ChocoId,'-y','--no-progress') -PassThru -WindowStyle Hidden -ErrorAction Stop
            $uninstallExitCode = Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name)
            try { $proc.Dispose() } catch {}
            if ($uninstallExitCode -in @(0,1641,3010)) { return [pscustomobject]@{ Success=$true; Detail="Chocolatey exact-ID uninstall succeeded (exit $uninstallExitCode)." } }
            $attempts.Add("Chocolatey uninstall returned exit code $uninstallExitCode.")
        } catch { $attempts.Add("Chocolatey uninstall error: $($_.Exception.Message)") }
    }

    return [pscustomobject]@{ Success=$false; Detail=('All supported exact uninstall methods failed or were unavailable: ' + ($attempts -join ' | ')) }
}

function Test-AMRInventoryIdentityRemoved {
    param($App)
    try {
        switch ([string]$App.UninstallMethod) {
            { $_ -in @('MSI','Registry') } {
                if ([string]::IsNullOrWhiteSpace([string]$App.RegistryKeyPath)) { return $false }
                return (-not (Test-Path -LiteralPath ([string]$App.RegistryKeyPath)))
            }
            'Portable' { return (-not (Test-Path -LiteralPath ([string]$App.PortableRootFolder) -PathType Container)) }
            'AppX' {
                $remaining = @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object { [string]$_.PackageFullName -ceq [string]$App.AppxPackageFullName })
                return ($remaining.Count -eq 0)
            }
            'WinGet' {
                $wg = Get-Command winget.exe -ErrorAction SilentlyContinue
                if (-not $wg) { return $false }
                $output = @(& $wg.Source list --id ([string]$App.WingetId) --exact --disable-interactivity 2>$null | ForEach-Object { [string]$_ }) -join "`n"
                return ($output -notmatch ('(?i)(?<![A-Za-z0-9_.-])' + [regex]::Escape([string]$App.WingetId) + '(?![A-Za-z0-9_.-])'))
            }
            'Chocolatey' {
                $roots=@(); if($env:ChocolateyInstall){$roots+=$env:ChocolateyInstall}; if($env:ProgramData){$roots+=(Join-Path $env:ProgramData 'chocolatey')}
                foreach($root in @($roots | Select-Object -Unique)){if(Test-Path -LiteralPath (Join-Path (Join-Path $root 'lib') ([string]$App.ChocoId)) -PathType Container){return $false}}
                return $true
            }
            'Scoop' {
                $roots=@(); if($env:SCOOP){$roots+=$env:SCOOP}; if($env:SCOOP_GLOBAL){$roots+=$env:SCOOP_GLOBAL}; if($env:USERPROFILE){$roots+=(Join-Path $env:USERPROFILE 'scoop')}; if($env:ProgramData){$roots+=(Join-Path $env:ProgramData 'scoop')}
                foreach($root in @($roots | Select-Object -Unique)){if(Test-Path -LiteralPath (Join-Path (Join-Path $root 'apps') ([string]$App.ScoopName)) -PathType Container){return $false}}
                return $true
            }
            default { return $false }
        }
    } catch { return $false }
}

function Invoke-AMRInventoryExactUninstall {
    param($App, [bool]$KeepData=$true, [bool]$Complete=$false)
    $attempts = New-Object System.Collections.Generic.List[string]
    switch ([string]$App.UninstallMethod) {
        'MSI' {
            $entry = $null
            try { $entry = Get-ItemProperty -LiteralPath ([string]$App.RegistryKeyPath) -ErrorAction Stop } catch { return [pscustomobject]@{Success=$false;Detail='Exact MSI registry record could not be reopened.'} }
            $quietProperty=$entry.PSObject.Properties['QuietUninstallString']; $uninstallProperty=$entry.PSObject.Properties['UninstallString']; $cmd=''; if($quietProperty){$cmd=[string]$quietProperty.Value}; if(-not $cmd -and $uninstallProperty){$cmd=[string]$uninstallProperty.Value}
            $childNameProperty=$entry.PSObject.Properties['PSChildName']; $childName=''; if($childNameProperty){$childName=[string]$childNameProperty.Value}
            $guid=$null; if($cmd -match '(?i)\{[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\}'){$guid=$Matches[0]}; if(-not $guid -and $childName -match '^\{[0-9a-fA-F-]{36}\}$'){$guid=$childName}
            if(-not $guid){return [pscustomobject]@{Success=$false;Detail='Exact MSI ProductCode is unavailable.'}}
            try{$args=@('/x',$guid,'/passive','/norestart');$proc=Start-Process -FilePath 'msiexec.exe' -ArgumentList $args -PassThru -ErrorAction Stop;$code=Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name);try{$proc.Dispose()}catch{};if($code -notin @(0,1641,3010)){return [pscustomobject]@{Success=$false;Detail=("Exact MSI ProductCode uninstall exit code: $code.")}}; Start-Sleep -Seconds 2; $verified=Test-AMRInventoryIdentityRemoved -App $App; return [pscustomobject]@{Success=$verified;Detail=$(if($verified){"Exact MSI registry identity disappeared after uninstall (exit $code)."}else{"MSI uninstaller exited $code, but the exact uninstall registry identity remains; success was not assumed."})}}catch{return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message}}
        }
        'Registry' {
            $entry=$null; try{$entry=Get-ItemProperty -LiteralPath ([string]$App.RegistryKeyPath) -ErrorAction Stop}catch{return [pscustomobject]@{Success=$false;Detail='Exact registry uninstall entry no longer exists.'}}
            $displayNameProperty=$entry.PSObject.Properties['DisplayName']; if(-not $displayNameProperty -or ([string]$displayNameProperty.Value).Trim() -ine ([string]$App.Name).Trim()){return [pscustomobject]@{Success=$false;Detail='Exact registry identity changed; refusing uninstall.'}}
            $quietProperty=$entry.PSObject.Properties['QuietUninstallString']; $uninstallProperty=$entry.PSObject.Properties['UninstallString']; $cmd=''; if($quietProperty){$cmd=[string]$quietProperty.Value}; if(-not $cmd -and $uninstallProperty){$cmd=[string]$uninstallProperty.Value}; if(-not $cmd){return [pscustomobject]@{Success=$false;Detail='No registered uninstall command.'}}
            if($cmd -match '^\s*"(?<exe>[^"]+)"\s*(?<args>.*)$'){$exe=$Matches.exe;$argText=[string]$Matches.args}elseif($cmd -match '^\s*(?<exe>.+?\.exe)\s*(?<args>.*)$'){$exe=$Matches.exe.Trim('"');$argText=[string]$Matches.args}else{return [pscustomobject]@{Success=$false;Detail='Uninstall command could not be parsed safely.'}}
            $exe=[Environment]::ExpandEnvironmentVariables($exe); $argText=[Environment]::ExpandEnvironmentVariables($argText)
            if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){return [pscustomobject]@{Success=$false;Detail='Registered uninstaller executable is missing.'}}
            try {
                if([IO.Path]::GetFileName($exe) -ieq 'msiexec.exe'){
                    $productCode=$null; if($argText -match '(?i)\{[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\}'){$productCode=$Matches[0]}
                    if(-not $productCode){return [pscustomobject]@{Success=$false;Detail='MSI command did not contain an exact ProductCode; refusing to run a possibly modifying command.'}}
                    $exe='msiexec.exe'; $argText=('/x {0} /passive /norestart' -f $productCode)
                } else {
                    $isNsis=([IO.Path]::GetFileName($exe) -ieq 'uninst.exe')
                    if(-not $isNsis){try{$probe=[IO.File]::ReadAllBytes($exe);$probeLength=[Math]::Min($probe.Length,2097152);if($probeLength -gt 0){$probeText=[Text.Encoding]::ASCII.GetString($probe,0,$probeLength);if($probeText -match '(?i)Nullsoft Install System'){$isNsis=$true}}}catch{}}
                    if($isNsis -and $argText -notmatch '(?i)(^|\s)/S(\s|$)'){$argText=($argText+' /S').Trim()}
                    $installDir=[string]$App.InstallLocation
                    if($isNsis -and $installDir -and $argText -notmatch '(?i)_\?='){$argText+=(' _?="'+$installDir.TrimEnd('\')+'"')}
                }
                $proc=Start-Process -FilePath $exe -ArgumentList $argText -PassThru -ErrorAction Stop
                $code=Wait-AMRUninstallProcess -Process $proc -AppName ([string]$App.Name); try{$proc.Dispose()}catch{}
                if($code -notin @(0,1641,3010)){return [pscustomobject]@{Success=$false;Detail=("Exact registered uninstaller exit code: $code.")}}
                Start-Sleep -Seconds 2; $verified=Test-AMRInventoryIdentityRemoved -App $App
                return [pscustomobject]@{Success=$verified;Detail=$(if($verified){"Exact registry uninstall identity disappeared (exit $code)."}else{"Uninstaller exited $code, but the exact registry identity remains; success was not assumed."})}
            } catch { return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message} }
        }
        'Portable' {
            try {
                $root=[IO.Path]::GetFullPath([string]$App.PortableRootFolder).TrimEnd('\')
                $exe=[IO.Path]::GetFullPath([string]$App.PortableExecutablePath)
                $allowed=$false
                $portableAllowedRoots=@(); if($env:USERPROFILE){$portableAllowedRoots+=(Join-Path $env:USERPROFILE 'PortableApps')}; if($env:ProgramData){$portableAllowedRoots+=(Join-Path $env:ProgramData 'PortableApps')}; $portableAllowedRoots+='C:\PortableApps'
                foreach($allowedRoot in $portableAllowedRoots){try{$prefix=[IO.Path]::GetFullPath($allowedRoot).TrimEnd('\')+'\';if(($root+'\').StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){$allowed=$true;break}}catch{}}
                if(-not $allowed -or -not $root -or -not $exe.StartsWith(($root+'\'),[StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path -LiteralPath $exe -PathType Leaf)){return [pscustomobject]@{Success=$false;Detail='Portable app root failed exact path safety checks; no files were removed.'}}
                $rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop
                if(($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){return [pscustomobject]@{Success=$false;Detail='Portable app folder is a reparse point/junction; deletion is blocked.'}}
                $confirmPortable=Show-AMRMessageGlass ("This portable app is stored in its own folder. AMR will permanently delete only this exact folder and its contents:`n`n$root`n`nShortcuts outside the folder and other user files will not be removed. Continue?") 'Confirm Portable App Removal' YesNo Warning
                if($confirmPortable -ne [System.Windows.MessageBoxResult]::Yes){return [pscustomobject]@{Success=$false;Detail='Portable app removal was cancelled.'}}
                Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction Stop
                Start-Sleep -Milliseconds 500
                $verified=Test-AMRInventoryIdentityRemoved -App $App
                return [pscustomobject]@{Success=$verified;Detail=$(if($verified){'Exact portable application folder was removed.'}else{'Portable folder still exists after the removal attempt.'})}
            } catch { return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message} }
        }
        'AppX' {
            try{$pkg=Get-AppxPackage -PackageTypeFilter Main,Framework,Resource,Bundle -ErrorAction SilentlyContinue | Where-Object {$_.PackageFullName -ceq [string]$App.AppxPackageFullName} | Select-Object -First 1;if(-not $pkg){return [pscustomobject]@{Success=$false;Detail='Exact AppX package is no longer registered for the current user.'}};if($KeepData){$cmd=Get-Command Remove-AppxPackage -ErrorAction Stop;if($cmd.Parameters.ContainsKey('PreserveApplicationData')){Remove-AppxPackage -Package ([string]$pkg.PackageFullName) -PreserveApplicationData -ErrorAction Stop}else{return [pscustomobject]@{Success=$false;Detail='This Windows version cannot request AppX data preservation; no removal was performed.'}}}else{Remove-AppxPackage -Package ([string]$pkg.PackageFullName) -ErrorAction Stop};Start-Sleep -Seconds 2; $verified=Test-AMRInventoryIdentityRemoved -App $App; return [pscustomobject]@{Success=$verified;Detail=$(if($verified){'Exact current-user AppX package is no longer registered.'}else{'AppX removal command completed, but the exact package remains registered.'})}}catch{return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message}}
        }
        'WinGet' {try{$wg=Get-Command winget.exe -ErrorAction Stop;$p=Start-Process -FilePath $wg.Source -ArgumentList @('uninstall','--id',[string]$App.WingetId,'--exact','--accept-source-agreements','--disable-interactivity') -PassThru -WindowStyle Hidden -ErrorAction Stop;$c=Wait-AMRUninstallProcess -Process $p -AppName ([string]$App.Name);try{$p.Dispose()}catch{};if($c -notin @(0,1641,3010)){return [pscustomobject]@{Success=$false;Detail=("WinGet exact-ID uninstall exit code: $c.")}}; Start-Sleep -Seconds 2; $verified=Test-AMRInventoryIdentityRemoved -App $App; return [pscustomobject]@{Success=$verified;Detail=$(if($verified){"WinGet exact ID no longer appears installed (exit $c)."}else{"WinGet exited $c, but the exact package ID is still listed; success was not assumed."})}}catch{return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message}}}
        'Chocolatey' {try{$ch=Get-Command choco.exe -ErrorAction Stop;$p=Start-Process -FilePath $ch.Source -ArgumentList @('uninstall',[string]$App.ChocoId,'-y','--no-progress') -PassThru -WindowStyle Hidden -ErrorAction Stop;$c=Wait-AMRUninstallProcess -Process $p -AppName ([string]$App.Name);try{$p.Dispose()}catch{};if($c -ne 0){return [pscustomobject]@{Success=$false;Detail=("Chocolatey exact-ID uninstall exit code: $c.")}}; Start-Sleep -Seconds 2; $verified=Test-AMRInventoryIdentityRemoved -App $App; return [pscustomobject]@{Success=$verified;Detail=$(if($verified){"Chocolatey exact package folder is gone (exit $c)."}else{"Chocolatey exited $c, but its exact package folder remains."})}}catch{return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message}}}
        'Scoop' {try{$sc=Get-Command scoop -ErrorAction Stop;& $sc.Source uninstall ([string]$App.ScoopName) 2>&1 | Out-Null;$c=$LASTEXITCODE;if($c -ne 0){return [pscustomobject]@{Success=$false;Detail=("Scoop exact-name uninstall exit code: $c.")}}; Start-Sleep -Seconds 2; $verified=Test-AMRInventoryIdentityRemoved -App $App; return [pscustomobject]@{Success=$verified;Detail=$(if($verified){"Scoop exact app folder is gone (exit $c)."}else{"Scoop exited $c, but its exact app folder remains."})}}catch{return [pscustomobject]@{Success=$false;Detail=$_.Exception.Message}}}
        default {return [pscustomobject]@{Success=$false;Detail='No verified uninstall method is available.'}}
    }
}

function Invoke-AMRSelectedUninstall {
    if ($script:InstallRunning) { Show-AMRMessageGlass 'Another software operation is currently running.' 'AMR Uninstall' OK Warning | Out-Null; return }
    if (-not $script:ShowInstalledOnly) { Show-AMRMessageGlass 'Switch to Show Installed before using Uninstall.' 'AMR Uninstall' OK Warning | Out-Null; return }
    $selected = @($script:InstalledAppsInventory | Where-Object { $_.IsSelected -eq $true -and $_.IsInstalled -eq $true })
    if ($selected.Count -eq 0) { Show-AMRMessageGlass 'Select one or more detected installed applications first.' 'Selection Required' OK Warning | Out-Null; return }
    $unsupported = @($selected | Where-Object { -not $_.CanUninstall })
    if ($unsupported.Count -gt 0) {
        $unsupportedNames = @($unsupported | ForEach-Object { '• ' + $_.Name + ': ' + $_.UninstallReason }) -join "`n"
        Show-AMRMessageGlass ("These selected items do not have a verified uninstall method and will be skipped:`n`n$unsupportedNames") 'Uninstall Not Available' OK Warning | Out-Null
        $selected = @($selected | Where-Object { $_.CanUninstall })
        if ($selected.Count -eq 0) { return }
    }
    $portableSelected = @($selected | Where-Object { $_.IsPortable -and $_.CanUninstall })
    if ($portableSelected.Count -gt 0) {
        $portableNames = @($portableSelected | ForEach-Object { '• ' + $_.Name + ' — ' + $_.PortableRootFolder }) -join "`n"
        $portableAck = Show-AMRMessageGlass ("Portable applications are files rather than registered installations. Removing them deletes their exact app folder even when Keep Data is selected. Each folder will be shown for a separate confirmation:`n`n$portableNames`n`nContinue?") 'Portable Apps Selected' YesNo Warning
        if ($portableAck -ne [System.Windows.MessageBoxResult]::Yes) { return }
    }
    $choice = Show-AMRUninstallChoice -ApplicationNames @($selected | ForEach-Object { [string]$_.Name })
    if ($choice -eq 'Cancel') { return }

    if ($choice -eq 'Complete') {
        $preview = "AMR will run the selected application's exact native uninstall method. In this build, AMR will not independently delete folders, user profiles, settings, shared data, or registry metadata. Any cleanup performed by the vendor's own uninstaller is controlled by that uninstaller. Continue?"
        $confirm = Show-AMRMessageGlass $preview 'Confirm Complete Uninstall' YesNo Warning
        if ($confirm -ne [System.Windows.MessageBoxResult]::Yes) { return }
    } else {
        $confirm = Show-AMRMessageGlass ("Uninstall the following application(s)? Registered apps use their native uninstaller. Portable apps are removed by deleting only their confirmed PortableApps folder, even in this mode.`n`n" + (($selected | ForEach-Object { '• ' + $_.Name }) -join "`n")) 'Confirm Uninstall' YesNo Warning
        if ($confirm -ne [System.Windows.MessageBoxResult]::Yes) { return }
    }

    Set-AMRInstallButtonsEnabled -Enabled $false
    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 0
    $script:ProgressText.Text = "Uninstall queued: 0% (0/$($selected.Count) applications completed)."
    $success = 0; $failed = 0
    try {
        for ($i=0; $i -lt $selected.Count; $i++) {
            $app = $selected[$i]
            $script:ProgressBar.IsIndeterminate = $true
            $completedBefore = [math]::Round(($i / $selected.Count) * 100)
            $script:ProgressText.Text = "Uninstalling $($app.Name)... ($completedBefore% completed; current app in progress)"
            Write-AMRLog "Starting uninstall for '$($app.Name)' (mode: $choice)." INFO Software
            try {
                $result = Invoke-AMRInventoryExactUninstall -App $app -KeepData:($choice -eq 'UninstallOnly') -Complete:($choice -eq 'Complete')
                if ($result.Success) {
                    $success++
                    Write-AMRLog "Uninstall succeeded for '$($app.Name)': $($result.Detail)" SUCCESS Software
                    if ($choice -eq 'Complete') { Write-AMRLog 'Complete mode delegated cleanup only to the vendor native uninstaller; AMR performed no additional file deletion.' INFO Software }
                } else { $failed++; Write-AMRLog "Uninstall not completed for '$($app.Name)': $($result.Detail)" WARNING Software }
            } catch { $failed++; Write-AMRLog "Uninstall failed for '$($app.Name)': $($_.Exception.Message)" ERROR Software }
            $script:ProgressBar.IsIndeterminate = $false
            $script:ProgressBar.Value = [math]::Round((($i+1)/$selected.Count)*100)
            $script:ProgressText.Text = "Uninstall progress: $([int]$script:ProgressBar.Value)% ($($i+1)/$($selected.Count) applications completed)."
        }
    } finally {
        $script:ProgressBar.IsIndeterminate = $false
        Set-AMRInstallButtonsEnabled -Enabled $true
        try { Start-AMRInstalledCatalogScan -Refresh -ShowWhenReady:([bool]$script:ShowInstalledOnly) } catch { Write-AMRLog "Could not schedule the post-uninstall inventory refresh: $($_.Exception.Message)" WARNING Software }
        $script:AppsView.Refresh()
        foreach ($app in $script:InstalledAppsInventory) { $app.IsSelected = $false }
        foreach ($app in $script:SoftwareCatalog) { $app.IsSelected = $false }
    }
    $script:ProgressBar.IsIndeterminate = $false
    $script:ProgressBar.Value = 100
    $script:ProgressText.Text = "Uninstall finished: $success succeeded, $failed failed."
    Show-AMRMessageGlass ("Uninstall summary`n`nSucceeded: $success`nFailed or unsupported: $failed`nAMR extra folders removed: 0 (safety mode)`n`nSome uninstallers may request a restart.") 'AMR Uninstall Summary' OK Information | Out-Null
}

