    }
    if ((C 'chkShowThisPCDesktop').IsChecked -eq $true) {
        $script:CurrentTweakName = [string](C 'chkShowThisPCDesktop').Content
        $script:CurrentTweakSource = 'Customize'
        if (Set-AMRRegistryKey -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" -Name "{20D04FE0-3AEA-1069-A2D8-08002B30309D}" -Value 0) { $appliedSuccessCount++; $needsExplorerRestart = $true }
    }
    if ((C 'chkShowRecycleBinDesktop').IsChecked -eq $true) {
        $script:CurrentTweakName = [string](C 'chkShowRecycleBinDesktop').Content
        $script:CurrentTweakSource = 'Customize'
        if (Set-AMRRegistryKey -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" -Name "{645FF040-5081-101B-9F08-00AA002F954E}" -Value 0) { $appliedSuccessCount++; $needsExplorerRestart = $true }
    }
    if ((C 'chkShowNetworkDesktop').IsChecked -eq $true) {
        $script:CurrentTweakName = [string](C 'chkShowNetworkDesktop').Content
        $script:CurrentTweakSource = 'Customize'
        if (Set-AMRRegistryKey -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" -Name "{F02C1A0D-BE21-4350-88B0-7367FC96EF3C}" -Value 0) { $appliedSuccessCount++; $needsExplorerRestart = $true }
    }
    if ((C 'chkShowUserFilesDesktop').IsChecked -eq $true) {
        $script:CurrentTweakName = [string](C 'chkShowUserFilesDesktop').Content
        $script:CurrentTweakSource = 'Customize'
        if (Set-AMRRegistryKey -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" -Name "{59031A47-3F72-44A7-89C5-5595FE6B30EE}" -Value 0) { $appliedSuccessCount++; $needsExplorerRestart = $true }
    }
    if ((C 'chkShowLibraries').IsChecked -eq $true) {
        $script:CurrentTweakName = [string](C 'chkShowLibraries').Content
        $script:CurrentTweakSource = 'Customize'
        if (Set-AMRRegistryKey -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ShowLibraries" -Value 1) { $appliedSuccessCount++; $needsExplorerRestart = $true }
    }
    if ((C 'chkDisableHibernation').IsChecked -eq $true) {
        $script:CurrentTweakName = [string](C 'chkDisableHibernation').Content
        $script:CurrentTweakSource = 'Customize'
        Invoke-AMRAuditedHibernationOff -TweakName (Get-AMRTweakContext) | Out-Null
        Write-AMRLog "Disabled system hibernation to free disk space." SUCCESS Tweaks
        $appliedSuccessCount++
    }

    if ($appliedSuccessCount -gt 0) {
        if ($needsExplorerRestart) {
            Write-AMRLog "Restarting File Explorer to apply desktop & registry changes..." INFO Customize
            Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
        }
        Show-AMRMessageGlass "Applied $appliedSuccessCount customization tweak(s) successfully!" "Customization Complete" OK Information | Out-Null
    } else {
        Show-AMRMessageGlass "Please select at least one tweak to apply." "Notice" OK Warning | Out-Null
    }
    $script:CurrentTweakName = $null; $script:CurrentTweakSource = $null
})

