function Invoke-AMRVerifiedTempCleanup {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Label)

    if (-not (Test-Path -LiteralPath $Path -PathType Container -ErrorAction Stop)) {
        throw ("{0} folder does not exist or cannot be accessed: {1}" -f $Label,$Path)
    }

    $entries = @(Get-ChildItem -LiteralPath $Path -Force -ErrorAction Stop)
    $deleted = 0
    $failed = 0
    $failureDetails = @()
    foreach ($entry in $entries) {
        try {
            Remove-Item -LiteralPath $entry.FullName -Recurse -Force -ErrorAction Stop
            if (Test-Path -LiteralPath $entry.FullName -ErrorAction Stop) {
                throw 'Entry still exists after the delete request.'
            }
            $deleted++
        } catch {
            $failed++
            $detail = '{0}: {1}' -f $entry.FullName,$_.Exception.Message
            $failureDetails += $detail
            Write-AMRDiagnostic -Severity 'WARNING' -Area 'Cleanup' -Operation 'VerifiedTempDelete' -Message $detail -ErrorRecord $_ -Target $entry.FullName
        }
    }

    $result = [pscustomobject]@{ Path=$Path; Deleted=$deleted; Failed=$failed; FailureDetails=@($failureDetails) }
    if ($failed -gt 0) {
        throw ("{0} cleanup was partial. Verified deleted entries: {1}; failed/not verified: {2}. Details: {3}" -f $Label,$deleted,$failed,($failureDetails -join ' | '))
    }
    return $result
}

# A20: Tool Kit temp clear runs in an isolated worker (same verification and same messages as Invoke-AMRVerifiedTempCleanup).
$script:AMRTempCleanupBusy = $false
$script:AMRTempCleanupState = $null
$script:AMRTempCleanupWorkerScript = @'
param($Queue,$Path,$Label)
$ErrorActionPreference = 'Stop'
try { [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal } catch {}
$deleted = 0
$failed = 0
$failureDetails = New-Object 'System.Collections.Generic.List[string]'
$errorText = $null
try {
    if (-not (Test-Path -LiteralPath $Path -PathType Container -ErrorAction Stop)) {
        throw ("{0} folder does not exist or cannot be accessed: {1}" -f $Label,$Path)
    }
    $entries = @(Get-ChildItem -LiteralPath $Path -Force -ErrorAction Stop)
    foreach ($entry in $entries) {
        try {
            Remove-Item -LiteralPath $entry.FullName -Recurse -Force -ErrorAction Stop
            if (Test-Path -LiteralPath $entry.FullName -ErrorAction Stop) { throw 'Entry still exists after the delete request.' }
            $deleted++
        } catch {
            $failed++
            $failureDetails.Add(('{0}: {1}' -f $entry.FullName,$_.Exception.Message))
        }
    }
    if ($failed -gt 0) {
        throw ("{0} cleanup was partial. Verified deleted entries: {1}; failed/not verified: {2}. Details: {3}" -f $Label,$deleted,$failed,($failureDetails -join ' | '))
    }
} catch {
    $errorText = $_.Exception.Message
}
[pscustomobject]@{ AMRResult = $true; Deleted = $deleted; Failed = $failed; FailureDetails = $failureDetails.ToArray(); Error = $errorText }
'@

function Complete-AMRTempCleanup {
    param($Result)
    $state = $script:AMRTempCleanupState
    $script:AMRTempCleanupBusy = $false
    foreach ($detail in @($Result.FailureDetails | Select-Object -First 200)) {
        try { Write-AMRDiagnostic -Severity 'WARNING' -Area 'Cleanup' -Operation 'VerifiedTempDelete' -Message ([string]$detail) -Target ([string]$state.Path) } catch {}
    }
    if ($null -ne $Result.Error) {
        Show-AMRMessageGlass ("Could not complete the selected optimization: " + [string]$Result.Error) 'Optimize' OK Error | Out-Null
        Write-AMRLog ("Optimize tool failed [$($state.Key)]: " + [string]$Result.Error) ERROR Optimize
        return
    }
    Write-AMRLog ("{0} TEMP cleanup verified: {1} top-level entries deleted; {2} failed." -f $state.Kind,$Result.Deleted,$Result.Failed) SUCCESS Cleanup
    Show-AMRMessageGlass ("{0} temporary-file cleanup verified.`nDeleted entries: {1}`nFailed: {2}" -f $state.Kind,$Result.Deleted,$Result.Failed) 'Optimize' OK Information | Out-Null
}
function Fail-AMRTempCleanup {
    param([string]$Message)
    $state = $script:AMRTempCleanupState
    $script:AMRTempCleanupBusy = $false
    Show-AMRMessageGlass ("Could not complete the selected optimization: " + $Message) 'Optimize' OK Error | Out-Null
    Write-AMRLog ("Optimize tool failed [$($state.Key)]: " + $Message) ERROR Optimize
}
function Start-AMRAsyncTempCleanup {
    param([string]$Key,[string]$Kind,[string]$Path,[string]$Label)
    if ($script:AMRTempCleanupBusy) {
        Show-AMRMessageGlass 'A temporary-file cleanup is already running. Wait for it to finish.' 'Optimize' OK Information | Out-Null
        return
    }
    $script:AMRTempCleanupBusy = $true
    $script:AMRTempCleanupState = @{ Key = $Key; Kind = $Kind; Path = $Path }
    Write-AMRLog ("{0} TEMP cleanup started in the background." -f $Kind) INFO Cleanup
    $started = Start-AMRCleanupJob -Name ('TempCleanup' + $Key) -WorkerScript $script:AMRTempCleanupWorkerScript -WorkerArguments @($Path,$Label) -OnComplete 'Complete-AMRTempCleanup' -OnFailure 'Fail-AMRTempCleanup'
    if (-not $started) { Fail-AMRTempCleanup 'Could not start the isolated cleanup worker.' }
}

function Invoke-AMROptimizeTool {
 param([string]$Key)
 try {
  switch ($Key) {
   'TelemetryOff' { $script:CurrentTweakName='Disable telemetry service'; $script:CurrentTweakSource='Optimize'; Set-AMRAuditedService -Name 'DiagTrack' -StartupType Disabled -StopAfter $true | Out-Null; Set-AMRRegistryKey -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' -Name 'AllowTelemetry' -Value 0 | Out-Null; Show-AMRMessageGlass 'Diagnostic tracking restrictions were applied where supported. Some Windows editions may ignore policy settings.' 'Optimize' OK Information | Out-Null; return }
   'BackgroundOff' { Set-AMRRegistryKey -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' -Name 'GlobalUserDisabled' -Value 1 | Out-Null; Show-AMRMessageGlass 'Background app access was disabled for supported apps.' 'Optimize' OK Information | Out-Null; return }
   'CortanaOff' { Set-AMRRegistryKey -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search' -Name 'AllowCortana' -Value 0 | Out-Null; Show-AMRMessageGlass 'Cortana policy was applied where supported. This setting may not affect newer Windows Search versions.' 'Optimize' OK Information | Out-Null; return }
   'PowerPlan' { powercfg /getactivescheme; return }
   'Ultimate' { $p=(powercfg /list | Select-String 'Ultimate Performance').ToString(); if($p -match '([a-fA-F0-9-]{36})'){ powercfg /setactive $matches[1] } else { powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61; Show-AMRMessageGlass 'Ultimate Performance scheme was requested. Check Power Options to confirm availability.' 'Optimize' OK Information | Out-Null }; return }
   'PowerOptions' { Start-Process powercfg.cpl; return }
   'AdvancedPower' { Start-Process control.exe -ArgumentList '/name Microsoft.PowerOptions'; return }
   'EnergyReport' { $f=Join-Path ([Environment]::GetFolderPath('Desktop')) 'AMR-Energy-Report.html'; powercfg /energy /duration 60 /output $f; if(Test-Path $f){Start-Process $f}; return }
   'BatteryReport' { $f=Join-Path ([Environment]::GetFolderPath('Desktop')) 'AMR-Battery-Report.html'; powercfg /batteryreport /output $f; if(Test-Path $f){Start-Process $f}; return }
   'FastStartupOff' { Set-AMRRegistryKey -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -Name 'HiberbootEnabled' -Value 0 | Out-Null; Show-AMRMessageGlass 'Fast Startup was disabled. Restart Windows to apply.' 'Optimize' OK Information | Out-Null; return }
   'FastStartupOn' { Set-AMRRegistryKey -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -Name 'HiberbootEnabled' -Value 1 | Out-Null; return }
   'StartupApps' { Start-Process 'ms-settings:startupapps'; return }
   'TaskManager' { Start-Process taskmgr.exe; return }
   'Processes' { Get-Process | Sort-Object CPU -Descending | Select-Object -First 25 ProcessName,Id,CPU,WorkingSet64 | Out-GridView -Title 'Top Processes' ; return }
   'Services' { Start-Process services.msc; return }
   'StorageSettings' { Start-Process 'ms-settings:storagesense'; return }
   'CleanMgr' { Start-Process cleanmgr.exe; return }
   'TempSettings' { Start-Process 'ms-settings:temporaryfiles'; return }
   'OptimizeDrives' { Start-Process dfrgui.exe; return }
   'DriveSpace' { Get-PSDrive -PSProvider FileSystem | Select-Object Name,Root,@{N='UsedGB';E={[math]::Round($_.Used/1GB,2)}},@{N='FreeGB';E={[math]::Round($_.Free/1GB,2)}} | Out-GridView -Title 'Drive Space'; return }
   'ClearUserTemp' { if((Show-AMRMessageGlass 'Delete files from your current user TEMP folder? Files in use may remain.' 'Confirm Cleanup' YesNo Warning) -ne 'Yes'){return}; Start-AMRAsyncTempCleanup -Key 'ClearUserTemp' -Kind 'User' -Path $env:TEMP -Label 'User TEMP'; return }
   'ClearWindowsTemp' { if((Show-AMRMessageGlass 'Delete files from the Windows TEMP folder? Administrator rights may be required.' 'Confirm Cleanup' YesNo Warning) -ne 'Yes'){return}; Start-AMRAsyncTempCleanup -Key 'ClearWindowsTemp' -Kind 'Windows' -Path (Join-Path $env:windir 'Temp') -Label 'Windows TEMP'; return }
   'RecycleBin' { Start-Process explorer.exe -ArgumentList 'shell:RecycleBinFolder'; return }
   'InstalledApps' { Start-Process 'ms-settings:appsfeatures'; return }
   'DefaultApps' { Start-Process 'ms-settings:defaultapps'; return }
   'WindowsUpdate' { Start-Process 'ms-settings:windowsupdate'; return }
   'UpdateService' { Get-Service wuauserv | Format-List Name,Status,StartType | Out-GridView -Title 'Windows Update Service'; return }
   'RestartUpdate' { if((Show-AMRMessageGlass 'Restart the Windows Update service now?' 'Confirm Service Restart' YesNo Warning) -ne 'Yes'){return}; Restart-Service wuauserv -Force -ErrorAction Stop; return }
   'SFC' { if((Show-AMRMessageGlass 'Run System File Checker? This may take several minutes.' 'Confirm Repair' YesNo Warning) -ne 'Yes'){return}; Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoExit','-Command','sfc /scannow'; return }
   'DISMCheck' { Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoExit','-Command','DISM /Online /Cleanup-Image /CheckHealth'; return }
   'DISMRepair' { if((Show-AMRMessageGlass 'Run DISM RestoreHealth? This may take a while and use Windows Update.' 'Confirm Repair' YesNo Warning) -ne 'Yes'){return}; Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoExit','-Command','DISM /Online /Cleanup-Image /RestoreHealth'; return }
   'Troubleshoot' { Start-Process 'ms-settings:troubleshoot'; return }
   'SystemProtection' { Start-Process SystemPropertiesProtection.exe; return }
   'RestorePoint' { Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoExit','-Command','Checkpoint-Computer -Description "AMR Utility Restore Point" -RestorePointType MODIFY_SETTINGS'; return }
   'VisualEffects' { Start-Process SystemPropertiesPerformance.exe; return }
   'PerformanceOptions' { Start-Process SystemPropertiesPerformance.exe; return }
   'VirtualMemory' { Start-Process SystemPropertiesAdvanced.exe; return }
   'GraphicsSettings' { Start-Process 'ms-settings:display-advancedgraphics'; return }
   'GameMode' { Start-Process 'ms-settings:gaming-gamemode'; return }
   'BackgroundSettings' { Start-Process 'ms-settings:privacy-backgroundapps'; return }
   'StartupFolder' { Start-Process explorer.exe -ArgumentList 'shell:startup'; return }
   'NetworkStatus' { Start-Process 'ms-settings:network-status'; return }
   'InternetOptions' { Start-Process inetcpl.cpl; return }
   'FlushDNS' { Invoke-AMRNativeCommand -FilePath 'ipconfig.exe' -ArgumentList @('/flushdns') -Operation 'Flush DNS resolver cache' | Out-Null; Show-AMRMessageGlass 'DNS resolver cache flush command returned exit code 0.' 'Optimize' OK Information | Out-Null; return }
   'DeliveryOptimization' { Start-Process 'ms-settings:delivery-optimization'; return }
   'Privacy' { Start-Process 'ms-settings:privacy'; return }
   'SearchPrivacy' { Start-Process 'ms-settings:search-permissions'; return }
   'OptionalFeatures' { Start-Process optionalfeatures.exe; return }
   'Reliability' { Start-Process perfmon.exe -ArgumentList '/rel'; return }
   'ResourceMonitor' { Start-Process resmon.exe; return }
   'PerfReport' { Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoExit','-Command','perfmon /report'; return }
  }
 } catch { Show-AMRMessageGlass ("Could not complete the selected optimization: " + $_.Exception.Message) 'Optimize' OK Error | Out-Null; Write-AMRLog ("Optimize tool failed [$Key]: " + $_.Exception.Message) ERROR Optimize }
}
function Get-AMRToolInfoText {
 param([Parameter(Mandatory=$true)]$Tool,[string]$Area='Tool')
 $name=[string]$Tool.Name; $category=[string]$Tool.Category; $key=[string]$Tool.Key
 $detail = switch -Regex ($name) {
  '^Open ' { 'Opens the related Windows settings page or management console. It does not apply a change by itself; review the options in the window that opens.'; break }
  '^(Show|Display|List|Review|Check) ' { 'Reads the current Windows configuration or status and displays the result. This is intended for inspection; it does not intentionally change the setting.'; break }
  '^(Enable|Activate) ' { 'Changes the related Windows feature or protection setting to the enabled/performance state. Review the confirmation/result and note that administrator rights or a restart may be required.'; break }
  '^Disable ' { 'Changes the related Windows feature, service, policy, or startup behavior to a disabled state. This can affect Windows behavior; review the result and use the corresponding enable/restore option if needed.'; break }
  '^(Run|Start) ' { 'Starts the requested Windows scan, diagnostic, or maintenance operation. Some operations can take time and may require administrator privileges.'; break }
  '^(Generate|Export|Create) ' { 'Creates a diagnostic or status report using Windows information. The report is intended to help inspect the current system and does not itself optimize or repair Windows.'; break }
  '^(Clear|Flush|Reset|Renew|Release|Restart) ' { 'Runs a Windows maintenance or network command that clears, renews, restarts, or resets the named component. This can temporarily interrupt the related service or connection.'; break }
  '^Empty ' { 'Removes temporary files from the named temporary folder. Files in use may be skipped; review the result carefully because this action deletes data from that location.'; break }
  '^Ping ' { 'Sends a small set of network echo requests to the named destination and displays response time or packet-loss information.'; break }
  '^Trace ' { 'Runs a route trace to the named destination to show the network hops along the path. Some routers may not respond to trace probes.'; break }
  '^Test ' { 'Performs a connectivity or service test against the named destination and displays whether the requested connection succeeded.'; break }
  default { 'Runs the Windows utility associated with this item. The information below identifies its purpose; the main card performs the action.' }
 }
 $extra = switch ($key) {
  'TelemetryOff' { 'It targets the DiagTrack diagnostic service and the Windows diagnostic-data policy where supported.'; break }
  'BackgroundOff' { 'It changes the global background-app permission; availability and effect vary by Windows version.'; break }
  'Ultimate' { 'It requests the Ultimate Performance power scheme; Windows may not expose this scheme on every device.'; break }
  'FastStartupOff' { 'It disables Fast Startup by changing the hibernation/boot configuration.'; break }
  'FastStartupOn' { 'It enables Fast Startup through the Windows hibernation/boot configuration.'; break }
  'ClearUserTemp' { 'Only the current user temporary directory is targeted.'; break }
  'ClearWindowsTemp' { 'The Windows temporary directory is targeted; elevated permissions may be needed.'; break }
  'RestorePoint' { 'Windows System Protection must be enabled, and Windows may limit restore-point creation frequency.'; break }
  'DISMRepair' { 'DISM RestoreHealth may use Windows Update as a repair source and can take several minutes.'; break }
  'SFC' { 'SFC /scannow checks protected Windows system files and attempts to repair corrupted copies.'; break }
  'DefenderOn' { 'This asks Microsoft Defender Antivirus to turn real-time monitoring on.'; break }
  'FirewallOn' { 'This enables Windows Firewall for Domain, Private, and Public profiles.'; break }
  'ActivityOff' { 'This writes policy values that disable publishing and uploading Windows Activity History.'; break }
  'QuickScan' { 'A confirmation is shown before Microsoft Defender starts a quick scan.'; break }
  'FullScan' { 'A confirmation is shown before Microsoft Defender starts a full scan; it may take a long time.'; break }
  'DefenderUpdate' { 'This requests the latest Microsoft Defender security intelligence definitions.'; break }
  'ResetTCP' { 'This resets the TCP/IP stack; a restart may be needed before all effects take place.'; break }
  'ResetWinsock' { 'This resets the Winsock catalog and may affect network software until Windows is restarted.'; break }
  'ResetBoth' { 'This resets both TCP/IP and Winsock; expect to restart Windows to complete recovery.'; break }
  'ReleaseIP' { 'This releases the current DHCP IPv4 lease and can temporarily disconnect the device.'; break }
  'RenewIP' { 'This asks the DHCP server for a renewed IP lease.'; break }
  default { '' }
 }
 $text = '{0}  Category: {1}. {2}' -f $name,$category,$detail
 if($extra){$text += "`r`n`r`n$extra"}
 return $text
}
function New-AMRCompactToolCard {
 param([string]$Name,[string]$Key,[string]$Icon,[string]$Description,[scriptblock]$OnAction)
 $border=New-Object System.Windows.Controls.Border
 $border.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#202A35')
 $border.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#344455')
 $border.BorderThickness='1'; $border.CornerRadius='7'; $border.Padding='4'; $border.Margin='0,0,7,7'; $border.MinHeight=42
 # Match the Backup Center's premium card feedback: a restrained gold edge,
 # soft surface tint and a tiny layout-neutral lift. Every card owns its brushes.
 $border.RenderTransformOrigin=[System.Windows.Point]::new(0.5,0.5)
 $border.RenderTransform=[System.Windows.Media.TranslateTransform]::new()
 $border.Add_MouseEnter({
  try {
   $bg=$this.Background
   if($bg -is [System.Windows.Media.SolidColorBrush]){$a=New-Object System.Windows.Media.Animation.ColorAnimation;$a.To=[System.Windows.Media.Color]::FromRgb(39,54,68);$a.Duration=[TimeSpan]::FromMilliseconds(150);$bg.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$a)}
   $br=$this.BorderBrush
   if($br -is [System.Windows.Media.SolidColorBrush]){$a=New-Object System.Windows.Media.Animation.ColorAnimation;$a.To=[System.Windows.Media.Color]::FromRgb(184,154,98);$a.Duration=[TimeSpan]::FromMilliseconds(150);$br.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$a)}
   $m=New-Object System.Windows.Media.Animation.DoubleAnimation;$m.To=-1.5;$m.Duration=[TimeSpan]::FromMilliseconds(160);$m.EasingFunction=New-Object System.Windows.Media.Animation.QuadraticEase;$m.EasingFunction.EasingMode='EaseOut';$this.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$m)
  } catch {}
 }.GetNewClosure())
 $border.Add_MouseLeave({
  try {
   $bg=$this.Background
   if($bg -is [System.Windows.Media.SolidColorBrush]){$a=New-Object System.Windows.Media.Animation.ColorAnimation;$a.To=[System.Windows.Media.Color]::FromRgb(32,42,53);$a.Duration=[TimeSpan]::FromMilliseconds(170);$bg.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$a)}
   $br=$this.BorderBrush
   if($br -is [System.Windows.Media.SolidColorBrush]){$a=New-Object System.Windows.Media.Animation.ColorAnimation;$a.To=[System.Windows.Media.Color]::FromRgb(52,68,85);$a.Duration=[TimeSpan]::FromMilliseconds(170);$br.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$a)}
   $m=New-Object System.Windows.Media.Animation.DoubleAnimation;$m.To=0.0;$m.Duration=[TimeSpan]::FromMilliseconds(170);$m.EasingFunction=New-Object System.Windows.Media.Animation.QuadraticEase;$m.EasingFunction.EasingMode='EaseOut';$this.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$m)
  } catch {}
 }.GetNewClosure())
 $layout=New-Object System.Windows.Controls.Grid
 $colA=New-Object System.Windows.Controls.ColumnDefinition; $colA.Width=[System.Windows.GridLength]::new(1,[System.Windows.GridUnitType]::Star)
 $colB=New-Object System.Windows.Controls.ColumnDefinition; $colB.Width=[System.Windows.GridLength]::new(28)
 [void]$layout.ColumnDefinitions.Add($colA); [void]$layout.ColumnDefinitions.Add($colB)
 $action=New-Object System.Windows.Controls.Button; $action.Content=('{0}  {1}' -f $Icon,$Name); $action.Tag=$Key
 $action.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#263646'); $action.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#E7EDF3')
 $action.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#40566B'); $action.BorderThickness='0.7'; $action.Padding='7,5'; $action.FontSize=11; $action.FontWeight='SemiBold'; $action.MinHeight=32; $action.HorizontalContentAlignment='Left'; $action.VerticalContentAlignment='Center'
 # Keep hover surfaces silent: all explanatory text is available only from the gold info button.
 $action.ToolTip=$null; $action.Add_Click($OnAction)
 $action.Add_MouseEnter({
  try{$b=$this.Background;if($b -is [System.Windows.Media.SolidColorBrush]){$a=New-Object System.Windows.Media.Animation.ColorAnimation;$a.To=[System.Windows.Media.Color]::FromRgb(49,73,94);$a.Duration=[TimeSpan]::FromMilliseconds(140);$b.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$a)};$this.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#B89A62')}catch{}
 }.GetNewClosure())
 $action.Add_MouseLeave({
  try{$b=$this.Background;if($b -is [System.Windows.Media.SolidColorBrush]){$a=New-Object System.Windows.Media.Animation.ColorAnimation;$a.To=[System.Windows.Media.Color]::FromRgb(38,54,70);$a.Duration=[TimeSpan]::FromMilliseconds(170);$b.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$a)};$this.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#40566B')}catch{}
 }.GetNewClosure())
 [System.Windows.Controls.Grid]::SetColumn($action,0); [void]$layout.Children.Add($action)
 $info=New-Object System.Windows.Controls.Button; $info.Content='i'; $info.Width=23; $info.Height=23; $info.Padding='0'; $info.FontSize=12; $info.FontWeight='Bold'
 $info.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#B89A62'); $info.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#17212B')
 $info.BorderThickness='0'; $info.ToolTip=$null; $info.HorizontalAlignment='Center'; $info.VerticalAlignment='Center'
 $info.Tag=$Description; $info.Add_Click({ Show-AMRMessageGlass ([string]$this.Tag) 'Tool Information' OK Information | Out-Null }.GetNewClosure())
 $info.Add_MouseEnter({try{$this.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#D8BC83')}catch{}}.GetNewClosure())
 $info.Add_MouseLeave({try{$this.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#B89A62')}catch{}}.GetNewClosure())
 [System.Windows.Controls.Grid]::SetColumn($info,1); [void]$layout.Children.Add($info)
 $border.Child=$layout
 return $border
}

# A9: shared native card list for the Toolkit tabs (Optimize, Security, System, Networks, Utilities).
# One ItemsControl + one DataTemplate per tab replaces ~50 PowerShell-built cards per tab; hover/gold edge are XAML triggers (220 ms).
$script:AMRToolCards = @{}
$script:AMRToolCardSources = @{}
$script:AMRToolCardItems = @{}
function Get-AMRToolCardConfig {
    param([string]$Area)
    switch ($Area) {
        'Optimize'  { return @{ Grid='OptToolsGrid';  Search='OptSearchBox';  Filter='OptCategoryFilter';  Count='OptResultsCount';  Icon=[string][char]0x2699; Cols=4 } }
        'Security'  { return @{ Grid='SecToolsGrid';  Search='SecSearchBox';  Filter='SecCategoryFilter';  Count='SecResultsCount';  Icon=[System.Char]::ConvertFromUtf32(0x1F6E1); Cols=4 } }
        'System'    { return @{ Grid='SysToolsGrid';  Search='SysSearchBox';  Filter='SysCategoryFilter';  Count='SysResultsCount';  Icon=[string][char]0x2699; Cols=4 } }
        'Networks'  { return @{ Grid='NetToolsGrid';  Search='NetSearchBox';  Filter='NetCategoryFilter';  Count='NetResultsCount';  Icon=[System.Char]::ConvertFromUtf32(0x1F310); Cols=4 } }
        'Utilities' { return @{ Grid='UtilButtonsPanel'; Search='UtilSearchBox'; Filter='UtilCategoryFilter'; Count='UtilResultsCount'; Icon=[System.Char]::ConvertFromUtf32(0x1F6E0); Cols=4 } }
    }
    return $null
}

function Initialize-AMRToolCards {
    param([string]$Area)
    $cfg = Get-AMRToolCardConfig -Area $Area
    if (-not $cfg) { return $false }
    $oldGrid = C $cfg.Grid
    if (-not $oldGrid) { return $false }
    $cardsXaml = @"
<ItemsControl xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" x:Name="ToolCardsList" HorizontalAlignment="Stretch" VerticalAlignment="Top" Focusable="False" Tag="300">
  <ItemsControl.ItemsPanel><ItemsPanelTemplate><WrapPanel Orientation="Horizontal"/></ItemsPanelTemplate></ItemsControl.ItemsPanel>
  <ItemsControl.ItemTemplate>
    <DataTemplate>
      <Border x:Name="CardRoot" Width="{Binding Tag, RelativeSource={RelativeSource AncestorType={x:Type ItemsControl}}}" Height="68" Margin="0,0,10,10" CornerRadius="12" BorderThickness="1" BorderBrush="#43576C" SnapsToDevicePixels="True" RenderTransformOrigin="0.5,0.5">
        <Border.RenderTransform><TranslateTransform Y="0"/></Border.RenderTransform>
        <Border.Background>
          <LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#F0263646" Offset="0"/><GradientStop Color="#F01B2531" Offset="1"/></LinearGradientBrush>
        </Border.Background>
        <Grid>
          <Border x:Name="CardHover" CornerRadius="11" Opacity="0" IsHitTestVisible="False">
            <Border.Background>
              <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#EE35506B" Offset="0"/><GradientStop Color="#EE27394D" Offset="1"/></LinearGradientBrush>
            </Border.Background>
          </Border>
          <Border x:Name="CardEdge" CornerRadius="12" Margin="-1" BorderThickness="1.2" BorderBrush="#FFB89A62" Opacity="0" IsHitTestVisible="False"/>
          <Border CornerRadius="11,11,0,0" Margin="1,1,1,0" Height="16" VerticalAlignment="Top" IsHitTestVisible="False">
            <Border.Background>
              <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#1EFFFFFF" Offset="0"/><GradientStop Color="#00FFFFFF" Offset="1"/></LinearGradientBrush>
            </Border.Background>
          </Border>
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="40"/></Grid.ColumnDefinitions>
            <Button x:Name="ToolRunBtn" Grid.Column="0" Tag="{Binding Id}" Background="Transparent" BorderThickness="0" Padding="0" Cursor="Hand" FocusVisualStyle="{x:Null}" HorizontalContentAlignment="Stretch">
              <Button.Template>
                <ControlTemplate TargetType="{x:Type Button}"><Border Background="Transparent" CornerRadius="11"><ContentPresenter/></Border></ControlTemplate>
              </Button.Template>
              <Grid Margin="10,0,4,0">
                <Grid.ColumnDefinitions><ColumnDefinition Width="42"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                <Border Width="36" Height="36" CornerRadius="10" BorderThickness="1" BorderBrush="#99B89A62" HorizontalAlignment="Left" VerticalAlignment="Center">
                  <Border.Background>
                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FF35506B" Offset="0"/><GradientStop Color="#FF263646" Offset="1"/></LinearGradientBrush>
                  </Border.Background>
                  <TextBlock Text="{Binding Icon}" FontSize="16" HorizontalAlignment="Center" VerticalAlignment="Center" Foreground="#FFE2C68E"/>
                </Border>
                <StackPanel Grid.Column="1" VerticalAlignment="Center">
                  <TextBlock Text="{Binding Name}" FontSize="12" FontWeight="SemiBold" Foreground="#FFE7EDF3" TextWrapping="Wrap" TextTrimming="CharacterEllipsis" MaxHeight="32"/>
                  <TextBlock Text="{Binding Category}" FontSize="10" Foreground="#FFB89A62" Margin="0,2,0,0"/>
                </StackPanel>
              </Grid>
            </Button>
            <Button x:Name="ToolInfoBtn" Grid.Column="1" Tag="{Binding Id}" Width="24" Height="24" HorizontalAlignment="Center" VerticalAlignment="Center" Cursor="Hand" FocusVisualStyle="{x:Null}" ToolTip="About this tool">
              <Button.Template>
                <ControlTemplate TargetType="{x:Type Button}">
                  <Border x:Name="InfoFace" CornerRadius="12" BorderThickness="1" BorderBrush="#FFE2C68E" Background="#FFB89A62">
                    <TextBlock Text="i" FontSize="12" FontWeight="Bold" Foreground="#FF17212B" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                  </Border>
                  <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="InfoFace" Property="Background" Value="#FFE0C58C"/></Trigger>
                    <Trigger Property="IsPressed" Value="True"><Setter TargetName="InfoFace" Property="Background" Value="#FFA8884F"/></Trigger>
                  </ControlTemplate.Triggers>
                </ControlTemplate>
              </Button.Template>
            </Button>
          </Grid>
        </Grid>
      </Border>
      <DataTemplate.Triggers>
        <Trigger SourceName="CardRoot" Property="IsMouseOver" Value="True">
          <Trigger.EnterActions>
            <BeginStoryboard><Storyboard>
              <DoubleAnimation Storyboard.TargetName="CardHover" Storyboard.TargetProperty="Opacity" To="1" Duration="0:0:0.22"/>
              <DoubleAnimation Storyboard.TargetName="CardEdge" Storyboard.TargetProperty="Opacity" To="1" Duration="0:0:0.22"/>
              <DoubleAnimation Storyboard.TargetName="CardRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" To="-1.5" Duration="0:0:0.22"/>
            </Storyboard></BeginStoryboard>
          </Trigger.EnterActions>
          <Trigger.ExitActions>
            <BeginStoryboard><Storyboard>
              <DoubleAnimation Storyboard.TargetName="CardHover" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.22"/>
              <DoubleAnimation Storyboard.TargetName="CardEdge" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.22"/>
              <DoubleAnimation Storyboard.TargetName="CardRoot" Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" To="0" Duration="0:0:0.22"/>
            </Storyboard></BeginStoryboard>
          </Trigger.ExitActions>
        </Trigger>
      </DataTemplate.Triggers>
    </DataTemplate>
  </ItemsControl.ItemTemplate>
</ItemsControl>
"@
    try {
        $cardsControl = [Windows.Markup.XamlReader]::Parse($cardsXaml)
        $parentPanel = $oldGrid.Parent -as [System.Windows.Controls.Panel]
        if (-not $parentPanel) { throw ('The ' + $Area + ' list has no panel parent.') }
        $cardsControl.Resources['AMRToolArea'] = [string]$Area
        $cardsControl.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent,[System.Windows.RoutedEventHandler]{
            param($sender,$e)
            try {
                $clicked = $e.OriginalSource -as [System.Windows.Controls.Button]
                if (-not $clicked) { return }
                $areaName = [string]$sender.Resources['AMRToolArea']
                $index = -1
                if (-not [int]::TryParse([string]$clicked.Tag,[ref]$index)) { return }
                $source = @($script:AMRToolCardSources[$areaName])
                if ($index -lt 0 -or $index -ge $source.Count) { return }
                $tool = $source[$index]
                if ($clicked.Name -eq 'ToolRunBtn') {
                    $e.Handled = $true
                    switch ($areaName) {
                        'Optimize'  { Invoke-AMROptimizeTool -Key $tool.Key }
                        'Security'  { Invoke-AMRSecurityTool -Key $tool.Key }
                        'System'    { Invoke-AMRSystemTool -Key $tool.Key }
                        'Networks'  { Invoke-AMRNetworkTool -Key $tool.Key }
                        'Utilities' { $tool.Button.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent))) }
                    }
                } elseif ($clicked.Name -eq 'ToolInfoBtn') {
                    $e.Handled = $true
                    if ($areaName -eq 'Utilities') { Show-AMRMessageGlass ([string]$tool.Description) 'Utility Information' OK Information | Out-Null }
                    else { Show-AMRMessageGlass (Get-AMRToolInfoText -Tool $tool -Area $areaName) 'Tool Information' OK Information | Out-Null }
                }
            } catch { try { Write-AMRLog ('Toolkit card click failed: ' + $_.Exception.Message) ERROR System } catch {} }
        })
        $maxColumns = [int]$cfg.Cols
        $cardsControl.Resources['AMRToolMaxCols'] = $maxColumns
        $cardsControl.Add_SizeChanged({
            param($sender,$e)
            try {
                $newWidth = [double]$sender.ActualWidth
                if ($newWidth -lt 240) { return }
                $maxCols = [int]$sender.Resources['AMRToolMaxCols']
                $columns = [int][Math]::Max(1,[Math]::Min($maxCols,[Math]::Floor(($newWidth + 10) / 250)))
                $sender.Tag = [double][Math]::Max(220,[Math]::Floor(($newWidth - ($columns * 10)) / $columns))
            } catch { try { Write-AMRLog ('Toolkit card layout warning: ' + $_.Exception.Message) WARNING System } catch {} }
        })
        $insertAt = $parentPanel.Children.IndexOf($oldGrid) + 1
        [void]$parentPanel.Children.Insert($insertAt,$cardsControl)
        $oldGrid.Visibility = 'Collapsed'
        $script:AMRToolCards[$Area] = $cardsControl
        return $true
    } catch {
        $script:AMRToolCards.Remove($Area)
        try { Write-AMRDriverDiagnostic -Severity WARNING -Operation 'Toolkit' -Stage 'CardsFallback' -Message ('Toolkit ' + $Area + ' kept the original card builder: ' + $_.Exception.Message) -Source 'AMRToolCards' } catch {}
        return $false
    }
}

function Update-AMRToolCardsView {
    param([string]$Area)
    $cards = $script:AMRToolCards[$Area]
    if (-not $cards) { return $false }
    try {
        $cfg = Get-AMRToolCardConfig -Area $Area
        $searchBox = C $cfg.Search; $filterBox = C $cfg.Filter; $countText = C $cfg.Count
        $search = if ($searchBox) { [string]$searchBox.Text } else { '' }
        $selected = if ($filterBox) { $filterBox.SelectedItem } else { $null }
        $category = 'All Categories'
        if ($selected) { $category = ([string]$selected.Content -replace '^[^A-Za-z0-9]+\s*','') }
        $visibleItems = New-Object System.Collections.Generic.List[object]
        $total = 0
        $sourceList = @()
        switch ($Area) {
            'Optimize'  { $sourceList = @($script:AMROptimizeTools) }
            'Security'  { $sourceList = @($script:AMRSecurityTools) }
            'System'    { $sourceList = @($script:AMRSystemTools) }
            'Networks'  { $sourceList = @($script:AMRNetworkTools) }
            'Utilities' { $sourceList = @($script:UtilityCardEntries) }
        }
        $total = $sourceList.Count
        $script:AMRToolCardSources[$Area] = $sourceList
        for ($i = 0; $i -lt $sourceList.Count; $i++) {
            $tool = $sourceList[$i]
            if ($category -ne 'All Categories' -and [string]$tool.Category -ne $category) { continue }
            if ($Area -eq 'Optimize') {
                if (-not ((([string]$tool.Name + ' ' + [string]$tool.Keywords + ' ' + [string]$tool.Category)) -match [regex]::Escape($search))) { continue }
            } elseif ($Area -eq 'Utilities') {
                if (-not ([string]::IsNullOrWhiteSpace($search) -or ([string]$tool.Name).IndexOf($search,[System.StringComparison]::OrdinalIgnoreCase) -ge 0)) { continue }
            } else {
                $haystack = ('{0} {1} {2}' -f $tool.Name,$tool.Category,$tool.Keywords)
                if (-not [string]::IsNullOrWhiteSpace($search)) {
                    $matched = $false
                    try { $matched = ($haystack -like "*$search*") } catch { $matched = ($haystack.IndexOf($search,[System.StringComparison]::OrdinalIgnoreCase) -ge 0) }
                    if (-not $matched) { continue }
                }
            }
            $visibleItems.Add([pscustomobject]@{ Id = [string]$i; Name = [string]$tool.Name; Category = [string]$tool.Category; Icon = [string]$cfg.Icon })
        }
        $cards.ItemsSource = $visibleItems.ToArray()
        if ($countText) {
            switch ($Area) {
                'Optimize'  { $countText.Text = ('Showing {0} of {1} optimization tools' -f $visibleItems.Count,$total) }
                'Security'  { $countText.Text = ('{0} security tools shown' -f $visibleItems.Count) }
                'System'    { $countText.Text = ('{0} system tools shown' -f $visibleItems.Count) }
                'Networks'  { $countText.Text = ('{0} network tools shown' -f $visibleItems.Count) }
                'Utilities' { $countText.Text = ('{0} utilities shown' -f $visibleItems.Count) }
            }
        }
        return $true
    } catch {
        try { Write-AMRDriverDiagnostic -Severity WARNING -Operation 'Toolkit' -Stage 'CardsFallback' -Message ('Toolkit ' + $Area + ' list update failed, original builder used: ' + $_.Exception.Message) -Source 'Update-AMRToolCardsView' } catch {}
        try { $cards.ItemsSource = $null; $cards.Visibility = 'Collapsed'; $old = C (Get-AMRToolCardConfig -Area $Area).Grid; if ($old) { $old.Visibility = 'Visible' } } catch {}
        if ($Area -eq 'Utilities') { return $true }
        $script:AMRToolCards.Remove($Area)
        return $false
    }
}

function Update-AMROptimizeView {
 if (Update-AMRToolCardsView -Area 'Optimize') { return }
 $query = ''; if ($null -ne (C 'OptSearchBox')) { $query = (C 'OptSearchBox').Text }
 $category = 'All Categories'; if ($null -ne (C 'OptCategoryFilter') -and (C 'OptCategoryFilter').SelectedItem) { $category = ([string](C 'OptCategoryFilter').SelectedItem.Content) -replace '^⚙️\s*','' }
 $grid = C 'OptToolsGrid'; if ($null -eq $grid) { return }; $grid.Children.Clear()
 $items = @($script:AMROptimizeTools | Where-Object { ($category -eq 'All Categories' -or $_.Category -eq $category) -and (($_.Name + ' ' + $_.Keywords + ' ' + $_.Category) -match [regex]::Escape($query)) })
 foreach ($tool in $items) { $info=Get-AMRToolInfoText -Tool $tool -Area 'Optimize'; $card=New-AMRCompactToolCard -Name $tool.Name -Key $tool.Key -Icon '⚙' -Description $info -OnAction ({ Invoke-AMROptimizeTool -Key $tool.Key }.GetNewClosure()); [void]$grid.Children.Add($card) }
 (C 'OptResultsCount').Text = "Showing $($items.Count) of $($script:AMROptimizeTools.Count) optimization tools"
}
(C 'OptSearchBox').Add_TextChanged({ Update-AMROptimizeView })
(C 'OptCategoryFilter').Add_SelectionChanged({ Update-AMROptimizeView })
[void](Initialize-AMRToolCards -Area 'Optimize')
Add-AMRStartupMark 'L25710 before-UpdateOptimizeView'
Update-AMROptimizeView

