# CLEANUP ENGINE - scan/review/confirm workflow (no deletion during scan)
# V20: WER scans archived reports only; isolated roots have strict per-root limits and blocked roots are skipped safely.
# Only known rebuildable cache folders are included. DriverStore, Windows\Installer,
# AMD extraction roots (for example C:\AMD), user projects and browser profile data are excluded.
$script:CleanupScanResults = @{}
Add-AMRStartupMark 'L26823 before-CacheRootsInit'
$script:AMRAppCacheRoots = New-Object 'System.Collections.Generic.List[string]' # GPU shader-cache roots
$script:AMRApplicationCacheRoots = New-Object 'System.Collections.Generic.List[string]'
$script:AMRApplicationCacheInventory = New-Object 'System.Collections.Generic.List[object]'
$script:AMRDriverArtifactRoots = New-Object 'System.Collections.Generic.List[string]'

# Optional cleanup locations are only registered when they exist on this PC.
# A missing app/profile/cache folder is normal (app not installed or cache not created),
# not a scan failure. A folder that disappears after registration is still reported.
function Test-AMRCleanupDirectory {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    try {
        $attributes = [System.IO.File]::GetAttributes($Path)
        return (($attributes -band [System.IO.FileAttributes]::Directory) -ne 0)
    } catch [System.IO.DirectoryNotFoundException] { return $false }
      catch [System.IO.FileNotFoundException] { return $false }
      catch {
        # Keep inaccessible locations in the scan list so the scanner can report the real error.
        return $true
    }
}

function Write-AMRCleanupTrace {
    param([string]$Message,[string]$Level='INFO')
    try {
        $traceDirectory = Join-Path $env:ProgramData 'AMR-Utility\Logs'
        if (-not [string]::IsNullOrWhiteSpace([string]$script:LogDir)) { $traceDirectory = [string]$script:LogDir }
        if (-not (Test-Path -LiteralPath $traceDirectory -PathType Container)) {
            New-Item -ItemType Directory -Path $traceDirectory -Force -ErrorAction Stop | Out-Null
        }
        $traceFile = Join-Path $traceDirectory ("AMR_Cleanup_Trace_{0}.log" -f (Get-Date -Format 'yyyyMMdd'))
        $traceLine = '{0} [{1}] [CleanupTrace] {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'),$Level,$Message
        Add-Content -LiteralPath $traceFile -Value $traceLine -Encoding UTF8 -ErrorAction Stop
    } catch {}
}

function Get-AMRExistingCleanupRoots {
    param([string[]]$Roots)
    $existing = New-Object 'System.Collections.Generic.List[string]'
    foreach ($root in @($Roots)) {
        if ([string]::IsNullOrWhiteSpace([string]$root)) { continue }
        try {
            if (-not (Test-AMRCleanupDirectory -Path ([string]$root))) { continue }
            $full = [System.IO.Path]::GetFullPath([string]$root).TrimEnd([System.IO.Path]::DirectorySeparatorChar)
            if (-not [string]::IsNullOrWhiteSpace($full) -and -not $existing.Contains($full)) { $existing.Add($full) }
        } catch {
            try { Write-AMRLog ("Optional cleanup root skipped during discovery | Path={0} | Reason={1}" -f [string]$root,$_.Exception.Message) WARNING Cleanup } catch {}
            continue
        }
    }
    return $existing.ToArray()
}

# GPU discovery + conservative vendor cache allow-list.
# Adapter/board-vendor detection is informational; board partners do not get arbitrary
# cleanup paths. Only explicitly known, rebuildable cache folders are ever registered.
function Get-AMRGPUInventory {
    # Combine the legacy WMI video-controller view with the Windows PnP Display
    # class. Some OEM, hybrid and virtual adapters are visible in only one view.
    $rawAdapters = New-Object 'System.Collections.Generic.List[object]'
    try {
        foreach ($adapter in @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop)) {
            $rawAdapters.Add([pscustomobject]@{
                Name=[string]$adapter.Name; PnpDeviceId=[string]$adapter.PNPDeviceID
                Compatibility=[string]$adapter.AdapterCompatibility
                DriverVersion=[string]$adapter.DriverVersion; DriverDate=[string]$adapter.DriverDate
                Discovery='Win32_VideoController'
            })
        }
    } catch {
        try {
            foreach ($adapter in @(Get-WmiObject -Class Win32_VideoController -ErrorAction Stop)) {
                $rawAdapters.Add([pscustomobject]@{
                    Name=[string]$adapter.Name; PnpDeviceId=[string]$adapter.PNPDeviceID
                    Compatibility=[string]$adapter.AdapterCompatibility
                    DriverVersion=[string]$adapter.DriverVersion; DriverDate=[string]$adapter.DriverDate
                    Discovery='WMI fallback'
                })
            }
        } catch { Write-AMRLog ("GPU WMI inventory query failed: {0}" -f $_.Exception.Message) WARNING Cleanup }
    }

    # Get-PnpDevice is available on supported modern Windows versions, but keep
    # it optional so the utility remains compatible with older PowerShell setups.
    try {
        $getPnp = Get-Command Get-PnpDevice -ErrorAction SilentlyContinue
        if ($getPnp) {
            foreach ($device in @(Get-PnpDevice -Class Display -ErrorAction Stop)) {
                $instanceId = [string]$device.InstanceId
                if ([string]::IsNullOrWhiteSpace($instanceId)) { continue }
                $already = @($rawAdapters | Where-Object { $_.PnpDeviceId -and $_.PnpDeviceId.Equals($instanceId,[System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0
                if (-not $already) {
                    $rawAdapters.Add([pscustomobject]@{
                        Name=[string]$device.FriendlyName; PnpDeviceId=$instanceId
                        Compatibility=''; DriverVersion=''; DriverDate=''
                        Discovery='Get-PnpDevice Display'
                    })
                }
            }
        }
    } catch { Write-AMRLog ("GPU PnP Display inventory query failed: {0}" -f $_.Exception.Message) WARNING Cleanup }

    $vendorNames = @{
        '10DE'='NVIDIA'; '1002'='AMD'; '8086'='Intel'
        '17CB'='Qualcomm'; '13B5'='ARM'; '1010'='Imagination Technologies'
        '102B'='Matrox'; '5333'='S3 Graphics'; '1039'='SiS'; '1106'='VIA'
        '1A03'='ASPEED'; '15AD'='VMware'; '80EE'='Oracle VirtualBox'
        '1AF4'='VirtIO'; '1414'='Microsoft Display'; '1234'='QEMU'; '1B36'='Red Hat Virtual'
    }
    $boardNames = @{
        '1043'='ASUS'; '1462'='MSI'; '1458'='Gigabyte'; '1569'='AORUS'
        '3842'='EVGA'; '19DA'='Zotac'; '196E'='PNY'; '1545'='PNY'
        '1682'='XFX'; '1DA2'='Sapphire'; '1849'='ASRock'
        '1B4C'='KFA2'; '7377'='Colorful'; '17AA'='Lenovo'
        '1028'='Dell'; '103C'='HP'; '1EAE'='Gainward'
        '1BFD'='Xiaomi'; '1F4C'='GALAX'
    }

    $inventory = New-Object 'System.Collections.Generic.List[object]'
    $seenIds = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($adapter in $rawAdapters) {
        $pnp = [string]$adapter.PnpDeviceId
        $name = [string]$adapter.Name
        $compat = [string]$adapter.Compatibility
        $vendorId = ''; $deviceId = ''; $subsystemVendorId = ''
        if ($pnp -match '(?i)VEN_([0-9A-F]{4})') { $vendorId = $matches[1].ToUpperInvariant() }
        if ($pnp -match '(?i)DEV_([0-9A-F]{4})') { $deviceId = $matches[1].ToUpperInvariant() }
        if ($pnp -match '(?i)SUBSYS_[0-9A-F]{4}([0-9A-F]{4})') { $subsystemVendorId = $matches[1].ToUpperInvariant() }

        $vendor = if ($vendorNames.ContainsKey($vendorId)) { $vendorNames[$vendorId] }
                  elseif ($compat -match '(?i)NVIDIA') { 'NVIDIA' }
                  elseif ($compat -match '(?i)AMD|ATI|Advanced Micro Devices') { 'AMD' }
                  elseif ($compat -match '(?i)Intel') { 'Intel' }
                  elseif ($name -match '(?i)NVIDIA|GeForce|Quadro|RTX|GTX|Tesla') { 'NVIDIA' }
                  elseif ($name -match '(?i)AMD|Radeon|FirePro|Ryzen') { 'AMD' }
                  elseif ($name -match '(?i)Intel|Arc|UHD|Iris') { 'Intel' }
                  elseif ($vendorNames.ContainsKey($vendorId)) { $vendorNames[$vendorId] }
                  else { 'Unknown' }

        $family = if ($name -match '(?i)Quadro|RTX\s*A\d{3,4}|RTX\s*PRO') { 'NVIDIA Workstation (Quadro/RTX A/RTX PRO)' }
                  elseif ($name -match '(?i)RTX\s*\d{3,4}|GeForce\s*RTX') { 'NVIDIA GeForce RTX' }
                  elseif ($name -match '(?i)GTX\s*\d{3,4}|GeForce\s*GTX') { 'NVIDIA GeForce GTX' }
                  elseif ($name -match '(?i)Tesla') { 'NVIDIA Compute (Tesla)' }
                  elseif ($name -match '(?i)Radeon\s*RX|RX\s*\d{3,4}') { 'AMD Radeon RX' }
                  elseif ($name -match '(?i)Radeon\s*Pro|FirePro') { 'AMD Workstation (Radeon Pro/FirePro)' }
                  elseif ($name -match '(?i)Radeon.*Graphics|Ryzen.*Graphics|AMD.*Graphics') { 'AMD Integrated Radeon (Ryzen/APU)' }
                  elseif ($name -match '(?i)Arc\s*[AB]\d{3,4}') { 'Intel Arc' }
                  elseif ($name -match '(?i)Iris') { 'Intel Iris' }
                  elseif ($name -match '(?i)UHD|HD Graphics') { 'Intel UHD/HD' }
                  elseif ($name -match '(?i)Adreno') { 'Qualcomm Adreno' }
                  elseif ($name -match '(?i)Mali') { 'ARM Mali' }
                  elseif ($name -match '(?i)PowerVR') { 'Imagination PowerVR' }
                  elseif ($name -match '(?i)Matrox') { 'Matrox Graphics' }
                  elseif ($vendor -match '(?i)VMware|VirtualBox|VirtIO|QEMU|Red Hat|Microsoft Display') { 'Virtual / Emulated Display' }
                  elseif ($vendor -eq 'Unknown') { 'Unknown / Virtual / OEM' }
                  else { $vendor + ' Other' }

        $board = if ($boardNames.ContainsKey($subsystemVendorId)) { $boardNames[$subsystemVendorId] }
                 elseif ($subsystemVendorId) { 'Subsystem vendor ' + $subsystemVendorId }
                 else { 'Not reported' }
        $dedupeKey = if ($pnp) { $pnp } else { $vendor + '|' + $name }
        if (-not $seenIds.Add($dedupeKey)) { continue }
        $inventory.Add([pscustomobject]@{
            Name=$name; Vendor=$vendor; Family=$family; VendorId=$vendorId; DeviceId=$deviceId
            BoardPartner=$board; SubsystemVendorId=$subsystemVendorId
            DriverVersion=[string]$adapter.DriverVersion; DriverDate=[string]$adapter.DriverDate
            PnpDeviceId=$pnp; Discovery=[string]$adapter.Discovery
        })
    }
    return $inventory.ToArray()
}

function Add-AMRKnownGPUCacheRoot {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return }
    try {
        if (Test-AMRCleanupDirectory -Path $Path) {
            $full = [System.IO.Path]::GetFullPath($Path).TrimEnd([System.IO.Path]::DirectorySeparatorChar)
            if (-not $script:AMRAppCacheRoots.Contains($full)) { $script:AMRAppCacheRoots.Add($full) }
        }
    } catch {
        Write-AMRLog ("GPU cache candidate could not be registered: {0} | {1}" -f $Path,$_.Exception.Message) WARNING Cleanup
    }
}

# A24: the GPU inventory (CIM Win32_VideoController + Get-PnpDevice) was queried synchronously here during
# script load (about 0.5 s of the pre-window startup per the A22 startup marks). Its only consumer is the
# 'GPU detected' log lines below, so it now runs in a background worker after first render.
$script:AMRGPUInventory = @()

function Add-AMRGPUCacheCandidate {
    param([string]$Vendor,[string]$CacheType,[string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return }
    $state = 'Missing'
    try {
        $attributes = [System.IO.File]::GetAttributes($Path)
        if (($attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
            $state = 'Present'
            $full = [System.IO.Path]::GetFullPath($Path).TrimEnd([System.IO.Path]::DirectorySeparatorChar)
            if (-not $script:AMRAppCacheRoots.Contains($full)) { $script:AMRAppCacheRoots.Add($full) }
        } else { $state = 'Not a directory' }
    } catch [System.IO.DirectoryNotFoundException] { $state = 'Missing' }
      catch [System.IO.FileNotFoundException] { $state = 'Missing' }
      catch { $state = 'Inaccessible or unavailable'; Add-AMRKnownGPUCacheRoot -Path $Path }
    Write-AMRLog ("GPU cache candidate | Vendor={0} | Type={1} | Status={2} | Path={3}" -f $Vendor,$CacheType,$state,$Path) $(if ($state -eq 'Present') { 'INFO' } elseif ($state -eq 'Missing') { 'INFO' } else { 'WARNING' }) Cleanup
}

# Phase 6.11 | Vendor-agnostic discovery + isolated, killable root scanning + safety-first cleanup.
# Discovery is deliberately broader than the installed GPU inventory so stale caches
# left by replaced adapters/drivers can still be found. Only explicit, rebuildable cache
# directories are registered; no driver packages, installer roots, profile databases,
# cookies, saved sessions, downloads or user documents are included.

function Add-AMRAppCacheCandidate {
    param([string]$Application,[string]$CacheType,[string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return }
    $state = 'Missing'
    try {
        $attributes = [System.IO.File]::GetAttributes($Path)
        if (($attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
            $state = 'Present'
            $full = [System.IO.Path]::GetFullPath($Path).TrimEnd([System.IO.Path]::DirectorySeparatorChar)
            if (-not $script:AMRApplicationCacheRoots.Contains($full)) { $script:AMRApplicationCacheRoots.Add($full) }
        } else { $state = 'Not a directory' }
    } catch [System.IO.DirectoryNotFoundException] { $state = 'Missing' }
      catch [System.IO.FileNotFoundException] { $state = 'Missing' }
      catch {
        $state = 'Inaccessible or unavailable'
        if (-not $script:AMRApplicationCacheRoots.Contains([System.IO.Path]::GetFullPath($Path).TrimEnd([System.IO.Path]::DirectorySeparatorChar))) { $script:AMRApplicationCacheRoots.Add([System.IO.Path]::GetFullPath($Path).TrimEnd([System.IO.Path]::DirectorySeparatorChar)) }
      }
    Write-AMRLog ("Application cache candidate | App={0} | Type={1} | Status={2} | Path={3}" -f $Application,$CacheType,$state,$Path) $(if ($state -eq 'Present') { 'INFO' } elseif ($state -eq 'Missing') { 'INFO' } else { 'WARNING' }) Cleanup
}

# DirectX cache is Windows-managed and may be used by any GPU vendor.
Add-AMRStartupMark 'L27054 before-GpuCacheDiscoveryStart'
Add-AMRGPUCacheCandidate -Vendor 'Microsoft/DirectX' -CacheType 'DirectX Shader Cache' -Path (Join-Path $env:LOCALAPPDATA 'D3DSCache')

# Known vendor cache locations. These are checked regardless of the currently installed
# adapter so that safe leftovers from an older GPU/driver can be discovered as well.
$gpuCacheCandidates = @(
    [pscustomobject]@{Vendor='NVIDIA';Type='DirectX Shader Cache';Relative='NVIDIA\DXCache'},
    [pscustomobject]@{Vendor='NVIDIA';Type='OpenGL Shader Cache';Relative='NVIDIA\GLCache'},
    [pscustomobject]@{Vendor='NVIDIA';Type='Legacy Shader Cache';Relative='NVIDIA\NV_Cache'},
    [pscustomobject]@{Vendor='NVIDIA';Type='Compute Cache';Relative='NVIDIA\ComputeCache'},
    [pscustomobject]@{Vendor='NVIDIA';Type='Legacy NVIDIA Corporation Cache';Relative='NVIDIA Corporation\NV_Cache'},
    [pscustomobject]@{Vendor='AMD';Type='DirectX Shader Cache';Relative='AMD\DxCache'},
    [pscustomobject]@{Vendor='AMD';Type='DirectX Compiler Cache';Relative='AMD\DxcCache'},
    [pscustomobject]@{Vendor='AMD';Type='Vulkan Shader Cache';Relative='AMD\VkCache'},
    [pscustomobject]@{Vendor='AMD';Type='OpenGL Shader Cache';Relative='AMD\GLCache'},
    [pscustomobject]@{Vendor='AMD';Type='Legacy DirectX Shader Cache';Relative='AMD\DX9Cache'},
    [pscustomobject]@{Vendor='Intel';Type='Intel Shader Cache';Relative='Intel\ShaderCache'}
)
foreach ($candidate in $gpuCacheCandidates) {
    Add-AMRGPUCacheCandidate -Vendor $candidate.Vendor -CacheType $candidate.Type -Path (Join-Path $env:LOCALAPPDATA $candidate.Relative)
}

# Additional documented LocalLow shader-cache locations used by newer/alternate
# driver branches. These remain exact allow-listed cache paths, not broad vendor roots.
$localLowCacheCandidates = @(
    [pscustomobject]@{Vendor='NVIDIA';Type='Per-driver DirectX Shader Cache';Relative='NVIDIA\PerDriverVersion\DXCache'},
    [pscustomobject]@{Vendor='NVIDIA';Type='Legacy LocalLow DirectX Shader Cache';Relative='NVIDIA\DXCache'},
    [pscustomobject]@{Vendor='AMD';Type='LocalLow DirectX Shader Cache';Relative='AMD\DxCache'},
    [pscustomobject]@{Vendor='Intel';Type='Intel LocalLow Shader Cache';Relative='Intel\ShaderCache'}
)
foreach ($candidate in $localLowCacheCandidates) {
    $candidatePath = Join-Path (Join-Path $env:USERPROFILE 'AppData\LocalLow') $candidate.Relative
    Add-AMRGPUCacheCandidate -Vendor $candidate.Vendor -CacheType $candidate.Type -Path $candidatePath
}
if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
    Add-AMRGPUCacheCandidate -Vendor 'Intel' -CacheType 'Intel LocalLow Shader Cache' -Path (Join-Path $env:USERPROFILE 'AppData\LocalLow\Intel\ShaderCache')
}

# Inventory logging includes product family, raw PCI identity, board partner and source.
# Product family is descriptive only; it never determines arbitrary cleanup locations.
function Start-AMRGpuInventoryWorker {
    $runspace = $null; $ps = $null
    try {
        $funcText = (Get-Command Get-AMRGPUInventory -ErrorAction Stop).ScriptBlock.ToString()
        $workerText = "function Write-AMRLog { param(`$Message,`$Level,`$Area) }`nfunction Get-AMRGPUInventory {`n" + $funcText + "`n}`nGet-AMRGPUInventory"
        $runspace = [runspacefactory]::CreateRunspace()
        $runspace.ApartmentState = 'MTA'
        $runspace.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $runspace
        [void]$ps.AddScript($workerText,$true)
        $script:AMRGpuInvJob = [pscustomobject]@{ PowerShell = $ps; Runspace = $runspace; Async = $ps.BeginInvoke() }
        $script:AMRGpuInvTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:AMRGpuInvTimer.Interval = [TimeSpan]::FromMilliseconds(250)
        $script:AMRGpuInvTimer.Add_Tick({
            $job = $script:AMRGpuInvJob
            if (-not $job) { $script:AMRGpuInvTimer.Stop(); return }
            if (-not $job.Async.IsCompleted) { return }
            $script:AMRGpuInvTimer.Stop()
            $script:AMRGpuInvJob = $null
            $items = @()
            try { $items = @($job.PowerShell.EndInvoke($job.Async)) } catch { Write-AMRLog ('GPU inventory worker failed: ' + $_.Exception.Message) WARNING Cleanup }
            try { $job.PowerShell.Dispose() } catch {}
            try { $job.Runspace.Close(); $job.Runspace.Dispose() } catch {}
            $script:AMRGPUInventory = @($items | Where-Object { $null -ne $_ -and $_.PSObject.Properties['Vendor'] })
            foreach ($gpu in $script:AMRGPUInventory) {
                Write-AMRLog ("GPU detected | Name={0} | ChipVendor={1} | Family={2} | PCI Vendor ID={3} | PCI Device ID={4} | BoardPartner={5} | SubsystemVendorID={6} | Driver={7} | DriverDate={8} | Discovery={9}" -f $gpu.Name,$gpu.Vendor,$gpu.Family,$gpu.VendorId,$gpu.DeviceId,$gpu.BoardPartner,$gpu.SubsystemVendorId,$gpu.DriverVersion,$gpu.DriverDate,$gpu.Discovery) INFO Cleanup
            }
            if ($script:AMRGPUInventory.Count -eq 0) {
                Write-AMRLog 'GPU inventory returned no adapters. Known DirectX and vendor cache candidates were still checked safely.' WARNING Cleanup
            }
        })
        $script:AMRGpuInvTimer.Start()
    } catch {
        try { if ($ps) { $ps.Dispose() } } catch {}
        try { if ($runspace) { $runspace.Close(); $runspace.Dispose() } } catch {}
        $script:AMRGpuInvJob = $null
        Write-AMRLog ('Could not start the GPU inventory worker: ' + $_.Exception.Message) WARNING Cleanup
    }
}
$script:AMRGpuInvJob = $null
$script:AMRGpuInvTimer = $null
Add-AMRDeferredStartupAction -Name 'GpuInventory' -Action { Start-AMRGpuInventoryWorker }

Add-AMRStartupMark 'cleanup.beforeBrowserProfiles'
# Chromium-family browser caches. Enumerate every recognized profile folder (Default,
# Profile N, Guest/System Profile, Person N) instead of scanning Default only. Only cache
# subdirectories are candidates; cookies, Login Data, Web Data, bookmarks and sessions
# are never registered. Browser variants are optional and missing paths are normal.
$browserProfiles = @(
    [pscustomobject]@{ Name='Google Chrome'; Base=(Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data') },
    [pscustomobject]@{ Name='Google Chrome Beta'; Base=(Join-Path $env:LOCALAPPDATA 'Google\Chrome Beta\User Data') },
    [pscustomobject]@{ Name='Google Chrome Dev'; Base=(Join-Path $env:LOCALAPPDATA 'Google\Chrome Dev\User Data') },
    [pscustomobject]@{ Name='Google Chrome Canary'; Base=(Join-Path $env:LOCALAPPDATA 'Google\Chrome SxS\User Data') },
    [pscustomobject]@{ Name='Microsoft Edge'; Base=(Join-Path $env:LOCALAPPDATA 'Microsoft\Edge\User Data') },
    [pscustomobject]@{ Name='Microsoft Edge Beta'; Base=(Join-Path $env:LOCALAPPDATA 'Microsoft\Edge Beta\User Data') },
    [pscustomobject]@{ Name='Microsoft Edge Dev'; Base=(Join-Path $env:LOCALAPPDATA 'Microsoft\Edge Dev\User Data') },
    [pscustomobject]@{ Name='Microsoft Edge Canary'; Base=(Join-Path $env:LOCALAPPDATA 'Microsoft\Edge SxS\User Data') },
    [pscustomobject]@{ Name='Brave'; Base=(Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data') },
    [pscustomobject]@{ Name='Vivaldi'; Base=(Join-Path $env:LOCALAPPDATA 'Vivaldi\User Data') },
    [pscustomobject]@{ Name='Yandex Browser'; Base=(Join-Path $env:LOCALAPPDATA 'Yandex\YandexBrowser\User Data') },
    [pscustomobject]@{ Name='Chromium'; Base=(Join-Path $env:LOCALAPPDATA 'Chromium\User Data') }
)
$chromiumCacheNames = @('Cache\Cache_Data','Code Cache','GPUCache','DawnCache','GrShaderCache','ShaderCache','GraphiteDawnCache','DawnGraphiteCache','DawnWebGPUCache')
$chromiumSharedCacheNames = @('ShaderCache','GrShaderCache','GraphiteDawnCache','DawnGraphiteCache','DawnWebGPUCache')
$recognizedProfilePattern = '^(Default|Profile\s+\d+|Guest Profile|System Profile|Person\s+\d+)$'
foreach ($browser in $browserProfiles) {
    if (-not (Test-AMRCleanupDirectory -Path $browser.Base)) {
        Write-AMRLog ("Browser profile root missing | App={0} | Path={1}" -f $browser.Name,$browser.Base) INFO Cleanup
        continue
    }
    try {
        $profiles = @(Get-ChildItem -LiteralPath $browser.Base -Directory -Force -ErrorAction Stop | Where-Object { $_.Name -match $recognizedProfilePattern })
        foreach ($profile in $profiles) {
            foreach ($cacheName in $chromiumCacheNames) {
                $cachePath = Join-Path $profile.FullName $cacheName
                Add-AMRAppCacheCandidate -Application ($browser.Name + ' / ' + $profile.Name) -CacheType $cacheName -Path $cachePath
            }
        }
        foreach ($cacheName in $chromiumSharedCacheNames) {
            Add-AMRAppCacheCandidate -Application ($browser.Name + ' shared user-data cache') -CacheType $cacheName -Path (Join-Path $browser.Base $cacheName)
        }
        Write-AMRLog ("Browser profile discovery | App={0} | Profiles={1} | Base={2}" -f $browser.Name,$profiles.Count,$browser.Base) INFO Cleanup
    } catch {
        Write-AMRLog ("Browser profile discovery failed | App={0} | Base={1} | Error={2}" -f $browser.Name,$browser.Base,$_.Exception.Message) WARNING Cleanup
    }
}

# Opera Stable and Opera GX have a different profile/cache layout from Chrome/Edge.
# Check both Local and Roaming layouts used by different releases, but only exact
# cache directory names; never register the Opera profile root itself.
$operaVariants = @(
    [pscustomobject]@{Name='Opera Stable';Local=(Join-Path $env:LOCALAPPDATA 'Opera Software\Opera Stable');Roaming=(Join-Path $env:APPDATA 'Opera Software\Opera Stable')},
    [pscustomobject]@{Name='Opera GX';Local=(Join-Path $env:LOCALAPPDATA 'Opera Software\Opera GX Stable');Roaming=(Join-Path $env:APPDATA 'Opera Software\Opera GX Stable')}
)
$operaLocalCacheNames = @('Cache','Code Cache','GPUCache','DawnCache','GrShaderCache','ShaderCache','GraphiteDawnCache','DawnGraphiteCache','DawnWebGPUCache')
$operaProfileCacheNames = @('Cache','Cache\Cache_Data','Code Cache','GPUCache','DawnCache','GrShaderCache','ShaderCache','GraphiteDawnCache','DawnGraphiteCache','DawnWebGPUCache')
foreach ($opera in $operaVariants) {
    foreach ($cacheName in $operaLocalCacheNames) {
        Add-AMRAppCacheCandidate -Application $opera.Name -CacheType $cacheName -Path (Join-Path $opera.Local $cacheName)
    }
    foreach ($profileRoot in @($opera.Roaming,(Join-Path $opera.Roaming 'Default'))) {
        foreach ($cacheName in $operaProfileCacheNames) {
            Add-AMRAppCacheCandidate -Application ($opera.Name + ' profile') -CacheType $cacheName -Path (Join-Path $profileRoot $cacheName)
        }
    }
}

# Firefox stores profile metadata under Roaming on common installations, while its
# disposable HTTP cache may be under Local. Check both known roots and deduplicate paths.
$firefoxProfileRoots = @(
    (Join-Path $env:APPDATA 'Mozilla\Firefox\Profiles'),
    (Join-Path $env:LOCALAPPDATA 'Mozilla\Firefox\Profiles')
)
foreach ($firefoxProfiles in $firefoxProfileRoots) {
    if (-not (Test-AMRCleanupDirectory -Path $firefoxProfiles)) { continue }
    try {
        foreach ($profile in @(Get-ChildItem -LiteralPath $firefoxProfiles -Directory -Force -ErrorAction Stop)) {
            Add-AMRAppCacheCandidate -Application ('Mozilla Firefox / ' + $profile.Name) -CacheType 'HTTP cache entries' -Path (Join-Path $profile.FullName 'cache2\entries')
        }
        Write-AMRLog ("Firefox profile discovery completed | Root={0}" -f $firefoxProfiles) INFO Cleanup
    } catch {
        Write-AMRLog ("Firefox profile discovery failed | Root={0} | Error={1}" -f $firefoxProfiles,$_.Exception.Message) WARNING Cleanup
    }
}

# Common desktop apps: inspect only allow-listed, rebuildable cache directories.
# Detection uses uninstall metadata and known executable locations; a missing app is
# reported as Not installed and never treated as an error. User data, messages, media,
# downloads, credentials, profiles and project folders are intentionally excluded.
Add-AMRStartupMark 'cleanup.beforeAppDetect'
$uninstallDisplayNames = New-Object 'System.Collections.Generic.List[string]'
# A1: the uninstall-registry read and the AppX lookups run in a worker started at the top of the script (about 0.5 s of the pre-window startup in A24).
# Wait only if it is not finished; on any failure the original synchronous code below runs unchanged.
$cleanupDetectUsed = $false
try {
    $cleanupDetect = Complete-AMRStartupPrefetchWorker -Job $script:AMRCleanupDetectJob -WaitMs 20000
    $script:AMRCleanupDetectJob = $null
    $cleanupDetectItem = $null
    if ($cleanupDetect.Ok -and @($cleanupDetect.Items).Count -gt 0) { $cleanupDetectItem = @($cleanupDetect.Items)[0] }
    if ($null -ne $cleanupDetectItem -and $cleanupDetectItem.PSObject.Properties['DisplayNames'] -and $cleanupDetectItem.PSObject.Properties['Appx']) {
        foreach ($detectedName in @($cleanupDetectItem.DisplayNames)) { if (-not [string]::IsNullOrWhiteSpace([string]$detectedName)) { $uninstallDisplayNames.Add([string]$detectedName) } }
        $script:AMRCleanupAppxDetect = $cleanupDetectItem.Appx
        $cleanupDetectUsed = $true
        Write-AMRLog ('Cleanup app detection prefetch used: {0} display name(s); worker {1} ms (registry {2} ms); waited {3} ms on the startup path.' -f $uninstallDisplayNames.Count,$cleanupDetectItem.TotalMs,$cleanupDetectItem.RegistryMs,$cleanupDetect.WaitedMs) INFO Cleanup
    } else {
        Write-AMRLog ('Cleanup app detection prefetch not available (ok={0}, waited {1} ms); using the synchronous scan.' -f $cleanupDetect.Ok,$cleanupDetect.WaitedMs) WARNING Cleanup
    }
} catch { $cleanupDetectUsed = $false; $script:AMRCleanupAppxDetect = $null; $uninstallDisplayNames.Clear() }
Add-AMRStartupMark 'cleanup.appDetectPrefetch.applied'
$uninstallRegistryRoots = @(
    'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall',
    'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
    'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall'
)
if (-not $cleanupDetectUsed) {
foreach ($registryRoot in $uninstallRegistryRoots) {
    try {
        foreach ($subKey in @(Get-ChildItem -LiteralPath $registryRoot -ErrorAction SilentlyContinue)) {
            try {
                $entry = Get-ItemProperty -LiteralPath $subKey.PSPath -ErrorAction Stop
                if (-not [string]::IsNullOrWhiteSpace([string]$entry.DisplayName)) { $uninstallDisplayNames.Add([string]$entry.DisplayName) }
            } catch { }
        }
    } catch { }
}
}
Add-AMRStartupMark 'cleanup.uninstallRegistry.ready'
function Test-AMRKnownAppInstalled {
    param([string]$DisplayPattern,[string[]]$ExecutablePaths)
    $packageNames = @()
    if ($DisplayPattern -match 'Teams') { $packageNames += 'MSTeams' }
    if ($DisplayPattern -match 'Spotify') { $packageNames += 'SpotifyAB.SpotifyMusic' }
    if ($DisplayPattern -match 'Discord') { $packageNames += '*Discord*' }
    foreach ($packageName in $packageNames) {
        if ($null -ne $script:AMRCleanupAppxDetect -and $script:AMRCleanupAppxDetect.ContainsKey($packageName)) {
            if ([bool]$script:AMRCleanupAppxDetect[$packageName]) { return $true }
            continue
        }
        try { if (@(Get-AppxPackage -Name $packageName -ErrorAction SilentlyContinue).Count -gt 0) { return $true } } catch { }
    }
    foreach ($displayName in $uninstallDisplayNames) {
        if ($displayName -match $DisplayPattern) { return $true }
    }
    foreach ($exePath in @($ExecutablePaths)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$exePath)) {
            try { if (Test-Path -Path $exePath -PathType Leaf -ErrorAction SilentlyContinue) { return $true } } catch { }
        }
    }
    return $false
}
$appCacheDefinitions = @(
    [pscustomobject]@{Name='Discord';Pattern='(?i)^Discord';Executables=@((Join-Path $env:LOCALAPPDATA 'Discord\Update.exe'),(Join-Path $env:LOCALAPPDATA 'Discord\app-*\Discord.exe'));Caches=@([pscustomobject]@{Type='Application Cache';Path=(Join-Path $env:APPDATA 'discord\Cache')},[pscustomobject]@{Type='Code Cache';Path=(Join-Path $env:APPDATA 'discord\Code Cache')},[pscustomobject]@{Type='GPU Cache';Path=(Join-Path $env:APPDATA 'discord\GPUCache')})},
    [pscustomobject]@{Name='CapCut';Pattern='(?i)^CapCut';Executables=@((Join-Path $env:LOCALAPPDATA 'CapCut\Apps\CapCut.exe'),(Join-Path $env:LOCALAPPDATA 'CapCut\CapCut.exe'));Caches=@([pscustomobject]@{Type='Application Cache';Path=(Join-Path $env:LOCALAPPDATA 'CapCut\User Data\Cache')},[pscustomobject]@{Type='Code Cache';Path=(Join-Path $env:LOCALAPPDATA 'CapCut\User Data\Code Cache')},[pscustomobject]@{Type='GPU Cache';Path=(Join-Path $env:LOCALAPPDATA 'CapCut\User Data\GPUCache')})},
    [pscustomobject]@{Name='Spotify';Pattern='(?i)^Spotify';Executables=@((Join-Path $env:APPDATA 'Spotify\Spotify.exe'),(Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\Spotify.exe'));Caches=@([pscustomobject]@{Type='Browser Cache';Path=(Join-Path $env:LOCALAPPDATA 'Spotify\Browser\Cache')},[pscustomobject]@{Type='Code Cache';Path=(Join-Path $env:LOCALAPPDATA 'Spotify\Browser\Code Cache')},[pscustomobject]@{Type='GPU Cache';Path=(Join-Path $env:LOCALAPPDATA 'Spotify\GPUCache')})},
    [pscustomobject]@{Name='Microsoft Teams';Pattern='(?i)^Microsoft Teams|^Teams';Executables=@((Join-Path $env:LOCALAPPDATA 'Microsoft\Teams\current\Teams.exe'),(Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\ms-teams.exe'));Caches=@([pscustomobject]@{Type='Classic Teams Cache';Path=(Join-Path $env:APPDATA 'Microsoft\Teams\Cache')},[pscustomobject]@{Type='Classic Teams Code Cache';Path=(Join-Path $env:APPDATA 'Microsoft\Teams\Code Cache')},[pscustomobject]@{Type='Classic Teams GPU Cache';Path=(Join-Path $env:APPDATA 'Microsoft\Teams\GPUCache')},[pscustomobject]@{Type='New Teams Web Cache';Path=(Join-Path $env:LOCALAPPDATA 'Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams\EBWebView\Default\Cache')},[pscustomobject]@{Type='New Teams Code Cache';Path=(Join-Path $env:LOCALAPPDATA 'Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams\EBWebView\Default\Code Cache')})},
    [pscustomobject]@{Name='Slack';Pattern='(?i)^Slack';Executables=@((Join-Path $env:LOCALAPPDATA 'slack\slack.exe'),(Join-Path $env:APPDATA 'Slack\app-*\slack.exe'));Caches=@([pscustomobject]@{Type='Application Cache';Path=(Join-Path $env:APPDATA 'Slack\Cache')},[pscustomobject]@{Type='Code Cache';Path=(Join-Path $env:APPDATA 'Slack\Code Cache')},[pscustomobject]@{Type='GPU Cache';Path=(Join-Path $env:APPDATA 'Slack\GPUCache')})},
    [pscustomobject]@{Name='Zoom';Pattern='(?i)^Zoom';Executables=@((Join-Path $env:APPDATA 'Zoom\bin\Zoom.exe'),(Join-Path $env:ProgramFiles 'Zoom\bin\Zoom.exe'));Caches=@([pscustomobject]@{Type='WebView Cache';Path=(Join-Path $env:APPDATA 'Zoom\data\WebviewCache')})},
    [pscustomobject]@{Name='Visual Studio Code';Pattern='(?i)^Microsoft Visual Studio Code|^Visual Studio Code';Executables=@((Join-Path $env:LOCALAPPDATA 'Programs\Microsoft VS Code\Code.exe'),(Join-Path $env:ProgramFiles 'Microsoft VS Code\Code.exe'));Caches=@([pscustomobject]@{Type='Application Cache';Path=(Join-Path $env:APPDATA 'Code\Cache')},[pscustomobject]@{Type='Code Cache';Path=(Join-Path $env:APPDATA 'Code\Code Cache')},[pscustomobject]@{Type='GPU Cache';Path=(Join-Path $env:APPDATA 'Code\GPUCache')},[pscustomobject]@{Type='Dawn Cache';Path=(Join-Path $env:APPDATA 'Code\DawnCache')})},
    [pscustomobject]@{Name='Epic Games Launcher';Pattern='(?i)^Epic Games Launcher';Executables=@((Join-Path $env:LOCALAPPDATA 'EpicGamesLauncher\Portal\Binaries\Win64\EpicGamesLauncher.exe'),(Join-Path $env:ProgramFiles 'Epic Games\Launcher\Portal\Binaries\Win64\EpicGamesLauncher.exe'));Caches=@([pscustomobject]@{Type='Web Cache';Path=(Join-Path $env:LOCALAPPDATA 'EpicGamesLauncher\Saved\webcache')},[pscustomobject]@{Type='Web Cache 4430';Path=(Join-Path $env:LOCALAPPDATA 'EpicGamesLauncher\Saved\webcache_4430')},[pscustomobject]@{Type='Web Cache 4147';Path=(Join-Path $env:LOCALAPPDATA 'EpicGamesLauncher\Saved\webcache_4147')})}
)
# Steam can be installed outside the default location. Read its own install path,
# then add only the disposable web/http cache subfolders (never game libraries).
$steamRoots = New-Object 'System.Collections.Generic.List[string]'
try {
    $steamKey = Get-Item -LiteralPath 'HKCU:\Software\Valve\Steam' -ErrorAction Stop
    $steamRegistryPath = [string]$steamKey.GetValue('SteamPath')
    if ($steamRegistryPath) { $steamRoots.Add(($steamRegistryPath -replace '/', '\\')) }
} catch { }
$pf86Steam = [Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFilesX86)
foreach ($steamRoot in @((Join-Path $env:ProgramFiles 'Steam'),$(if ($pf86Steam) { Join-Path $pf86Steam 'Steam' }), (Join-Path $env:LOCALAPPDATA 'Steam'))) {
    if (-not [string]::IsNullOrWhiteSpace([string]$steamRoot)) {
        $fullSteamRoot = [System.IO.Path]::GetFullPath([string]$steamRoot).TrimEnd([System.IO.Path]::DirectorySeparatorChar)
        if (-not $steamRoots.Contains($fullSteamRoot)) { $steamRoots.Add($fullSteamRoot) }
    }
}
$steamExePaths = @($steamRoots | ForEach-Object { Join-Path $_ 'steam.exe' })
$steamCachePaths = New-Object 'System.Collections.Generic.List[object]'
foreach ($steamRoot in $steamRoots) {
    $steamCachePaths.Add([pscustomobject]@{Type='Steam Web Cache';Path=(Join-Path $steamRoot 'htmlcache')})
    $steamCachePaths.Add([pscustomobject]@{Type='Steam HTTP Cache';Path=(Join-Path $steamRoot 'appcache\httpcache')})
}
$appCacheDefinitions += [pscustomobject]@{Name='Steam';Pattern='(?i)^Steam';Executables=$steamExePaths;Caches=$steamCachePaths.ToArray()}
foreach ($app in $appCacheDefinitions) {
    $installed = Test-AMRKnownAppInstalled -DisplayPattern $app.Pattern -ExecutablePaths $app.Executables
    $cacheCount = 0
    if ($installed) {
        foreach ($cache in $app.Caches) {
            $before = $script:AMRApplicationCacheRoots.Count
            Add-AMRAppCacheCandidate -Application $app.Name -CacheType $cache.Type -Path $cache.Path
            if ($script:AMRApplicationCacheRoots.Count -gt $before) { $cacheCount++ }
        }
        $appStatus = 'Installed'
    } else {
        $appStatus = 'Not installed'
        Write-AMRLog ("Application cache discovery skipped; app not installed: {0}" -f $app.Name) INFO Cleanup
    }
    $script:AMRApplicationCacheInventory.Add([pscustomobject]@{Name=$app.Name;Status=$appStatus;CacheFolders=$cacheCount})
}
Add-AMRStartupMark 'cleanup.appInventory.done'

# Cross-volume application-cache discovery (bounded to known user-data roots).
# Search every fixed local volume for Windows user profiles, then register only
# recognized rebuildable cache folder names under each profile's AppData trees.
# We never recurse through the entire disk or enter reparse points / user documents.
# Startup discovery is intentionally limited to the Windows system volume and the
# signed-in user's profile. The old all-fixed-volumes / all-profiles pass caused slow
# launches, touched unrelated disks, and added little value to the normal cleanup view.
# Other volumes and other user profiles are never traversed by this startup discovery.
Add-AMRStartupMark 'L27277 before-CacheDiscoveryVolumes'
$script:AMRCacheDiscoveryVolumes = New-Object 'System.Collections.Generic.List[string]'
$systemVolumeRoot = ([string]$env:SystemDrive).TrimEnd('\')
if ([string]::IsNullOrWhiteSpace($systemVolumeRoot)) { $systemVolumeRoot = 'C:' }
$script:AMRCacheDiscoveryVolumes.Add($systemVolumeRoot)
$knownCacheDirectoryNames = @('Cache','Cache_Data','Code Cache','GPUCache','DawnCache','DawnGraphiteCache','DawnWebGPUCache','GraphiteDawnCache','GrShaderCache','ShaderCache','NV_Cache','DxCache','DxcCache','VkCache','httpcache','htmlcache','webcache','WebCache','WebviewCache','cache2')
$crossVolumeProfiles = New-Object 'System.Collections.Generic.List[string]'
if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE) -and [System.IO.Directory]::Exists($env:USERPROFILE)) {
    $crossVolumeProfiles.Add([System.IO.Path]::GetFullPath($env:USERPROFILE).TrimEnd('\'))
}
$crossVolumeCacheHits = 0
foreach ($profileRoot in $crossVolumeProfiles) {
    foreach ($appDataName in @('AppData\Local','AppData\Roaming','AppData\LocalLow')) {
        $appDataRoot = Join-Path $profileRoot $appDataName
        if (-not [System.IO.Directory]::Exists($appDataRoot)) { continue }
        # Exact high-value known application paths are checked first, including Discord
        # even when it is not currently running or its install was moved to another drive.
        $knownRelativeCaches = @(
            'discord\Cache','discord\Code Cache','discord\GPUCache',
            'Code\Cache','Code\Code Cache','Code\GPUCache','Code\DawnCache',
            'Slack\Cache','Slack\Code Cache','Slack\GPUCache',
            'Spotify\Browser\Cache','Spotify\Browser\Code Cache','Spotify\GPUCache',
            'Microsoft\Teams\Cache','Microsoft\Teams\Code Cache','Microsoft\Teams\GPUCache',
            'CapCut\User Data\Cache','CapCut\User Data\Code Cache','CapCut\User Data\GPUCache',
            'Google\Chrome\User Data\Default\Cache\Cache_Data','Microsoft\Edge\User Data\Default\Cache\Cache_Data',
            'BraveSoftware\Brave-Browser\User Data\Default\Cache\Cache_Data'
        )
        foreach ($relativeCache in $knownRelativeCaches) {
            $candidatePath = Join-Path $appDataRoot $relativeCache
            if ([System.IO.Directory]::Exists($candidatePath)) {
                Add-AMRAppCacheCandidate -Application ('Discovered profile cache: ' + [System.IO.Path]::GetFileName($profileRoot)) -CacheType $relativeCache -Path $candidatePath
                $crossVolumeCacheHits++
            }
        }
        # Firefox profile folders contain bookmarks, history, cookies and databases.
        # Register only the explicit rebuildable HTTP cache leaf inside each profile.
        $firefoxProfilesRoot = Join-Path $appDataRoot 'Mozilla\Firefox\Profiles'
        if ([System.IO.Directory]::Exists($firefoxProfilesRoot)) {
            try {
                foreach ($firefoxProfile in [System.IO.Directory]::GetDirectories($firefoxProfilesRoot)) {
                    $firefoxCacheEntries = Join-Path $firefoxProfile 'cache2\entries'
                    if ([System.IO.Directory]::Exists($firefoxCacheEntries)) {
                        Add-AMRAppCacheCandidate -Application ('Firefox cache: ' + [System.IO.Path]::GetFileName($firefoxProfile)) -CacheType 'HTTP cache entries' -Path $firefoxCacheEntries
                        $crossVolumeCacheHits++
                    }
                }
            } catch {
                Write-AMRLog (("Firefox cross-volume cache discovery warning | ProfileRoot={0} | {1}" -f $firefoxProfilesRoot,$_.Exception.Message)) WARNING Cleanup
            }
        }
        # One-level application-folder pass: only folders whose own name is a known
        # cache type are accepted; no unrestricted recursive walk is performed.
        try {
            foreach ($appFolder in [System.IO.Directory]::GetDirectories($appDataRoot)) {
                $appFolderName = [System.IO.Path]::GetFileName($appFolder)
                if ($appFolderName -in @('Packages','Microsoft','Google','Mozilla','BraveSoftware','discord','Discord','Code','Slack','Spotify','CapCut','Zoom','EpicGamesLauncher','Opera Software','NVIDIA','AMD','Intel')) {
                    foreach ($child in [System.IO.Directory]::GetDirectories($appFolder)) {
                        foreach ($cacheName in $knownCacheDirectoryNames) {
                            if ([string]::Equals([System.IO.Path]::GetFileName($child),$cacheName,[System.StringComparison]::OrdinalIgnoreCase)) {
                                Add-AMRAppCacheCandidate -Application ('Discovered cache: ' + $appFolderName) -CacheType $cacheName -Path $child
                                $crossVolumeCacheHits++
                            }
                        }
                    }
                }
            }
        } catch { Write-AMRLog ("Cross-volume cache discovery warning | Profile={0} | Root={1} | {2}" -f $profileRoot,$appDataRoot,$_.Exception.Message) WARNING Cleanup }
    }
}
Write-AMRLog ("Scoped cache discovery completed | SystemVolume={0} | ActiveProfiles={1} | CandidateHits={2}" -f $script:AMRCacheDiscoveryVolumes.Count,$crossVolumeProfiles.Count,$crossVolumeCacheHits) INFO Cleanup

# Phase 6.10.9 | Vendor-agnostic GPU shader cache discovery.
# Do not infer cache locations only from the currently installed adapter: old GPU
# drivers may have been removed or replaced. Search all discovered user profiles on
# every fixed local volume, but only register exact shader-cache directory names
# underneath recognizable graphics-vendor folders. Never register a driver/package root.
$gpuShaderCacheNames = @(
    'DXCache','DxCache','GLCache','NV_Cache','ShaderCache','GrShaderCache',
    'DxcCache','VkCache','VulkanCache','ComputeCache','DX9Cache','OglCache',
    'OpenGLCache','PipelineCache','D3DSCache'
)
$gpuVendorFolderPattern = '(?i)^(NVIDIA(?: Corporation)?|AMD|ATI|Advanced Micro Devices|Intel|Qualcomm|ARM|Imagination Technologies|Matrox|S3 Graphics|SiS|VIA|ASPEED|DisplayLink|Mesa|Khronos|Vulkan|PowerVR|Radeon|Broadcom|Apple|Microsoft|VMware|VirtualBox|QEMU|Parallels|VirtIO)(?:$|[\s._-])'
$gpuShaderCandidateHits = 0
foreach ($profileRoot in $crossVolumeProfiles) {
    foreach ($appDataName in @('AppData\Local','AppData\LocalLow','AppData\Roaming')) {
        $appDataRoot = Join-Path $profileRoot $appDataName
        if (-not [System.IO.Directory]::Exists($appDataRoot)) { continue }
        if ($appDataName -eq 'AppData\Local') {
            $directDxCache = Join-Path $appDataRoot 'D3DSCache'
            Add-AMRGPUCacheCandidate -Vendor 'Microsoft DirectX (vendor-independent)' -CacheType 'DirectX Shader Cache' -Path $directDxCache
        }
        try {
            foreach ($vendorRoot in [System.IO.Directory]::GetDirectories($appDataRoot)) {
                $vendorFolderName = [System.IO.Path]::GetFileName($vendorRoot)
                if ($vendorFolderName -notmatch $gpuVendorFolderPattern) { continue }
                foreach ($cacheFolder in [System.IO.Directory]::GetDirectories($vendorRoot)) {
                    $cacheName = [System.IO.Path]::GetFileName($cacheFolder)
                    if ($gpuShaderCacheNames -contains $cacheName) {
                        Add-AMRGPUCacheCandidate -Vendor ('Legacy/other GPU vendor: ' + $vendorFolderName) -CacheType $cacheName -Path $cacheFolder
                        $gpuShaderCandidateHits++
                        continue
                    }
                    # A few driver branches nest the cache under a version/container folder.
                    if ($cacheName -match '(?i)^(PerDriverVersion|DriverCache|CacheData|D3D|Vulkan|OpenGL)$') {
                        foreach ($nestedCache in [System.IO.Directory]::GetDirectories($cacheFolder)) {
                            $nestedName = [System.IO.Path]::GetFileName($nestedCache)
                            if ($gpuShaderCacheNames -contains $nestedName) {
                                Add-AMRGPUCacheCandidate -Vendor ('Legacy/other GPU vendor: ' + $vendorFolderName) -CacheType $nestedName -Path $nestedCache
                                $gpuShaderCandidateHits++
                            }
                        }
                    }
                }
            }
        } catch {
            Write-AMRLog ("Vendor-agnostic GPU cache discovery warning | Profile={0} | Root={1} | {2}" -f $profileRoot,$appDataRoot,$_.Exception.Message) WARNING Cleanup
        }
    }
}
# Machine-wide cache locations are also checked on each fixed local volume. These are
# exact cache leaves, not broad ProgramData or driver-installation directories.
foreach ($volumeRoot in $script:AMRCacheDiscoveryVolumes) {
    foreach ($machineCache in @(
        [pscustomobject]@{Vendor='NVIDIA (legacy machine cache)';Relative='ProgramData\NVIDIA Corporation\NV_Cache';Type='NV_Cache'},
        [pscustomobject]@{Vendor='AMD (legacy machine cache)';Relative='ProgramData\AMD\DxCache';Type='DxCache'},
        [pscustomobject]@{Vendor='Intel (machine shader cache)';Relative='ProgramData\Intel\ShaderCache';Type='ShaderCache'}
    )) {
        $machinePath = Join-Path $volumeRoot $machineCache.Relative
        Add-AMRGPUCacheCandidate -Vendor $machineCache.Vendor -CacheType $machineCache.Type -Path $machinePath
    }
}
Write-AMRLog ("Scoped GPU shader discovery completed | ActiveProfiles={0} | CandidateHits={1} | CacheTypes={2}" -f $crossVolumeProfiles.Count,$gpuShaderCandidateHits,($gpuShaderCacheNames -join ',')) INFO Cleanup

# Browser profiles also contribute only their explicit disposable cache directories.
# Mark a browser installed from its executable/registry metadata for the final summary.
$browserInventoryDefinitions = @(
    [pscustomobject]@{Name='Google Chrome';Pattern='(?i)^Google Chrome';Exe=@((Join-Path $env:ProgramFiles 'Google\Chrome\Application\chrome.exe'),(Join-Path $env:LOCALAPPDATA 'Google\Chrome\Application\chrome.exe'))},
    [pscustomobject]@{Name='Microsoft Edge';Pattern='(?i)^Microsoft Edge';Exe=@((Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe'))},
    [pscustomobject]@{Name='Mozilla Firefox';Pattern='(?i)^Mozilla Firefox';Exe=@((Join-Path $env:ProgramFiles 'Mozilla Firefox\firefox.exe'))},
    [pscustomobject]@{Name='Brave Browser';Pattern='(?i)^Brave';Exe=@((Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\Application\brave.exe'),(Join-Path $env:ProgramFiles 'BraveSoftware\Brave-Browser\Application\brave.exe'))},
    [pscustomobject]@{Name='Vivaldi';Pattern='(?i)^Vivaldi';Exe=@((Join-Path $env:LOCALAPPDATA 'Vivaldi\Application\vivaldi.exe'),(Join-Path $env:ProgramFiles 'Vivaldi\Application\vivaldi.exe'))},
    [pscustomobject]@{Name='Opera';Pattern='(?i)^Opera';Exe=@((Join-Path $env:LOCALAPPDATA 'Programs\Opera\opera.exe'),(Join-Path $env:ProgramFiles 'Opera\launcher.exe'))},
    [pscustomobject]@{Name='Yandex Browser';Pattern='(?i)^Yandex Browser';Exe=@((Join-Path $env:LOCALAPPDATA 'Yandex\YandexBrowser\Application\browser.exe'),(Join-Path $env:ProgramFiles 'Yandex\YandexBrowser\Application\browser.exe'))},
    [pscustomobject]@{Name='Chromium';Pattern='(?i)^Chromium';Exe=@((Join-Path $env:LOCALAPPDATA 'Chromium\Application\chrome.exe'),(Join-Path $env:ProgramFiles 'Chromium\Application\chrome.exe'))}
)
foreach ($browserDef in $browserInventoryDefinitions) {
    $installed = Test-AMRKnownAppInstalled -DisplayPattern $browserDef.Pattern -ExecutablePaths $browserDef.Exe
    $script:AMRApplicationCacheInventory.Add([pscustomobject]@{Name=$browserDef.Name;Status=$(if ($installed) {'Installed'} else {'Not installed'});CacheFolders=0})
}

# NVIDIA App OTA download artifacts only; restrict to files older than 30 days.
$nvidiaOtaPath = Join-Path $env:ProgramData 'NVIDIA Corporation\NVIDIA app\UpdateFramework\ota-artifacts'
if (Test-AMRCleanupDirectory -Path $nvidiaOtaPath) { $script:AMRDriverArtifactRoots.Add([System.IO.Path]::GetFullPath($nvidiaOtaPath).TrimEnd([System.IO.Path]::DirectorySeparatorChar)) }

# Expand only recognized temporary-directory roots. This deliberately avoids a
# drive-wide search for filenames containing 'temp', which could include installers,
# application data, source files, or user documents that are not disposable.
Add-AMRStartupMark 'L27433 before-UserTempDiscoveryRoots'
$script:AMRUserTempDiscoveryRoots = New-Object 'System.Collections.Generic.List[string]'
foreach ($profileRoot in @($crossVolumeProfiles)) {
    if ([string]::IsNullOrWhiteSpace([string]$profileRoot)) { continue }
    # Standard per-profile temporary folders, including roaming and Windows Error
    # Reporting temp/dump locations. These are explicit disposable locations only.
    foreach ($relativeTemp in @(
        'AppData\Local\Temp',
        'AppData\LocalLow\Temp',
        'AppData\Roaming\Temp',
        'AppData\Local\Microsoft\Windows\WER\Temp',
        'AppData\Local\CrashDumps'
    )) {
        $candidateTemp = Join-Path $profileRoot $relativeTemp
        if ([System.IO.Directory]::Exists($candidateTemp)) { $script:AMRUserTempDiscoveryRoots.Add($candidateTemp) }
    }
    $packagesRoot = Join-Path $profileRoot 'AppData\Local\Packages'
    if ([System.IO.Directory]::Exists($packagesRoot)) {
        try {
            foreach ($packageRoot in [System.IO.Directory]::GetDirectories($packagesRoot)) {
                # UWP package temporary state is distinct from LocalCache and user data.
                foreach ($packageTempRelative in @('AC\Temp','TempState')) {
                    $packageTemp = Join-Path $packageRoot $packageTempRelative
                    if ([System.IO.Directory]::Exists($packageTemp)) { $script:AMRUserTempDiscoveryRoots.Add($packageTemp) }
                }
            }
        } catch { Write-AMRLog ("User package-temp discovery warning | Profile={0} | {1}" -f $profileRoot,$_.Exception.Message) WARNING Cleanup }
    }
}
foreach ($currentTemp in @($env:TEMP,$env:TMP)) {
    if (-not [string]::IsNullOrWhiteSpace([string]$currentTemp)) { $script:AMRUserTempDiscoveryRoots.Add([string]$currentTemp) }
}

# Windows service accounts and the system profile keep their own temp locations.
# Include LocalLow temp and WER's explicit Temp folder, but not CBS/Setup logs,
# WinSxS servicing data, Prefetch, installer caches, or Windows Update downloads.
$script:AMRWindowsTempDiscoveryRoots = New-Object 'System.Collections.Generic.List[string]'
foreach ($systemProfileRoot in @(
    (Join-Path $env:windir 'ServiceProfiles\LocalService'),
    (Join-Path $env:windir 'ServiceProfiles\NetworkService'),
    (Join-Path $env:windir 'System32\config\systemprofile')
)) {
    foreach ($relativeSystemTemp in @(
        'AppData\Local\Temp',
        'AppData\LocalLow\Temp',
        'AppData\Local\Microsoft\Windows\WER\Temp'
    )) {
        $script:AMRWindowsTempDiscoveryRoots.Add((Join-Path $systemProfileRoot $relativeSystemTemp))
    }
}
foreach ($windowsTempRoot in @(
    (Join-Path $env:windir 'Temp'),
    (Join-Path $env:windir 'SystemTemp'),
    (Join-Path $env:windir 'CbsTemp'),
    (Join-Path $env:ProgramData 'Microsoft\Windows\WER\Temp')
)) {
    $script:AMRWindowsTempDiscoveryRoots.Add($windowsTempRoot)
}

# Build explicit, version-tolerant roots for the three Windows cache/report categories.
# Windows versions and servicing states place these data in more than one supported location.
# Only exact known folders are registered; no broad Windows/profile traversal is introduced.
$script:AMRWerReportRoots = New-Object 'System.Collections.Generic.List[string]'
foreach ($werBase in @(
    (Join-Path $env:ProgramData 'Microsoft\Windows\WER'),
    (Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\WER'),
    (Join-Path $env:windir 'ServiceProfiles\LocalService\AppData\Local\Microsoft\Windows\WER'),
    (Join-Path $env:windir 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\WER'),
    (Join-Path $env:windir 'System32\config\systemprofile\AppData\Local\Microsoft\Windows\WER')
)) {
    foreach ($werLeaf in @('ReportArchive','ReportQueue')) {
        $werCandidate = Join-Path $werBase $werLeaf
        if (-not $script:AMRWerReportRoots.Contains($werCandidate)) { $script:AMRWerReportRoots.Add($werCandidate) }
    }
}
foreach ($profileRoot in @($crossVolumeProfiles)) {
    if ([string]::IsNullOrWhiteSpace([string]$profileRoot)) { continue }
    foreach ($werLeaf in @('ReportArchive','ReportQueue')) {
        $werCandidate = Join-Path $profileRoot ('AppData\Local\Microsoft\Windows\WER\' + $werLeaf)
        if (-not $script:AMRWerReportRoots.Contains($werCandidate)) { $script:AMRWerReportRoots.Add($werCandidate) }
    }
}

$script:AMRDeliveryOptimizationRoots = @(
    (Join-Path $env:ProgramData 'Microsoft\Windows\DeliveryOptimization\Cache'),
    (Join-Path $env:windir 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'),
    (Join-Path $env:windir 'ServiceProfiles\LocalService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache')
)

# NVIDIA has used both the short NVIDIA and NVIDIA Corporation cache directory names.
# Add only known shader-cache locations, including the machine-level NV_Cache folder.
foreach ($nvidiaCachePath in @(
    (Join-Path $env:LOCALAPPDATA 'NVIDIA\DXCache'),
    (Join-Path $env:LOCALAPPDATA 'NVIDIA\GLCache'),
    (Join-Path $env:LOCALAPPDATA 'NVIDIA\NV_Cache'),
    (Join-Path $env:LOCALAPPDATA 'NVIDIA\ComputeCache'),
    (Join-Path $env:LOCALAPPDATA 'NVIDIA Corporation\NV_Cache'),
    (Join-Path $env:ProgramData 'NVIDIA Corporation\NV_Cache')
)) {
    Add-AMRGPUCacheCandidate -Vendor 'NVIDIA' -CacheType 'NVIDIA shader cache (additional known location)' -Path $nvidiaCachePath
}

$script:CleanupCategories = @(
    [pscustomobject]@{ Key='WER'; Check='CleanupWerCheck'; Info='CleanupWerInfo'; Label='Windows error reports'; Paths=@(Get-AMRExistingCleanupRoots -Roots $script:AMRWerReportRoots.ToArray()); MinAgeDays=7; Weight=8 },
    [pscustomobject]@{ Key='Shader'; Check='CleanupShaderCheck'; Info='CleanupShaderInfo'; Label='GPU shader cache'; Paths=@(Get-AMRExistingCleanupRoots -Roots @($script:AMRAppCacheRoots.ToArray())); MinAgeDays=7; Weight=10 },
    [pscustomobject]@{ Key='Delivery'; Check='CleanupDeliveryCheck'; Info='CleanupDeliveryInfo'; Label='Delivery Optimization cache'; Paths=@(Get-AMRExistingCleanupRoots -Roots $script:AMRDeliveryOptimizationRoots); MinAgeDays=7; Weight=12 },
    [pscustomobject]@{ Key='WindowsTemp'; Check='CleanupWindowsTempCheck'; Info='CleanupWindowsTempInfo'; Label='Windows temporary files'; Paths=@(Get-AMRExistingCleanupRoots -Roots $script:AMRWindowsTempDiscoveryRoots.ToArray()); MinAgeDays=0; Weight=14 },
    [pscustomobject]@{ Key='Update'; Check='CleanupUpdateCheck'; Info='CleanupUpdateInfo'; Label='Windows and graphics-driver update leftovers'; Paths=@(Get-AMRExistingCleanupRoots -Roots (@((Join-Path $env:windir 'SoftwareDistribution\Download')) + @($script:AMRDriverArtifactRoots.ToArray()))); MinAgeDays=30; Weight=16 },
    [pscustomobject]@{ Key='AppCache'; Check='CleanupAppCacheCheck'; Info='CleanupAppCacheInfo'; Label='Application caches'; Paths=@(Get-AMRExistingCleanupRoots -Roots @($script:AMRApplicationCacheRoots.ToArray())); MinAgeDays=7; Weight=18 },
    [pscustomobject]@{ Key='UserTemp'; Check='CleanupUserTempCheck'; Info='CleanupUserTempInfo'; Label='User temporary files'; Paths=@(Get-AMRExistingCleanupRoots -Roots $script:AMRUserTempDiscoveryRoots.ToArray()); MinAgeDays=0; Weight=22 }
)

function Get-AMRCleanupFiles {
    param(
        [string[]]$Roots,
        [int]$MinAgeDays = 0,
        [int]$MaxEntries = 100000,
        [int]$MaxSeconds = 120
    )

    # Bounded, cooperative scan: never follow reparse points, cap work per
    # category, and periodically pump the WPF message queue so the window can
    # repaint/respond while local filesystem enumeration is in progress.
    # A capped/timed-out inventory is marked incomplete and Clean Selected
    # refuses to act on it.
    $found = New-Object 'System.Collections.Generic.List[System.IO.FileInfo]'
    $errors = New-Object 'System.Collections.Generic.List[object]'
    $missingRoots = New-Object 'System.Collections.Generic.List[string]'
    $stack = New-Object 'System.Collections.Generic.Stack[string]'
    $reparseSkipped = 0
    $visited = 0
    $truncated = $false
    $clock = [System.Diagnostics.Stopwatch]::StartNew()
    $cutoff = if ($MinAgeDays -gt 0) { (Get-Date).AddDays(-$MinAgeDays) } else { [datetime]::MinValue }

    foreach ($root in @($Roots)) {
        if ([string]::IsNullOrWhiteSpace([string]$root)) { continue }
        try {
            if (-not (Test-Path -LiteralPath $root -PathType Container -ErrorAction Stop)) {
                $missingRoots.Add([string]$root)
                continue
            }
            $rootAttributes = [System.IO.File]::GetAttributes([string]$root)
            if (($rootAttributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
                $errors.Add([pscustomobject]@{ Path=[string]$root; Stage='RootSafety'; Message='Cleanup root is a reparse point and was not traversed.' })
                continue
            }
            $stack.Push([string]$root)
        } catch {
            $errors.Add([pscustomobject]@{ Path=[string]$root; Stage='RootCheck'; Message=$_.Exception.Message })
        }
    }

    while ($stack.Count -gt 0) {
        if ($visited -ge $MaxEntries -or $clock.Elapsed.TotalSeconds -ge $MaxSeconds) { $truncated = $true; break }
        $current = $stack.Pop()
        try {
            foreach ($item in [System.IO.Directory]::EnumerateFileSystemEntries($current)) {
                $visited++
                if (($visited % 128) -eq 0) {
                    try { [System.Windows.Forms.Application]::DoEvents() } catch { }
                    if ($clock.Elapsed.TotalSeconds -ge $MaxSeconds) { $truncated = $true; break }
                }
                if ($visited -gt $MaxEntries) { $truncated = $true; break }
                try {
                    $attributes = [System.IO.File]::GetAttributes($item)
                    if (($attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
                        $reparseSkipped++
                        continue
                    }
                    if (($attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
                        $stack.Push($item)
                    } else {
                        $file = New-Object -TypeName System.IO.FileInfo -ArgumentList $item
                        if ($MinAgeDays -le 0 -or $file.LastWriteTime -le $cutoff) { $found.Add($file) }
                    }
                } catch {
                    if ($errors.Count -lt 5000) { $errors.Add([pscustomobject]@{ Path=[string]$item; Stage='InspectEntry'; Message=$_.Exception.Message }) }
                }
            }
            if ($truncated) { break }
        } catch {
            if ($errors.Count -lt 5000) { $errors.Add([pscustomobject]@{ Path=[string]$current; Stage='EnumerateDirectory'; Message=$_.Exception.Message }) }
        }
    }
    $clock.Stop()

    return [pscustomobject]@{
        Files = $found.ToArray()
        Errors = $errors.ToArray()
        MissingRoots = $missingRoots.ToArray()
        ReparsePointsSkipped = $reparseSkipped
        Visited = $visited
        Truncated = $truncated
        ElapsedSeconds = [math]::Round($clock.Elapsed.TotalSeconds,1)
        Complete = ((-not $truncated) -and ($errors.Count -eq 0) -and ($missingRoots.Count -eq 0))
    }
}

